function logAudit(req, action, entity, entityId, details) {
	try {
		const user = req.session?.user || {};
		db.prepare("INSERT INTO audit_trail (timestamp, user_id, username, role, action, entity, entity_id, details) VALUES (?, ?, ?, ?, ?, ?, ?, ?)")
			.run(new Date().toISOString(), user.id || 0, user.username || 'system', user.role || 'system', action, entity, String(entityId || ''), details || '');
	} catch (err) { console.error("Audit log error:", err.message); }
}

// ============================================================================
// REFUSAL AUDITING — coalescing + bounded retention
// ============================================================================
// ⚠️ AUDIT ROWS ARE EVIDENCE. Nothing below may ever touch a row that records a
// WRITE. The split that makes that safe is already enforced by naming: every
// guard in this file audits its refusal under a DISTINCT action from its success
// (`update_sheet_row_blocked` vs `update_sheet_row`, `cancel_blocked` vs
// `cancel_load`), and `*_failed` is a THIRD thing again — a write that got past
// the guards and then threw, i.e. possibly a partial write, which is the most
// important row in the table and is never purged or coalesced.
//
// The problem this solves, reported by PR #248: refusals are trivially generated
// and every one INSERTs. A Driver holding one legitimate load can drive
// `driver_respond_blocked` at driverWriteLimiter's 60/min, and the load-binding
// refusals added by #248 and by this PR are reachable on demand by design — a
// wrong `rowIndex` is a 409 every time. The whole audit_trail is 1,314 rows over
// its first four months (measured on the production copy, ~11.5 rows/day, ALL of
// them evidence of a write or a read); a single scripted client would out-write
// that entire history in about two minutes and bury the signal the refusal row
// exists to preserve.
const REFUSAL_AUDIT_WINDOW_MS = 60 * 1000;
// ⚠️ THE COALESCE KEY DELIBERATELY EXCLUDES entity_id. Keying on the load id
// would look more precise and would be useless: the cheapest flood varies the id
// on every request, so every request would be a fresh key, coalescing would never
// fire, and the key map would grow without bound — turning a log-volume problem
// into a memory one. Keyed on (user, action, code) the map is bounded by a small
// finite product (users x guards x codes), and the signal actually worth keeping
// is "this actor is repeatedly being refused for this reason", which is exactly
// what that key names. The first refusal in each window is written in full and
// still carries its own entity_id, so the specific load is never lost.
const refusalAuditWindows = new Map();

// ⚠️ NEVER COALESCED, however cheap it looks to fold them in. A period refusal
// needs a locked month AND a material write, on routes that are Super Admin /
// Dispatcher only — it is not floodable, so coalescing buys nothing and costs the
// per-attempt load id and period list, which are the highest-value rows in this
// table. It is made worse by the shared login: `super_admin` is one account for
// several people, and the coalesce key is the ACCOUNT, so two operators refused
// on different loads in different months within the window would collapse into
// one row naming one of them. "Someone repeatedly tried to restate a settled
// month" is exactly the signal the refusal audit exists to keep.
//
// ⚠️ EVERY MEMBER MUST BE NAMED `PERIOD_…`, and that is a hard coupling, not a
// stylistic one. purgeOldAuditRefusals() exempts a row from deletion by matching
// `[PERIOD_` in its DETAILS, while this set exempts it from coalescing by CODE —
// two mechanisms keyed on two different things, documented as a pair and, until
// assertUncoalescedRefusalContract() below, enforced by nothing. A member named
// otherwise would be written in full and then silently purged at 90 days, which
// is the worse half of both behaviours. Asserted at boot.
const UNCOALESCED_REFUSAL_CODES = new Set([
	"PERIOD_FINALIZED", "PERIOD_LOCK_UNREADABLE", "PERIOD_UNRESOLVED",
	// The settlement guard on POST /api/investor/payouts/:id/status: the month is
	// over but still inside its grace window, so a forward move to processing/paid
	// is refused. Listed here for the same reason as its neighbours and for one
	// sharper one — that route is "Mark Paid", the only verb in the app asserting
	// money actually moved. Its refusals need a locked-or-pending month AND a
	// Super Admin session, so they cannot flood; and `super_admin` is a SHARED
	// login, so with this code absent a second operator refused on a different
	// payout within the same minute would have written nothing at all.
	"PERIOD_NOT_FINALIZED",
]);

// The contract above, checked rather than trusted. Never throws: an audit-config
// drift must not take dispatch down, and the log line is addressed to whoever
// adds the next code.
function assertUncoalescedRefusalContract() {
	const stray = [...UNCOALESCED_REFUSAL_CODES].filter((c) => !String(c).startsWith("PERIOD_"));
	if (stray.length) {
		console.error(
			`[audit] UNCOALESCED_REFUSAL_CODES contains ${stray.join(", ")}, which purgeOldAuditRefusals() ` +
			`will NOT exempt — its filter matches '[PERIOD_' in details. Rename the code, or widen the purge filter to match.`
		);
	}
}
assertUncoalescedRefusalContract();

function logAuditRefusal(req, action, entity, entityId, details, code) {
	try {
		const user = req.session?.user || {};
		if (UNCOALESCED_REFUSAL_CODES.has(code)) return logAudit(req, action, entity, entityId, details);
		const key = `${user.id || 0}|${action}|${code || ""}`;
		const now = Date.now();
		const prev = refusalAuditWindows.get(key);
		if (prev && now - prev.windowStart < REFUSAL_AUDIT_WINDOW_MS) {
			prev.suppressed++;
			return;
		}
		// Cheap bound on the map itself. Keys are already finite, but a long-lived
		// process should not accumulate one entry per user who was ever refused.
		if (refusalAuditWindows.size > 500) {
			for (const [k, v] of refusalAuditWindows) {
				if (now - v.windowStart >= REFUSAL_AUDIT_WINDOW_MS) refusalAuditWindows.delete(k);
			}
		}
		const suppressed = prev ? prev.suppressed : 0;
		refusalAuditWindows.set(key, { windowStart: now, suppressed: 0 });
		// The count is carried on the NEXT row rather than dropped, so a burst is
		// summarised rather than silently discarded.
		// ⚠️ KNOWN LIMIT, stated rather than glossed: the tally of a burst that is
		// never followed by another refusal on the same key is never written — it
		// sits in the map until the process restarts. What is NEVER lost is the
		// existence of the burst: the FIRST refusal in every window is written in
		// full, with its own entity_id and timestamp. So "this actor was refused
		// for this reason, starting at T" is always on the record, and only the
		// magnitude of a trailing burst can go unreported. Flushing that would mean
		// a timer per key writing rows after the fact, which is more machinery than
		// the signal is worth — the rate limiter, not this log, is the control that
		// stops the flood.
		logAudit(req, action, entity, entityId, suppressed
			? `${details || ""} [+${suppressed} more identical refusal(s) suppressed in the previous ${Math.round(REFUSAL_AUDIT_WINDOW_MS / 1000)}s]`
			: details);
	} catch (err) { console.error("Audit refusal log error:", err.message); }
}

// ⚠️ AN EXPLICIT ALLOWLIST, NEVER `action LIKE '%_blocked'`. A pattern would
// silently adopt any future action someone names with that suffix, including one
// that records a write; and it would just as silently MISS a refusal named
// otherwise. Each entry below was checked against every call site: all are
// written only on a path that returns before any sheet or database write.
// Deliberately ABSENT, and each for its own reason:
//   • `setup_refused` — the only refusal on an UNAUTHENTICATED route (the admin
//     minter). It is itself the security evidence of a distributed guess, it is
//     capped at 5/15min by setupLimiter so it cannot flood, and a campaign slower
//     than the retention window is exactly the one worth catching. Kept forever.
//   • `db_export_blocked` — a refused cross-site attempt on POST /api/db/download,
//     the route that hands over the ENTIRE database. Same call as setup_refused
//     and for the same two reasons. It IS the security evidence: `super_admin` is
//     a shared login, so audit_trail is the only who/when/from-where record that
//     exists, and this is the highest-value single row it can hold. And it cannot
//     flood — requireRole("Super Admin") is mounted BEFORE the guard, so only an
//     already-authenticated admin session can produce one at all, and
//     logAuditRefusal coalesces it to one row per minute per (user, action, code).
//     A campaign slower than 90 days is, again, exactly the one worth catching.
//   • every `*_failed` action — those record a write that already started.
//   • every success action — the entire rest of the table.
//   • ⚠️ EVERY PERIOD-GUARD REFUSAL ACTION, and this was decided per action, not
//     as a batch. `update_driver_pay_blocked`, `delete_driver_blocked`,
//     `update_user_blocked`, `delete_user_blocked`, `create_truck_blocked`,
//     `update_truck_blocked`, `delete_truck_blocked`, `driver_rename_blocked`,
//     `delete_sheet_rows_blocked`, `delete_load_blocked`,
//     `add_driver_day_blocked`, `exclude_driver_day_blocked`,
//     `restore_driver_day_blocked`, `restore_added_driver_day_blocked`,
//     `delete_sheet_row_blocked`, `routemate_link_blocked`,
//     `routemate_unlink_blocked`, `maintenance_fund_blocked`,
//     `create_compliance_fee_blocked`, `pay_compliance_fee_blocked`,
//     `adjust_invoice_blocked`, `pay_invoice_blocked` and the
//     catch-all `period_refusal_blocked` are all absent, deliberately, for the
//     three reasons the four settlement refusals fixed before them were:
//       (i) THEY CANNOT FLOOD. Every one needs a locked month (or an unreadable
//           lock table) AND a material write, on a Super Admin — or at widest
//           Dispatcher — route. That is the opposite of `status_update_blocked`,
//           which also carries cheap ROW_LOAD_MISMATCH noise a Driver can
//           produce 60x a minute, and which is why that one IS on this list.
//      (ii) THE RETENTION WINDOW IS SHORTER THAN THE QUESTION. Settlement
//           disputes surface on a quarterly or annual cadence — reliably after
//           90 days — so purging by action would delete the evidence exactly
//           when it is first wanted, while the corresponding successful writes
//           are kept forever.
//     (iii) ADDING THEM WOULD PURGE NOTHING TODAY ANYWAY (every row they write
//           carries a `[PERIOD_` code, which the detail filter below exempts)
//           while reading as a decision that these rows are disposable. They are
//           the opposite: on a SHARED `super_admin` login they are the only
//           record of who kept trying to restate a settled month.
//     Revisit only if a cheap, on-demand refusal is ever audited under one of
//     these same actions. `scripts/test-refusal-audit-coverage.js` pins their
//     absence, the mirror of the required-present pin in
//     `scripts/test-driver-status-row-binding.js`.
const PURGEABLE_REFUSAL_ACTIONS = [
	"dispatch_blocked",
	"reassign_blocked",
	"cancel_blocked",
	"driver_respond_blocked",
	"status_update_blocked",
	"status_override_blocked",
	"create_sheet_row_blocked",
	"update_sheet_row_blocked",
];
const REFUSAL_AUDIT_RETENTION_DAYS = 90;

// ⚠️ THE PURGE EXEMPTION IS A LITERAL LIVING IN CALLER-INFLUENCED TEXT, SO IT HAS
// TO BE A RESERVED SEQUENCE. purgeOldAuditRefusals() below spares any row whose
// `details` contain `[PERIOD_`, and several PURGEABLE actions build their details
// by interpolating values that arrived on the request:
//   • `create_sheet_row_blocked` / `update_sheet_row_blocked` — buildSheetUpdateAudit()
//     emits `changed[].from` / `.to`, which are RAW SHEET CELL VALUES off the body.
//     They are capped by capAuditField() and were never scanned, and JSON.stringify
//     escapes quotes and newlines but not `[` or `_`.
//   • `dispatch_blocked` / `reassign_blocked` / `driver_respond_blocked` — the two
//     refusal helpers interpolate `what`, built from `driver` / `newDriver`, which
//     fall back to the caller's raw string.
// So one `PUT /api/data/:rowIndex` with a cell reading `[PERIOD_` — or one
// dispatch with that driver name — writes an audit row that can never be deleted.
// Neither /api/data route is rate-limited, a ROW_LOAD_MISMATCH is a 409 on demand,
// and none of these codes coalesce, so it is one permanent multi-KB row per
// request against the one table in this app with no other retention job.
//
// ⚠️ THE SCRUB BELONGS ON THE CALLER TEXT AND NEVER ON THE FINISHED DETAIL. Every
// writer appends the REAL marker as a literal `[` followed by a module-constant
// code — sheetAuditWithCode(), periodRefusalDetail(), and the two refusal helpers
// all put that bracket in the template, OUTSIDE the capping call — so scrubbing
// here provably cannot reach it. Scrubbing the assembled string instead would
// delete the exemption from exactly the rows it exists to keep, which is the same
// defect one layer down.
//
// The bracket becomes a paren rather than being deleted: an audited sheet cell is
// evidence and must stay legible, while `(PERIOD_` cannot match the filter.
// ⚠️ CASE-FOLDED, and that is not belt-and-braces — SQLite's LIKE is
// case-INSENSITIVE for ASCII by default, so `[period_` is spared just as readily
// as `[PERIOD_` (measured). A case-sensitive scrub would leave the hole open under
// one keystroke's difference.
function scrubPurgeMarker(s) {
	return String(s).replace(/\[(?=period)/gi, "(");
}

// Purge refusal rows older than the retention window. Mirrors
// purgeOldDriverLocations() below: run once at boot to seed, then weekly.
// ⚠️ The cutoff is computed in JS as an ISO string, NOT with
// datetime('now','-90 days'). logAudit() is the ONLY writer of this table and
// always stores `new Date().toISOString()` (verified: 0 of 1,314 production rows
// deviate), so an ISO-to-ISO comparison is exact — whereas SQLite's datetime()
// renders `YYYY-MM-DD HH:MM:SS`, and comparing that to `YYYY-MM-DDTHH:MM:SS.sssZ`
// is a string comparison in which the 'T' sorts above the space. That happens to
// fail SAFE here (it keeps a row a fraction longer) but it is an accident, and an
// accident is not something to leave in a DELETE aimed at an audit table.
function purgeOldAuditRefusals() {
	try {
		const cutoff = new Date(Date.now() - REFUSAL_AUDIT_RETENTION_DAYS * 24 * 60 * 60 * 1000).toISOString();
		const placeholders = PURGEABLE_REFUSAL_ACTIONS.map(() => "?").join(",");
		// ⚠️ THE ACTION IS NOT FINE-GRAINED ENOUGH ON ITS OWN. `status_update_blocked`
		// covers both ROW_LOAD_MISMATCH (cheap, floodable noise — the reason this
		// purge exists) and PERIOD_FINALIZED (someone repeatedly trying to restate a
		// settled month). Those are opposite in value, and settlement disputes surface
		// on a quarterly or annual cadence, i.e. reliably AFTER 90 days — so purging
		// them by action would delete the evidence exactly when it is first wanted,
		// while the corresponding successful writes are kept forever. Every refusal
		// detail is written as `… [CODE]…` by the two helpers, so excluding `[PERIOD_`
		// keeps the whole period family (FINALIZED / LOCK_UNREADABLE / UNRESOLVED)
		// indefinitely. Pairs with UNCOALESCED_REFUSAL_CODES above: the same rows that
		// are never collapsed are also never purged.
		const result = db
			.prepare(`DELETE FROM audit_trail WHERE action IN (${placeholders}) AND timestamp < ? AND details NOT LIKE '%[PERIOD\\_%' ESCAPE '\\'`)
			.run(...PURGEABLE_REFUSAL_ACTIONS, cutoff);
		if (result.changes > 0) console.log(`[cleanup] Purged ${result.changes} audit_trail refusal rows older than ${REFUSAL_AUDIT_RETENTION_DAYS} days`);
	} catch (err) {
		console.error("[cleanup] audit_trail refusal purge failed:", err.message);
	}
}
purgeOldAuditRefusals();
setInterval(purgeOldAuditRefusals, 7 * 24 * 60 * 60 * 1000); // weekly

// Load status phase history — append-only transition log. Powers the per-phase
// started/ended/duration timeline (admin load modals + driver app). Forward-only:
// rows accrue from the moment this ships; pre-existing loads have none. Mirrors
// the audit_trail idiom above.
db.exec(`
	CREATE TABLE IF NOT EXISTS load_status_history (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		load_id TEXT NOT NULL,
		old_status TEXT DEFAULT '',
		new_status TEXT NOT NULL,
		source TEXT NOT NULL DEFAULT 'manual',
		actor TEXT DEFAULT '',
		changed_at DATETIME DEFAULT CURRENT_TIMESTAMP
	)
`);
try { db.exec(`CREATE INDEX IF NOT EXISTS idx_lsh_load ON load_status_history(load_id, changed_at)`); } catch {}
// Why a transition happened. Only cancellations require one today (see
// POST /api/dispatch/cancel); every other source leaves it ''. Added after a
// live load was cancelled by mistake and the log could say who and when but
// never why. Additive, so existing rows keep their blank reason.
try { db.exec("ALTER TABLE load_status_history ADD COLUMN reason TEXT DEFAULT ''"); } catch { /* column already exists */ }

const insertStatusHistory = db.prepare(
	`INSERT INTO load_status_history (load_id, old_status, new_status, source, actor, reason) VALUES (?, ?, ?, ?, ?, ?)`
);

// Record one load status transition for the phase timeline. Best-effort: never
// throws into the caller (a failed history write must not break a status update),
// and skips no-op transitions (old === new, case-insensitive) so a re-saved
// identical status or a geofence re-fire doesn't create duplicate rows. load_id
// is normalized (lowercase, leading '#' stripped) to match the lookup convention.
function recordStatusChange({ loadId, oldStatus, newStatus, source, actor, reason }) {
	try {
		const lid = String(loadId || "").trim().toLowerCase().replace(/^#/, "");
		const ns = String(newStatus || "").trim();
		if (!lid || !ns) return;
		const os = String(oldStatus || "").trim();
		if (os && os.toLowerCase() === ns.toLowerCase()) return; // no-op transition
		insertStatusHistory.run(lid, os, ns, source || "manual", String(actor || "").trim(), String(reason || "").trim().slice(0, 500));
	} catch (err) {
		console.error("recordStatusChange error:", err.message);
	}
}

// Investor payout amount history — append-only log of everything that moved a
// payout figure. Forward-only: rows accrue from the moment this ships, and prior
// movements are NOT reconstructible because `amount` was overwritten in place.
//
// WHY: reconcileInvestorPayouts() refreshes `amount` on every relevant page load.
// Deliberate actions (adjust, status change, reopen) leave a trace in audit_trail
// and in columns on the row, but a SILENT recompute — caused by a load or an
// expense changing underneath an open month — left none at all. So "why is this
// month different from last week?" had no answer on screen. That is the question
// this table exists to answer.
//
// `breakdown` stores the SAME component object the waterfall and the payout
// statement already use ({ revenue, driverPay, fixedCosts, tripExpenses,
// maintFundCost, complianceCost, netProfit, splitPct, monthShare }), so the UI
// derives "what moved" by diffing consecutive snapshots rather than recomputing —
// and it reconciles to the existing drill-down by construction. finalized_breakdown
// already serialises that same object, so this is a proven shape, not a new one.
db.exec(`
	CREATE TABLE IF NOT EXISTS investor_payout_history (
		id INTEGER PRIMARY KEY AUTOINCREMENT,
		payout_id INTEGER,
		owner_id INTEGER NOT NULL,
		period TEXT NOT NULL,
		kind TEXT NOT NULL DEFAULT 'recompute',
		old_amount REAL,
		new_amount REAL,
		delta REAL,
		detail TEXT DEFAULT '',
		breakdown TEXT DEFAULT '',
		actor TEXT DEFAULT '',
		changed_at DATETIME DEFAULT CURRENT_TIMESTAMP
	)
`);
try { db.exec(`CREATE INDEX IF NOT EXISTS idx_iph_owner_period ON investor_payout_history(owner_id, period, changed_at)`); } catch {}

const insertPayoutHistory = db.prepare(
	`INSERT INTO investor_payout_history
	   (payout_id, owner_id, period, kind, old_amount, new_amount, delta, detail, breakdown, actor)
	 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
);

// Record one payout movement. Best-effort in the same sense as
// recordStatusChange: it must NEVER throw into the caller, because a failed
// history write must not break a settlement, a reconcile, or a period close.
//
// It also skips no-ops for the `recompute` kind. The reconcile's own guard
// already suppresses identical amounts before it writes, so this is belt-and-
// braces — but the reconcile runs on every GET and loops per investor on the
// admin console, so anything that slipped past would flood the table and bury
// the handful of rows that matter.
function recordPayoutChange({ payoutId, ownerId, period, kind, oldAmount, newAmount, detail, breakdown, actor }) {
	try {
		const oid = Number(ownerId);
		const per = String(period || "").trim();
		if (!oid || !per) return;
		const k = String(kind || "recompute").trim();
		const oldA = oldAmount == null ? null : Number(oldAmount);
		const newA = newAmount == null ? null : Number(newAmount);
		// A recompute that moved nothing is not a movement.
		if (k === "recompute" && oldA != null && newA != null && Math.abs(newA - oldA) < 0.005) return;
		const delta = oldA != null && newA != null ? Number((newA - oldA).toFixed(2)) : null;
		insertPayoutHistory.run(
			payoutId == null ? null : Number(payoutId),
			oid, per, k, oldA, newA, delta,
			String(detail || "").trim(),
			breakdown ? (typeof breakdown === "string" ? breakdown : JSON.stringify(breakdown)) : "",
			String(actor || "").trim()
		);
	} catch (err) {
		console.error("recordPayoutChange error:", err.message);
	}
}

// Escape applicant-controlled text before interpolating into HTML email bodies.
// Submission and acceptance emails embed full_name, address, phone, etc.; without
// this, a name like `<img src=x onerror=...>` would render in the admin's mail
// client. Used by the /api/public/apply and /api/applications/:id/status flows.
function escapeHtml(s) {
	return String(s ?? "")
		.replace(/&/g, "&amp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;")
		.replace(/"/g, "&quot;")
		.replace(/'/g, "&#39;");
}

