// READ — Get rows from a sheet tab (supports pagination via ?page=&limit=)
app.get("/api/data", requireRole("Super Admin", "Dispatcher"), async (req, res) => {
	try {
		const sheetName = getSheetName(req);
		const page = Math.max(1, parseInt(req.query.page) || 1);
		const limit = Math.max(1, Math.min(200, parseInt(req.query.limit) || 50));

		const sheets = await getSheets();
		const response = await sheets.spreadsheets.values.get({
			spreadsheetId: SPREADSHEET_ID,
			range: `${sheetName}`,
		});

		const rows = response.data.values || [];
		if (rows.length === 0) {
			return res.json({ headers: [], data: [], sheet: sheetName, total: 0, page, limit, totalPages: 0 });
		}

		// First row = headers, rest = data
		const headers = rows[0];
		let allData = rows.slice(1).map((row, index) => {
			const obj = { _rowIndex: index + 2 }; // Sheet rows are 1-indexed, +1 for header
			headers.forEach((header, i) => {
				obj[header] = row[i] || "";
			});
			return obj;
		});

		// Deduplicate loads by Load ID (keep most advanced status)
		let duplicates = [];
		if (sheetName === "Job Tracking") {
			const result = deduplicateLoads(allData, headers, true);
			allData = result.data;
			duplicates = result.duplicates;
		}

		// Search filter
		const search = (req.query.search || "").trim().toLowerCase();
		if (search) {
			allData = allData.filter((row) =>
				headers.some((h) => (row[h] || "").toLowerCase().includes(search)),
			);
		}

		const total = allData.length;
		const totalPages = Math.ceil(total / limit);
		const start = (page - 1) * limit;
		let data = allData.slice(start, start + limit);

		// Sanitize broker contact data for non-Admin roles
		if (req.session.user.role !== "Super Admin") {
			data = sanitizeBrokerColumns(headers, data);
		}

		res.json({ headers, data, sheet: sheetName, total, page, limit, totalPages, duplicates });
	} catch (error) {
		console.error("Error reading sheet:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// CREATE — Append a new row
app.post("/api/data", requireRole("Super Admin", "Dispatcher"), async (req, res) => {
	try {
		const { values, coordinates } = req.body; // values = array of cell values, coordinates = optional {loadId, originLat, originLng, destLat, destLng, pickupAddress, dropoffAddress}

		const sheets = await getSheets();

		// ⚠️ Canonicalize ?sheet= for the SAME reason PUT does. A1 range notation
		// matches a tab title case-insensitively, so `?sheet=job tracking` appended
		// to Job Tracking while `sheetName === "Job Tracking"` was false — silently
		// skipping BOTH the Owner ID validation and the duplicate-Load-ID check
		// below. Falls back to the raw name when the tab list cannot be read, which
		// is the pre-existing behaviour.
		const requestedSheet = getSheetName(req);
		const appendTarget = await resolveSheetTargetForWrite(sheets, requestedSheet);
		const sheetName = appendTarget.resolved ? appendTarget.title : requestedSheet;

		// Validate Owner ID + check for duplicate Load ID in Job Tracking
		let warning = "";
		if (appendTarget.guarded) {
			let hdrs = [];
			try {
				const headerResp = await sheets.spreadsheets.values.get({
					spreadsheetId: SPREADSHEET_ID,
					range: "Job Tracking!1:1",
				});
				hdrs = (headerResp.data.values || [[]])[0];
			} catch { /* header fetch failed — skip both checks */ }
			// "Job Tracking" literal, not `sheetName`: on the metaUnreadable fallback
			// sheetName is the raw request string, which would make this a no-op in
			// the one window where the tab identity is least certain.
			const ownerErr = validateOwnerIdCell("Job Tracking", hdrs, values);
			if (ownerErr) return res.status(400).json({ error: ownerErr.error });
			try {
				const lidIdx = hdrs.findIndex((h) => /load.?id|job.?id/i.test(h));
				if (lidIdx >= 0 && values[lidIdx]) {
					const newLid = values[lidIdx].trim().toLowerCase().replace(/^#/, "");
					if (newLid) {
						const allResp = await sheets.spreadsheets.values.get({
							spreadsheetId: SPREADSHEET_ID,
							range: "Job Tracking",
						});
						const allRows = allResp.data.values || [];
						for (let i = 1; i < allRows.length; i++) {
							const existing = (allRows[i][lidIdx] || "").trim().toLowerCase().replace(/^#/, "");
							if (existing === newLid) {
								warning = `Load ID '${values[lidIdx]}' already exists (row ${i + 1}). A duplicate entry will be created.`;
								break;
							}
						}
					}
				}
			} catch { /* non-critical: dup-check is best-effort */ }
		}

		// ⚠️ AN APPEND INTO A CLOSED MONTH IS THE SAME ACCOUNTING EVENT AS AN EDIT,
		// and leaving it open makes the cheapest way to restate a finalized month
		// "append", not "edit". A row with a completed status, an amount and an
		// Assigned Date inside a locked month books fresh revenue into that month —
		// /api/investor, /api/financials and the payout statement's composition are
		// all live recomputes, so they all move, while the frozen
		// investor_payouts.amount does not. The statement then disagrees with the
		// figure it settles.
		//
		// Reuses the update guard with an EMPTY before, which is exactly right: a
		// new row has no prior figures, so only the "moved INTO a closed month" leg
		// can fire, and sheetRowIsEmpty([]) makes the blank-before carve-out apply.
		// Note this constrains the API only — n8n writes to the sheet directly and
		// is unaffected either way.
		let appendHeaders = null;
		if (appendTarget.guarded) {
			const hdrs = await (async () => {
				try {
					const hr = await sheets.spreadsheets.values.get({ spreadsheetId: SPREADSHEET_ID, range: `${a1SheetPrefix(sheetName)}!1:1` });
					return ((hr.data.values || [[]])[0]) || [];
				} catch { return null; }
			})();
			if (!hdrs || !hdrs.length) {
				return res.status(409).json({
					error: "The sheet's header row could not be read, so the new row cannot be shown to belong to an open month. Try again.",
					code: "ROW_READ_FAILED",
				});
			}
			appendHeaders = hdrs;
			const appendChanges = changedGuardedCells(hdrs, [], values);
			const appendBlocker = sheetRowUpdateBlocker(true, hdrs, [], values, appendChanges);
			if (appendBlocker) {
				// logAuditRefusal, not logAudit, and the code is passed so the coalescer
				// can see it. Byte-identical today for the PERIOD_* causes (all three are
				// in UNCOALESCED_REFUSAL_CODES, so they are still written one row per
				// attempt with their own row address) — the change is that a future
				// non-period refusal on this action inherits the 60s window instead of
				// being able to flood the table. sheetAuditWithCode() puts the bracketed
				// code outside the JSON so purgeOldAuditRefusals() can actually see it;
				// without it this action's period refusals were deleted at 90 days.
				logAuditRefusal(req, "create_sheet_row_blocked", "sheet_row", `${sheetName}!new`, sheetAuditWithCode(buildSheetUpdateAudit({
					outcome: "blocked", sheet: sheetName, rowIndex: null,
					changed: appendChanges.map((c) => ({ column: c.column, index: c.index, from: "", to: c.to, why: c.why })),
					guardedChanged: appendChanges, code: appendBlocker.code, periods: appendBlocker.periods,
				}), appendBlocker.code), appendBlocker.code);
				return res.status(409).json({
					error: appendBlocker.error.replace("This row's figures are counted in", "This new row's figures would be counted in"),
					code: appendBlocker.code,
					periods: appendBlocker.periods,
					...(appendBlocker.unreadable ? { unreadable: appendBlocker.unreadable } : {}),
				});
			}
		}

		const response = await sheets.spreadsheets.values.append({
			spreadsheetId: SPREADSHEET_ID,
			range: `${sheetName}`,
			valueInputOption: "USER_ENTERED",
			requestBody: {
				values: [values],
			},
		});

		// The append had no audit line either — and unlike the update there is no
		// prior value to record, so the row's own contents ARE the record.
		logAudit(req, "create_sheet_row", "sheet_row", `${sheetName}!${(response.data.updates && response.data.updates.updatedRange) || "new"}`, buildSheetUpdateAudit({
			outcome: "created", sheet: sheetName, rowIndex: null,
			changed: values.map((v, i) => ({
				column: (appendHeaders && String(appendHeaders[i] || "").trim()) || "(unnamed)",
				index: i, from: "", to: v == null ? "" : String(v),
				why: appendHeaders ? (guardedColumnReason(appendHeaders[i]) || "") : "",
			})),
			guardedChanged: appendHeaders ? changedGuardedCells(appendHeaders, [], values) : [],
		}));

		// Save coordinates to load_coordinates if provided
		if (sheetName === "Job Tracking" && coordinates && coordinates.loadId) {
			try {
				const lid = coordinates.loadId.trim().toLowerCase().replace(/^#/, "");
				db.prepare(`INSERT OR REPLACE INTO load_coordinates (load_id, origin_lat, origin_lng, dest_lat, dest_lng, pickup_address, dropoff_address) VALUES (?, ?, ?, ?, ?, ?, ?)`)
					.run(lid, coordinates.originLat || null, coordinates.originLng || null, coordinates.destLat || null, coordinates.destLng || null, coordinates.pickupAddress || "", coordinates.dropoffAddress || "");
			} catch { /* non-critical */ }
		}

		res.json({
			success: true,
			updatedRange: response.data.updates.updatedRange,
			...(warning && { warning }),
		});
	} catch (error) {
		console.error("Error appending row:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// UPDATE — Update a specific row
//
// Period-guarded and audited: see sheetRowUpdateBlocker() above for WHICH cells
// are guarded and why the list is read out of the money math rather than chosen.
app.put("/api/data/:rowIndex", requireRole("Super Admin", "Dispatcher"), async (req, res) => {
	try {
		const requestedSheet = getSheetName(req);
		// Number(), not parseInt(): parseInt("5abc") is 5 and parseInt("2.9") is 2,
		// so a malformed index silently rewrote a real row. Same fix #209 applied to
		// the delete.
		const rowIndex = Number(req.params.rowIndex);
		const { values } = req.body || {};

		if (!Array.isArray(values)) {
			return res.status(400).json({ error: "values must be an array of cell values", code: "VALUES_REQUIRED" });
		}
		// The body limit is 50mb (raised for base64 photos), and `values` was
		// previously bounded only by that. The diff and the audit builder both walk
		// max(headers, before, after) and buildSheetUpdateAudit stringifies the
		// payload before it can test the size cap — so one authenticated request
		// carrying a multi-million-element array materialises it several times over
		// on a single-process server. Sheets itself tops out at 18,278 columns
		// (ZZZ), so nothing real is refused here.
		if (values.length > SHEET_ROW_MAX_CELLS) {
			return res.status(400).json({
				error: `A row cannot have more than ${SHEET_ROW_MAX_CELLS} cells (received ${values.length}).`,
				code: "ROW_TOO_WIDE",
			});
		}
		// ⚠️ ROW 1 IS THE HEADER ROW, and rewriting it is strictly worse here than
		// deleting it. Every column in this app is resolved by matching header TEXT
		// (findCol), so renaming "  Payment  " re-points the revenue column for
		// /api/investor, /api/financials, /api/dashboard and the invoice batch at
		// once — the entire P&L changes with no data row touched, and no period
		// guard fires because no row was edited.
		if (!Number.isInteger(rowIndex) || rowIndex < 2) {
			return res.status(400).json({
				error: "rowIndex must be a whole number of 2 or more — row 1 is the header row, and rewriting it re-points every column this app resolves by header text.",
				code: "INVALID_ROW_INDEX",
			});
		}

		const sheets = await getSheets();

		// Resolve ?sheet= to a real tab, then use the canonical title for the guard,
		// the reads AND the write, so they can never disagree about which tab this
		// is. See the ⚠️ on resolveSheetTargetForWrite.
		const target = await resolveSheetTargetForWrite(sheets, requestedSheet);
		if (!target.resolved && !target.metaUnreadable) {
			return res.status(400).json({
				error: `Unknown sheet tab '${requestedSheet}'.`,
				code: "UNKNOWN_SHEET",
			});
		}
		const sheetName = target.title;
		const guarded = target.guarded;
		const a1 = a1SheetPrefix(sheetName);

		// ONE read for the header row AND the full target row. Replaces the two
		// separate gets this route used to make, and gives the guard and the audit
		// line the "before" they both need.
		let headers = [];
		let before = [];
		let snapshotUnavailable = false;
		try {
			const pre = await sheets.spreadsheets.values.batchGet({
				spreadsheetId: SPREADSHEET_ID,
				ranges: [`${a1}!1:1`, `${a1}!${rowIndex}:${rowIndex}`],
			});
			const vr = pre.data.valueRanges || [];
			headers = ((vr[0] && vr[0].values) || [[]])[0] || [];
			before = ((vr[1] && vr[1].values) || [[]])[0] || [];
			// ⚠️ An empty-but-successful read must not unlock the write — the same
			// fail-open #209's review caught on the delete batch. A guarded tab always
			// has a header row, so no header means the read failed, and with no
			// "before" the guard cannot know which cells changed OR which month the
			// row books to today. Both are exactly what it needs.
			if (!headers.length) snapshotUnavailable = true;
		} catch (err) {
			snapshotUnavailable = true;
			if (!guarded && req.session.user.role !== "Super Admin") throw err;
		}
		if (snapshotUnavailable && guarded) {
			return res.status(409).json({
				error: "The current contents of this row could not be read, so the edit cannot be shown to leave closed months alone and cannot be recorded reversibly. Try again.",
				code: "ROW_READ_FAILED",
			});
		}

		// Validate Job Tracking Owner ID early — reject investors.id typos before any
		// writes happen. (Reuses the headers just read.)
		//
		// Keyed on `guarded`, NOT on `sheetName === "Job Tracking"`: when the tab
		// list cannot be read, resolveSheetTargetForWrite falls back to the raw
		// request string, so `?sheet=job tracking` would make that equality false
		// while values.batchGet and the write both still land on Job Tracking (A1
		// notation is case-insensitive) — skipping this check in exactly the window
		// where least is known. validateOwnerIdCell is a no-op on any tab without an
		// "Owner ID" header, so widening it costs nothing.
		if (guarded) {
			const ownerErr = validateOwnerIdCell("Job Tracking", headers, values);
			if (ownerErr) return res.status(400).json({ error: ownerErr.error });
		}

		// For non-Admin users, preserve original broker/phone column values so the
		// sanitized copy they were served doesn't overwrite the full record.
		//
		// ⚠️ THIS WAS A NO-OP UNTIL NOW, and it was losing data. The old code read
		// `${sheetName}!A${rowIndex}` — in A1 notation that is the single CELL A5,
		// not row 5 (verified against a real spreadsheet: it returns 1 value where
		// `5:5` returns 25). So `currentValues[i]` was undefined for every column
		// past A, the `&& currentValues[i]` test never passed, and nothing was ever
		// spliced back. Measured against production's layout, what a Dispatcher then
		// wrote back was lossy: sanitizeBrokerColumns() then picked its column with
		// `headers.find(/phone|contact/i)`, which matches "Broker Contact Name"
		// (it contains "Contact") BEFORE "Phone Number" — so the column actually
		// redacted was Broker Contact Name, and saving the row wrote that stripped
		// copy over the stored value. Reading the real row above is what fixed the
		// splice.
		//
		// ⚠️ THAT SHADOWING IS FIXED TOO — see resolveBrokerWithheldColumns().
		// "Phone Number" and "Email" were reached by neither lookup, so they were
		// served IN FULL to every non-Super-Admin caller; they are withheld now,
		// which is exactly why the splice below must take its column list from the
		// same resolver rather than carrying a second copy of the rule.
		//
		// ⚠️ RESTORE ONLY WHAT WAS REDACTED, not every matching column. Because the
		// splice had never once run, "preserve broker columns" had never actually
		// restricted anybody — and both columns are editable in the Active Loads
		// modal a Dispatcher uses. A blanket restore would silently discard their
		// edit, answer {success:true}, and let the UI show the change until the next
		// refresh. So the value is put back only when the caller sent back exactly
		// the redacted copy GET /api/data served them; a genuine edit goes through.
		//
		// ⚠️ THE CANDIDATE SET IS DERIVED, NOT RE-SPELLED. This filter used to be
		// its own hardcoded `/broker|phone|contact/i`, which does NOT match
		// "Email" — so the moment the reader started redacting that column (it
		// now does; it always should have), a Dispatcher's save would write ""
		// straight over the stored address. A disclosure bug turns into DATA LOSS
		// the instant the reader and the writer disagree about which columns were
		// redacted, so both now ask resolveBrokerWithheldColumns(). The
		// `served !== stored` test below remains the real authority; this is only
		// the candidate list.
		const preserved = [];
		if (req.session.user.role !== "Super Admin") {
			const servedRow = sanitizeBrokerColumns(headers, [rowObjectFromCells(headers, before)])[0] || {};
			const withheldCols = new Set(resolveBrokerWithheldColumns(headers));
			headers.forEach((h, i) => {
				if (!withheldCols.has(h) || !before[i] || i >= values.length) return;
				const stored = String(before[i]);
				const served = servedRow[h] === undefined ? stored : String(servedRow[h]);
				// Nothing was hidden from them for this column — let them edit it.
				if (served === stored) return;
				// They sent the redacted copy straight back: that is the round-trip
				// this splice exists to catch, not an edit.
				if (String(values[i] == null ? "" : values[i]) === served) {
					values[i] = before[i];
					preserved.push(String(h).trim() || `col${i + 1}`);
				}
			});
		}

		// Diff AFTER the splice — the spliced values are what actually get written,
		// so they are what has to be judged and what has to be audited.
		const after = sheetRowAfterUpdate(before, values);
		const changes = changedGuardedCells(headers, before, after);

		const auditDetails = (outcome, extra) => buildSheetUpdateAudit({
			outcome,
			sheet: sheetName,
			rowIndex,
			// Every changed cell, guarded or not — the audit's job is to make the
			// write reversible by hand, and a corrected address is as much a change
			// as a corrected payment.
			changed: (() => {
				const out = [];
				for (let i = 0; i < Math.max(headers.length, before.length, after.length); i++) {
					const from = before[i] == null ? "" : String(before[i]);
					const to = after[i] == null ? "" : String(after[i]);
					if (from === to) continue;
					out.push({ column: String(headers[i] == null ? "" : headers[i]).trim() || "(unnamed)", index: i, from, to, why: guardedColumnReason(headers[i]) || "" });
				}
				return out;
			})(),
			guardedChanged: changes,
			snapshotUnavailable,
			...extra,
		});

		// ⚠️ A LOAD ID CHANGE REACHES A ROW THIS GUARD NEVER LOOKED AT.
		// sheetRowUpdateBlocker judges the months of the EDITED row only, but
		// deduplicateLoads() runs inside getJobTrackingCached() — which every
		// aggregate reads — and it resolves a collision by keeping the LAST row with
		// that id. So retyping an open-month row's Load ID to match a completed load
		// sitting in a finalized month shadows that row out of every total: both
		// sides of the edited row are open, `locked` is empty, and the guard allows
		// it while a closed month quietly loses the revenue. The reverse (making a
		// duplicate unique again) re-admits the shadowed row's money the same way.
		// Load ID is the one guarded column whose edit moves a DIFFERENT row's
		// contribution, so the same-row test cannot see it by construction.
		//
		// Refusing the collision outright is both the cheap fix and the correct rule
		// on its own: POST /api/loads/from-ratecon already 409s DUPLICATE_LOAD for
		// exactly this, and two live rows sharing a load id is a bug in any month.
		// Only fires when the Load ID actually CHANGES, so the 116 duplicate rows
		// already on the production sheet stay editable.
		if (guarded) {
			const lidChange = changes.find((c) => /load.?id|job.?id/i.test(c.column));
			if (lidChange) {
				const norm = (v) => String(v == null ? "" : v).trim().toLowerCase().replace(/^#/, "");
				const target = norm(lidChange.to);
				if (target) {
					let collision = null;
					try {
						const colLetter = a1ColumnLetter(lidChange.index);
						const all = await sheets.spreadsheets.values.get({
							spreadsheetId: SPREADSHEET_ID,
							range: `${a1}!${colLetter}:${colLetter}`,
						});
						const cells = (all.data.values || []).map((r) => (r && r[0]) || "");
						for (let i = 1; i < cells.length; i++) {
							if (i + 1 === rowIndex) continue;   // the row being edited
							if (norm(cells[i]) === target) { collision = i + 1; break; }
						}
					} catch (err) {
						// Fail CLOSED: an unread Load ID column means the collision cannot
						// be ruled out, and this is the one check standing between a
						// retyped id and a silently shadowed locked-month load.
						logAudit(req, "update_sheet_row_blocked", "sheet_row", `${sheetName}!${rowIndex}`, sheetAuditWithCode(auditDetails("blocked", { code: "LOAD_ID_CHECK_FAILED", error: err.message }), "LOAD_ID_CHECK_FAILED"));
						return res.status(409).json({
							error: "This edit changes the Load ID, and the existing load ids could not be read to check for a collision. Try again.",
							code: "LOAD_ID_CHECK_FAILED",
						});
					}
					if (collision) {
						logAudit(req, "update_sheet_row_blocked", "sheet_row", `${sheetName}!${rowIndex}`, sheetAuditWithCode(auditDetails("blocked", { code: "DUPLICATE_LOAD" }), "DUPLICATE_LOAD"));
						return res.status(409).json({
							error: `Load ID '${lidChange.to}' already exists on row ${collision}. Two rows sharing a load id are collapsed to one everywhere the app totals revenue, so this would silently drop that row's figures — including out of a finalized month. Use a unique load id.`,
							code: "DUPLICATE_LOAD",
							conflictRowIndex: collision,
						});
					}
				}
			}
		}

		const blocker = sheetRowUpdateBlocker(guarded, headers, before, after, changes);
		if (blocker) {
			// Record the attempt. `super_admin` is a shared login, so a refusal that
			// left no trace would make a repeated attempt to rewrite a closed month
			// invisible in the one place anyone looks afterwards.
			// logAuditRefusal, not logAudit — see the create twin in POST /api/data. Every
			// code sheetRowUpdateBlocker() can answer here is a PERIOD_* one and all three
			// are in UNCOALESCED_REFUSAL_CODES, so this is byte-identical today: still one
			// row per attempt, still carrying its own sheet address and month list. What it
			// buys is that the action now declares its coalescing rule in one place, and
			// the sibling refusals on this same action (DUPLICATE_LOAD, SHEET_CHANGED) —
			// which ARE reachable on demand — are the ones a future reader will reach for.
			logAuditRefusal(req, "update_sheet_row_blocked", "sheet_row", `${sheetName}!${rowIndex}`, sheetAuditWithCode(auditDetails("blocked", { code: blocker.code, periods: blocker.periods }), blocker.code), blocker.code);
			return res.status(409).json({
				error: blocker.error,
				code: blocker.code,
				periods: blocker.periods,
				...(blocker.changed ? { changed: blocker.changed } : {}),
				// Which date cells could not be read, so the caller can fix the right
				// one without parsing it back out of the prose.
				...(blocker.unreadable ? { unreadable: blocker.unreadable } : {}),
			});
		}

		// ⚠️ RE-READ IMMEDIATELY BEFORE WRITING, for the same reason
		// POST /api/admin/remove-rows does. Row indices are POSITIONAL: a delete
		// landing between the snapshot above and the write below shifts every
		// following row up, so row 214 — judged as an open-month load — becomes what
		// was row 215, and this request overwrites a row the guard never evaluated
		// while the audit records a `before` describing a different load. `values.update`
		// leaves a plausible-looking row where a delete at least leaves a hole, and
		// `super_admin` is a SHARED login, so two people on it is the normal case.
		if (guarded) {
			let fresh = null;
			try {
				const re = await sheets.spreadsheets.values.get({
					spreadsheetId: SPREADSHEET_ID,
					range: `${a1}!${rowIndex}:${rowIndex}`,
				});
				fresh = ((re.data.values || [[]])[0]) || [];
			} catch (err) {
				logAudit(req, "update_sheet_row_blocked", "sheet_row", `${sheetName}!${rowIndex}`, sheetAuditWithCode(auditDetails("blocked", { code: "ROW_READ_FAILED", error: err.message }), "ROW_READ_FAILED"));
				return res.status(409).json({
					error: "The row could not be re-read immediately before writing, so it cannot be confirmed to be the row that was checked. Try again.",
					code: "ROW_READ_FAILED",
				});
			}
			const same = (a, b) => {
				const n = Math.max(a.length, b.length);
				for (let i = 0; i < n; i++) if (String(a[i] == null ? "" : a[i]) !== String(b[i] == null ? "" : b[i])) return false;
				return true;
			};
			if (!same(fresh, before)) {
				logAudit(req, "update_sheet_row_blocked", "sheet_row", `${sheetName}!${rowIndex}`, sheetAuditWithCode(auditDetails("blocked", { code: "SHEET_CHANGED" }), "SHEET_CHANGED"));
				return res.status(409).json({
					error: `Row ${rowIndex} changed while this edit was being checked — another write, or a deleted row shifting the sheet up, means this index no longer points at the row that was validated. Re-open the row and try again.`,
					code: "SHEET_CHANGED",
				});
			}
		}

		let response;
		try {
			response = await sheets.spreadsheets.values.update({
				spreadsheetId: SPREADSHEET_ID,
				range: `${a1}!A${rowIndex}`,
				valueInputOption: "USER_ENTERED",
				requestBody: {
					values: [values],
				},
			});
		} catch (err) {
			// Audit the failed attempt too. A timed-out Sheets write leaves it
			// genuinely unknown whether the row changed, and that is precisely when
			// the before/after values are worth having.
			logAudit(req, "update_sheet_row_failed", "sheet_row", `${sheetName}!${rowIndex}`, auditDetails("failed", { error: err.message }));
			throw err;
		}

		logAudit(req, "update_sheet_row", "sheet_row", `${sheetName}!${rowIndex}`, auditDetails("updated"));
		// The 60s Job Tracking cache would otherwise keep serving the old figures.
		if (guarded) jtCacheInvalidate();

		res.json({
			success: true,
			updatedCells: response.data.updatedCells,
			// Columns whose redacted value was put back rather than written. Told to
			// the caller instead of silently swallowed, so a UI can mark them
			// read-only rather than showing an edit that did not happen.
			...(preserved.length ? { preserved } : {}),
		});
	} catch (error) {
		console.error("Error updating row:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// POST /api/webhook/new-load — Called by n8n after writing a load to Google Sheets.
// Emits a socket event so connected dashboards refresh instantly instead of waiting for the 60s poll.
app.post("/api/webhook/new-load", (req, res) => {
	const webhookSecret = process.env.N8N_WEBHOOK_SECRET;
	if (!webhookSecret || req.headers["x-webhook-secret"] !== webhookSecret) {
		return res.status(401).json({ error: "Unauthorized" });
	}
	jtCacheInvalidate();
	const loadId = req.body?.load_id || req.body?.loadId || "";
	const driver = req.body?.driver || "";
	insertDispatchNotification.run(
		"new-load",
		`New Load${loadId ? " " + loadId : ""}`,
		driver ? `Assigned to ${driver}` : "New load added from dispatch workflow",
		JSON.stringify({ loadId, driver, source: "n8n" })
	);
	io.to("dispatch").emit("new-load", { timestamp: Date.now() });
	io.to("dispatch").emit("dispatch-notification", { type: "new-load", title: `New Load${loadId ? " " + loadId : ""}`, body: driver ? `Assigned to ${driver}` : "New load added" });
	res.json({ ok: true });
});

// Validate a caller-supplied Job Tracking row number, or refuse the request.
// Returns the coerced integer, or null AFTER sending a 400 — the same
// "already responded, just return" convention as resolveDriverActor() below.
//
// ⚠️ ROW 1 IS THE HEADER ROW, and `if (!rowIndex)` does not stop a write to it:
// 1 is truthy. Every column in this app is resolved by matching header TEXT
// (findCol, headers.findIndex(/driver/i), the /rate|amount|revenue|pay/ money
// pattern), so overwriting row 1 re-points the dashboard, the driver app,
// /api/financials, /api/investor and the invoice batch at once, silently, with
// no data row touched. That is why PUT /api/data/:rowIndex has refused
// `rowIndex < 2` since #209 — this is the same rule, the same status code and
// the same error body, so the two can't answer differently.
//
// Number(), not parseInt(): parseInt("5abc") is 5 and parseInt("2.9") is 2, so
// a malformed index silently picks a real row. Callers use the RETURNED number
// (never the raw body value) to build their A1 ranges, so the row that gets
// written is always the row that was validated — a string like "2:D1000" can no
// longer widen `Job Tracking!D2` into a range.
function resolveSheetDataRow(res, value) {
	const rowIndex = Number(value);
	if (!Number.isInteger(rowIndex) || rowIndex < 2) {
		res.status(400).json({
			error: "rowIndex must be a whole number of 2 or more — row 1 is the header row, and rewriting it re-points every column this app resolves by header text.",
			code: "INVALID_ROW_INDEX",
		});
		return null;
	}
	return rowIndex;
}

// Raw Job Tracking row (array) → the header-keyed shape the month resolvers read.
// Blank header cells are skipped: an "" key would collide across every unnamed
// column, and Job Tracking's last column is literally named "output".
function sheetRowToObject(headers, row) {
	const out = {};
	(headers || []).forEach((h, c) => { if (h) out[h] = (row || [])[c]; });
	return out;
}

// The Job Tracking status column, BY NAME, resolved with the same first-match
// /status/i the four dispatch routes use to pick the cell they write — so the
// guard and the write can never end up reading different columns.
//
// Returns null when the match is a date column, and every caller treats null as
// "assume this write is material". /status/i also matches "Status Update Date";
// on production "Job Status" (index 11) sorts ahead of it (21), but that is
// header ORDER, not a guarantee. On a sheet with no plain status column this
// would resolve a DATE, no value would ever look completed, and the guard would
// fail OPEN on every row — the one failure mode that must not be silent.
function jobStatusColumnName(headers) {
	const name = findCol(headers || [], /status/i);
	if (!name || /date/i.test(name)) return null;
	return name;
}

const DISPATCH_COMPLETED_RE = /^(delivered|completed|pod received)$/i;

// May this dispatch / driver-status write land on this row? null to allow, else
// the 409 body. Shared by POST /api/dispatch, POST /api/dispatch/reassign,
// POST /api/driver/respond and PUT /api/driver/status — the four routes that
// write Driver / Job Status / Truck / Owner ID, i.e. four of the eleven cells
// sheetRowUpdateBlocker() exists to protect, while bypassing it completely.
//
// Measured during PR #222: PUT /api/data/:rowIndex REFUSED to restore row 306
// with 409 PERIOD_FINALIZED while POST /api/dispatch had just written all four
// of those cells to that same finalized row with no complaint.
//
// ⚠️ THIS IS DELIBERATELY NOT A BLANKET REFUSAL, and the reason is not
// convenience. A dispatcher assigning a driver to an older load is ordinary
// work; a guard that refuses ordinary work gets switched off, and then it
// protects nothing. POST /api/dispatch/cancel was left unguarded in PR #211 on
// exactly this reasoning ("a broker calling off a July load in August is
// normal"). So the line is drawn where the MONEY is, not where the paperwork is:
//
//   A load contributes to a month ONLY when its status is completed. Revenue
//   (`if (completedStatuses.test(st))`, /api/investor ~29118 and /api/financials
//   ~32420) and driver pay (`completedStatuses.test(st) && driver`, ~29139) are
//   both gated on it, and nothing else on this row reaches a settled figure.
//   So on a load that is NOT completed, Driver, Job Status, Truck and Owner ID
//   all carry $0 into whatever month it books in — closed or open. Assignment,
//   reassignment, acceptance and every mid-trip status stay unblocked.
//
//   The moment either side of the write is completed, those same four cells ARE
//   the month's revenue, the days its driver is paid for, and the investor it
//   pays: 382 production rows, $313,923.93, 356 of them carrying a driver
//   ($296,350.93) and $83,073.34 of it inside owner 5's already-PAID 2026-05 and
//   2026-06 payouts. Then it refuses.
//
// ⚠️ IT IS NOT THE "DOES THIS ROW CONTRIBUTE TODAY?" PREDICATE statusOverrideBlocker()
// warns against, and the difference is load-bearing. That predicate asks only
// about the BEFORE state, so it answers "no" for the 25 Cancelled rows sitting
// in locked months ($29,166.25) and waves through the flip to Delivered that
// injects them. This asks about BOTH sides — `completed(before) || completed(after)`
// — so the injection is material by the AFTER state and the erasure by the
// BEFORE state, and both refuse. Reviving a cancelled load is allowed (it moves
// $0, and reviving one cancelled by mistake is the 2026-08-05 incident), but the
// COMPLETION that would book its money is then refused here and by
// statusOverrideBlocker() alike. The guard fires where the money moves.
//
// Materiality is the union of three tests, any one sufficient:
//   1. completed on EITHER side — the write changes what the month is made of;
//   2. the write MOVES the row's months — jobTrackingMonthCols().dateCol takes
//      the FIRST header matching status-update/completion/assigned date. On
//      production "Assigned Date" (20) wins over "Status Update Date" (21) and
//      "Completion Date" (22), so PUT /api/driver/status stamping those two is
//      inert — but that is header luck, not a property of the route (the same
//      trap statusOverrideBlocker() documents). On a layout resolving to Status
//      Update Date, that stamp moves the load's revenue month, which is why the
//      months are compared before ∪ after and never before-only (PR #218);
//   3. the status column cannot be told apart from a date column — fail closed.
//
// ⚠️ "THE CANCELLED FLAG CHANGED" WAS CONSIDERED AS A FOURTH TEST AND REJECTED —
// do not add it back. It looks necessary because excludeDroppedLoads() drops a
// cancelled row from every aggregate, so crossing that boundary visibly changes
// what the month contains. But every crossing that moves MONEY already has a
// completed side and is caught by test 1: Delivered → Cancelled is the erasure,
// Cancelled → Delivered the injection. What is left over is exactly
// Cancelled ↔ Dispatched/Assigned/Unassigned/mid-trip, where revenue and driver
// pay are $0 on both sides — so the test protected nothing and cost the one
// operation this route exists for on a closed month: reviving a load cancelled
// by mistake, which is the 2026-08-05 incident that put a reason field on
// POST /api/dispatch/cancel. The revived load then sits at "Dispatched" until
// someone reopens the period, because its COMPLETION is what test 1 refuses.
//
// Fails closed on an unreadable period_locks and, once material, on a row whose
// months cannot be resolved on either side. A NON-material write is allowed
// without resolving months at all, and that is not a fail-open: if no settled
// figure moves, it does not matter which month the row belongs to.
//
// Ungated on PERIOD_FINALIZE_ENABLED, like every other lock guard: flag off
// means period_locks is empty, nothing is locked, one indexed SELECT.
//
// `before` is the header-keyed row as it stands; `edits` is the header-keyed
// delta the route would apply, i.e. after = {...before, ...edits}.
function dispatchWriteBlocker(headers, before, edits) {
	// RUNG 1 — refuse FIRST on an unreadable lock table. isLocked() swallows
	// every error and answers "not locked", so without this the guard would be
	// present, silent and open.
	if (!periodLocksReadable()) return { code: "PERIOD_LOCK_UNREADABLE", periods: [] };

	const after = { ...before, ...(edits || {}) };
	const statusName = jobStatusColumnName(headers);
	const statusOf = (row) => (statusName ? String(row[statusName] == null ? "" : row[statusName]).trim() : "");
	const isCompleted = (row) => DISPATCH_COMPLETED_RE.test(statusOf(row));

	// Status-blind by construction, exactly like loadRowPeriods' other callers:
	// it reads dates only, which is what makes the cancelled-row resurrection
	// case above come out right for free.
	const cols = jobTrackingMonthCols(headers);
	const pBefore = loadRowPeriods(before, cols);
	const pAfter = loadRowPeriods(after, cols);

	const material =
		!statusName ||
		isCompleted(before) || isCompleted(after) ||
		pBefore.periods.join("|") !== pAfter.periods.join("|");
	if (!material) return null;

	// PERIOD_FINALIZED outranks PERIOD_UNRESOLVED, matching statusOverrideBlocker():
	// "this would restate June" is the answer an operator can act on, and the
	// remedy (reopen the period) is the same either way.
	const locked = lockedAmong([...new Set([...pBefore.periods, ...pAfter.periods])]);
	if (locked.length) return { code: "PERIOD_FINALIZED", periods: locked };
	if (!pBefore.resolved || !pAfter.resolved) return { code: "PERIOD_UNRESOLVED", periods: [] };
	return null;
}

// One refusal shape for all four routes, and the audit line that goes with it.
// Refusals are recorded as well as successes: `super_admin` is a shared login,
// so an untraced refusal would make a repeated attempt to rewrite a closed month
// invisible in the one place anyone looks afterwards.
//
// ⚠️ `loadId` and `what` are caller-derived and capped for the same reason
// sendLoadBindRefusal() caps them: `what` interpolates `driver` / `newDriver`,
// which fall back to the caller's raw string, and neither this function nor
// logAudit() bounded them. Reachable here only when the period guard fires
// (locked month + material write) rather than on demand — but the two refusal
// helpers sit side by side, and one of them capping is worse than neither,
// because it reads as a decision that the other case is safe.
function sendDispatchRefusal(req, res, blocked, action, loadId, what) {
	const periods = blocked.periods || [];
	// Coalesced — see logAuditRefusal(). A period refusal is far harder to spam
	// than a binding one (it needs a locked month AND a material write), but the
	// two helpers sit side by side and one coalescing while its neighbour does not
	// reads as a decision that the other case cannot flood.
	logAuditRefusal(
		req, action, "load",
		(typeof loadId === "string" || typeof loadId === "number") ? String(loadId).slice(0, 100) : "",
		// scrubPurgeMarker: `what` interpolates the caller's raw driver name, and a
		// `[PERIOD_` in it would exempt this row from purgeOldAuditRefusals() forever.
		// The real marker is the `[${blocked.code}]` immediately after it, which is a
		// literal bracket around a module constant and is not scrubbed.
		`Blocked ${scrubPurgeMarker(what == null ? "" : what).slice(0, 200)} [${blocked.code}]${periods.length ? ` periods=${periods.join(",")}` : ""} — ${JSON.stringify({ code: blocked.code, periods })}`,
		blocked.code
	);
	// AUDITED_UPSTREAM: the logAuditRefusal above IS this refusal's row. Passing a
	// descriptor here would write a second one for the same event.
	if (blocked.code === "PERIOD_LOCK_UNREADABLE") return sendPeriodRefusal(req, res, "unreadable", null, null, AUDITED_UPSTREAM);
	if (blocked.code === "PERIOD_UNRESOLVED") return sendPeriodRefusal(req, res, "unresolved", null, what, AUDITED_UPSTREAM);
	return sendPeriodRefusal(req, res, "finalized", periods, what, AUDITED_UPSTREAM);
}

// Read Job Tracking's header row, EVERY data row, and the caller's target row
// in a single round trip.
//
// ⚠️ THE FULL-TAB RANGE IS THE POINT, AND IT COSTS NOTHING EXTRA. This replaced
// a two-range batchGet (`Job Tracking!1:1` + `Job Tracking!{n}:{n}`) at the SAME
// API-call count — the Sheets 300/min quota counts requests, not bytes — because
// resolveLoadBinding() below has to answer "how many rows carry this load id?",
// and the column holding the id is only known AFTER the header row is read, so
// it cannot be named as a third range in the same batchGet. PUT
// /api/driver/status and PUT /api/loads/:loadId/status-override already read the
// whole tab on every call, and this family is user-initiated and low-frequency.
//
// ⚠️ NOT getJobTrackingCached(), for two independent reasons, either sufficient:
//   1. it is up to 60 s stale, and a row that moved WITHIN those 60 s is exactly
//      the state the binding exists to catch;
//   2. it returns deduplicateLoads() output — last row per load id wins — which
//      HIDES the duplicate rows AMBIGUOUS_LOAD is looking for.
// The binding has to be judged against the sheet as it is at write time.
//
// Returns null on a failed read; callers refuse rather than fall through, since
// the months AND the binding both depend on this read, and neither can be guessed.
async function readJobTrackingSnapshot(sheets, rowIndex) {
	try {
		const resp = await sheets.spreadsheets.values.get({
			spreadsheetId: SPREADSHEET_ID,
			range: "Job Tracking",
		});
		const all = resp.data.values || [];
		const rows = all.slice(1);
		return {
			headers: all[0] || [],
			rows,
			// Row 1 is the header row, so data row 0 is sheet row 2. An index past
			// the end yields [] — which carries no load id and is therefore refused
			// by the binding, never written to.
			row: rows[rowIndex - 2] || [],
		};
	} catch (e) {
		console.error(`Job Tracking read failed (target row ${rowIndex}):`, e.message);
		return null;
	}
}

// Does the row the caller named actually hold the load the caller named?
//
// ⚠️ `rowIndex` AND `loadId` ARE INDEPENDENT BODY FIELDS, AND UNTIL THIS GUARD
// NOTHING COMPARED THEM. Every route in this family writes to `rowIndex` while
// recording `loadId`: POST /api/dispatch/cancel set `Job Status = "Cancelled"`
// and blanked `Driver` at the caller's row, then audited, notified the driver,
// posted to the dispatch feed and stamped load_status_history — all naming a
// load it had never confirmed was there. A client whose cached row numbers no
// longer match the sheet therefore cancels WHATEVER LOAD SITS AT ROW N while
// every record names a different one.
//
// That is the 2026-08-05 incident again — a live $1,050 load cancelled instead
// of the one the broker called off — and the mandatory-reason guard shipped
// after it makes the outcome WORSE, not better: the reason is now attached to
// the wrong load, so the record reads as deliberate and correct.
//
// It is not theoretical. Rows shift: DELETE /api/data/:rowIndex uses
// deleteDimension, which moves every row below it up by one, and nothing
// invalidates a client's cached `_rowIndex`. PR #246's own test harness derived
// row numbers from `Job Tracking!A:A` — short, because `Contract ID` is blank on
// ingested rows — and aimed writes at two real production rows.
//
// Resolution order, and why each rung is where it is:
//
//   1. NO LOAD ID → refuse. Without one there is nothing to bind the row to, and
//      omitting the field would otherwise be a free bypass of this whole guard.
//      It refuses no real work: on the local copy of production 8 of 412 rows
//      carry no load id, ALL EIGHT are already `Completed`, and
//      recordStatusChange() already discards the history row for a blank id
//      (`if (!lid || !ns) return`) — so such a cancel was never recordable.
//   2. NO LOAD ID COLUMN → refuse. Fail closed: the binding cannot be judged, and
//      "cannot judge" must never read as "allow" (the rung-1 lesson from
//      statusOverrideBlocker()).
//   3. THE ID IS ON NO ROW → refuse. The caller is acting on a load this sheet
//      does not have.
//   4. THE ID IS ON 2+ ROWS → refuse, #223's AMBIGUOUS_LOAD. Even when the
//      caller's row is one of them, cancelling one of two copies is a coin flip
//      on whether it takes effect at all: the dashboard reads deduplicateLoads()
//      (last row wins), so cancelling the earlier copy changes nothing visible
//      while load_status_history records the load as cancelled. Measured before
//      choosing this: 87 of 288 distinct load ids sit on 2+ rows, but ZERO of
//      those 87 have a row that is not already completed or cancelled — the
//      duplicates are entirely historical, so this refuses no live work. That
//      measurement is the argument; without it this rung would be exactly the
//      "guard that refuses ordinary work and then gets switched off" #211 warns
//      about.
//
//      ⚠️ opts.callerRowWinsAmongDuplicates RELAXES RUNG 4 — AND ONLY RUNG 4,
//      AND ONLY WHEN THE CALLER'S OWN ROW IS ONE OF THE COPIES. It exists
//      because the measurement above is true for the four routes #248 wired and
//      FALSE for PUT /api/driver/status, the driver app's main write path.
//      Re-measured against the PRODUCTION sheet (read-only) over the whole
//      load_status_history window 2026-06-15 .. 2026-08-06: of 199 real manual
//      status changes, 195 (98.0%) bind cleanly, 0 hit LOAD_ID_REQUIRED, 0 hit
//      LOAD_NOT_ON_SHEET — and 4 hit AMBIGUOUS_LOAD. Those 4 are not stray
//      traffic: they are Howard Reddie advancing load 7052901 through Heading
//      to Shipper → In Transit → At Receiver → Delivered on 2026-07-11..14. The
//      id is duplicated because row 383 holds the live load and row 388 holds a
//      "#7052901" copy that was CANCELLED. A blanket rung 4 would have refused
//      a driver in the cab, four times, on his own load, with the only remedy
//      (delete the stale row) being Super-Admin-only — the exact shape of guard
//      #211 warns gets switched off, after which it protects nothing.
//      The relaxation keeps the whole security property intact, because the
//      invariant it preserves is the one that matters: THE WRITTEN ROW ALWAYS
//      HOLDS THE NAMED LOAD. A row can only be accepted here by carrying the
//      caller's own load id, so no input reaches another load's row — to do
//      that an attacker would need the victim row to carry the attacker's load
//      id, which is a contradiction. What the caller gains is only the choice of
//      WHICH COPY OF THEIR OWN LOAD to advance, and a status write is scoped to
//      its row (unlike a cancel, whose whole purpose is to take the load off the
//      board). Ambiguity is still refused when the caller's row is NOT one of
//      the copies, because then the server would have to guess which copy — and
//      guessing is precisely what produced the 2026-08-05 incident.
//
//      ⚠️⚠️ WHAT THE RELAXATION LEANS ON, AND IT IS NOT LOCAL TO THIS FUNCTION.
//      "Choice of which copy of their OWN load" is only a safe thing to grant
//      while ownership is judged on the DEDUPLICATED view. loadBelongsToDriver()
//      iterates getJobTrackingCached(), which returns deduplicateLoads() output
//      — LAST row per load id wins — so to own a duplicated load a Driver must
//      own its LAST row, which is also the row every dashboard, KPI and payout
//      surface treats as the load. This guard, by contrast, deliberately reads
//      the RAW snapshot (it has to; the deduped view hides the duplicates it
//      counts). Those two views disagreeing is exactly what keeps the pair safe:
//      the attacker-controlled row is the representative one, so writing to an
//      earlier copy moves nothing anyone reads. If loadBelongsToDriver() is ever
//      "fixed" to scan raw rows, a Driver owning ANY copy could stamp a status
//      onto a DIFFERENT driver's copy of the same id. Do not change that helper
//      to a raw scan without narrowing this relaxation in the same commit —
//      e.g. to additionally require the target row's Driver cell to match the
//      actor. Pinned by scripts/test-driver-status-row-binding.js.
//   5. THE ID IS ON EXACTLY ONE ROW, AND IT IS NOT THE CALLER'S → refuse, and
//      name the row it IS on so the caller can refresh rather than guess.
//
// ⚠️ MATCH ON THE NORMALISED ID. Job Tracking stores both "513987502" and
// "#513987502" — 93 of 412 rows on the local copy carry the '#' — so a raw
// string compare would refuse a large slice of legitimate cancels. normLoadKey()
// is the app's single normaliser (defined beside getLoadCoordsRow(), which
// exists for this same inconsistency); a second copy here would be free to drift
// from the one every other load lookup uses.
//
// ⚠️ THE REFUSAL NEVER ECHOES WHAT THE TARGET ROW ACTUALLY HOLDS. Saying "row 14
// holds load 562787563" would turn this into a load-id oracle for the one caller
// who can reach it without being an admin — a Driver on POST /api/driver/respond
// — who could sweep rowIndex 2..N with their own load id and read the whole
// sheet's ids back. Load ids are not inert: GET /api/public/track/:loadId is
// unauthenticated and keyed on nothing else. The caller is told their OWN load's
// row, which they already named, and nothing about anyone else's.
//
// ⚠️ THIS NARROWS THE WINDOW; IT DOES NOT CLOSE IT. Sheets has no transactions,
// so a row deleted between the snapshot read and the write still shifts the
// target — the app-wide "no transactions" caveat, not something specific here.
// What changes is the size: the unguarded window was "however long this client's
// cached _rowIndex has been stale", which is unbounded and in practice hours;
// the remaining one is the few hundred ms of a single request, and it needs a
// concurrent DELETE to land inside it. Closing it entirely needs an idempotency
// key or a row id the sheet does not have — worth doing, not worth blocking this.
//
// Pure: no I/O, no clock, no database. Returns null to allow, else the refusal.
// `opts.callerRowWinsAmongDuplicates` defaults OFF, so the four routes #248 wired
// keep byte-identical behaviour; only PUT /api/driver/status opts in.
function resolveLoadBinding(headers, rows, rowIndex, loadId, opts) {
	// ⚠️ TYPE FIRST, because normLoadKey() goes through String() and JS array
	// coercion is not the identity: String(["562620213"]) === "562620213", so a
	// one-element array would bind exactly as the bare id does. That is not a
	// binding bug — it resolves to the right row — but the same value then flows
	// on to logAudit(), insertNotification.run() and a `db.prepare(...).run()`,
	// where better-sqlite3 refuses a non-primitive and throws AFTER the sheet has
	// already been written. Refusing the type here is one rule instead of a
	// case-by-case audit of every sink, and mirrors PR #246's `typeof newStatus
	// !== "string"` on the sibling route.
	// ⚠️ LENGTH IS PART OF THE TYPE GATE, and it is not cosmetic. `.trim()` strips
	// SP/TAB/NBSP/ZWNBSP/LS, so `" ".repeat(200000) + "#562620213"` normalises to
	// a real load id and BINDS — after which the routes hand the *raw* value
	// (never the normalised one) to insertLoadResponse.run, insertNotification.run,
	// insertDispatchNotification.run, logAudit and io.emit, none of which cap it,
	// against a 50mb body limit with body-parser inflation. Capping here is what
	// makes the 64/100-char caps below a policy rather than a coincidence. 128
	// clears every real id many times over: production ids are 6-12 digits and the
	// longest alphanumeric broker ref seen is SHP2607-A3BJ112 (15).
	const typed = (typeof loadId === "string" || (typeof loadId === "number" && Number.isFinite(loadId)))
		&& String(loadId).length <= 128;
	// Capped before it is echoed anywhere. The body limit is 50mb and
	// body-parser inflates, so an unbounded id in an error string is the same
	// reflection PR #246 capped on the status route — and POST /api/driver/respond
	// is Driver-reachable at driverWriteLimiter's 60/min.
	const shown = typed ? String(loadId).trim().slice(0, 64) : "";
	const wanted = typed ? normLoadKey(loadId) : "";
	if (!wanted) {
		return {
			http: 400,
			code: "LOAD_ID_REQUIRED",
			// Deliberately does not echo the value — there is nothing useful to show
			// a caller who sent 200 KB of padding.
			error: "A load id is required: text or a number, at most 128 characters. This route writes to the row number the caller supplies, so without a load id the server cannot confirm that row holds the load you meant — and the audit entry, the driver notification and the status history would all name nothing.",
		};
	}

	const loadIdIdx = (headers || []).findIndex((h) => /load.?id|job.?id/i.test(h));
	if (loadIdIdx === -1) {
		return {
			http: 409,
			code: "SHEET_LOAD_ID_MISSING",
			error: "Job Tracking has no Load ID column, so the server cannot confirm that the row it was given holds the load you named. Refusing rather than writing to an unverified row.",
		};
	}

	const carrying = [];
	for (let i = 0; i < (rows || []).length; i++) {
		if (normLoadKey((rows[i] || [])[loadIdIdx]) === wanted) carrying.push(i + 2);
	}

	if (!carrying.length) {
		return {
			http: 404,
			code: "LOAD_NOT_ON_SHEET",
			error: `Load ${shown} is not on Job Tracking, so there is no row to act on. Refresh and try again.`,
		};
	}
	if (carrying.length > 1) {
		// The caller named one of the copies, and this route opted in: the row
		// demonstrably holds the named load, which is the only question this guard
		// asks. See the ⚠️ on rung 4 above for the measurement that forced this and
		// for why it cannot reach another load's row.
		// ⚠️ `Object.hasOwn`, not a truthiness read. `opts.callerRowWinsAmongDuplicates`
		// on a bare `{}` would inherit from a polluted Object.prototype and switch the
		// relaxation on for a caller that never asked. No caller passes `{}` today and
		// there is no known pollution primitive here (no express.urlencoded, so no `qs`
		// vector), but an own-property test removes the class for one word.
		if (opts && Object.hasOwn(opts, "callerRowWinsAmongDuplicates")
			&& opts.callerRowWinsAmongDuplicates && carrying.includes(rowIndex)) return null;
		return {
			http: 409,
			code: "AMBIGUOUS_LOAD",
			rowIndices: carrying,
			error: `Load ${shown} appears on ${carrying.length} rows of Job Tracking (${carrying.join(", ")}), so the server cannot tell which one you mean. Give the duplicate rows distinct load ids — or remove the stale one — and try again.`,
		};
	}
	if (carrying[0] !== rowIndex) {
		return {
			http: 409,
			code: "ROW_LOAD_MISMATCH",
			rowIndex: carrying[0],
			error: `Row ${rowIndex} of Job Tracking does not hold load ${shown}, so this would have been applied to a different load. Your view of the board is out of date — rows move when one is deleted. Refresh and try again: load ${shown} is on row ${carrying[0]}.`,
		};
	}
	return null;
}

// One refusal shape for the binding, and the audit line that goes with it.
// Refusals are recorded as well as successes, for the same reason
// sendDispatchRefusal() records its own: `super_admin` is a shared login, so an
// untraced refusal would make a repeated attempt to write to a row that is not
// the load being named invisible in the one place anyone looks afterwards — and
// "someone tried to cancel row 14 claiming it was load X" is precisely the
// signal the 2026-08-05 incident had no record of.
//
// Reuses each route's existing `*_blocked` action so a period refusal and a
// binding refusal read out of one place, and caps the audited id at 100 chars
// exactly as PR #246 does (logAudit stores entity_id unbounded).
//
// ⚠️ `what` IS CAPPED TOO, and that one is the sharper edge. It is built by the
// callers from `driver` / `newDriver`, which fall back to the caller's raw
// `rawDriver.trim()` when no users row matches — unbounded, against a 50mb body
// limit, on two routes (POST /api/dispatch, /api/dispatch/reassign) that carry
// NO rate limiter at all. A ROW_LOAD_MISMATCH is triggerable on demand, so
// without this cap a dispatcher session could write tens of MB per request into
// audit_trail, which has no retention job. logAudit() itself caps nothing.
//
// ⚠️ STRINGIFY ONLY PRIMITIVES. `String(x)` on a deeply-nested array recurses
// through Array.prototype.toString and throws RangeError on a body like
// [[[[…]]]] — inside the refusal path, so the 409 would become a 500.
function sendLoadBindRefusal(req, res, refusal, action, loadId, what) {
	const detail = refusal.rowIndices
		? ` rows=${refusal.rowIndices.join(",").slice(0, 200)}`
		: (refusal.rowIndex ? ` load is on row ${refusal.rowIndex}` : "");
	const auditId = (typeof loadId === "string" || typeof loadId === "number")
		? String(loadId).slice(0, 100) : "";
	// Coalesced — see logAuditRefusal(). This is the helper PR #248 flagged: a
	// binding refusal is reachable on demand (a wrong rowIndex is a 409 every
	// time), on routes one of which a Driver can call 60x a minute.
	logAuditRefusal(
		req, action, "load", auditId,
		// scrubPurgeMarker, same reasoning as sendDispatchRefusal() — and sharper
		// here, because a ROW_LOAD_MISMATCH is a 409 on demand on two routes with no
		// rate limiter, so this is the cheapest way to mint a permanent row.
		`Blocked ${scrubPurgeMarker(what == null ? "" : what).slice(0, 200)} [${refusal.code}]${detail}`,
		refusal.code
	);
	const body = { error: refusal.error, code: refusal.code };
	if (refusal.rowIndices) body.rowIndices = refusal.rowIndices;
	else if (refusal.rowIndex) body.rowIndex = refusal.rowIndex;
	return res.status(refusal.http).json(body);
}

// POST /api/dispatch — Assign driver to a load and notify via Socket.IO
//
// ⚠️ PERIOD-GUARDED — see dispatchWriteBlocker() above for where the line is
// drawn and why it is not a blanket refusal.
app.post("/api/dispatch", requireRole("Super Admin", "Dispatcher"), async (req, res) => {
	try {
		const { rowIndex: rawRowIndex, driver: rawDriver, loadId, origin, destination } = req.body;
		if (!rawDriver) {
			return res.status(400).json({ error: "rowIndex and driver required" });
		}
		const rowIndex = resolveSheetDataRow(res, rawRowIndex);
		if (rowIndex === null) return; // 400 already sent

		// Normalize driver name against users table to prevent misspelling mismatches
		const userMatch = db.prepare("SELECT driver_name FROM users WHERE LOWER(driver_name) = LOWER(?) AND role = 'Driver'").get(rawDriver.trim());
		const driver = userMatch ? userMatch.driver_name : rawDriver.trim();

		// Queueing is allowed: dispatch to a driver who's already on a load,
		// the new row lands as "Dispatched" and queues behind their current
		// work. The "one accept at a time" rule is enforced at
		// POST /api/driver/respond — the driver can't promote a queued load
		// to Assigned until they've delivered their current one. The
		// LoadAssignedBanner emit below is suppressed for busy drivers so the
		// queue is silent until the driver is free (mid-trip notifications
		// were noisy and confused drivers about which load to work next).

		const sheets = await getSheets();
		// Headers, every row, AND the target row in one round trip — the target
		// row is what the period guard below judges, and the rest is what the
		// load binding needs. RUNG 2: a failed read REFUSES rather than falling
		// through to a generic 500.
		const snapshot = await readJobTrackingSnapshot(sheets, rowIndex);
		if (!snapshot) {
			return sendDispatchRefusal(
				req, res, { code: "PERIOD_UNRESOLVED", periods: [] },
				"dispatch_blocked", loadId, `Assigning ${driver} to load ${loadId || "(unknown)"}`
			);
		}
		const headers = snapshot.headers;

		// LOAD BINDING — before the period guard, and before every write. The
		// period guard reasons about the row at `rowIndex`; if that row is not the
		// load the caller named, its verdict is about the wrong load, so the
		// subject has to be established first. See resolveLoadBinding().
		{
			const unbound = resolveLoadBinding(headers, snapshot.rows, rowIndex, loadId);
			if (unbound) {
				return sendLoadBindRefusal(
					req, res, unbound, "dispatch_blocked", loadId,
					`assigning ${driver} to row ${rowIndex}`
				);
			}
		}

		const driverColIdx = headers.findIndex((h) => /driver/i.test(h));
		const statusColIdx = headers.findIndex((h) => /status/i.test(h));

		if (driverColIdx === -1) {
			return res.status(400).json({ error: "Driver column not found" });
		}

		// Look up truck and owner for this driver. Primary source is the
		// trucks.assigned_driver single-slot column, which assignDriverToTruck()
		// keeps in sync; if that's drifted (legacy admin edits, name casing,
		// etc.) we fall back to the active truck_assignments row. Without this
		// fallback a missed lookup stamps Owner ID = 0 on the load, which then
		// blocks the driver-name fallback in /api/investor (see commit 656f1b1).
		let truckForDriver = db.prepare("SELECT unit_number, owner_id FROM trucks WHERE LOWER(assigned_driver) = LOWER(?)").get(driver.trim());
		if (!truckForDriver) {
			truckForDriver = db.prepare(
				"SELECT t.unit_number AS unit_number, t.owner_id AS owner_id " +
				"FROM truck_assignments ta JOIN trucks t ON t.id = ta.truck_id " +
				"WHERE LOWER(ta.driver_name) = LOWER(?) AND ta.end_date = '' " +
				"ORDER BY ta.start_date DESC LIMIT 1"
			).get(driver.trim());
		}
		const truckUnit = truckForDriver ? truckForDriver.unit_number : '';
		const ownerId = truckForDriver ? truckForDriver.owner_id : 0;

		// PERIOD GUARD — before the first write, including the header-ensure
		// update just below. Assigning a driver to a load that is not completed
		// moves $0 and is allowed in any month; doing it to a COMPLETED load
		// un-completes it and erases that load's revenue and driver-pay days
		// from the month it settled in. See dispatchWriteBlocker().
		{
			const before = sheetRowToObject(headers, snapshot.row);
			const edits = {};
			if (headers[driverColIdx]) edits[headers[driverColIdx]] = driver;
			if (statusColIdx !== -1 && headers[statusColIdx]) edits[headers[statusColIdx]] = "Dispatched";
			// Truck / Owner ID are written too, but they carry neither a status
			// nor a date, so they cannot change this guard's answer; when their
			// headers do not exist yet the route creates them below, which also
			// changes nothing the guard reads.
			const blocked = dispatchWriteBlocker(headers, before, edits);
			if (blocked) {
				return sendDispatchRefusal(
					req, res, blocked, "dispatch_blocked", loadId,
					`Assigning ${driver} to load ${loadId || "(unknown)"}`
				);
			}
		}

		// Ensure Truck and Owner ID columns exist in sheet
		let truckColIdx = headers.findIndex(h => /^truck$/i.test(h));
		let ownerColIdx = headers.findIndex(h => /^owner.?id$/i.test(h));
		if (truckColIdx === -1 || ownerColIdx === -1) {
			const newHeaders = [];
			if (truckColIdx === -1) { newHeaders.push('Truck'); truckColIdx = headers.length + newHeaders.length - 1; }
			if (ownerColIdx === -1) { newHeaders.push('Owner ID'); ownerColIdx = headers.length + newHeaders.length - 1; }
			if (newHeaders.length) {
				await sheets.spreadsheets.values.update({
					spreadsheetId: SPREADSHEET_ID,
					range: `Job Tracking!${colLetter(headers.length)}1`,
					valueInputOption: "USER_ENTERED",
					requestBody: { values: [newHeaders] },
				});
				headers.push(...newHeaders);
			}
		}

		// Batch update: driver, status, truck, owner ID
		const updates = [
			{ range: `Job Tracking!${colLetter(driverColIdx)}${rowIndex}`, values: [[driver]] },
		];
		if (statusColIdx !== -1) updates.push({ range: `Job Tracking!${colLetter(statusColIdx)}${rowIndex}`, values: [["Dispatched"]] });
		if (truckColIdx !== -1) updates.push({ range: `Job Tracking!${colLetter(truckColIdx)}${rowIndex}`, values: [[truckUnit]] });
		if (ownerColIdx !== -1) updates.push({ range: `Job Tracking!${colLetter(ownerColIdx)}${rowIndex}`, values: [[String(ownerId)]] });

		await sheets.spreadsheets.values.batchUpdate({
			spreadsheetId: SPREADSHEET_ID,
			requestBody: { valueInputOption: "USER_ENTERED", data: updates },
		});

		// Persist notification and notify the driver in real-time
		const route = [origin, destination].filter(Boolean).join(' → ') || '';
		const notifResult = insertNotification.run(
			driver.trim().toLowerCase(), 'load-assigned',
			`New Load Assigned: ${loadId || 'Load'}`,
			route,
			JSON.stringify({ loadId, rowIndex, origin: origin || '', destination: destination || '' })
		);
		// Always notify the driver in real time. Drivers can hold multiple
		// accepted loads at once (dispatcher pre-planning), so there's no
		// busy-suppression — every assignment surfaces immediately.
		io.to(driver.trim().toLowerCase()).emit("load-assigned", { loadId, rowIndex, origin: origin || '', destination: destination || '', notificationId: notifResult.lastInsertRowid });

		// Notify dispatch team
		insertDispatchNotification.run(
			'load-assigned',
			`Assigned ${driver} to Load ${loadId || 'N/A'}`,
			route,
			JSON.stringify({ loadId, driver, rowIndex })
		);
		io.to("dispatch").emit("dispatch-notification", {
			type: 'load-assigned',
			title: `Assigned ${driver} to Load ${loadId || 'N/A'}`,
			body: route,
		});

		// Clear stale load_responses so driver gets a fresh Accept/Decline prompt
		if (loadId) {
			db.prepare("DELETE FROM load_responses WHERE load_id = ? AND driver_name = ?")
				.run(loadId, driver.trim().toLowerCase());
		}

		logAudit(req, 'dispatch_load', 'load', loadId, `Assigned driver ${driver} to load ${loadId}`);
			recordStatusChange({ loadId, newStatus: 'Dispatched', source: 'dispatch', actor: req.session?.user?.username || '' });
		notifyChange("dashboard"); jtCacheInvalidate();
		res.json({ success: true });
	} catch (error) {
		console.error("Error dispatching load:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// POST /api/dispatch/reassign — Reassign a load to a different driver
app.post("/api/dispatch/reassign", requireRole("Super Admin", "Dispatcher"), async (req, res) => {
	try {
		const { rowIndex: rawRowIndex, newDriver: rawNewDriver, loadId, oldDriver } = req.body;
		if (!rawNewDriver) {
			return res.status(400).json({ error: "rowIndex and newDriver required" });
		}
		// Row 1 is the header row — see resolveSheetDataRow() above.
		const rowIndex = resolveSheetDataRow(res, rawRowIndex);
		if (rowIndex === null) return; // 400 already sent

		// Normalize against users table (same pattern as /api/dispatch).
		const userMatch = db.prepare("SELECT driver_name FROM users WHERE LOWER(driver_name) = LOWER(?) AND role = 'Driver'").get(rawNewDriver.trim());
		const newDriver = userMatch ? userMatch.driver_name : rawNewDriver.trim();

		const sheets = await getSheets();
		// Headers, every row AND the target row in one round trip; RUNG 2 refuses
		// on a failed read. Same shape as POST /api/dispatch above.
		const snapshot = await readJobTrackingSnapshot(sheets, rowIndex);
		if (!snapshot) {
			return sendDispatchRefusal(
				req, res, { code: "PERIOD_UNRESOLVED", periods: [] },
				"reassign_blocked", loadId, `Reassigning load ${loadId || "(unknown)"} to ${newDriver}`
			);
		}
		const headers = snapshot.headers;

		// LOAD BINDING — before the period guard and every write, same reasoning
		// as POST /api/dispatch. On this route an unbound row moves the WHOLE
		// load's revenue to another investor (Owner ID) and its active-day pay to
		// another person (Driver), on a load nobody asked about.
		{
			const unbound = resolveLoadBinding(headers, snapshot.rows, rowIndex, loadId);
			if (unbound) {
				return sendLoadBindRefusal(
					req, res, unbound, "reassign_blocked", loadId,
					`reassigning row ${rowIndex} to ${newDriver}`
				);
			}
		}

		const driverCol = headers.findIndex((h) => /driver/i.test(h));
		if (driverCol === -1) {
			return res.status(400).json({ error: "Driver column not found" });
		}

		// Reassignment to a busy driver is allowed — the load queues behind
		// their current work as "Dispatched". The "one accept at a time" rule
		// for drivers is enforced at POST /api/driver/respond.

		// Look up new driver's truck + owner so we can re-stamp Truck and
		// Owner ID alongside the Driver cell. Without this, a load reassigned
		// from a company-truck driver (Owner ID = 0) to an investor's driver
		// keeps the stale 0, which blocks the driver-name fallback in
		// /api/investor (commit 656f1b1) and the load never appears in their
		// My Loads section. Same hardened lookup as /api/dispatch.
		let truckForDriver = db.prepare("SELECT unit_number, owner_id FROM trucks WHERE LOWER(assigned_driver) = LOWER(?)").get(newDriver.trim());
		if (!truckForDriver) {
			truckForDriver = db.prepare(
				"SELECT t.unit_number AS unit_number, t.owner_id AS owner_id " +
				"FROM truck_assignments ta JOIN trucks t ON t.id = ta.truck_id " +
				"WHERE LOWER(ta.driver_name) = LOWER(?) AND ta.end_date = '' " +
				"ORDER BY ta.start_date DESC LIMIT 1"
			).get(newDriver.trim());
		}
		const truckUnit = truckForDriver ? truckForDriver.unit_number : '';
		const ownerId = truckForDriver ? truckForDriver.owner_id : 0;

		// PERIOD GUARD — before the first write. This route writes NO status, so
		// it can never move a row across the completed boundary: its materiality
		// collapses to "is this row already completed?", which for a status-blind
		// write is the whole question. On a completed load in a settled month,
		// Driver moves that load's active-day pay to another person and Owner ID
		// moves its entire revenue to another investor — 356 production rows,
		// $296,350.93, some inside payouts already marked PAID. Written as the
		// before ∪ after union anyway, so it stays correct if this route ever
		// learns to write a status.
		{
			const before = sheetRowToObject(headers, snapshot.row);
			const edits = {};
			if (headers[driverCol]) edits[headers[driverCol]] = newDriver;
			const blocked = dispatchWriteBlocker(headers, before, edits);
			if (blocked) {
				return sendDispatchRefusal(
					req, res, blocked, "reassign_blocked", loadId,
					`Reassigning load ${loadId || "(unknown)"} to ${newDriver}`
				);
			}
		}

		// Ensure Truck and Owner ID columns exist (same approach as /api/dispatch).
		let truckColIdx = headers.findIndex(h => /^truck$/i.test(h));
		let ownerColIdx = headers.findIndex(h => /^owner.?id$/i.test(h));
		if (truckColIdx === -1 || ownerColIdx === -1) {
			const newHeaders = [];
			if (truckColIdx === -1) { newHeaders.push('Truck'); truckColIdx = headers.length + newHeaders.length - 1; }
			if (ownerColIdx === -1) { newHeaders.push('Owner ID'); ownerColIdx = headers.length + newHeaders.length - 1; }
			if (newHeaders.length) {
				await sheets.spreadsheets.values.update({
					spreadsheetId: SPREADSHEET_ID,
					range: `Job Tracking!${colLetter(headers.length)}1`,
					valueInputOption: "USER_ENTERED",
					requestBody: { values: [newHeaders] },
				});
				headers.push(...newHeaders);
			}
		}

		// Batch update: driver + truck + owner ID
		const updates = [
			{ range: `Job Tracking!${colLetter(driverCol)}${rowIndex}`, values: [[newDriver]] },
		];
		if (truckColIdx !== -1) updates.push({ range: `Job Tracking!${colLetter(truckColIdx)}${rowIndex}`, values: [[truckUnit]] });
		if (ownerColIdx !== -1) updates.push({ range: `Job Tracking!${colLetter(ownerColIdx)}${rowIndex}`, values: [[String(ownerId)]] });
		await sheets.spreadsheets.values.batchUpdate({
			spreadsheetId: SPREADSHEET_ID,
			requestBody: { valueInputOption: "USER_ENTERED", data: updates },
		});

		// Notify new driver
		insertNotification.run(
			newDriver.trim().toLowerCase(), 'load-assigned',
			`Load Reassigned: ${loadId || 'Load'}`,
			`Previously assigned to ${oldDriver || 'another driver'}`,
			JSON.stringify({ loadId, rowIndex })
		);
		// Always notify the new driver in real time (multi-load acceptance).
		io.to(newDriver.trim().toLowerCase()).emit("load-assigned", { loadId, rowIndex });

		// Notify old driver — also emit a socket event so their app
		// optimistically removes the ghost load instead of waiting for the
		// next manual refresh. Without this, the old driver's UI keeps the
		// load visible and they hit a confusing 403 when they try to act on it.
		if (oldDriver) {
			const oldDriverKey = oldDriver.trim().toLowerCase();
			const oldNotif = insertNotification.run(
				oldDriverKey, 'load-cancelled',
				`Load Removed: ${loadId || 'Load'}`,
				`Reassigned to ${newDriver}`,
				JSON.stringify({ loadId, rowIndex, reassignedTo: newDriver })
			);
			io.to(oldDriverKey).emit("load-cancelled", {
				loadId, rowIndex, reason: 'reassigned',
				notificationId: oldNotif.lastInsertRowid,
			});
		}

		// Notify dispatch team
		insertDispatchNotification.run(
			'load-reassigned',
			`Reassigned Load ${loadId || 'N/A'} to ${newDriver}`,
			`Previously ${oldDriver || 'unknown'}`,
			JSON.stringify({ loadId, newDriver, oldDriver, rowIndex })
		);
		io.to("dispatch").emit("dispatch-notification", {
			type: 'load-reassigned',
			title: `Reassigned Load ${loadId || 'N/A'} to ${newDriver}`,
			body: `Previously ${oldDriver || 'unknown'}`,
		});

		// Clear stale load_responses for new driver
		if (loadId && newDriver) {
			db.prepare("DELETE FROM load_responses WHERE load_id = ? AND driver_name = ?")
				.run(loadId, newDriver.trim().toLowerCase());
		}
		// This route wrote Driver, Truck and Owner ID with NO audit line at all —
		// the only trace was a dispatch notification, which is a feed item, not a
		// record. Refusals are now audited (see sendDispatchRefusal), and auditing
		// only the blocks would make the trail read as if reassignment never
		// succeeded.
		logAudit(req, 'reassign_load', 'load', loadId, `Reassigned load ${loadId} from ${oldDriver || 'unknown'} to ${newDriver} (truck ${truckUnit || 'none'}, owner ${ownerId})`);
		notifyChange("dashboard"); jtCacheInvalidate();
		res.json({ success: true });
	} catch (error) {
		console.error("Error reassigning load:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// POST /api/dispatch/cancel — Truly cancel a load. Status becomes "Cancelled"
// so it drops out of every KPI, list, and financial total. Super Admin only.
//
// Before 2026-04-20 this endpoint set status back to "Unassigned" and the row
// stayed on the job board. Per client feedback, that behaviour duplicated the
// Driver reassign dropdown (which already re-picks a driver without touching
// status). Now "Cancel" means what it says. If dispatch wants to swap drivers
// without cancelling, they still use the reassign dropdown.
app.post("/api/dispatch/cancel", requireRole("Super Admin"), async (req, res) => {
	try {
		// ⚠️ `driver` IS NO LONGER TAKEN FROM THE BODY. It is read off the bound row
		// instead — see the note beside `boundDriver` below. Not destructured at all,
		// so no later edit can quietly reach for the caller's version again.
		const { rowIndex: rawRowIndex, loadId } = req.body;
		// Row 1 is the header row — see resolveSheetDataRow() above. This was the
		// last route in the family still carrying the `if (!rowIndex)` shape PR #222
		// fixed on its three siblings; it was skipped there only to avoid colliding
		// with another agent, not because it was safe. `1` is truthy, so it passed —
		// and this route then writes `Job Status = "Cancelled"` and blanks `Driver`
		// on whatever row it was handed, re-pointing every findCol() regex in the app.
		//
		// That guard stops row 1. It does NOT stop row N: the load binding further
		// down is what stops the row being some OTHER live load — see
		// resolveLoadBinding().
		//
		// ⚠️ NO PERIOD GUARD HERE, DELIBERATELY, AND STILL NONE. #211 left cancel
		// unguarded because a broker calling off a July load in August is ordinary
		// business, and a guard that refuses ordinary work gets switched off. The
		// binding below is a different question — "is this the load you named?",
		// which has one right answer in every month — so it is not a period check
		// in disguise. Do not fold one in.
		const rowIndex = resolveSheetDataRow(res, rawRowIndex);
		if (rowIndex === null) return; // 400 already sent

		// A reason is MANDATORY. Cancelling drops the load from every KPI, wipes
		// the driver assignment and pushes "cancelled" to their phone — and on
		// 2026-08-05 a live $1,050 load was cancelled by mistake because the
		// confirm said only "Cancel this assignment?" with no load ID. The log
		// could then say who and when but never why. Same guard the payout
		// reopen uses: no reason, no state change.
		const cancelReason = String(req.body.reason || "").trim();
		if (cancelReason.length < 3) {
			return res.status(400).json({
				error: "A reason is required to cancel a load.",
				code: "CANCEL_REASON_REQUIRED",
			});
		}

		const sheets = await getSheets();
		// ⚠️ THIS ROUTE USED TO READ ONLY `Job Tracking!1:1` — the header row — and
		// then write to whatever row it was handed. It never checked that the row
		// carried the load it was about to audit, notify the driver about and
		// stamp onto load_status_history. See resolveLoadBinding() for why that is
		// the 2026-08-05 mis-cancel exactly, and why the mandatory reason above
		// makes an unbound cancel read as deliberate rather than as a mistake.
		const snapshot = await readJobTrackingSnapshot(sheets, rowIndex);
		if (!snapshot) {
			// The sheet could not be read, so the row cannot be confirmed to hold
			// this load. Refusing is the only answer that is not a guess — and
			// unlike a period check, retrying costs nothing once the read works.
			return sendLoadBindRefusal(
				req, res,
				{
					http: 503,
					code: "SHEET_UNREADABLE",
					error: "Job Tracking could not be read, so the server cannot confirm that this row holds the load you are cancelling. Nothing was changed. Try again in a moment.",
				},
				"cancel_blocked", loadId, `cancelling row ${rowIndex}`
			);
		}
		const headers = snapshot.headers;

		// LOAD BINDING — the row must actually hold this load before anything is
		// written, audited or pushed to the driver's phone.
		{
			const unbound = resolveLoadBinding(headers, snapshot.rows, rowIndex, loadId);
			if (unbound) {
				return sendLoadBindRefusal(
					req, res, unbound, "cancel_blocked", loadId,
					`cancelling row ${rowIndex}`
				);
			}
		}

		const driverColIdx = headers.findIndex((h) => /driver/i.test(h));
		const statusColIdx = headers.findIndex((h) => /status/i.test(h));

		// ⚠️ THE DRIVER COMES FROM THE BOUND ROW, NOT FROM req.body.driver. This
		// completes PR #248's own thesis: that PR made the ROW trustworthy, and this
		// is the one field that was still taken on the caller's word. Until now a
		// Super Admin could cancel load X on row N and push "Load Cancelled: X" to
		// ANY driver they named — someone with nothing to do with the load — while
		// `audit_trail`, the dispatch feed and the driver's own phone all agreed with
		// each other and with nothing on the sheet. It also cuts the ordinary-mistake
		// case: a stale board that names the previous driver of a reassigned load
		// notified the wrong person, which is the same 2026-08-05 shape (right
		// intent, wrong subject) one field further along.
		//
		// `snapshot.row` is the row at `rowIndex`, and resolveLoadBinding() has just
		// proved that row carries `loadId` — so this value is the driver the sheet
		// says is on the load being cancelled, and it is read BEFORE the write below
		// blanks the cell. A sheet cell is always a string, which also removes the
		// `.trim()`-on-a-non-string throw the body value carried. An unassigned load
		// yields "" and notifies nobody, exactly as an absent body field used to.
		const boundDriver = driverColIdx === -1 ? "" : String((snapshot.row || [])[driverColIdx] || "").trim();

		// Clear driver (no point keeping a driver on a cancelled load) and set
		// status to Cancelled so the load is excluded from every KPI loop.
		if (driverColIdx !== -1) {
			await sheets.spreadsheets.values.update({
				spreadsheetId: SPREADSHEET_ID,
				range: `Job Tracking!${colLetter(driverColIdx)}${rowIndex}`,
				valueInputOption: "USER_ENTERED",
				requestBody: { values: [[""]] },
			});
		}
		if (statusColIdx !== -1) {
			await sheets.spreadsheets.values.update({
				spreadsheetId: SPREADSHEET_ID,
				range: `Job Tracking!${colLetter(statusColIdx)}${rowIndex}`,
				valueInputOption: "USER_ENTERED",
				requestBody: { values: [["Cancelled"]] },
			});
		}
		recordStatusChange({ loadId, newStatus: 'Cancelled', source: 'cancel', actor: req.session?.user?.username || '', reason: cancelReason });
		logAudit(req, 'cancel_load', 'load', loadId, `Cancelled load ${loadId || 'N/A'}${boundDriver ? ` (driver: ${boundDriver})` : ''} — reason: ${cancelReason}`);

		// Notify driver — the one the SHEET says is on this load.
		if (boundDriver) {
			const cancelNotif = insertNotification.run(
				boundDriver.toLowerCase(), 'load-assigned',
				`Load Cancelled: ${loadId || 'Load'}`,
				`Cancelled by dispatch — ${cancelReason}`,
				JSON.stringify({ loadId, rowIndex, reason: cancelReason })
			);
			io.to(boundDriver.toLowerCase()).emit("load-cancelled", {
				loadId,
				rowIndex,
				notificationId: cancelNotif.lastInsertRowid,
			});
		}

		// Notify dispatch team
		insertDispatchNotification.run(
			'load-cancelled',
			`Cancelled Load ${loadId || 'N/A'}`,
			`Was assigned to ${boundDriver || 'unknown'} — ${cancelReason}`,
			JSON.stringify({ loadId, driver: boundDriver, rowIndex, reason: cancelReason })
		);
		io.to("dispatch").emit("dispatch-notification", {
			type: 'load-cancelled',
			title: `Cancelled Load ${loadId || 'N/A'}`,
			body: `Was assigned to ${boundDriver || 'unknown'} — ${cancelReason}`,
		});
		notifyChange("dashboard"); jtCacheInvalidate();
		res.json({ success: true });
	} catch (error) {
		console.error("Error cancelling load:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// Shared 409 for the two guards below. Kept in one place so a load delete and a
// driver-day override refuse in the same shape (`code` + `periods`), which is
// what lets one client-side handler render both.
// ⚠️ AUDITS BEFORE IT ANSWERS, like its two siblings above. `req` is first for
// the same reason: three of this helper's callers (the load delete and both
// driver-day override verbs) had no audit row of any kind on their refusal path,
// so an attempt to drop a load out of a settled month — or to put a $150 active
// day back into one — left nothing behind at all. The callers that DO record
// their own (sendDispatchRefusal, the status-override route) pass
// AUDITED_UPSTREAM so this cannot double-write.
//
// `kind` maps 1:1 onto the audited cause code, so the row and the response can
// never disagree about why the write was refused.
function sendPeriodRefusal(req, res, kind, periods, extra, audit) {
	const code = kind === "unreadable" ? "PERIOD_LOCK_UNREADABLE"
		: kind === "unresolved" ? "PERIOD_UNRESOLVED"
		: "PERIOD_FINALIZED";
	recordPeriodRefusal(
		audit === AUDITED_UPSTREAM ? audit : { req, ...(audit || {}) },
		code, periods || [], extra
	);
	if (kind === "unreadable") {
		return res.status(409).json({
			error: "The period lock table could not be read, so no month can be confirmed open. This change is held until that is fixed. It is a database fault, not the close window — waiting will not clear it.",
			code: "PERIOD_LOCK_UNREADABLE",
		});
	}
	if (kind === "unresolved") {
		return res.status(409).json({
			error: `${extra || "This change"} cannot be attributed to an accounting month, so the server cannot tell whether it lands in a closed one. Correct the dates on the row (or retry if the sheet was briefly unreadable) and try again.`,
			code: "PERIOD_UNRESOLVED",
		});
	}
	const named = (periods || []).map(periodLabel).join(", ");
	return res.status(409).json({
		error: `${extra || "This change"} would restate ${named} — ${periods.length === 1 ? "a month that is" : "months that are"} already finalized, with the statement published against ${periods.length === 1 ? "it" : "them"}. Reopen the period first (POST /api/periods/:period/reopen records a reason), or leave the figures as settled.`,
		code: "PERIOD_FINALIZED",
		periods,
	});
}

// DELETE /api/loads/:loadId — Soft-delete a load. Row stays in the Google
// Sheet for audit / external integrations; admin views and every KPI loop
// filter it out via excludeDroppedLoads(). Super Admin only. Reversible
// via `DELETE FROM deleted_loads WHERE load_id = ?` in SQL.
//
// ⚠️ PERIOD-GUARDED (added after PR #205's user-delete guard, same reasoning).
// "Reversible" is not the same as "harmless": dropping the load out of
// excludeDroppedLoads() removes its revenue AND its driver-pay active days from
// whatever month it books in, and while reconcileInvestorPayouts() freezes the
// headline `amount` of a locked period, the BASIS is recomputed live everywhere
// else — /api/financials, the payout waterfall drill-down, `recomputedAmount`
// (the drift figure printed beside the frozen one) and page 1 of the statement
// PDF. Reopening a period also re-links an `owed` row to live earnings, so a
// month reopened after such a delete settles at a different number with nothing
// recording why. Measured on production 2026-08-08: 381 of 391 live loads sit in
// a locked month, $313,922.93 of completed revenue, and the single largest
// (load 553198052, $4,800, 2026-05) sits in a month already marked PAID.
//
// Ungated on PERIOD_FINALIZE_ENABLED, like every other lock guard: with the flag
// off period_locks is empty, isLocked() is false for everything, and this costs
// one indexed SELECT.
app.delete("/api/loads/:loadId", requireRole("Super Admin"), async (req, res) => {
	try {
		const rawId = (req.params.loadId || "").trim();
		if (!rawId || !/^[A-Za-z0-9\-_.#]{1,40}$/.test(rawId)) {
			return res.status(400).json({ error: "Invalid load id" });
		}
		const lid = rawId.toLowerCase().replace(/^#/, "");

		// Fail CLOSED before anything else: isLocked() swallows every error and
		// answers "not locked", so an unreadable period_locks would leave the guard
		// present, silent and open.
		// ⚠️ THE MOST DESTRUCTIVE LOAD ACTION IN THE APP, and until now only its
		// SUCCESS was recorded. `delete_load` has been audited since it removes a
		// load from every KPI; a refused delete wrote nothing, so audit_trail could
		// not tell "nobody tried to drop that load out of May" from "someone tried
		// repeatedly and the close window refused them". entity/entity_id mirror the
		// `delete_load` success line — the load id, which is what the delete is
		// keyed on. The raw id is used rather than the lowercased `lid` so the row
		// records what the caller actually sent.
		const loadDelAudit = {
			action: "delete_load_blocked", entity: "load", entityId: rawId,
			subject: `soft-delete load ${rawId}`,
		};
		if (!periodLocksReadable()) return sendPeriodRefusal(req, res, "unreadable", null, null, loadDelAudit);

		// ONE sheet read serves both the guard and the audit row index. It used to
		// be wrapped in a bare `catch {}` so a Sheets hiccup merely cost the row
		// index; now the months depend on it, so a failed read has to refuse — the
		// months are exactly what cannot be guessed at.
		let jobTracking;
		try {
			jobTracking = await getJobTrackingCached();
		} catch (e) {
			console.error("Load delete blocked — Job Tracking unreadable:", e.message);
			return sendPeriodRefusal(req, res, "unresolved", null, `Load ${rawId}`, loadDelAudit);
		}

		const cols = jobTrackingMonthCols(jobTracking.headers);
		// EVERY row carrying this load id, not just the first: the delete is keyed
		// on load_id, so it drops all of them and the guard has to answer for all
		// of them. Matched with the same `#`-stripped lowercasing the delete uses.
		const matches = cols.loadIdCol
			? jobTracking.data.filter((r) => (r[cols.loadIdCol] || "").toString().trim().toLowerCase().replace(/^#/, "") === lid)
			: [];

		if (matches.length) {
			const periods = new Set();
			let allResolved = true;
			for (const row of matches) {
				const p = loadRowPeriods(row, cols);
				if (!p.resolved) allResolved = false;
				p.periods.forEach((m) => periods.add(m));
			}
			// A row whose dates are unreadable could be booked anywhere, including a
			// closed month. Refuse rather than guess — the same asymmetry as
			// everywhere else: refusing costs a reopen, permitting costs a restated
			// settlement nobody can see happen.
			if (!allResolved) return sendPeriodRefusal(req, res, "unresolved", null, `Load ${rawId}`, loadDelAudit);
			const locked = lockedAmong([...periods]);
			if (locked.length) {
				// SPANNING AN OPEN AND A CLOSED MONTH → refuse, never partially allow.
				// A scoped delete is not representable: `deleted_loads` is keyed on
				// load_id alone and excludeDroppedLoads() is the single source of truth
				// for "is this load live?" across dashboard / financials / investor. A
				// period-scoped exclusion would fork that predicate — the one thing
				// CLAUDE.md explicitly protects — so the closed month would be spared at
				// the cost of the three surfaces disagreeing about the same load. And
				// per the month-mapping note above, spanning can ONLY happen when the
				// assigned date is unparseable, which the check above already refused.
				return sendPeriodRefusal(req, res, "finalized", locked, `Deleting load ${rawId}`, loadDelAudit);
			}
		}
		// matches.length === 0 is deliberately allowed, and it is not a fail-open:
		// the sheet read SUCCEEDED and positively showed no such row, so the insert
		// excludes nothing and moves no month. Only an unreadable sheet refuses.

		// Best-effort row index for the audit record. A mismatch is fine — the
		// Google Sheet row can shift later, but the load_id stays authoritative.
		const rowIndex = (matches[0] && matches[0]._rowIndex) || 0;

		const deletedBy = req.session.user.username || req.session.user.full_name || "";
		db.prepare("INSERT INTO deleted_loads (load_id, row_index, deleted_by) VALUES (?, ?, ?)").run(lid, rowIndex, deletedBy);

		// The most destructive load action in the app previously left NO audit row —
		// only a dispatch notification, which is a feed item that ages out, not a
		// record. `cancel_load` has been audited since the 2026-08-05 wrong-load
		// incident; this is the same class of act (it removes a load from every KPI)
		// and now leaves the same trace, including the months it was cleared against.
		const auditedPeriods = matches.length
			? [...new Set(matches.flatMap((r) => loadRowPeriods(r, cols).periods))].sort().join(", ")
			: "";
		logAudit(req, "delete_load", "load", lid,
			`Soft-deleted load ${rawId}${rowIndex ? ` (sheet row ${rowIndex})` : ""}${matches.length ? ` — settlement month${auditedPeriods.includes(",") ? "s" : ""} ${auditedPeriods}` : " — no matching Job Tracking row"}. Reversible: DELETE FROM deleted_loads WHERE load_id = '${lid}'`);

		insertDispatchNotification.run(
			"load-deleted",
			`Deleted Load ${rawId}`,
			`Removed by ${deletedBy || "admin"}`,
			JSON.stringify({ loadId: rawId, deletedBy, rowIndex }),
		);
		io.to("dispatch").emit("dispatch-notification", {
			type: "load-deleted",
			title: `Deleted Load ${rawId}`,
			body: `Removed by ${deletedBy || "admin"}`,
		});
		notifyChange("dashboard");
		jtCacheInvalidate();
		res.json({ success: true });
	} catch (error) {
		console.error("Error deleting load:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// WHICH settlement months does one (driver, date, action) override move?
//
// ⚠️ NOT simply the month the date falls in — that answer is right for `add` and
// wrong for `remove`, which is the more common of the two.
//   • 'add' credits a day the ELD missed, and the pay loop buckets an added day
//     by `d.slice(0,7)` unconditionally (it is tied to no load). So: the date's
//     own month, full stop.
//   • 'remove' drops the day out of the counted set of every load whose window
//     covers it — and those days are bucketed by the LOAD'S ASSIGNED month. So
//     excluding 2026-08-01 on a load assigned in July moves JULY, and excluding
//     2026-07-31 on a load assigned in August moves AUGUST. The date's own month
//     can be neither of them.
// Hence the sheet read: the covering loads are the only place the answer lives.
//
// ⚠️ THE DATE'S OWN MONTH IS ADDED TO THE COVERING LOADS' MONTHS, NEVER
// DISPLACED BY THEM. This tail used to read
//
//     return months.size ? [...months].sort() : [own];   // `own` DISPLACED
//
// i.e. `own` survived only while NO covering load existed, and the moment one
// did the day's own month dropped out of the answer entirely. That is a
// fail-OPEN, and the only one of its kind at this gate: unlike the sibling
// guards, excludedDayGate() has no `unresolved` rung to catch it — a month that
// is not in this array is simply never offered to isLocked(), so a co-covering
// load in an OPEN month silently suppresses a LOCKED one and the write goes
// through and restates it.
//
// The `[own]` fallback was never merely cosmetic: `own` is the bucket the day
// takes the moment a load with no readable assigned date covers it (see
// loadRowPeriods — that is the one path by which days fall back to their own
// calendar months). Reported by PR #245's security review as M-1, because #245
// is what made the bad state REACHABLE: a row with an unreadable assigned date
// plus a pickup only moneySheetDate() can read now yields a counted pay day on
// the money side while loadWindowDays() still returns [] for the guard. Before
// #245 such a row's window was empty and it contributed nothing.
//
// Not reachable on today's data — 0 of 421 raw production rows have an
// unreadable assigned date — so this is the cheap moment to close it. Measured
// read-only on production (2026-08-09, 421 raw → 305 deduped rows, 354
// (driver, date) pairs): 40 pairs report MORE months, 0 report fewer, and the
// gate's refuse/allow verdict flips on 0 — 0 new refusals and 0 new permits.
// 18 of the 40 were already being refused and now name more months in the 409.
// The union direction is fail-CLOSED by construction, not just by measurement:
// the array's only consumer re-filters it through lockedAmong(), so a month
// this adds can only ever produce a refusal that isLocked() independently
// justifies. It can never permit a write the narrower set refused.
//
// Covering loads are matched regardless of STATUS, unlike the pay loop, which
// counts completed ones only. Status is mutable and the override row is not, so
// a load one status change away from counting would otherwise be one status
// change away from silently restating a closed month.
function excludedDayPeriods({ driver, date, action, jobTracking }) {
	// ⚠️ `own` is deliberately NOT run through LOCKABLE_MONTH_KEY, because
	// filtering it would DROP it from the array, which is a PERMIT. The producers
	// below need the test because they build their keys from arbitrary sheet cells;
	// this one must refuse instead of filter.
	//
	// ⚠️ AND `own` IS NOT SELF-EVIDENTLY MATCHABLE — an earlier revision of this
	// comment asserted that it always is ("route-validated /^\d{4}-\d{2}-\d{2}$/,
	// so this is always a matchable key already"), and that was FALSE for months
	// 13-99: `2026-13-01` satisfies that regex, slices to `2026-13`, and no lock row
	// can ever equal it — so the month would resolve, match nothing, and be waved
	// through as open. It is now excludedDayGate() that makes the claim true, by
	// refusing an unresolvable date outright before it reaches here. Both callers go
	// through that gate, so the invariant holds for the sheet-supplied `remove` path
	// and the stored-date DELETE path alike. Do not restore the "the route already
	// checked" reasoning: the route checks the SHAPE, and the shape is not the month.
	const own = String(date || "").slice(0, 7);
	if (action === "add" || !jobTracking) return [own];
	const cols = jobTrackingMonthCols(jobTracking.headers);
	if (!cols.driverCol) return [own];
	const months = new Set();
	for (const row of jobTracking.data) {
		if (normalizeDriverName(row[cols.driverCol]) !== driver) continue;
		if (!loadWindowDays(row, cols).includes(date)) continue;
		loadRowPeriods(row, cols).periods.forEach((m) => months.add(m));
	}
	// UNION, not displacement — see the ⚠️ above. With no covering load this is
	// still exactly [own], so the no-load case is byte-identical to before.
	return [...new Set([...months, own])].sort();
}

// The gate itself: `{ refuse: 'unreadable'|'unresolved'|'finalized'|null, periods }`.
// Fails closed on an unreadable lock table and on an unreadable sheet, for the
// same reason as the load delete — the months are exactly what cannot be guessed.
async function excludedDayGate({ driver, date, action }) {
	// ⚠️ FAIL CLOSED ON A DATE THAT NAMES NO REAL MONTH, and REFUSE rather than
	// filter. `2026-13-01` passes a bare shape test, slices to `2026-13`, and no
	// period_locks row can ever carry that key — so without this the gate resolves
	// a month, finds no lock, and PERMITS the write. Same trap
	// invoiceMonthLockBlockers() range-checks against, and the same reason its
	// unresolved rung exists.
	//
	// ⚠️ IT LIVES HERE, NOT IN excludedDayPeriods(), and not as a filter. Removing
	// the month from the array is the fail-OPEN that PR #249 reverted: a reader that
	// admits less than period_locks can hold silently discards a genuinely locked
	// month and turns a refusal into a permit. Refusing the whole request cannot do
	// that.
	//
	// Both entry points are covered on purpose. POST validates the caller's date and
	// 400s first, so it never arrives here malformed; DELETE passes a STORED
	// `excluded_date` it did not validate, which is the row that would otherwise
	// carry a pre-validation typo straight past the guard.
	const dateStr = String(date || "");
	if (!/^\d{4}-\d{2}-\d{2}$/.test(dateStr) || !Number.isFinite(Date.parse(`${dateStr}T00:00:00Z`))) {
		return { refuse: "unresolved", periods: [] };
	}
	if (!periodLocksReadable()) return { refuse: "unreadable", periods: [] };
	let jobTracking = null;
	// An 'add' is bucketed by its own date and needs no sheet, so it is not made
	// to depend on Sheets being up. Only 'remove' has to find its covering loads.
	if (action !== "add") {
		try {
			jobTracking = await getJobTrackingCached();
		} catch (e) {
			console.error("Driver-day override blocked — Job Tracking unreadable:", e.message);
			return { refuse: "unresolved", periods: [] };
		}
	}
	const periods = excludedDayPeriods({ driver, date, action, jobTracking });
	const locked = lockedAmong(periods);
	return locked.length ? { refuse: "finalized", periods: locked } : { refuse: null, periods };
}

// POST /api/admin/excluded-days — Super Admin manually overrides a (driver, date)
// in the active-day count. Two override types share this endpoint via `action`:
//   - 'remove' (default): drop a day the ELD over-counted (parked-but-creeping
//     ping, midnight-boundary quirk, stale window).
//   - 'add': credit a day the driver worked but the ELD missed (truck offline,
//     vehicle not yet linked, gap in the feed).
// /api/investor, /api/financials, and /api/invoices/generate all consult this
// table, so an override moves in lockstep across the investor view, company
// P&L, and weekly invoice PDF.
//
// ⚠️ PERIOD-GUARDED — see excludedDayPeriods() above for WHICH month an override
// actually moves, which is not the month the date is in.
app.post("/api/admin/excluded-days", requireRole("Super Admin"), async (req, res) => {
	try {
		const driverNameRaw = (req.body && req.body.driverName) || "";
		const date = (req.body && req.body.date) || "";
		const reason = ((req.body && req.body.reason) || "").toString().trim().slice(0, 500);
		const actionRaw = ((req.body && req.body.action) || "remove").toString().toLowerCase();
		const action = actionRaw === "add" ? "add" : "remove";
		const driver = normalizeDriverName(driverNameRaw);
		if (!driver) return res.status(400).json({ error: "Missing driverName" });
		// ⚠️ A CALENDAR CHECK, NOT ONLY A SHAPE ONE. The shape test alone accepts
		// `2026-13-01`, which excludedDayPeriods() slices to `2026-13` — a key no lock
		// row can ever equal — so the month resolved, matched nothing, and the write
		// was PERMITTED into what may well be a closed period. Same `Date.parse`
		// round-trip POST /api/expenses uses on the same kind of value, so the two
		// routes agree about what a date is. excludedDayGate() repeats it as the
		// fail-closed backstop for the stored-date DELETE path; this one is here so a
		// caller's typo is a legible 400 rather than a 409 about a month.
		if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !Number.isFinite(Date.parse(`${date}T00:00:00Z`))) {
			return res.status(400).json({ error: "Invalid date — must be a real calendar date in YYYY-MM-DD form" });
		}

		// Guard BEFORE the insert. There are no transactions here, so a refusal
		// discovered after the write is not a refusal.
		const gate = await excludedDayGate({ driver, date, action });
		// entity/entity_id mirror the `add_driver_day` / `exclude_driver_day` success
		// lines exactly — `driver_active_day` keyed `${driver}:${date}` — so one query
		// returns both the overrides that landed on a day and the ones refused. The
		// action name follows the `remove` default, matching this route's own naming.
		// The caller's `reason` is carried because on an override it is the entire
		// justification for moving a day of pay, and on a refusal it is the record of
		// what someone believed they were correcting in a settled month.
		if (gate.refuse) return sendPeriodRefusal(req, res, gate.refuse, gate.periods,
			`${action === "add" ? "Crediting" : "Excluding"} ${date} for ${driverNameRaw || driver}`,
			{
				action: action === "add" ? "add_driver_day_blocked" : "exclude_driver_day_blocked",
				entity: "driver_active_day", entityId: `${driver}:${date}`,
				subject: `${action === "add" ? "credit" : "exclude"} ${date} for ${driverNameRaw || driver}`,
				note: reason,
			});

		const excludedBy = req.session.user.username || req.session.user.full_name || "";
		const result = db.prepare(
			"INSERT OR IGNORE INTO excluded_driver_days (driver_name, excluded_date, reason, excluded_by, action) VALUES (?, ?, ?, ?, ?)"
		).run(driver, date, reason, excludedBy, action);
		const auditAction = action === "add" ? "add_driver_day" : "exclude_driver_day";
		logAudit(req, auditAction, "driver_active_day", `${driver}:${date}`, reason || `${action === "add" ? "Added" : "Excluded"} by ${excludedBy}`);
		jtCacheInvalidate();
		const row = db.prepare(
			"SELECT id, driver_name, excluded_date, reason, excluded_by, strftime('%Y-%m-%dT%H:%M:%SZ', excluded_at) AS excluded_at, COALESCE(action, 'remove') AS action FROM excluded_driver_days WHERE driver_name = ? AND excluded_date = ?"
		).get(driver, date);
		res.json({ success: true, inserted: result.changes > 0, row });
	} catch (error) {
		console.error("Error overriding driver day:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// DELETE /api/admin/excluded-days/:id — Super Admin restores a previously
// overridden day. Works for both 'remove' and 'add' overrides — dropping the
// row reverts the active-day count to whatever ELD+loads compute on their own.
//
// ⚠️ PERIOD-GUARDED, and this direction is the one that bites in practice: both
// override rows on production today target 2026-05-15/16, a month that is locked
// AND whose payout is marked PAID. Restoring either puts a $150 active day back
// into a settled month.
app.delete("/api/admin/excluded-days/:id", requireRole("Super Admin"), async (req, res) => {
	try {
		const id = parseInt(req.params.id, 10);
		if (!Number.isFinite(id) || id <= 0) return res.status(400).json({ error: "Invalid id" });
		const row = db.prepare(
			"SELECT id, driver_name, excluded_date, reason, COALESCE(action, 'remove') AS action FROM excluded_driver_days WHERE id = ?"
		).get(id);
		if (!row) return res.status(404).json({ error: "Not found" });

		// Undoing an override moves exactly the months applying it moved — the day
		// goes back where it was — so the same predicate answers both directions.
		const gate = await excludedDayGate({
			driver: normalizeDriverName(row.driver_name),
			date: (row.excluded_date || "").trim(),
			action: row.action,
		});
		// ⚠️ THE DIRECTION THAT BITES IN PRACTICE — both override rows on production
		// target a month that is locked AND already PAID, so restoring either puts a
		// $150 active day back into a settled month. Mirrors the
		// `restore_driver_day` / `restore_added_driver_day` success lines. The stored
		// reason is carried: it is the justification for the override being undone,
		// and after a successful delete the row is gone, so on a refusal this is the
		// only place it survives.
		if (gate.refuse) return sendPeriodRefusal(req, res, gate.refuse, gate.periods,
			`Restoring ${row.excluded_date} for ${row.driver_name}`,
			{
				action: row.action === "add" ? "restore_added_driver_day_blocked" : "restore_driver_day_blocked",
				entity: "driver_active_day", entityId: `${row.driver_name}:${row.excluded_date}`,
				subject: `restore ${row.excluded_date} for ${row.driver_name} (undo '${row.action}' override #${id})`,
				note: row.reason,
			});

		db.prepare("DELETE FROM excluded_driver_days WHERE id = ?").run(id);
		const auditAction = row.action === "add" ? "restore_added_driver_day" : "restore_driver_day";
		logAudit(req, auditAction, "driver_active_day", `${row.driver_name}:${row.excluded_date}`, row.reason || "");
		jtCacheInvalidate();
		res.json({ success: true });
	} catch (error) {
		console.error("Error restoring driver day:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// GET /api/admin/driver-day-overrides — Super Admin only. Powers the dedicated
// /admin/driver-pay-overrides admin page. Returns every override row in one
// payload plus a `drivers` list (union of drivers_directory + currently-
// assigned truck drivers) for the page's driver dropdown — saves a second
// round-trip and keeps the page self-contained.
app.get("/api/admin/driver-day-overrides", requireRole("Super Admin"), (req, res) => {
	try {
		const overrides = db.prepare(
			"SELECT id, driver_name, excluded_date, reason, excluded_by, strftime('%Y-%m-%dT%H:%M:%SZ', excluded_at) AS excluded_at, COALESCE(action, 'remove') AS action FROM excluded_driver_days ORDER BY excluded_date DESC, id DESC"
		).all();
		// Driver universe = anyone in drivers_directory OR currently assigned to
		// a truck. Some drivers exist in only one or the other depending on how
		// they were onboarded, so union both. Lowercase-deduped, original case
		// preserved when available.
		const seen = new Map(); // lc → display
		try {
			db.prepare("SELECT driver_name FROM drivers_directory WHERE driver_name IS NOT NULL AND driver_name != ''")
				.all().forEach(r => {
					const lc = (r.driver_name || "").trim().toLowerCase();
					if (lc && !seen.has(lc)) seen.set(lc, r.driver_name.trim());
				});
		} catch {}
		try {
			db.prepare("SELECT DISTINCT assigned_driver FROM trucks WHERE assigned_driver IS NOT NULL AND assigned_driver != ''")
				.all().forEach(r => {
					const lc = (r.assigned_driver || "").trim().toLowerCase();
					if (lc && !seen.has(lc)) seen.set(lc, r.assigned_driver.trim());
				});
		} catch {}
		const drivers = [...seen.values()].sort((a, b) => a.localeCompare(b));
		// Closed months, so the page can say so BEFORE an admin clicks. Without
		// this the only signal is the 409, i.e. the guard is discovered by tripping
		// it. Sent as a plain list of 'YYYY-MM'; `lockReadable:false` means "cannot
		// tell", which the UI must render as an unknown rather than as "all open" —
		// the server would refuse every write in that state.
		let lockedPeriods = [];
		const lockReadable = periodLocksReadable();
		if (lockReadable) {
			try {
				lockedPeriods = db.prepare("SELECT period FROM period_locks WHERE status = 'locked' ORDER BY period").all().map((r) => r.period);
			} catch { lockedPeriods = []; }
		}
		res.json({ overrides, drivers, lockedPeriods, lockReadable });
	} catch (error) {
		console.error("Error listing driver day overrides:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// Per-IP throttle for driver write paths. Sized for one human driver hitting
// these from a phone — a normal shift sees < 60 status/respond/message/expense
// writes per minute. The Sheets API ceiling is 300 req/min for the whole
// fleet, so a runaway client could drain the quota for everyone without this.
// Location pings get a tighter limit since the client already self-throttles
// to one per ~30s; anything above 12/min is misbehaving.
const driverWriteLimiter = rateLimit({
	windowMs: 60 * 1000,
	max: 60,
	message: { error: "Too many requests. Please slow down." },
	standardHeaders: true,
	legacyHeaders: false,
});
const locationLimiter = rateLimit({
	windowMs: 60 * 1000,
	max: 12,
	message: { error: "Too many location updates." },
	standardHeaders: true,
	legacyHeaders: false,
});

// POST /api/driver/respond — Driver accepts or declines a load assignment
app.post("/api/driver/respond", requireAuth, driverWriteLimiter, async (req, res) => {
	try {
		const { loadId, rowIndex: rawRowIndex, response } = req.body;
		const driverName = resolveDriverActor(req, res, req.body.driverName);
		if (driverName === null) return; // 401/403 already sent
		if (!loadId || !response || !driverName) {
			return res.status(400).json({ error: "loadId, rowIndex, response, and driverName required" });
		}
		// Row 1 is the header row — see resolveSheetDataRow() above. This route is
		// the Driver-reachable one: loadBelongsToDriver() below scopes `loadId`,
		// but `rowIndex` is independent of it and lands straight in an A1 range,
		// so without this a driver could rewrite the header row of the whole app.
		const rowIndex = resolveSheetDataRow(res, rawRowIndex);
		if (rowIndex === null) return; // 400 already sent
		if (!["accepted", "declined"].includes(response)) {
			return res.status(400).json({ error: "response must be 'accepted' or 'declined'" });
		}
		// SECURITY: drivers can only respond to loads currently assigned to them
		if (req.session.user.role === "Driver") {
			const owned = await loadBelongsToDriver(loadId, driverName);
			if (!owned) return res.status(403).json({ error: "This load is not assigned to you" });
		}

		// Check for duplicate response (scoped to load_id + driver + rowIndex)
		const existing = db.prepare(
			`SELECT id, response FROM load_responses WHERE load_id = ? AND driver_name = ? AND row_index = ? ORDER BY responded_at DESC LIMIT 1`
		).get(loadId, driverName.trim().toLowerCase(), rowIndex);
		if (existing && existing.response === response && response === "accepted") {
			return res.status(409).json({ error: "You have already accepted this load" });
		}

		const sheets = await getSheets();

		// ONE read serves the binding, the period guard and both write branches
		// below. It used to be three separate reads of `Job Tracking!1:1` on top of
		// the guard's own, and headers resolved separately per branch can drift
		// from the headers the guard judged.
		const snapshot = await readJobTrackingSnapshot(sheets, rowIndex);
		if (!snapshot) {
			return sendDispatchRefusal(
				req, res, { code: "PERIOD_UNRESOLVED", periods: [] },
				"driver_respond_blocked", loadId, `Recording "${response}" on load ${loadId || "(unknown)"}`
			);
		}
		const headers = snapshot.headers;

		// LOAD BINDING — before the period guard and before the load_responses
		// insert. loadBelongsToDriver() above scopes `loadId`, but `rowIndex` is an
		// INDEPENDENT field: a driver who genuinely owns load X could send X with
		// any row number and land the decline's `Driver = ""` / `Job Status =
		// "Unassigned"` on a stranger's live load. Ownership of the id is not
		// ownership of the row, so the two have to be tied together.
		{
			const unbound = resolveLoadBinding(headers, snapshot.rows, rowIndex, loadId);
			if (unbound) {
				return sendLoadBindRefusal(
					req, res, unbound, "driver_respond_blocked", loadId,
					`recording "${response}" on row ${rowIndex}`
				);
			}
		}

		// PERIOD GUARD — before the first write of either kind, including the
		// load_responses row below. Included with its three siblings because a
		// DECLINE writes Driver = "" and Job Status = "Unassigned": on a completed
		// load in a settled month that erases the load's revenue AND its
		// driver-pay days, which is the same accounting event PUT
		// /api/driver/status is guarded against three routes down. Leaving it out
		// would make that guard decorative — the same Driver could reach the same
		// cells by declining instead. An ACCEPT writes "Assigned", which is not a
		// completed status, so ordinary acceptance is unaffected in any month.
		{
			const before = sheetRowToObject(headers, snapshot.row);
			const sIdx = headers.findIndex((h) => /status/i.test(h));
			const dIdx = headers.findIndex((h) => /^driver$/i.test(h));
			const edits = {};
			if (sIdx !== -1 && headers[sIdx]) edits[headers[sIdx]] = response === "accepted" ? "Assigned" : "Unassigned";
			if (response !== "accepted" && dIdx !== -1 && headers[dIdx]) edits[headers[dIdx]] = "";
			const blocked = dispatchWriteBlocker(headers, before, edits);
			if (blocked) {
				return sendDispatchRefusal(
					req, res, blocked, "driver_respond_blocked", loadId,
					`Recording "${response}" on load ${loadId || "(unknown)"}`
				);
			}
		}

		// Insert response
		insertLoadResponse.run(loadId, rowIndex, driverName.trim().toLowerCase(), response);

		const now = new Date();
		const logId = `LOG-${now.getTime()}`;
		// Houston wall-clock, NOT server-local: this box runs UTC, so the old
		// getter-based build stamped evening deliveries with tomorrow's date.
		// See houstonStamp() — the date part here decides revenue month,
		// invoice week, and driver-pay day.
		const dateTime = houstonStamp(now);

		if (response === "accepted") {
			// Update Job Status to "Assigned" in the sheet, using the SAME headers
			// the binding and the period guard were judged against.
			//
			// ⚠️ colLetter(), not String.fromCharCode(65 + idx), which this branch
			// used: that expression is only correct for the first 26 columns and
			// emits `[`, `\`, `]` past column Z, so on a wider sheet it would build
			// a malformed A1 range. Job Tracking is 26 columns wide today, i.e. it
			// is one added column away from being wrong.
			const statusColIdx2 = headers.findIndex((h) => /status/i.test(h));
			if (statusColIdx2 !== -1) {
				// colLetter(), not String.fromCharCode(65 + idx) — the latter emits "["
				// at index 26 and silently writes to a garbage range on any sheet wider
				// than Z. Job Tracking is 26 columns today, i.e. exactly one column
				// away. The DECLINE branch of this same handler (below) was already
				// converted; this accept branch was missed, so one if/else disagreed
				// with itself.
				await sheets.spreadsheets.values.update({
					spreadsheetId: SPREADSHEET_ID,
					range: `Job Tracking!${colLetter(statusColIdx2)}${rowIndex}`,
					valueInputOption: "USER_ENTERED",
					requestBody: { values: [["Assigned"]] },
				});
			}
			recordStatusChange({ loadId, oldStatus: 'Dispatched', newStatus: 'Assigned', source: 'accept', actor: driverName });

			// Notify dispatch
			insertDispatchNotification.run(
				'load-accepted',
				`${driverName} accepted Load ${loadId}`,
				`Driver confirmed assignment`,
				JSON.stringify({ loadId, driverName, rowIndex })
			);
			io.to("dispatch").emit("load-accepted", { loadId, driverName, rowIndex });
			io.to("dispatch").emit("dispatch-notification", {
				type: 'load-accepted',
				title: `${driverName} accepted Load ${loadId}`,
				body: `Driver confirmed assignment`,
			});
		} else {
			// Decline: clear driver and set Unassigned — again off the SAME headers
			// the binding and the period guard used, so the cells written are the
			// cells that were judged.
			const driverColIdx = headers.findIndex((h) => /^driver$/i.test(h));
			const statusColIdx = headers.findIndex((h) => /status/i.test(h));

			if (driverColIdx !== -1) {
				await sheets.spreadsheets.values.update({
					spreadsheetId: SPREADSHEET_ID,
					range: `Job Tracking!${colLetter(driverColIdx)}${rowIndex}`,
					valueInputOption: "USER_ENTERED",
					requestBody: { values: [[""]] },
				});
			}
			if (statusColIdx !== -1) {
				await sheets.spreadsheets.values.update({
					spreadsheetId: SPREADSHEET_ID,
					range: `Job Tracking!${colLetter(statusColIdx)}${rowIndex}`,
					valueInputOption: "USER_ENTERED",
					requestBody: { values: [["Unassigned"]] },
				});
			}
			recordStatusChange({ loadId, newStatus: 'Unassigned', source: 'decline', actor: driverName });

			// Notify dispatch
			insertDispatchNotification.run(
				'load-declined',
				`${driverName} declined Load ${loadId}`,
				`Load returned to Job Board`,
				JSON.stringify({ loadId, driverName, rowIndex })
			);
			io.to("dispatch").emit("load-declined", { loadId, driverName, rowIndex });
			io.to("dispatch").emit("dispatch-notification", {
				type: 'load-declined',
				title: `${driverName} declined Load ${loadId}`,
				body: `Load returned to Job Board`,
			});
		}

		// Both branches mutated the Job Tracking sheet — bust the 60s cache so the
		// driver's immediate loadData() refetch sees the new status instead of
		// the pre-accept "Dispatched"/pre-decline assignment.
		jtCacheInvalidate();

		res.json({ success: true, response });
	} catch (error) {
		console.error("Error responding to load:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// DELETE — Clear a row (shifts content up by deleting the row) — Admin only
//
// Guarded and audited by the shared helpers beside POST /api/admin/remove-rows —
// read the block comment there for what a deleted Job Tracking row actually
// costs and why each check exists. This is the single-row twin of that route and
// applies the identical rules; the only difference is that with one row there is
// nothing to skip, so a blocked row is a 409 rather than a skip-and-report.
//
// `reason` is accepted from the JSON body or from `?reason=`. A DELETE body is
// legal and express.json() parses it, but it is easy to lose through a proxy or
// a client that strips it, so the query form is there as well.
app.delete("/api/data/:rowIndex", requireRole("Super Admin"), async (req, res) => {
	try {
		const sheetName = getSheetName(req);
		// Number(), not parseInt(): parseInt("2abc") is 2 and parseInt("2.9") is 2,
		// so a malformed index would silently delete a real row.
		const rowIndex = Number(String(req.params.rowIndex).trim());
		const reason = String((req.body && req.body.reason) || req.query.reason || "").trim();

		if (!Number.isInteger(rowIndex) || rowIndex < 2) {
			return res.status(400).json({
				error: rowIndex === 1
					? "Row 1 is the header row — deleting it re-points every column lookup in the app at the wrong data."
					: "rowIndex must be an integer of 2 or more (row 1 is the header row).",
				code: rowIndex === 1 ? "HEADER_ROW_PROTECTED" : "INVALID_ROW_INDEX",
			});
		}
		if (reason.length < SHEET_ROW_DELETE_REASON_MIN || reason.length > SHEET_ROW_REASON_MAX) {
			return res.status(400).json({
				error: `A reason of ${SHEET_ROW_DELETE_REASON_MIN}-${SHEET_ROW_REASON_MAX} characters is required — it is written to the audit trail beside the deleted contents.`,
				code: "DELETE_REASON_REQUIRED",
			});
		}

		const sheets = await getSheets();
		const sheetId = await getSheetId(sheets, sheetName);
		// An unresolved tab name leaves the GridRange with no sheetId, which is
		// gid 0 — a different tab entirely. See gap 1 beside remove-rows.
		if (!Number.isInteger(sheetId)) {
			return res.status(400).json({
				error: `No tab named "${sheetName}" exists in this spreadsheet. Tab names are matched exactly, including case and spacing.`,
				code: "UNKNOWN_SHEET",
			});
		}

		// Read the row BEFORE deleting it — this is both the audit snapshot and the
		// basis for the month check. Fail closed if it cannot be read: the audit
		// line is the only record that survives the delete.
		const quoted = `'${String(sheetName).replace(/'/g, "''")}'`;
		let headers = [];
		let row = [];
		try {
			const snap = await sheets.spreadsheets.values.batchGet({
				spreadsheetId: SPREADSHEET_ID,
				ranges: [`${quoted}!1:1`, `${quoted}!${rowIndex}:${rowIndex}`],
			});
			const ranges = snap.data.valueRanges || [];
			headers = (ranges[0] && ranges[0].values && ranges[0].values[0]) || [];
			row = (ranges[1] && ranges[1].values && ranges[1].values[0]) || [];
		} catch (err) {
			console.error("Delete row: could not read the row before deleting:", err.message);
			return res.status(409).json({
				error: "The row could not be read before deleting, so nothing was removed — a delete that cannot be recorded is not performed.",
				code: "ROW_READ_FAILED",
			});
		}
		// A read that returns no HEADER row is a degraded read, not an empty sheet —
		// and without headers no column can be identified, so no month can be
		// resolved and sheetRowIsEmpty() would wave every row through. See the ⚠️ on
		// sheetRowIsEmpty.
		if (!headers.length) {
			return res.status(409).json({
				error: "The sheet read returned no header row, so nothing was removed — the row contents could not be recorded and no month could be checked.",
				code: "ROW_READ_FAILED",
			});
		}

		const guarded = await isPeriodGuardedGid(sheets, sheetId);
		const blocker = sheetRowDeleteBlocker(guarded, headers, row);
		if (blocker) {
			// The single-row twin of POST /api/admin/remove-rows, and it had the same
			// gap: `delete_sheet_row` and `delete_sheet_row_failed` were both audited
			// while the refusal wrote nothing. `blocker.code` is passed through rather
			// than assumed — sheetRowDeleteBlocker() answers PERIOD_FINALIZED or
			// PERIOD_UNRESOLVED, and which one it was is the difference between "reopen
			// the month" and "fix the date on the row". entity/entity_id mirror the
			// success line's `${sheetName}!${rowIndex}` address.
			recordPeriodRefusal({
				req, action: "delete_sheet_row_blocked", entity: "sheet_row",
				entityId: `${sheetName}!${rowIndex}`,
				subject: `delete row ${rowIndex} of ${sheetName}`,
				note: reason,
			}, blocker.code, blocker.periods || []);
			return res.status(409).json({ error: blocker.error, code: blocker.code, periods: blocker.periods });
		}

		const auditDetails = (outcome, extra) => buildSheetDeleteAudit({
			outcome,
			sheet: sheetName,
			reason,
			requested: [rowIndex],
			deletedRowIndices: [rowIndex],
			rows: [{ rowIndex, cells: sheetRowSnapshot(headers, row) }],
			...extra,
		});

		try {
			// Delete the entire row so remaining rows shift up
			await sheets.spreadsheets.batchUpdate({
				spreadsheetId: SPREADSHEET_ID,
				requestBody: {
					requests: [
						{
							deleteDimension: {
								range: {
									sheetId: sheetId,
									dimension: "ROWS",
									startIndex: rowIndex - 1, // 0-indexed
									endIndex: rowIndex,
								},
							},
						},
					],
				},
			});
		} catch (err) {
			// ⚠️ Audit the failed attempt too — a Sheets write is a POST and is
			// deliberately not retried on timeout, so a timeout leaves it genuinely
			// unknown whether the row is gone. See the same note in remove-rows.
			logAudit(req, "delete_sheet_row_failed", "sheet_row", `${sheetName}!${rowIndex}`, auditDetails("failed", { error: err.message }));
			throw err;
		}

		logAudit(req, "delete_sheet_row", "sheet_row", `${sheetName}!${rowIndex}`, auditDetails("deleted"));
		// The 60s Job Tracking cache would otherwise keep serving the deleted row.
		if (guarded) jtCacheInvalidate();

		res.json({ success: true });
	} catch (error) {
		console.error("Error deleting row:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// ============================================================
// DASHBOARD — Aggregated data from multiple sheets
// ============================================================
app.get("/api/dashboard", requireRole("Super Admin", "Dispatcher"), async (req, res) => {
	try {
		// Use shared 60s Job Tracking cache (invalidated by mutations) instead of
		// hitting Sheets on every dashboard load.
		const jobTracking = await getJobTrackingCached();
		// Filter out soft-deleted + cancelled loads BEFORE any aggregation so every
		// downstream KPI, list, and revenue total sees the same consistent view.
		jobTracking.data = excludeDroppedLoads(jobTracking.data, jobTracking.headers);
		const carrierDB = getCarrierDBFromSQLite();

		// Identify key columns
		const statusCol = findCol(jobTracking.headers, /status/i);
		const driverCol = findCol(jobTracking.headers, /driver/i);
		const loadIdCol = findCol(jobTracking.headers, /load.?id|job.?id/i);
		const delivDateCol = findCol(
			jobTracking.headers,
			/deliv|drop.?off.*date|completion.*date/i,
		);
		const jtPayCol = findCol(jobTracking.headers, /payment|rate|amount|pay/i);
		const carrierDriverCol =
			findCol(carrierDB.headers, /driver/i) || carrierDB.headers[0];
		const truckCol = findCol(carrierDB.headers, /truck|unit|vehicle/i);

		// Status patterns
		// "heading to shipper" added 2026-05-07 — was missed when the status was
		// introduced on 2026-05-05; loads in that status had been falling through
		// all three buckets (Active / Unassigned / Completed) and silently
		// disappearing from the dashboard until the geofence flipped them.
		const activeStatuses =
			/^(heading to shipper|in transit|dispatched|assigned|picked up|at shipper|at receiver|loading|unloading)$/i;
		const completedStatuses = /^(delivered|completed|pod received)$/i;
		const canceledStatuses = /^(cancel|canceled|cancelled)$/i;
		const unassignedStatuses =
			/^(unassigned|new|open|pending|available)$/i;

		// Filter jobs — only rows with a Load ID
		const hasLoadId = (r) => loadIdCol ? !!(r[loadIdCol] || "").trim() : true;
		const activeJobs = jobTracking.data.filter(
			(r) => hasLoadId(r) && statusCol && activeStatuses.test((r[statusCol] || "").trim()),
		);
		const unassignedJobs = jobTracking.data.filter((r) => {
			if (!hasLoadId(r)) return false;
			const status = statusCol ? (r[statusCol] || "").trim() : "";
			if (activeStatuses.test(status) || completedStatuses.test(status) || canceledStatuses.test(status)) return false;
			return unassignedStatuses.test(status) || !status;
		});
		const completedJobs = jobTracking.data.filter(
			(r) =>
				hasLoadId(r) &&
				statusCol &&
				completedStatuses.test((r[statusCol] || "").trim()),
		);

		// Sort completed jobs by most recent first
		const sortDateCol = findCol(jobTracking.headers, /completion.*date|status.*update.*date|drop.?off.*date|assigned.*date/i);
		if (sortDateCol) {
			completedJobs.sort((a, b) => {
				const da = new Date((a[sortDateCol] || '').replace(/^Date:\s*/i, '').trim());
				const db2 = new Date((b[sortDateCol] || '').replace(/^Date:\s*/i, '').trim());
				const ta = isNaN(da) ? 0 : da.getTime();
				const tb = isNaN(db2) ? 0 : db2.getTime();
				return tb - ta;
			});
		}

		// Date boundaries
		const now = new Date();
		// NOTE: this week is MONDAY-based, which is NOT the Sat-Fri LogisX invoice
		// week (see getWeekRange). Pre-existing and deliberately left alone here —
		// "completed this week" is a dashboard glance, not a payroll figure.
		const weekStart = new Date(now);
		weekStart.setDate(
			now.getDate() - now.getDay() + (now.getDay() === 0 ? -6 : 1),
		);
		weekStart.setHours(0, 0, 0, 0);
		// Month boundary on the HOUSTON calendar, not the server's. This was
		// new Date(now.getFullYear(), now.getMonth(), 1), and those getters are
		// server-local — UTC on the VPS. So for the last 5-6 hours of every month
		// (from 19:00 CDT / 18:00 CST on the final day) the dashboard had already
		// rolled to the NEXT month and showed 0 completed, while /api/investor and
		// /api/financials — which key off houstonDay() — were still counting the
		// month the owner was actually still working. Same basis, same numbers.
		const [hYear, hMonth] = houstonDay(now).slice(0, 7).split("-").map(Number);
		const monthStart = new Date(hYear, hMonth - 1, 1);

		const completedThisWeek = completedJobs.filter((r) => {
			if (!delivDateCol) return false;
			const d = new Date(r[delivDateCol]);
			return !isNaN(d) && d >= weekStart && d <= now;
		}).length;

		const completedThisMonth = completedJobs.filter((r) => {
			if (!delivDateCol) return false;
			const d = new Date(r[delivDateCol]);
			return !isNaN(d) && d >= monthStart && d <= now;
		}).length;

		// Fleet utilization — mirror the /trucks page: total = every truck in the
		// fleet (all statuses), assigned = any truck with a driver. Previous logic
		// excluded Inactive/OOS trucks and conflated drivers_directory rows with
		// trucks, producing "0/0" when the real fleet had Inactive rows.
		const totalTrucks = db.prepare("SELECT COUNT(*) AS cnt FROM trucks").get().cnt;
		const assignedTrucks = db.prepare(
			"SELECT COUNT(*) AS cnt FROM trucks WHERE TRIM(assigned_driver) != ''"
		).get().cnt;

		// Revenue
		function parseAmount(str) {
			return (
				parseFloat(String(str || "0").replace(/[$,]/g, "")) || 0
			);
		}
		// Revenue — only count rows that map to one of the three dashboard
		// buckets (completed, active, unassigned/empty). Canceled and
		// uncategorized rows (status matches none of the four regexes) are
		// excluded from all three totals so the cards match the breakdown
		// modal content exactly.
		let revTotal = 0,
			revPaid = 0,
			revPending = 0;
		jobTracking.data.filter(hasLoadId).forEach((r) => {
			const amt = parseAmount(jtPayCol ? r[jtPayCol] : 0);
			if (!amt) return;
			const status = statusCol ? (r[statusCol] || "").trim() : "";
			if (completedStatuses.test(status)) {
				revTotal += amt;
				revPaid += amt;
			} else if (activeStatuses.test(status) || unassignedStatuses.test(status) || !status) {
				revTotal += amt;
				revPending += amt;
			}
		});

		// Driver list for dispatch dropdown — only active drivers (pending = awaiting drug test, inactive = disabled)
		const driverMap = new Map();
		carrierDB.data.forEach((r) => {
			const name = (r[carrierDriverCol] || "").trim();
			const status = (r["Status"] || "active").toLowerCase();
			if (name && status === "active" && !driverMap.has(name.toLowerCase())) driverMap.set(name.toLowerCase(), name);
		});
		const driverList = [...driverMap.values()].sort();

		// Per-driver FIFO queue map — keyed by normalized driver name. Same
		// helper feeds the driver app so the queue position labels agree across
		// both surfaces.
		const driverQueues = computeDriverQueues(jobTracking.data, jobTracking.headers);

		// Fleet details. "On Load" should only fire when the driver is actually
		// mid-trip (heading-to-shipper..unloading); a driver whose only loads are
		// Dispatched (queued, unaccepted) or Assigned (accepted, not started) is
		// "Queued" — distinguish them in the fleet pill so dispatchers see the
		// difference between "Howard is driving" and "Howard has work waiting."
		const inProgressRe = /^(heading to shipper|at shipper|loading|in transit|at receiver|unloading)$/i;
		const statusColIdx = jobTracking.headers.findIndex((h) => /status/i.test(h));
		const fleet = carrierDB.data.map((r) => {
			const name = (r[carrierDriverCol] || "").trim();
			const nameNorm = normalizeDriverName(name);
			// In-progression load only — excludes Dispatched and Assigned. Used
			// to decide the "On Load" pill and the CurrentLoad ID surfacing.
			const inProgressLoad = statusColIdx === -1 ? null : activeJobs.find(
				(j) => driverCol && normalizeDriverName(j[driverCol]) === nameNorm
					&& inProgressRe.test((j[statusColIdx] || "").toString().trim()),
			);
			const phoneCol = findCol(carrierDB.headers, /phone|contact/i);
			const queue = driverQueues[nameNorm] || [];
			// Status:
			//   "On Load"   — in-progression load active
			//   "Queued"    — no in-progression, but has Dispatched or Assigned waiting
			//   "Available" — neither
			let status;
			if (inProgressLoad) status = "On Load";
			else if (queue.length > 0) status = "Queued";
			else status = "Available";
			return {
				Driver: name,
				Truck: truckCol ? r[truckCol] || "" : "",
				Phone: phoneCol ? r[phoneCol] || "" : "",
				Status: status,
				CurrentLoad: inProgressLoad
					? loadIdCol
						? inProgressLoad[loadIdCol]
						: ""
					: "",
				QueueCount: queue.length,
				QueuedLoadIds: queue.map((q) => q.load_id),
				CompletedLoads: completedJobs.filter((j) => {
					return driverCol && normalizeDriverName(j[driverCol]) === nameNorm;
				}).length,
			};
		});

		// Pre-resolve origin/destination address columns so we can enrich every
		// job row with plain "City, ST ZIP" strings that the new Pickup/Drop-off
		// table columns render. Deshorn asked for this 2026-04-20 because the
		// raw "Pickup Info" sheet column carries broker-facing references like
		// "Brothers WMS RDC - MPS REF/PU#: 29284990" that are useless for
		// scanning the dispatch board.
		const originAddrCol = pickAddressColumn(jobTracking.headers, /origin|pickup|shipper/i);
		const destAddrCol = pickAddressColumn(jobTracking.headers, /dest|drop|receiver|delivery/i);
		function enrichLocations(rows) {
			for (const r of rows) {
				const lid = loadIdCol ? r[loadIdCol] : "";
				const pu = resolveAddressParts(r, "pickup", lid, originAddrCol ? r[originAddrCol] : "");
				const dr = resolveAddressParts(r, "drop", lid, destAddrCol ? r[destAddrCol] : "");
				r._pickupLocation = pu.cityStateZip;  // city/state/zip — unchanged contract
				r._pickupStreet = pu.street;           // line 1 (street); "" when none
				r._dropLocation = dr.cityStateZip;
				r._dropStreet = dr.street;
			}
			return rows;
		}
		enrichLocations(unassignedJobs);
		enrichLocations(activeJobs);
		enrichLocations(completedJobs);

		// Sanitize broker contact data for non-Admin roles
		const respUnassigned = req.session.user.role !== "Super Admin"
			? sanitizeBrokerColumns(jobTracking.headers, unassignedJobs)
			: unassignedJobs;
		const respActive = req.session.user.role !== "Super Admin"
			? sanitizeBrokerColumns(jobTracking.headers, activeJobs)
			: activeJobs;
		const respCompleted = req.session.user.role !== "Super Admin"
			? sanitizeBrokerColumns(jobTracking.headers, completedJobs)
			: completedJobs;

		res.json({
			timestamp: new Date().toISOString(),
			kpis: {
				activeLoads: activeJobs.length,
				unassignedLoads: unassignedJobs.length,
				completedThisWeek,
				completedThisMonth,
				fleetUtilization: { assigned: assignedTrucks, total: totalTrucks },
				revenue: {
					total: Math.round(revTotal * 100) / 100,
					paid: Math.round(revPaid * 100) / 100,
					pending: Math.round(revPending * 100) / 100,
				},
			},
			unassignedJobs: respUnassigned,
			jobTrackingHeaders: jobTracking.headers,
			completedHeaders: jobTracking.headers,
			activeJobs: respActive,
			completedJobs: respCompleted,
			fleet,
			drivers: driverList,
			driverQueues,
		});
	} catch (error) {
		console.error("Error building dashboard:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// ============================================================
// DRIVER APP — Endpoints for the mobile driver application
// ============================================================

// Helper: parse sheet rows into { headers, data } with _rowIndex
function parseSheet(valueRange) {
	const rows = (valueRange && valueRange.values) || [];
	if (rows.length === 0) return { headers: [], data: [] };
	const headers = rows[0];
	const data = rows.slice(1).map((row, idx) => {
		const obj = { _rowIndex: idx + 2 };
		headers.forEach((h, i) => {
			obj[h] = row[i] || "";
		});
		return obj;
	});
	return { headers, data };
}

// Status hierarchy for smart deduplication (higher = more advanced)
const STATUS_RANK = {
	'': 0, unassigned: 1, dispatched: 2, assigned: 3, 'at shipper': 4,
	loading: 5, 'in transit': 6, unloading: 7, 'at receiver': 8,
	delivered: 9, 'pod received': 10, completed: 11,
};

// Helper: remove duplicate load IDs, keeping the row with the most advanced status
function deduplicateLoads(data, headers, returnDuplicates = false) {
	const loadIdCol = headers.find((h) => /load.?id|job.?id/i.test(h));
	if (!loadIdCol) return returnDuplicates ? { data, duplicates: [] } : data;
	// Track last (most recent) index per load ID — bottom row wins
	const lastIndex = new Map();
	for (let i = 0; i < data.length; i++) {
		const lid = (data[i][loadIdCol] || "").trim().toLowerCase().replace(/^#/, "");
		if (!lid) continue;
		lastIndex.set(lid, i); // overwrite keeps the last occurrence
	}
	const keepSet = new Set(lastIndex.values());
	const duplicates = [];
	const filtered = [];
	for (let i = 0; i < data.length; i++) {
		const lid = (data[i][loadIdCol] || "").trim().toLowerCase().replace(/^#/, "");
		if (!lid) { filtered.push(data[i]); continue; }
		if (keepSet.has(i)) filtered.push(data[i]);
		else duplicates.push(data[i]);
	}
	if (!returnDuplicates) return filtered;
	return { data: filtered, duplicates };
}

function sanitizeBrokerContact(value) {
	if (!value || typeof value !== "string") return value;
	const trimmed = value.trim();
	if (!trimmed.startsWith("{")) return value;
	try {
		const parsed = JSON.parse(trimmed);
		return JSON.stringify({ Name: parsed.Name || parsed.name || "" });
	} catch {
		return value;
	}
}

// ---------------------------------------------------------------------------
// The broker-contact columns a non-Super-Admin must not receive in full.
//
// ⚠️ THIS IS A UNION RESOLVED BY NAME, NEVER `headers.find(...)`. The previous
// version picked ONE column per role with two loose regexes:
//
//     const brokerCol = headers.find((h) => /broker/i.test(h));
//     const phoneCol  = headers.find((h) => /phone|contact/i.test(h));
//
// and against production's real 26-column Job Tracking header row —
// … "Broker Contact Name", "Phone Number", "Email" … — `/phone|contact/i`
// matched "Broker **Contact** Name" FIRST, because it sorts before "Phone
// Number". So both lookups resolved to the SAME column, and the function did the
// exact inverse of its job:
//   • the name column was blanked (it is not JSON, so it took the else branch),
//   • and "Phone Number" and "Email" were never referenced by any lookup at all,
//     so they were served IN FULL to every non-Super-Admin caller.
// The harmless column was redacted and the two it exists to protect were
// published. This is the same class of bug as the `pickAddressColumn` note
// below, where a naive `headers.find(/pickup/i)` grabbed a broker-reference
// column instead of the address — first-regex-wins over a 26-column sheet.
//
// The fix is a UNION: every matching column is withheld, so no column can be
// shadowed by an earlier one. That makes the set a strict SUPERSET of what the
// old code redacted on any sheet, i.e. this change can only ever narrow what is
// served — it cannot widen it. `/contact/i` is deliberately kept for that
// reason (a "Contact Number" column on some other sheet was redacted before and
// still is); it is simply no longer allowed to *shadow* the phone column.
//
// DELIBERATE, not accidental: "Broker Contact Name" IS withheld. It was blanked
// only by the bug above, but that is what every non-Super-Admin sees today, so
// keeping it withheld makes this change strictly narrowing — no UI that already
// copes with an empty cell regresses, and no new disclosure ships inside a leak
// fix. It is also the coherent line: the control exists so dispatch cannot route
// around the company to the broker, and a named agent at a known brokerage is a
// directly actionable contact, so publishing the person while hiding the channel
// is a weak boundary. Revealing it to Dispatchers is a product decision and
// belongs in its own change, with the owner.
//
// ⚠️ `Contract ID`, `"  Payment  "` (real surrounding spaces) and `Owner ID`
// match nothing here and are untouched — verified against the header row above.
//
// ⚠️ ONE SOURCE FOR READER AND WRITER. PUT /api/data/:rowIndex splices the real
// values back in so a non-Super-Admin's save cannot overwrite the full record
// with the redacted copy they were served. That path used its own hardcoded
// `/broker|phone|contact/i`, which does NOT match "Email" — so widening the
// redaction without it would have turned a disclosure bug into DATA LOSS: a
// Dispatcher saving a row would write "" over the stored email. Both sides now
// call this resolver.
// ---------------------------------------------------------------------------
const BROKER_WITHHELD_RE = /broker|phone|e-?mail|contact|\bfax\b|mobile|\bcell\b/i;
function resolveBrokerWithheldColumns(headers) {
	return (headers || []).filter((h) => BROKER_WITHHELD_RE.test(String(h == null ? "" : h)));
}

function sanitizeBrokerColumns(headers, rows) {
	const withheld = resolveBrokerWithheldColumns(headers);
	if (!withheld.length) return rows;
	return rows.map((row) => {
		const cleaned = { ...row };
		for (const col of withheld) {
			if (!cleaned[col]) continue;
			const val = String(cleaned[col]).trim();
			// A legacy cell carrying a JSON contact blob degrades to just the
			// name rather than vanishing — blanking it outright would destroy
			// the load's broker association wholesale. Production's Job Tracking
			// carries no such cell (the name column holds a plain string), so
			// this branch is compatibility for older/other sheets and is left
			// exactly as it behaved before.
			cleaned[col] = val.startsWith("{") ? sanitizeBrokerContact(val) : "";
		}
		return cleaned;
	});
}

function findCol(headers, regex) {
	return headers.find((h) => regex.test(h)) || null;
}

// Pick the sheet column that holds a side's REAL address, not the broker-reference /
// company-info column that sorts before it. The Job Tracking sheet carries BOTH
// "Pickup Company Information" (broker refs like "... REF/PU#: 29284990") AND
// "Pickup Address", info first — so a naive headers.find(/pickup/i) grabbed the ref column
// and leaked it into the Pickup/Drop-off cells. Prefer an explicit "* Address" header; else
// fall back to the looser side match but skip info / reference / appointment columns.
// sideRe selects the side (e.g. /origin|pickup|shipper/i). Returns null when nothing matches —
// every caller already treats null/"" as "no source" and renders "—".
function pickAddressColumn(headers, sideRe) {
	const notMeta = (h) => !/lat|lng|lon|date|time|appt|eta/i.test(h);
	return (headers || []).find((h) => sideRe.test(h) && /address/i.test(h) && notMeta(h))
		|| (headers || []).find((h) => sideRe.test(h) && notMeta(h) && !/info|reference|appointment/i.test(h))
		|| null;
}

// Normalize a driver name for comparison. Lowercases, trims, AND collapses
// internal whitespace. Use this any time a driver name read from the Job
// Tracking sheet is being matched against a session/user driverName — exact
// equality silently dropped real loads when older sheet rows had typo'd
// double-spaces (see invoice generator regression May 2026).
function normalizeDriverName(s) {
	return (s || "").trim().toLowerCase().replace(/\s+/g, " ");
}

// SECURITY: enforce that a Driver-role user is acting only on their own
// account. Super Admin / Dispatcher can act on behalf of any driver (they
// need to for dispatch operations), but a Driver MUST be the one named in
// the request. Returns the resolved driverName string, or null after sending
// the appropriate 401/403 response. Always check `=== null` and early-return.
function resolveDriverActor(req, res, bodyDriverName) {
	const user = req.session?.user;
	if (!user) {
		res.status(401).json({ error: "Not authenticated" });
		return null;
	}
	if (user.role === "Driver") {
		const sessionName = (user.driverName || "").trim();
		if (!sessionName) {
			res.status(403).json({ error: "Driver session has no name" });
			return null;
		}
		const requested = (bodyDriverName || "").trim();
		if (requested && normalizeDriverName(requested) !== normalizeDriverName(sessionName)) {
			res.status(403).json({ error: "Drivers can only act on their own account" });
			return null;
		}
		return sessionName;
	}
	return (bodyDriverName || "").trim();
}

// SECURITY: verify that a Job Tracking load is currently assigned to the
// given driver (case + whitespace tolerant). Used by driver-side write paths
// (status update, POD upload, GPS ping) to reject spoofed rowIndex/loadId.
// Uses the cached sheet so it does not add a Sheets API call per request.
async function loadBelongsToDriver(loadId, driverName) {
	if (!loadId || !driverName) return false;
	const target = normalizeDriverName(driverName);
	const targetLid = String(loadId).trim().toLowerCase().replace(/^#/, "");
	// Soft-deleted loads are not assignable. A driver who cached the loadId
	// before admin removed the load can otherwise still drive status mutations
	// against the sheet row, which would re-surface the load in admin lists.
	if (getDeletedLoadIds().has(targetLid)) return false;
	let jt;
	try { jt = await getJobTrackingCached(); } catch { return false; }
	const headers = jt.headers || [];
	const driverCol = findCol(headers, /driver/i);
	const loadIdCol = findCol(headers, /load.?id|job.?id/i);
	if (!driverCol || !loadIdCol) return false;
	for (const row of jt.data || []) {
		const lid = String(row[loadIdCol] || "").trim().toLowerCase().replace(/^#/, "");
		if (lid !== targetLid) continue;
		if (normalizeDriverName(row[driverCol]) === target) return true;
	}
	return false;
}

// Load-drop filtering — single source of truth for "this load should not
// appear in any admin list or KPI". Combines two exclusion reasons:
//   1. Status is Cancelled (set by POST /api/dispatch/cancel)
//   2. The load_id was soft-deleted (row in deleted_loads)
// Used by /api/dashboard, /api/financials, /api/investor, and /api/public/track
// so every surface stays consistent.
const CANCELED_STATUS_RE = /^(cancel|canceled|cancelled)$/i;
function getDeletedLoadIds() {
	try {
		const rows = db.prepare("SELECT load_id FROM deleted_loads").all();
		return new Set(rows.map((r) => (r.load_id || "").toString().trim().toLowerCase()));
	} catch {
		return new Set();
	}
}
function excludeDroppedLoads(rows, headers, deletedIds) {
	if (!Array.isArray(rows) || rows.length === 0) return rows || [];
	const loadIdCol = findCol(headers || [], /load.?id|job.?id/i);
	const statusCol = findCol(headers || [], /^(job[\s._-]?)?status$/i) || findCol(headers || [], /status/i);
	const ids = deletedIds instanceof Set ? deletedIds : getDeletedLoadIds();
	return rows.filter((r) => {
		const lid = loadIdCol ? (r[loadIdCol] || "").toString().trim().toLowerCase() : "";
		if (lid && ids.has(lid)) return false;
		const st = statusCol ? (r[statusCol] || "").toString().trim() : "";
		if (CANCELED_STATUS_RE.test(st)) return false;
		return true;
	});
}

// Returns { normalizedDriverName: { remove: Set<"YYYY-MM-DD">, add: Set<"YYYY-MM-DD"> } }
// for every admin override. Consumed by /api/investor, /api/financials, and
// /api/invoices/generate so a Super-Admin override drops or adds the day
// across the investor view, company P&L, and weekly invoice together.
// `remove` strips a day from the computed active-day set; `add` credits a day
// the ELD missed (truck offline / lost feed).
function getAllExcludedDriverDays() {
	const map = {};
	try {
		db.prepare("SELECT driver_name, excluded_date, COALESCE(action, 'remove') AS action FROM excluded_driver_days").all().forEach((r) => {
			const dn = (r.driver_name || "").trim();
			const dt = (r.excluded_date || "").trim();
			if (!dn || !dt) return;
			if (!map[dn]) map[dn] = { remove: new Set(), add: new Set() };
			if (r.action === "add") map[dn].add.add(dt);
			else map[dn].remove.add(dt);
		});
	} catch { /* table missing on first boot — fall through */ }
	return map;
}

// ---------------------------------------------------------------------------
// WHICH MONTHS DOES A LOAD (OR A DRIVER-DAY OVERRIDE) ACTUALLY MOVE?
//
// Both mechanisms below — the load soft-delete and the excluded/added-day
// override — silently restate a month's settlement, so both need a period-lock
// guard. A guard is only as good as its month mapping, and the mapping here is
// NOT the obvious one. Getting it wrong is worse than having no guard: it would
// refuse the deletes that are safe and wave through the ones that are not.
//
// The rule the money math actually uses (GET /api/investor, GET /api/financials
// and the payouts drill-down are all identical here, deliberately):
//   • REVENUE counts in the month the load was ASSIGNED, not delivered. That is
//     a deliberate choice to match the dashboard, and it is why "it delivered in
//     August" tells you nothing about which month a load books in.
//   • DRIVER PAY counts active days = a completed load's pickup→delivery window
//     ∩ ELD travel — and each of those days is then bucketed by
//     `assignedMonthKey || day.slice(0,7)`, i.e. it lands in the load's ASSIGNED
//     month too, NOT in the month the day physically falls in.
// So for a load with a readable assigned date, revenue and driver pay agree and
// the load touches exactly ONE month. A load can reach TWO months only when its
// assigned date cannot be parsed, at which point the days fall back to their own
// calendar months and a window straddling a month boundary splits. Measured on
// production 2026-08-08: 0 of 391 live loads are in that state. The two-month
// case is therefore not a workflow being blocked — it IS the unreadable-data
// case, which fails closed anyway.
//
// ⚠️ The three helpers below are a deliberate copy of the ones inlined in the
// /api/investor and /api/financials handlers, which live inside those closures
// and cannot be called from here. The copy is the point: a guard that expanded
// dates its own way would answer for a different month than the SUM it is
// protecting — the same failure the truckChargeFromMonth note in
// userDeleteLockBlockers() describes. If the rule ever changes, every copy
// changes together or this guard silently drifts off the money it is guarding.
//
// The money handlers' own `parseSheetDate` copies are GONE (they now read every
// date through the shared moneySheetDate()), so jtParseSheetDate has exactly one
// surviving caller: the NARROW leg of loadWindowDays() below, which is kept
// deliberately — see the union note there. It is no longer a mirror of anything
// in the money math and must not be re-adopted as one.
function jtParseSheetDate(val) {
	if (!val) return null;
	const s = String(val).trim();
	// ISO first — the US M/D/Y regex below would mis-read "2026-05-13".
	const iso = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
	if (iso) {
		const d = new Date(parseInt(iso[1]), parseInt(iso[2]) - 1, parseInt(iso[3]));
		return isNaN(d) ? null : d;
	}
	const m = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})/);
	if (!m) return null;
	let yr = parseInt(m[3]);
	if (yr < 100) yr += 2000;
	const d = new Date(yr, parseInt(m[1]) - 1, parseInt(m[2]));
	return isNaN(d) ? null : d;
}
function jtFmtDate(d) {
	return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0");
}
function jtExpandDateRange(start, end) {
	const dates = [];
	const s = new Date(start); s.setHours(12, 0, 0, 0);
	const e = end ? new Date(end) : new Date(start);
	e.setHours(12, 0, 0, 0);
	if (e < s) return [jtFmtDate(s)];
	const MAX_SPAN = 31 * 24 * 3600 * 1000; // same runaway guard as the pay loop
	if (e - s > MAX_SPAN) e.setTime(s.getTime() + MAX_SPAN);
	const cur = new Date(s);
	while (cur <= e) { dates.push(jtFmtDate(cur)); cur.setDate(cur.getDate() + 1); }
	return dates;
}

// The same column regexes the money endpoints resolve, in the same order.
// `dateCol` in particular MUST keep the status-update/completion/assigned
// alternation ahead of the bare /date/i fallback: on the production sheet the
// header order is [20] Assigned Date, [21] Status Update Date, [22] Completion
// Date and headers.find() returns the FIRST match — so this resolves to
// "Assigned Date", which is what puts revenue in the assigned month.
function jobTrackingMonthCols(headers) {
	const h = headers || [];
	return {
		loadIdCol: findCol(h, /load.?id|job.?id/i),
		dateCol: findCol(h, /status.*update.*date|completion.*date|assigned.*date/i) || findCol(h, /date/i),
		driverCol: findCol(h, /^driver$/i),
		pickupDateCol: findCol(h, /pickup.*appo|pickup.*date/i),
		dropoffDateCol: findCol(h, /drop.?off.*appo|drop.?off.*date|delivery.*date/i),
	};
}

// The load's assigned month, or "" when the cell cannot be read as a date.
//
// ⚠️ CALLS THE MONEY MATH'S OWN RESOLVER, moneySheetDate(), AND MUST KEEP DOING
// SO. This guard returns a SINGLE month (loadRowPeriods wraps it as `[assigned]`,
// not a union), so any disagreement with the P&L is a one-sided hole rather than
// an extra refusal: resolve MAY here while the revenue books APRIL, with April
// locked and May open, and the guard clears a delete out of a closed period.
// It previously inlined `jtParseSheetDate(v) || new Date(v)` — a verbatim copy of
// what the money math read at the time, and load-bearing for the same reason it
// is now a shared call: production carries assigned dates like
// "Date: Tue, 1 Jul 2025 11:33:05 -0500" that the strict parser rejects. When
// that expression was replaced on 2026-08-08 (see moneySheetDate) this had to
// move with it, in the same commit. Sharing the function is what makes drifting
// apart impossible; do not re-inline a copy.
//
// ⚠️ A MONTH KEY THAT IS NOT A MONTH IS A PERMIT, NOT A REFUSAL — hence the
// shape test below. lockedAmong() filters candidates through this same regex and
// SILENTLY DROPS anything else, so a key like "275760-" or "999-01-" leaves it
// nothing to match, `locked.length` is 0, and every guard clears the write —
// while `resolved` still says true, so the `unresolved` rung never fires either.
// Both month-key sites — here and loadRowPeriods()'s window leg — build the key
// the same way, and that is where it comes from: jtFmtDate() writes the year
// unpadded and unbounded, so for any Date whose year is not exactly 4 digits
// the .slice(0, 7) cuts in the wrong place.
//
// It is plantable through moneySheetDate's normal branches, not just exotica.
// Probed 2026-08-09: the `new Date()` tail reads "Sat Sep 13 275760",
// "10000-01-01" and "September 13, 275760"; the ISO branch reads "0999-01-01"
// (parseInt drops the pad → year 999); and the RFC-2822 branch reads
// "1 Jan 0999" — that last is the realistic one, because production's Assigned
// Date column IS RFC 2822 ("Date: Tue, 1 Jul 2025 11:33:05 -0500"), so a
// mistyped year is one keystroke away from a silent permit.
//
// Fail-CLOSED: an unmatchable key becomes NO key, which drops loadRowPeriods()
// to its window leg and, failing that, to `resolved:false` — which every caller
// treats as a refusal. Reported as L-2 on PR #245. Measured read-only on
// production 2026-08-09: 0 of 305 deduped rows change their loadRowPeriods()
// answer, 0 resolved flips, 0 rows in the bad state today.
//
// ⚠️ THE PREDICATE IS lockedAmong()'s OWN, SHARED — NOT sheetCellMonths' TIGHTER
// 1970–2999 BOUND, WHICH PR #245'S L-2 SUGGESTED AND WHICH IS A FAIL-OPEN HERE.
// The two functions are answering different questions. sheetCellMonths INVENTS
// candidate months from ambiguous text, so bounding them to plausible years is
// conservative. This one only has to emit keys isLocked() can be ASKED about, and
// any predicate STRICTER than lockedAmong's discards a key the lock table could
// legitimately hold — silently converting a refusal into a permit, i.e. the very
// bug being fixed. That is not hypothetical: period_locks.period has no CHECK and
// POST /api/periods/:period/finalize admits anything matching /^\d{4}-\d{2}$/, so
// "1900-05" and "1969-12" ARE lockable today. Caught by security review on this
// PR; measured with a 1970–2999 bound and such a lock present: 128 REFUSE→permit
// flips over 1,183 gate combinations, versus 0 with the shared predicate. Sharing
// one regex is what makes producer and consumer unable to drift apart — do not
// re-narrow it here, and do not copy sheetCellMonths' bound into it.
const LOCKABLE_MONTH_KEY = /^\d{4}-\d{2}$/;
function loadAssignedMonthKey(row, cols) {
	if (!cols.dateCol || !row[cols.dateCol]) return "";
	const d = moneySheetDate(row[cols.dateCol]);
	if (!d || isNaN(d)) return "";
	const key = jtFmtDate(d).slice(0, 7);
	return LOCKABLE_MONTH_KEY.test(key) ? key : "";
}

// The active-day window a load contributes, as "YYYY-MM-DD" strings. Mirrors the
// pay loop: pickup appointment → drop-off appointment, pickup falling back to the
// assigned date when blank. Deliberately NOT gated on the completed status the
// pay loop checks — status is mutable, and a load one status change away from
// counting should not be one status change away from being deletable out of a
// closed month. A wider window here can only ever refuse more, never permit more.
//
// ⚠️ THE DROP-OFF END MUST USE moneySheetDate(), THE SAME RESOLVER AS THE PICKUP
// FALLBACK BELOW. It used to call the strict jtParseSheetDate() with no fallback
// of any kind, so a drop-off the strict parser could not read silently collapsed
// the window to the single pickup day — and this function backs loadRowPeriods(),
// which backs every period-lock guard. A narrower window means FEWER months
// considered, i.e. the guard concludes a row touches nothing locked and clears an
// operation out of a closed period: it failed OPEN, the one direction a guard
// must never fail. Widening is safe by construction, not merely by measurement:
// moneySheetDate's ISO and US branches are byte-identical to jtParseSheetDate's,
// so every value that resolves today resolves to the SAME Date and only new
// shapes are added; and jtExpandDateRange starts `if (e < s) return [fmtDate(s)]`,
// so a resolved drop-off can never yield fewer days than a null one. The window
// is therefore always a superset => the guard only ever refuses MORE.
//
// ⚠️ THE PICKUP END IS A UNION, NOT A SUBSTITUTION, AND THAT ASYMMETRY WITH THE
// DROP-OFF ABOVE IS THE WHOLE POINT. The pay loop resolves the pickup CELL through
// moneySheetDate() (it must — that is the day the driver actually worked, and it is
// what POST /api/invoices/generate already reads). Copying that here verbatim would
// break the guard in two ways the drop-off change could not, because widening the
// pickup is not monotone the way widening the drop-off is:
//
//   1. IT SHIFTS THE WINDOW'S START, so the window can LOSE a day rather than only
//      gain one. Measured on production 2026-08-09: load 529227269's Pickup
//      Appointment is "2025/09/23 23:59", which the strict parser cannot read, so
//      today the fallback below starts the window at the ASSIGNED date 2025-09-22.
//      Reading the cell moves the start to 09-23 and drops 09-22 — and a start that
//      moves can cross a month boundary, i.e. hide a month from the guard.
//   2. IT WOULD FLIP resolved:false -> resolved:true. The `return []` below is what
//      makes loadRowPeriods() answer "I cannot read this row", which every caller
//      treats as a REFUSAL. It is reached only when the assigned date is also
//      unreadable — exactly the case a widened pickup would start resolving. Turning
//      a refusal into a permission is the one direction a guard must never move, and
//      no measurement makes it safe: it is a change to the DEFAULT.
//
// So the narrow reading is kept exactly as it was — same `pickup`, same fallback,
// same `return []` — and the wide reading is added as a SECOND leg. The result is a
// superset of the pre-change window (property 1 restored) while the refusal
// condition is untouched (property 2 restored).
//
// ⚠️ WHICH CALLER ACTUALLY GETS THE UNION — do not mis-read this as the thing that
// keeps the load-delete and status-override guards correct. IT IS NOT, and those
// two never see it at all. loadRowPeriods() below reaches this function only when
// loadAssignedMonthKey() returned "", i.e. moneySheetDate() could not read the
// assigned date — which is exactly the condition that makes the fallback above
// yield null too. So on that path `pickup` is always the strict read, and either it
// is null (→ `return []`, unchanged) or it resolved, in which case moneySheetDate()
// on the same cell returns the IDENTICAL instant (the strict ISO/US branches are a
// byte-for-byte subset of moneySheetDate's, and its only extra pre-step, stripping
// a leading "Date:", cannot apply to a string those ^-anchored regexes matched) and
// the equality test below short-circuits. Verified by instrumenting the union leg:
// it fired 0 times in 312 combinations that reach the window path via
// loadRowPeriods, against 144 times on the direct call. What keeps those two guards
// byte-identical is the untouched `return []` plus that subset property — NOT the
// union. Deleting the union would not weaken them; adding a third leg would not
// strengthen them.
//
// The union's one live consumer is the DIRECT call in excludedDayPeriods(), whose
// `loadWindowDays(row, cols).includes(date)` coverage test runs on rows whose
// assigned date IS readable. Keeping that test monotone is the whole job: a row
// that covered a date before must still cover it, or the gate silently stops
// consulting that load's months.
//
// Measured on production 2026-08-09 across all 305 deduplicated Job Tracking rows
// (the set the guards actually see — they do NOT run excludeDroppedLoads): windows
// changed 0, days lost 0, loadRowPeriods changed 0, resolved flips 0. The union is
// inert on today's data and is here for the row that has not arrived yet.
function loadWindowDays(row, cols) {
	let pickup = jtParseSheetDate(cols.pickupDateCol ? row[cols.pickupDateCol] : null);
	// The same cell through the shared resolver. NOT a replacement for the line
	// above — see the ⚠️ note. Production carries 2 such cells (of 252 non-empty),
	// of which 1 resolves: "2025/09/23 23:59"; "14:00" is a time and stays null.
	const pickupShared = moneySheetDate(cols.pickupDateCol ? row[cols.pickupDateCol] : null);
	const dropoff = moneySheetDate(cols.dropoffDateCol ? row[cols.dropoffDateCol] : null);
	if (!pickup && cols.dateCol && row[cols.dateCol]) {
		// Same shared resolver as the pay loop's own assigned-date fallback, for
		// the same reason as loadAssignedMonthKey above.
		pickup = moneySheetDate(row[cols.dateCol]);
	}
	// UNCHANGED — this line alone decides loadRowPeriods()'s `resolved`, so the
	// refusal default is byte-identical to before the pickup end was widened.
	if (!pickup || isNaN(pickup)) return [];
	const days = jtExpandDateRange(pickup, dropoff || pickup);
	if (!pickupShared || isNaN(pickupShared) || +pickupShared === +pickup) return days;
	// Both readings agreed on nothing but the drop-off — take their union, so the
	// guard sees every month either basis could book this load into.
	return [...new Set(days.concat(jtExpandDateRange(pickupShared, dropoff || pickupShared)))].sort();
}

// Every settlement month one Job Tracking row feeds. `resolved:false` means the
// row's dates are unreadable — i.e. the guard cannot answer, which its callers
// treat as a refusal and never as "affects nothing".
function loadRowPeriods(row, cols) {
	const assigned = loadAssignedMonthKey(row, cols);
	if (assigned) return { periods: [assigned], resolved: true };
	// No assigned month: revenue drops out entirely (the P&L needs that key to
	// bucket at all) and the active days fall back to their own calendar months —
	// the only path by which one load reaches two periods.
	//
	// Same LOCKABLE_MONTH_KEY test as the assigned leg above, and required for the
	// same reason: jtExpandDateRange() builds these days with jtFmtDate() too, so
	// an ISO pickup like "0999-01-01" reaches here as "999-01-" and lockedAmong()
	// would drop it. Filtering rather than bailing is deliberate, and safe ONLY
	// because the predicate is lockedAmong's own: what it discards is exactly what
	// lockedAmong could never have matched, so discarding it cannot cost a refusal.
	// (Were this tightened — see the ⚠️ on LOCKABLE_MONTH_KEY — the filter would
	// start dropping lockable months and this line would become the fail-open.)
	// When it filters everything out, `months` is empty and the row answers
	// resolved:false, i.e. the guard refuses.
	const months = [...new Set(loadWindowDays(row, cols).map((d) => d.slice(0, 7)).filter((m) => LOCKABLE_MONTH_KEY.test(m)))].sort();
	return { periods: months, resolved: months.length > 0 };
}

// Of a set of candidate months, the ones period_locks records as closed.
// Callers must have checked periodLocksReadable() first — isLocked() answers
// "not locked" on an unreadable table, so this alone is not a guard.
function lockedAmong(periods) {
	// THE SAME regex object the producers filter on (see LOCKABLE_MONTH_KEY). It
	// was a local copy; sharing it is what makes a gap between "keys we emit" and
	// "keys we can match" structurally impossible, because a key silently dropped
	// here reads as "nothing locked" and permits the write.
	return [...new Set((periods || []).filter((p) => LOCKABLE_MONTH_KEY.test(p) && isLocked(p)))].sort();
}

// ── Which months may be WRITTEN into period_locks ────────────────────────────
// LOCKABLE_MONTH_KEY above answers "can isLocked() be asked about this key?".
// This answers the different question "may this key be CREATED as a lock?", and
// it is deliberately NARROWER: `1900-05`, `0999-13` and `9999-99` all satisfy
// /^\d{4}-\d{2}$/, so before this the finalize route admitted every one of them
// and period_locks — which has no CHECK on `period` — kept the junk row that
// every guard in this file then consults.
//
// ⚠️ THE DIRECTION IS THE WHOLE POINT, AND IT IS THE OPPOSITE OF PR #249's.
// #249 tried tightening the CONSUMER (a 1970–2999 bound inside the month-key
// producers, which lockedAmong then had to match) and that was a FAIL-OPEN:
// when the reader admits less than the lock table can hold, a genuinely locked
// month is silently discarded, `locked.length` is 0, and a refusal becomes a
// permit — measured at 128 REFUSE→permit flips. Tightening the WRITER cannot do
// that: it can only ever REMOVE rows from period_locks, never HIDE one that
// exists, and a hidden lock is what turns a refusal into a permit.
//
// ⚠️ Note precisely what that does and does not claim. A lock row that is never
// created IS a refusal that never happens, so this is not free — it is safe only
// because the months it removes are not settlement months at all. The invariant
// below is what keeps the *reader* whole:
//
//         isPlausibleLockPeriod(p)  ⟹  LOCKABLE_MONTH_KEY.test(p)
//
// i.e. the writer's set is a strict SUBSET of the reader's. That is enforced
// STRUCTURALLY by the first line of the function — it delegates to the very
// same regex object rather than restating the shape — so the two cannot drift
// apart even if the bounds below are edited. Do NOT reimplement the shape here,
// and do NOT copy this bound back into lockedAmong() or the month-key producers;
// that is exactly the fail-open #249 reverted.
//
// The bound is a typo/garbage filter, not a business rule, so it is deliberately
// enormous: production's oldest lock is 2025-05 and the carrier did not exist in
// 1999. Fixed rather than clock- or data-derived on purpose — a window learned
// from the rows present goes blind exactly when the data is wrong, which is the
// case this exists for (same reasoning as the LOAD_NUM_RE note in
// lib/ratecon-reconcile.js). Widen it before 2100 and nothing else changes.
//
// ⚠️ WIDENING IS SAFE. NARROWING IS NOT — DO NOT EVER NARROW THIS.
// Not to a "business" range (2020-2030), not to trim the tails. Two reasons, and
// the second has no recovery:
//   1. A month that becomes implausible stops being lockable, so any guard whose
//      only candidate is that month flips refuse → permit. That is #249's bug
//      arriving through the back door.
//   2. It is a ONE-WAY DOOR. Reopen deliberately skips this bound when a lock row
//      already exists (see the route), but finalize does not — so narrowing past a
//      month that is already locked leaves it reopenable and never re-lockable,
//      with no API able to close it again.
// The tails cost nothing: nobody types 2001-03 by accident, and the bound exists
// to catch 1900-05 and 0999-13, both of which are far outside any range worth
// arguing about.
const LOCK_PERIOD_MIN_YEAR = 2000;
const LOCK_PERIOD_MAX_YEAR = 2100;
function isPlausibleLockPeriod(period) {
	const p = String(period == null ? "" : period);
	if (!LOCKABLE_MONTH_KEY.test(p)) return false;   // ⚠️ subset, structurally — see above
	const y = Number(p.slice(0, 4)), m = Number(p.slice(5, 7));
	return m >= 1 && m <= 12 && y >= LOCK_PERIOD_MIN_YEAR && y <= LOCK_PERIOD_MAX_YEAR;
}

// Compute per-driver FIFO queues from Job Tracking + load_responses.
// Returns { [driverNameNorm]: [{ load_id, queue_position, accepted_at }, ...] }.
// A "queued" load is one the driver has accepted (Sheet status === "Assigned")
// but hasn't yet started progressing. The dispatcher's confirmation modal and
// the driver app's "Up Next" list both read off this. Position is 1-based,
// ordered by load_responses.responded_at ASC (the FIFO requirement).
function computeDriverQueues(jobTrackingRows, headers) {
	const driverCol = findCol(headers || [], /driver|operator/i);
	const statusCol = findCol(headers || [], /^(job[\s._-]?)?status$/i) || findCol(headers || [], /status/i);
	const loadIdCol = findCol(headers || [], /load.?id|job.?id/i);
	if (!driverCol || !statusCol || !loadIdCol) return {};
	if (!Array.isArray(jobTrackingRows) || jobTrackingRows.length === 0) return {};
	// Both "Dispatched" (queued, awaiting acceptance) and "Assigned" (accepted,
	// waiting to start) count as "in queue" — the dispatcher's (Queue: N) badge
	// reflects total pending work for that driver. Phase 2 introduced deferred
	// acceptance: dispatchers can queue ahead of a busy driver, the row sits at
	// "Dispatched" until the driver delivers their current load, at which point
	// it surfaces in their Pending sub-tab and they can accept it (→ Assigned).
	const queuedRe = /^(assigned|dispatched)$/i;
	const candidates = [];
	for (const r of jobTrackingRows) {
		const status = (r[statusCol] || "").toString().trim();
		if (!queuedRe.test(status)) continue;
		const driverNorm = normalizeDriverName(r[driverCol]);
		const loadId = (r[loadIdCol] || "").toString().trim();
		if (driverNorm && loadId) {
			candidates.push({ driverNorm, loadId, isAssigned: /^assigned$/i.test(status) });
		}
	}
	if (candidates.length === 0) return {};
	const loadIds = [...new Set(candidates.map((c) => c.loadId))];
	const placeholders = loadIds.map(() => "?").join(",");
	// Accept timestamps for "Assigned" loads (driver's accept time = FIFO key).
	let acceptRows = [];
	try {
		acceptRows = db.prepare(
			`SELECT load_id, driver_name, responded_at, id FROM load_responses
			 WHERE response = 'accepted' AND load_id IN (${placeholders})
			 ORDER BY responded_at ASC, id ASC`
		).all(...loadIds);
	} catch {
		acceptRows = [];
	}
	// Keep the latest accepted row per (driver, load_id) — a driver who declined
	// then re-accepted has two rows; use the most recent acceptance as their
	// accepted_at. ORDER BY ASC means we overwrite as we walk; later wins.
	const acceptMap = new Map();
	for (const ar of acceptRows) {
		const key = `${normalizeDriverName(ar.driver_name)}::${ar.load_id}`;
		acceptMap.set(key, ar.responded_at || "");
	}
	// Dispatch timestamps for "Dispatched" loads (server's dispatch time = FIFO
	// key). Pulled from the per-driver notifications table where each load
	// assignment writes a row. Uses json_extract to read metadata.loadId.
	const dispatchMap = new Map();
	try {
		const dispatchRows = db.prepare(
			`SELECT driver_name, json_extract(metadata, '$.loadId') AS load_id, created_at, id
			 FROM notifications
			 WHERE type = 'load-assigned' AND json_extract(metadata, '$.loadId') IN (${placeholders})
			 ORDER BY created_at ASC, id ASC`
		).all(...loadIds);
		for (const dr of dispatchRows) {
			if (!dr.load_id) continue;
			const key = `${normalizeDriverName(dr.driver_name)}::${String(dr.load_id).trim()}`;
			dispatchMap.set(key, dr.created_at || "");
		}
	} catch {
		// Best-effort: if notifications query fails, Dispatched loads fall back to row-order.
	}
	const byDriver = {};
	for (const c of candidates) {
		const key = `${c.driverNorm}::${c.loadId}`;
		const ts = c.isAssigned ? (acceptMap.get(key) || "") : (dispatchMap.get(key) || "");
		if (!byDriver[c.driverNorm]) byDriver[c.driverNorm] = [];
		byDriver[c.driverNorm].push({
			load_id: c.loadId,
			accepted_at: c.isAssigned ? ts : null,
			dispatched_at: c.isAssigned ? null : ts,
			status: c.isAssigned ? "assigned" : "dispatched",
			_sortKey: ts,
		});
	}
	for (const driverNorm of Object.keys(byDriver)) {
		// Sort by whichever timestamp applies (accepted_at for Assigned,
		// dispatched_at for Dispatched). Loads without any timestamp sort to
		// the end (treated as "newest" with no FIFO signal).
		byDriver[driverNorm].sort((a, b) => {
			const at = a._sortKey || "";
			const bt = b._sortKey || "";
			if (!at && !bt) return 0;
			if (!at) return 1;
			if (!bt) return -1;
			return at.localeCompare(bt);
		});
		byDriver[driverNorm].forEach((q, i) => {
			q.queue_position = i + 1;
			delete q._sortKey;
		});
	}
	return byDriver;
}

// GET /api/driver/position  (alias: /api/driver/me/position)
// The requesting driver's OWN live truck position.
//
// ⚠️ THIS FIXES A LIVE BUG, AND THE BUG IS AN AUTHORIZATION ONE WEARING A 403.
// DriverView polls `/api/locations/latest` for its own pin, but that route is
// requireRole("Super Admin", "Dispatcher") — so from a Driver session it has
// always returned 403, swallowed by the caller's empty catch. A real driver's
// position poll has never once worked, silently, and the map has been rendering
// its no-pin fallback for every driver since phone GPS was retired.
//
// ⚠️ DO NOT "FIX" IT BY ADDING "Driver" TO THAT ROUTE'S ROLE LIST. It returns
// EVERY driver's live position, ETA, active loads and truck assignment and lets
// the CLIENT filter to one — so widening the role hands each driver the whole
// fleet's real-time locations and load book. The scoping has to happen on the
// server, which means a separate route.
//
// Shape follows the /me precedent set by GET /api/driver/me/truck-photo and the
// Driver branch of GET /api/fuel/range, and for the same three reasons:
//   - the driver is resolved from the SESSION, never from a parameter;
//   - query params are IGNORED rather than 403'd, so there is no spoofable
//     surface at all — nothing to probe means nothing to enumerate;
//   - `routemate_vehicle_id` is OMITTED from the response. It is inert while no
//     parameter accepts it, but publishing the ELD id to every driver hands out
//     exactly the enumeration key the scoping depends on, so a later refactor
//     that relaxed a lookup would find the fleet's ids already in the wild.
//     `unit` stays — it is the placard on the truck they are sitting in, and
//     /api/driver/:driverName already returns it.
//
// ⚠️ THIS MUST STAY ABOVE `app.get("/api/driver/:driverName")`, AND THAT IS THE
// ONLY REASON IT SITS HERE RATHER THAN BESIDE ITS SIBLING /me ROUTES. Express
// matches in REGISTRATION ORDER, and `:driverName` matches a single segment — so
// registered after it, `/api/driver/position` is unreachable: the request lands
// in the driver-lookup handler with driverName = "position". That failure is
// quiet in the worst way, because it does NOT 404 (the shape a client would
// notice and fall back from) — it returns a 200-ish driver payload for a driver
// who does not exist. `/api/driver/me/position` is immune by construction (two
// segments, which is why truck-photo is spelled `/api/driver/me/truck-photo`),
// but the bare form is not, so ORDER is what makes it work.
//
// BOTH PATHS are registered deliberately. `/api/driver/position` is the name the
// client composable already calls; `/api/driver/me/position` is the spelling
// consistent with every other self-scoped driver route here. One handler, so
// they cannot drift.
// ⚠️ DEFINED HERE, NOT REUSED FROM fuelPlanLimiter, AND THAT IS FORCED. That
// limiter is a `const` declared ~9,000 lines below; route registration runs at
// module-eval time, so naming it here is a TDZ ReferenceError at boot — the exact
// failure the note beside refuseCrossOrigin documents. Its SHAPE is copied
// instead: same 15-minute window, same role-aware `max`, same per-user
// keyGenerator.
//
// ⚠️ KEYED PER USER, NEVER PER IP, and here that is not a nicety. A carrier's
// drivers sitting in one yard behind one NAT would otherwise share a single
// bucket while a driver on cellular gets a fresh one — throttling the group that
// is behaving and not the one that is not. Same reasoning poiLimiter states.
//
// The caps are arithmetic, not taste: useDriverPosition polls this every
// ELD_POLL_MS = 30 s, i.e. 30 requests per window PER OPEN TAB. 120 is four
// concurrent tabs/devices for one driver — comfortably above any real usage, and
// still a hard stop on a scripted client. Super Admin is looser because the role
// reaches this route only by opening the driver app itself, usually while also
// holding a dashboard open. This is a BACKSTOP: the request is two indexed
// SQLite reads and costs no third-party call, so nothing here needs a tight cap.
const driverPositionLimiter = rateLimit({
	windowMs: 15 * 60 * 1000,
	max: (req) => (req.session?.user?.role === "Super Admin" ? 240 : 120),
	keyGenerator: (req) => {
		const id = req.session?.user?.id;
		return id ? `u:${id}` : `ip:${ipKeyGenerator(req.ip)}`;
	},
	message: { error: "Too many position requests. Try again later." },
	standardHeaders: true,
});

// ⚠️ requireRole BEFORE the limiter, matching the order stated beside
// crossSiteGuard and used by fuelEventsLimiter / fuelGallonsLimiter: a request we
// are going to refuse anyway must not first consume the budget of the session it
// is not authenticated as. Reversed, an unauthenticated caller could spend a real
// driver's window on 403s.
app.get(["/api/driver/position", "/api/driver/me/position"], requireRole("Driver", "Super Admin"), driverPositionLimiter, (req, res) => {
	try {
		const user = req.session.user;
		const driverName = (user.driverName || user.driver_name || "").trim();
		// A Super Admin using the driver app (/driver permits the role) usually has
		// no linked driver name, and a Driver whose account is not linked to a
		// carrier row is an admin-side gap. Both degrade to the same honest empty
		// answer rather than an error: the map renders its no-pin state, which is
		// also what it does for a truck with no ELD. A 404 here would surface a
		// linkage gap as a broken driver screen.
		if (!driverName) return res.json({ ok: true, position: null, reason: "no_driver_name" });

		// The widened resolver the fuel endpoints use: active truck_assignments
		// row first, falling back to trucks.assigned_driver, matching on
		// normalizeDriverName() rather than SQL TRIM(LOWER()). Reusing it keeps this
		// route from becoming a fourth spelling of "which truck is this driver in".
		const truck = resolveTruckForDriverName(driverName);
		const vehicleId = (truck && truck.routemate_vehicle_id) || "";
		if (!vehicleId) {
			return res.json({
				ok: true, position: null,
				unit: (truck && truck.unit) || "",
				reason: truck ? "truck_not_eld_linked" : "no_truck_assigned",
			});
		}

		// Two rows: the latest clean fix, and the one before it as a heading
		// fallback. idx_rm_tel_clean covers (routemate_vehicle_id, dropped_reason,
		// id DESC) exactly, so this is two index reads.
		const rows = db.prepare(
			`SELECT latitude, longitude, speed, bearing, fuel_pct, location_date_ms
			   FROM routemate_telemetry
			  WHERE routemate_vehicle_id = ? AND dropped_reason = ''
			  ORDER BY id DESC LIMIT 2`
		).all(vehicleId);
		const rm = rows[0] || null;
		const prev = rows[1] || null;

		// Same 14-day visibility window dispatch gets, deliberately: an ELD pings
		// only while the truck is powered, so a 5-minute freshness gate threw away
		// the position of every parked truck and hid it entirely (owner report,
		// 2026-07-27). RECENCY is published as lastPingAge and left to the UI to
		// render as Online/Dormant/Offline — visibility and freshness are different
		// questions. Making this window narrower than dispatch's would put the
		// driver and the dispatcher looking at contradicting maps.
		const STALE_SHOW_MS = 14 * 24 * 60 * 60 * 1000;
		// A linked truck whose ELD has lost GPS reports NULL/0 coordinates. Letting
		// that through pins the truck at the equator, which is worse than no pin.
		const hasFix = rm
			&& Number.isFinite(rm.latitude) && Number.isFinite(rm.longitude)
			&& (rm.latitude !== 0 || rm.longitude !== 0)
			&& Number.isFinite(rm.location_date_ms)
			&& Date.now() - rm.location_date_ms < STALE_SHOW_MS;
		if (!hasFix) {
			return res.json({ ok: true, position: null, unit: (truck && truck.unit) || "", reason: "no_recent_fix" });
		}

		// Heading: the device's own bearing (numeric degrees or a compass string),
		// else the rhumb-line bearing from the previous clean fix. Same two-step,
		// and the same helper, as /api/locations/latest — a driver's camera should
		// point where the dispatcher's arrow points.
		let heading = parseRoutemateBearing(rm.bearing);
		if (heading == null && prev
			&& Number.isFinite(prev.latitude) && Number.isFinite(prev.longitude)
			&& (prev.latitude !== rm.latitude || prev.longitude !== rm.longitude)) {
			heading = geolib.getRhumbLineBearing(
				{ latitude: prev.latitude, longitude: prev.longitude },
				{ latitude: rm.latitude, longitude: rm.longitude },
			);
		}

		const speedMps = Number.isFinite(rm.speed) ? rm.speed : 0;
		const lastPingAge = Date.now() - rm.location_date_ms;
		res.json({
			ok: true,
			unit: (truck && truck.unit) || "",
			position: {
				latitude: rm.latitude,
				longitude: rm.longitude,
				// `speed` stays METRES PER SECOND, the column's unit and the unit
				// /api/locations/latest publishes — the Linxup receiver converts
				// mph->m/s on the way in and MOVEMENT_MOVING_MPS compares against it.
				// speedMph is a convenience for the overlay's pill so the conversion
				// is not re-derived (and mis-derived) per component.
				speed: speedMps,
				speedMph: Math.round((speedMps * 2.23694) * 10) / 10,
				heading: heading == null ? null : heading,
				timestamp: new Date(rm.location_date_ms).toISOString(),
				lastPingAge,
				source: "routemate",
				fuelPct: Number.isFinite(rm.fuel_pct) ? rm.fuel_pct : null,
				// Same three-state classifier the tracking panel uses, computed here
				// so the driver and the dispatcher cannot disagree about whether the
				// truck is moving.
				movement: classifyMovement({ lastPingAge, speed: speedMps }),
			},
		});
	} catch (err) {
		console.error("driver position error:", err.message);
		res.status(500).json({ ok: false, error: "Failed to read position" });
	}
});

// GET /api/driver/:driverName — All data for one driver (single batchGet)
app.get("/api/driver/:driverName", requireAuth, async (req, res) => {
	try {
		const driverName = decodeURIComponent(req.params.driverName).trim();

		// Drivers can only access their own data
		if (
			req.session.user.role === "Driver" &&
			req.session.user.driverName.toLowerCase() !== driverName.toLowerCase()
		) {
			return res.status(403).json({ error: "Forbidden" });
		}
		// Use the shared 60s in-memory cache so the driver endpoint matches the
		// rest of the load-aggregating endpoints (/api/dashboard, /api/investor,
		// /api/financials, /api/public/track). Cold reads still hit Sheets, but
		// warm reads now respond in ~10ms instead of 2-5s, and drop cancelled +
		// soft-deleted rows the same way the admin KPIs do.
		const jobTracking = await getJobTrackingCached();
		jobTracking.data = excludeDroppedLoads(jobTracking.data, jobTracking.headers);
		const carrierDB = getCarrierDBFromSQLite();

		// Find driver column in Job Tracking. Regex covers the common
		// labels we've actually seen ("Driver", "Driver Name", "Assigned Driver")
		// plus "Operator" as a defensive fallback. If a sheet is ever renamed
		// outside these patterns, log it loudly — silent regex misses used to
		// return zero loads with no signal to the driver or the operator.
		const driverCol = findCol(jobTracking.headers, /driver|operator/i);
		if (!driverCol) {
			console.error(`[driver-data] No driver column matched in Job Tracking headers for driverName=${driverName}. Headers: ${JSON.stringify(jobTracking.headers)}`);
		}
		const carrierDriverCol =
			findCol(carrierDB.headers, /driver|operator/i) || carrierDB.headers[0];

		// Filter loads for this driver. normalizeDriverName tolerates internal
		// whitespace variants in the sheet so a typo'd row doesn't silently
		// drop loads from the driver's app.
		const driverNameNorm = normalizeDriverName(driverName);
		const loads = driverCol
			? jobTracking.data.filter(
					(r) => normalizeDriverName(r[driverCol]) === driverNameNorm,
				)
			: [];

		// Build a diagnostic payload for the two empty-load failure modes we've
		// actually seen in production: (1) the Job Tracking sheet header drifts
		// outside the /driver|operator/i regex, (2) the column matches but the
		// session driver name doesn't match any row. Both manifest as "the
		// driver app shows zero loads" with no on-screen signal. Surfacing the
		// reason here lets an admin curl /api/driver/<name> and see what broke
		// without having to tail server logs.
		const diagnostic = {};
		if (!driverCol) {
			diagnostic.warning = "driver_column_not_matched";
			diagnostic.sheetHeaders = jobTracking.headers;
		} else if (jobTracking.data.length > 0 && loads.length === 0) {
			diagnostic.warning = "no_loads_for_driver";
			diagnostic.driverNameSearched = driverNameNorm;
			diagnostic.sampleDriverNamesInSheet = [
				...new Set(
					jobTracking.data
						.map((r) => (r[driverCol] || "").trim())
						.filter(Boolean),
				),
			].slice(0, 5);
		}

		// Find driver info from Carrier Database
		const driverInfo = carrierDB.data.find(
			(r) =>
				(r[carrierDriverCol] || "").trim().toLowerCase() ===
				driverName.toLowerCase(),
		);

		// Messages from SQLite (fast indexed query)
		const nameLower = driverName.toLowerCase();
		const driverMessages = db
			.prepare(
				`SELECT id, timestamp, "from", "to", message, load_id AS loadId, read
				 FROM messages
				 WHERE LOWER("from") = ? OR LOWER("to") = ?
				 ORDER BY id ASC`,
			)
			.all(nameLower, nameLower);

		// Notifications from SQLite
		// SQLite's CURRENT_TIMESTAMP is UTC but serializes without a zone
		// ("2026-04-20 14:30:00"), which JS parses as local time — every row
		// then looks ~N hours in the future and the UI stuck on "just now".
		// Force ISO-8601 with Z so `new Date(...)` parses it as UTC.
		const driverNotifications = db
			.prepare(
				`SELECT id, type, title, body, metadata, read,
				        strftime('%Y-%m-%dT%H:%M:%SZ', created_at) AS createdAt
				 FROM notifications
				 WHERE driver_name = ?
				 ORDER BY id DESC
				 LIMIT 100`,
			)
			.all(nameLower);

		// Expenses from SQLite. photo_data is the receipt URL (per
		// saveReceiptToDisk() — base64 is written to /uploads/expense-receipts/
		// on submit and only the URL is stored), so the payload stays small
		// even for drivers with hundreds of expenses. PDF receipts (admin/
		// dispatcher-logged via savePdfReceiptToDisk) are blanked here: the
		// driver app renders photoData in an <img> and would show a broken
		// thumbnail — the deliberately-unchanged driver UI is image-only.
		const driverExpenses = db
			.prepare(
				`SELECT id, timestamp, driver, load_id AS loadId, type, amount,
				        description, date,
				        CASE WHEN photo_data LIKE '%.pdf' THEN '' ELSE photo_data END AS photoData,
				        status,
				        location_city AS locationCity, location_state AS locationState
				 FROM expenses
				 WHERE LOWER(driver) = ?
				 ORDER BY id DESC`,
			)
			.all(nameLower);

		// Count uploaded documents per load (total + per-kind breakdown). The
		// driver-mobile-view's DocumentUpload needs per-kind counts so BOL /
		// Receipt / Other show "N uploaded" accurately after a reload, not just
		// POD. _otherCount is anything that isn't one of the three known kinds.
		const loadIdCol = findCol(jobTracking.headers, /load.?id|job.?id/i);
		const loadIds = loads
			.map((l) => (loadIdCol ? l[loadIdCol] : ""))
			.filter(Boolean);
		const docCounts = {};
		const podCounts = {};
		const bolCounts = {};
		const receiptCounts = {};
		const otherCounts = {};
		if (loadIds.length) {
			const placeholders = loadIds.map(() => "?").join(",");
			const docs = db
				.prepare(
					`SELECT load_id,
						COUNT(*) as count,
						SUM(CASE WHEN type = 'POD' THEN 1 ELSE 0 END) as pod_count,
						SUM(CASE WHEN type = 'BOL' THEN 1 ELSE 0 END) as bol_count,
						SUM(CASE WHEN type = 'Receipt' THEN 1 ELSE 0 END) as receipt_count,
						SUM(CASE WHEN type NOT IN ('POD', 'BOL', 'Receipt') THEN 1 ELSE 0 END) as other_count
					FROM documents WHERE load_id IN (${placeholders}) AND deleted_at IS NULL GROUP BY load_id`,
				)
				.all(...loadIds);
			docs.forEach((d) => {
				docCounts[d.load_id] = d.count;
				podCounts[d.load_id] = d.pod_count;
				bolCounts[d.load_id] = d.bol_count;
				receiptCounts[d.load_id] = d.receipt_count;
				otherCounts[d.load_id] = d.other_count;
			});
		}
		loads.forEach((load) => {
			const lid = loadIdCol ? load[loadIdCol] : "";
			load._docCount = docCounts[lid] || 0;
			load._podCount = podCounts[lid] || 0;
			load._bolCount = bolCounts[lid] || 0;
			load._receiptCount = receiptCounts[lid] || 0;
			load._otherCount = otherCounts[lid] || 0;
		});

		// Strip rate/revenue columns for Driver role
		let filteredLoads = loads;
		let filteredHeaders = jobTracking.headers;
		if (req.session.user.role === "Driver") {
			const rateRegex = /rate|amount|revenue|pay|charge|price|cost/i;
			const hiddenCols = new Set(
				jobTracking.headers.filter((h) => rateRegex.test(h)),
			);
			filteredHeaders = jobTracking.headers.filter(
				(h) => !hiddenCols.has(h),
			);
			filteredLoads = loads.map((load) => {
				const cleaned = { ...load };
				hiddenCols.forEach((col) => delete cleaned[col]);
				return cleaned;
			});
		}

		// Sanitize broker contact data for non-Admin roles
		if (req.session.user.role !== "Super Admin") {
			filteredLoads = sanitizeBrokerColumns(filteredHeaders, filteredLoads);
		}

		// Attach _accepted flag from load_responses
		const acceptedRows = db.prepare(
			`SELECT load_id FROM load_responses WHERE driver_name = ? AND response = 'accepted'`
		).all(nameLower);
		const acceptedSet = new Set(acceptedRows.map(r => r.load_id));
		const acceptLoadIdCol = jobTracking.headers.find((h) => /load.?id|job.?id/i.test(h));
		filteredLoads.forEach((load) => {
			const lid = acceptLoadIdCol ? (load[acceptLoadIdCol] || "") : "";
			load._accepted = acceptedSet.has(lid);
		});

		// Attach FIFO queue position for "Assigned" loads. Position is derived
		// from load_responses.responded_at (oldest accept = position 1) by the
		// shared computeDriverQueues helper so the driver app and the dispatch
		// board agree on the ordering. Loads not in the "Assigned" state get no
		// _queuePosition; the driver UI treats absence as "this isn't queued".
		const driverQueueForName = computeDriverQueues(
			jobTracking.data,
			jobTracking.headers,
		)[driverNameNorm] || [];
		if (driverQueueForName.length > 0) {
			const posByLoadId = new Map(
				driverQueueForName.map((q) => [q.load_id, q]),
			);
			filteredLoads.forEach((load) => {
				const lid = acceptLoadIdCol ? (load[acceptLoadIdCol] || "").toString().trim() : "";
				const q = lid ? posByLoadId.get(lid) : null;
				if (q) {
					load._queuePosition = q.queue_position;
					load._acceptedAt = q.accepted_at || null;
				}
			});
		}

		// PRIVACY: do not expose other drivers' names to a Driver-role caller.
		// Previously this returned the full carrier driver list to every
		// /api/driver/:name response. The driver UI never consumed it; admin
		// views fetch the list separately via /api/data?sheet=Carrier+Database.
		const carrierDriverNames = req.session.user.role === "Driver"
			? []
			: [
				...new Set(
					carrierDB.data
						.map((r) => (r[carrierDriverCol] || "").trim())
						.filter(Boolean),
				),
			].sort();

		// Assigned truck from SQLite. `photo` is a base64 data URI that can
		// run ~700KB+ for a single truck — we ship `has_photo` only and let
		// the driver app fetch the image lazily from /api/driver/me/truck-photo
		// when the Truck Details accordion expands. Keeps this endpoint small
		// enough to land reliably on a flaky mobile connection.
		const assignedTruck = db.prepare(
			`SELECT id, unit_number, make, model, year, vin, license_plate, status,
			        CASE WHEN photo IS NULL OR photo = '' THEN 0 ELSE 1 END AS has_photo
			 FROM trucks WHERE LOWER(assigned_driver) = ?`
		).get(nameLower) || null;

		// Truck-scoped legal documents the admin has explicitly marked as
		// driver-visible. Only truck-scoped rows (truck_id > 0, no driver_id,
		// no investor_id) participate. `file_url` is deliberately NOT returned
		// — drivers only ever get the row id and hit the view endpoint, which
		// re-checks the active assignment at request time.
		let truckDocuments = [];
		if (assignedTruck && assignedTruck.id > 0) {
			truckDocuments = db.prepare(
				`SELECT id, doc_type, file_name, notes, strftime('%Y-%m-%dT%H:%M:%SZ', uploaded_at) AS uploaded_at
				 FROM legal_documents
				 WHERE truck_id = ?
				   AND visible_to_driver = 1
				   AND (driver_id IS NULL OR driver_id = 0)
				   AND (investor_id IS NULL OR investor_id = 0)
				 ORDER BY uploaded_at DESC`
			).all(assignedTruck.id);
		}

		// Onboarding data (if driver has an onboarding record).
		// IMPORTANT: drivers must NOT see their own drug test result — legal
		// requirement. We explicitly enumerate the columns returned here and
		// omit drug_test_result / drug_test_file_url / drug_test_uploaded_at.
		// Super Admin / Dispatcher still sees them via /api/drivers-directory/:id/documents.
		const userId = req.session.user.id;
		const onboarding = db.prepare(
			"SELECT id, user_id, application_id, driver_name, status, onboarded_at, strftime('%Y-%m-%dT%H:%M:%SZ', created_at) AS created_at FROM driver_onboarding WHERE user_id = ?"
		).get(userId) || null;
		const onboardingDocs = onboarding
			? stripSigningEvidence(db.prepare("SELECT * FROM onboarding_documents WHERE user_id = ? ORDER BY id").all(userId))
			: [];
		// Also fetch the original application so the driver Kit can display
		// the documents and qualifications the applicant submitted. SSN is
		// stripped. The CDL/medical card base64 uploads (~2.5MB each, ~8MB
		// total for a typical driver) used to ship inline here, which is what
		// turned a routine /api/driver/* response into an 8MB+ payload and
		// caused drivers on weak signal to see a stale-or-empty loads tab
		// (the fetch would stall or partially-fail before it could refresh
		// the loads list). We now ship a *_type metadata field per file and
		// let the Kit tab lazy-load actual bytes from
		// /api/driver/me/identity-file/:fileType when it renders.
		let application = null;
		if (onboarding?.application_id) {
			const fullApp = db.prepare(
				"SELECT *, strftime('%Y-%m-%dT%H:%M:%SZ', created_at) AS created_at FROM job_applications WHERE id = ?"
			).get(onboarding.application_id);
			if (fullApp) {
				const { ssn: _drop, cdl_front, cdl_back, medical_card, ...safeApp } = fullApp;
				const detectMime = (b64) => {
					if (!b64) return null;
					if (b64.startsWith("data:application/pdf")) return "pdf";
					if (b64.startsWith("data:image/")) return "image";
					return null;
				};
				application = {
					...safeApp,
					cdl_front_type: detectMime(cdl_front),
					cdl_back_type: detectMime(cdl_back),
					medical_card_type: detectMime(medical_card),
				};
			}
		}
		// Recent invoices (soft-deleted ones are hidden from drivers)
		const driverInvoices = db.prepare(
			`SELECT id, invoice_number, week_start, week_end, loads_count, total_earnings, expenses_total, status, submitted_at,
			        strftime('%Y-%m-%dT%H:%M:%SZ', created_at) AS created_at
			 FROM invoices WHERE LOWER(driver) = ? AND deleted_at = '' ORDER BY created_at DESC LIMIT 20`
		).all(nameLower);

		// Geocode enrichment from the local cache. Lets the driver-mobile-view
		// pre-fill its navigation handoff and render static-map thumbnails
		// without paying for re-geocoding. Lookup key is the lowercased,
		// single-spaced address (same shape geocode_cache stores).
		const pickupAddrCol = findCol(filteredHeaders, /pickup.*address/i);
		const dropAddrCol = findCol(filteredHeaders, /drop.?off.*address|delivery.*address|receiver.*address/i);
		if (filteredLoads.length && (pickupAddrCol || dropAddrCol)) {
			const geoRows = db.prepare("SELECT address, lat, lng FROM geocode_cache").all();
			const geoMap = new Map(
				geoRows.map((r) => [(r.address || "").toLowerCase().replace(/\s+/g, " ").trim(), { lat: r.lat, lng: r.lng }]),
			);
			const lookupGeo = (addr) => {
				if (!addr) return null;
				const norm = String(addr).toLowerCase().replace(/\n/g, " ").replace(/\s+/g, " ").trim();
				return geoMap.get(norm) || null;
			};
			filteredLoads.forEach((load) => {
				if (pickupAddrCol) {
					const geo = lookupGeo(load[pickupAddrCol]);
					if (geo) load._pickupGeo = geo;
				}
				if (dropAddrCol) {
					const geo = lookupGeo(load[dropAddrCol]);
					if (geo) load._dropGeo = geo;
				}
			});
		}

		// Shared documents — files Super Admin uploaded to this driver via /drivers detail modal.
		// Lookup keyed on drivers_directory.id (resolved by driver_name). Guard against id=0 sentinel
		// collision so drivers without a directory row return [] instead of every truck/investor doc.
		let sharedDocuments = [];
		let profilePictureUrl = "";
		let driverDirectoryId = 0;
		const directoryRow = db.prepare("SELECT id, profile_picture_url FROM drivers_directory WHERE LOWER(driver_name) = ?").get(nameLower);
		if (directoryRow && directoryRow.id > 0) {
			driverDirectoryId = directoryRow.id;
			profilePictureUrl = directoryRow.profile_picture_url || "";
			sharedDocuments = db.prepare(
				`SELECT id, doc_type, file_name, notes, uploaded_by, strftime('%Y-%m-%dT%H:%M:%SZ', uploaded_at) AS uploaded_at
				 FROM legal_documents WHERE driver_id = ? ORDER BY uploaded_at DESC`
			).all(directoryRow.id);
		}

		res.json({
			loads: filteredLoads,
			driverInfo: driverInfo || null,
			truck: assignedTruck,
			messages: driverMessages,
			notifications: driverNotifications,
			expenses: driverExpenses,
			drivers: carrierDriverNames,
			headers: {
				jobTracking: filteredHeaders,
				carrierDB: carrierDB.headers,
			},
			onboarding: onboarding ? {
				...onboarding,
				documents: onboardingDocs,
				totalDocs: ONBOARDING_DOCS.length,
			} : null,
			application,
			invoices: driverInvoices,
			sharedDocuments,
			truckDocuments,
			profilePictureUrl,
			driverDirectoryId,
			...(Object.keys(diagnostic).length ? { diagnostic } : {}),
		});
	} catch (error) {
		console.error("Error fetching driver data:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// GET /api/driver/me/identity-file/:fileType — Stream the requesting driver's
// own CDL Front / CDL Back / Medical Card. Companion to the application_*_type
// metadata in /api/driver/:driverName: the main endpoint advertises which
// files exist (and their MIME type), and this one serves the bytes lazily so
// the Driver Kit only pays the ~2.5MB-per-file cost when the user actually
// opens the Kit tab. Super Admin can also call this against their own session
// (debug); admins/dispatchers fetching ON BEHALF of a driver continue to use
// /api/trucks/:id/driver-files, which already supports that flow.
app.get("/api/driver/me/identity-file/:fileType", requireAuth, (req, res) => {
	try {
		const user = req.session.user;
		if (user.role !== "Driver" && user.role !== "Super Admin") {
			return res.status(403).json({ error: "Forbidden" });
		}
		const colMap = {
			"cdl-front": "cdl_front",
			"cdl-back": "cdl_back",
			"medical-card": "medical_card",
		};
		const col = colMap[req.params.fileType];
		if (!col) return res.status(400).json({ error: "Invalid file type" });
		const onboarding = db.prepare(
			"SELECT application_id FROM driver_onboarding WHERE user_id = ?"
		).get(user.id);
		if (!onboarding?.application_id) return res.status(404).json({ error: "Not found" });
		const row = db.prepare(`SELECT ${col} AS data FROM job_applications WHERE id = ?`).get(onboarding.application_id);
		const data = row?.data;
		if (!data) return res.status(404).json({ error: "Not found" });
		const match = /^data:([^;]+);base64,(.+)$/.exec(data);
		if (!match) return res.status(500).json({ error: "Invalid file format" });
		const [, contentType, b64] = match;
		const buf = Buffer.from(b64, "base64");
		res.setHeader("Content-Type", contentType);
		// Private cache — drivers won't refetch the same image every page open.
		res.setHeader("Cache-Control", "private, max-age=3600");
		res.setHeader("X-Content-Type-Options", "nosniff");
		res.end(buf);
	} catch (err) {
		console.error("identity-file error:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// GET /api/driver/me/truck-photo — Stream the photo of the truck currently
// assigned to the requesting driver. Paired with truck.has_photo in
// /api/driver/:driverName, this lets LoadDetail render the truck image only
// when the Truck Details accordion is expanded.
app.get("/api/driver/me/truck-photo", requireAuth, (req, res) => {
	try {
		const user = req.session.user;
		if (user.role !== "Driver" && user.role !== "Super Admin") {
			return res.status(403).json({ error: "Forbidden" });
		}
		const driverName = (user.driverName || user.driver_name || "").trim().toLowerCase();
		if (!driverName) return res.status(404).json({ error: "Not found" });
		const row = db.prepare("SELECT photo FROM trucks WHERE LOWER(assigned_driver) = ?").get(driverName);
		const data = row?.photo;
		if (!data) return res.status(404).json({ error: "Not found" });
		const match = /^data:([^;]+);base64,(.+)$/.exec(data);
		if (!match) return res.status(500).json({ error: "Invalid file format" });
		const [, contentType, b64] = match;
		const buf = Buffer.from(b64, "base64");
		res.setHeader("Content-Type", contentType);
		res.setHeader("Cache-Control", "private, max-age=3600");
		res.setHeader("X-Content-Type-Options", "nosniff");
		res.end(buf);
	} catch (err) {
		console.error("truck-photo error:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// GET /api/driver/shared-documents/:id/download — Proxy download for driver shared docs
// Ownership check: the requesting user must be the driver the document was uploaded to (or Super Admin).
// Matches the invoice/investor signed-PDF proxy pattern. This is the only path drivers use to access
// their files — the raw /uploads/legal/* route is protected by requireAuth but not by ownership,
// so we deliberately don't expose the raw file_url to the driver's frontend.
app.get("/api/driver/shared-documents/:id/download", requireAuth, (req, res) => {
	try {
		const docId = parseInt(req.params.id);
		if (!docId || docId <= 0) return res.status(400).json({ error: "Invalid document id" });
		const doc = db.prepare("SELECT * FROM legal_documents WHERE id = ?").get(docId);
		if (!doc) return res.status(404).json({ error: "Document not found" });
		if (!doc.driver_id || doc.driver_id <= 0) {
			return res.status(404).json({ error: "Not a driver shared document" });
		}
		const sessionUser = req.session.user;
		if (sessionUser.role !== "Super Admin") {
			// Ownership check: session user must be the driver this doc was uploaded to
			const driverRow = db.prepare("SELECT driver_name FROM drivers_directory WHERE id = ?").get(doc.driver_id);
			if (!driverRow) return res.status(403).json({ error: "Forbidden" });
			const sessionDriver = (sessionUser.driver_name || sessionUser.driverName || "").trim().toLowerCase();
			if (!sessionDriver || sessionDriver !== (driverRow.driver_name || "").trim().toLowerCase()) {
				return res.status(403).json({ error: "Forbidden" });
			}
		}
		if (!doc.file_url) return res.status(404).json({ error: "File missing" });
		const filePath = path.join(__dirname, doc.file_url);
		if (!fs.existsSync(filePath)) return res.status(404).json({ error: "File missing" });
		// Same headers the /uploads mount applies — this route bypasses it, and an
		// admin can upload any ALLOWED_FILE_EXTS type here, so a bare sendFile would
		// serve e.g. an .html shared doc as executable same-origin content.
		setUploadServeHeaders(res, doc.file_name || filePath);
		res.sendFile(filePath);
	} catch (err) {
		console.error("Shared doc download error:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// GET /api/driver/truck-documents/:id/view — View-only inline preview for a
// truck's driver-visible legal document. Works for the assigned driver, Super
// Admin, and Dispatcher. No file_url is ever exposed to the driver client —
// they only hold the row id and hit this endpoint, which re-checks the active
// truck_assignments row on every request (so reassignment revokes access
// immediately). Streams inline; we intentionally do not set
// Content-Disposition: attachment, matching the "view-only" product decision.
const truckDocViewLimiter = rateLimit({
	windowMs: 15 * 60 * 1000,
	max: 30,
	message: { error: "Too many requests. Try again later." },
	standardHeaders: true,
});
app.get("/api/driver/truck-documents/:id/view", requireAuth, truckDocViewLimiter, (req, res) => {
	try {
		const docId = parseInt(req.params.id);
		if (!docId || docId <= 0) return res.status(400).json({ error: "Invalid document id" });
		const doc = db.prepare(
			"SELECT id, truck_id, driver_id, investor_id, visible_to_driver, file_url, file_name FROM legal_documents WHERE id = ?"
		).get(docId);
		if (!doc) return res.status(404).json({ error: "Document not found" });
		// Only truck-scoped, driver-visible docs flow through here. Any other
		// category (driver-shared, investor-profile) is rejected so this
		// endpoint cannot be used to bypass the other auth paths.
		if (!doc.truck_id || doc.truck_id <= 0 || doc.visible_to_driver !== 1
			|| (doc.driver_id && doc.driver_id > 0) || (doc.investor_id && doc.investor_id > 0)) {
			return res.status(403).json({ error: "Forbidden" });
		}
		const role = req.session.user.role;
		if (role !== "Super Admin" && role !== "Dispatcher") {
			if (role !== "Driver") return res.status(403).json({ error: "Forbidden" });
			// Driver must be the one currently assigned to this truck.
			const sessionDriver = (req.session.user.driverName || req.session.user.driver_name || "").trim().toLowerCase();
			if (!sessionDriver) return res.status(403).json({ error: "Forbidden" });
			const active = db.prepare(
				`SELECT 1 FROM truck_assignments
				 WHERE truck_id = ? AND end_date = '' AND LOWER(driver_name) = ?
				 LIMIT 1`
			).get(doc.truck_id, sessionDriver);
			if (!active) {
				// Fallback: trucks.assigned_driver is kept in sync with the
				// active assignment, so accept that too in case the history
				// table lags.
				const truck = db.prepare("SELECT assigned_driver FROM trucks WHERE id = ?").get(doc.truck_id);
				if (!truck || (truck.assigned_driver || "").trim().toLowerCase() !== sessionDriver) {
					return res.status(403).json({ error: "Forbidden" });
				}
			}
		}
		if (!doc.file_url) return res.status(404).json({ error: "File missing" });
		const filePath = path.join(__dirname, doc.file_url);
		if (!fs.existsSync(filePath)) return res.status(404).json({ error: "File missing" });
		// Shared rule (see setUploadServeHeaders): nosniff always, inline for the
		// formats we deliberately render, attachment for everything else. This
		// route used to hand-roll an UNCONDITIONAL inline, so an admin-uploaded
		// .doc/.xls/.csv/.txt truck document stayed inline here while the same
		// bytes downloaded everywhere else. Not exploitable — nosniff plus those
		// Content-Types can't become HTML — but this is the widest audience in the
		// app (every assigned driver), and the product decision that matters is
		// "PDFs and images preview", which the shared rule keeps.
		setUploadServeHeaders(res, doc.file_name || filePath);
		res.sendFile(filePath);
	} catch (err) {
		console.error("Truck doc view error:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// THE JOB STATUS VOCABULARY — the only values a human-driven route may write into
// the Job Status column, and the exact spelling each is written in. `newStatus`
// used to be unconstrained free text on BOTH routes that write this column, so
// anything at all could be dropped into the field every KPI branches on.
//
// ⚠️ ONE LIST, TWO ROUTES, ON PURPOSE. It governs `PUT /api/driver/status`
// (below — Driver/Dispatcher/Super Admin) and `PUT /api/loads/:loadId/status-override`
// (further down — Super Admin/Dispatcher, PR #223, which is where the name comes
// from). The legal values of a sheet column are a property of the DATA MODEL, not
// of the route that happens to write it, and two lists that merely ought to agree
// are the drift `DRIVER_RENAME_TARGETS` was consolidated to stop — an override that
// could set a status the ordinary route could not (or the reverse) is incoherent,
// since the override exists to bypass the POD gate on the SAME vocabulary. Per-route
// POLICY still differs and belongs in the routes: the POD gate and the one-active-job
// 409 here, the reason requirement and the ambiguity refusal there.
//
// It is the union of every client that posts to either route, and equals the
// widest of them exactly:
//   • ActiveLoadsTab.vue `statusOptions`  — all 7 (dispatch dropdown -> status route;
//     the override modal defaults to statusOptions[0], so it is the same list)
//   • StatusStepper.vue `statusFlow`      — 6; no "Dispatched" (a driver never moves
//     a load backwards to it)
//   • public/driver.html `STATUS_FLOW`    — 5; legacy, also no "Heading to Shipper"
// The last two are strict SUBSETS, so the unit test asserts subset for them and
// equality only for statusOptions — asserting equality on all three would fail on
// a list that is correct. What must never happen is a client offering a button the
// server refuses; that is the direction the subset test pins.
//
// Enforced server-side for the same reason CANCEL_REASON_REQUIRED is: the guard has
// to hold for any caller, not just the one screen. Matching is case-insensitive but
// the write is canonical, so "delivered" lands as "Delivered" and the sheet keeps
// one spelling per status.
//
// ⚠️ "Cancelled" is deliberately NOT here, even though it is a perfectly
// legitimate status elsewhere in the app. Two independent reasons, either alone
// sufficient:
//   1. PRIVILEGE. Cancelling has its own route — POST /api/dispatch/cancel — which
//      is **Super Admin only** (dispatchers lost it by client decision 2026-04-19),
//      demands a reason, stamps load_status_history, notifies the driver over the
//      `load-cancelled` socket and audits `cancel_load`. Neither route here is
//      Super-Admin-only — the status route is reachable by a **Driver**, the lowest
//      privilege in the app — so accepting "Cancelled" is a plain walk-around of
//      that gate, and it produces a cancellation none of that plumbing recorded.
//   2. MONEY. CANCELED_STATUS_RE in excludeDroppedLoads() drops a cancelled load
//      out of revenue, driver pay and every KPI — it is the one value on the
//      allowlist's doorstep that ERASES a figure rather than moving it. PR #230
//      refuses this in a CLOSED month (it crosses the completed boundary, or lands
//      on a completed row); in an OPEN month nothing stopped it, and an open month
//      is exactly the one still being accrued into.
// The opposite direction — reviving a load cancelled by mistake — is unaffected:
// pick any of the seven. "Completed" and "POD Received" are likewise absent because
// no client ever offered them and "Delivered" already satisfies completedStatuses,
// so nothing is lost. "Assigned"/"Unassigned" are absent for the same reason: they
// are written by POST /api/driver/respond, never by a status write, and a load
// sitting at either still steps forward normally (StatusStepper maps both, plus
// "Dispatched", to "Heading to Shipper" as the next step).
const STATUS_OVERRIDE_ALLOWED = ["Dispatched", "Heading to Shipper", "At Shipper", "Loading", "In Transit", "At Receiver", "Delivered"];

// PUT /api/driver/status — Update load status
//
// ⚠️ `requireRole`, NOT `requireAuth` — an INVESTOR could reach this route.
// `requireAuth` only asserts that a session exists, and the ownership check
// below is gated on `role === "Driver"`, so every other role skipped it: Super
// Admin and Dispatcher legitimately, and **Investor** by omission. There are 3
// Investor accounts on production. Every other Job Tracking surface is properly
// scoped (`GET /api/data`, `/api/dashboard`, `/api/load/:loadId` are all
// requireRole("Super Admin","Dispatcher")); this route was the hole.
//
// It mattered before this PR because an Investor could WRITE a status to an
// arbitrary row. It matters differently now: the load binding below answers
// "which row is load X on?" precisely (`ROW_LOAD_MISMATCH` names the row), so
// leaving the route open would have converted a blind write into an accurate
// row-location oracle for any load id an investor can already see on their own
// portal. Narrowing the write while widening the read is the wrong trade — so
// the role gate closes both at once.
//
// No client changes: all three callers are Driver or admin surfaces
// (client/src/stores/driver.js, client/src/stores/dashboard.js,
// public/driver.html). Mounted BEFORE driverWriteLimiter, matching the
// convention on the fuel-events/fuel-gallons routes, so an unauthorized caller
// cannot spend the rate-limit budget on 403s.
app.put("/api/driver/status", requireRole("Super Admin", "Dispatcher", "Driver"), driverWriteLimiter, async (req, res) => {
	try {
		// `rowData` is deliberately NOT destructured any more — see the load-binding
		// block below. Clients still send it and it is simply ignored, so no client
		// needs a change.
		let { rowIndex: rawRowIndex, loadId, newStatus } = req.body;
		const driverName = resolveDriverActor(req, res, req.body.driverName);
		if (driverName === null) return;
		// ⚠️ ROW 1 IS THE HEADER ROW. This route had NO rowIndex validation of any
		// kind — which is why it survived PR #222's sweep for `if (!rowIndex)`,
		// the shape its three siblings carried. The old row re-resolution was
		// gated on `if (rowData && …)` and rowData is OPTIONAL, so `{rowIndex: 1}`
		// with no rowData skipped re-resolution entirely and wrote the Job Tracking
		// HEADER row. Every column in this app is resolved by matching header text,
		// so that one request re-points the dashboard, the driver app,
		// /api/financials, /api/investor, the payout ledger and invoicing at once —
		// silently, with no data row touched and no period guard fired, because no
		// data row WAS touched. Driver-reachable: this is the lowest-privilege
		// write surface in the app. Same helper, status code and body as the
		// siblings, so the four cannot answer differently.
		//
		// ⚠️ `const`, NOT `let` — and that is load-bearing, not tidiness. The whole
		// defect this route carried was that `rowIndex` meant one thing on the way in
		// and another by the time the write happened, because the re-resolution below
		// reassigned it. Nothing reassigns it now, so "the row the caller named is the
		// row that gets written" is true BY CONSTRUCTION rather than by inspection,
		// and the load binding below is what decides whether that row is allowed.
		const rowIndex = resolveSheetDataRow(res, rawRowIndex);
		if (rowIndex === null) return; // 400 already sent

		// ⚠️ `newStatus` WAS UNCONSTRAINED FREE TEXT, on the one status-writing route
		// a **Driver** can reach. PR #223 constrained the admin-only override route and
		// PR #230 closed the locked-month half here, but an OPEN month was unchanged:
		// a driver could write any string at all into the column excludeDroppedLoads()
		// and every completedStatuses branch read — including "Cancelled", which drops
		// the load out of revenue, driver pay and every KPI with none of the reason,
		// notification or `cancel_load` audit that POST /api/dispatch/cancel demands.
		// See STATUS_OVERRIDE_ALLOWED above for why the two routes share one list.
		//
		// Placed AFTER the row guard and BEFORE the ownership check on purpose: it is
		// request validation, not an authorization decision, so it reveals nothing
		// about the load and must not cost an ownership lookup or a full sheet read.
		if (!newStatus || typeof newStatus !== "string") {
			return res.status(400).json({ error: "newStatus is required" });
		}
		// ⚠️ CAP THE LENGTH BEFORE trimming, lower-casing, or echoing it back. The
		// body limit is 50mb and body-parser inflates by default, so a ~50 KB gzip
		// payload expands to a 50 MB string; the INVALID_STATUS branch below echoes
		// the value into the response and this route is Driver-reachable at
		// driverWriteLimiter's 60/min. Refusing early keeps a bad request O(1) instead
		// of several copies of a very large string. 64 clears the longest member of
		// the list ("Heading to Shipper", 18) many times over. Deliberately does NOT
		// echo the value — there is nothing useful to show a caller who sent 50 MB.
		if (newStatus.length > 64) {
			return res.status(400).json({
				error: `That is not a status this route can set. Allowed: ${STATUS_OVERRIDE_ALLOWED.join(", ")}.`,
				code: "INVALID_STATUS",
				allowed: STATUS_OVERRIDE_ALLOWED,
			});
		}
		const canonicalStatus = STATUS_OVERRIDE_ALLOWED.find((s) => s.toLowerCase() === newStatus.trim().toLowerCase());
		if (!canonicalStatus) {
			const cancelling = CANCELED_STATUS_RE.test(newStatus.trim());
			// A cancel attempt lands in the audit trail; an ordinary typo does not —
			// same split as PR #223. This one is a privilege-boundary event (cancel is
			// Super-Admin-only and a Driver can reach this route), so it is worth a
			// trace, while auditing every malformed string would bury that signal.
			// Reuses this route's own `status_update_blocked` action, so a period
			// refusal and a vocabulary refusal read from one place.
			//
			// ⚠️ Two things about this row. (a) `loadId` is caller-supplied and
			// logAudit stores it unbounded, so it is capped here — see the 64-char
			// note above for why a Driver-reachable route cannot trust a body string's
			// length. (b) It is written BEFORE the ownership check below, so a
			// `status_update_blocked` row naming load X is NOT evidence the actor
			// could reach X. That ordering is deliberate (validation is not
			// authorization, and the 400 is byte-identical either way, so it leaks
			// nothing) — but do not read the trail as an access record.
			if (cancelling) {
				// Coalesced like every other refusal on this route — see
				// logAuditRefusal(). A Driver can reach this 60x a minute, and the
				// suppressed count preserves the burst, which is the signal here.
				logAuditRefusal(
					req, "status_update_blocked", "load", String(loadId || "").slice(0, 100),
					`Blocked status write "${newStatus.trim()}" [CANCEL_NOT_A_STATUS_UPDATE] — ${JSON.stringify({ code: "CANCEL_NOT_A_STATUS_UPDATE", periods: [] })}`,
					"CANCEL_NOT_A_STATUS_UPDATE"
				);
			}
			return res.status(400).json({
				error: cancelling
					? "Cancelling a load is not a status update. Use POST /api/dispatch/cancel (Super Admin), which records the reason, notifies the driver and audits the cancellation — a cancelled load drops out of revenue and every KPI, so it must not be set silently."
					: `'${newStatus}' is not a status this route can set. Allowed: ${STATUS_OVERRIDE_ALLOWED.join(", ")}.`,
				// Twin of PR #223's CANCEL_NOT_AN_OVERRIDE: same policy, named for the
				// route the operator actually called, since this one is not an override.
				code: cancelling ? "CANCEL_NOT_A_STATUS_UPDATE" : "INVALID_STATUS",
				allowed: STATUS_OVERRIDE_ALLOWED,
			});
		}
		// Everything downstream — the one-active-job 409, the POD gate, the period
		// guard, the sheet write, the socket event, the dispatch feed, the audit line
		// and load_status_history — must see the CANONICAL spelling, never the raw
		// request string. Reassigning the destructured binding (already `let`, like
		// `rowIndex` below) is what makes that true by construction: it leaves no site
		// that could still read the caller's version, which a separate variable would.
		newStatus = canonicalStatus;

		// SECURITY: drivers can only update loads assigned to them.
		// Admin/Dispatcher use the /api/loads/:loadId/status-override flow,
		// which has its own audit/reason gate, so this guard is Driver-only.
		if (req.session.user.role === "Driver") {
			const owned = await loadBelongsToDriver(loadId, driverName);
			if (!owned) return res.status(403).json({ error: "This load is not assigned to you" });
		}
		const sheets = await getSheets();

		// Headers + EVERY data row in one round trip. This route always read the
		// whole tab; routing it through the shared helper means the binding below,
		// the one-active-job scan and the period guard all judge one snapshot, and
		// costs no extra Sheets call (the 300/min quota counts requests, not bytes).
		const snapshot = await readJobTrackingSnapshot(sheets, rowIndex);
		if (!snapshot) {
			// The sheet could not be read, so the row cannot be confirmed to hold this
			// load. Refusing is the only answer that is not a guess, and unlike a
			// period refusal, retrying costs nothing once the read works.
			return sendLoadBindRefusal(
				req, res,
				{
					http: 503,
					code: "SHEET_UNREADABLE",
					error: "Job Tracking could not be read, so the server cannot confirm that this row holds the load you are updating. Nothing was changed. Try again in a moment.",
				},
				"status_update_blocked", loadId, `setting row ${rowIndex} to "${newStatus}"`
			);
		}
		const headers = snapshot.headers;
		const dataRows = snapshot.rows;

		// ⚠️ LOAD BINDING — REPLACES A THREE-STEP `rowMatchesData` RE-RESOLUTION THAT
		// WAS NOT A BINDING AT ALL. PR #248 fixed the four sibling routes and reported
		// this one; it is the LIVE hole, because the POD gate, the audit line, the
		// socket, the dispatch feed and load_status_history all key on the CLAIMED
		// `loadId` while the sheet write went to the caller's `rowIndex` — so a Driver
		// holding a genuine POD for their own load could stamp "Delivered" + a
		// Completion Date onto an ARBITRARY row, including another driver's live load
		// and including a completed one in a closed month.
		//
		// The old code failed on three independent counts, and all three are gone:
		//   1. `rowData` WAS OPTIONAL and the whole re-resolution was gated on it
		//      (`if (rowData && !rowMatchesData(...))`). Omit it and nothing was
		//      re-resolved or compared — the write simply went to `rowIndex`. Not
		//      hypothetical: the legacy public/driver.html posts `values`, NOT
		//      `rowData`, so that client has always taken the ungated path.
		//   2. EVEN SUPPLIED IT WAS NOT A LOAD-ID CHECK. It compared only NON-EMPTY
		//      expected values, so `{}` matched every row, and it need not contain the
		//      Load ID column at all. `rowData` is caller-supplied, so this bound the
		//      write to the caller's own assertion rather than to evidence about the
		//      load — the thing a guard must never do.
		//   3. ITS FALLBACK SILENTLY RETARGETED to the LAST row carrying the id,
		//      last-match-wins across the 87 duplicated ids on this sheet — the guess
		//      #223 refused. So `rowIndex` was advisory in one branch and authoritative
		//      in the other: two trust models in one handler.
		//
		// `rowMatchesData` does NOT survive in any form, and that is deliberate rather
		// than incidental. Once the binding has proved that `rowIndex` holds `loadId`,
		// a rowData comparison could only ever move the write AWAY from a correctly
		// bound row — and it would do so routinely, because rowData carries the status
		// the client last saw and geofence auto-advance (live since 2026-08-05) rewrites
		// that server-side behind the client's back. Keeping it would re-introduce the
		// retarget under a guard built to stop retargeting.
		//
		// `rowData` is still ACCEPTED in the body and ignored, so no client needs a
		// change; it is simply no longer consulted.
		{
			const unbound = resolveLoadBinding(headers, dataRows, rowIndex, loadId, {
				// ⚠️ See the rung-4 ⚠️ in resolveLoadBinding(): measured on the
				// production sheet, a blanket AMBIGUOUS_LOAD would have refused 4 real
				// driver taps on load 7052901 and stranded the driver mid-load. The
				// caller's row must still carry the caller's own load id.
				callerRowWinsAmongDuplicates: true,
			});
			if (unbound) {
				return sendLoadBindRefusal(
					req, res, unbound, "status_update_blocked", loadId,
					`setting row ${rowIndex} to "${newStatus}"`
				);
			}
		}

		const statusIdx = headers.findIndex((h) => /status/i.test(h));
		const dateIdx = headers.findIndex((h) => /status.*update.*date|update.*date/i.test(h));

		if (statusIdx === -1) {
			return res.status(400).json({ error: "Status column not found in sheet" });
		}

		// Enforce one active job at a time: block transition to "At Shipper" if another load is active
		//
		// ⚠️ "ANOTHER JOB" IS ANOTHER LOAD ID, NOT ANOTHER ROW. This scan used to
		// exclude only the caller's own row index, which silently assumed one row per
		// load — and `dataRows` comes from readJobTrackingSnapshot(), the RAW whole-tab
		// read, so deduplicateLoads() has NOT run and duplicates are present by
		// construction (87 of 288 distinct load ids sit on 2+ rows). A second live row
		// for the caller's OWN load, same driver, active status therefore read as "you
		// already have an active job" and 409'd the driver off their own load, with the
		// only remedy — delete the stale row — being Super-Admin-only. That is the
		// shape of guard #211 warns gets switched off, at which point it protects
		// nothing.
		//
		// The policy is not invented here: it is the SAME one resolveLoadBinding() was
		// given ten lines above via the callerRowWinsAmongDuplicates opt-in (spelled
		// out there, and deliberately not repeated verbatim here — the family-coherence
		// check in scripts/test-driver-status-row-binding.js counts that literal across
		// the whole file to prove exactly one route opts in, and a prose copy would
		// defeat it, which is the same trap its own "COMMENTS STRIPPED FIRST" note
		// describes), and for the same measured reason (load 7052901: row 383 live,
		// row 388 a cancelled "#7052901" copy). Having the binding accept a
		// duplicated id and then having the very next guard refuse the caller
		// BECAUSE it is duplicated is the two halves of one route disagreeing about
		// what a load is.
		//
		// Skipping on the id is strictly NARROWER than "skip everything for this
		// driver": a genuine second load still 409s, because its id differs. It cannot
		// be widened by a blank cell either — `callerLoadKey` is guaranteed non-empty
		// (resolveLoadBinding's rung 1 already refused a blank id), and it is tested
		// explicitly so the skip is provably inert if that ever stops being true, since
		// otherwise every id-less row would be skipped. `loadIdIdx` is likewise
		// guaranteed >= 0 by the binding's rung 2; the check is defence in depth.
		// The row-index test is kept as well — it costs nothing and is the only cover
		// if a future edit moves this scan above the binding.
		if (/^at shipper$/i.test(newStatus)) {
			const driverCol = headers.findIndex((h) => /driver/i.test(h));
			if (driverCol !== -1) {
				const activeRe = /^(heading to shipper|at shipper|loading|in transit|at receiver)$/i;
				const driverNameNorm = normalizeDriverName(driverName);
				// normLoadKey(), not a raw compare: Job Tracking stores both "513987502"
				// and "#513987502", so a raw compare would fail to recognise the caller's
				// own duplicate exactly when it is spelled the other way — which is the
				// commonest way a duplicate arises. Same normaliser the binding uses.
				const loadIdIdx = headers.findIndex((h) => /load.?id|job.?id/i.test(h));
				const callerLoadKey = normLoadKey(loadId);
				const hasActive = dataRows.some((row, i) => {
					const rIdx = i + 2;
					if (rIdx === rowIndex) return false;
					if (callerLoadKey && loadIdIdx !== -1
						&& normLoadKey((row || [])[loadIdIdx]) === callerLoadKey) return false;
					const drv = normalizeDriverName(row[driverCol]);
					const sts = (row[statusIdx] || "").trim();
					return drv === driverNameNorm && activeRe.test(sts);
				});
				if (hasActive) {
					return res.status(409).json({
						code: "ACTIVE_JOB_CONFLICT",
						error: "You already have an active job. Complete it before starting another.",
					});
				}
			}
		}

		// POD gate: require at least one POD document before allowing a delivered/completed transition.
		// CEO requirement (2026-05-05): drivers and dispatchers cannot mark Delivered without proof.
		// Backend enforcement covers the dispatcher dropdown bypass that the client-side gate misses.
		// `deleted_at IS NULL` is load-bearing: without it a soft-deleted POD would
		// still satisfy the gate, and the load could reach Delivered with no
		// attachable proof — exactly the state DELETE /api/documents/:id refuses to create.
		if (/^(delivered|completed|pod received)$/i.test((newStatus || "").trim())) {
			const podRow = db
				.prepare("SELECT COUNT(*) AS n FROM documents WHERE load_id = ? AND UPPER(type) = 'POD' AND deleted_at IS NULL")
				.get(loadId || "");
			if (!podRow || podRow.n === 0) {
				return res.status(409).json({
					code: "POD_REQUIRED",
					error: "Upload a Proof of Delivery (POD) before marking this load as Delivered.",
				});
			}
		}

		// Read verified row to get old status for logging
		const currentRow = dataRows[rowIndex - 2] || [];
		const oldStatus = currentRow[statusIdx] || "";

		// Build batch update for status column + date column
		const now = new Date();
		// Houston wall-clock, NOT server-local: this box runs UTC, so the old
		// getter-based build stamped evening deliveries with tomorrow's date.
		// See houstonStamp() — the date part here decides revenue month,
		// invoice week, and driver-pay day.
		const dateTime = houstonStamp(now);

		// PERIOD GUARD — on the FINAL resolved row, after the re-resolution above,
		// so it judges the row that actually gets written and not the one the
		// caller claimed. This is the last unguarded path to a completed status:
		// PUT /api/loads/:loadId/status-override got the same treatment in PR #223
		// and is admin-only, so without this a Driver could book a load into a
		// settled month by the route built for them. Mid-trip statuses (At
		// Shipper, In Transit, At Receiver) move $0 and stay unblocked in any
		// month; crossing the completed boundary in either direction does not.
		{
			const before = sheetRowToObject(headers, currentRow);
			const edits = {};
			if (headers[statusIdx]) edits[headers[statusIdx]] = newStatus;
			// The dates this route stamps are part of the AFTER state — inert on
			// production's header order, but see dispatchWriteBlocker() test 2.
			if (dateIdx !== -1 && headers[dateIdx]) edits[headers[dateIdx]] = dateTime;
			if (/^(delivered|completed|pod received)$/i.test(newStatus)) {
				const cIdx = headers.findIndex((h) => /completion.*date/i.test(h));
				if (cIdx !== -1 && headers[cIdx]) edits[headers[cIdx]] = dateTime;
			}
			const blocked = dispatchWriteBlocker(headers, before, edits);
			if (blocked) {
				return sendDispatchRefusal(
					req, res, blocked, "status_update_blocked", loadId,
					`Setting load ${loadId || "(unknown)"} to "${newStatus}"`
				);
			}
		}

		const updateData = [
			{ range: `Job Tracking!${colLetter(statusIdx)}${rowIndex}`, values: [[newStatus]] },
		];
		if (dateIdx !== -1) {
			updateData.push({ range: `Job Tracking!${colLetter(dateIdx)}${rowIndex}`, values: [[dateTime]] });
		}
		// Write Completion Date when status is a completed status
		if (/^(delivered|completed|pod received)$/i.test(newStatus)) {
			const compDateIdx = headers.findIndex((h) => /completion.*date/i.test(h));
			if (compDateIdx !== -1) {
				updateData.push({ range: `Job Tracking!${colLetter(compDateIdx)}${rowIndex}`, values: [[dateTime]] });
			}
		}

		await sheets.spreadsheets.values.batchUpdate({
			spreadsheetId: SPREADSHEET_ID,
			requestBody: {
				valueInputOption: "USER_ENTERED",
				data: updateData,
			},
		});

		// Notify dispatch in real-time
		jtCacheInvalidate();
		io.to("dispatch").emit("status-updated", { loadId, driverName, newStatus });
		insertDispatchNotification.run(
			'status-updated',
			`${driverName}: ${newStatus}`,
			`Load ${loadId}`,
			JSON.stringify({ loadId, driverName, newStatus })
		);
		io.to("dispatch").emit("dispatch-notification", {
			type: 'status-updated',
			title: `${driverName}: ${newStatus}`,
			body: `Load ${loadId}`,
		});

		logAudit(req, 'update_status', 'load', loadId, `Status changed to "${newStatus}" for load ${loadId} (driver: ${driverName})`);
		recordStatusChange({ loadId, oldStatus, newStatus, source: 'manual', actor: driverName });
		res.json({ success: true });
	} catch (error) {
		console.error("Error updating driver status:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// May this status override be written? Returns null to allow, else the 409 body.
//
// ⚠️ THE UNION OF BEFORE AND AFTER, exactly as sheetRowUpdateBlocker() spells out
// at length — read that comment, it is the canonical statement of this problem.
// Two things make it non-obvious that this route needs it:
//
//   • BEFORE covers the RESURRECTION, and it does so only because
//     loadRowPeriods() is deliberately status-blind. 26 rows sit at
//     "Cancelled"/"Canceled" and are dropped from every aggregate by
//     excludeDroppedLoads(), so a guard phrased as "does this row contribute to a
//     locked month TODAY?" answers *no* for all of them and waves the write
//     through. 25 of those 26 are inside a locked month and carry $29,166.25
//     between them (the 26th, load 512441414, sits in an unlocked 2025-04) — so
//     flipping them to "Delivered" INJECTS that money into closed months,
//     including load 554481641, $4,100, assigned 2026-06, a month whose payout is
//     already `paid`. Asking loadRowPeriods() instead — which reads dates and
//     never looks at the status — gets that right for free, and is why no
//     status-aware predicate belongs here. (Counts measured 2026-08-09; recount
//     the CANCELLED rows and you get 26, not 25. The gap is the unlocked one.)
//   • AFTER covers the DATES THIS ROUTE ITSELF WRITES. It stamps Status Update
//     Date and sets or clears Completion Date, and jobTrackingMonthCols().dateCol
//     matches `status.*update.*date|completion.*date|assigned.*date` on the FIRST
//     header that hits. On production "Assigned Date" sits ahead of both, so the
//     revenue month is untouched and the after-state is inert — but that is header
//     luck, not a property of the route. On a sheet resolving to Status Update
//     Date this write MOVES the load's revenue month to today (into a locked
//     current month, if one was closed early), and on one resolving to Completion
//     Date clearing the cell makes the month unresolvable. A before-only guard
//     cannot see either, by construction.
//
// Fails closed on an unreadable period_locks and on a row whose months cannot be
// resolved on EITHER side. Not gated on PERIOD_FINALIZE_ENABLED, matching
// isLocked() and every other lock guard: flag off means period_locks is empty,
// nothing is locked, and this costs one indexed SELECT.
//
// `rows` are header-keyed Job Tracking rows (parseSheet's shape) — EVERY row
// carrying the load id, not the last one. `edits` is the header-keyed delta the
// write would apply, i.e. after = {...before, ...edits}.
function statusOverrideBlocker(headers, rows, edits) {
	if (!periodLocksReadable()) {
		return {
			code: "PERIOD_LOCK_UNREADABLE",
			periods: [],
		};
	}
	const cols = jobTrackingMonthCols(headers);
	const periods = new Set();
	let allResolved = true;
	for (const before of rows) {
		const after = { ...before, ...edits };
		for (const side of [before, after]) {
			const p = loadRowPeriods(side, cols);
			if (!p.resolved) allResolved = false;
			p.periods.forEach((m) => periods.add(m));
		}
	}

	// PERIOD_FINALIZED outranks the other two: when a row both names a closed
	// month and carries an unreadable date, "this would restate June" is the
	// answer the operator can act on, and the remedy (reopen the period) is the
	// same either way.
	const locked = lockedAmong([...periods]);
	if (locked.length) return { code: "PERIOD_FINALIZED", periods: locked };

	// A row whose dates cannot be read could be booked anywhere, including a
	// closed month. Same asymmetry as everywhere else: refusing costs a retry,
	// permitting costs a restated settlement nobody can see happen.
	if (!allResolved) return { code: "PERIOD_UNRESOLVED", periods: [] };

	// AMBIGUITY IS A REFUSAL, NOT A TIE-BREAK. The old loop took the LAST matching
	// row, and 87 load ids inside locked months sit on 2+ rows — so the write could
	// land on a row other than the one the modal displayed, silently, with the
	// audit naming a load id that identifies neither. There is no correct guess:
	// the request carries a load id and nothing else, so nothing in it distinguishes
	// the rows. (Reached only after the period checks above, which have already
	// judged EVERY candidate row, so an ambiguous load in a closed month is told
	// about the closed month first.)
	if (rows.length > 1) return { code: "AMBIGUOUS_LOAD", periods: [] };

	return null;
}

// PUT /api/loads/:loadId/status-override — Admin status reversion
//
// CEO requirement (2026-05-05): Super Admins and Dispatchers must be able to
// revert a load that was tagged with the wrong status (e.g. accidentally
// marked Delivered before POD was uploaded). Bypasses the POD gate that
// blocks PUT /api/driver/status — that's the whole point of an override.
// Every override is reason-tagged and audit-logged.
//
// ⚠️ PERIOD-GUARDED, same three fail-closed rungs as DELETE /api/loads/:loadId.
// This was the last route that could rewrite a settled month: it writes Job
// Status — the column excludeDroppedLoads() and every `completedStatuses` test
// branch on — with no period check of any kind. Measured on production
// 2026-08-09: 407 of 421 rows sit in locked periods, $313,922.93 of completed-load
// revenue erasable from closed months, plus the $29,166.25 of resurrection
// described on statusOverrideBlocker() above.
app.put("/api/loads/:loadId/status-override", requireRole("Super Admin", "Dispatcher"), async (req, res) => {
	try {
		const { loadId } = req.params;
		const { newStatus, reason } = req.body || {};
		if (!newStatus || typeof newStatus !== "string") {
			return res.status(400).json({ error: "newStatus is required" });
		}
		// Record every refusal. `super_admin` is a shared login, so a refusal that
		// left no trace would make a repeated attempt to rewrite a closed month
		// invisible in the one place anyone looks afterwards.
		//
		// logAuditRefusal, not logAudit, and the code is now passed. Two things
		// follow. (1) Every PERIOD_* cause is in UNCOALESCED_REFUSAL_CODES, so those
		// rows are byte-identical to before — a settlement refusal is still written
		// in full, one per attempt, with its own load id. (2) The non-period cause
		// this arrow also carries, CANCEL_NOT_AN_OVERRIDE, is reachable on demand by
		// any Dispatcher retyping "Cancelled", so it coalesces to one row per minute
		// per account — the trace the comment above asks for, without the flood.
		// `super_admin` is a shared login, so the coalesce key is the ACCOUNT and the
		// row identifies a session, never an individual.
		const auditBlocked = (code, periods, statusLabel) => logAuditRefusal(
			req, "status_override_blocked", "load", loadId,
			`Blocked override to "${statusLabel}" [${code}]${(periods || []).length ? ` periods=${periods.join(",")}` : ""} — ${JSON.stringify({ code, periods: periods || [] })}`,
			code
		);

		// Canonicalize against the allowlist. See STATUS_OVERRIDE_ALLOWED above for
		// why "Cancelled" is refused here rather than silently accepted.
		const canonicalStatus = STATUS_OVERRIDE_ALLOWED.find((s) => s.toLowerCase() === newStatus.trim().toLowerCase());
		if (!canonicalStatus) {
			const cancelling = CANCELED_STATUS_RE.test(newStatus.trim());
			// A cancel attempt lands in the audit trail; an ordinary typo does not.
			// This one is a privilege-boundary event — POST /api/dispatch/cancel is
			// Super Admin only and this route is not — so a Dispatcher reaching for it
			// is worth a trace, while auditing every malformed string would bury that
			// signal in noise.
			if (cancelling) auditBlocked("CANCEL_NOT_AN_OVERRIDE", [], newStatus.trim());
			return res.status(400).json({
				error: cancelling
					? "Cancelling a load is not an override. Use POST /api/dispatch/cancel (Super Admin), which records the reason, notifies the driver and audits the cancellation — a cancelled load drops out of revenue and every KPI, so it must not be set silently."
					: `'${newStatus}' is not a status this override can set. Allowed: ${STATUS_OVERRIDE_ALLOWED.join(", ")}.`,
				code: cancelling ? "CANCEL_NOT_AN_OVERRIDE" : "INVALID_STATUS",
				allowed: STATUS_OVERRIDE_ALLOWED,
			});
		}
		if (!reason || typeof reason !== "string" || reason.trim().length < 5) {
			return res.status(400).json({ error: "reason is required (min 5 chars)" });
		}

		// RUNG 1 — fail CLOSED before anything else: isLocked() swallows every error
		// and answers "not locked", so an unreadable period_locks would leave the
		// guard present, silent and open.
		if (!periodLocksReadable()) {
			auditBlocked("PERIOD_LOCK_UNREADABLE", [], canonicalStatus);
			// AUDITED_UPSTREAM: auditBlocked() above wrote this refusal's row.
			return sendPeriodRefusal(req, res, "unreadable", null, null, AUDITED_UPSTREAM);
		}

		// RUNG 2 — a failed sheet read REFUSES. It used to fall through to a generic
		// 500, which is fail-closed by accident rather than by decision; now the
		// months depend on this read, and the months are exactly what cannot be
		// guessed at.
		const sheets = await getSheets();
		let sheetRes;
		try {
			sheetRes = await sheets.spreadsheets.values.get({
				spreadsheetId: SPREADSHEET_ID,
				range: "Job Tracking",
			});
		} catch (e) {
			console.error("Status override blocked — Job Tracking unreadable:", e.message);
			auditBlocked("PERIOD_UNRESOLVED", [], canonicalStatus);
			return sendPeriodRefusal(req, res, "unresolved", null, `Load ${loadId}`, AUDITED_UPSTREAM);
		}
		const allRows = sheetRes.data.values || [];
		const headers = allRows[0] || [];
		const dataRows = allRows.slice(1);

		const statusIdx = headers.findIndex((h) => /status/i.test(h));
		const dateIdx = headers.findIndex((h) => /status.*update.*date|update.*date/i.test(h));
		const compDateIdx = headers.findIndex((h) => /completion.*date/i.test(h));
		const loadIdIdx = headers.findIndex((h) => /load.?id|job.?id/i.test(h));
		const driverIdx = headers.findIndex((h) => /driver/i.test(h));

		if (statusIdx === -1 || loadIdIdx === -1) {
			return res.status(400).json({ error: "Status or Load ID column not found in sheet" });
		}
		// The three write targets must be three distinct columns. `/status/i` also
		// matches "Status Update Date", so a sheet with no plain status column
		// resolves statusIdx and dateIdx to the same cell — the route would then
		// write it twice with different values, and `edits` (keyed by header name)
		// would collapse to one entry describing a state the sheet never reaches.
		// Refuse rather than write a delta the guard did not judge.
		if (dateIdx === statusIdx || compDateIdx === statusIdx || (dateIdx !== -1 && dateIdx === compDateIdx)) {
			return res.status(400).json({
				error: "Job Tracking's status and date columns cannot be told apart, so this override cannot be applied safely.",
				code: "SHEET_COLUMNS_AMBIGUOUS",
			});
		}

		// EVERY row carrying this load id, not the last one — see the AMBIGUOUS_LOAD
		// note on statusOverrideBlocker(). The guard has to answer for all of them
		// because nothing in the request says which was meant.
		const targetLid = loadId.toString().trim().toLowerCase().replace(/^#/, "");
		const matches = [];
		for (let i = 0; i < dataRows.length; i++) {
			const lid = (dataRows[i][loadIdIdx] || "").toString().trim().toLowerCase().replace(/^#/, "");
			if (lid === targetLid) matches.push({ row: dataRows[i], rowIndex: i + 2 });
		}
		if (!matches.length) {
			return res.status(404).json({ error: `Load ${loadId} not found` });
		}

		const now = new Date();
		// Houston wall-clock, NOT server-local: this box runs UTC, so the old
		// getter-based build stamped evening deliveries with tomorrow's date.
		// See houstonStamp() — the date part here decides revenue month,
		// invoice week, and driver-pay day.
		const dateTime = houstonStamp(now);
		// Reverting away from a completed status: clear the Completion Date so the
		// column doesn't lie. Setting to a completed status: populate it.
		const isCompletion = /^(delivered|completed|pod received)$/i.test(canonicalStatus);

		// RUNG 3 — the period guard, over the union of before and after for EVERY
		// candidate row. `edits` is byte-identical to the cells written below; both
		// are built from the same three values so the state judged and the state
		// written cannot drift apart.
		const edits = { [headers[statusIdx]]: canonicalStatus };
		if (dateIdx !== -1) edits[headers[dateIdx]] = dateTime;
		if (compDateIdx !== -1) edits[headers[compDateIdx]] = isCompletion ? dateTime : "";
		const asObject = (arr) => {
			const o = {};
			headers.forEach((h, i) => { o[h] = arr[i] == null ? "" : arr[i]; });
			return o;
		};
		const blocker = statusOverrideBlocker(headers, matches.map((m) => asObject(m.row)), edits);
		if (blocker) {
			auditBlocked(blocker.code, blocker.periods, canonicalStatus);
			// AUDITED_UPSTREAM on all three: auditBlocked() one line above wrote the
			// row, and it did so for the AMBIGUOUS_LOAD branch below too.
			if (blocker.code === "PERIOD_LOCK_UNREADABLE") return sendPeriodRefusal(req, res, "unreadable", null, null, AUDITED_UPSTREAM);
			if (blocker.code === "PERIOD_UNRESOLVED") return sendPeriodRefusal(req, res, "unresolved", null, `Load ${loadId}`, AUDITED_UPSTREAM);
			if (blocker.code === "PERIOD_FINALIZED") {
				return sendPeriodRefusal(req, res, "finalized", blocker.periods, `Changing the status of load ${loadId}`, AUDITED_UPSTREAM);
			}
			return res.status(409).json({
				error: `Load ${loadId} appears on ${matches.length} rows of Job Tracking (${matches.map((m) => m.rowIndex).join(", ")}), so the server cannot tell which one this override means. Give the duplicate rows distinct load ids — or remove the stale one — and try again.`,
				code: "AMBIGUOUS_LOAD",
				rowIndices: matches.map((m) => m.rowIndex),
			});
		}

		const { row: currentRow, rowIndex } = matches[0];
		const oldStatus = currentRow[statusIdx] || "";
		const driverName = driverIdx !== -1 ? (currentRow[driverIdx] || "") : "";

		// Written straight out of `edits`, so what the guard judged and what lands in
		// the sheet are the same three values by construction.
		const updateData = [
			{ range: `Job Tracking!${colLetter(statusIdx)}${rowIndex}`, values: [[edits[headers[statusIdx]]]] },
		];
		if (dateIdx !== -1) {
			updateData.push({ range: `Job Tracking!${colLetter(dateIdx)}${rowIndex}`, values: [[edits[headers[dateIdx]]]] });
		}
		if (compDateIdx !== -1) {
			updateData.push({
				range: `Job Tracking!${colLetter(compDateIdx)}${rowIndex}`,
				values: [[edits[headers[compDateIdx]]]],
			});
		}

		await sheets.spreadsheets.values.batchUpdate({
			spreadsheetId: SPREADSHEET_ID,
			requestBody: { valueInputOption: "USER_ENTERED", data: updateData },
		});

		jtCacheInvalidate();
		const overrideUser = req.session?.user?.username || "admin";
		// canonicalStatus, never the raw `newStatus`: the socket event, the dispatch
		// feed, the status history and the audit line must all say what actually
		// landed in the cell, or a lowercase request leaves four records disagreeing
		// with the sheet.
		const detailMsg = `Override: "${oldStatus}" → "${canonicalStatus}" — ${reason.trim()}`;
		io.to("dispatch").emit("status-updated", { loadId, driverName, newStatus: canonicalStatus });
		insertDispatchNotification.run(
			'status-override',
			`${driverName || "Load"}: ${canonicalStatus} (override)`,
			detailMsg,
			JSON.stringify({ loadId, driverName, newStatus: canonicalStatus, oldStatus, reason: reason.trim(), by: overrideUser })
		);
		io.to("dispatch").emit("dispatch-notification", {
			type: 'status-override',
			title: `${driverName || "Load"}: ${canonicalStatus} (override)`,
			body: detailMsg,
		});

		logAudit(req, 'status_override', 'load', loadId, `Override "${oldStatus}" → "${canonicalStatus}" by ${overrideUser}: ${reason.trim()}`);
		recordStatusChange({ loadId, oldStatus, newStatus: canonicalStatus, source: 'override', actor: overrideUser });
		res.json({ success: true, oldStatus, newStatus: canonicalStatus });
	} catch (error) {
		console.error("Error overriding load status:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// computeStatusPhases(loadId) — derive the per-phase timeline for one load from
// the load_status_history table. Each transition opens a phase whose end is the
// next transition's start; the last phase is in-progress unless its status is
// terminal. Returns Array<{ status, source, actor, reason, startedAt, endedAt,
// durationMs, inProgress, terminal }>. Shared by the auth-protected
// /api/loads/:loadId/status-history route (which returns phases WITH actor and
// reason) and the public tracker (which strips BOTH — no driver names, and no
// internal cancellation note). Forward-only: loads that predate this feature
// yield an empty array.
function computeStatusPhases(loadId) {
	const lid = (loadId || "").toString().trim().toLowerCase().replace(/^#/, "");
	const rows = db.prepare(
		`SELECT new_status AS newStatus, source, actor, reason,
		        strftime('%Y-%m-%dT%H:%M:%SZ', changed_at) AS at
		 FROM load_status_history
		 WHERE load_id = ?
		 ORDER BY changed_at ASC, id ASC`
	).all(lid);

	// Each transition opens a phase; its end = the next transition's start.
	// The last phase is in-progress unless its status is terminal.
	const TERMINAL_RE = /^(delivered|completed|pod received|cancel|canceled|cancelled)$/i;
	return rows.map((r, i) => {
		const next = rows[i + 1];
		const startedAt = r.at;
		const endedAt = next ? next.at : null;
		const durationMs = endedAt ? (new Date(endedAt) - new Date(startedAt)) : null;
		const terminal = !next && TERMINAL_RE.test((r.newStatus || "").trim());
		return {
			status: r.newStatus,
			source: r.source,
			actor: r.actor,
			// Internal — why a load was cancelled. Stripped for the public
			// tracker alongside actor (see the /api/public/track whitelist);
			// a customer must never read dispatch's internal note.
			reason: r.reason || "",
			startedAt,
			endedAt,
			durationMs,
			inProgress: !next && !terminal,
			terminal,
		};
	});
}

// GET /api/loads/:loadId/status-history — per-phase timeline for one load.
// Returns a derived phases[] (started/ended/duration), computed server-side so
// the driver app and the admin modals render identical numbers. Roles: Super
// Admin + Dispatcher see any load; a Driver only their own (same ownership gate
// the write paths use). Forward-only: loads that predate this feature return an
// empty array (the UI shows a friendly empty state).
app.get("/api/loads/:loadId/status-history", requireAuth, async (req, res) => {
	try {
		const rawId = (req.params.loadId || "").trim();
		if (!rawId || !/^[A-Za-z0-9\-_.#]{1,40}$/.test(rawId)) {
			return res.status(400).json({ error: "Invalid load id" });
		}
		const role = req.session.user.role;
		if (role === "Driver") {
			const owned = await loadBelongsToDriver(rawId, req.session.user.driverName || "");
			if (!owned) return res.status(403).json({ error: "This load is not assigned to you" });
		} else if (role !== "Super Admin" && role !== "Dispatcher") {
			return res.status(403).json({ error: "Forbidden" });
		}

		const phases = computeStatusPhases(rawId);
		res.json({ loadId: rawId, phases });
	} catch (error) {
		console.error("status-history error:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// An export walks every Job Tracking row and resolves an address per row, so it
// is real work on top of the (cached) sheet read — but it is user-initiated,
// read-only, and trivially re-requested when a download fails. Same shape and
// rationale as statementLimiter: generous enough for real use (an owner pulling
// a handful of driver histories in one sitting), tight enough that a
// refresh-hammer can't pin the box.
const exportLimiter = rateLimit({
	windowMs: 15 * 60 * 1000,
	max: 20,
	message: { error: "Too many exports. Try again in a few minutes." },
	standardHeaders: true,
});

// WHICH DAY A LOAD BELONGS TO — read LITERALLY off the cell, on purpose.
//
// Cells arrive in THREE shapes, all verified against prod:
//   ISO      "2026-07-31" / "2026-07-15T13:28:33.000Z"  (n8n, reassign endpoint)
//   US slash "7/15/2026 14:31:58" / "8/3/2026, 2:15:49 PM"  (Apps Script/manual)
//   RFC 2822 "Date: Thu, 19 Jun 2025 08:16:37 -0500"    (n8n stamps the raw
//            email header on rate-con-ingested loads — 103 of 258 completed
//            rows carry Assigned Date in this form today)
// The date is taken VERBATIM off the front of the cell — no timezone conversion,
// whatever shape the cell is in. This helper does NOT convert and must not start
// doing so: its job is to agree with the accounting, not to be independently
// right. Bucketing on the VIEWER's zone would be worse still — the same export
// would then contain different loads depending on who clicked it.
//
// This used to convert to America/Chicago via localDayInTz(). It no longer calls
// that (or any zone lookup) — the export has to land on the day the P&L already
// used. Load 558865809 was the live case: stored 7/1, displayed Jun 30, revenue
// counted in JULY, so a June export listed a load whose money was not in June.
// Making the accounting convert instead would have moved revenue into a closed
// month, which the client's rule forbids ("if it is already closed and locked by
// the month then follow that date"). The client filters on the same literal
// basis; keep them together.
//
// WHAT THE MONEY PATHS ACTUALLY DO. This comment used to claim every one of them
// "reads this column's date part literally". That is false, and the exceptions
// matter before you trust a reconciliation. Verified under TZ=UTC, which is what
// the VPS runs:
//
//   parseSheetDate (x4)  literal for ISO and US slash. It returns null on RFC
//                        2822, and every call site USED TO BE
//                        `parseSheetDate(v) || new Date(v)` — a fallback that
//                        honored the offset and was then read back through
//                        server-local getters, so "19 Jun 2025 20:16:37 -0500"
//                        bucketed as Jun 20 here and Jun 19 in this helper.
//                        FIXED 2026-08-08: those call sites now go through
//                        moneySheetDate(), which reads RFC 2822 literally, so
//                        the money day and this helper's day AGREE. Verified
//                        read-only on production: the resolved month changed on
//                        zero of 421 rows, so nothing was restated.
//   parseInvoiceDate     had NO ISO branch, so both ISO and RFC 2822 fell
//                        through to new Date() + server-local getters — the same
//                        Jun 19 -> Jun 20 shift. FIXED 2026-08-09: it now calls
//                        THIS helper and builds a local-midnight Date from the
//                        key, so the days it pays and the week it is paid in are
//                        decided by one function.
//   invoice-week filter  FIXED EARLIER, in #184: it was
//                        new Date(raw).toISOString(), an outright conversion to
//                        UTC, and is now sheetDayKey(). The paragraph that used
//                        to sit here still described the toISOString version and
//                        was read in good faith as a live bug months after it was
//                        gone. A comment asserting a defect is a claim with a
//                        shelf life — re-read the code before trusting one.
//
// EVERY reader of this column now agrees with this helper. The week path
// (the filter, driversWithCompletedLoadsInWeek and parseInvoiceDate) resolves
// through sheetDayKey; the month path resolves through moneySheetDate. Those two
// differ on exactly one shape — an ISO stamp with a trailing offset, which this
// helper converts to the Houston day and moneySheetDate reads literally — and
// that split is deliberate: see the `Z` note above for why the week converts, and
// moneySheetDate's header for why settled months do not.
//
// Cost is limited to history: since 2026-08-03 the server stamps Houston time,
// so the stored date IS the business day and literal == correct. Only
// pre-cutover evening loads read a day off, and for those the recorded date is
// the one that was settled on.
// Returns "YYYY-MM-DD", or "" when nothing is parseable.
const RFC2822_MONTHS = ["jan", "feb", "mar", "apr", "may", "jun", "jul", "aug", "sep", "oct", "nov", "dec"];
function sheetDayKey(val) {
	// The "Date: " prefix is part of the copied email header (the dashboard's
	// completed-sort strips the same thing before parsing).
	const s = String(val ?? "").replace(/^Date:\s*/i, "").trim();
	if (!s) return "";
	const p2 = (n) => String(parseInt(n, 10)).padStart(2, "0");

	// ISO first — the US M/D/Y branch below would misread "2026-05-13" as May 13 2020.
	const iso = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ](\d{1,2}):(\d{2})(?::(\d{2}))?(?:\.\d+)?\s*(Z|[+-]\d{2}:?\d{2})?)?/i);
	if (iso) {
		const literal = `${iso[1]}-${p2(iso[2])}-${p2(iso[3])}`;
		// A TRAILING OFFSET makes the string an instant, not a wall clock, so its
		// date part is only the right day for a reader sitting in that offset.
		// Reading it literally is wrong, and wrong in the underpay direction: `Z`
		// is what toISOString() emits, and a 19:16 Houston Friday serializes as
		// "…-08-08T00:16:37.000Z". This helper decides the invoice week, so that
		// load silently leaves the week it was worked and nobody is short-paid
		// loudly enough to notice. Convert to the Houston business day, which is
		// what every other date in the money path already means.
		//
		// NOTHING WRITING THIS COLUMN EMITS `Z` TODAY — this is latent, not live.
		// It is fixed anyway because the failure is silent, in money, and the fix
		// costs one branch.
		//
		// No offset stays byte-identical: a bare "YYYY-MM-DD", or a naive
		// "…T20:16:37" with no zone, has nothing to convert FROM. Those are the
		// overwhelming majority of real values and they are correct as-is.
		//
		// WHY THE RFC 2822 BRANCH BELOW STAYS LITERAL EVEN THOUGH IT ALSO CARRIES
		// AN OFFSET — the obvious inconsistency, and it is deliberate. That shape
		// is the pre-cutover stamp on delivered rows, and its evening values were
		// ALREADY SETTLED on the day the cell shows; converting them now would
		// restate closed months, which the client has ruled out ("if it is already
		// closed and locked by the month then follow that date"). The `Z` shape has
		// no such history: of the 69 `Z` values in the sheet (all `Assigned Date`,
		// May–Nov 2025) every one lands 11:00–22:00 UTC, i.e. 05:00–17:00 Houston,
		// so not one has ever fallen in the 00:00–05:59 UTC window where the day
		// flips. Nothing was settled on the wrong day, so fixing it restates
		// nothing — it only stops the next `Z` writer from being wrong.
		const offset = iso[7];
		if (!offset) return literal;
		// "-0500" -> "-05:00"; Date's ISO parsing wants the colon form.
		const tz = /^[+-]\d{4}$/.test(offset) ? `${offset.slice(0, 3)}:${offset.slice(3)}` : offset.toUpperCase();
		const at = new Date(`${literal}T${p2(iso[4])}:${iso[5]}:${iso[6] ? p2(iso[6]) : "00"}${tz}`);
		// Degrade to the literal day, never to "". An unparseable oddity must not
		// turn a dated row into an undated one on a path that pays people.
		return Number.isNaN(at.getTime()) ? literal : houstonDay(at);
	}

	const us = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})(?:,?\s+(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(AM|PM)?)?/i);
	if (us) {
		let yr = parseInt(us[3], 10);
		if (yr < 100) yr += 2000; // "5/16/25" -> 2025 (same rule as parseSheetDate)
		return `${yr}-${p2(us[1])}-${p2(us[2])}`;
	}

	// RFC 2822 last: both checks above are ^-anchored and cheap, and this one is
	// the only loose match here.
	const rfc = s.match(/\b(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?\s+(\d{4})\b/i);
	if (rfc) {
		const mon = RFC2822_MONTHS.indexOf(rfc[2].toLowerCase()) + 1;
		if (mon > 0) {
			return `${rfc[3]}-${p2(mon)}-${p2(rfc[1])}`;
		}
	}
	return "";
}

// THE DATE THE MONEY MATH RESOLVES FOR A JOB TRACKING CELL. One function, used
// by the revenue/driver-pay math AND by the period guards that have to agree
// with it. Returns a LOCAL-midnight Date (or null), so fmtDate()/jtFmtDate()
// read back exactly the calendar day this picked, in any server zone.
//
// ⚠️ THIS REPLACES `parseSheetDate(v) || new Date(v)`, WHICH WAS SERVER-ZONE
// DEPENDENT. parseSheetDate itself was never the problem — its ISO and US-slash
// branches build `new Date(y, m-1, d)`, a local midnight read back through local
// getters, so they round-trip identically anywhere. The FALLBACK was:
// `new Date("Date: Wed, 30 Apr 2025 19:35:06 -0500")` is an INSTANT
// (2025-05-01T00:35Z), and fmtDate() then took its month in the SERVER's zone —
// UTC in production. That cell booked revenue to MAY on the VPS and to APRIL on
// a Houston laptop: same sheet, same code, different money. Nothing warned.
//
// The RFC 2822 branch reads the date LITERALLY, exactly as sheetDayKey() above
// already does. That is deliberate on two counts. It ends a live disagreement
// this file already documents — see "WHAT THE MONEY PATHS ACTUALLY DO", which
// records the accounting bucketing "19 Jun 2025 20:16:37 -0500" as Jun 20 while
// the export calls it Jun 19. And literal is the basis the client's rule names:
// "if it is already closed and locked by the month then follow that date."
//
// WHY LITERAL RATHER THAN AN America/Chicago CONVERSION — on production all 205
// RFC 2822 cells carry -0500 (192) or -0600 (13), i.e. Houston's own offsets, so
// the literal day and the Houston day are THE SAME DAY and the two candidate
// fixes are indistinguishable on real data. Literal wins because it needs no
// zone lookup, cannot drift when the tz database updates, and matches every
// other reader of this column.
//
// MEASURED READ-ONLY ON PRODUCTION BEFORE SHIPPING (2026-08-08): of 421 Job
// Tracking rows, 205 take this fallback. Against the previous behaviour this
// changes the resolved DAY of exactly two rows (#521716147 Jul 15→14, $580;
// 523642943 Aug 4→3, $500) and the resolved MONTH of NONE. Monthly revenue,
// per-load assigned month, per-truck first/last load date and every driver's
// pay-day set all come out byte-identical, so no locked period is restated —
// which is the only reason this was safe to change at all. Both moved rows take
// their pay window from a Pickup Appointment, so neither shifts a paid day.
//
// The last branch keeps `new Date()` for anything the three readers do not
// recognize. Production has zero such cells today; it stays so that an unforeseen
// shape degrades to the OLD behaviour rather than to null, which would silently
// drop that row's revenue instead of merely dating it awkwardly.
function moneySheetDate(val) {
	// The "Date: " prefix is part of the copied email header, same as sheetDayKey.
	const s = String(val ?? "").replace(/^Date:\s*/i, "").trim();
	if (!s) return null;
	// ISO first — the US M/D/Y branch would misread "2026-05-13".
	let m = s.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
	if (m) { const d = new Date(+m[1], +m[2] - 1, +m[3]); return isNaN(d) ? null : d; }
	m = s.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})/);
	if (m) {
		let yr = +m[3];
		if (yr < 100) yr += 2000; // "5/16/25" -> 2025, same rule as parseSheetDate
		const d = new Date(yr, +m[1] - 1, +m[2]);
		return isNaN(d) ? null : d;
	}
	// RFC 2822, read literally. Same shape sheetDayKey matches, so the two cannot
	// disagree about which day a rate-con-ingested load belongs to.
	m = s.match(/\b(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)[a-z]*\.?\s+(\d{4})\b/i);
	if (m) {
		const mon = RFC2822_MONTHS.indexOf(m[2].slice(0, 3).toLowerCase());
		if (mon >= 0) { const d = new Date(+m[3], mon, +m[1]); if (!isNaN(d)) return d; }
	}
	const fb = new Date(s);
	return isNaN(fb) ? null : fb;
}

// GET /api/loads/completed/export?driver=&from=&to= — every completed load as a
// CSV, optionally narrowed to one driver and/or a delivery-date window. Built
// for "download everything <driver> did" from the Completed tab.
//
// Super Admin only, and that is not a copy/paste of the neighbouring routes: the
// Payment column ships in this file. Dispatchers are stripped of broker and
// financial columns on every other surface (sanitizeBrokerColumns, the Driver
// column filter in GET /api/data), so handing them a whole-fleet money export
// would be the one hole in that policy.
//
// All three params are optional; none of them means "every completed load".
app.get("/api/loads/completed/export", requireRole("Super Admin"), exportLimiter, async (req, res) => {
	try {
		const driverQ = (req.query.driver || "").toString().trim();
		const from = (req.query.from || "").toString().trim();
		const to = (req.query.to || "").toString().trim();

		// Same date contract as GET /api/expenses/receipts-download. A backwards
		// range is a caller mistake, not an empty result — say so instead of
		// returning a confusing "no loads found".
		if ((from && !/^\d{4}-\d{2}-\d{2}$/.test(from)) || (to && !/^\d{4}-\d{2}-\d{2}$/.test(to))) {
			return res.status(400).json({ error: "Dates must be YYYY-MM-DD" });
		}
		if (from && to && to < from) {
			return res.status(400).json({ error: "'to' must be on or after 'from'" });
		}

		const jt = await getJobTrackingCached();
		const headers = jt.headers || [];
		// Cancelled + soft-deleted loads are absent from every KPI and admin list;
		// an export that included them would hand the owner a document that
		// disagrees with the screen he ran it from.
		const rows = excludeDroppedLoads(jt.data || [], headers);

		// Column resolution mirrors /api/dashboard's, regex for regex, so the file
		// and the Completed tab can never disagree about which column holds what.
		const statusCol = findCol(headers, /status/i);
		const driverCol = findCol(headers, /driver/i);
		const loadIdCol = findCol(headers, /load.?id|job.?id/i);
		const truckCol = findCol(headers, /^truck$|truck[._\s-]?(unit|number|#)|unit[._\s-]?number/i);
		const assignedDateCol = findCol(headers, /assigned.*date/i);
		// Delivery date. Two findCol calls, not one alternation, and that matters:
		// findCol returns the first HEADER that matches, so a single
		// `/completion|status.*update/` resolves by sheet column ORDER rather than
		// by preference. That is not hypothetical — the dashboard's completed-sort
		// regex has all four alternatives in one pattern, and because the live
		// header order is [20] Assigned Date, [21] Status Update Date,
		// [22] Completion Date, it silently resolves to "Assigned Date" and sorts
		// the Completed tab by assignment instead of delivery (pre-existing, filed
		// separately). Splitting the calls pins us to Completion Date, which is
		// what "Delivery Date" means. In prod it and Status Update Date hold the
		// same instant on 252 of 258 rows (the other 6 differ only in zero-padding),
		// so the fallback is a genuine equivalent when Completion Date is absent.
		const deliveredDateCol = findCol(headers, /completion|complete/i) || findCol(headers, /status.*update/i);
		// The money header is literally "  Payment  " — real leading/trailing
		// spaces. Reuses the invoice builder's resolver, which trims before
		// matching and deliberately refuses a /rate|amount/ fallback. That refusal
		// is the whole point: a `rate` keyword is why the on-screen Completed table
		// silently has no money column today, and it would happily bill
		// "Rate Per Mile" as the load's pay.
		const paymentCol = brokerInvoice.findPaymentColumn(headers);
		// Same address-column picker the dashboard uses, so we get the real
		// address and not the "Pickup Company Information" broker-reference column.
		const originAddrCol = pickAddressColumn(headers, /origin|pickup|shipper/i);
		const destAddrCol = pickAddressColumn(headers, /dest|drop|receiver|delivery/i);

		// Byte-identical to /api/dashboard's completedJobs test. If these two ever
		// diverge, the owner exports a different set of loads than the tab shows.
		const completedStatuses = /^(delivered|completed|pod received)$/i;
		// Whitespace-tolerant driver match — older sheet rows carry double-space
		// drift, and the UI dropdown normalizes names the same way.
		const wantDriver = driverQ ? normalizeDriverName(driverQ) : "";
		const filtering = !!(from || to);

		const matched = rows.filter((r) => {
			if (loadIdCol && !(r[loadIdCol] || "").toString().trim()) return false;
			if (!statusCol || !completedStatuses.test((r[statusCol] || "").toString().trim())) return false;
			if (wantDriver && (!driverCol || normalizeDriverName(r[driverCol]) !== wantDriver)) return false;
			if (filtering) {
				const day = deliveredDateCol ? sheetDayKey(r[deliveredDateCol]) : "";
				// DELIBERATE, and it is not a small effect: 160 of today's 258
				// completed loads have a BLANK Completion Date (they predate
				// status logging), so ANY date range drops ~62% of history. We
				// exclude them rather than pad, because the alternatives are
				// worse — falling back to Drop-off Appointment would silently mix
				// the SCHEDULED date into a filter the owner reads as actual
				// delivery, and including undated rows in every range would make
				// two adjacent months double-count the same load. An unfiltered
				// export (the primary ask, "every load this driver did") still
				// returns all of them. The client applies the same rule.
				if (!day) return false;
				if (from && day < from) return false;
				if (to && day > to) return false;
			}
			return true;
		});

		if (matched.length === 0) {
			// Human-readable and specific about which filter came up empty — this
			// lands in a toast, and "no results" alone sends the owner hunting.
			const scope = [
				driverQ ? `for ${driverQ}` : "",
				from && to ? `between ${from} and ${to}` : from ? `on or after ${from}` : to ? `on or before ${to}` : "",
			].filter(Boolean).join(" ");
			return res.status(404).json({
				error: `No completed loads found${scope ? " " + scope : ""}.`,
			});
		}

		// Newest delivery first — the order the Completed tab already shows.
		// Sorting the day-strings keeps this on the same TZ-free basis as the
		// filter; undated rows sort to the bottom instead of to 1970.
		matched.sort((a, b) => {
			const da = deliveredDateCol ? sheetDayKey(a[deliveredDateCol]) : "";
			const db2 = deliveredDateCol ? sheetDayKey(b[deliveredDateCol]) : "";
			if (da === db2) return 0;
			if (!da) return 1;
			if (!db2) return -1;
			return da < db2 ? 1 : -1;
		});

		// Collapse newlines/runs of spaces — a multi-line sheet address is legal
		// inside a quoted CSV cell but makes the row look broken in Excel.
		const oneLine = (v) => String(v ?? "").replace(/\s+/g, " ").trim();
		const cell = (r, col) => (col ? oneLine(r[col]) : "");
		// Both date columns carry BOTH shapes in prod — "8/3/2026, 2:15:49 PM"
		// (Apps Script) and "2026-07-31" (n8n) sit in the same column — so a
		// straight passthrough gives the owner a column Excel cannot sort. Emit
		// the normalized day, which is also the exact basis the from/to filter
		// ran on, so the file can't appear to contradict the range that produced
		// it. Unparseable cells pass through raw rather than silently blanking.
		const dateCell = (r, col) => (col ? (sheetDayKey(r[col]) || oneLine(r[col])) : "");

		const out = [[
			"Load ID", "Job Status", "Driver", "Truck", "Pickup", "Drop-off",
			"Assigned Date", "Delivery Date", "Payment",
		]];
		for (const r of matched) {
			const lid = loadIdCol ? (r[loadIdCol] || "").toString().trim() : "";
			// Prefer the enriched "City, ST ZIP" the dashboard computed — these ARE
			// the shared cache's row objects, so the fields are already there
			// whenever the dashboard ran inside the 60s TTL. Otherwise derive it
			// the same way (geocoded address first, sheet column second), and only
			// fall back to the raw cell when nothing parses.
			const pickupRaw = originAddrCol ? r[originAddrCol] : "";
			const dropRaw = destAddrCol ? r[destAddrCol] : "";
			const pickup = r._pickupLocation
				|| resolveAddressParts(r, "pickup", lid, pickupRaw).cityStateZip
				|| oneLine(pickupRaw);
			const drop = r._dropLocation
				|| resolveAddressParts(r, "drop", lid, dropRaw).cityStateZip
				|| oneLine(dropRaw);
			out.push([
				lid,
				cell(r, statusCol),
				cell(r, driverCol),
				cell(r, truckCol),
				pickup,
				drop,
				dateCell(r, assignedDateCol),
				dateCell(r, deliveredDateCol),
				// Raw sheet value ("$1,800.00"), not a reformat — the export should
				// reconcile to the sheet the invoices are billed from.
				cell(r, paymentCol),
			]);
		}

		// completed-loads[-<driver>][-<from>-to-<to>].csv — one-sided ranges get a
		// labelled segment so the filename still says what the file contains.
		const safe = (s) => String(s).replace(/[^a-zA-Z0-9._-]/g, "_");
		let name = "completed-loads";
		if (driverQ) name += `-${safe(driverQ)}`;
		if (from && to) name += `-${safe(from)}-to-${safe(to)}`;
		else if (from) name += `-from-${safe(from)}`;
		else if (to) name += `-to-${safe(to)}`;
		const filename = `${name}.csv`;

		res.setHeader("Content-Type", "text/csv");
		res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
		// Matches the other file-serving routes (truck docs, shared driver files).
		// no-store matters here specifically because this URL is reachable on a
		// cross-site NAVIGATION — a whole-fleet revenue CSV should never sit in a
		// shared or browser cache afterwards. That was written when the session
		// cookie was sameSite:"none"; it went "lax" on 2026-08-09 and the reason
		// SURVIVES unchanged, because lax withholds the cookie from cross-site
		// POSTs and subresources but still sends it on a top-level GET
		// navigation, which is exactly the shape that reaches this route.
		res.setHeader("X-Content-Type-Options", "nosniff");
		res.setHeader("Cache-Control", "no-store");
		res.send(csvRows(out));
		console.log(`Completed-loads export: ${matched.length} rows${driverQ ? " driver=" + driverQ : ""}${from || to ? ` ${from || "…"}..${to || "…"}` : ""}`);
	} catch (err) {
		console.error("GET /api/loads/completed/export error:", err.message);
		if (!res.headersSent) res.status(500).json({ error: "Failed to export completed loads" });
	}
});

// --- Routemate ELD/telematics probe endpoints (Phase 1) ---
// The sync intervals come in Phase 2+. For now these two endpoints validate
// that the API key works and mirror the vehicle list into routemate_vehicles
// so admins can link trucks → Routemate devices in TrucksView (Phase 2).

// POST /api/admin/routemate/sync-now — Manual probe + vehicle list mirror.
// Super Admin only. No-ops with a clean 503 when ROUTEMATE_ENABLED is false
// or the key is unset; that keeps the kill switch usable from the UI.
// Method guard — without this, a stray GET to this URL falls through to the
// SPA catch-all and serves index.html, which looks like the endpoint is
// world-readable. POST is properly auth-gated below; this just keeps the
// 405 error explicit for any tooling that probes both verbs.
app.all("/api/admin/routemate/sync-now", (req, res, next) => {
	if (req.method === "POST") return next();
	res.set("Allow", "POST");
	res.status(405).json({ error: "Method not allowed", expected: "POST" });
});
app.post("/api/admin/routemate/sync-now", requireRole("Super Admin"), async (req, res) => {
	if (!ROUTEMATE_ENABLED) {
		return res.status(503).json({ error: "Routemate integration disabled (set ROUTEMATE_ENABLED=true)" });
	}
	if (!ROUTEMATE_API_KEY) {
		return res.status(503).json({ error: "Routemate API key not configured (set ROUTEMATE_API_KEY)" });
	}
	try {
		// Smoke test first via the lightest call before paginating vehicles.
		await routemate.getCompany(routemateCreds());
		const result = await routemateSyncVehicles();
		// Trigger one telemetry pull so the operator sees fresh data immediately.
		routemateSyncTelemetry().catch(() => {});
		logAudit(req, 'routemate_sync', 'vehicles', '', `Synced ${result.synced} Routemate vehicles`);
		res.json({ success: true, vehiclesSynced: result.synced, vehiclesHydrated: result.hydrated || 0 });
	} catch (err) {
		console.error("Routemate sync-now error:", err.message);
		// Pull telemetry anyway — that endpoint isn't affected by the
		// /assets/vehicles outage and is what dispatchers actually care about.
		routemateSyncTelemetry().catch(() => {});
		const upstream500 = err.status === 500;
		const fellBackToTelemetry = Number.isFinite(err.fallbackSynced);
		const hydrated = Number.isFinite(err.hydratedIndividually) ? err.hydratedIndividually : 0;
		res.status(err.status === 401 || err.status === 403 ? err.status : 502).json({
			error: err.message || "Routemate sync failed",
			code: err.code || "ROUTEMATE_SYNC_FAILED",
			upstreamStatus: err.status || null,
			// Helpful breadcrumb for support — explains *what* Routemate broke,
			// and, when the per-vehicle fallback covered it, that the mirror is
			// actually populated despite this non-2xx. Without that second half
			// an operator reads "sync failed" and assumes VIN auto-match is
			// still dead when it has just been repaired.
			hint: upstream500
				? (hydrated > 0
					? `Routemate's /api/v0/assets/vehicles list endpoint is returning HTTP 500 (upstream bug). Worked around it: ${hydrated} vehicle record(s) fetched individually, so VIN/make/model are up to date and VIN auto-match works. Telemetry (live GPS) is unaffected.`
					: "Routemate's /api/v0/assets/vehicles endpoint is returning HTTP 500. Telemetry (live GPS) is unaffected. Contact Routemate support — this is upstream.")
				: undefined,
			fallbackSynced: fellBackToTelemetry ? err.fallbackSynced : undefined,
			vehiclesHydrated: hydrated || undefined,
		});
	}
});

// GET /api/routemate/health — Last-sync timestamps + recent error count.
// Super Admin only. Used by the manual probe UI in TrucksView (Phase 2).
app.get("/api/routemate/health", requireRole("Super Admin"), (req, res) => {
	res.json({
		enabled: ROUTEMATE_ENABLED,
		hasKey: !!ROUTEMATE_API_KEY,
		baseUrl: ROUTEMATE_BASE_URL,
		lastSync: routemateHealth.lastSync,
		lastError: routemateHealth.lastError,
		errorsLast24h: routemateHealth.errorsLast24h,
	});
});

// ===================================================================
// Linxup Push API v3 — inbound GPS webhook (replaces the Routemate poll)
// ===================================================================
// Linxup PUSHES telemetry to us. This receiver validates a shared-secret token,
// maps each Position message into routemate_telemetry (the live table tracking +
// driver-pay already read), and fans out the same location-update + geofence as
// the poller. Ships DORMANT: the token gate is always enforced, but positions
// are only WRITTEN when LINXUP_ENABLED=true — so nothing touches live tracking
// or driver pay until we've verified real pushes.
//   LINXUP_ENABLED        — master write switch (default false)
//   LINXUP_WEBHOOK_TOKEN  — shared secret Linxup must present on every push
//   LINXUP_SPEED_UNIT     — mph | kmh | mps (default mph → converted to m/s)
const LINXUP_ENABLED = String(process.env.LINXUP_ENABLED || "").toLowerCase() === "true";
const LINXUP_WEBHOOK_TOKEN = process.env.LINXUP_WEBHOOK_TOKEN || "";
const LINXUP_SPEED_UNIT = process.env.LINXUP_SPEED_UNIT || "mph";
const linxupHealth = { lastReceived: null, lastWritten: null, lastError: null, counts: {}, unlinked: 0 };

// Resolve the LINXUP token from wherever Linxup places it. Until a real push
// confirms the scheme, accept the common carriers: Authorization: Bearer <t>,
// X-Api-Key / X-Webhook-Token header, or ?token= query. LIVE-CAPTURE: lock to
// the actual header once the first push is seen.
function linxupTokenFromReq(req) {
	const auth = String(req.headers["authorization"] || "");
	const bearer = /^Bearer\s+(.+)$/i.exec(auth);
	return (
		(bearer && bearer[1]) ||
		req.headers["x-api-key"] ||
		req.headers["x-webhook-token"] ||
		req.headers["x-linxup-token"] ||
		(req.query && (req.query.token || req.query.apiKey)) ||
		""
	).toString().trim();
}
// Constant-time-ish compare so the token check doesn't leak length via timing.
function safeEqual(a, b) {
	a = String(a || ""); b = String(b || "");
	if (a.length !== b.length) return false;
	let diff = 0;
	for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
	return diff === 0;
}

// Insert one normalized Linxup position into routemate_telemetry with the same
// quality gates + fan-out as the poller. Returns { written, dropped_reason }.
async function ingestLinxupPosition(pos) {
	// Link to a truck: match any candidate id against trucks.routemate_vehicle_id.
	// Use the MATCHED value as the stored vehicle id so the existing read paths
	// (which key on trucks.routemate_vehicle_id) line up regardless of which id
	// the fleet linked by. Unmatched positions are still stored (first candidate)
	// so no data is lost — they just won't map to a truck until it's linked.
	let vehicleId = pos.vehicle_id;
	let driverName = "";
	if (pos.candidates && pos.candidates.length) {
		const ph = pos.candidates.map(() => "?").join(",");
		const row = db.prepare(
			`SELECT ta.driver_name AS driver, t.routemate_vehicle_id AS vid
			 FROM truck_assignments ta JOIN trucks t ON t.id = ta.truck_id
			 WHERE ta.end_date = '' AND t.routemate_vehicle_id IN (${ph}) LIMIT 1`,
		).get(...pos.candidates);
		if (row) { vehicleId = row.vid; driverName = row.driver || ""; }
	}
	if (!vehicleId) return { written: false, dropped_reason: "no_vehicle_id" };
	if (!driverName) linxupHealth.unlinked++;

	// Quality gates — mirror the poller: invalid coords / implied-speed outlier
	// are still INSERTED but tagged so every read path filters them.
	let droppedReason = "";
	const hasValidCoords = Number.isFinite(pos.latitude) && Number.isFinite(pos.longitude)
		&& (pos.latitude !== 0 || pos.longitude !== 0);
	if (!hasValidCoords) {
		droppedReason = "invalid_coords";
	} else {
		const prev = routemateLastCleanFixStmt.get(vehicleId);
		if (prev && Number.isFinite(prev.location_date_ms)) {
			const dtMs = (pos.location_date_ms || Date.now()) - prev.location_date_ms;
			if (dtMs >= SPEED_CHECK_MIN_DT_MS && dtMs <= SPEED_CHECK_MAX_DT_MS) {
				const distM = geolib.getDistance(
					{ latitude: prev.latitude, longitude: prev.longitude },
					{ latitude: pos.latitude, longitude: pos.longitude },
				);
				if (distM / (dtMs / 1000) > SPEED_OUTLIER_MPS) droppedReason = "speed_outlier";
			}
		}
	}

	routemateInsertTelemetryStmt.run({
		routemate_vehicle_id: vehicleId,
		latitude: pos.latitude,
		longitude: pos.longitude,
		speed: pos.speed || 0,
		bearing: pos.bearing || "",
		odometer: pos.odometer || 0,
		engine_hours: pos.engine_hours || 0,
		fuel_pct: pos.fuel_pct,
		geocoded_location: pos.geocoded_location || "",
		location_date_ms: pos.location_date_ms || Date.now(),
		dropped_reason: droppedReason,
	});
	linxupHealth.lastWritten = new Date().toISOString();

	// Fan out live UI + geofence only for clean, linked fixes (same as the poller).
	if (!droppedReason && driverName) {
		const driverLower = driverName.trim().toLowerCase();
		let activeLoadId = "";
		// Every active load for this driver, most-progressed first — same reason
		// as the Routemate path: queueing is supported, and first-match-by-row
		// is rate-con arrival order, which picks the STALEST load and starves the
		// one actually being driven. activeLoadId (first match) is kept for the
		// location payload / tracker, which expects a single id.
		let driverActiveLoads = [];
		try {
			const jt = await getJobTrackingCached();
			const headers = jt.headers || [];
			const loadIdCol = findCol(headers, /load.?id|job.?id/i);
			const statusCol = findCol(headers, /^status$/i) || findCol(headers, /status/i);
			const driverCol = findCol(headers, /^driver$/i) || findCol(headers, /driver/i);
			const activeRe = /^(assigned|dispatched|heading to shipper|at shipper|loading|in transit|at receiver|unloading)$/i;
			if (loadIdCol && statusCol && driverCol) {
				for (const r of (jt.data || [])) {
					if ((r[driverCol] || "").toString().trim().toLowerCase() !== driverLower) continue;
					const s = (r[statusCol] || "").toString().trim();
					if (!activeRe.test(s)) continue;
					const lid = (r[loadIdCol] || "").toString().trim();
					if (!lid) continue;
					if (!activeLoadId) activeLoadId = lid;
					driverActiveLoads.push({ loadId: lid, status: s });
				}
				driverActiveLoads = orderGeofenceCandidates(driverActiveLoads, pos.latitude, pos.longitude);
			}
		} catch { /* best-effort */ }
		const headingDeg = parseRoutemateBearing(pos.bearing);
		const locationPayload = {
			driver: driverName,
			latitude: pos.latitude,
			longitude: pos.longitude,
			speed: pos.speed || 0,
			heading: headingDeg != null ? headingDeg : 0,
			loadId: activeLoadId,
			timestamp: new Date(pos.location_date_ms || Date.now()).toISOString(),
			source: "linxup",
			fuelPct: Number.isFinite(pos.fuel_pct) ? pos.fuel_pct : null,
		};
		io.to("dispatch").emit("location-update", locationPayload);
		if (driverLower) io.to(driverLower).emit("location-update", locationPayload);
		for (const cand of driverActiveLoads) {
			try {
				const advanced = await tryGeofenceAdvance({
					latitude: pos.latitude, longitude: pos.longitude,
					driverName, loadId: cand.loadId, routemateVehicleId: vehicleId,
					// WAS MISSING: without speed, the departure rule can never
					// fire, so "In Transit" would silently stop working the day
					// Linxup replaces the Routemate poller — taking the time-out
					// half of detention with it.
					speedMps: pos.speed,
				});
				if (advanced) break;   // one transition per ping
			} catch (e) { console.error("[linxup] geofence error:", e.message); }
		}
	}
	return { written: true, dropped_reason: droppedReason };
}

// POST /api/eld/linxup/webhook — inbound push. Token-gated; ACKs 200 quickly so
// Linxup doesn't retry-storm. Handles a single message OR an array of messages.
app.post("/api/eld/linxup/webhook", async (req, res) => {
	// Token gate is ALWAYS enforced (even when writes are disabled) so a
	// misconfigured/unauth caller can never reach the ingest path.
	if (!LINXUP_WEBHOOK_TOKEN) return res.status(503).json({ error: "Linxup webhook not configured" });
	if (!safeEqual(linxupTokenFromReq(req), LINXUP_WEBHOOK_TOKEN)) {
		return res.status(401).json({ error: "Unauthorized" });
	}
	linxupHealth.lastReceived = new Date().toISOString();
	const body = req.body;
	const messages = Array.isArray(body) ? body : (body && Array.isArray(body.messages) ? body.messages : [body]);
	// ACK immediately; process after the response so a slow sheet/geofence read
	// never makes Linxup time out and re-deliver.
	res.json({ ok: true, received: messages.length, enabled: LINXUP_ENABLED });
	setImmediate(async () => {
		for (const msg of messages) {
			try {
				const type = linxupPush.detectMessageType(msg);
				linxupHealth.counts[type] = (linxupHealth.counts[type] || 0) + 1;
				if (type !== "position") continue;           // v1: only Position feeds tracking
				if (!LINXUP_ENABLED) continue;                 // dormant — recognized + counted, not written
				const pos = linxupPush.normalizePosition(msg, { speedUnit: LINXUP_SPEED_UNIT });
				await ingestLinxupPosition(pos);
			} catch (e) {
				linxupHealth.lastError = e.message;
				console.error("[linxup] ingest error:", e.message);
			}
		}
	});
});

// GET /api/eld/linxup/health — Super Admin. Never echoes the token.
app.get("/api/eld/linxup/health", requireRole("Super Admin"), (req, res) => {
	res.json({
		provider: "linxup",
		enabled: LINXUP_ENABLED,
		hasToken: !!LINXUP_WEBHOOK_TOKEN,
		speedUnit: LINXUP_SPEED_UNIT,
		lastReceived: linxupHealth.lastReceived,
		lastWritten: linxupHealth.lastWritten,
		lastError: linxupHealth.lastError,
		messageCounts: linxupHealth.counts,
		unlinkedPositions: linxupHealth.unlinked,
	});
});

