// GET /api/routemate/vehicles — Mirrored Routemate vehicle inventory.
// Used by the truck-linkage UI in /trucks. Super Admin + Dispatcher.
app.get("/api/routemate/vehicles", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		const rows = db.prepare(`
			SELECT rv.id, rv.routemate_vehicle_id, rv.vehicle_id, rv.vin, rv.make, rv.model,
			       rv.year, rv.fuel_type, rv.license_num, rv.eld_id, rv.state, rv.active,
			       strftime('%Y-%m-%dT%H:%M:%SZ', rv.last_synced_at) AS last_synced_at,
			       (SELECT t.id FROM trucks t WHERE t.routemate_vehicle_id = rv.routemate_vehicle_id LIMIT 1) AS linked_truck_id,
			       (SELECT t.unit_number FROM trucks t WHERE t.routemate_vehicle_id = rv.routemate_vehicle_id LIMIT 1) AS linked_truck_unit
			FROM routemate_vehicles rv
			ORDER BY rv.vin, rv.routemate_vehicle_id
		`).all();
		res.json({ vehicles: rows });
	} catch (err) {
		console.error("routemate vehicles list error:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// Trailing digits of a LogisX unit number, which is how the fleet names a truck
// after the Routemate `vehicleId` on its device: "LogisX-#33" -> "33",
// "Logisx-#91" -> "91", "LogisX-#2372" -> "2372". Every link that exists in
// production satisfies this, which is the evidence the convention is real.
//
// ⚠️ This is a SUGGESTION key, never an auto-link key. The ELD link is a
// driver-pay input (it is the map historical loads resolve through to get their
// travel days) and re-pointing it is guarded by truckEditLockBlockers — so a
// heuristic that binds without a human confirming is the wrong trade. VIN is the
// only key strong enough to link on its own. See the auto branch below.
function unitNumberToken(unit) {
	const m = String(unit || "").match(/(\d+)\s*$/);
	return m ? m[1] : "";
}

// The unlinked Routemate vehicle whose `vehicle_id` matches a truck's unit
// number, if exactly one does. Returns null on no match OR on ambiguity —
// two candidates means the convention has broken down for this fleet and
// guessing between them is worse than offering nothing.
function suggestRoutemateVehicleForTruck(truck) {
	const token = unitNumberToken(truck && truck.unit_number);
	if (!token) return null;
	const matches = db.prepare(`
		SELECT rv.routemate_vehicle_id, rv.vehicle_id, rv.vin, rv.make, rv.model, rv.year
		FROM routemate_vehicles rv
		WHERE TRIM(rv.vehicle_id) = ?
		  AND rv.routemate_vehicle_id NOT IN (
			SELECT routemate_vehicle_id FROM trucks WHERE COALESCE(routemate_vehicle_id, '') <> ''
		  )
		LIMIT 2
	`).all(token);
	if (matches.length !== 1) return null;
	return { ...matches[0], reason: "unit-number", matchedOn: token };
}

// GET /api/routemate/vehicles/unlinked — Routemate vehicles not yet linked
// to any LogisX truck. Used to populate the link modal in TrucksView.
//
// Optional ?truckId=N adds a `suggested` device for that truck (see
// suggestRoutemateVehicleForTruck). Purely additive — the `vehicles` array is
// unchanged and callers that omit truckId see the exact same body as before.
// The rule lives here rather than in the client so it cannot drift from the
// auto-match branch of POST /link-routemate, which consults the same helper.
app.get("/api/routemate/vehicles/unlinked", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		const rows = db.prepare(`
			SELECT rv.id, rv.routemate_vehicle_id, rv.vehicle_id, rv.vin, rv.make, rv.model,
			       rv.year, rv.fuel_type, rv.license_num, rv.eld_id, rv.state
			FROM routemate_vehicles rv
			WHERE rv.routemate_vehicle_id NOT IN (
				SELECT routemate_vehicle_id FROM trucks WHERE COALESCE(routemate_vehicle_id, '') <> ''
			)
			ORDER BY rv.vin, rv.routemate_vehicle_id
		`).all();

		const body = { vehicles: rows };
		const truckId = parseInt(req.query.truckId, 10);
		if (truckId) {
			const truck = db.prepare("SELECT id, unit_number, vin FROM trucks WHERE id = ?").get(truckId);
			if (truck) {
				const suggested = suggestRoutemateVehicleForTruck(truck);
				if (suggested) body.suggested = suggested;
			}
		}
		res.json(body);
	} catch (err) {
		console.error("routemate unlinked-vehicles error:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// POST /api/trucks/:truckId/link-routemate — Link a LogisX truck to a Routemate
// vehicle. Body accepts either {routemateVehicleId} for explicit selection or
// {auto:true} to attempt VIN-based auto-match. Super Admin only.
app.post("/api/trucks/:truckId/link-routemate", requireRole("Super Admin"), (req, res) => {
	try {
		const truckId = parseInt(req.params.truckId, 10);
		if (!truckId) return res.status(400).json({ error: "Invalid truck id" });
		// SELECT * (was id/unit_number/vin/routemate_vehicle_id): the period guard
		// below reads the whole row, and a partial one would silently evaluate
		// against zeroed fixed costs and a missing created_at.
		const truck = db.prepare("SELECT * FROM trucks WHERE id = ?").get(truckId);
		if (!truck) return res.status(404).json({ error: "Truck not found" });

		let target = (req.body && req.body.routemateVehicleId) || "";
		const auto = req.body && req.body.auto === true;

		if (auto) {
			if (!String(truck.vin || "").trim()) {
				return res.status(400).json({ error: "Truck has no VIN to auto-match", code: "TRUCK_NO_VIN" });
			}
			// TRIM both sides, and refuse to match an EMPTY stored VIN. The
			// non-empty guard is not defensive tidying: routemate_vehicles.vin
			// defaults to '' and is '' for every row whenever the inventory
			// hydration hasn't run, so without it a truck whose VIN is
			// whitespace would silently bind to an arbitrary blank-VIN device.
			const match = db.prepare(
				"SELECT routemate_vehicle_id FROM routemate_vehicles WHERE UPPER(TRIM(vin)) = UPPER(TRIM(?)) AND TRIM(vin) <> '' LIMIT 1"
			).get(truck.vin);

			if (!match) {
				// Two very different failures used to share one message. Saying
				// "no vehicle matches VIN X" when we hold NO VIN for ANY device
				// asserts a mismatch that was never tested — it sent at least one
				// operator hunting for a data-entry error in a VIN that was in
				// fact correct. Name the real state instead.
				const vinStats = db.prepare(
					"SELECT COUNT(*) AS total, SUM(CASE WHEN TRIM(COALESCE(vin,'')) <> '' THEN 1 ELSE 0 END) AS withVin, MAX(last_synced_at) AS lastSync FROM routemate_vehicles"
				).get();
				const suggestion = suggestRoutemateVehicleForTruck(truck);
				if (!vinStats || !vinStats.withVin) {
					return res.status(404).json({
						code: "RM_NO_VIN_DATA",
						error: `Routemate inventory holds no VIN for any of the ${vinStats ? vinStats.total : 0} mirrored device(s)`
							+ `${vinStats && vinStats.lastSync ? ` (last sync ${vinStats.lastSync})` : ""}`
							+ `, so VIN auto-match cannot run — this is not a mismatch with ${truck.vin}.`
							+ ` Run Sync from Admin Tools to pull vehicle detail, then try again.`,
						truckVin: truck.vin,
						mirroredVehicles: vinStats ? vinStats.total : 0,
						suggestion: suggestion || undefined,
					});
				}
				return res.status(404).json({
					code: "RM_VIN_NO_MATCH",
					error: `No Routemate vehicle matches VIN ${truck.vin}`,
					truckVin: truck.vin,
					suggestion: suggestion || undefined,
				});
			}
			target = match.routemate_vehicle_id;
		}

		if (!target) return res.status(400).json({ error: "routemateVehicleId or {auto:true} required" });

		// Verify the target exists and isn't already linked to a different truck.
		const rv = db.prepare("SELECT routemate_vehicle_id FROM routemate_vehicles WHERE routemate_vehicle_id = ?").get(target);
		if (!rv) return res.status(404).json({ error: "Routemate vehicle not found in mirror — run sync-now first" });
		const otherTruck = db.prepare(
			"SELECT id, unit_number FROM trucks WHERE routemate_vehicle_id = ? AND id <> ?"
		).get(target, truckId);
		if (otherTruck) {
			return res.status(409).json({ error: `Already linked to truck ${otherTruck.unit_number} (#${otherTruck.id}). Unlink first.` });
		}

		// The ELD link is a driver-pay input, not a piece of configuration: it is the
		// map historical loads resolve through to get their travel days. Same guard
		// the truck PUT runs, so re-pointing a device cannot do what editing the
		// unit number is refused for. See check (5b).
		if (String(truck.routemate_vehicle_id || "").trim() !== String(target).trim()) {
			const lock = truckEditLockBlockers(truck, { routemate_vehicle_id: target });
			// Mirrors the `routemate_link` success line. BOTH device ids are recorded:
			// the link is the map historical loads resolve through to get their travel
			// days, so which device it was moved FROM is as much of the story as which
			// it was moved to.
			const linkAudit = {
				action: "routemate_link_blocked", entity: "truck", entityId: String(truckId),
				subject: `re-point ELD on ${truck.unit_number || `truck #${truckId}`}:` +
					` ${truck.routemate_vehicle_id || "none"} -> ${target}`,
			};
			if (lock.unreadable) return periodLockUnreadableResponse(req, res, "Linking an ELD device", linkAudit);
			if (lock.blockers.length) {
				return periodBlockedResponse(req, res,
					`Cannot re-point the ELD device on ${truck.unit_number || `truck #${truckId}`}`,
					lock.blockers,
					"Reopen the affected periods first — POST /api/periods/:period/reopen records a reason.",
					linkAudit);
			}
		}

		db.prepare("UPDATE trucks SET routemate_vehicle_id = ? WHERE id = ?").run(target, truckId);
		logAudit(req, 'routemate_link', 'truck', String(truckId), `Linked truck ${truck.unit_number} → Routemate ${target}`);
		res.json({ success: true, truckId, routemateVehicleId: target });
	} catch (err) {
		console.error("routemate link error:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// DELETE /api/trucks/:truckId/link-routemate — Clear the Routemate link.
// Telemetry continues to be ingested for the underlying device but stops
// being attributed to this truck in /api/locations/latest. Super Admin only.
app.delete("/api/trucks/:truckId/link-routemate", requireRole("Super Admin"), (req, res) => {
	try {
		const truckId = parseInt(req.params.truckId, 10);
		if (!truckId) return res.status(400).json({ error: "Invalid truck id" });
		// SELECT * — the period guard below reads the whole row.
		const truck = db.prepare("SELECT * FROM trucks WHERE id = ?").get(truckId);
		if (!truck) return res.status(404).json({ error: "Truck not found" });
		const prev = truck.routemate_vehicle_id || "";
		// Unlinking is the sharpest version of this whole class of bug: it removes
		// the truck from the unit→vehicle map, so every historical load loses ELD
		// coverage and getEldTravelDaysByVehicle()'s coverage-aware fallback pays
		// the FULL scheduled window instead of the days actually travelled. One
		// call, driver pay up across every closed month. See check (5b).
		if (prev) {
			const lock = truckEditLockBlockers(truck, { routemate_vehicle_id: "" });
			// Mirrors the `routemate_unlink` success line, and records the device id
			// being detached — after a successful unlink the column is empty, so on a
			// refusal this is the only place the intended target survives.
			const unlinkAudit = {
				action: "routemate_unlink_blocked", entity: "truck", entityId: String(truckId),
				subject: `unlink ELD from ${truck.unit_number || `truck #${truckId}`} (was ${prev})`,
			};
			if (lock.unreadable) return periodLockUnreadableResponse(req, res, "Unlinking an ELD device", unlinkAudit);
			if (lock.blockers.length) {
				return periodBlockedResponse(req, res,
					`Cannot unlink the ELD device on ${truck.unit_number || `truck #${truckId}`}`,
					lock.blockers,
					"Reopen the affected periods first — POST /api/periods/:period/reopen records a reason.",
					unlinkAudit);
			}
		}
		db.prepare("UPDATE trucks SET routemate_vehicle_id = '' WHERE id = ?").run(truckId);
		logAudit(req, 'routemate_unlink', 'truck', String(truckId), `Unlinked truck ${truck.unit_number} (was ${prev || 'none'})`);
		res.json({ success: true, truckId });
	} catch (err) {
		console.error("routemate unlink error:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// GET /api/admin/fleet-health — Phase 3 dashboard data. Per-truck snapshot
// blending the trucks table with the latest Routemate telemetry row, plus
// a derived "idle seconds" (time since the truck last moved at >5 mph).
// Super Admin + Dispatcher only. No alerts here — Phase 5 owns thresholds.
app.get("/api/admin/fleet-health", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		const trucks = db.prepare(`
			SELECT id, unit_number, vin, status, assigned_driver, routemate_vehicle_id
			FROM trucks
			ORDER BY unit_number ASC
		`).all();

		// Pre-fetch latest telemetry per linked vehicle and the latest "moving"
		// timestamp in one pass so we don't N+1 the DB.
		const linkedIds = trucks.map(t => t.routemate_vehicle_id).filter(Boolean);
		const latestByVehicle = {};
		const lastMovingByVehicle = {};
		if (linkedIds.length > 0) {
			const placeholders = linkedIds.map(() => "?").join(",");
			const latestRows = db.prepare(`
				SELECT rt.routemate_vehicle_id, rt.latitude, rt.longitude, rt.speed,
				       rt.fuel_pct, rt.odometer, rt.engine_hours, rt.geocoded_location,
				       rt.location_date_ms
				FROM routemate_telemetry rt
				INNER JOIN (
					SELECT routemate_vehicle_id, MAX(id) AS max_id
					FROM routemate_telemetry
					WHERE routemate_vehicle_id IN (${placeholders})
					  AND dropped_reason = ''
					GROUP BY routemate_vehicle_id
				) latest ON rt.id = latest.max_id
			`).all(...linkedIds);
			for (const r of latestRows) latestByVehicle[r.routemate_vehicle_id] = r;

			const MOVING_MPH_M_PER_S = 2.235; // ~5 mph
			const movingRows = db.prepare(`
				SELECT routemate_vehicle_id, MAX(location_date_ms) AS last_moving_ms
				FROM routemate_telemetry
				WHERE routemate_vehicle_id IN (${placeholders})
				  AND speed > ?
				  AND dropped_reason = ''
				GROUP BY routemate_vehicle_id
			`).all(...linkedIds, MOVING_MPH_M_PER_S);
			for (const r of movingRows) lastMovingByVehicle[r.routemate_vehicle_id] = r.last_moving_ms;
		}

		const FRESH_MS = 5 * 60 * 1000;
		const now = Date.now();
		const result = trucks.map((t) => {
			const rmId = t.routemate_vehicle_id || "";
			const tel = rmId ? latestByVehicle[rmId] : null;
			const isFresh = !!(tel && tel.location_date_ms && (now - tel.location_date_ms) < FRESH_MS);
			let idleSeconds = null;
			if (tel) {
				const lastMoving = lastMovingByVehicle[rmId];
				const speedMps = tel.speed || 0;
				if (speedMps <= 2.235) {
					// Stationary now; clock starts at last_moving_ms (or fall back to
					// the latest fix if we have no record of the truck ever moving).
					const since = lastMoving || tel.location_date_ms;
					idleSeconds = since ? Math.round((now - since) / 1000) : null;
				} else {
					idleSeconds = 0;
				}
			}
			return {
				truckId: t.id,
				unitNumber: t.unit_number,
				vin: t.vin || "",
				truckStatus: t.status,
				assignedDriver: t.assigned_driver || "",
				routemateVehicleId: rmId,
				source: rmId && isFresh ? "routemate" : (rmId ? "stale" : "unlinked"),
				latitude: tel ? tel.latitude : null,
				longitude: tel ? tel.longitude : null,
				speedMph: tel ? Math.round((tel.speed || 0) * 2.237) : null,
				fuelPct: tel && tel.fuel_pct != null ? tel.fuel_pct : null,
				odometer: tel ? tel.odometer : null,
				engineHours: tel ? tel.engine_hours : null,
				geocodedLocation: tel ? tel.geocoded_location : "",
				lastFixMs: tel ? tel.location_date_ms : null,
				lastFixAgeSec: tel ? Math.round((now - tel.location_date_ms) / 1000) : null,
				idleSeconds,
			};
		});

		res.json({ trucks: result, generatedAt: new Date().toISOString() });
	} catch (err) {
		console.error("fleet-health error:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// GET /api/routemate/fuel/summary?days=7 — Per-truck rolling MPG. Available
// to Super Admin / Dispatcher (full fleet) and Investor (own trucks only,
// scoped by trucks.owner_id like /api/trucks does).
app.get("/api/routemate/fuel/summary", requireRole("Super Admin", "Dispatcher", "Investor"), (req, res) => {
	try {
		const days = Math.max(1, Math.min(parseInt(req.query.days, 10) || 7, 30));
		const fromDate = new Date(Date.now() - days * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
		const user = req.session.user;
		// Super Admin previewing an investor's portal: scope to that investor's
		// trucks so MPG matches what the investor sees on their own dashboard.
		const preview = resolvePreviewUser(req);

		const trucks = preview.isPreview
			? db.prepare("SELECT id, unit_number, routemate_vehicle_id FROM trucks WHERE owner_id = ?").all(preview.effectiveUserId)
			: (user.role === "Investor")
				? db.prepare("SELECT id, unit_number, routemate_vehicle_id FROM trucks WHERE owner_id = ?").all(user.id)
				: db.prepare("SELECT id, unit_number, routemate_vehicle_id FROM trucks").all();

		const fuelStmt = db.prepare(`
			SELECT
				SUM(miles) AS miles_total,
				SUM(gallons_est) AS gallons_total,
				COUNT(*) AS day_count,
				MAX(date) AS latest_date
			FROM routemate_fuel_daily
			WHERE routemate_vehicle_id = ?
			  AND date >= ?
		`);

		const result = trucks.map(t => {
			let miles_total = 0, gallons_total = 0, day_count = 0, latest_date = null, mpg_avg = null;
			if (t.routemate_vehicle_id) {
				const r = fuelStmt.get(t.routemate_vehicle_id, fromDate);
				miles_total = r.miles_total || 0;
				gallons_total = r.gallons_total || 0;
				day_count = r.day_count || 0;
				latest_date = r.latest_date;
				if (gallons_total > 0) mpg_avg = round1(miles_total / gallons_total);
			}
			return {
				truckId: t.id,
				unitNumber: t.unit_number,
				routemateVehicleId: t.routemate_vehicle_id || "",
				milesTotal: round1(miles_total),
				gallonsTotal: round1(gallons_total),
				dayCount: day_count,
				latestDate: latest_date,
				mpgAvg: mpg_avg,
			};
		});

		res.json({
			days,
			tankAssumptionGallons: ROUTEMATE_DEFAULT_TANK_GALLONS,
			derivedFromTelemetry: true,
			trucks: result,
		});
	} catch (err) {
		console.error("fuel summary error:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// GET /api/routemate/fault-codes — Open ELD fault codes per truck. "Open"
// means last_seen within 24h AND not acked. Investor sees only own trucks.
app.get("/api/routemate/fault-codes", requireRole("Super Admin", "Dispatcher", "Investor"), (req, res) => {
	try {
		const user = req.session.user;
		const trucksFilter = (user.role === "Investor")
			? db.prepare("SELECT id, unit_number, routemate_vehicle_id, assigned_driver FROM trucks WHERE owner_id = ? AND COALESCE(routemate_vehicle_id, '') <> ''").all(user.id)
			: db.prepare("SELECT id, unit_number, routemate_vehicle_id, assigned_driver FROM trucks WHERE COALESCE(routemate_vehicle_id, '') <> ''").all();
		if (trucksFilter.length === 0) return res.json({ faults: [] });
		const placeholders = trucksFilter.map(() => "?").join(",");
		const args = trucksFilter.map(t => t.routemate_vehicle_id);
		const faults = db.prepare(`
			SELECT id, routemate_vehicle_id, code, status, ack_by_user_id,
			       strftime('%Y-%m-%dT%H:%M:%SZ', first_seen) AS first_seen,
			       strftime('%Y-%m-%dT%H:%M:%SZ', last_seen) AS last_seen,
			       strftime('%Y-%m-%dT%H:%M:%SZ', ack_at) AS ack_at
			FROM routemate_fault_codes
			WHERE routemate_vehicle_id IN (${placeholders})
			  AND ack_at IS NULL
			  AND last_seen > datetime('now', '-1 day')
			ORDER BY last_seen DESC
		`).all(...args);
		const byVehicle = {};
		for (const t of trucksFilter) byVehicle[t.routemate_vehicle_id] = t;
		const enriched = faults.map(f => {
			const t = byVehicle[f.routemate_vehicle_id] || {};
			return { ...f, truckId: t.id || null, unitNumber: t.unit_number || "", assignedDriver: t.assigned_driver || "" };
		});
		res.json({ faults: enriched });
	} catch (err) {
		console.error("fault-codes list error:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// GET /api/routemate/fault-codes/summary — Open fault count per truck.
// Used by FleetHealthView and InvestorView for the badge.
app.get("/api/routemate/fault-codes/summary", requireRole("Super Admin", "Dispatcher", "Investor"), (req, res) => {
	try {
		const user = req.session.user;
		const preview = resolvePreviewUser(req);
		const trucks = preview.isPreview
			? db.prepare("SELECT id, unit_number, routemate_vehicle_id FROM trucks WHERE owner_id = ?").all(preview.effectiveUserId)
			: (user.role === "Investor")
				? db.prepare("SELECT id, unit_number, routemate_vehicle_id FROM trucks WHERE owner_id = ?").all(user.id)
				: db.prepare("SELECT id, unit_number, routemate_vehicle_id FROM trucks").all();
		const countStmt = db.prepare(`
			SELECT COUNT(*) AS n FROM routemate_fault_codes
			WHERE routemate_vehicle_id = ?
			  AND ack_at IS NULL
			  AND last_seen > datetime('now', '-1 day')
		`);
		const result = trucks.map(t => ({
			truckId: t.id,
			unitNumber: t.unit_number,
			openFaults: t.routemate_vehicle_id ? (countStmt.get(t.routemate_vehicle_id).n || 0) : 0,
		}));
		res.json({ trucks: result });
	} catch (err) {
		console.error("fault-codes summary error:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// POST /api/routemate/fault-codes/:id/ack — Mark a fault as acknowledged.
// Sets ack_at + ack_by_user_id; the row stays in the table for audit but
// stops counting toward the open-fault badge. Super Admin + Dispatcher.
app.post("/api/routemate/fault-codes/:id/ack", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		const id = parseInt(req.params.id, 10);
		if (!id) return res.status(400).json({ error: "Invalid fault id" });
		const fault = db.prepare("SELECT id, routemate_vehicle_id, code, ack_at FROM routemate_fault_codes WHERE id = ?").get(id);
		if (!fault) return res.status(404).json({ error: "Fault not found" });
		if (fault.ack_at) return res.status(409).json({ error: "Already acknowledged" });
		const userId = req.session?.user?.id || 0;
		db.prepare("UPDATE routemate_fault_codes SET ack_at = CURRENT_TIMESTAMP, ack_by_user_id = ? WHERE id = ?").run(userId, id);
		logAudit(req, 'routemate_fault_ack', 'fault_code', String(id), `Acknowledged ELD fault ${fault.code} (vehicle ${fault.routemate_vehicle_id})`);
		res.json({ success: true });
	} catch (err) {
		console.error("fault-codes ack error:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// POST /api/messages — Send a new message
app.post("/api/messages", requireAuth, driverWriteLimiter, (req, res) => {
	try {
		const { to, message, loadId, attachmentUrl, attachmentType, assetRef } = req.body;
		// SECURITY: never trust the client-supplied `from`. A logged-in driver
		// who hits this endpoint directly could otherwise impersonate any user
		// (including dispatch). Drivers + Investors are pinned to their session
		// identity; Super Admin / Dispatcher may speak as the dispatch desk so
		// we keep their `from` overridable but default it to driverName / username.
		const sessionUser = req.session.user;
		const sessionName = (sessionUser?.driverName || sessionUser?.username || "").trim();
		const isPrivilegedSender = sessionUser?.role === "Super Admin" || sessionUser?.role === "Dispatcher";
		const requestedFrom = (req.body.from || "").trim();
		const from = isPrivilegedSender ? (requestedFrom || sessionName) : sessionName;
		if (!from || !to || (!message && !attachmentUrl && !assetRef)) {
			return res.status(400).json({ error: "from, to, and message required" });
		}

		const timestamp = new Date().toISOString();
		const result = db
			.prepare(
				`INSERT INTO messages (timestamp, "from", "to", message, load_id, attachment_url, attachment_type, asset_ref)
				 VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
			)
			.run(timestamp, from, to, message || "", loadId || "", attachmentUrl || "", attachmentType || "", assetRef || "");

		// Persist notification for recipient
		const msgNotif = insertNotification.run(
			to.trim().toLowerCase(), 'message',
			`New message from ${from}`,
			(message || "").length > 100 ? message.substring(0, 100) + '...' : (message || ""),
			JSON.stringify({ from, to, loadId: loadId || '' })
		);

		// PRIVACY: only emit to the actual participants + the dispatch room
		// (so admins can see all messages they're authorized to see). Previously
		// this used io.emit() which broadcast every message to every connected
		// client — drivers were receiving messages between other parties even
		// though the UI hid them.
		const payload = {
			id: result.lastInsertRowid,
			notificationId: msgNotif.lastInsertRowid,
			timestamp,
			from,
			to,
			message,
			loadId: loadId || "",
			attachment_url: attachmentUrl || "",
			attachment_type: attachmentType || "",
		};
		const fromRoom = (from || "").trim().toLowerCase();
		const toRoom = (to || "").trim().toLowerCase();
		if (fromRoom) io.to(fromRoom).emit("new-message", payload);
		if (toRoom && toRoom !== fromRoom) io.to(toRoom).emit("new-message", payload);
		if (fromRoom !== "dispatch" && toRoom !== "dispatch") {
			io.to("dispatch").emit("new-message", payload);
		}

		res.json({ success: true, id: result.lastInsertRowid });
	} catch (error) {
		console.error("Error sending message:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// PUT /api/messages/read — Mark messages as read
app.put("/api/messages/read", requireAuth, driverWriteLimiter, (req, res) => {
	try {
		const { messageIds } = req.body; // array of message IDs
		if (!messageIds || !messageIds.length) {
			return res.json({ success: true });
		}

		// SECURITY: Drivers can only mark messages addressed TO them. Admin/
		// Dispatcher keep the broader behavior so they can clear inbox-wide.
		const placeholders = messageIds.map(() => "?").join(",");
		const user = req.session.user;
		if (user.role === "Driver") {
			const recipient = (user.driverName || "").trim();
			db.prepare(
				`UPDATE messages SET read = 1 WHERE id IN (${placeholders}) AND LOWER("to") = LOWER(?)`,
			).run(...messageIds, recipient);
		} else {
			db.prepare(
				`UPDATE messages SET read = 1 WHERE id IN (${placeholders})`,
			).run(...messageIds);
		}

		res.json({ success: true });
	} catch (error) {
		console.error("Error marking messages read:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// PUT /api/notifications/read — Mark notifications as read
app.put("/api/notifications/read", requireAuth, driverWriteLimiter, (req, res) => {
	try {
		const { ids } = req.body;
		if (!ids || !ids.length) return res.json({ success: true });
		const placeholders = ids.map(() => "?").join(",");
		// SECURITY: Drivers can only mark their own notifications. Admin keeps
		// broader behavior (e.g. clearing dispatch alerts on behalf).
		const user = req.session.user;
		if (user.role === "Driver") {
			const driverNameLower = (user.driverName || "").trim().toLowerCase();
			db.prepare(`UPDATE notifications SET read = 1 WHERE id IN (${placeholders}) AND LOWER(driver_name) = ?`)
				.run(...ids, driverNameLower);
		} else {
			db.prepare(`UPDATE notifications SET read = 1 WHERE id IN (${placeholders})`).run(...ids);
		}
		res.json({ success: true });
	} catch (error) {
		console.error("Error marking notifications read:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// GET /api/dispatch-notifications — Fetch dispatch notifications
app.get("/api/dispatch-notifications", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		// SQLite's CURRENT_TIMESTAMP is UTC but serializes without a zone
		// ("2026-04-20 14:30:00"), which JS parses as local time — every row
		// then looks ~N hours in the future and the UI stuck on "just now".
		// Force ISO-8601 with Z so `new Date(...)` parses it as UTC.
		const notifications = db.prepare(
			`SELECT id, type, title, body, metadata, read,
			        strftime('%Y-%m-%dT%H:%M:%SZ', created_at) AS createdAt
			 FROM dispatch_notifications ORDER BY id DESC LIMIT 200`
		).all();
		const unreadCount = db.prepare(
			`SELECT COUNT(*) AS count FROM dispatch_notifications WHERE read = 0`
		).get().count;
		res.json({ notifications, unreadCount });
	} catch (error) {
		res.status(500).json({ error: error.message });
	}
});

// PUT /api/dispatch-notifications/read — Mark dispatch notifications as read
app.put("/api/dispatch-notifications/read", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		const { ids } = req.body;
		if (ids && ids.length) {
			const placeholders = ids.map(() => "?").join(",");
			db.prepare(`UPDATE dispatch_notifications SET read = 1 WHERE id IN (${placeholders})`).run(...ids);
		} else {
			db.prepare(`UPDATE dispatch_notifications SET read = 1 WHERE read = 0`).run();
		}
		res.json({ success: true });
	} catch (error) {
		res.status(500).json({ error: error.message });
	}
});

// GET /api/investor/messages — Investor's own message thread with dispatch
app.get("/api/investor/messages", requireRole("Super Admin", "Investor"), (req, res) => {
	try {
		// Super Admin previewing an investor's portal: scope by the target's username.
		// Note: read receipts deliberately do NOT fire in preview mode — the admin
		// is verifying what the investor sees, not consuming the investor's queue.
		const preview = resolvePreviewUser(req);
		const name = preview.effectiveUsername.trim().toLowerCase();
		const messages = db.prepare(
			`SELECT id, timestamp, "from", "to", message, load_id AS loadId, read, attachment_url, attachment_type, asset_ref
			 FROM messages
			 WHERE LOWER("from") = ? OR LOWER("to") = ?
			 ORDER BY id ASC`
		).all(name, name);
		if (!preview.isPreview) {
			// Mark messages to this investor as read
			db.prepare(`UPDATE messages SET read = 1 WHERE LOWER("to") = ? AND read = 0`).run(name);
		}
		res.json({ messages });
	} catch (err) {
		console.error("Error fetching investor messages:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// GET /api/messages — All messages for dispatch view (Admin/Dispatcher)
app.get("/api/messages", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		// Group conversations by driver + load
		const conversations = db
			.prepare(
				`SELECT
					CASE WHEN LOWER("from") = 'dispatch' THEN "to" ELSE "from" END AS driver,
					load_id AS loadId,
					MAX(timestamp) AS lastTimestamp,
					SUM(CASE WHEN LOWER("to") = 'dispatch' AND read = 0 THEN 1 ELSE 0 END) AS unread
				 FROM messages
				 GROUP BY driver, load_id
				 ORDER BY lastTimestamp DESC`,
			)
			.all();

		res.json({ conversations });
	} catch (error) {
		console.error("Error fetching messages:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// GET /api/messages/:driverName — Messages for a specific driver (Admin/Dispatcher)
app.get("/api/messages/:driverName", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		const driverName = decodeURIComponent(req.params.driverName).trim();
		const nameLower = driverName.toLowerCase();
		const loadId = req.query.loadId || "";

		let messages;
		if (loadId) {
			messages = db
				.prepare(
					`SELECT id, timestamp, "from", "to", message, load_id AS loadId, read, attachment_url, attachment_type
					 FROM messages
					 WHERE (LOWER("from") = ? OR LOWER("to") = ?) AND load_id = ?
					 ORDER BY id ASC`,
				)
				.all(nameLower, nameLower, loadId);
		} else {
			messages = db
				.prepare(
					`SELECT id, timestamp, "from", "to", message, load_id AS loadId, read, attachment_url, attachment_type
					 FROM messages
					 WHERE LOWER("from") = ? OR LOWER("to") = ?
					 ORDER BY id ASC`,
				)
				.all(nameLower, nameLower);
		}

		res.json({ messages });
	} catch (error) {
		console.error("Error fetching driver messages:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// Receipt photo storage helpers — write base64 data URIs to disk and return
// the URL path. Old base64-in-DB rows still work because the frontend img tag
// accepts both data URIs and URL paths.
const RECEIPTS_DIR = path.join(__dirname, "uploads", "expense-receipts");
try { fs.mkdirSync(RECEIPTS_DIR, { recursive: true }); } catch {}
// Image formats we are prepared to STORE AND SERVE as a receipt. Deliberately
// narrower than isValidImageMagic (which also allows GIF, because imageToPdf can
// render one): every other receipt consumer already agrees on exactly this set —
// the POST /api/expenses/ocr accept regex, POST /api/documents/scan,
// lib/receipt-ocr.js DATA_URI_RE, and MIME_BY_EXT in the two backfill scripts.
// It also makes the ext→MIME map in POST /api/expenses/:id/extract-details
// (`png ? : webp ? : image/jpeg`) correct BY CONSTRUCTION rather than by luck —
// its jpeg catch-all is only right while nothing else can reach the disk. A GIF
// is not a receipt.
const RECEIPT_IMAGE_EXTS = new Set(["jpg", "png", "webp"]);
const MAX_IMAGE_RECEIPT_BYTES = 20 * 1024 * 1024; // 20 MB decoded — far above any phone-camera receipt

// Returns { url } on success or { error, status } on refusal — the same shape as
// savePdfReceiptToDisk() below, so the image and PDF halves of a receipt upload
// read and fail consistently.
//
// SECURITY — this is the trust boundary, and the trusted thing is the BYTES.
// This used to take the data-URI's MIME token straight into the on-disk file
// extension (`data:image/(\w+)` → `.svg`, `.html`, …) with no byte check at all,
// while POST /api/expenses is only requireAuth. So any authenticated user — a
// Driver — could store `data:image/svg;base64,<svg onload=…>` or an HTML
// document, which uploads/ then served from our own origin to whichever
// dispatcher or Super Admin opened the receipt: stored XSS against exactly the
// sessions worth stealing. The label a client sends is a hint and is now used
// for NOTHING; sniffImageFormat decides both whether we store the file and what
// we name it.
function saveReceiptToDisk(photoData) {
	if (!photoData || typeof photoData !== "string") return { url: "" }; // no receipt attached — normal
	if (!photoData.startsWith("data:")) return { url: photoData }; // already a URL/path (legacy rows)
	// The MIME token is captured only so a malformed URI can be told apart from a
	// well-formed one; it is never read. Matching `[^;,]*` rather than the old
	// `image/(\w+)` means a mislabelled payload is REFUSED here instead of
	// slipping past the regex into the old silent drop.
	const m = photoData.match(/^data:([^;,]*);base64,(.+)$/);
	if (!m) return { error: "Receipt must be a base64 image data URI", status: 400 };
	// Cheap pre-decode guard: base64 inflates ~4/3, so anything longer than this
	// cannot decode under the byte cap — reject before buffering it.
	if (m[2].length > Math.ceil((MAX_IMAGE_RECEIPT_BYTES * 4) / 3) + 4) {
		return { error: "Receipt image too large (max 20 MB)", status: 413 };
	}
	const buf = Buffer.from(m[2], "base64");
	if (buf.length === 0) return { error: "Receipt image could not be decoded", status: 400 };
	if (buf.length > MAX_IMAGE_RECEIPT_BYTES) return { error: "Receipt image too large (max 20 MB)", status: 413 };
	const ext = sniffImageFormat(buf);
	if (!ext || !RECEIPT_IMAGE_EXTS.has(ext)) {
		return { error: "Receipt must be a JPEG, PNG, or WebP image", status: 400 };
	}
	const fname = `${Date.now()}-${crypto.randomBytes(6).toString("hex")}.${ext}`;
	try {
		fs.writeFileSync(path.join(RECEIPTS_DIR, fname), buf);
		return { url: `/uploads/expense-receipts/${fname}` };
	} catch (err) {
		console.error("Receipt save failed:", err.message);
		return { error: "Failed to store receipt image", status: 500 };
	}
}

// PDF receipts (admin/dispatcher "Log Expense" only — 2026-06-11 owner
// meeting: toll invoices, emailed receipts, etc. arrive as PDFs). Stored in
// the same expense-receipts dir so the per-truck ZIP bundle picks them up
// automatically (it preserves the file extension). PDF failures return an
// explicit error so an admin never saves an expense believing the invoice
// attached when it didn't — the image path above now does the same, so the two
// halves behave identically. (It used to drop silently; that asymmetry was the
// bug, and this comment used to describe it as legacy behaviour to preserve.)
const MAX_PDF_RECEIPT_BYTES = 15 * 1024 * 1024; // 15 MB decoded
function savePdfReceiptToDisk(photoData) {
	const m = String(photoData).match(/^data:application\/pdf;base64,(.+)$/i);
	if (!m) return { error: "Receipt must be a base64 PDF data URI", status: 400 };
	// Cheap pre-decode guard: base64 inflates ~4/3, so anything longer than
	// this cannot decode under the byte cap — reject before buffering it.
	if (m[1].length > Math.ceil((MAX_PDF_RECEIPT_BYTES * 4) / 3) + 4) {
		return { error: "Receipt PDF too large (max 15 MB)", status: 413 };
	}
	const buf = Buffer.from(m[1], "base64");
	if (buf.length === 0) return { error: "Receipt PDF could not be decoded", status: 400 };
	if (buf.length > MAX_PDF_RECEIPT_BYTES) return { error: "Receipt PDF too large (max 15 MB)", status: 413 };
	// Magic bytes: a real PDF starts with "%PDF-". The data-URI MIME alone is
	// client-controlled (same reasoning as isValidImageMagic at top of file).
	if (buf.length < 5 || buf.toString("latin1", 0, 5) !== "%PDF-") {
		return { error: "File is not a valid PDF", status: 400 };
	}
	const fname = `${Date.now()}-${crypto.randomBytes(6).toString("hex")}.pdf`;
	try {
		fs.writeFileSync(path.join(RECEIPTS_DIR, fname), buf);
		return { url: `/uploads/expense-receipts/${fname}` };
	} catch (err) {
		console.error("Receipt PDF save failed:", err.message);
		return { error: "Failed to store receipt PDF", status: 500 };
	}
}

// Geocode-enrichment budget. Expense inserts are driver-triggerable and every
// UNIQUE junk city is a billable Google Geocoding call (geocode_cache only
// dedupes exact strings), so cap enrichment lookups per UTC day and require a
// plausible city string. Enrichment is best-effort — skipping is always safe.
const GEOCODE_ENRICH_DAILY_MAX = 500;
const GEOCODE_CITY_RE = /^[A-Za-z][A-Za-z .'\-]{1,49}$/;
let geocodeEnrichDay = "";
let geocodeEnrichCount = 0;
function spendGeocodeBudget() {
	const day = new Date().toISOString().slice(0, 10);
	if (day !== geocodeEnrichDay) { geocodeEnrichDay = day; geocodeEnrichCount = 0; }
	if (geocodeEnrichCount >= GEOCODE_ENRICH_DAILY_MAX) return false;
	geocodeEnrichCount++;
	return true;
}

// POST /api/expenses — Log a new expense (SQLite)
// Receipt "details" = the dynamic label/value pairs runReceiptOcr extracts from
// a receipt (fuel: pump/grade/PPG; food: items/tax/tip; etc.), stored as a JSON
// string in expenses.receipt_details. sanitize → store, parse → serve.
function sanitizeReceiptDetails(v) {
	let arr = v;
	if (typeof arr === "string") { try { arr = JSON.parse(arr); } catch { return ""; } }
	if (!Array.isArray(arr)) return "";
	const clean = arr
		.filter((d) => d && typeof d === "object" && typeof d.label === "string" && d.label.trim())
		.slice(0, 40)
		.map((d) => ({
			label: d.label.trim().slice(0, 40),
			value: (typeof d.value === "string" ? d.value : String(d.value == null ? "" : d.value)).trim().slice(0, 200),
		}));
	return clean.length ? JSON.stringify(clean) : "";
}
function parseReceiptDetails(s) {
	if (!s || typeof s !== "string") return [];
	try { const a = JSON.parse(s); return Array.isArray(a) ? a : []; } catch { return []; }
}

app.post("/api/expenses", requireAuth, driverWriteLimiter, async (req, res) => {
	try {
		const { loadId, type, amount, description, date, photoData, gallons, odometer, city, state, vendor } =
			req.body;
		// Dynamic OCR-extracted receipt fields the client reviewed (editable). Optional.
		const safeReceiptDetails = sanitizeReceiptDetails(req.body.receiptDetails != null ? req.body.receiptDetails : req.body.receipt_details);
		// SECURITY: drivers must use their session identity; admin/dispatcher
		// can pass driver in the body to log on behalf. Investors cannot log
		// at all. resolveDriverActor returns null after sending the response.
		if (req.session.user.role === "Investor") {
			return res.status(403).json({ error: "Investors cannot submit expenses" });
		}
		const driver = resolveDriverActor(req, res, req.body.driver);
		if (driver === null) return;
		if (!driver || !type || !amount || !date) {
			return res.status(400).json({ error: "Missing required fields" });
		}
		const VALID_EXPENSE_TYPES = ['Fuel', 'Repair', 'Maintenance', 'Wear & Tear', 'Toll', 'Food', 'Other'];
		if (!VALID_EXPENSE_TYPES.includes(type)) {
			return res.status(400).json({ error: "Invalid expense type" });
		}
		// Validate amount: must be positive number under 1M
		const parsedAmount = parseFloat(amount);
		if (isNaN(parsedAmount) || parsedAmount <= 0 || parsedAmount > 1_000_000) {
			return res.status(400).json({ error: "Amount must be a positive number under 1,000,000" });
		}
		// Date must be a real calendar day — junk like "2026-13-01" would leak
		// into month buckets and the ELD enrichment window math downstream.
		if (!/^\d{4}-\d{2}-\d{2}$/.test(String(date)) || !Number.isFinite(Date.parse(`${date}T00:00:00Z`))) {
			return res.status(400).json({ error: "Date must be a valid YYYY-MM-DD" });
		}
		// Sanitize free-text fields
		const safeDescription = (description || "").toString().slice(0, 500);
		const safeLoadId = (loadId || "").toString().slice(0, 100);
		// Merchant City/State (optional — prefilled by receipt OCR, editable).
		// city: trimmed, <=60 chars. state: a 2-letter US code, else dropped.
		const safeCity = (city || "").toString().trim().slice(0, 60);
		const rawState = (state || "").toString().trim().toUpperCase();
		const safeState = /^[A-Z]{2}$/.test(rawState) ? rawState : "";
		// Merchant name (optional — prefilled by receipt OCR, editable). Explicit
		// vendors normalize leniently (unknown brands still group). The
		// description fallback exists for legacy clients that folded the OCR
		// vendor into description — those are overwhelmingly known brands, so it
		// is ALIAS-GATED (mirrors backfill pass 1b): free-typed text like
		// "oil change" must never mint a pseudo-vendor in the leaderboard.
		const safeVendor = (vendor || "").toString().trim().slice(0, 80);
		let vendorNormalized = normalizeVendor(safeVendor);
		if (!vendorNormalized && safeDescription) {
			const det = normalizeVendorDetailed(safeDescription);
			if (det.aliasHit) vendorNormalized = det.normalized;
		}

		// SECURITY: drivers can only file expenses against loads assigned to
		// them. Without this check a driver could pollute another driver's
		// load expense history (and their per-load profitability roll-up).
		// Admin/Dispatcher act on behalf of any driver so they're exempt.
		if (req.session.user.role === "Driver" && safeLoadId) {
			const owned = await loadBelongsToDriver(safeLoadId, driver);
			if (!owned) return res.status(403).json({ error: "This load is not assigned to you" });
		}

		const timestamp = new Date().toISOString();
		// Look up truck/owner for this driver to stamp on expense
		const driverTruck = db.prepare("SELECT unit_number, owner_id, routemate_vehicle_id FROM trucks WHERE LOWER(assigned_driver) = LOWER(?)").get(driver.trim());
		const expOwnerId = driverTruck ? driverTruck.owner_id : 0;
		const expTruckUnit = driverTruck ? driverTruck.unit_number : '';
		// DEDUP: Deshorn bulk-uploads receipts drivers text him, and the same
		// photo routinely arrives twice. Hash the receipt payload (sha256 of the
		// base64) and reject a re-upload before it double-books the P&L. Only a
		// data-URI payload carries a receipt to hash; an already-stored URL/path
		// does not. A hit on a non-empty hash → 409 so the client flags the row
		// (a duplicate, not a retryable error). POST /api/expenses is not
		// idempotent, so this is the server guard behind the client's in-batch
		// file dedup. Checked before the file is written so a dup leaves no orphan.
		let receiptHash = "";
		if (typeof photoData === "string" && photoData.startsWith("data:")) {
			const comma = photoData.indexOf(",");
			const b64 = comma >= 0 ? photoData.slice(comma + 1) : "";
			if (b64) receiptHash = crypto.createHash("sha256").update(b64).digest("hex");
		}
		// Prefer the client's hash of the ORIGINAL file when it sends one. The
		// stored payload stopped being byte-stable once bulk upload began running
		// images through ScanKit — which silently falls back to the un-enhanced
		// image when it is down or out of credits — so the same receipt could
		// re-enter under a different payload hash and double-book the P&L (and the
		// investor payout deduction). Both hashes are checked so a receipt logged
		// before this change is still recognized.
		//
		// ⚠️ ACCEPTED ONLY ALONGSIDE A PAYLOAD. The value is never checked against the
		// bytes received — it cannot be, that is the point of it — so before this
		// line any authenticated non-Investor could POST an expense carrying a
		// `sourceHash` and NOTHING ELSE and permanently burn that hash:
		// idx_expenses_receipt_hash is UNIQUE, so the receipt's real filer then gets a
		// hard 409 DUPLICATE_RECEIPT with no race to rescue them and no way to file
		// the expense at all. Guessing a sha256 is not an attack; pre-registering
		// hashes read off receipts you have SEEN is, and so is the accidental
		// version — any script that resends a hash without its payload.
		//
		// Ignoring `sourceHash` outright is NOT the fix and would re-open the
		// double-booking above. Requiring the payload is: bulk upload always sends
		// `photoData` beside it (BulkReceiptScan.saveOne), which is the ONLY caller
		// that sends `sourceHash` at all, so no real workflow loses anything.
		//
		// ⚠️ THIS RAISES THE COST OF THE BURN; IT DOES NOT ABOLISH IT, and the residual
		// is SMALLER THAN AN EARLIER DRAFT OF THIS COMMENT CLAIMED — corrected here
		// because the next reader will price the risk off these numbers.
		//
		//   • THE PAYLOAD FLOOR IS 12 BYTES, NOT ~70. The only gate on this path is
		//     sniffImageFormat() inside saveReceiptToDisk(): a magic prefix plus its
		//     >=12-byte floor, so `FF D8 FF` and nine bytes of padding is an accepted
		//     "image". verifyInlineServedBytes() and validateFileExt() are NOT on this
		//     path — they guard the /uploads mount and the document upload route.
		//     The PDF branch (savePdfReceiptToDisk) is 5 bytes: `%PDF-`.
		//   • "ATTRIBUTABLE" HOLDS ONLY FOR `role === "Driver"`. `expenses` carries no
		//     actor column — the INSERT below writes `driver`, not a user id — and
		//     resolveDriverActor() pins the name to the session for that role ONLY;
		//     for a Dispatcher or Super Admin it returns the request's own string
		//     verbatim. So on those two roles the row names whichever driver the
		//     caller typed, and the audit link back to the account is the session log,
		//     not this table.
		//
		// What genuinely changes is that the attempt is no longer free or invisible: it
		// must create a real, validated expense row under a driver name, with a receipt
		// file written to disk, subject to the amount/date rules and the duplicate
		// checks — i.e. it leaves an artefact, where a payload-less pre-registration
		// left none. The structural fix is a SEPARATE `source_hash` column, leaving
		// `receipt_hash` as the server-computed payload hash that no caller can choose;
		// that is a migration on a UNIQUE index and is deliberately not attempted here.
		//
		// ⚠️ AND IT COSTS ONE THING, STATED RATHER THAN GLOSSED: a bulk row whose FILE
		// COULD NOT BE READ AT ALL keeps `photoData: ''` (BulkReceiptScan's three
		// failure paths) and is still savable, since saveAll validates only
		// driver/amount/date. Such a row used to be byte-deduped on the client's hash
		// and now is not — it stores `receipt_hash = ''`, which the PARTIAL unique
		// index does not constrain. It is not undefended: the content check below
		// (same driver + day + amount) is what actually catches the re-upload of a
		// receipt that has no readable bytes, and that check is unconditional. The
		// client no longer sends a hash it is not backing with bytes, so this path is
		// honest on the wire rather than silently discarded here.
		//
		// `receiptHash` is the predicate rather than a fresh re-test of `photoData`
		// because it is non-empty EXACTLY when a `data:` payload with a non-empty
		// body arrived and was hashed. A second test would be a second definition of
		// "a payload came with this request", and those drift.
		const rawSourceHash = (req.body && req.body.sourceHash) || "";
		const sourceHash = receiptHash && /^[a-f0-9]{64}$/i.test(String(rawSourceHash).trim())
			? String(rawSourceHash).trim().toLowerCase()
			: "";
		const hashCandidates = [...new Set([sourceHash, receiptHash].filter(Boolean))];
		if (hashCandidates.length) {
			// ⚠️ SCOPED TO THE FILING DRIVER, exactly as the POSSIBLE_DUPLICATE check
			// below already is. Unscoped, this SELECT was a queryable oracle over every
			// receipt in the fleet: any authenticated caller could probe an arbitrary
			// hash and be told whether it is booked AND the expense id that holds it —
			// a cross-driver read, on a route whose own answer is otherwise scoped.
			//
			// ⚠️ THIS NARROWS THE MESSAGE, NEVER THE ENFORCEMENT — and the pair of
			// queries below is what makes that true UNCONDITIONALLY, rather than only
			// on a database where a boot-time migration happened to succeed.
			//
			// The first draft leaned entirely on the index: "a cross-driver collision
			// falls through to the INSERT and the UNIQUE constraint refuses it". That
			// holds only while idx_expenses_receipt_hash IS unique, and the migration
			// beside the column has a documented SKIP path — its collision pre-flight
			// finds duplicate hashes, logs SKIPPED, and deliberately leaves the OLD
			// NON-UNIQUE index in place (correctly: which of two rows sharing a receipt
			// is the real expense is a business question, and both are money already
			// booked). A refreshed or staging database seeded from an older snapshot is
			// exactly the shape that skips. On such a database the scoped SELECT
			// answers "no", the INSERT is unconstrained, and the receipt is
			// DOUBLE-BOOKED into the P&L and the investor payout deduction — which is
			// the precise defect the index exists to prevent, reintroduced by a change
			// that was only ever meant to stop an information leak.
			//
			// So the REFUSAL is decided fleet-wide and the MESSAGE is decided per
			// driver. Two queries, not one with an extra column, because the second
			// must be incapable of leaking: it selects the literal 1 and no id, so
			// there is nothing for a later edit to accidentally put on the wire.
			const dup = db
				.prepare(
					`SELECT id FROM expenses
					  WHERE receipt_hash IN (${hashCandidates.map(() => "?").join(",")})
					    AND LOWER(TRIM(COALESCE(driver, ''))) = LOWER(TRIM(?))
					  LIMIT 1`,
				)
				.get(...hashCandidates, driver || "");
			if (dup) {
				return res.status(409).json({
					error: `This receipt was already logged (expense #${dup.id})`,
					code: "DUPLICATE_RECEIPT",
					existingId: dup.id,
				});
			}
			// The enforcement half. Byte-identical response to the constraint path's
			// unnamed 409 below, so the caller cannot tell which door refused it — and
			// so an admin filing on behalf of a driver still sees "already logged"
			// rather than a duplicate row appearing in the P&L.
			//
			// ⚠️ NO `id` IN THE SELECT LIST. That is the whole discipline: the oracle
			// this scoping removed was "tell me WHICH expense holds this hash", and a
			// boolean cannot answer it. It does still confirm that SOME row holds the
			// hash — unavoidable, because refusing the write IS that disclosure, and it
			// is the same single bit the UNIQUE index has always disclosed by refusing.
			const taken = db
				.prepare(
					`SELECT 1 FROM expenses
					  WHERE receipt_hash IN (${hashCandidates.map(() => "?").join(",")})
					  LIMIT 1`,
				)
				.get(...hashCandidates);
			if (taken) {
				return res.status(409).json({
					error: "This receipt was already logged",
					code: "DUPLICATE_RECEIPT",
				});
			}
		}
		// Store the stable one so future re-uploads collide regardless of processing.
		if (sourceHash) receiptHash = sourceHash;

		// CONTENT DEDUP — the hash check above only fires on identical BYTES, and
		// that misses the most common real-world case: the driver logs a receipt
		// from his phone, then the same photo is bulk-uploaded by an admin. The
		// phone's HEIC is converted to JPEG client-side before upload, so the two
		// never share a hash even though they are the same purchase. (2026-08-01:
		// three such pairs — QuikTrip Conroe $500, Alvarado $450, Gardner $30 —
		// were caught only by manual audit, after an earlier round of duplicates
		// had already inflated the investor payout deduction.)
		//
		// Same merchant + same day + same amount is strong but NOT proof: a driver
		// can genuinely fuel twice at one stop. So the 409 is a STOP, not a verdict —
		// distinct code, and `allowDuplicate: true` lets the caller consciously
		// override, mirroring the conscious per-row Retry used for save timeouts.
		//
		// ⚠️ ON BY DEFAULT SINCE 2026-08-12, AND THE PARAGRAPH THAT USED TO SIT HERE
		// ARGUED THE OPPOSITE — read this before re-reading it as opt-in. The check
		// was gated on the caller sending `checkDuplicate: true`, on the reasoning
		// that whether a 409 is survivable is a property of the SURFACE: only a form
		// that can offer "save anyway" may ask for it, and the driver app's
		// ExpenseForm cleared the photo and every field the moment it submitted, so
		// a 409 there would strand the user AND destroy the receipt with no way to
		// re-file it. That reasoning was sound and its PRECONDITION has now been met
		// — ExpenseForm retains its photo across a failed submit — so the gate is
		// gone. Only `ExpensesTab` and `BulkReceiptScan` ever sent the flag, which
		// meant every other writer (the driver app, and any script) could book a
		// known duplicate with no check at all. The client ask is "make sure that
		// the receipt doesn't have any duplicate"; a check nobody has to ask for is
		// not that.
		//
		// ⚠️ THERE IS EXACTLY ONE OVERRIDE, AND IT IS AUDITED. `allowDuplicate: true`
		// writes an `expense_duplicate_override` audit row, which is also what
		// CLOSES the pair in duplicateReceiptGroups() and stops the sweep below
		// re-pinging it. `checkDuplicate` is deliberately NOT honoured as an opt-OUT:
		// a second, silent door around the guard is how the first version of this
		// came to be unenforced everywhere, and an override that leaves no trace
		// cannot dismiss anything. The key is still accepted and ignored, so the two
		// existing clients keep working unchanged.
		//
		// Scoped to the SAME driver: the incident is one driver's receipt entered
		// twice, so this keeps every real case while dropping the largest
		// false-positive class (two trucks hitting one brand on one day for the
		// same round prepaid amount — $500/$30 are exactly such amounts).
		//
		// ⚠️ THE MERCHANT IS NOT REQUIRED TO MATCH, and that is the fix. This used
		// to be `WHERE vendor_normalized = ?`, gated on the incoming row having a
		// vendor at all — so it could only ever fire when BOTH sides named the same
		// merchant. Measured against production that is the minority case: of the
		// five pairs actually double-booked, three have no merchant on one side
		// (the copy that was typed blind, without the receipt OCR'd) and one has no
		// merchant on either. The check was structurally incapable of seeing four of
		// the five. Matching is now truck/driver + day + amount, with
		// lib/receipt-duplicates.js deciding — which is what keeps this from
		// becoming the too-aggressive key: a pair whose merchants BOTH exist and
		// differ, or whose gallons both exist and differ, is exonerated in JS rather
		// than never being looked at.
		//
		// Nothing here edits or voids the existing row — the 409 refuses the NEW
		// write and names the row it collided with; deciding which of the two is
		// real stays a human's job.
		const wantsDuplicateCheck = req.body?.allowDuplicate !== true;
		const incomingRow = { vendor_normalized: vendorNormalized, gallons: parseFloat(gallons) || 0 };
		const findContentDuplicate = () => {
			// Same driver, same day, same amount — the candidate set, still SCOPED TO
			// ONE DRIVER (two trucks hitting one brand on one day for the same round
			// prepaid amount is the largest false-positive class, and $200/$400 are
			// exactly such amounts). Bounded because a candidate set is a truck-day.
			const candidates = db
				.prepare(
					`SELECT id, driver, amount, date, vendor, vendor_normalized, gallons FROM expenses
					 WHERE date = ? AND ROUND(amount, 2) = ROUND(?, 2)
					   AND LOWER(TRIM(COALESCE(driver, ''))) = LOWER(TRIM(?))
					   AND COALESCE(status, '') != 'Rejected'
					 ORDER BY id DESC LIMIT 20`,
				)
				.all(date, parsedAmount, driver || "");
			// Report the STRONGEST match, not the newest: with two candidates on one
			// truck-day the one that agrees on a merchant is the one worth naming.
			let best = null, bestRank = 0;
			for (const c of candidates) {
				const verdict = receiptDuplicates.judgeReceiptPair(incomingRow, c);
				if (!verdict.duplicate) continue;
				const rank = receiptDuplicates.CONFIDENCE_RANK[verdict.confidence] || 0;
				if (rank > bestRank) { bestRank = rank; best = c; }
			}
			return best;
		};
		if (wantsDuplicateCheck && parsedAmount > 0) {
			const near = findContentDuplicate();
			if (near) {
				return res.status(409).json({
					// Names the EXISTING row's merchant, or says it has none — never
					// falls back to the incoming row's. The whole point of this widening
					// is that the two sides often disagree about the merchant, so
					// printing ours over theirs would describe a row that does not exist
					// and make the warning impossible to check against the receipt.
					error: `Looks like this was already logged — expense #${near.id} (${near.vendor || "no merchant recorded"}, ${near.date}, $${near.amount}${near.driver ? `, ${near.driver}` : ""}). Save anyway if it is a separate purchase.`,
					code: "POSSIBLE_DUPLICATE",
					existingId: near.id,
					existing: { id: near.id, driver: near.driver, amount: near.amount, date: near.date, vendor: near.vendor },
				});
			}
		}
		// An override books money against a warning a human dismissed. The original
		// duplicates took a manual audit to find; leave something greppable so the
		// next one doesn't.
		// The `vendorNormalized &&` precondition is gone here too, and not just for
		// symmetry: this audit line is what CLOSES the row's group in the duplicate
		// queue (duplicateReceiptGroups suppresses on it). Left gated on the
		// merchant, an override of a blank-merchant warning would book the money and
		// leave the queue nagging about a pair a human had already settled — i.e.
		// exactly the rows this widening newly catches would be the ones that could
		// never be dismissed.
		let overrodeDuplicateOf = null;
		if (req.body?.allowDuplicate === true && parsedAmount > 0) {
			const near = findContentDuplicate();
			if (near) overrodeDuplicateOf = near.id;
		}
		// Receipt: both halves now fail loudly on a bad format. PDFs are an
		// admin/dispatcher-only addition (toll invoices etc.); images take the
		// branch below. The image path used to DROP a bad format silently, which
		// meant the two behaved differently for the same class of problem and,
		// worse, that a receipt could vanish while the money was still booked —
		// the exact failure savePdfReceiptToDisk's comment was written to avoid.
		// A genuine JPEG/PNG/WebP is unaffected either way; the only requests
		// that newly get a 400 are ones carrying bytes we would refuse to store.
		let photoUrlOrPath = "";
		// ⚠️ ONLY SET WHEN THIS REQUEST ACTUALLY WROTE THE BYTES, and that
		// distinction is load-bearing for the UNIQUE-constraint cleanup below.
		// saveReceiptToDisk() has a pass-through branch — `if
		// (!photoData.startsWith("data:")) return { url: photoData }` for legacy
		// rows — so photoUrlOrPath can be a CLIENT-SUPPLIED path naming a file that
		// belongs to a DIFFERENT expense. Deleting that on a failed insert would
		// destroy another row's receipt, which is strictly worse than the orphan the
		// cleanup exists to avoid. Only a data-URI request creates a new file.
		let wroteReceiptFile = "";
		if (typeof photoData === "string" && /^data:application\/pdf;base64,/i.test(photoData)) {
			const role = req.session.user.role;
			if (role !== "Super Admin" && role !== "Dispatcher") {
				return res.status(403).json({ error: "PDF receipts are limited to admin and dispatcher uploads" });
			}
			const savedPdf = savePdfReceiptToDisk(photoData);
			if (savedPdf.error) return res.status(savedPdf.status || 400).json({ error: savedPdf.error });
			photoUrlOrPath = savedPdf.url;
			wroteReceiptFile = savedPdf.url;
		} else {
			const savedImg = saveReceiptToDisk(photoData);
			if (savedImg.error) return res.status(savedImg.status || 400).json({ error: savedImg.error });
			photoUrlOrPath = savedImg.url;
			if (typeof photoData === "string" && photoData.startsWith("data:")) wroteReceiptFile = savedImg.url;
		}
		// Best-effort geo enrichment — a failure here must NEVER fail the insert.
		// (a) City+State known (OCR/admin) → forward geocode (cached, null-safe).
		// (b) No state, but the driver's truck is ELD-linked → locate the truck
		//     from clean telemetry pings on the expense's calendar day and derive
		//     the state via the IFTA bounding boxes. City is never invented.
		let locLat = null, locLng = null, locSource = "";
		let enrichState = safeState, enrichCity = safeCity;
		try {
			if (safeCity && safeState && GEOCODE_CITY_RE.test(safeCity) && spendGeocodeBudget()) {
				const g = await geocodeAddress(`${safeCity}, ${safeState}`);
				if (g) { locLat = g.lat; locLng = g.lng; locSource = "geocode"; }
			} else if (!safeState && driverTruck?.routemate_vehicle_id) {
				// Window = user-entered day: [00:00Z − 6h, 00:00Z + 30h] covers the
				// full local day in every US zone; pick the ping closest to 18:00Z
				// (≈ noon Central) as the "midday" position.
				const dayMs = Date.parse(`${date}T00:00:00Z`);
				if (Number.isFinite(dayMs)) {
					const pings = db.prepare(
						`SELECT latitude, longitude, location_date_ms FROM routemate_telemetry
						 WHERE routemate_vehicle_id = ? AND dropped_reason = ''
						   AND location_date_ms BETWEEN ? AND ?`
					).all(driverTruck.routemate_vehicle_id, dayMs - 6 * 3600e3, dayMs + 30 * 3600e3);
					const targetMs = Date.parse(`${date}T18:00:00Z`);
					let best = null;
					for (const p of pings) {
						if (typeof p.latitude !== "number" || typeof p.longitude !== "number") continue;
						if (!best || Math.abs(p.location_date_ms - targetMs) < Math.abs(best.location_date_ms - targetMs)) best = p;
					}
					if (best) {
						const pingState = getStateFromCoords(best.latitude, best.longitude);
						if (/^[A-Z]{2}$/.test(pingState || "")) {
							enrichState = pingState;
							locLat = best.latitude;
							locLng = best.longitude;
							locSource = "eld";
						}
					}
				}
			}
		} catch (e) {
			console.warn("expense enrichment skipped:", e.message);
		}
		// Settlement posting month. A receipt whose own month is still open books
		// to that month (posted_period = '', the overwhelmingly normal case). One
		// whose month has already been FINALIZED books to the current open month
		// instead — a prior-period adjustment.
		//
		// Never reject the write: the receipt is real money that left the bank, and
		// refusing it means it never enters the books at all. It also teaches people
		// to fudge the date to get it in, which would corrupt the true purchase date
		// that IFTA and fuel cost-per-gallon read. So `date` is preserved verbatim
		// and only the BOOKING month moves.
		//
		// Always the current month, never a future one: posting forward would drop
		// the expense into a period with no earnings row to absorb it and break the
		// ledger's paid+processing+owed+accruing == earned+adjustments identity.
		//
		// periodWriteLocked, not isLocked: on an unreadable lock table isLocked
		// answers "open" for every month, so the redirect silently stops happening
		// and late receipts book straight into closed periods — the same fail-open
		// as the odometer backfill, on the row itself rather than one column of it.
		// Failing closed here costs nothing anyone loses: the receipt is still
		// written, at its true `date`, just booked to the current open month, which
		// is the reversible direction. The `!== openPeriod` test keeps that from
		// degenerating into stamping every receipt with its own month.
		const naturalPeriod = String(date || "").slice(0, 7);
		const openPeriod = currentMonthKeyCT();
		const lockUnreadable = !periodLocksReadable();
		const postedPeriod = naturalPeriod && naturalPeriod !== openPeriod && periodWriteLocked(naturalPeriod) ? openPeriod : "";

		// ⚠️ THE CONSTRAINT IS THE GUARD; THE SELECT ABOVE IS ONLY THE NICE MESSAGE.
		// idx_expenses_receipt_hash is UNIQUE over receipt_hash <> '' (see the
		// migration beside the column), so the byte-identical-receipt case is
		// decided here rather than in the check-then-act window the bulk uploader's
		// 3-wide concurrency opens. Without this catch the loser of that race gets a
		// generic 500 — "Failed to log expense" — which the client retries, so the
		// one outcome the index exists to produce would read as a transient fault.
		// Translated to the SAME 409/DUPLICATE_RECEIPT the pre-check emits, so both
		// paths are indistinguishable to the caller.
		let result;
		try {
			result = db
				.prepare(
					`INSERT INTO expenses (timestamp, driver, load_id, type, amount, description, date, photo_data, gallons, odometer, owner_id, truck_unit, location_city, location_state, vendor, vendor_normalized, location_lat, location_lng, location_source, receipt_hash, receipt_details, posted_period)
					 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
				)
				.run(timestamp, driver, safeLoadId, type, parsedAmount, safeDescription, date, photoUrlOrPath,
					parseFloat(gallons) || 0, parseFloat(odometer) || 0, expOwnerId, expTruckUnit, enrichCity, enrichState,
					safeVendor, vendorNormalized, locLat, locLng, locSource, receiptHash, safeReceiptDetails, postedPeriod);
		} catch (insErr) {
			// Narrow on better-sqlite3's `code`, never on the message text, and
			// narrow on the INDEX NAME too: this table carries other constraints, and
			// reporting an unrelated violation as "duplicate receipt" would send
			// whoever reads it looking for a second copy that does not exist.
			const isDupReceipt = insErr && insErr.code === "SQLITE_CONSTRAINT_UNIQUE"
				&& String(insErr.message || "").includes("expenses.receipt_hash");
			if (!isDupReceipt) throw insErr;
			// Name the winner if we can. Best-effort: the row is certainly there, but
			// a failed re-read must not turn a clean 409 into a 500.
			//
			// ⚠️ SCOPED TO THE FILING DRIVER, THE SAME WAY THE PRE-CHECK ABOVE IS, or
			// the oracle simply moves house. The UNIQUE index is fleet-wide, so a
			// cross-driver collision reaches HERE rather than the pre-check — and an
			// unscoped re-read would hand back another driver's expense id on exactly
			// the request the pre-check just refused to answer. The 409 is unchanged
			// either way (the receipt is still refused, and the index is what refuses
			// it); only the id is withheld, and the caller who cannot see the row is
			// the caller who has no business seeing it.
			let winnerId = null;
			try {
				const w = db.prepare(
					`SELECT id FROM expenses
					  WHERE receipt_hash = ?
					    AND LOWER(TRIM(COALESCE(driver, ''))) = LOWER(TRIM(?))
					  LIMIT 1`,
				).get(receiptHash, driver || "");
				winnerId = w ? w.id : null;
			} catch { /* best effort */ }
			// The receipt file was written to disk above and the row that would have
			// owned it does not exist, so it is an orphan — remove it rather than
			// leave the uploads tree growing a copy per lost race.
			//
			// ⚠️ KEYED ON wroteReceiptFile, NEVER ON photoUrlOrPath. The two differ
			// exactly when the client passed an existing path instead of a data URI
			// (saveReceiptToDisk's legacy pass-through), in which case that path names
			// ANOTHER expense's receipt and unlinking it destroys a live row's
			// evidence. ⚠️ The example that used to sit here — "a caller can send no
			// data URI at all and still reach this 409 by supplying a `sourceHash`
			// that collides" — is NO LONGER REACHABLE: `sourceHash` is now honoured
			// only alongside a payload, so a request with no data URI carries an empty
			// receipt_hash, which the PARTIAL unique index (`WHERE receipt_hash <> ''`)
			// does not constrain at all. The rule stands on its own merits regardless,
			// and must: it is the difference between deleting our own orphan and
			// deleting a live expense's receipt.
			try {
				if (wroteReceiptFile && wroteReceiptFile.startsWith("/uploads/expense-receipts/")) {
					const orphan = path.join(__dirname, wroteReceiptFile.replace(/^\//, ""));
					if (orphan.startsWith(path.join(__dirname, "uploads", "expense-receipts"))) fs.unlinkSync(orphan);
				}
			} catch { /* best effort */ }
			return res.status(409).json({
				error: winnerId
					? `This receipt was already logged (expense #${winnerId})`
					: "This receipt was already logged",
				code: "DUPLICATE_RECEIPT",
				...(winnerId ? { existingId: winnerId } : {}),
			});
		}

		// Tell the caller when a receipt was redirected, so the UI can say
		// "March is closed — booked to August" rather than silently moving money
		// between months. Also on the audit trail: this is a settlement decision.
		if (postedPeriod) {
			logAudit(req, "expense_posted_to_open_period", "expense", String(result.lastInsertRowid),
				`Receipt dated ${date} — ${naturalPeriod} ${lockUnreadable
					// Never say "finalized" about a month we could not look up. The
					// redirect is right either way; the REASON is a different fact.
					? "could not be confirmed open (period_locks unreadable)"
					: "is finalized"}, booked to ${postedPeriod} ($${parsedAmount}, ${driver})`);
		}
		if (overrodeDuplicateOf) {
			logAudit(req, "expense_duplicate_override", "expense", String(result.lastInsertRowid),
				`Logged despite matching expense #${overrodeDuplicateOf} (${safeVendor || vendorNormalized}, ${date}, $${parsedAmount}, ${driver})`);
		}
		notifyChange("expenses");
		res.json({
			success: true,
			id: result.lastInsertRowid,
			// periodClosed stays reserved for a month we actually READ as closed —
			// the client turns it into "March is closed, so it was booked to August",
			// which must not be said about a month whose lock state is unknown. The
			// unreadable case reports the redirect without the claim; the client's
			// `periodClosed && postedPeriod` test then falls through to its plain
			// confirmation rather than printing something false.
			...(postedPeriod ? { postedPeriod, naturalPeriod, periodClosed: !lockUnreadable, periodLockUnreadable: lockUnreadable } : {}),
		});
	} catch (error) {
		console.error("Error logging expense:", error.message);
		res.status(500).json({ error: "Failed to log expense" });
	}
});

// ── Bulk receipt upload drafts ─────────────────────────────────────────────
// Cross-device resume for the Bulk Receipt Upload tool: the in-progress batch
// lives server-side (one row per user) so a stack started on the phone can be
// finished on the computer. All three routes are requireAuth and hard-scoped to
// req.session.user.id — a user only ever reads/writes/clears their own draft.
const bulkDraftLimiter = rateLimit({
	windowMs: 60 * 1000,
	max: 120, // debounced client auto-save (~1.5s) + shared office-IP headroom
	message: { error: "Too many draft saves. Please slow down." },
	standardHeaders: true,
	legacyHeaders: false,
});
const MAX_BULK_DRAFT_ROWS = 25; // mirrors MAX_BATCH client-side
const MAX_BULK_DRAFT_BYTES = 40 * 1024 * 1024; // headroom under the 50 MB body cap

// GET /api/expenses/bulk-draft — the caller's saved batch, or null.
app.get("/api/expenses/bulk-draft", requireAuth, (req, res) => {
	try {
		const row = db
			.prepare("SELECT draft_json, updated_at FROM receipt_upload_drafts WHERE user_id = ?")
			.get(req.session.user.id);
		if (!row || !row.draft_json) return res.json({ draft: null });
		let rows = [];
		try { rows = JSON.parse(row.draft_json).rows || []; } catch { rows = []; }
		if (!Array.isArray(rows) || rows.length === 0) return res.json({ draft: null });
		res.json({ draft: { rows, updatedAt: row.updated_at } });
	} catch (error) {
		console.error("Error reading bulk draft:", error.message);
		res.status(500).json({ error: "Failed to read draft" });
	}
});

// PUT /api/expenses/bulk-draft — upsert the caller's batch. Best-effort
// convenience; the client auto-saves it debounced as the user works. An empty
// rows[] clears the draft (mirrors DELETE) so the last save after everything is
// logged leaves nothing stale behind.
app.put("/api/expenses/bulk-draft", requireAuth, bulkDraftLimiter, (req, res) => {
	try {
		const rows = Array.isArray(req.body?.rows) ? req.body.rows : null;
		if (!rows) return res.status(400).json({ error: "rows must be an array" });
		if (rows.length === 0) {
			db.prepare("DELETE FROM receipt_upload_drafts WHERE user_id = ?").run(req.session.user.id);
			return res.json({ success: true, cleared: true });
		}
		if (rows.length > MAX_BULK_DRAFT_ROWS) {
			return res.status(400).json({ error: `Too many rows (max ${MAX_BULK_DRAFT_ROWS})` });
		}
		const draftJson = JSON.stringify({ rows });
		if (Buffer.byteLength(draftJson, "utf8") > MAX_BULK_DRAFT_BYTES) {
			return res.status(413).json({ error: "Draft too large to save" });
		}
		const now = new Date().toISOString();
		db.prepare(`
			INSERT INTO receipt_upload_drafts (user_id, draft_json, updated_at)
			VALUES (?, ?, ?)
			ON CONFLICT(user_id) DO UPDATE SET draft_json = excluded.draft_json, updated_at = excluded.updated_at
		`).run(req.session.user.id, draftJson, now);
		res.json({ success: true, updatedAt: now });
	} catch (error) {
		console.error("Error saving bulk draft:", error.message);
		res.status(500).json({ error: "Failed to save draft" });
	}
});

// DELETE /api/expenses/bulk-draft — clear the caller's batch (all rows saved,
// or Clear All).
app.delete("/api/expenses/bulk-draft", requireAuth, (req, res) => {
	try {
		db.prepare("DELETE FROM receipt_upload_drafts WHERE user_id = ?").run(req.session.user.id);
		res.json({ success: true });
	} catch (error) {
		console.error("Error clearing bulk draft:", error.message);
		res.status(500).json({ error: "Failed to clear draft" });
	}
});

// POST /api/expenses/ocr — parse a receipt image into structured fields via
// Gemini 2.5 Flash vision. Called by the driver expense form after camera
// capture so amount/date/gallons/etc. prefill. Driver still confirms before
// submitting the actual expense (POST /api/expenses re-validates everything).
//
// SECURITY:
// - Role-gated: Drivers / Super Admin / Dispatcher. Investors blocked (same
//   as POST /api/expenses).
// - Rate-limited to cap API spend + prevent abuse.
// - Photo payload capped at ~6 MB (canvas-compressed 1600px receipts are ~500KB).
// - Gemini response uses responseSchema so the output is always valid JSON,
//   but we still re-validate every field shape + range. Model output is
//   treated as untrusted data and never passes through to SQL. The existing
//   amount < 1,000,000 guard on POST /api/expenses is the second line of
//   defense against prompt injection or hallucinated totals.
// Role-aware cap. Admin/Dispatcher get 100/15min because the bulk-receipt
// upload fires one OCR call per receipt (a ~25 batch from a shared office IP
// needs headroom); Drivers stay at the original tight 20 (a phone should never
// need more, and it keeps the abuse surface small). requireAuth runs before
// this middleware, so req.session.user is populated. Still a firm per-IP cap on
// Gemini vision spend; endpoint is auth+role gated (no Investors).
const expenseOcrLimiter = rateLimit({
	windowMs: 15 * 60 * 1000,
	max: (req) => {
		const role = req.session?.user?.role;
		return role === "Super Admin" || role === "Dispatcher" ? 100 : 20;
	},
	// Key on the SESSION USER, not the IP. With trust proxy on, a whole office
	// behind one WAN IP was sharing a single bucket — two people running bulk
	// batches locked each other (and every driver on that IP) out, which reads as
	// "it stopped scanning". Falls back to IP for the unauthenticated edge.
	keyGenerator: (req) => {
		const id = req.session?.user?.id;
		return id ? `u:${id}` : `ip:${ipKeyGenerator(req.ip)}`;
	},
	message: { error: "Too many OCR requests. Try again later." },
	standardHeaders: true,
});

app.post("/api/expenses/ocr", requireAuth, expenseOcrLimiter, async (req, res) => {
	try {
		const role = req.session.user.role;
		if (role === "Investor") return res.status(403).json({ error: "Investors cannot submit expenses" });
		if (role !== "Driver" && role !== "Super Admin" && role !== "Dispatcher") {
			return res.status(403).json({ error: "Forbidden" });
		}
		const { photoData } = req.body || {};
		if (!photoData || typeof photoData !== "string") return res.status(400).json({ error: "photoData required" });
		if (photoData.length > 8_500_000) return res.status(413).json({ error: "Receipt file too large — max about 6 MB" });
		// Images OR a PDF: fuel/toll receipts routinely arrive as emailed PDFs and
		// Gemini reads them natively (same mime the rate-con path already sends).
		// Keep this in lockstep with DATA_URI_RE in lib/receipt-ocr.js.
		if (!/^data:(image\/(?:jpeg|jpg|png|webp)|application\/pdf);base64,(.+)$/i.test(photoData)) {
			return res.status(400).json({ error: "photoData must be a base64 image or PDF data URI" });
		}
		// The data-URI mime is client-controlled, and the bulk uploader labels a
		// file a PDF from its extension alone. Re-verify the payload really is one
		// (same %PDF- magic check the rate-con intake uses) so a mislabelled zip or
		// photo can't burn three retried Gemini calls before failing.
		if (/^data:application\/pdf;base64,/i.test(photoData) && !/^data:application\/pdf;base64,JVBERi/i.test(photoData)) {
			return res.status(400).json({ error: "That file isn't a readable PDF." });
		}
		// Same treatment for the IMAGE half, which had only the label check above:
		// `data:image/png;base64,<an SVG>` passed straight through to Gemini. This
		// endpoint is body-only (it writes nothing, so it is not the stored-XSS
		// path), but the reasoning in the PDF comment applies verbatim — a
		// mislabelled payload should fail here for free rather than after three
		// retried vision calls. Sniffed format, not the label, and narrowed to the
		// formats runReceiptOcr actually forwards.
		if (!/^data:application\/pdf;base64,/i.test(photoData)) {
			// Decode only the header, not the whole 6 MB payload. 256 chars rather
			// than the 24 that would suffice for contiguous base64: a LINE-WRAPPED
			// payload (RFC 2045 style, 76 chars + CRLF) carries whitespace that
			// Buffer.from discards, so a tight window can decode to under
			// sniffImageFormat's 12-byte floor and report a real JPEG as "not a
			// readable image". Today's callers don't wrap, but the driver-mobile
			// client is a separate codebase — cheap insurance against a confusing
			// false rejection. 256 chars still decodes to ~192 bytes, not megabytes.
			const comma = photoData.indexOf(",");
			const imgFmt = sniffImageFormat(Buffer.from(photoData.slice(comma + 1, comma + 257), "base64"));
			if (!imgFmt || !RECEIPT_IMAGE_EXTS.has(imgFmt)) {
				return res.status(400).json({ error: "That file isn't a readable image." });
			}
		}
		// Prompt, schema, and the Gemini call + retry/15s-timeout live in
		// lib/receipt-ocr.js — the single point of contact for the vision API.
		// It re-parses the data URI and signals OCR_NO_KEY when GEMINI_API_KEY
		// is unset (→ 503). The normalized object adds city/state to the prior
		// {amount,date,vendor,gallons,odometer,suggestedType,confidence} shape.
		try {
			const out = await runReceiptOcr(photoData);
			return res.json(out);
		} catch (err) {
			if (err && err.code === "OCR_NO_KEY") return res.status(503).json({ error: "ocr_unavailable" });
			// A rejected/limited key is a SERVICE problem, not a bad receipt. Saying
			// "couldn't read this receipt" sends the user off re-photographing
			// perfectly good paper; 503 makes the UI say scanning is unavailable and
			// to enter it manually, which is the truth and the useful instruction.
			//
			// Was a raw 401/403/429 test, which MISSED the most likely case in
			// production: a revoked or out-of-credit key answers HTTP 400
			// INVALID_ARGUMENT with reason API_KEY_INVALID, so it fell through to the
			// 502 below and told the driver their receipt was unreadable. The verdict
			// from lib/gemini-errors.js reads Google's body, which is the only place
			// that distinction exists. A request WE malformed is still a loud 502.
			if (err && err.kind === "unavailable") {
				console.error(`Expense OCR unavailable (Gemini ${err.status}${err.reason ? " " + err.reason : ""}):`, err.message);
				return res.status(503).json({ error: "ocr_unavailable" });
			}
			console.error("Expense OCR failed after retries:", err && err.message);
			return res.status(502).json({ error: "ocr_failed" });
		}
	} catch (err) {
		console.error("Expense OCR error:", err.message);
		res.status(500).json({ error: "ocr_failed" });
	}
});

// POST /api/expenses/:id/extract-details — run Gemini vision on an ALREADY
// stored receipt to (re)build its dynamic label/value details list, so the
// expense modal can surface "all important info" for receipts logged before
// details capture existed. Images only (PDFs → 415). Reuses runReceiptOcr;
// expenseOcrLimiter caps Gemini spend. Super Admin / Dispatcher only (the admin
// Expenses modal is the sole caller).
app.post("/api/expenses/:id/extract-details", requireRole("Super Admin", "Dispatcher"), expenseOcrLimiter, async (req, res) => {
	try {
		if (!GEMINI_API_KEY) return res.status(503).json({ error: "ocr_unavailable" });
		const id = parseInt(req.params.id, 10);
		if (!Number.isInteger(id) || id <= 0) return res.status(400).json({ error: "Invalid expense id" });
		const exp = db.prepare("SELECT id, photo_data FROM expenses WHERE id = ?").get(id);
		if (!exp) return res.status(404).json({ error: "Expense not found" });
		const photo = exp.photo_data || "";
		if (!photo) return res.status(404).json({ error: "No receipt on file" });

		// Build an image data URI from either an inline data URI or a stored file.
		let dataUri = "";
		if (photo.startsWith("data:image/")) {
			dataUri = photo;
		} else if (/^data:application\/pdf/i.test(photo) || /\.pdf$/i.test(photo)) {
			return res.status(415).json({ error: "PDF receipts can't be auto-extracted" });
		} else if (photo.startsWith("/uploads/expense-receipts/")) {
			const fname = path.basename(photo); // strips any traversal segments
			const abs = path.join(RECEIPTS_DIR, fname);
			if (!abs.startsWith(RECEIPTS_DIR + path.sep)) return res.status(400).json({ error: "Invalid receipt path" });
			let st;
			try { st = fs.statSync(abs); } catch { return res.status(404).json({ error: "Receipt file missing" }); }
			// Cap the disk read before base64 — receipts are canvas-compressed images;
			// anything over 10 MB isn't a real receipt and would spike memory + Gemini cost.
			if (st.size > 10 * 1024 * 1024) return res.status(413).json({ error: "Receipt too large to scan" });
			let buf;
			try { buf = fs.readFileSync(abs); } catch { return res.status(404).json({ error: "Receipt file missing" }); }
			const ext = fname.split(".").pop().toLowerCase();
			const mime = ext === "png" ? "image/png" : ext === "webp" ? "image/webp" : "image/jpeg";
			dataUri = `data:${mime};base64,${buf.toString("base64")}`;
		} else {
			return res.status(415).json({ error: "Receipt format not supported for extraction" });
		}

		let ocr;
		try {
			ocr = await runReceiptOcr(dataUri);
		} catch (err) {
			if (err && err.code === "OCR_NO_KEY") return res.status(503).json({ error: "ocr_unavailable" });
			// Same branch and the same reasoning as POST /api/expenses/ocr above: a
			// rejected key or an exhausted quota is the state this route already
			// answers 503 for when GEMINI_API_KEY is unset, so it degrades the same
			// way rather than telling the admin their stored receipt is unreadable.
			// `kind` is set by lib/gemini-errors.js; a defect stays a loud 502.
			if (err && err.kind === "unavailable") {
				console.error(`extract-details unavailable (Gemini ${err.status}${err.reason ? " " + err.reason : ""}):`, err.message);
				return res.status(503).json({ error: "ocr_unavailable" });
			}
			console.error("extract-details OCR failed:", err && err.message);
			return res.status(502).json({ error: "ocr_failed" });
		}
		const json = sanitizeReceiptDetails(ocr.details || []);
		db.prepare("UPDATE expenses SET receipt_details = ? WHERE id = ?").run(json, id);
		return res.json({ receipt_details: parseReceiptDetails(json) });
	} catch (err) {
		console.error("extract-details error:", err.message);
		res.status(500).json({ error: "extract_failed" });
	}
});

// GET /api/expenses/:id/receipt-thumbnail — small cached JPEG thumbnail of a
// stored receipt image so the expenses LIST renders ~5 KB thumbs instead of the
// full ~283 KB originals (×150 rows ≈ 43 MB, the page's real load cost).
// Generated on first request via jimp, cached to uploads/expense-receipts/thumbs/,
// and revalidated by mtime. Super Admin / Dispatcher (same scope as the list).
// Degrades to the original image on any resize error so a row never shows blank.
app.get("/api/expenses/:id/receipt-thumbnail", requireRole("Super Admin", "Dispatcher"), async (req, res) => {
	try {
		const id = parseInt(req.params.id, 10);
		if (!Number.isInteger(id) || id <= 0) return res.status(400).end();
		const exp = db.prepare("SELECT photo_data FROM expenses WHERE id = ?").get(id);
		const photo = exp && exp.photo_data ? exp.photo_data : "";
		// No thumbnails for missing receipts or PDFs (the list shows a PDF chip instead).
		if (!photo || /\.pdf$/i.test(photo) || /^data:application\/pdf/i.test(photo)) return res.status(404).end();

		// Resolve the source to an on-disk path (traversal-guarded) or a data-URI buffer.
		let srcPath = "", srcBuf = null;
		if (photo.startsWith("/uploads/expense-receipts/")) {
			const abs = path.join(RECEIPTS_DIR, path.basename(photo));
			if (!abs.startsWith(RECEIPTS_DIR + path.sep)) return res.status(400).end();
			srcPath = abs;
		} else if (photo.startsWith("data:image/")) {
			const comma = photo.indexOf(",");
			if (comma < 0) return res.status(404).end();
			srcBuf = Buffer.from(photo.slice(comma + 1), "base64");
		} else {
			return res.status(404).end();
		}

		const THUMBS_DIR = path.join(RECEIPTS_DIR, "thumbs");
		const thumbPath = path.join(THUMBS_DIR, `${id}.jpg`);
		// `private`, not `public`: this is a role-gated receipt behind requireRole,
		// so a shared/intermediary cache must never hold it. The browser still
		// caches it for a day, which is the whole point of the endpoint.
		res.set("Cache-Control", "private, max-age=86400");
		// The image/jpeg below is asserted BEFORE the bytes are produced, and the
		// degrade path at the bottom can ship the ORIGINAL file under it. nosniff
		// keeps that mismatch inert instead of letting a browser re-interpret it.
		res.setHeader("X-Content-Type-Options", "nosniff");
		res.type("image/jpeg");

		// Serve a cached thumb if it's at least as new as its source.
		try {
			if (fs.existsSync(thumbPath)) {
				const fresh = srcPath ? fs.statSync(thumbPath).mtimeMs >= fs.statSync(srcPath).mtimeMs : true;
				if (fresh) return res.send(fs.readFileSync(thumbPath));
			}
		} catch { /* stale/unreadable cache → regenerate below */ }

		try {
			const { Jimp } = require("jimp");
			const img = await Jimp.read(srcPath || srcBuf);
			img.resize({ w: 200 }); // width-constrained, aspect preserved
			const buf = await img.getBuffer("image/jpeg", { quality: 70 });
			try { fs.mkdirSync(THUMBS_DIR, { recursive: true }); fs.writeFileSync(thumbPath, buf); } catch { /* cache write is best-effort */ }
			return res.send(buf);
		} catch (genErr) {
			// Degrade to the original image so the row still renders — but only if
			// the bytes really are one, and under their OWN type rather than the
			// image/jpeg asserted above. Receipts written before the magic-byte
			// check existed are still on disk and nothing ever removes them, so
			// "jimp couldn't read it" and "it isn't an image" overlap exactly here.
			console.warn("thumbnail gen failed, serving original:", genErr && genErr.message);
			try {
				const raw = srcPath ? fs.readFileSync(srcPath) : srcBuf;
				const fmt = raw ? sniffImageFormat(raw) : null;
				if (raw && fmt) {
					res.type(fmt === "jpg" ? "image/jpeg" : `image/${fmt}`);
					return res.send(raw);
				}
			} catch { /* ignore */ }
			return res.status(404).end();
		}
	} catch (err) {
		console.error("receipt-thumbnail error:", err.message);
		return res.status(500).end();
	}
});

// POST /api/documents/scan — crop / deskew / lighting-correct a document photo
// via ScanKit.io, returning the processed image (or a searchable OCR PDF) as a
// base64 data URI so the client can preview it and then upload via the existing
// POST /api/documents/upload. Replaces the old client-side jscanify/OpenCV
// scanner in DocumentUpload.vue. Mirrors the /api/expenses/ocr contract.
//
// SECURITY:
// - Role-gated identically to /api/expenses/ocr (Investors blocked).
// - SCANKIT_API_KEY lives server-side only; never sent to or echoed at the
//   client. An auth/key failure is masked as a generic 502 so a driver device
//   never learns the company key is bad.
// - Decoded image bytes re-validated via isValidImageMagic (the data-URI mime
//   is client-controlled). Rate-limited to cap ScanKit credit spend.
const scanKitLimiter = rateLimit({
	windowMs: 15 * 60 * 1000,
	// Bulk receipt upload now enhances each image before OCR, so one 25-receipt
	// batch alone would have blown the old cap of 30. Raised, and keyed per user
	// (see expenseOcrLimiter) so one person's batch can't lock out the office.
	max: 120,
	keyGenerator: (req) => {
		const id = req.session?.user?.id;
		return id ? `u:${id}` : `ip:${ipKeyGenerator(req.ip)}`;
	},
	message: { error: "Too many scan requests. Try again later." },
	standardHeaders: true,
});
app.post("/api/documents/scan", requireAuth, scanKitLimiter, async (req, res) => {
	try {
		const role = req.session.user.role;
		if (role === "Investor") return res.status(403).json({ error: "Investors cannot scan documents" });
		if (role !== "Driver" && role !== "Super Admin" && role !== "Dispatcher") {
			return res.status(403).json({ error: "Forbidden" });
		}
		const { photoData } = req.body || {};
		if (!photoData || typeof photoData !== "string") return res.status(400).json({ error: "photoData required" });
		if (photoData.length > 8_500_000) return res.status(413).json({ error: "Image too large" });
		const m = photoData.match(/^data:image\/(jpeg|jpg|png|webp);base64,(.+)$/i);
		if (!m) return res.status(400).json({ error: "photoData must be a base64 image data URI" });
		if (!SCANKIT_ENABLED || !SCANKIT_API_KEY) return res.status(503).json({ error: "scan_unavailable" });

		const imageBuffer = Buffer.from(m[2], "base64");
		// Re-verify the decoded bytes — the data-URI mime is client-controlled.
		if (!isValidImageMagic(imageBuffer)) return res.status(400).json({ error: "Invalid image data" });

		// Whitelist / clamp the options the client may influence.
		const filter = ["original", "flat", "white"].includes(req.body.filter) ? req.body.filter : "white";
		const returnPdf = req.body.returnPdf === true;
		const outputWidth = Math.min(2048, Math.max(512, Number(req.body.outputWidth) || 1536));

		try {
			const result = await scankit.cropDocument(
				{ apiKey: SCANKIT_API_KEY, baseUrl: SCANKIT_BASE_URL },
				imageBuffer,
				{ outputWidth, filter, returnPdf, ocrLang: "eng" },
			);
			const dataUri = `data:${result.contentType};base64,${result.buffer.toString("base64")}`;
			scanKitHealth.lastScan = new Date().toISOString();
			scanKitHealth.scans24h.ok++;
			scanKitHealth.noCreditsSince = null;
			return res.json({
				data: dataUri,
				contentType: result.contentType,
				ext: result.ext,
				isPdf: result.ext === ".pdf",
			});
		} catch (err) {
			// Map adapter error codes → client status. Never leak a key problem.
			// Record health BEFORE the switch so every failure path is counted.
			// status = the HTTP status this maps to for the known codes; for the
			// masked cases (NO_KEY/AUTH/ERROR) fall back to the real upstream
			// err.status (more useful to an admin than the client-facing 502),
			// or null when the failure happened before any HTTP response.
			const mappedStatus =
				err.code === "SCANKIT_NO_CREDITS" ? 402 :
				err.code === "SCANKIT_BAD_INPUT" ? 400 :
				err.code === "SCANKIT_RATE_LIMIT" ? 429 :
				(err.status || null);
			scanKitHealth.lastError = { at: new Date().toISOString(), status: mappedStatus, code: err.code || null, message: err.message };
			scanKitHealth.errorsLast24h++;
			scanKitHealth.scans24h.failed++;
			switch (err.code) {
				case "SCANKIT_NO_CREDITS":
					if (!scanKitHealth.noCreditsSince) scanKitHealth.noCreditsSince = new Date().toISOString();
					return res.status(402).json({ error: "scan_no_credits" });
				case "SCANKIT_BAD_INPUT":
					return res.status(400).json({ error: "scan_bad_input" });
				case "SCANKIT_RATE_LIMIT":
					return res.status(429).json({ error: "scan_rate_limited" });
				case "SCANKIT_NO_KEY":
				case "SCANKIT_AUTH":
				default:
					console.error("ScanKit scan failed:", err.code || "", err.message);
					return res.status(502).json({ error: "scan_failed" });
			}
		}
	} catch (err) {
		console.error("Document scan error:", err.message);
		res.status(500).json({ error: "scan_failed" });
	}
});

// Helper: convert image buffer(s) to PDF buffer (supports multi-page)
function imageToPdf(imageBuffers) {
	const buffers = Array.isArray(imageBuffers) ? imageBuffers : [imageBuffers];
	return new Promise((resolve, reject) => {
		const doc = new PDFDocument({ autoFirstPage: false });
		const chunks = [];
		doc.on("data", (chunk) => chunks.push(chunk));
		doc.on("end", () => resolve(Buffer.concat(chunks)));
		doc.on("error", reject);
		for (const buf of buffers) {
			const img = doc.openImage(buf);
			doc.addPage({ size: [img.width, img.height] });
			doc.image(img, 0, 0);
		}
		doc.end();
	});
}

// Helper: OCR text extraction for receipts
async function extractReceiptText(imageBuffer) {
	try {
		const Tesseract = require("tesseract.js");
		const {
			data: { text },
		} = await Tesseract.recognize(imageBuffer, "eng");
		return text.trim();
	} catch (err) {
		console.error("OCR failed:", err.message);
		return "";
	}
}

// ============================================================
// Rate-con drag-and-drop → load creation
// ============================================================
// Server-side replica of the n8n "Dispatch v2 (Fixed)" ingestion path (see
// Dispatch-v2-fixed.json — Validate Load ID · Critical Fields Complete? ·
// Lookup Existing Row · Row Already Has Payment? · JOB DETAILS ENTRY).
// ⚠️ Node names drift; the live workflow over the API is the source of truth.
// This list previously named "Check Existing Load", "RATE UPDATE", "Google
// Maps Distance", "Calculate Rate Per Mile" and "Google Sheets2" — no nodes by
// those names exist. Today a load can enter LogisX ONLY via a rate-con email
// landing in info@logisx.com; when a broker sends the details over WhatsApp
// instead there is zero signal and the dispatcher retypes the whole load.
// Dropping the PDF here produces the same rows the email pipeline writes.
//
// Deliberately two steps so the dispatcher reviews Gemini's output before
// anything is written — the same interaction as the receipt-OCR prefill:
//   POST /api/loads/ratecon/extract  — read-only, writes nothing anywhere
//   POST /api/loads/from-ratecon     — the reviewed fields become sheet rows
//
// The field mapping, the rate-per-mile math (ported from the n8n code node)
// and the upsert row-building are pure and live in lib/ratecon-load.js;
// everything network/Sheets/Drive/SQLite stays here.
const rateconLoad = require("./lib/ratecon-load");

// Caps Gemini spend on PDF extraction the way expenseOcrLimiter caps vision
// OCR. 60 / 15 min is roomy for a human dropping files one at a time (and for
// a shared office IP) while still being a firm per-IP ceiling. The endpoints
// are auth + role gated on top, so this is purely an abuse/cost backstop.
//
// Applied to BOTH routes on one shared budget (a real drop costs 1 extract +
// 1 create = 2 tokens, so ~30 loads per IP per 15 min). The create route is
// the more expensive of the two despite spending no Gemini credits: it fans
// out to 3 full-tab Sheets reads + up to 3 Sheets writes + 1 Distance Matrix
// + 2 geocodes + 1 Drive upload per call. Sheets is the primary database on a
// 300 req/min quota, so an unthrottled loop there would take the dashboard,
// driver app and invoices down with it.
const rateConLimiter = rateLimit({
	windowMs: 15 * 60 * 1000,
	max: 60,
	message: { error: "Too many rate-con uploads. Try again later." },
	standardHeaders: true,
});

// Load IDs with a create in flight. The dedupe read and the sheet append are
// seconds apart (a Distance Matrix call and two geocodes sit between them), so
// two concurrent submits of the same PDF — an impatient double-click, or a
// client retry on a slow response — would both pass the 409 check and both
// append. Sheets has no unique constraint to lean on, so hold the ID here for
// the duration of the write.
const rateConCreateInFlight = new Set();

// POST /api/loads/ratecon/extract — PDF → the 23-field rate-con object.
// Read-only: no sheet, no DB, no Drive write happens here, so a dispatcher can
// drop the wrong file and simply close the modal. Reuses runRateConGemini()
// (the same extractor the n8n webhook and the invoice fallback call) so all
// three paths stay on one prompt/schema.
app.post("/api/loads/ratecon/extract", requireRole("Super Admin", "Dispatcher"), rateConLimiter, async (req, res) => {
	try {
		const { pdfBase64 } = req.body || {};
		if (!pdfBase64 || typeof pdfBase64 !== "string") {
			return res.status(400).json({ error: "pdfBase64 required" });
		}
		const base64 = pdfBase64.replace(/^data:application\/pdf;base64,/, "").trim();
		// PDF magic bytes "%PDF-" → base64 "JVBERi". The client-side accept=
		// filter and the mime type are both trivially bypassed; the decoded
		// bytes are the only trustworthy signal.
		if (!/^JVBERi/.test(base64)) {
			return res.status(400).json({ error: "Not a valid PDF (missing %PDF- header)" });
		}
		// 15 MB decoded. base64 inflates ~4/3, so measure the decoded size.
		if (Math.floor((base64.length * 3) / 4) > 15 * 1024 * 1024) {
			return res.status(400).json({ error: "PDF too large (15 MB max)" });
		}
		if (!GEMINI_API_KEY) return res.status(503).json({ error: "ratecon_extract_unavailable" });

		try {
			// Normalize Gemini's raw output (money → "$X,XXX.XX", multi-line addresses
			// collapsed, phones tidied, "None"/"" → null) so warnings run on clean data
			// and the review modal shows consistent values across broker layouts.
			let fields = rateconNormalize.normalizeRateConFields(await runRateConGemini(base64));
			// Second-pass nudge: if a critical field (Load #, Rate, pickup/drop address)
			// is still missing, re-run once and fill the gaps — some broker formats need
			// a second look. One extra Gemini call, only when something important is blank.
			if (rateconNormalize.missingCriticalFields(fields).length) {
				try {
					const retry = rateconNormalize.normalizeRateConFields(await runRateConGemini(base64));
					fields = rateconNormalize.mergeExtractions(fields, retry);
				} catch { /* keep the first-pass fields if the retry fails */ }
			}
			return res.json({ fields, warnings: rateconLoad.extractionWarnings(fields) });
		} catch (err) {
			// A rejected key or an exhausted quota is the same state as having no key
			// at all, which this route already answers 503 for six lines above — so
			// say 503 and reuse that error code, and the dispatcher is told the
			// scanner is unavailable (fill the load in by hand) instead of being sent
			// to re-scan a PDF that was never the problem. This is the path that lost
			// a $1,300 load: the rate-con arrived while credits were depleted and the
			// 502 read as "bad PDF". `kind` is set by lib/gemini-errors.js; a request
			// WE malformed stays a loud 502 below.
			if (err && err.kind === "unavailable") {
				console.error(`Rate-con extract unavailable (Gemini ${err.status}${err.reason ? " " + err.reason : ""}):`, err.message);
				return res.status(503).json({ error: "ratecon_extract_unavailable" });
			}
			console.error("Rate-con extract failed after retries:", err && err.message);
			return res.status(502).json({ error: "ratecon_extract_failed" });
		}
	} catch (err) {
		console.error("Rate-con extract error:", err.message);
		res.status(500).json({ error: "ratecon_extract_failed" });
	}
});

// POST /api/loads/from-ratecon — the reviewed fields become a live load.
// `fields` is what the dispatcher confirmed in the review modal (Gemini output
// is treated as a draft, never as truth). Order of operations mirrors the n8n
// workflow; everything after the Job Tracking append is best-effort and
// degrades to a warning, because the load row is already committed and a
// dispatcher "fixing" a hard error by re-dropping the PDF would create a twin.
app.post("/api/loads/from-ratecon", requireRole("Super Admin", "Dispatcher"), rateConLimiter, async (req, res) => {
	try {
		const { fields, pdfBase64, fileName } = req.body || {};
		if (!fields || typeof fields !== "object" || Array.isArray(fields)) {
			return res.status(400).json({ error: "fields required" });
		}

		// ---- 1) Validate Load ID (n8n "Validate Load ID" filter) ----
		const loadId = String(fields["Load Number"] == null ? "" : fields["Load Number"]).trim();
		if (!loadId) {
			return res.status(400).json({ error: "Load Number is required — fill it in before creating the load." });
		}
		// Same whitelist the public tracker uses. Keeps the Load ID safe to
		// interpolate into a Drive file name and an A1 range.
		if (!/^[A-Za-z0-9\-_.#]{1,40}$/.test(loadId)) {
			return res.status(400).json({ error: "Load Number contains unsupported characters." });
		}
		// Re-validate every field's shape. These arrive hand-edited from the
		// review modal, so runRateConGemini's own 500-char-per-field cap no
		// longer applies and nothing else stands between a stray paste (or a
		// crafted client) and a sheet cell.
		for (const fieldName of Object.keys(fields)) {
			const v = fields[fieldName];
			if (v == null) continue;
			if (typeof v !== "string" && typeof v !== "number") {
				return res.status(400).json({ error: `Field "${fieldName}" must be text.` });
			}
			if (String(v).length > 1000) {
				return res.status(400).json({ error: `Field "${fieldName}" is too long (1000 characters max).` });
			}
		}

		// Claim this Load ID for the duration of the write so a double-submit
		// can't slip a twin past the dedupe check below. Released on response
		// close, which covers the error paths and a client abort too.
		const loadKey = rateconLoad.normalizeLoadId(loadId);
		if (rateConCreateInFlight.has(loadKey)) {
			return res.status(409).json({
				error: `Load ${loadId} is already being created — wait for that request to finish.`,
				code: "DUPLICATE_LOAD",
				existingRowIndex: null,
			});
		}
		rateConCreateInFlight.add(loadKey);
		res.on("close", () => rateConCreateInFlight.delete(loadKey));

		const warnings = [];
		const sheets = await getSheets();

		// ---- 2) Dedupe against Job Tracking (n8n "Check Existing Load") ----
		const jtResp = await sheets.spreadsheets.values.get({
			spreadsheetId: SPREADSHEET_ID,
			range: "Job Tracking",
		});
		const { headers, data } = parseSheet(jtResp.data);
		if (!headers.length) {
			return res.status(502).json({ error: "Could not read the Job Tracking sheet. Try again." });
		}
		const loadIdCol = findCol(headers, /load.?id|job.?id/i);
		if (!loadIdCol) {
			return res.status(502).json({ error: "Job Tracking has no Load ID column." });
		}
		const existing = deduplicateLoads(data, headers).find(
			(r) => rateconLoad.normalizeLoadId(r[loadIdCol]) === loadKey,
		);
		if (existing) {
			// Soft-deleted loads keep their sheet row, so "already exists" would
			// otherwise be baffling — the dispatcher can't see the load anywhere.
			const softDeleted = getDeletedLoadIds().has(loadKey);
			return res.status(409).json({
				error: softDeleted
					? `Load ${loadId} already exists (row ${existing._rowIndex}) but was deleted. Restore it instead of re-creating it.`
					: `Load ${loadId} already exists (row ${existing._rowIndex}).`,
				code: "DUPLICATE_LOAD",
				existingRowIndex: existing._rowIndex,
			});
		}

		// ---- 3) Distance Matrix → rate per mile (ported from the n8n nodes
		// "Get Distance Matrix" → "Calculate RPM + Details", both since deleted
		// as unreachable, so this is the only Distance Matrix caller left).
		// Never fatal: a missing key, a quota error, a timeout or ZERO_RESULTS
		// all arrive at calculateRatePerMile() as a non-OK element and take the
		// node's own zeros / "N/A" branch. A Maps outage must not stop a
		// dispatcher from booking a load. ----
		const pickupAddress = String(fields["Pickup Address"] || "").trim();
		const dropoffAddress = String(fields["Drop-off Address"] || "").trim();
		let distanceMatrix = null;
		if (GOOGLE_MAPS_API_KEY && pickupAddress && dropoffAddress) {
			try {
				const controller = new AbortController();
				const timer = setTimeout(() => controller.abort(), 8000);
				const dmUrl =
					"https://maps.googleapis.com/maps/api/distancematrix/json" +
					`?origins=${encodeURIComponent(pickupAddress)}` +
					`&destinations=${encodeURIComponent(dropoffAddress)}` +
					`&units=imperial&key=${encodeURIComponent(GOOGLE_MAPS_API_KEY)}`;
				const dmResp = await fetch(dmUrl, { signal: controller.signal });
				clearTimeout(timer);
				distanceMatrix = await dmResp.json();
			} catch (e) {
				console.error("Rate-con load: Distance Matrix failed:", e.message);
			}
		}
		const rpm = rateconLoad.calculateRatePerMile(distanceMatrix, fields);
		if (rpm.distance_miles === 0) {
			warnings.push("Distance could not be calculated — Job Details shows 0 miles. Check the pickup and drop-off addresses.");
		}

		// Geocode both ends (served from geocode_cache when already seen) so the
		// dashboard map + ETA pipeline have coordinates the moment the load
		// lands, exactly like the map-picker path in NewJobView.
		let pickupCoords = null;
		let dropoffCoords = null;
		try { pickupCoords = pickupAddress ? await geocodeAddress(pickupAddress) : null; } catch { /* non-critical */ }
		try { dropoffCoords = dropoffAddress ? await geocodeAddress(dropoffAddress) : null; } catch { /* non-critical */ }

		// ---- 4) Append the Job Tracking row (n8n "JOB DETAILS ENTRY") ----
		// Houston day, not the UTC day — this lands in "Assigned Date", which
		// decides the load's revenue month. See houstonDay().
		const today = houstonDay();
		const values = rateconLoad.buildJobTrackingRow(headers, fields, {
			today,
			ownerId: 0,
			pickupLat: pickupCoords ? pickupCoords.lat : null,
			pickupLng: pickupCoords ? pickupCoords.lng : null,
			dropoffLat: dropoffCoords ? dropoffCoords.lat : null,
			dropoffLng: dropoffCoords ? dropoffCoords.lng : null,
		});
		const ownerErr = validateOwnerIdCell("Job Tracking", headers, values);
		if (ownerErr) return res.status(400).json({ error: ownerErr.error });

		const appendResp = await sheets.spreadsheets.values.append({
			spreadsheetId: SPREADSHEET_ID,
			range: "Job Tracking",
			valueInputOption: "USER_ENTERED",
			requestBody: { values: [values] },
		});
		// "Job Tracking!A742:Z742" → 742
		const updatedRange = (appendResp.data.updates && appendResp.data.updates.updatedRange) || "";
		const rowMatch = updatedRange.match(/![A-Z]+(\d+)/);
		const rowIndex = rowMatch ? parseInt(rowMatch[1], 10) : null;
		jtCacheInvalidate();

		// ---- 5/6) Payments Table + Job Details upserts ----
		// Sheets v4 has no native appendOrUpdate (the n8n node fakes it the same
		// way): read the tab, values.update the matching row, else values.append.
		// Unmapped columns keep whatever the existing row held, so an update
		// never blanks Invoice Number / Payment Status.
		//
		// `preserveFilled` additionally refuses to overwrite an already-populated
		// *mapped* cell — see the Payments Table call below.
		const upsertByKey = async (tabName, keyColumn, mapping, opts) => {
			const preserveFilled = !!(opts && opts.preserveFilled);
			const resp = await sheets.spreadsheets.values.get({
				spreadsheetId: SPREADSHEET_ID,
				range: tabName,
				// Round-trip formulas as formulas. An update rewrites the WHOLE
				// row, and the default FORMATTED_VALUE render would hand back a
				// formula cell as its computed text — writing that back would
				// flatten a live formula in a column this feature doesn't own.
				valueRenderOption: "FORMULA",
			});
			const rows = resp.data.values || [];
			const tabHeaders = rows[0] || [];
			if (!tabHeaders.length) throw new Error(`${tabName} has no header row`);
			const matchRow = rateconLoad.findRowIndexByColumn(rows, keyColumn, loadId);
			const existingRow = matchRow > 0 ? rows[matchRow - 1] : null;
			let rowValues;
			let conflicts = [];
			if (matchRow > 0 && preserveFilled) {
				const built = rateconLoad.buildMappedRowPreservingFilled(tabHeaders, mapping, existingRow);
				rowValues = built.values;
				conflicts = built.conflicts;
			} else {
				rowValues = rateconLoad.buildMappedRow(tabHeaders, mapping, existingRow);
			}
			// Anchor every write to column A explicitly. values.append with a
			// bare tab range lets Sheets auto-detect the table's anchor column
			// from existing data, and when a tab's leading column is empty
			// (Job Details' column A is blank; Payments Table's early columns are
			// sparse) the appended row lands SHIFTED right into the wrong columns.
			// A new row goes to A{lastRow+1} — rows already excludes trailing
			// empties, so its length is the last populated row (1-based incl. the
			// header). Both branches therefore write starting at column A.
			const targetRow = matchRow > 0 ? matchRow : rows.length + 1;
			await sheets.spreadsheets.values.update({
				spreadsheetId: SPREADSHEET_ID,
				range: `${tabName}!A${targetRow}`,
				valueInputOption: "USER_ENTERED",
				requestBody: { values: [rowValues] },
			});
			return { action: matchRow > 0 ? "updated" : "appended", row: targetRow, conflicts };
		};

		// n8n "RATE UPDATE" — the key column really is named " Job ID"
		// (leading space); matching is done on the trimmed header.
		//
		// preserveFilled because the dedupe above only proves the LOAD is new,
		// not that the payment row is: a matched Payments Table row can belong
		// to an older load whose Job Tracking row was archived or removed, and
		// that row may already carry a booked Payment Amount / Invoice Number.
		// Filling its blanks is the point of an upsert; silently rewriting a
		// settled figure from a load-creation flow is not. Conflicts surface as
		// a warning naming the columns so a human reconciles them.
		try {
			const payResult = await upsertByKey("Payments Table", " Job ID", {
				" Job ID": loadId,
				"Contract ID": String(fields["Broker Name"] || "").trim(),
				"Payment Amount": String(fields["Rate"] || "").trim(),
			}, { preserveFilled: true });
			if (payResult.conflicts.length) {
				warnings.push(
					`The Payments Table already had a row for ${loadId} with a different ` +
					`${payResult.conflicts.join(" and ")} — the existing value was kept. Reconcile it manually.`,
				);
			}
		} catch (e) {
			console.error("Rate-con load: Payments Table upsert failed:", e.message);
			warnings.push("The Payments Table row was not written — add the payment amount manually.");
		}

		// n8n "Google Sheets2"
		try {
			await upsertByKey("Job Details", "Load ID", {
				"Load ID": loadId,
				"Rate Per Mile": `$${rpm.rate_per_mile}`,
				"Distance": `${rpm.distance_miles} Miles`,
				"Details": rpm.details,
				"Payment": rpm.payment,
			});
		} catch (e) {
			console.error("Rate-con load: Job Details upsert failed:", e.message);
			warnings.push("The Job Details row was not written — distance and rate-per-mile are missing for this load.");
		}

		// ---- 7) Archive the rate-con PDF so invoice drafting can find it later.
		// getRateConBytes() resolves a load's rate-con from THREE sources, in
		// order: (a) the Drive folder, (b) a `documents` row of type RATECON, and
		// (c) a base64 in the request body. The Drive folder is a *My Drive*
		// folder owned by info@logisx.com — the app's service account is
		// read-only there and has no storage quota, so a service-account upload
		// ALWAYS fails in production (n8n only manages it via OAuth delegation).
		// So the reliable path is (b): write the PDF under /uploads and register
		// a `documents` row, exactly like PODs. That row is what makes a dropped
		// load invoiceable. Drive is then attempted best-effort for parity with
		// the email pipeline, but its failure is silent — (b) already covers us.
		let rateconArchived = false;
		const rawPdf = typeof pdfBase64 === "string"
			? pdfBase64.replace(/^data:application\/pdf;base64,/, "").trim()
			: "";
		if (!rawPdf) {
			warnings.push(`No rate-con PDF was attached, so invoice drafting will not find one for load ${loadId}.`);
		} else if (!/^JVBERi/.test(rawPdf)) {
			warnings.push("The attached file was not a PDF, so the rate-con was not archived.");
		} else if (Math.floor((rawPdf.length * 3) / 4) > 15 * 1024 * 1024) {
			// Same 15 MB decoded cap the extract route enforces — without it this
			// route would accept anything up to the 50 MB global body limit.
			// Warn rather than fail: the load row is already committed.
			warnings.push(`The rate-con PDF is larger than 15 MB, so it was not archived. Attach it to load ${loadId} manually before drafting an invoice.`);
		} else {
			const pdfBuffer = Buffer.from(rawPdf, "base64");
			// (b) PRIMARY — local /uploads + a documents row. This is what
			// getRateConBytes() step 2 reads, and it needs no Drive quota.
			try {
				const rcDir = path.join(__dirname, "uploads", "rate-cons");
				if (!fs.existsSync(rcDir)) fs.mkdirSync(rcDir, { recursive: true });
				const safeLoad = String(loadId).replace(/[^A-Za-z0-9._-]/g, "_");
				const fileNameOut = `${safeLoad}.pdf`;
				fs.writeFileSync(path.join(rcDir, fileNameOut), pdfBuffer);
				// Replace any prior rate-con for this load so a re-create can't
				// leave two RATECON rows racing in getRateConBytes' ORDER BY.
				db.prepare("DELETE FROM documents WHERE load_id = ? AND UPPER(type) = 'RATECON'").run(loadId);
				db.prepare(
					`INSERT INTO documents (load_id, driver, type, file_name, drive_file_id, drive_url)
					 VALUES (?, ?, 'RATECON', ?, '', ?)`,
				).run(loadId, "", fileNameOut, `/uploads/rate-cons/${fileNameOut}`);
				rateconArchived = true;
			} catch (e) {
				console.error("Rate-con load: local rate-con archive failed:", e.message);
				warnings.push(`The rate-con PDF could not be saved, so invoice drafting will not find one for load ${loadId}. Attach it manually.`);
			}
			// (a) BEST-EFFORT — mirror into the Drive folder too, for parity with
			// the n8n email pipeline. Expected to fail under the service account
			// in production; that's fine, (b) is authoritative. Silent on error.
			try {
				const { Readable } = require("stream");
				const drive = await getDrive();
				await drive.files.create({
					requestBody: {
						name: `${loadId}.pdf`,
						parents: [RATECON_DRIVE_FOLDER_ID],
						mimeType: "application/pdf",
					},
					media: { mimeType: "application/pdf", body: Readable.from(pdfBuffer) },
					fields: "id,name",
					supportsAllDrives: true,
				});
			} catch (e) {
				// No warning to the dispatcher — the local copy already made the
				// load invoiceable. Log for observability only.
				console.error("Rate-con load: Drive mirror failed (non-fatal):", e.message);
			}
		}

		// ---- 8) load_coordinates + audit trail + dispatch notification ----
		if (pickupCoords || dropoffCoords) {
			try {
				db.prepare(`INSERT OR REPLACE INTO load_coordinates (load_id, origin_lat, origin_lng, dest_lat, dest_lng, pickup_address, dropoff_address) VALUES (?, ?, ?, ?, ?, ?, ?)`)
					.run(
						loadKey,
						pickupCoords ? pickupCoords.lat : null,
						pickupCoords ? pickupCoords.lng : null,
						dropoffCoords ? dropoffCoords.lat : null,
						dropoffCoords ? dropoffCoords.lng : null,
						pickupAddress,
						dropoffAddress,
					);
			} catch { /* non-critical */ }
		}

		logAudit(
			req,
			"create_load_ratecon",
			"load",
			loadId,
			`Created load ${loadId} from a dropped rate-con${fileName ? ` (${String(fileName).slice(0, 120)})` : ""}; ` +
				`${rpm.distance_miles} mi @ $${rpm.rate_per_mile}/mi; rate-con ${rateconArchived ? "archived to Drive" : "NOT archived"}`,
		);

		// Same "new-load" notification the n8n webhook raises, so a dropped load
		// surfaces identically to an email-ingested one. loadId lives inside
		// metadata for the NotificationsView click-routing convention.
		const route = rpm.details && rpm.details !== "Distance unavailable"
			? rpm.details
			: [pickupAddress, dropoffAddress].filter(Boolean).join(" → ");
		insertDispatchNotification.run(
			"new-load",
			`New Load ${loadId}`,
			route,
			JSON.stringify({ loadId, rowIndex, source: "ratecon-drop" }),
		);
		io.to("dispatch").emit("new-load", { timestamp: Date.now() });
		io.to("dispatch").emit("dispatch-notification", {
			type: "new-load",
			title: `New Load ${loadId}`,
			body: route,
		});
		notifyChange("dashboard");

		res.json({
			success: true,
			loadId,
			rowIndex,
			distanceMiles: rpm.distance_miles,
			ratePerMile: rpm.rate_per_mile,
			warnings,
		});
	} catch (error) {
		console.error("Error creating load from rate-con:", error.message);
		res.status(500).json({ error: "Failed to create the load. Check the Job Tracking sheet before retrying." });
	}
});

// GET /api/documents/:loadId — Fetch all documents for a load
app.get("/api/documents/:loadId", requireAuth, async (req, res) => {
	try {
		const loadId = decodeURIComponent(req.params.loadId);
		// SECURITY: drivers can only read documents for their own loads.
		// Without this guard, any logged-in driver could enumerate PODs and
		// receipts on any other driver's load by guessing the loadId.
		if (req.session.user.role === "Driver") {
			const owned = await loadBelongsToDriver(loadId, req.session.user.driverName);
			if (!owned) return res.status(403).json({ error: "This load is not assigned to you" });
		}
		// RATECON rows are EXCLUDED from this list, by owner request 2026-08-06:
		// this panel is the driver's proof-of-delivery paperwork, and a rate con
		// is neither uploaded by the driver nor something dispatch needs beside a
		// POD. It is written here only as an invoice-drafting archive by
		// POST /api/loads/from-ratecon (getRateConBytes() source (b), since the
		// service account cannot write the Drive folder).
		//
		// SECURITY, not just cosmetics: a rate con states the BROKER RATE, and
		// every RATECON row carries a working drive_url (/uploads/rate-cons/...).
		// The driver's DocumentList renders a View link for any row with one, so
		// before this filter a driver could open the rate con for their own load
		// and read the rate — undoing the financial-column stripping that
		// GET /api/driver/:driverName and the /rate|amount|.../i filter do
		// everywhere else. The matching /uploads/rate-cons guard is above.
		//
		// The row is NOT deleted and NOT hidden from invoicing: getRateConBytes()
		// queries `documents` directly, so drafting still finds and attaches it.
		const docs = db
			.prepare(
				`SELECT id, load_id, driver, type, file_name, drive_file_id, drive_url, strftime('%Y-%m-%dT%H:%M:%SZ', uploaded_at) AS uploaded_at, ocr_text
				 FROM documents
				 WHERE load_id = ? AND deleted_at IS NULL
				   AND UPPER(REPLACE(REPLACE(COALESCE(type,''), ' ', ''), '_', '')) != 'RATECON'
				 ORDER BY uploaded_at DESC`,
			)
			.all(loadId);
		res.json({ documents: docs });
	} catch (error) {
		console.error("Error fetching documents:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// DELETE /api/documents/:id — SOFT-delete one document (the "X" on a POD tile).
//
// Soft only, deliberately: a POD is the financial/legal proof a broker paid
// against, so the bytes stay on disk / in Drive and the row stays queryable.
// This mirrors deleted_loads and job_applications.deleted_at. Recovery is
// `UPDATE documents SET deleted_at = NULL WHERE id = ?`.
//
// Guard: the LAST live POD on a delivered/completed load cannot be removed.
// That load could not legally have reached Delivered without a POD (see the POD
// gate in PUT /api/driver/status), so dropping its last one would manufacture a
// state the system would never have allowed — and silently break invoicing,
// since POST /api/loads/:loadId/draft-invoice 400s with no POD. Upload the
// replacement first, then delete. Removing a NON-last POD is always fine.
// Super Admin ONLY, per the owner. Deleting a POD is what makes a load
// un-invoiceable, so it sits with whoever answers for the money — not with
// whoever is moving the freight. Note this is narrower than the UPLOAD route
// (requireAuth), which must stay open: drivers upload their own PODs from the
// driver app, and dispatchers attach ones that arrive by email.
app.delete("/api/documents/:id", requireRole("Super Admin"), async (req, res) => {
	try {
		const id = Number(req.params.id);
		if (!Number.isInteger(id) || id <= 0) {
			return res.status(400).json({ error: "Invalid document id" });
		}
		const doc = db.prepare("SELECT * FROM documents WHERE id = ?").get(id);
		if (!doc) return res.status(404).json({ error: "Document not found" });
		if (doc.deleted_at) return res.status(404).json({ error: "Document already deleted" });

		const reason = String((req.body && req.body.reason) || "").trim().slice(0, 500);
		const loadId = doc.load_id || "";
		const isPod = String(doc.type || "").toUpperCase() === "POD";

		// Only the last-POD case needs the load's status, so the Sheets read is
		// skipped entirely for every other delete — a Sheets outage must not
		// block removing a duplicate receipt or a page-2 POD.
		if (isPod && loadId) {
			const remaining = db
				.prepare(
					"SELECT COUNT(*) AS n FROM documents WHERE load_id = ? AND UPPER(type) = 'POD' AND deleted_at IS NULL AND id != ?",
				)
				.get(loadId, id);
			if (!remaining || remaining.n === 0) {
				let status = null;
				try {
					const jt = await getJobTrackingCached();
					const headers = jt.headers || [];
					const loadIdCol = findCol(headers, /load.?id|job.?id/i);
					const statusCol = findCol(headers, /status/i);
					const target = String(loadId).trim().toLowerCase().replace(/^#/, "");
					if (loadIdCol && statusCol) {
						const row = (jt.data || []).find(
							(r) => String(r[loadIdCol] || "").trim().toLowerCase().replace(/^#/, "") === target,
						);
						// A load with NO Job Tracking row stays null, not "". Older
						// loads do get archived out of the live sheet, and "" would
						// sail past the delivered regex below and drop the guard
						// entirely for exactly the archived, already-invoiced loads
						// this protects.
						if (row) status = String(row[statusCol] || "").trim();
					}
				} catch (e) {
					console.error("Document delete: Job Tracking read failed:", e.message);
				}
				// status === null means the load's status could not be established —
				// sheet unreadable, columns missing, or no matching row. Fail CLOSED
				// rather than guess the load is still in transit.
				if (status === null) {
					return res.status(409).json({
						code: "LOAD_STATUS_UNVERIFIED",
						error:
							"This is the only Proof of Delivery on the load, and its status could not be verified right now. Try again in a moment.",
					});
				}
				if (/^(delivered|completed|pod received)$/i.test(status)) {
					return res.status(409).json({
						code: "LAST_POD_ON_DELIVERED_LOAD",
						error: `This is the only Proof of Delivery on load ${loadId}, which is already ${status}. Removing it would leave the load un-invoiceable — upload a replacement POD first, then delete this one.`,
					});
				}
			}
		}

		const result = db
			.prepare(
				"UPDATE documents SET deleted_at = CURRENT_TIMESTAMP, deleted_by = ?, delete_reason = ? WHERE id = ? AND deleted_at IS NULL",
			)
			.run((req.session.user && req.session.user.username) || "", reason, id);
		if (result.changes === 0) {
			// Lost a race with a concurrent delete of the same row.
			return res.status(404).json({ error: "Document not found or already deleted" });
		}

		logAudit(
			req,
			"soft_delete_document",
			"document",
			id,
			`${doc.type || "document"} "${doc.file_name || id}" on load ${loadId || "(none)"}${reason ? ` — ${reason}` : ""}`,
		);
		notifyChange("dashboard"); // _podCount on the load card just changed
		res.json({ success: true, id, loadId, type: doc.type || "", fileName: doc.file_name || "" });
	} catch (err) {
		console.error("Document soft-delete failed:", err.message);
		res.status(500).json({ error: "Delete failed. Please try again." });
	}
});

// ============================================================
// Draft Invoice — assemble invoice + supporting docs for ANY broker and
// write a Gmail draft (IMAP), falling back to n8n. LogisX does ALL the data
// work; n8n only turns the assembled payload into a draft. Bison is no
// longer a gate, only a branch (its own AP inbox). See lib/broker-invoice.js.
// ============================================================

// Lazily-created Drive client. Reuses the same service-account `auth` as
// getSheets(); its scopes include drive.file (read/write the app's own files,
// e.g. PODs LogisX uploaded) AND drive.readonly (read any shared file, e.g.
// the n8n-populated rate-con folder — see getRateConBytes).
let driveClient = null;
async function getDrive() {
	if (!driveClient) {
		const authClient = await auth.getClient();
		driveClient = google.drive({ version: "v3", auth: authClient });
	}
	return driveClient;
}

// Fetch raw bytes for a documents-table row. Prefers the local /uploads copy
// (uploads are written to disk with drive_url = "/uploads/<file>"), falling
// back to the Drive API when only a drive_file_id is present. Returns a
// Buffer or null.
async function fetchDocumentBytes(doc) {
	if (!doc) return null;
	// 1) Local /uploads copy.
	const localName =
		(doc.drive_url && doc.drive_url.startsWith("/uploads/"))
			? doc.drive_url.replace("/uploads/", "")
			: doc.file_name;
	if (localName) {
		const uploadsRoot = path.join(__dirname, "uploads");
		const localPath = path.join(uploadsRoot, localName);
		// SECURITY — containment assert, same pattern as the receipt reads.
		// `drive_url` and `file_name` are the two columns POST /api/documents/upload
		// just stopped being able to write traversal into, but rows written BEFORE
		// that fix are still on disk and nothing prunes them. Neither guard above
		// catches "/uploads/../../.env": it passes startsWith(), and .replace() is
		// single-occurrence so only the leading segment is stripped, leaving
		// "../../.env" to resolve to the app root — where .env,
		// service-account-key.json and app.db all live. That matters more here than
		// almost anywhere else, because this feeds getRateConBytes() →
		// POST /api/loads/:loadId/draft-invoice, so the bytes are ATTACHED TO AN
		// OUTBOUND GMAIL DRAFT addressed to the broker.
		// Skip the local read rather than returning — a poisoned drive_url must not
		// also disable the legitimate Drive fallback below.
		if (!localPath.startsWith(uploadsRoot + path.sep)) {
			console.error("Draft invoice: refused out-of-tree document path", { localName });
		} else {
			try {
				if (fs.existsSync(localPath)) return fs.readFileSync(localPath);
			} catch (e) {
				console.error("Draft invoice: local doc read failed:", e.message);
			}
		}
	}
	// 2) Drive API (files.get alt=media) by drive_file_id.
	if (doc.drive_file_id) {
		try {
			const drive = await getDrive();
			const resp = await drive.files.get(
				{ fileId: doc.drive_file_id, alt: "media", supportsAllDrives: true },
				{ responseType: "arraybuffer" },
			);
			return Buffer.from(resp.data);
		} catch (e) {
			console.error("Draft invoice: Drive doc fetch failed:", e.message);
		}
	}
	return null;
}

// Resolve the rate-con bytes + display name for a load. Order of preference:
//   1. The rate-con Drive folder (RATECON_DRIVE_FOLDER_ID) — the n8n dispatch
//      workflow drops every Bison rate-con there, named by email subject
//      ("...Bison Transport Order #7007280"). We match on the order number
//      (== loadId for Bison) and take the most recent. Needs drive.readonly.
//   2. A rate-con document row in the documents table (future-proofing, if a
//      RateCon/BOL ever gets registered for the load).
//   3. A caller-supplied base64 in the request body (rateconPdfBase64).
// Returns { buffer, fileName } (buffer may be null when nothing is found).
async function getRateConBytes(loadId, body) {
	const orderNumber = String(loadId || "").replace(/^#/, "").trim();
	// Sanitize before interpolating into the Drive query (avoid breaking the
	// quoted `name contains '...'` clause). Bison order numbers are numeric.
	const safe = orderNumber.replace(/[^A-Za-z0-9]/g, "");

	// Collect EVERY candidate rate-con for this load, in priority order. A load
	// often has more than one file (the original rate-con + a "Re:" reply, or a
	// signed scan), and the billing / "send documents to" email may live on only
	// ONE of them — so callers can extract from all, not just the newest.
	const candidates = [];

	// 1) Rate-con Drive folder — ALL files whose name contains the order number.
	if (RATECON_DRIVE_FOLDER_ID && safe) {
		try {
			const drive = await getDrive();
			const list = await drive.files.list({
				q: `'${RATECON_DRIVE_FOLDER_ID}' in parents and trashed = false and name contains '${safe}'`,
				fields: "files(id,name,createdTime)",
				orderBy: "createdTime desc",
				pageSize: 10,
				supportsAllDrives: true,
				includeItemsFromAllDrives: true,
			});
			const files = (list.data.files || []).filter((f) => (f.name || "").includes(safe));
			for (const f of files.slice(0, 5)) {
				try {
					const resp = await drive.files.get(
						{ fileId: f.id, alt: "media", supportsAllDrives: true },
						{ responseType: "arraybuffer" },
					);
					const buffer = Buffer.from(resp.data);
					if (buffer && buffer.length) candidates.push({ buffer, fileName: `${orderNumber}.pdf`, label: (f.name || "").replace(/^Subject:\s*/i, "").replace(/\.pdf$/i, "").trim().slice(0, 70) || "Rate-con", source: "drive" });
				} catch (e) {
					console.error("Draft invoice: rate-con Drive file fetch failed:", e.message);
				}
			}
		} catch (e) {
			console.error("Draft invoice: rate-con Drive list failed:", e.message);
		}
	}

	// 2) A rate-con document row in the documents table.
	const row = db
		.prepare(
			`SELECT * FROM documents
			 WHERE load_id = ? AND UPPER(type) IN ('RATECON','RATE CON','RATE_CON','BOL')
			   AND deleted_at IS NULL
			 ORDER BY uploaded_at DESC LIMIT 1`,
		)
		.get(loadId);
	if (row) {
		const buffer = await fetchDocumentBytes(row);
		if (buffer) candidates.push({ buffer, fileName: row.file_name || `${orderNumber || "ratecon"}.pdf`, label: row.file_name || "Stored rate-con", source: "documents" });
	}

	// 3) Caller-supplied base64 fallback.
	const supplied = body && (body.rateconPdfBase64 || body.ratecon_base64);
	if (supplied && typeof supplied === "string") {
		const b64 = supplied.replace(/^data:application\/pdf;base64,/, "").trim();
		try {
			const buffer = Buffer.from(b64, "base64");
			if (buffer && buffer.length) candidates.push({ buffer, fileName: `${orderNumber || "ratecon"}.pdf`, label: "Uploaded file", source: "upload" });
		} catch { /* fall through */ }
	}

	// Primary (first) drives the attachment + order/total extraction, unchanged.
	const primary = candidates[0] || null;
	return {
		buffer: primary ? primary.buffer : null,
		fileName: primary ? primary.fileName : `${orderNumber || "ratecon"}.pdf`,
		candidates,
	};
}

// ===========================================================================
// EDITABLE INVOICE OVERRIDES — the shared validator for the two routes that
// render an invoice from dispatcher-supplied fields (POST …/draft-invoice and
// POST …/invoice-preview).
//
// Client ask: "I can't approve it if the information on it is not correct."
// Nine fields on the printed invoice used to be derived-only, so a misread
// order number or a stale sheet rate had no path but "fix the source and
// re-run" — which, for a delivered load in a closed month, is no path at all.
//
// ⚠️ ONE validator, called as the first statement of BOTH routes. Forking the
// rules is how the preview comes to render something the approve then refuses
// (or worse, quietly renders differently).
// ===========================================================================

// MM/DD/YYYY out of a bare `YYYY-MM-DD`, by STRING SURGERY.
//
// ⚠️ NEVER `new Date(iso)` and never brokerInvoice.formatDate() on an ISO
// string. Both lose a day, measured: formatDate("2026-08-14") returns
// "08/13/2026", because its final fallback is `new Date(raw)` (UTC midnight)
// rendered through mdy() in America/Chicago. `<input type="date">` emits
// exactly this shape, so passing it through would date EVERY edited invoice one
// day early — on the document that drives the broker's aging terms.
function isoToMdy(iso) {
	const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(iso == null ? "" : iso).trim());
	return m ? `${m[2]}/${m[3]}/${m[1]}` : "";
}

// The inverse, for seeding `<input type="date">` from a value the server
// already formatted for print. Same rule: string surgery, no Date.
function mdyToIso(mdy) {
	const m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(String(mdy == null ? "" : mdy).trim());
	return m ? `${m[3]}-${m[1].padStart(2, "0")}-${m[2].padStart(2, "0")}` : "";
}

// Wide enough that no legitimate invoice or delivery date is ever refused
// (backdated corrections included), narrow enough that a typo cannot print a
// year no broker's AP system will accept.
const INVOICE_YEAR_MIN = 2000;
const INVOICE_YEAR_MAX = 2100;

// A real day, without constructing a Date (which would silently roll 2026-02-30
// forward to March and print a date the dispatcher never chose).
function isRealCalendarDate(y, mo, d) {
	// The \d{4} shape alone admits year 0000 — `<input type="date">` will happily
	// emit it from a mistyped keystroke, and "01/14/0000" printed on a broker's
	// invoice is a document nobody can age. Bounded rather than clamped: a
	// refusal the dispatcher can see and correct beats a silently rewritten year.
	if (!(y >= INVOICE_YEAR_MIN && y <= INVOICE_YEAR_MAX)) return false;
	if (!(mo >= 1 && mo <= 12) || !(d >= 1)) return false;
	const leap = (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0;
	return d <= [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][mo - 1];
}

// A filename, from a string that reached us off a PDF, a sheet cell or a form.
//
// Today `orderNumber` is NOT sanitized at all yet builds both the invoice
// attachment name and the rate-con attachment name — and it is now editable, so
// the value is directly attacker-supplied by anyone who can reach the route.
// A CR in a filename forges MIME headers; a leading ".." is the traversal token;
// the Windows-reserved set breaks the recipient's own save dialog.
//
// `fallback` is a parameter and not a constant because the broker-name half is
// legitimately EMPTY (the non-Bison filename reads "Invoice Order #…" with no
// prefix) — defaulting that to "Invoice" would print "Invoice Invoice Order #…".
function safeAttachmentName(value, max = 80, fallback = "Invoice") {
	let s = String(value == null ? "" : value).normalize("NFC").replace(EVIDENCE_TEXT_STRIP, " ");
	s = s.replace(/[\\/:*?"<>|]+/g, " ").replace(/\s+/g, " ").trim();
	// ⚠️ `[.\s]+`, not `\.+`, and it must run AFTER the separator replacement.
	// Replacing separators MANUFACTURES new leading dot-runs: "../../etc/passwd"
	// becomes ".. .. etc passwd", and a `^\.+` pass strips only the FIRST run —
	// the trim then re-exposes the second, leaving ".. etc passwd", a name that
	// still begins with the traversal token. Measured: that is exactly what the
	// first draft returned. Stripping any leading run of dots OR spaces is
	// idempotent by construction.
	s = s.replace(/^[.\s]+/, "");
	// Array.from, not slice — cutting at a UTF-16 boundary splits a surrogate
	// pair and leaves a lone surrogate in a MIME header. Same reasoning as
	// sanitizeEvidenceText().
	s = Array.from(s).slice(0, max).join("").trim();
	return s || fallback;
}

// The strict money shape, applied BEFORE brokerInvoice.parseMoney() ever runs.
//
// ⚠️ THE ORDER IS THE WHOLE POINT. parseMoney is a MANGLER, not a validator —
// it strips everything outside [0-9.\-] and parseFloats the remains, so
// (measured) "12abc34" → 1234, "-500" → -500 (a NEGATIVE invoice), "1e9" → 19,
// "0.001" → 0.001 which formatMoney prints as "$0.00". Every one of those
// passes a naive `> 0` check. Gate the SHAPE first; parse second.
const INVOICE_TOTAL_FORMAT_RE = /^\$?\s*(\d{1,3}(,\d{3})*|\d+)(\.\d{1,2})?$/;
// $1,000,000 matches sanitizeManualInvoiceRows' ceiling — one carrier, one
// invoice, and a typo'd extra digit is the realistic failure here.
const INVOICE_TOTAL_MAX = 1000000;
// ⚠️ 0.01, NOT `> 0`. formatMoney(0.001) === "$0.00": a positive number that
// prints zero, which walks straight through the never-draft-a-$0.00-invoice
// guard while printing exactly the document that guard exists to prevent.
const INVOICE_TOTAL_MIN = 0.01;

// Charsets. Deliberately narrow — these strings become a filename, an email
// subject, a PDF field and an audit line. The `{0,39}` is the LENGTH RULE, not
// decoration: see INVOICE_FIELD_SCAN_MAX.
const INVOICE_ID_RE = /^[A-Za-z0-9][A-Za-z0-9._\/-]{0,39}$/;
const INVOICE_REF_RE = /^[A-Za-z0-9][A-Za-z0-9 ._\/#-]{0,39}$/;

// ⚠️ The sanitize bound is DELIBERATELY LOOSER than the charset regexes' own
// 40-char limit, and that is what makes over-length a REFUSAL instead of a
// silent truncation. sanitize(v, 40) would cut a 45-character invoice number
// down to 40 and hand the regex a string that now matches — so the dispatcher
// types a number, the modal accepts it, and the PDF prints a different one.
// Sanitizing wide and letting the anchored regex judge the WHOLE value is the
// only ordering where the stated limit is the enforced limit.
//
// Bounded at all (rather than unbounded) because these are anchored, non-nested
// single-class patterns — linear, so 200 characters is free — and the cap keeps
// an oversized body from being copied around before it is refused.
const INVOICE_FIELD_SCAN_MAX = 200;

// The nine editable fields plus `moveNumber`, which has no UI: it is printed in
// the Bison cover letter, so leaving it un-pinned would let a nondeterministic
// Gemini re-run on the commit change a body the dispatcher already reviewed —
// the same reasoning already written for the recipient below.
//
// Returns { ok, error, code, field, has, values }. `has[k]` is true only when
// the CLIENT SENT the key: undefined/null mean "not supplied → derive it
// server-side", "" means "the dispatcher cleared it" and is honoured or
// refused per the table. That distinction is the POST /api/invoices/manual
// precedent verbatim (see the payeeAddress comment) and it matters here for
// the same reason: silently restoring a value somebody deliberately deleted
// defeats the entire feature.
function parseInvoiceOverrides(body) {
	const src = body && typeof body === "object" ? body : {};
	// ⚠️ Object.create(null), NOT {} — and this is the money-bearing half.
	//
	// supplied() correctly uses hasOwnProperty, so nothing can be WRITTEN through
	// the prototype. But every consumer READS `ov.has.total` / `ov.values.total`,
	// and a plain object literal inherits, so those reads traverse it:
	//
	//   Object.prototype.total = 999999;  parseInvoiceOverrides({})
	//     → ov.has.total is truthy and ov.values.total === 999999, having NEVER
	//       entered `if (supplied("total"))` — so the format gate, the $0.01
	//       floor and the $1,000,000 ceiling are all skipped and the approve
	//       bills $999,999.00. The same shape reaches has.recipientEmail (which
	//       redirects where the invoice is MAILED) and has.invoiceId.
	//
	// There is no pollution sink in this app today (no Object.assign over
	// req.body, no deepMerge, no lodash.merge, and express.json()'s JSON.parse
	// makes "__proto__" an OWN property rather than polluting), so this is
	// defence in depth — but the cost is one word and the failure mode is a
	// silently mis-billed invoice that passes every validator.
	const has = Object.create(null);
	const values = Object.create(null);
	const supplied = (k) => {
		if (!Object.prototype.hasOwnProperty.call(src, k)) return false;
		return src[k] !== undefined && src[k] !== null;
	};
	// The refusal shape needs the same treatment: a caller that ignores `ok` and
	// reads `has`/`values` anyway must see nothing, not the prototype.
	const bad = (code, field, error) => ({ ok: false, code, field, error, has: Object.create(null), values: Object.create(null) });

	// --- free text, may be cleared -------------------------------------------
	// brokerName / billToName / moveNumber all have fallback rendering in the
	// template, so "" is a legitimate choice rather than an error. Coerced, not
	// refused — a non-string here is a client bug, not an attack surface, and
	// sanitizeEvidenceText already String()s and strips the dangerous class.
	for (const [key, max] of [["brokerName", 80], ["billToName", 80], ["moveNumber", 40]]) {
		if (!supplied(key)) continue;
		has[key] = true;
		values[key] = sanitizeEvidenceText(src[key], max);
	}

	// --- invoiceId ------------------------------------------------------------
	if (supplied("invoiceId")) {
		const v = sanitizeEvidenceText(src.invoiceId, INVOICE_FIELD_SCAN_MAX);
		if (!INVOICE_ID_RE.test(v)) {
			return bad("INVOICE_ID_INVALID", "invoiceId",
				"Invoice # must be 1–40 characters using letters, numbers, . _ / or - and start with a letter or number.");
		}
		has.invoiceId = true;
		values.invoiceId = v;
	}

	// --- dates ----------------------------------------------------------------
	// invoiceDate is required-if-sent; deliveryDate may be cleared (the template
	// renders a blank cell, which is what a load with no recorded delivery date
	// already prints today).
	for (const [key, code, allowEmpty, label] of [
		["invoiceDate", "INVOICE_DATE_INVALID", false, "Invoice date"],
		["deliveryDate", "DELIVERY_DATE_INVALID", true, "Delivery date"],
	]) {
		if (!supplied(key)) continue;
		const v = sanitizeEvidenceText(src[key], 40);
		if (!v) {
			if (allowEmpty) { has[key] = true; values[key] = ""; continue; }
			return bad(code, key, `${label} is required.`);
		}
		const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(v);
		if (!m || !isRealCalendarDate(+m[1], +m[2], +m[3])) {
			return bad(code, key, `${label} must be a real date in YYYY-MM-DD form.`);
		}
		has[key] = true;
		// Stored PRINT-READY. buildInvoiceHtml runs formatDate() over whatever it
		// is handed, and only the M/D/Y branch of that function is day-accurate.
		values[key] = isoToMdy(v);
		values[key + "Iso"] = v;
	}

	// --- recipientEmail -------------------------------------------------------
	// One deliberate behaviour change: an invalid address used to be SILENTLY
	// IGNORED here. Tolerable while this was one hidden field; a trap with nine
	// visible ones, because the dispatcher would watch their correction vanish
	// and the invoice mail to the old address anyway.
	if (supplied("recipientEmail")) {
		const v = brokerInvoice.normalizeEmail(src.recipientEmail);
		if (!v) return bad("RECIPIENT_INVALID", "recipientEmail", "Recipient must be a valid email address.");
		has.recipientEmail = true;
		values.recipientEmail = v;
	}

	// --- order / PO refs ------------------------------------------------------
	// orderNumber may NOT be cleared: it heads the invoice, drives the subject,
	// and an empty one yields a rate-con attachment literally named ".pdf".
	if (supplied("orderNumber")) {
		const v = sanitizeEvidenceText(src.orderNumber, INVOICE_FIELD_SCAN_MAX);
		if (!v || !INVOICE_REF_RE.test(v)) {
			return bad("ORDER_NUMBER_INVALID", "orderNumber",
				"Order # must be 1–40 characters using letters, numbers, spaces or . _ / # - and start with a letter or number.");
		}
		has.orderNumber = true;
		values.orderNumber = v;
	}
	if (supplied("poNumber")) {
		const v = sanitizeEvidenceText(src.poNumber, INVOICE_FIELD_SCAN_MAX);
		if (v && !INVOICE_REF_RE.test(v)) {
			return bad("PO_NUMBER_INVALID", "poNumber",
				"PO # must use letters, numbers, spaces or . _ / # - and start with a letter or number.");
		}
		has.poNumber = true;
		values.poNumber = v;
	}

	// --- total ----------------------------------------------------------------
	// Three ordered steps; see INVOICE_TOTAL_FORMAT_RE above for why the gate
	// runs first. "" is REFUSED rather than falling back to the derived number:
	// clearing the field is deliberate, and quietly restamping the old rate is
	// exactly the silent behaviour the manual-invoice route already refuses.
	if (supplied("total")) {
		const t = src.total;
		// Arrays coerce disarmingly well — String([1800]) === "1800" — so the
		// type check is not ceremony.
		if (typeof t !== "string" && typeof t !== "number") {
			return bad("INVOICE_TOTAL_INVALID", "total", "Invoice total must be a number.");
		}
		const raw = sanitizeEvidenceText(t, 40);
		if (!raw || !INVOICE_TOTAL_FORMAT_RE.test(raw)) {
			return bad("INVOICE_TOTAL_INVALID", "total",
				"Invoice total must be a plain dollar amount, e.g. 1800 or 1,800.00.");
		}
		const n = Math.round(brokerInvoice.parseMoney(raw) * 100) / 100;
		if (!(n >= INVOICE_TOTAL_MIN) || n > INVOICE_TOTAL_MAX) {
			return bad("INVOICE_TOTAL_OUT_OF_RANGE", "total",
				`Invoice total must be between $${INVOICE_TOTAL_MIN.toFixed(2)} and $${INVOICE_TOTAL_MAX.toLocaleString("en-US")}.`);
		}
		has.total = true;
		values.total = n;
	}

	return { ok: true, error: "", code: "", field: "", has, values };
}

// "Is this invoice number already on a draft?" — a WARNING, never a block.
//
// invoice_id carries no unique index and must not gain one: the modal already
// offers a legitimate re-approve, which reissues the number on purpose. It is
// also a MEMBERSHIP test (COUNT), not a fetch-one-then-compare, for the same
// reason guardInvoicePdf is.
//
// ⚠️ False negatives BY CONSTRUCTION: recordDraft() only runs on send success,
// so a number burned by a failed IMAP APPEND is absent from this table and this
// probe will call it free. Reporting it as a warning rather than a refusal is
// what keeps that acceptable.
function invoiceIdAlreadyUsed(invoiceId, loadId) {
	try {
		const row = db
			.prepare("SELECT COUNT(*) AS n FROM load_invoice_drafts WHERE invoice_id = ? AND load_id <> ?")
			.get(String(invoiceId || ""), String(loadId || ""));
		return !!(row && row.n > 0);
	} catch {
		return false;
	}
}

// POST /api/loads/:loadId/draft-invoice  (alias: .../draft-bison-invoice)
// Restricted to Super Admin + Dispatcher (the roles that run dispatch ops).
// The legacy Bison-specific path stays registered so any external caller
// (bookmarks, n8n, a cached SPA bundle) keeps working — same handler.
app.post(
	["/api/loads/:loadId/draft-invoice", "/api/loads/:loadId/draft-bison-invoice"],
	requireRole("Super Admin", "Dispatcher"),
	async (req, res) => {
		try {
			const loadId = decodeURIComponent(req.params.loadId || "").trim();
			if (!loadId) return res.status(400).json({ error: "loadId is required" });
			const dryRun = String(req.query.dryRun || "") === "1" || req.query.dryRun === "true";

			// 0) The dispatcher's corrections, validated BEFORE anything is spent.
			//    A malformed body must not cost a full Job Tracking read, N Drive
			//    document reads and a Gemini vision call before it 400s.
			const ov = parseInvoiceOverrides(req.body);
			if (!ov.ok) return res.status(400).json({ error: ov.error, code: ov.code, field: ov.field });

			// 1) Look up the load in the Job Tracking sheet by loadId.
			const sheets = await getSheets();
			const resp = await sheets.spreadsheets.values.get({
				spreadsheetId: SPREADSHEET_ID,
				range: "Job Tracking",
			});
			const parsed = parseSheet({ values: resp.data.values });
			const rows = deduplicateLoads(parsed.data, parsed.headers);
			const headers = parsed.headers;
			const loadIdCol = findCol(headers, /load.?id|job.?id/i);
			if (!loadIdCol) return res.status(500).json({ error: "Sheet misconfigured" });
			const target = loadId.toLowerCase().replace(/^#/, "");
			const load = rows.find(
				(r) => (r[loadIdCol] || "").toString().trim().toLowerCase().replace(/^#/, "") === target,
			);
			if (!load) return res.status(404).json({ error: "Load not found" });

			// Resolve the columns we need from the sheet.
			const emailCol = findCol(headers, /^email$/i) || findCol(headers, /broker.*email|email/i);
			const statusCol = findCol(headers, /^status$/i) || findCol(headers, /status/i);
			const trailerCol = findCol(headers, /trailer/i);
			const deliveryDateCol =
				headers.find((h) => /status.*update.*date|completion.*date/i.test(h)) ||
				headers.find((h) => /drop.?off.*date|drop.?off.*appoint|deliv.*date|deliv.*appoint/i.test(h));
			const driverCol = findCol(headers, /^driver$/i) || findCol(headers, /driver/i);
			const brokerNameCol = findCol(headers, /broker.*(contact|name)/i);
			// The money column is literally "  Payment  " (real surrounding
			// spaces) — matched on the trimmed header inside the helper.
			const paymentCol = brokerInvoice.findPaymentColumn(headers);

			const brokerEmail = emailCol ? (load[emailCol] || "").toString().trim() : "";
			const brokerContactName = brokerNameCol ? (load[brokerNameCol] || "").toString().trim() : "";
			const status = statusCol ? (load[statusCol] || "").toString().trim() : "";
			const sheetTrailer = trailerCol ? (load[trailerCol] || "").toString().trim() : "";

			// 2) Broker identity. Every broker can be invoiced now — the Bison
			//    check is a BRANCH (it picks the AP inbox), no longer a gate.
			//    The sheet has no brokerage-company column, so the name is
			//    resolved from the email domain; see lib/broker-invoice.js.
			const brokerCtx = { brokerEmail, brokerContactName };
			const isBison = brokerInvoice.isBisonLoad({ email: brokerEmail });
			const brokerName = brokerInvoice.resolveBrokerName(brokerCtx);
			let invoiceTo = brokerInvoice.resolveInvoiceTo(brokerCtx);

			//    The delivered/completed gate is unchanged.
			if (!/delivered|completed|pod received/i.test(status)) {
				return res.status(400).json({
					error: `Load must be delivered/completed to draft an invoice (current status: "${status || "unknown"}").`,
				});
			}

			// 3) Get the POD + rate-con bytes (server-side).
			//
			// EVERY POD, not just the newest. A proof packet routinely arrives as
			// several files (driver photographs the signed BOL page by page), and
			// this used to be `ORDER BY uploaded_at DESC LIMIT 1` — which silently
			// billed brokers with a one-page fragment of a three-page proof and got
			// invoices rejected. 14 of 85 loads with a POD have more than one.
			//
			// ASC = upload order = page order (id breaks ties: uploaded_at only has
			// second granularity and a burst of page uploads can share a second).
			const podDocs = db
				.prepare(
					"SELECT * FROM documents WHERE load_id = ? AND UPPER(type) = 'POD' AND deleted_at IS NULL ORDER BY uploaded_at ASC, id ASC",
				)
				.all(loadId);
			if (!podDocs.length) return res.status(400).json({ error: "POD not found for this load" });

			// Fetch sequentially — these are local /uploads reads in the common case,
			// and the Drive fallback is rate-limited enough that a parallel fan-out
			// buys nothing. A row whose bytes are unreadable is dropped rather than
			// failing the whole draft, but it IS surfaced to the caller (below), so a
			// missing page is never silently omitted a second time.
			const podFiles = [];
			const podMissing = [];
			for (const d of podDocs) {
				const buf = await fetchDocumentBytes(d);
				if (buf && buf.length) podFiles.push({ doc: d, buffer: buf });
				else podMissing.push(d.file_name || String(d.id));
			}
			if (!podFiles.length) return res.status(400).json({ error: "POD not found for this load" });
			if (podMissing.length) {
				console.warn(
					`Draft invoice ${loadId}: ${podMissing.length} of ${podDocs.length} POD file(s) unreadable, attaching ${podFiles.length} — ${podMissing.join(", ")}`,
				);
			}

			// Attachment names. A single POD keeps its EXACT historical name — the
			// overwhelming majority of loads, and "1 of 1" would be noise a broker
			// has to parse. Multi-POD gets "POD_2_of_3_<loadId>.pdf" so an AP clerk
			// can see at a glance whether the packet is complete.
			const podSafeLoadId = String(loadId).replace(/[^A-Za-z0-9._-]/g, "_");
			const podAttachments = podFiles.map((f, i) => ({
				filename:
					podFiles.length === 1
						? f.doc.file_name || `${podSafeLoadId}_POD.pdf`
						: `POD_${i + 1}_of_${podFiles.length}_${podSafeLoadId}.pdf`,
				content: f.buffer,
				contentType: "application/pdf",
			}));
			// Back-compat aliases for the single-POD consumers further down.
			const podDoc = podFiles[0].doc;
			const podBuffer = podFiles[0].buffer;

			const { buffer: rateconBuffer, fileName: rateconFileName, candidates: rateconCandidates } = await getRateConBytes(loadId, req.body);
			// Say so plainly. The invoice still drafts without one (POD + the
			// sheet's Payment column carry it), but brokers generally require the
			// rate-con alongside the invoice, so an unattached one is the reason a
			// payment later stalls. The preview modal warns the reviewer too.
			if (!rateconBuffer || !rateconBuffer.length) {
				console.warn(
					`Draft invoice ${loadId}: no rate-con found (Drive folder, documents table and request body all empty) — drafting without it.`,
				);
			}

			// 4) Extract the rate-con fields (deterministic text scan → Gemini fallback).
			//    The Gemini fallback reuses the shared runRateConGemini() helper.
			//    NOTE: only the Bison rate-con has the "Billing Information" block
			//    the deterministic scan understands — every OTHER broker takes the
			//    Gemini path, so it is the primary path now, not an edge case
			//    (verified against real C.H. Robinson / Navisphere rate-cons).
			const geminiExtract = GEMINI_API_KEY
				? async (buf) => {
						// Defensive: extractRateConFields already skips the call when
						// there are no bytes, but this wrapper is the seam a future
						// caller reaches for, and Buffer.from(null) throws.
						if (!buf || !buf.length) return null;
						const b64 = Buffer.from(buf).toString("base64");
						if (!/^JVBERi/.test(b64)) return null;
						return runRateConGemini(b64);
				  }
				: null;
			// This route already degrades correctly on a Gemini failure —
			// extractRateConFields returns empty fields, the total falls back to the
			// sheet's Payment column and the order number to the load ID — so there is
			// no status to change here. Two things are free, and only those:
			// (a) NAME the failure in the log. "Gemini fallback failed" on a dead key
			//     reads as a parsing problem, which is what sent 2026-08-05's outage to
			//     the wrong diagnosis for a day.
			// (b) latch it, so the alternate-rate-con loop below stops re-calling a
			//     scanner that is refusing everything.
			let geminiUnavailable = null;
			const onGeminiError = (e) => {
				if (e && e.kind === "unavailable") {
					geminiUnavailable = e;
					console.error(`Draft invoice: Gemini fallback unavailable (Gemini ${e.status}${e.reason ? " " + e.reason : ""}):`, e.message);
					return;
				}
				console.error("Draft invoice: Gemini fallback failed:", e.message);
			};
			const rcFields = await brokerInvoice.extractRateConFields(rateconBuffer, {
				brokerEmail, // exclude the booking agent's own email from documents-email detection
				geminiExtract,
				onGeminiError,
			});

			// A load can have MULTIPLE rate-con files (the original + a "Re:" reply, or
			// a signed scan). getRateConBytes returns the newest as the primary, but the
			// billing / "send documents to" email may live on ANOTHER file — so if the
			// primary yielded none, check the other candidates and take the first that
			// does. Prevents defaulting the invoice to the wrong inbox (client 2026-07-30:
			// Steam Logistics load 2214407 — carrierdocs@steamlogistics.com was only on the
			// original file, not the newer "Re:" scan). Only runs when the primary is empty.
			if (!rcFields.documentsEmail && Array.isArray(rateconCandidates) && rateconCandidates.length > 1) {
				for (const cand of rateconCandidates) {
					if (!cand || !cand.buffer || cand.buffer === rateconBuffer) continue;
					try {
						// Drop only the GEMINI half when the key is refusing — the
						// documents email this loop is hunting for comes from the
						// deterministic text scan, so skipping the whole loop would
						// throw away a recovery that never needed Gemini. Passing null
						// keeps the free scan and spends nothing.
						const alt = await brokerInvoice.extractRateConFields(cand.buffer, { brokerEmail, geminiExtract: geminiUnavailable ? null : geminiExtract, onGeminiError });
						if (alt.documentsEmail) {
							rcFields.documentsEmail = alt.documentsEmail;
							console.log(`Draft invoice ${loadId}: documents email recovered from an alternate rate-con file (of ${rateconCandidates.length} candidates).`);
							break;
						}
					} catch (e) {
						console.error("Draft invoice: alternate rate-con extract failed:", e.message);
					}
				}
			}

			// Recipient: the rate-con's "email documents to" address wins over the
			// hardcoded default (drives both the Gmail To: and the printed
			// "Invoice To" block); falls back to Bison AP inbox / quickpay when absent.
			invoiceTo = brokerInvoice.resolveInvoiceTo({ ...brokerCtx, documentsEmail: rcFields.documentsEmail });

			// The review-before-approve preview sends the recipient the dispatcher SAW
			// back on approve, pinning it — so a nondeterministic Gemini re-run on the
			// commit can't silently re-route the draft to a different address than the
			// one that was reviewed. Classify "manual" only when the override actually
			// DIFFERS from what extraction resolved (an unchanged confirm keeps the
			// ratecon/default badge). An invalid/empty override is ignored.
			const resolvedEmail = invoiceTo.email;
			const resolvedInvoiceToName = invoiceTo.name;
			const recipientOverride = ov.has.recipientEmail ? ov.values.recipientEmail : "";
			let recipientSource = rcFields.documentsEmail ? "ratecon" : "default";
			if (recipientOverride) {
				if (recipientOverride.toLowerCase() !== String(resolvedEmail).toLowerCase()) recipientSource = "manual";
				invoiceTo = { name: invoiceTo.name, email: recipientOverride };
			}
			// The "Invoice To" NAME is separately overridable now. It is a different
			// fact from the address — resolveInvoiceTo() labels the block from the
			// RECIPIENT's domain, so the two legitimately diverge — which is exactly
			// why recipient_source above is left alone and keeps meaning "provenance
			// of the email address" and nothing else.
			if (ov.has.billToName) invoiceTo = { name: ov.values.billToName, email: invoiceTo.email };

			// 4b) Invoice reference number. Per client (2026-07-30): ONLY Bison
			//     invoices carry the broker's rate-con Order # (Bison AP matches on
			//     it). EVERY other broker is invoiced by our Load Number, so a
			//     non-Bison rate-con Order # is deliberately ignored here. Bison
			//     still falls back to the load ID when its rate-con had no Order #.
			const loadRef = loadId.replace(/^#/, "").trim();
			const derivedOrderNumber = isBison ? (rcFields.orderNumber || loadRef) : loadRef;
			// The dispatcher's correction wins — this is the field Gemini most often
			// gets one digit wrong on, and it is what broker AP matches against.
			const orderNumber = ov.has.orderNumber ? ov.values.orderNumber : derivedOrderNumber;
			if (isBison && !rcFields.orderNumber) {
				console.log(
					`Draft invoice ${loadId}: no order # from the Bison rate-con (gemini=${GEMINI_API_KEY ? "on" : "off"}) — falling back to the load ID.`,
				);
			}

			// 5) Validation: rate-con trailer must match the load's stored trailer.
			//    On mismatch, do NOT call n8n — return 409 so the frontend can alert.
			//    Only compare when the extracted trailer actually looks like a
			//    trailer id (contains a digit): a guard that blocks on garbage is
			//    worse than no guard, and prose like "Trailer Required" has been
			//    seen leaking out of loosely-labelled rate-cons.
			const normTrailer = (s) => String(s || "").toLowerCase().replace(/[^a-z0-9]/g, "");
			const rcTrailerUsable = /\d/.test(String(rcFields.trailerNumber || ""));
			if (sheetTrailer && rcTrailerUsable && normTrailer(sheetTrailer) !== normTrailer(rcFields.trailerNumber)) {
				return res.status(409).json({
					error: `Trailer mismatch: rate-con says ${rcFields.trailerNumber} but the load is on trailer ${sheetTrailer}. Invoice not drafted.`,
					code: "TRAILER_MISMATCH",
					details: { rateconTrailer: rcFields.trailerNumber, loadTrailer: sheetTrailer },
				});
			}

			// 6) Invoice total: the rate-con's Total Rate, else the load's
			//    "  Payment  " cell from the sheet. HARD STOP when neither
			//    yields a positive number — this endpoint moves money, and a
			//    $0.00 invoice mailed to a broker is worse than an error.
			const rcTotal = brokerInvoice.parseMoney(rcFields.totalRate);
			const sheetTotal = paymentCol ? brokerInvoice.parseMoney(load[paymentCol]) : 0;
			const derivedTotal = rcTotal > 0 ? rcTotal : sheetTotal;
			// A SUPPLIED total satisfying this guard IS the feature: extraction
			// fails, the dispatcher types 2100.00, the invoice drafts. But the
			// guarantee shifts from "the server proved a number exists" to "a human
			// typed a number", so the number is RE-DERIVED through the same format
			// gate / >= $0.01 floor / $1,000,000 ceiling in parseInvoiceOverrides()
			// rather than trusted. It is never skipped.
			//
			// ⚠️ An overridden total is INVOICE-ONLY. Nothing here writes back to the
			// Job Tracking "  Payment  " column, so revenue, driver pay, investor
			// payouts and the P&L keep reading the sheet exactly as they do today and
			// no closed month can be restated by an invoice correction. The
			// divergence is RECORDED instead (total_source / sheet_total /
			// ratecon_total below). Owner decision — do not "helpfully" sync it.
			const totalAmount = ov.has.total ? ov.values.total : derivedTotal;
			const totalSource = ov.has.total ? "manual" : (rcTotal > 0 ? "ratecon" : (derivedTotal > 0 ? "sheet" : "unknown"));
			const needsTotal = !(totalAmount > 0);
			// ⚠️ RELAXED FOR dryRun ONLY, and that relaxation is the blocker fix.
			// The review modal opens exclusively via ?dryRun=1, so while this 422
			// fired ahead of the preview response the dispatcher never saw a form to
			// type the missing total INTO — precisely in the case this feature exists
			// for. The preview instead returns 200 with needsTotal:true and skips the
			// render entirely, so no $0.00 LogisX PDF is ever produced. The real
			// approve keeps the hard 422 unchanged, and the delivered gate, both POD
			// gates and the trailer 409 above are all untouched.
			if (needsTotal && !dryRun) {
				return res.status(422).json({
					error:
						`Invoice total is unknown for load ${loadId} — the rate-con had no readable Total Rate` +
						(paymentCol ? ` and the sheet's ${paymentCol.trim()} column is empty` : " and the sheet has no payment column") +
						". Refusing to draft a $0.00 invoice. Add the rate to the load, then retry." +
						(GEMINI_API_KEY ? "" : " (Rate-con AI extraction is not configured on this server.)"),
					code: "INVOICE_TOTAL_UNKNOWN",
				});
			}

			// 6b) Invoice identifiers + dates. invoiceId/invoiceDate use the
			//    button-click date (today, server local). deliveryDate is the
			//    load's ACTUAL delivery/completion date from the sheet — never
			//    today, never the rate-con scheduled date.
			const today = new Date();
			// dryRun previews the next number without consuming it; a real draft commits it.
			//
			// ⚠️ THE SEQUENCE IS CONSUMED ON EVERY REAL APPROVE, override or not.
			// The common path is a dispatcher confirming the peeked value verbatim,
			// so gating nextInvoiceNumber() on "no override was sent" would leave the
			// slot unconsumed and the NEXT draft would reissue the same number. Mint
			// first, then print whatever was reviewed.
			const mintedInvoiceId = dryRun ? peekInvoiceNumber(today) : nextInvoiceNumber(today);
			const invoiceId = ov.has.invoiceId ? ov.values.invoiceId : mintedInvoiceId;
			const derivedInvoiceDate = brokerInvoice.formatDate(today);
			const invoiceDate = ov.has.invoiceDate ? ov.values.invoiceDate : derivedInvoiceDate;
			const rawDeliveryDate = deliveryDateCol ? (load[deliveryDateCol] || "").toString().trim() : "";
			const derivedDeliveryDate = brokerInvoice.formatDate(rawDeliveryDate);
			const deliveryDate = ov.has.deliveryDate ? ov.values.deliveryDate : derivedDeliveryDate;
			// ⚠️ isBison is NOT recomputed from an edited broker name. It derives from
			// the broker EMAIL above and drives the AP inbox, the Bison-vs-generic
			// cover letter and the Bison filename — editing a display name must never
			// flip the email template or the routing.
			const effBrokerName = ov.has.brokerName ? ov.values.brokerName : brokerName;
			const derivedPoNumber = rcFields.poNumber || "";
			const poNumber = ov.has.poNumber ? ov.values.poNumber : derivedPoNumber;
			const derivedMoveNumber = rcFields.moveNumber || "";
			const moveNumber = ov.has.moveNumber ? ov.values.moveNumber : derivedMoveNumber;
			// "" on the needsTotal dryRun — never "$0.00", which reads as a real
			// figure the reviewer might approve.
			const total = needsTotal ? "" : brokerInvoice.formatMoney(totalAmount);

			// 7) Render the invoice PDF. Skipped entirely when no total could be
			//    derived AND none was supplied (dryRun only — see the guard above):
			//    there is nothing honest to print, and a rendered $0.00 invoice is
			//    the one artifact this route has always refused to create.
			let invoicePdf = null;
			let invoicePdfBase64 = "";
			if (!needsTotal) {
				const invoiceHtml = brokerInvoice.buildInvoiceHtml({
					invoiceId,
					invoiceDate,
					brokerName: effBrokerName,
					invoiceTo,
					orderNumber,
					poNumber,
					deliveryDate,
					total,
				});
				invoicePdf = await renderHtmlToPdf(invoiceHtml);
				invoicePdfBase64 = Buffer.from(invoicePdf).toString("base64");
			}

			// 7b) Build the standard invoice email (body + signature) — the same
			//     content the draft carries. For a Bison load brokerName is
			//     "Bison Transport", so the subject renders exactly as before.
			const draftSubject = effBrokerName
				? `${effBrokerName} Order #${orderNumber}`
				: `Order #${orderNumber}`;
			const draftHtml = brokerInvoice.buildInvoiceEmailHtml({
				brokerName: effBrokerName,
				isBison,
				loadNumber: loadRef,
				orderNumber,
				moveNumber,
				poNumber,
			});
			// Bison's attachment name is left byte-identical; other brokers get
			// their own name (a broker filing "Bison Invoice ..." would be odd).
			//
			// Both halves now go through safeAttachmentName(): orderNumber is
			// dispatcher-supplied and was never sanitized at all. The broker half
			// passes fallback "" on purpose — an empty broker name legitimately
			// yields the bare "Invoice Order #…" form.
			const safeName = safeAttachmentName(effBrokerName, 40, "");
			const safeOrderNumber = safeAttachmentName(orderNumber, 40);
			const invoiceFileName = isBison
				? `Bison Invoice Order #${safeOrderNumber}.pdf`
				: `${safeName ? safeName + " " : ""}Invoice Order #${safeOrderNumber}.pdf`;
			// invoicePdf is null only on the needsTotal dryRun, which returns below
			// and never reads this array.
			const draftAttachments = invoicePdf
				? [
						{ filename: invoiceFileName, content: invoicePdf, contentType: "application/pdf" },
						// ALL PODs, in page order — see step 3.
						...podAttachments,
				  ]
				: [];
			if (invoicePdf && rateconBuffer && rateconBuffer.length) {
				draftAttachments.push({ filename: `${safeOrderNumber}.pdf`, content: rateconBuffer, contentType: "application/pdf" });
			}

			// Dry-run / preview: generate everything but create no draft. Echo
			// the resolved routing so a reviewer can verify recipient/subject/
			// total without opening the PDF.
			if (dryRun) {
				return res.json({
					success: true,
					preview: true,
					dryRun: true,
					invoiceId,
					brokerName: effBrokerName,
					to: invoiceTo.email,
					subject: draftSubject,
					orderNumber,
					total,
					totalSource,
					// ── Seeds for the editable review form. Everything the modal has
					//    to render as an input, in the exact shape the input wants —
					//    the client must never reparse a printed date or a formatted
					//    money string, because that is where the off-by-one and the
					//    "$" round-trip come back.
					needsTotal,
					// RAW number, not the formatted `total`, so the input starts as
					// "3000" and not "$3,000.00". null when there is nothing to seed —
					// an empty field the dispatcher must fill, which is the point.
					totalAmount: needsTotal ? null : totalAmount,
					invoiceDate,
					invoiceDateIso: mdyToIso(invoiceDate),
					deliveryDate,
					deliveryDateIso: mdyToIso(deliveryDate),
					poNumber,
					billToName: invoiceTo.name,
					// The number the sequence WOULD hand out, so the modal can flag an
					// invoice # that diverges from it. Peeked — never consumed here.
					peekedInvoiceId: mintedInvoiceId,
					// Printed in the Bison cover letter but has no UI: echoed so the
					// approve can pin the value the reviewer actually saw, exactly as
					// the recipient is pinned above.
					moveNumber,
					// ⚠️ PINNED, NOT DERIVED — the same treatment as moveNumber, and for
					// the same reason. This value is authoritative HERE and only here:
					// it comes from the SHEET's broker email, which nobody can edit.
					// The preview route cannot see the sheet, so echoing it is what
					// lets the Email tab render the exact cover letter the approve will
					// send. Without it a Bison load previews the generic letter and
					// mails the Bison one — the precise class of bug this whole feature
					// exists to remove, on the tab whose entire job is "read the note
					// before you approve".
					isBison,
					invoiceFileName,
					// Gemini is nondeterministic, so the trailer 409 can still fire on
					// approve after a clean preview. Surfacing the comparison here lets
					// the modal warn BEFORE the dispatcher spends time editing.
					trailerCheck: {
						sheet: sheetTrailer,
						ratecon: String(rcFields.trailerNumber || ""),
						ok: !(sheetTrailer && rcTrailerUsable && normTrailer(sheetTrailer) !== normTrailer(rcFields.trailerNumber)),
					},
					// The whole POD packet, by name, so QA/the reviewer can confirm
					// every page is attached without opening the draft.
					podCount: podAttachments.length,
					podFileNames: podAttachments.map((a) => a.filename),
					podUnreadable: podMissing,
					documentsEmail: invoiceTo.email,
					documentsEmailSource: recipientSource,
					invoicePdfBase64,
					rateconPdfBase64: rateconBuffer && rateconBuffer.length ? Buffer.from(rateconBuffer).toString("base64") : "",
					emailHtml: draftHtml, // exact Gmail draft body so the reviewer can read the cover note before approving
					ratecons: (rateconCandidates || []).map((c) => ({ base64: Buffer.from(c.buffer).toString("base64"), label: c.label || "Rate-con", source: c.source || "" })), // EVERY rate-con file for this load so the reviewer can see all of them, not just the primary
				});
			}

			// PRIMARY: create the Gmail draft directly via IMAP APPEND using the
			// existing app password (GMAIL_USER/GMAIL_APP_PASSWORD). No OAuth, no
			// token expiry. The draft lands in that mailbox's [Gmail]/Drafts.
			// Record the resolved recipient + its source so a mis-route is
			// diagnosable after the fact (recipient selection is now dynamic).
			console.log(
				`Draft invoice ${loadId}: recipient=${invoiceTo.email} source=${recipientSource}`,
			);

			// ⚠️ The collision probe runs HERE, not only in the preview — a caller
			// that never opens the modal (curl, n8n, any non-SPA client) can supply
			// an invoiceId duplicating a number already issued against another load
			// and would otherwise get no signal at all. Still a WARNING and never a
			// block: invoice_id carries no unique index by design, because the
			// re-approve flow legitimately reissues a number. Probed BEFORE
			// recordDraft() inserts this draft's own row.
			const draftWarnings = [];
			if (invoiceIdAlreadyUsed(invoiceId, loadId)) {
				draftWarnings.push(`Invoice # ${invoiceId} is already recorded on another load's draft.`);
				console.warn(`Draft invoice ${loadId}: invoice # ${invoiceId} collides with an existing draft on another load.`);
			}

			// What the dispatcher actually CHANGED, judged against what the server
			// would have produced on its own — not merely "which keys were sent".
			// The common path is confirming the peeked values verbatim, so keying on
			// presence would mark every draft edited and the distinction would be
			// worth nothing six months later.
			const fmtMoney = (n) => brokerInvoice.formatMoney(n || 0);
			const editDiffs = [
				["invoiceId", mintedInvoiceId, invoiceId],
				["invoiceDate", derivedInvoiceDate, invoiceDate],
				["billToName", resolvedInvoiceToName, invoiceTo.name],
				["recipientEmail", resolvedEmail, invoiceTo.email],
				["brokerName", brokerName, effBrokerName],
				["orderNumber", derivedOrderNumber, orderNumber],
				["poNumber", derivedPoNumber, poNumber],
				["deliveryDate", derivedDeliveryDate, deliveryDate],
				["moveNumber", derivedMoveNumber, moveNumber],
				["total", derivedTotal, totalAmount],
			].filter(([, from, to]) => String(from == null ? "" : from) !== String(to == null ? "" : to));
			const editedFields = editDiffs.map(([f]) => f);
			// Names the divergence explicitly, and names the RULE with it — an
			// auditor reading this row months later must not have to go and check
			// whether the sheet moved too. It did not, and that is owner decision #2.
			const editDetail = `${invoiceId} load ${loadId} — ` + editDiffs.map(([f, from, to]) =>
				f === "total"
					? `total: sheet ${fmtMoney(sheetTotal)} / ratecon ${fmtMoney(rcTotal)} → invoiced ${fmtMoney(to)} (INVOICE ONLY — Job Tracking Payment unchanged)`
					: `${f}: "${from}" → "${to}"`,
			).join("; ");

			// Persist that an official draft was created for this load so the load
			// modal can show "approved draft → recipient / invoice #". Best-effort —
			// never fails the draft. Only called on a real (non-dryRun) success.
			const recordDraft = (via) => {
				try {
					db.prepare(
						"INSERT INTO load_invoice_drafts (load_id, invoice_id, recipient, recipient_source, total, broker_name, order_number, via, created_by, edited, edited_fields, overrides_json, total_source, sheet_total, ratecon_total, invoice_id_minted) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
					).run(
						loadId, invoiceId, invoiceTo.email, recipientSource, total, effBrokerName, orderNumber, via,
						(req.session.user && req.session.user.username) || "",
						editedFields.length ? 1 : 0,
						editedFields.join(","),
						editedFields.length ? JSON.stringify(ov.values) : "",
						totalSource,
						sheetTotal > 0 ? fmtMoney(sheetTotal) : "",
						rcTotal > 0 ? fmtMoney(rcTotal) : "",
						invoiceId === mintedInvoiceId ? "" : mintedInvoiceId,
					);
					// ⚠️ BYTE-IDENTICAL for the unedited case, deliberately — historical
					// queries over invoice_draft_created must not change shape. The edit
					// is a SEPARATE action, per the naming discipline beside logAudit():
					// "which invoices did somebody hand-correct, and to what?" is then a
					// one-line query instead of a string scan.
					logAudit(req, "invoice_draft_created", "load", loadId, `${invoiceId} → ${invoiceTo.email} (${via})`);
					if (editedFields.length) {
						logAudit(req, "invoice_draft_edited", "load", loadId, sanitizeEvidenceText(editDetail, 1000));
					}
				} catch (e) {
					console.error("Draft invoice: draft record persist failed:", e.message);
				}
			};

			const gmailUser = process.env.GMAIL_USER;
			const gmailPass = process.env.GMAIL_APP_PASSWORD;
			let imapError = null;
			if (gmailUser && gmailPass) {
				try {
					await appendGmailDraft({
						user: gmailUser,
						pass: gmailPass,
						from: `LogisX Inc. <${gmailUser}>`,
						to: invoiceTo.email,
						subject: draftSubject,
						html: draftHtml,
						attachments: draftAttachments,
					});
					recordDraft("imap");
					return res.json({ success: true, invoiceId, via: "imap", draftMailbox: "[Gmail]/Drafts", warnings: draftWarnings });
				} catch (e) {
					imapError = e;
					console.error("Draft invoice: IMAP draft failed:", e.message);
					// fall through to the n8n fallback (if configured), else surface the error below
				}
			}

			// FALLBACK: POST to the n8n webhook, only if explicitly configured.
			const webhookUrl = process.env.N8N_INVOICE_WEBHOOK_URL;
			const webhookSecret = process.env.N8N_WEBHOOK_SECRET;
			if (webhookUrl && webhookSecret) {
				// The EFFECTIVE values, not the extracted ones — the fallback must
				// mail what the dispatcher reviewed, or the two send paths diverge on
				// exactly the fields this feature exists to correct.
				const payload = {
					loadId,
					brokerName: effBrokerName,
					orderNumber,
					moveNumber,
					poNumber,
					to: invoiceTo.email,
					invoicePdfBase64,
					invoiceFileName,
					// Legacy single-POD fields — kept so the existing n8n node keeps
					// working untouched; they carry page 1.
					podPdfBase64: Buffer.from(podBuffer).toString("base64"),
					podFileName: podAttachments[0].filename,
					// Full packet. n8n must attach `pods` (not just podPdfBase64) to
					// send a complete proof; the two overlap on page 1 by design.
					podCount: podAttachments.length,
					pods: podAttachments.map((a) => ({
						fileName: a.filename,
						base64: Buffer.from(a.content).toString("base64"),
					})),
					rateconPdfBase64: rateconBuffer ? Buffer.from(rateconBuffer).toString("base64") : "",
					rateconFileName: `${safeOrderNumber}.pdf`,
				};
				try {
					const controller = new AbortController();
					const timer = setTimeout(() => controller.abort(), 30000);
					const r = await fetch(webhookUrl, {
						method: "POST",
						headers: { "Content-Type": "application/json", "x-webhook-secret": webhookSecret },
						body: JSON.stringify(payload),
						signal: controller.signal,
					});
					clearTimeout(timer);
					const txt = await r.text().catch(() => "");
					let n8nResponse;
					try { n8nResponse = txt ? JSON.parse(txt) : {}; } catch { n8nResponse = { raw: txt.slice(0, 500) }; }
					if (!r.ok) return res.status(502).json({ error: `n8n webhook returned ${r.status}`, details: n8nResponse });
					recordDraft("n8n");
					return res.json({ success: true, invoiceId, via: "n8n", draftId: n8nResponse && (n8nResponse.draftId || n8nResponse.id), n8n: n8nResponse, warnings: draftWarnings });
				} catch (e) {
					console.error("Draft invoice: n8n webhook call failed:", e.message);
					return res.status(502).json({ error: "Failed to reach the invoice-draft webhook." });
				}
			}

			// IMAP was configured but failed, and no n8n fallback handled it →
			// surface the failure instead of pretending it worked.
			if (imapError) {
				return res.status(502).json({
					error: `Invoice ${invoiceId} was generated, but saving the Gmail draft failed (${imapError.message}). No draft was created — please retry.`,
					code: "DRAFT_SAVE_FAILED",
					invoiceId,
				});
			}
			// Nothing configured: return the generated invoice for preview so the
			// call still yields something useful.
			return res.json({ success: true, preview: true, invoiceId, invoicePdfBase64, note: "No Gmail/n8n draft target configured — invoice generated (preview only).", warnings: draftWarnings });
		} catch (err) {
			console.error("Draft invoice error:", err.message);
			return res.status(500).json({ error: "Failed to draft the invoice." });
		}
	},
);

// ===========================================================================
// POST /api/loads/:loadId/invoice-preview — re-render the invoice from the
// dispatcher's edits, and NOTHING else.
//
// Re-running ?dryRun=1 on every keystroke would cost a full Job Tracking read
// (Sheets is the primary database, 300 req/min quota), N Drive/POD reads and a
// Gemini vision call PER EDIT. This route does only: validate →
// buildInvoiceHtml → renderHtmlToPdf → base64. Zero Sheets, zero Drive, zero
// Gemini, zero DB writes.
//
// ⚠️ NO delivered / POD / trailer guards, and that is deliberate rather than an
// oversight. Those exist to stop an invoice being SENT for an undelivered load;
// this route sends nothing, creates nothing and persists nothing. Using them as
// a spend-limiter would reintroduce exactly the Sheets + Drive cost the route
// exists to avoid. It is not an IDOR either: it discloses nothing about the
// load, it echoes back what the caller already sent. `:loadId` stays in the
// path purely for log correlation and limiter locality — do NOT "fix" it into a
// lookup.
//
// ⚠️ It AUDITS NOTHING. A debounced render is not an event; writing an
// audit_trail row per keystroke is precisely the flood the refusal coalescing
// beside logAudit() exists to prevent. console.log, keyed on load + user.
// ===========================================================================
const invoicePreviewLimiter = rateLimit({
	windowMs: 15 * 60 * 1000,
	max: 120,
	// Per USER, not per IP — same reasoning as poiLimiter: a dispatch office
	// behind one NAT would otherwise share a bucket while any single client got
	// its own. 120 is a debounced editing session with headroom.
	keyGenerator: (req) => {
		const id = req.session?.user?.id;
		return id ? `u:${id}` : `ip:${ipKeyGenerator(req.ip)}`;
	},
	message: { error: "Too many invoice preview requests. Try again in a few minutes." },
	standardHeaders: true,
});
// ⚠️ THE LIMITER IS NOT THE REAL BOUND — THE IN-FLIGHT CAP IS. A per-user limit
// does not bound total work: several dispatchers (or one scripted client with a
// session) still land N concurrent Chromium tabs and OOM the box, which is the
// same reasoning already written above PDF_PREVIEW_MAX_INFLIGHT.
//
// ⚠️ FOLLOW-UP, deliberately NOT done here: that counter is route-local to the
// anonymous investor preview and renderHtmlToPdf() itself has no gate at all
// (lib/pdf-browser.js calls newPage() unserialized), so this makes TWO counters
// over ONE Chromium. The correct fix is a shared gate inside pdf-browser.js;
// doing it in this PR would change the concurrency behaviour of onboarding
// signing and the Friday auto-invoice batch as a side effect.
const INVOICE_PREVIEW_MAX_INFLIGHT = 2;
let invoicePreviewInflight = 0;
app.post(
	"/api/loads/:loadId/invoice-preview",
	requireRole("Super Admin", "Dispatcher"),
	// requireRole BEFORE the limiter so an unauthenticated caller cannot spend
	// the budget on 403s — the fuelEvents/fuelGallons precedent.
	refuseCrossSite,
	invoicePreviewLimiter,
	async (req, res) => {
		const loadId = decodeURIComponent(req.params.loadId || "").trim();
		if (!loadId) return res.status(400).json({ error: "loadId is required" });

		// The SAME validator the approve uses, as the first statement. Forking the
		// rules is how a preview comes to render something the approve refuses.
		const ov = parseInvoiceOverrides(req.body);
		if (!ov.ok) return res.status(400).json({ error: ov.error, code: ov.code, field: ov.field });

		// ⚠️ 422 INVOICE_TOTAL_UNKNOWN keeps EXACTLY its existing meaning here —
		// nothing derivable AND nothing supplied. On this route nothing is ever
		// derivable (it reads no sheet), so an omitted total is that case by
		// construction, and rendering it anyway would produce the $0.00 invoice
		// the whole flow refuses to create. A hand-typed junk value is a different
		// failure with a different code, decided above.
		if (!ov.has.total) {
			return res.status(422).json({
				error: "Enter an invoice total to preview the invoice.",
				code: "INVOICE_TOTAL_UNKNOWN",
			});
		}

		if (invoicePreviewInflight >= INVOICE_PREVIEW_MAX_INFLIGHT) {
			return res.status(429).json({
				error: "Too many invoice previews rendering at once. Try again in a moment.",
				code: "PREVIEW_BUSY",
			});
		}
		invoicePreviewInflight++;
		try {
			const loadRef = loadId.replace(/^#/, "").trim();
			// Fallbacks for an omitted key. Everything here is derivable from the
			// body or the path — no lookup — and in practice the client seeds every
			// field from the ?dryRun=1 response before the first keystroke.
			const fallbackTo = brokerInvoice.resolveInvoiceTo({});
			const invoiceTo = {
				name: ov.has.billToName ? ov.values.billToName : fallbackTo.name,
				email: ov.has.recipientEmail ? ov.values.recipientEmail : fallbackTo.email,
			};
			// PRINT THE CLIENT'S invoiceId; peek only as the omitted-key fallback.
			// Peeking per render would make the invoice # jump under the cursor
			// whenever another dispatcher approves something.
			const peekedInvoiceId = peekInvoiceNumber(new Date());
			const invoiceId = ov.has.invoiceId ? ov.values.invoiceId : peekedInvoiceId;
			const invoiceDate = ov.has.invoiceDate ? ov.values.invoiceDate : brokerInvoice.formatDate(new Date());
			const deliveryDate = ov.has.deliveryDate ? ov.values.deliveryDate : "";
			const brokerName = ov.has.brokerName ? ov.values.brokerName : "";
			const orderNumber = ov.has.orderNumber ? ov.values.orderNumber : loadRef;
			const poNumber = ov.has.poNumber ? ov.values.poNumber : "";
			const moveNumber = ov.has.moveNumber ? ov.values.moveNumber : "";
			const total = brokerInvoice.formatMoney(ov.values.total);

			// ⚠️ PINNED FROM THE dryRun, exactly like moveNumber — never re-derived
			// from the editable broker NAME.
			//
			// The approve path computes isBison from the SHEET's broker email and
			// echoes it in the ?dryRun=1 response; the modal sends it straight back
			// here. That is what makes the previewed cover letter provably the one
			// that gets sent, which is the Email tab's entire purpose.
			//
			// WHY ACCEPTING IT FROM THE BODY IS SAFE, and why the approve must never
			// do the same: this route SENDS NOTHING. It renders a PDF and returns
			// HTML to the caller who supplied the values. A client-supplied isBison
			// here is presentation-only — it cannot influence routing, the AP inbox,
			// the recipient, the attachment contents or anything that reaches Gmail.
			// On the approve path the same field would decide where money is invoiced
			// to, so it stays derived from the sheet, which nobody can edit.
			//
			// STRICTLY a boolean (the `agreed === true` discipline used for consent):
			// a "false" string is truthy and would flip the template the wrong way.
			// Anything else falls back to the recipient ADDRESS — resolveInvoiceTo()
			// pins every Bison load to the bisontransport.com AP inbox and rate-con
			// text can never override it, so the address is a faithful proxy. That
			// fallback keeps a caller that has not been updated (and any non-SPA
			// client) working. Its known edge — a Bison invoice deliberately
			// re-routed off-domain would preview the generic letter — is exactly what
			// the pinned value removes when it is present.
			const isBison = typeof (req.body && req.body.isBison) === "boolean"
				? req.body.isBison
				: brokerInvoice.isBisonLoad({ email: invoiceTo.email });

			const invoiceHtml = brokerInvoice.buildInvoiceHtml({
				invoiceId, invoiceDate, brokerName, invoiceTo, orderNumber, poNumber, deliveryDate, total,
			});
			const invoicePdf = await renderHtmlToPdf(invoiceHtml);

			// Return the DERIVED STRINGS too, so the client never re-implements a
			// server template. emailHtml especially: the modal's Email tab renders
			// the cover note built from the ORIGINAL values, so once those are
			// editable it would silently show a body that will not be sent.
			const subject = brokerName ? `${brokerName} Order #${orderNumber}` : `Order #${orderNumber}`;
			const emailHtml = brokerInvoice.buildInvoiceEmailHtml({
				brokerName, isBison, loadNumber: loadRef, orderNumber, moveNumber, poNumber,
			});
			const safeName = safeAttachmentName(brokerName, 40, "");
			const safeOrderNumber = safeAttachmentName(orderNumber, 40);
			const invoiceFileName = isBison
				? `Bison Invoice Order #${safeOrderNumber}.pdf`
				: `${safeName ? safeName + " " : ""}Invoice Order #${safeOrderNumber}.pdf`;

			const warnings = [];
			if (invoiceIdAlreadyUsed(invoiceId, loadId)) {
				warnings.push(`Invoice # ${invoiceId} is already recorded on another load's draft.`);
			}

			console.log(
				`Invoice preview ${sanitizeEvidenceText(loadId, 40)}: user=${(req.session.user && req.session.user.username) || ""} invoice=${invoiceId} total=${total}`,
			);
			return res.json({
				invoicePdfBase64: Buffer.from(invoicePdf).toString("base64"),
				subject,
				emailHtml,
				invoiceFileName,
				peekedInvoiceId,
				warnings,
			});
		} catch (err) {
			console.error("Invoice preview error:", err.message);
			return res.status(500).json({ error: "Failed to render the invoice preview." });
		} finally {
			// In a finally, always: a throw inside the render would otherwise leak a
			// slot and the cap would ratchet to zero after two failures.
			invoicePreviewInflight--;
		}
	},
);

// GET /api/loads/:loadId/invoice-draft — the latest official invoice draft created
// for a load (recipient + invoice #), so the load modal can reflect "approved draft".
app.get("/api/loads/:loadId/invoice-draft", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		const loadId = decodeURIComponent(req.params.loadId || "").trim();
		if (!loadId) return res.status(400).json({ error: "loadId is required" });
		// The edit columns ride along so the load modal can say "this draft was
		// hand-corrected, and here is what changed" without a second round trip.
		// overrides_json is deliberately NOT selected — it is the forensic copy for
		// audit_trail, not something a modal should render.
		const row = db
			.prepare(
				"SELECT load_id, invoice_id, recipient, recipient_source, total, broker_name, order_number, via, created_at, created_by, edited, edited_fields, total_source, sheet_total, ratecon_total, invoice_id_minted FROM load_invoice_drafts WHERE load_id = ? ORDER BY id DESC LIMIT 1",
			)
			.get(loadId);
		res.json({ draft: row || null });
	} catch (err) {
		console.error("GET /api/loads/:loadId/invoice-draft error:", err.message);
		res.status(500).json({ error: "Failed to load invoice draft state" });
	}
});

// GET /api/legal-documents — Legal docs for investor's trucks or driver shared docs
app.get("/api/legal-documents", requireRole("Super Admin", "Investor"), (req, res) => {
	try {
		const user = req.session.user;
		const isSuperAdmin = user.role === "Super Admin";
		// Accept BOTH snake_case (frontend convention) and camelCase (legacy).
		// Previously only `truckId` was read while the frontend always sent
		// `truck_id` — silently making truckId null and falling through to the
		// "return ALL docs" branch, leaking the entire fleet's docs into every
		// truck modal.
		let truckId = req.query.truck_id
			? parseInt(req.query.truck_id)
			: (req.query.truckId ? parseInt(req.query.truckId) : null);
		if (!truckId && req.query.unit_number) {
			const t = db.prepare("SELECT id FROM trucks WHERE LOWER(unit_number) = LOWER(?)").get(req.query.unit_number.trim());
			if (t) truckId = t.id;
		}
		// Super Admin viewing a specific driver's shared docs — guard against driver_id=0 sentinel collision
		const queryDriverId = req.query.driver_id ? parseInt(req.query.driver_id) : null;
		if (isSuperAdmin && queryDriverId && queryDriverId > 0) {
			const driverDocs = db.prepare(
				`SELECT ld.*, strftime('%Y-%m-%dT%H:%M:%SZ', ld.uploaded_at) AS uploaded_at FROM legal_documents ld WHERE ld.driver_id = ? ORDER BY ld.uploaded_at DESC`
			).all(queryDriverId);
			return res.json({ documents: driverDocs });
		}
		let docs;
		if (isSuperAdmin) {
			const queryInvId = req.query.investor_id ? parseInt(req.query.investor_id) : null;
			if (queryInvId) {
				// Super Admin viewing a specific investor's docs (profile + truck)
				const invUserId = db.prepare("SELECT user_id FROM investors WHERE id = ?").get(queryInvId);
				const owned = invUserId ? db.prepare("SELECT id FROM trucks WHERE owner_id = ?").all(invUserId.user_id).map(t => t.id) : [];
				const conditions = [`ld.investor_id = ?`];
				const params = [queryInvId];
				if (owned.length > 0) {
					conditions.push(`ld.truck_id IN (${owned.map(() => '?').join(',')})`);
					params.push(...owned);
				}
				docs = db.prepare(`SELECT ld.*, t.make, t.model, strftime('%Y-%m-%dT%H:%M:%SZ', ld.uploaded_at) AS uploaded_at FROM legal_documents ld LEFT JOIN trucks t ON t.id = ld.truck_id WHERE (${conditions.join(' OR ')}) ORDER BY ld.uploaded_at DESC`).all(...params);
			} else if (truckId) {
				docs = db.prepare(`SELECT ld.*, t.make, t.model, strftime('%Y-%m-%dT%H:%M:%SZ', ld.uploaded_at) AS uploaded_at FROM legal_documents ld LEFT JOIN trucks t ON t.id = ld.truck_id WHERE ld.truck_id = ? ORDER BY ld.uploaded_at DESC`).all(truckId);
			} else {
				docs = db.prepare(`SELECT ld.*, t.make, t.model, strftime('%Y-%m-%dT%H:%M:%SZ', ld.uploaded_at) AS uploaded_at FROM legal_documents ld LEFT JOIN trucks t ON t.id = ld.truck_id ORDER BY ld.uploaded_at DESC`).all();
			}
		} else {
			const inv = db.prepare("SELECT id FROM investors WHERE user_id = ?").get(user.id);
			const invId = inv ? inv.id : 0;
			const owned = db.prepare("SELECT id FROM trucks WHERE owner_id = ?").all(user.id).map(t => t.id);
			if (owned.length === 0 && !invId) return res.json({ documents: [] });

			// Per-truck scope: when the investor requests a specific truck, only
			// return docs for THAT truck (after verifying they own it). Previously
			// this branch always returned every doc across every truck the
			// investor owned, even when viewing a single-truck modal.
			if (truckId) {
				if (!owned.includes(truckId)) return res.json({ documents: [] });
				docs = db.prepare(`SELECT ld.*, t.make, t.model, strftime('%Y-%m-%dT%H:%M:%SZ', ld.uploaded_at) AS uploaded_at FROM legal_documents ld LEFT JOIN trucks t ON t.id = ld.truck_id WHERE ld.truck_id = ? ORDER BY ld.uploaded_at DESC`).all(truckId);
			} else {
				// Fleet-wide view: all owned-truck docs + investor-profile docs.
				const conditions = [];
				const params = [];
				if (owned.length > 0) {
					conditions.push(`ld.truck_id IN (${owned.map(() => '?').join(',')})`);
					params.push(...owned);
				}
				if (invId) {
					conditions.push(`ld.investor_id = ?`);
					params.push(invId);
				}
				const where = conditions.length > 0 ? `WHERE (${conditions.join(' OR ')})` : '';
				docs = db.prepare(`SELECT ld.*, t.make, t.model, strftime('%Y-%m-%dT%H:%M:%SZ', ld.uploaded_at) AS uploaded_at FROM legal_documents ld LEFT JOIN trucks t ON t.id = ld.truck_id ${where} ORDER BY ld.uploaded_at DESC`).all(...params);
			}
		}
		res.json({ documents: docs });
	} catch (err) {
		console.error("Error fetching legal documents:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// POST /api/legal-documents/upload — Super Admin or Investor uploads a legal doc
app.post("/api/legal-documents/upload", requireRole("Super Admin", "Investor"), async (req, res) => {
	try {
		const { truckId, unitNumber, docType, fileData, fileName, notes, investorId, driverId, visibleToDriver } = req.body;
		if (!fileData || !fileName) {
			return res.status(400).json({ error: "fileData and fileName are required" });
		}
		if (fileData.length > 13_500_000) {
			return res.status(400).json({ error: "File too large (max 10MB)" });
		}
		if (!validateFileExt(fileName)) return res.status(400).json({ error: "File type not allowed" });
		const validTypes = ['Title','Vehicle Title','Registration','Insurance Certificate','Insurance COI','Lease Agreement','Bill of Sale','Inspection Report','IFTA License','Maintenance Records','Photo','Contract','Tax Document','Compliance','Driver\'s License','Medical Card','ID Card','Other'];
		const safeType = validTypes.includes(docType) ? docType : 'Other';
		const ext = path.extname(fileName) || '.pdf';
		// Prefix filename with driver- or truck identifier depending on mode (for easier forensics in the uploads dir)
		const drvId = parseInt(driverId) || 0;
		const prefix = drvId > 0 ? `driver${drvId}` : (unitNumber || 'truck').replace(/[^a-zA-Z0-9]/g, '_');
		const safeName = `${prefix}_${safeType.replace(/[\s']/g, '_')}_${Date.now()}${ext}`;
		const legalDir = path.join(__dirname, "uploads", "legal");
		if (!fs.existsSync(legalDir)) fs.mkdirSync(legalDir, { recursive: true });
		const base64 = fileData.replace(/^data:[^;]+;base64,/, "");
		const legalBuf = Buffer.from(base64, "base64");
		// Bytes must match the extension for the types uploads/ serves inline —
		// same rule as POST /api/documents/upload. Not exploitable on its own
		// (nosniff), but this writes into the same inline-served tree, and a
		// mislabelled file is a broken document either way.
		const legalErr = verifyInlineServedBytes(legalBuf, path.extname(safeName));
		if (legalErr) return res.status(400).json({ error: legalErr });
		fs.writeFileSync(path.join(legalDir, safeName), legalBuf);
		const fileUrl = `/uploads/legal/${safeName}`;
		// Determine investor_id: from request body or from session (if Investor role)
		let invId = parseInt(investorId) || 0;
		if (req.session.user.role === "Investor" && !invId) {
			const inv = db.prepare("SELECT id FROM investors WHERE user_id = ?").get(req.session.user.id);
			if (inv) invId = inv.id;
		}
		// Driver-mode uploads MUST NOT also be tagged with truck/investor IDs
		const finalTruckId = drvId > 0 ? 0 : (parseInt(truckId) || 0);
		const finalInvId = drvId > 0 ? 0 : invId;
		const finalUnit = drvId > 0 ? '' : (unitNumber || '');
		// visible_to_driver only applies to truck-scoped docs. Driver-shared and
		// investor-profile docs already have their own visibility paths.
		const finalVisible = (finalTruckId > 0 && drvId === 0 && finalInvId === 0 && visibleToDriver) ? 1 : 0;
		const result = db.prepare(
			`INSERT INTO legal_documents (truck_id, unit_number, doc_type, file_name, file_url, notes, uploaded_by, investor_id, driver_id, visible_to_driver) VALUES (?,?,?,?,?,?,?,?,?,?)`
		).run(finalTruckId, finalUnit, safeType, fileName, fileUrl, notes || '', req.session.user.username, finalInvId, drvId, finalVisible);
		res.json({ success: true, id: result.lastInsertRowid, fileUrl, visibleToDriver: finalVisible === 1 });
	} catch (err) {
		console.error("Legal doc upload error:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// PATCH /api/legal-documents/:id/visibility — Super Admin toggles driver visibility
// on an existing truck-scoped doc. Driver-shared and investor-profile docs ignore
// the flag (those have their own visibility paths), so we reject them with 400.
app.patch("/api/legal-documents/:id/visibility", requireRole("Super Admin"), (req, res) => {
	try {
		const id = parseInt(req.params.id);
		if (!id || id <= 0) return res.status(400).json({ error: "Invalid document id" });
		const doc = db.prepare("SELECT id, truck_id, driver_id, investor_id FROM legal_documents WHERE id = ?").get(id);
		if (!doc) return res.status(404).json({ error: "Document not found" });
		if (!doc.truck_id || doc.truck_id <= 0 || (doc.driver_id && doc.driver_id > 0) || (doc.investor_id && doc.investor_id > 0)) {
			return res.status(400).json({ error: "Only truck-scoped documents support driver visibility" });
		}
		const next = req.body && req.body.visibleToDriver ? 1 : 0;
		db.prepare("UPDATE legal_documents SET visible_to_driver = ? WHERE id = ?").run(next, id);
		res.json({ success: true, id, visibleToDriver: next === 1 });
	} catch (err) {
		console.error("Visibility toggle error:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// DELETE /api/legal-documents/:id — Super Admin or owner removes a legal doc
app.delete("/api/legal-documents/:id", requireRole("Super Admin", "Investor"), (req, res) => {
	try {
		const id = parseInt(req.params.id);
		const doc = db.prepare("SELECT * FROM legal_documents WHERE id = ?").get(id);
		if (!doc) return res.status(404).json({ error: "Document not found" });
		if (doc.file_url) {
			const filePath = path.join(__dirname, doc.file_url);
			try { fs.unlinkSync(filePath); } catch { /* file may already be gone */ }
		}
		db.prepare("DELETE FROM legal_documents WHERE id = ?").run(id);
		res.json({ success: true });
	} catch (err) {
		res.status(500).json({ error: err.message });
	}
});

// This route was requireAuth ONLY and had no limiter, which is the combination
// that matters: it is reachable by EVERY role including a Driver, and it WRITES
// A FILE TO DISK on every call — up to 10 MB, under a `chat_${Date.now()}_${5
// random chars}` name that nothing ever prunes. Unbounded, that is a disk-fill
// available to the lowest-privilege account in the system, on the same volume as
// app.db and the nightly backups. There is no quota, no retention job, and no
// alert on free space; the VPS finding out is `SQLITE_FULL` on a settlement write.
//
// Capped at 40 attachments per 15 min for Super Admin / Dispatcher and 20 for
// everyone else — deliberately tighter than routeLimiter above, because the cost
// here is PERMANENT (bytes that stay on the disk) rather than per-request. 20 is
// still far above real chat use: it is one attachment every 45 seconds, sustained.
//
// Per-user keyed, and requireAuth mounted BEFORE it for the same reason
// routeLimiter sits behind requireRole — an unauthenticated caller must not be
// able to spend somebody else's bucket on 401s.
const chatAttachmentLimiter = rateLimit({
	windowMs: 15 * 60 * 1000,
	max: (req) => {
		const role = req.session?.user?.role;
		return role === "Super Admin" || role === "Dispatcher" ? 40 : 20;
	},
	keyGenerator: (req) => {
		const id = req.session?.user?.id;
		return id ? `u:${id}` : `ip:${ipKeyGenerator(req.ip)}`;
	},
	message: { error: "Too many attachments. Try again in a few minutes." },
	standardHeaders: true,
});

// POST /api/chat/attachment — Upload file for chat message
app.post("/api/chat/attachment", requireAuth, chatAttachmentLimiter, async (req, res) => {
	try {
		const { fileData, fileName, mimeType } = req.body;
		if (!fileData || !fileName) return res.status(400).json({ error: "fileData and fileName required" });
		if (fileData.length > 13_500_000) return res.status(400).json({ error: "File too large (max 10MB)" });
		if (!validateFileExt(fileName)) return res.status(400).json({ error: "File type not allowed" });
		const attachmentType = (mimeType || '').startsWith('image/') ? 'image' : (mimeType === 'application/pdf' ? 'pdf' : 'other');
		const ext = path.extname(fileName) || (attachmentType === 'image' ? '.jpg' : '.bin');
		const safeName = `chat_${Date.now()}_${Math.random().toString(36).slice(2,7)}${ext}`;
		const chatDir = path.join(__dirname, "uploads", "chat");
		if (!fs.existsSync(chatDir)) fs.mkdirSync(chatDir, { recursive: true });
		const base64 = fileData.replace(/^data:[^;]+;base64,/, "");
		const chatBuf = Buffer.from(base64, "base64");
		// This route is requireAuth ONLY — a Driver can reach it — and it writes
		// into the same inline-served tree, so the bytes get the same check as
		// every other writer. `attachmentType` above is derived from the
		// client-sent mimeType and is a display hint, never evidence.
		const chatErr = verifyInlineServedBytes(chatBuf, path.extname(safeName));
		if (chatErr) return res.status(400).json({ error: chatErr });
		fs.writeFileSync(path.join(chatDir, safeName), chatBuf);
		res.json({ success: true, fileUrl: `/uploads/chat/${safeName}`, attachmentType });
	} catch (err) {
		console.error("Chat attachment error:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// ── Orphaned chat-attachment sweep ─────────────────────────────────────────
// Uploading and SENDING are two steps: POST /api/chat/attachment writes the file
// and hands back a URL, and only a subsequent POST /api/messages records it on a
// row. Abandon the compose box, reload the tab, or navigate away in between, and
// the file stays on disk with no row and no reference, forever. Nothing has ever
// reaped them.
//
// ⚠️ THIS DELETES FILES THAT ARE NOT BACKED UP, WHICH IS WHY IT SHIPS DORMANT.
// `uploads/` is explicitly NOT copied by the nightly backup or the environment
// refresh (see scripts/README-env-refresh.md), so unlike almost everything else
// in this file a wrong delete here is PERMANENT — there is no snapshot to
// restore a driver's POD photo or a broker's attachment from. That inverts the
// usual "a cleanup job is harmless" reasoning, so CHAT_ORPHAN_SWEEP_ENABLED
// defaults OFF and the sweep runs in REPORT-ONLY mode until someone opts in.
// Report-only is not a token gesture: it prints exactly what it would remove and
// how much it would reclaim, so the decision is made on real numbers.
//
// Four independent conditions, ALL required before a byte is removed:
//   1. The file is in uploads/chat/ and its name has the `chat_` prefix that the
//      one writer above produces. The sweep only ever reaps what it knows made.
//   2. Its basename appears in NO messages.attachment_url. Matched on BASENAME,
//      not the whole string, so a stored value that differs by a leading slash
//      or an absolute origin still counts as a reference.
//   3. It is older than CHAT_ORPHAN_MIN_AGE_HOURS (168h = 7 days). This is what
//      makes the race safe: a file uploaded seconds ago whose message row has not
//      been inserted yet is indistinguishable from an orphan, and a user can sit
//      in a compose box for a long time. An age floor costs disk and removes the
//      entire class of "deleted it while they were still typing".
//
//      ⚠️ THE FLOOR IS A WEEK, NOT A DAY, AND THAT IS NOT CAUTION FOR ITS OWN
//      SAKE. client/src/lib/chatAttachment.js MEMOIZES a successful upload on the
//      attachment object and reuses that URL forever, which is deliberate — it is
//      what stops a failed send from re-uploading and orphaning a second copy.
//      The consequence is that an attachment kept on screen after a failed send
//      (also deliberate — losing the user's file is worse) still points at a real
//      URL days later. Under a 24h floor: upload succeeds, the send fails, the
//      tab is left open overnight, the sweep reaps the file, the user hits Send
//      again, and the memo writes a message row pointing at bytes that no longer
//      exist. uploads/ is NOT in the nightly backup, so that is unrecoverable.
//      A week outlives any realistic compose session; the reclaim is a disk
//      optimisation and buying a week of certainty with it costs nothing.
//      The durable fix is for the client to verify the memo (treat a 404 on the
//      stored URL as "not uploaded" and re-upload) — until that lands, this floor
//      is the mitigation, and the flag should stay off without one of the two.
//   4. lstat().isFile() — never stat(). Same rule as purgeOrphanedDbExports():
//      a symlink planted in the tree must not be followed into something else.
//
// FAILS CLOSED. If the reference set cannot be read for ANY reason — an old
// database with no attachment_url column, a locked table, anything — the sweep
// removes NOTHING and says so. Deleting user evidence because a SELECT failed is
// the one outcome worse than never cleaning up at all.
const CHAT_ORPHAN_SWEEP_ENABLED = /^(true|1|yes|on)$/i.test(String(process.env.CHAT_ORPHAN_SWEEP_ENABLED ?? "").trim());
const CHAT_ORPHAN_MIN_AGE_MS =
	Math.max(1, parseInt(process.env.CHAT_ORPHAN_MIN_AGE_HOURS ?? "168", 10) || 168) * 60 * 60 * 1000;

function sweepOrphanedChatAttachments({ apply = false } = {}) {
	const chatDir = path.join(__dirname, "uploads", "chat");
	let removed = 0, orphans = 0, bytes = 0;
	try {
		if (!fs.existsSync(chatDir)) return { removed, orphans, bytes };

		// (2) The reference set, read FIRST and fail-closed. Basenames only.
		let referenced;
		try {
			referenced = new Set(
				db.prepare("SELECT attachment_url FROM messages WHERE COALESCE(attachment_url, '') <> ''").all()
					.map((r) => path.posix.basename(String(r.attachment_url).split("?")[0].replace(/\\/g, "/")))
					.filter(Boolean),
			);
		} catch (e) {
			console.warn(`[chat-cleanup] messages.attachment_url unreadable (${e.message}) — removing nothing this run.`);
			return { removed, orphans, bytes, referenceUnreadable: true };
		}

		const now = Date.now();
		for (const name of fs.readdirSync(chatDir)) {
			if (!name.startsWith("chat_")) continue;          // (1)
			if (referenced.has(name)) continue;               // (2)
			const p = path.join(chatDir, name);
			try {
				const st = fs.lstatSync(p);                     // (4)
				if (!st.isFile()) continue;
				if (now - st.mtimeMs < CHAT_ORPHAN_MIN_AGE_MS) continue; // (3)
				orphans++;
				bytes += st.size;
				if (apply) { fs.unlinkSync(p); removed++; }
			} catch { /* vanished under us, or not ours to touch */ }
		}

		const mb = (bytes / (1024 * 1024)).toFixed(1);
		if (apply && removed > 0) {
			console.log(`[chat-cleanup] removed ${removed} orphaned chat attachment(s), ${mb} MB reclaimed`);
		} else if (!apply && orphans > 0) {
			console.log(
				`[chat-cleanup] REPORT ONLY — ${orphans} orphaned chat attachment(s) older than ` +
				`${Math.round(CHAT_ORPHAN_MIN_AGE_MS / 3600000)}h, ${mb} MB. ` +
				`Set CHAT_ORPHAN_SWEEP_ENABLED=true to reclaim. Note uploads/ is NOT in the nightly backup.`,
			);
		}
	} catch (err) {
		console.error("[chat-cleanup] sweep failed:", err.message);
	}
	return { removed, orphans, bytes };
}

// Delayed at boot (the readdir is synchronous and the documented deploy flow
// pm2-restarts during business hours), then daily. Unlike purgeOrphanedDbExports
// this producer is a LIVE process, so a boot-only sweep would let orphans
// accumulate for however long the process stays up — weeks, on this box.
setTimeout(() => sweepOrphanedChatAttachments({ apply: CHAT_ORPHAN_SWEEP_ENABLED }), 5 * 60 * 1000);
setInterval(() => sweepOrphanedChatAttachments({ apply: CHAT_ORPHAN_SWEEP_ENABLED }), 24 * 60 * 60 * 1000);

// GET /api/investor/onboarding-documents — Investor's signed onboarding docs (Master Agreement, Vehicle Lease, W-9)
app.get("/api/investor/onboarding-documents", requireRole("Super Admin", "Investor"), (req, res) => {
	try {
		const user = req.session.user;
		let investor;
		if (user.role === "Super Admin" && req.query.investor_id) {
			investor = db.prepare("SELECT application_id FROM investors WHERE id = ?").get(parseInt(req.query.investor_id));
		} else {
			investor = db.prepare("SELECT application_id FROM investors WHERE user_id = ?").get(user.id);
		}
		if (!investor || !investor.application_id) return res.json({ documents: [] });
		const docs = db.prepare("SELECT doc_key, doc_name, signed, signature_text, signed_at, signed_pdf_url FROM investor_onboarding_documents WHERE application_id = ? ORDER BY id").all(investor.application_id);
		res.json({ documents: docs });
	} catch (err) {
		res.status(500).json({ error: err.message });
	}
});

// GET /api/investor/documents — All documents for the investor's drivers
app.get("/api/investor/documents", requireRole("Super Admin", "Investor"), async (req, res) => {
	try {
		const preview = resolvePreviewUser(req);
		const user = { ...preview.sessionUser, id: preview.effectiveUserId, username: preview.effectiveUsername };
		const isSuperAdmin = preview.sessionUser.role === "Super Admin" && !preview.isPreview;
		let docs;
		if (isSuperAdmin) {
			docs = db.prepare(
				`SELECT id, load_id, driver, type, file_name, drive_url, strftime('%Y-%m-%dT%H:%M:%SZ', uploaded_at) AS uploaded_at
				 FROM documents WHERE deleted_at IS NULL ORDER BY uploaded_at DESC LIMIT 500`
			).all();
		} else {
			const cdb = getCarrierDBFromSQLite();
			const cDriverCol = findCol(cdb.headers, /driver/i) || cdb.headers[0];
			const cCarrierCol = findCol(cdb.headers, /carrier/i);
			const driverSet = getInvestorDriverSet(user.id, cdb.data, cDriverCol, cCarrierCol);
			if (driverSet.size === 0) return res.json({ documents: [] });
			const drivers = [...driverSet];
			const placeholders = drivers.map(() => '?').join(',');
			docs = db.prepare(
				`SELECT id, load_id, driver, type, file_name, drive_url, strftime('%Y-%m-%dT%H:%M:%SZ', uploaded_at) AS uploaded_at
				 FROM documents WHERE LOWER(driver) IN (${placeholders}) AND deleted_at IS NULL
				 ORDER BY uploaded_at DESC LIMIT 500`
			).all(...drivers);
		}
		res.json({ documents: docs });
	} catch (err) {
		console.error("Error fetching investor documents:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// GET /api/investor/tax-csv — Download tax shield data as CSV
app.get("/api/investor/tax-csv", requireRole("Super Admin", "Investor"), async (req, res) => {
	try {
		const preview = resolvePreviewUser(req);
		const user = { ...preview.sessionUser, id: preview.effectiveUserId, username: preview.effectiveUsername };
		const isSuperAdmin = preview.sessionUser.role === "Super Admin" && !preview.isPreview;

		// Pull investor config for purchase price
		const globalCfg = db.prepare("SELECT key, value FROM investor_config WHERE owner_id = 0").all();
		const config = {};
		globalCfg.forEach(r => (config[r.key] = r.value));
		if (!isSuperAdmin) {
			const investorCfg = db.prepare("SELECT key, value FROM investor_config WHERE owner_id = ?").all(user.id);
			investorCfg.forEach(r => (config[r.key] = r.value));
		}
		const purchasePrice = parseFloat(config.truck_purchase_price || config.purchase_price) || 58000;
		const totalTrucks = isSuperAdmin
			? db.prepare("SELECT COUNT(*) AS cnt FROM trucks").get().cnt
			: db.prepare("SELECT COUNT(*) AS cnt FROM trucks WHERE owner_id = ?").get(user.id).cnt;
		const totalPurchasePrice = purchasePrice * totalTrucks;
		const totalStartupExpenses = 5000 * totalTrucks;
		const section179 = purchasePrice;
		const annualDepreciation = purchasePrice;

		// Net revenue — must succeed; we refuse to fabricate financial figures
		let netRevenueToDate = 0;
		try {
			const sheets = await getSheets();
			const rng = await sheets.spreadsheets.values.batchGet({ spreadsheetId: SPREADSHEET_ID, ranges: ["Job Tracking"] });
			const jt = parseSheet(rng.data.valueRanges[0]);
			const cdb = parseSheet(rng.data.valueRanges[1]);
			const cDriverCol = findCol(cdb.headers, /driver/i) || cdb.headers[0];
			const cCarrierCol = findCol(cdb.headers, /carrier/i);
			const jtRateCol = findCol(jt.headers, /rate|amount|revenue|pay|charge|price|cost/i);
			const jtDriverCol = findCol(jt.headers, /driver/i);
			// Tax revenue counts COMPLETED loads only — match the other
			// financial endpoints; never inflate with dispatched/in-transit.
			const jtStatusCol = findCol(jt.headers, /^(job[\s._-]?)?status$/i) || findCol(jt.headers, /status/i);
			const taxCompletedStatuses = /^(delivered|completed|pod received)$/i;
			let totalRevenue = 0;
			let driverSet = null;
			const taxOwnerId = !isSuperAdmin ? user.id : null;
			if (!isSuperAdmin) {
				driverSet = getInvestorDriverSet(user.id, cdb.data, cDriverCol, cCarrierCol);
			}
			const taxOwnerIdCol = findCol(jt.headers, /^owner.?id$/i);
			jt.data.forEach(r => {
				if (driverSet) {
					let match = false;
					if (taxOwnerIdCol && parseInt(r[taxOwnerIdCol]) === taxOwnerId) match = true;
					if (!match && jtDriverCol) {
						const d = (r[jtDriverCol] || "").trim().toLowerCase();
						if (driverSet.has(d)) match = true;
					}
					if (!match) return;
				}
				if (jtStatusCol && !taxCompletedStatuses.test(String(r[jtStatusCol] || "").trim())) return;
				if (jtRateCol) totalRevenue += parseFloat(String(r[jtRateCol] || "0").replace(/[$,]/g, "")) || 0;
			});
			const expClause = isSuperAdmin
				? db.prepare(`SELECT COALESCE(SUM(amount),0) AS t FROM expenses WHERE ${EXPENSE_PNL_FILTER}`).get().t
				: (() => {
					// Shared scope, so a tax document can never report a different
					// expense total than the portal it was generated from. Note this
					// also drops the old `if (!drivers.length) return 0` early exit,
					// which zeroed expenses outright for an investor whose drivers
					// were all resolved by owner_id alone — a $0 cost line on a TAX
					// form, in the direction that overstates income.
					const scope = investorExpenseScopeSql(user.id, getInvestorDriverMonthWindows(user.id), EXPENSE_PERIOD_EXPR);
					return db.prepare(`SELECT COALESCE(SUM(amount),0) AS t FROM expenses WHERE ${scope.sql} AND ${EXPENSE_PNL_FILTER}`).get(...scope.params).t;
				})();
			netRevenueToDate = Math.round(totalRevenue - expClause);
		} catch (sheetsErr) {
			// Refuse to generate a financial document with fabricated zeros.
			console.error("Tax CSV: sheets fetch failed:", sheetsErr.message);
			return res.status(503).json({
				error: "Unable to generate tax document — financial data source unavailable. Please try again shortly.",
			});
		}

		const atRiskCapital = Math.max(0, (totalPurchasePrice + totalStartupExpenses) - netRevenueToDate);
		const today = new Date().toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });
		const ownerLabel = isSuperAdmin ? "All Investors" : user.username;

		const rows = [
			["LogisX Tax Shield Summary"],
			["Generated", today],
			["Investor", ownerLabel],
			[""],
			["Field", "Value"],
			["Purchase Price (per truck)", `$${purchasePrice.toLocaleString("en-US")}`],
			["Total Trucks", totalTrucks],
			["Total Fleet Purchase Price", `$${totalPurchasePrice.toLocaleString("en-US")}`],
			["Startup Expenses (est. $5,000/truck)", `$${totalStartupExpenses.toLocaleString("en-US")}`],
			["Section 179 Deduction (100%)", `$${section179.toLocaleString("en-US")}`],
			["Annual Depreciation (Year 1)", `$${annualDepreciation.toLocaleString("en-US")}`],
			["Write-Off Percentage", "100%"],
			["Net Revenue to Date", `$${netRevenueToDate.toLocaleString("en-US")}`],
			["At-Risk Capital Remaining", `$${atRiskCapital.toLocaleString("en-US")}`],
			[""],
			["Note", "Section 179 allows 100% first-year deduction of qualifying business property."],
			["Disclaimer", "Consult a licensed tax professional before filing."],
		];

		// Shared escaper (lib/csv.js) — this file goes to an Investor and carries
		// dollar figures, so it gets the same formula-injection guard as every
		// other export rather than the quote-only escaping it used to do.
		const csv = csvRows(rows);
		const filename = `tax-shield-${user.username}-${new Date().toISOString().slice(0, 10)}.csv`;
		res.setHeader("Content-Type", "text/csv");
		res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
		res.send(csv);
	} catch (err) {
		console.error("Tax CSV error:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// GET /api/investor/load-report — Per-period load report for an investor.
// period=weekly (Sat–Fri, via getWeekRange) | monthly. Returns the actual loads
// in each period plus load count and gross revenue (completed loads). Broker /
// customer identity is deliberately NOT exposed here — the investor portal must
// never leak broker contacts. No share is derived from gross: the authoritative
// NET monthly share lives in the dashboard's monthlyEarnings/investorNetToDate.
// For CSV/PDF exports the caller passes ?net=YYYY-MM:amount,... (the per-month net
// investor earnings from monthlyEarnings); each completed load's "Your Share" is
// that month's net allocated proportionally by rate, so the exported rows
// reconcile with the dashboard exactly. Honors ?as_user_id= preview. format=json|csv|pdf.
app.get("/api/investor/load-report", requireRole("Super Admin", "Investor"), async (req, res) => {
	try {
		const period = req.query.period === "weekly" ? "weekly" : "monthly";
		const format = ["csv", "pdf"].includes(req.query.format) ? req.query.format : "json";
		const maxPeriods = Math.min(Math.max(parseInt(req.query.limit) || 12, 1), 53);
		const startBound = (req.query.start || "").toString().trim();   // YYYY-MM-DD inclusive
		const endBound = (req.query.end || "").toString().trim();

		const jobTracking = await getJobTrackingCached();
		const headers = jobTracking.headers;
		const data = excludeDroppedLoads(jobTracking.data, headers);
		const carrierDB = getCarrierDBFromSQLite();

		// Preview ("view as investor") + scoping — mirror /api/investor exactly.
		const preview = resolvePreviewUser(req);
		const user = { ...preview.sessionUser, id: preview.effectiveUserId, username: preview.effectiveUsername };
		const isSuperAdmin = preview.sessionUser.role === "Super Admin" && !preview.isPreview;
		if (preview.isPreview) logAudit(req, "investor_preview_view", "investor", preview.effectiveUserId, "");

		const carrierDriverCol = findCol(carrierDB.headers, /driver/i) || carrierDB.headers[0];
		const carrierCarrierCol = findCol(carrierDB.headers, /carrier/i);
		let investorDriverSet = null;
		const investorOwnerId = !isSuperAdmin ? user.id : null;
		if (!isSuperAdmin) investorDriverSet = getInvestorDriverSet(user.id, carrierDB.data, carrierDriverCol, carrierCarrierCol);

		const cfg = {};
		db.prepare("SELECT key, value FROM investor_config WHERE owner_id = 0").all().forEach((r) => (cfg[r.key] = r.value));
		if (!isSuperAdmin) db.prepare("SELECT key, value FROM investor_config WHERE owner_id = ?").all(user.id).forEach((r) => (cfg[r.key] = r.value));
		const investorSplit = resolveInvestorSplitPct(cfg) / 100;

		const driverCol = findCol(headers, /^driver$/i);
		const ownerIdCol = findCol(headers, /^owner.?id$/i);
		const loadIdCol = findCol(headers, /load.?id|job.?id/i);
		const rateCol = findCol(headers, /payment|rate|amount|revenue/i);
		const dateCol = findCol(headers, /status.*update.*date|completion.*date|assigned.*date/i) || findCol(headers, /date/i);
		const truckCol = findCol(headers, /^truck$|truck[._\s-]?(unit|number|#)|unit[._\s-]?number/i);
		const statusCol = findCol(headers, /status/i);
		const pickupDateCol = findCol(headers, /pickup.*appo|pickup.*date/i);
		const dropoffDateCol = findCol(headers, /drop.?off.*appo|drop.?off.*date|delivery.*date/i);
		const originCol = pickAddressColumn(headers, /origin|pickup|shipper/i);
		const destCol = pickAddressColumn(headers, /dest|drop|receiver|delivery/i);
		const completedStatuses = /^(delivered|completed|pod received)$/i;

		const filtered = investorDriverSet
			? data.filter((r) => {
				if (ownerIdCol) {
					const raw = r[ownerIdCol];
					if (raw !== undefined && raw !== null && String(raw).trim() !== "") return (parseInt(raw) || 0) === investorOwnerId;
				}
				const d = driverCol ? (r[driverCol] || "").trim().toLowerCase() : "";
				return d && investorDriverSet.has(d);
			})
			: data;

		const periodsMap = new Map();
		for (const r of filtered) {
			const lid = loadIdCol ? (r[loadIdCol] || "").trim() : "";
			if (!lid) continue;
			// ⚠️ moneySheetDate(), NOT a local ISO/US-slash parser. This handler used
			// to define its own `parseSheetDate` — ISO + US-slash only, null for
			// anything else — and the `continue` below then dropped the row. The
			// comment said "un-dateable"; the rows were perfectly dateable. n8n copies
			// the rate-con email's own `Date:` header into Assigned Date, so they are
			// RFC 2822 ("Date: Tue, 13 May 2025 11:56:47 -0500"), which that parser
			// could not read. MEASURED READ-ONLY ON PRODUCTION 2026-08-09: 205 of the
			// 421 sheet rows are RFC 2822; after the dedupe + excludeDroppedLoads this
			// route already applies, 106 of 275 eligible rows are — so the report
			// rendered 162 loads and silently hid 105 of them, $68,801 of gross. It
			// was worst in the months that look emptiest: 2025-06/07/09/10/11 each
			// reported $0 gross while holding real delivered loads.
			//
			// NOTHING IS RESTATED, which is why this was safe to change under the
			// no-restatement rule. The settlement math is NOT this route — payouts
			// come from /api/investor's monthlyRevenue, which resolves the SAME column
			// with the SAME regexes through moneySheetDate() already (see the loop by
			// `assignedMonthKey`), so those 105 loads have always been inside the
			// figures. Only the document describing them hid them. This route writes
			// nothing, and "Your Net Result" is passed IN via ?net= from the dashboard
			// rather than derived here. Verified on the same read: 0 rows change their
			// resolved month and 0 change their resolved day — every one of the 105 is
			// an appearance, not a move. The one investor with `paid` payouts (owner 5)
			// owns 0 of them.
			//
			// Do NOT reintroduce a local parser. Two disagreeing resolvers over one
			// column is what produced this bug; moneySheetDate() is the single one.
			const dt = dateCol ? moneySheetDate(r[dateCol]) : null;
			if (!dt || isNaN(dt)) continue; // genuinely un-dateable (blank / non-date text)
			const dayKey = dt.getFullYear() + "-" + String(dt.getMonth() + 1).padStart(2, "0") + "-" + String(dt.getDate()).padStart(2, "0");
			if (startBound && dayKey < startBound) continue;
			if (endBound && dayKey > endBound) continue;
			let key, label, start, end;
			if (period === "weekly") {
				const wr = getWeekRange(dt);
				key = wr.weekStart; start = wr.weekStart; end = wr.weekEnd; label = `${wr.weekStart} to ${wr.weekEnd}`;
			} else {
				key = dt.getFullYear() + "-" + String(dt.getMonth() + 1).padStart(2, "0");
				start = key + "-01"; end = "";
				// `label` is the DISPLAY string and `key` is the identity — they were
				// the same value here, so the investor's period dropdown read
				// "2026-08" directly under a card headed "August 2026". periodLabel()
				// is the one formatter every other month-facing surface already uses
				// (the payout ledger, the statement, the period-lock 409s), so this
				// makes the report agree with them rather than inventing a third form.
				//
				// Display-only and therefore safe: nothing sorts or parses on `label`.
				// Ordering is on `key` (below), the client's selection is on `key`, and
				// the only other consumers are the CSV "Period" column and the PDF
				// heading — both of which read better for it. WEEKLY deliberately
				// keeps its "start to end" range form: a week has no month name, and
				// periodLabel() would return the raw string unchanged anyway.
				label = periodLabel(key);
			}
			if (!periodsMap.has(key)) periodsMap.set(key, { key, label, start, end, loadCount: 0, completedCount: 0, inTransitCount: 0, grossRevenue: 0, loads: [] });
			const bucket = periodsMap.get(key);
			const status = statusCol ? (r[statusCol] || "").trim() : "";
			const gross = parseFloat(String(rateCol ? r[rateCol] : "0").replace(/[$,]/g, "")) || 0;
			const isCompleted = completedStatuses.test(status);
			// loadCount = every load bucketed here (kept for back-compat / CSV).
			// completedCount is the count that shares grossRevenue's basis: gross
			// only sums DELIVERED loads, so surfacing loadCount next to it read as
			// "12 loads earned $20,623" when 3 of those were still in transit.
			bucket.loadCount++;
			if (isCompleted) {
				bucket.completedCount++;
				bucket.grossRevenue += gross;
			} else {
				bucket.inTransitCount++;
			}
			bucket.loads.push({
				loadId: lid, status,
				pickup: resolveCityState(r, "pickup", lid, originCol ? r[originCol] : ""),
				dropoff: resolveCityState(r, "drop", lid, destCol ? r[destCol] : ""),
				truck: truckCol ? (r[truckCol] || "").trim() : "",
				driver: driverCol ? (r[driverCol] || "").trim() : "",
				pickupDate: pickupDateCol ? (r[pickupDateCol] || "") : "",
				dropDate: dropoffDateCol ? (r[dropoffDateCol] || "") : "",
				rate: Math.round(gross),
				completed: isCompleted,
			});
		}

		const periods = [...periodsMap.values()].sort((a, b) => (a.key < b.key ? 1 : -1)).slice(0, maxPeriods);
		periods.forEach((p) => {
			p.grossRevenue = Math.round(p.grossRevenue);
			p.loads.sort((a, b) => (a.loadId < b.loadId ? 1 : -1));
		});

		const investorName = isSuperAdmin
			? "All Investors"
			: (((db.prepare("SELECT full_name FROM investors WHERE user_id = ?").get(user.id) || {}).full_name) || user.username || "Investor");
		const splitPct = Math.round(investorSplit * 100);

		// Authoritative per-month NET investor earnings, supplied by the client from
		// the dashboard's monthlyEarnings as ?net=YYYY-MM:amount,... Used only to
		// render CSV/PDF exports so the document reconciles with the investor
		// dashboard. No gross-based share is ever computed or shown.
		const netByMonth = {};
		String(req.query.net || "").split(",").forEach((pair) => {
			const idx = pair.indexOf(":");
			if (idx <= 0) return;
			const k = pair.slice(0, idx).trim();
			const amt = parseFloat(pair.slice(idx + 1));
			if (/^\d{4}-\d{2}$/.test(k) && Number.isFinite(amt)) netByMonth[k] = amt;
		});
		const periodNet = (p) => (Object.prototype.hasOwnProperty.call(netByMonth, p.key) ? netByMonth[p.key] : null);
		// Allocate a period's net investor earnings across its completed loads,
		// rate-weighted, as whole dollars that sum EXACTLY to the period net
		// (largest-remainder method) so the rows reconcile with the stated total.
		// Returns {} (→ no share shown) when no net is known, e.g. the weekly view.
		// Mirrors allocateNet() in client LoadReportsSection.vue — keep in sync.
		const allocateNet = (loads, net) => {
			const out = {};
			if (net == null) return out;
			const done = loads.filter((l) => l.completed && (l.rate || 0) > 0);
			const denom = done.reduce((s, l) => s + l.rate, 0);
			if (denom <= 0) return out;
			const target = Math.round(net);
			let allocated = 0;
			const rema = [];
			for (const l of done) {
				const exact = (target * l.rate) / denom;
				const base = Math.floor(exact);
				out[l.loadId] = base;
				allocated += base;
				rema.push({ id: l.loadId, f: exact - base });
			}
			let leftover = target - allocated; // 0 <= leftover < done.length
			rema.sort((a, b) => b.f - a.f);
			for (let i = 0; i < rema.length && leftover > 0; i++, leftover--) out[rema[i].id] += 1;
			return out;
		};

		if (format === "json") {
			return res.json({ periodType: period, splitPct, investorName, periods });
		}

		if (format === "csv") {
			// Shared escaper (lib/csv.js). This one matters most of the four: the
			// pickup/dropoff/driver/status cells originate in broker-supplied rate
			// con PDFs parsed by n8n/Gemini — attacker-influenceable text — and the
			// reader is an Investor, so a `=HYPERLINK(...)` smuggled through a
			// shipper name would fire in their spreadsheet. Quote-only escaping
			// (what this used to do) does not stop that.
			const lines = [["Period", "Start", "End", "Load ID", "Status", "Pickup", "Dropoff", "Truck", "Driver", "Pickup Date", "Drop Date", "Rate", "Completed", "Your Net Result (net)"]];
			for (const p of periods) {
				const shares = allocateNet(p.loads, periodNet(p));
				for (const l of p.loads) {
					const ns = Object.prototype.hasOwnProperty.call(shares, l.loadId) ? shares[l.loadId] : null;
					lines.push([p.label, p.start, p.end, l.loadId, l.status, l.pickup, l.dropoff, l.truck, l.driver, l.pickupDate, l.dropDate, l.rate, l.completed ? "Yes" : "No", ns == null ? "" : ns]);
				}
			}
			res.setHeader("Content-Type", "text/csv");
			res.setHeader("Content-Disposition", `attachment; filename="load-report-${period}.csv"`);
			return res.send(csvRows(lines));
		}

		// format === "pdf"
		const PDFDocument = require("pdfkit");
		const doc = new PDFDocument({ margin: 40, size: "LETTER" });
		const chunks = [];
		doc.on("data", (c) => chunks.push(c));
		doc.on("end", () => {
			res.setHeader("Content-Type", "application/pdf");
			res.setHeader("Content-Disposition", `attachment; filename="load-report-${period}.pdf"`);
			res.send(Buffer.concat(chunks));
		});
		doc.fontSize(18).fillColor("#0f172a").text(`${period === "weekly" ? "Weekly" : "Monthly"} Load Report`);
		doc.moveDown(0.2).fontSize(10).fillColor("#475569").text(investorName);
		doc.fontSize(8).fillColor("#94a3b8").text(`"Your Net Result" is your net investor earnings — gross minus driver pay, fuel and fixed costs — reconciled with the totals on your investor dashboard. Generated by LogisX.`);
		doc.moveDown(0.6);

		// Fixed-column table so the statement reads cleanly (widths sum to the
		// 532pt LETTER content area). Single-line rows (clip + no wrap) keep columns
		// aligned; rows page-break safely.
		const money = (n) => "$" + Math.round(Number(n) || 0).toLocaleString();
		const L = doc.page.margins.left;
		const cols = [
			{ key: "load", x: L, w: 66 },
			{ key: "status", x: L + 66, w: 78 },
			{ key: "route", x: L + 144, w: 218 },
			{ key: "rate", x: L + 362, w: 75, align: "right" },
			{ key: "share", x: L + 437, w: 95, align: "right" },
		];
		const ROW_H = 13;
		const bottom = () => doc.page.height - doc.page.margins.bottom;
		const clip = (s, n) => { s = String(s == null ? "" : s); return s.length > n ? s.slice(0, n - 1) + "…" : s; };
		const row = (cells, { color = "#334155", size = 8, bold = false } = {}) => {
			if (doc.y + ROW_H > bottom()) doc.addPage();
			const y = doc.y;
			doc.font(bold ? "Helvetica-Bold" : "Helvetica").fontSize(size).fillColor(color);
			for (const c of cols) {
				doc.text(cells[c.key] == null ? "" : String(cells[c.key]), c.x, y, { width: c.w, align: c.align || "left", lineBreak: false, ellipsis: true });
			}
			doc.font("Helvetica").x = L;
			doc.y = y + ROW_H;
		};

		for (const p of periods) {
			const net = periodNet(p);
			const shares = allocateNet(p.loads, net);
			if (doc.y + 46 > bottom()) doc.addPage();
			doc.moveDown(0.5).font("Helvetica-Bold").fontSize(12).fillColor("#0f172a").text(p.label, L);
			const shareTxt = net == null ? "" : `   ·   Your share (net) ${money(net)}`;
			// Count the DELIVERED loads next to Gross — they share the same basis.
			// In-transit loads are listed in the rows below but earn nothing yet.
			const transitTxt = p.inTransitCount ? ` (+${p.inTransitCount} in transit)` : "";
			doc.font("Helvetica").fontSize(9).fillColor("#475569").text(`${p.completedCount} delivered${transitTxt}   ·   Gross ${money(p.grossRevenue)}${shareTxt}`, L);
			doc.moveDown(0.4);
			row({ load: "LOAD", status: "STATUS", route: "ROUTE", rate: "RATE", share: "YOUR SHARE" }, { color: "#94a3b8", size: 7, bold: true });
			if (!p.loads.length) { doc.fontSize(8).fillColor("#94a3b8").text("No loads in this period.", L); continue; }
			for (const l of p.loads) {
				const ns = Object.prototype.hasOwnProperty.call(shares, l.loadId) ? shares[l.loadId] : null;
				row({
					load: l.loadId,
					status: clip(l.status, 16),
					route: clip(`${l.pickup || "?"} -> ${l.dropoff || "?"}`, 46),
					rate: money(l.rate),
					share: ns == null ? "—" : money(ns),
				});
			}
		}
		if (!periods.length) doc.moveDown().fontSize(11).fillColor("#94a3b8").text("No loads found for this investor in the selected range.");
		doc.end();
	} catch (error) {
		console.error("Investor load-report error:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// GET /api/investor/report — Generate PDF performance report
app.get("/api/investor/report", requireRole("Super Admin", "Investor"), async (req, res) => {
	try {
		// Re-use the investor data by making an internal call
		const preview = resolvePreviewUser(req);
		const user = { ...preview.sessionUser, id: preview.effectiveUserId, username: preview.effectiveUsername };
		const isSuperAdmin = preview.sessionUser.role === "Super Admin" && !preview.isPreview;
		if (preview.isPreview) logAudit(req, "investor_preview_report", "investor", preview.effectiveUserId, "");

		// Fetch the same investor data inline (mirrors /api/investor logic summary)
		const sheets = await getSheets();
		const response = await sheets.spreadsheets.values.get({
			spreadsheetId: SPREADSHEET_ID,
			range: "Job Tracking",
		});
		const jobTracking = parseSheet(response.data);
		jobTracking.data = deduplicateLoads(jobTracking.data, jobTracking.headers);
		const rptCarrierDB = getCarrierDBFromSQLite();
		const rptCDriverCol = findCol(rptCarrierDB.headers, /driver/i) || rptCarrierDB.headers[0];
		const rptCCarrierCol = findCol(rptCarrierDB.headers, /carrier/i);

		let investorDriverSet = null;
		const reportOwnerId = !isSuperAdmin ? user.id : null;
		if (!isSuperAdmin) {
			investorDriverSet = getInvestorDriverSet(user.id, rptCarrierDB.data, rptCDriverCol, rptCCarrierCol);
		}

		const globalCfg = db.prepare("SELECT key, value FROM investor_config WHERE owner_id = 0").all();
		const config = {};
		globalCfg.forEach(r => (config[r.key] = r.value));
		if (!isSuperAdmin) {
			db.prepare("SELECT key, value FROM investor_config WHERE owner_id = ?").all(user.id)
				.forEach(r => (config[r.key] = r.value));
		}

		// Date range filter (RFD-26)
		const filterStart = req.query.start ? new Date(req.query.start) : null;
		const filterEnd = req.query.end ? new Date(req.query.end + 'T23:59:59') : null;

		const driverCol = findCol(jobTracking.headers, /^driver$/i);
		const rptOwnerIdCol = findCol(jobTracking.headers, /^owner.?id$/i);
		const jtDateColR = findCol(jobTracking.headers, /status.*update.*date|completion.*date|assigned.*date/i) || findCol(jobTracking.headers, /date/i);
		const filteredJobData = (investorDriverSet
			? jobTracking.data.filter(r => {
				// Same rule as /api/investor: an EXPLICIT Owner ID (including "0") is
				// trusted; only an EMPTY cell falls back to driver-name matching.
				if (rptOwnerIdCol) {
					const raw = r[rptOwnerIdCol];
					const hasOwnerIdValue = raw !== undefined && raw !== null && String(raw).trim() !== "";
					if (hasOwnerIdValue) {
						return (parseInt(raw) || 0) === reportOwnerId;
					}
				}
				const d = driverCol ? (r[driverCol] || "").trim().toLowerCase() : "";
				return d && investorDriverSet.has(d);
			}) : jobTracking.data
		).filter(r => {
			if (!filterStart && !filterEnd) return true;
			const d = jtDateColR ? new Date(r[jtDateColR]) : null;
			if (!d || isNaN(d)) return false;
			if (filterStart && d < filterStart) return false;
			if (filterEnd && d > filterEnd) return false;
			return true;
		});

		const jtRateCol2 = findCol(jobTracking.headers, /payment|rate|amount|revenue/i);
		const jtDateCol2 = findCol(jobTracking.headers, /status.*update.*date|completion.*date|assigned.*date/i) || findCol(jobTracking.headers, /date/i);
		const rptStatusCol = findCol(jobTracking.headers, /status/i);
		const rptCompletedStatuses = /^(delivered|completed|pod received)$/i;

		// Only count revenue from rows in a completed status (delivered,
		// completed, pod received) — matches the investor dashboard logic
		// so the PDF and the dashboard always show the same totalRevenue.
		// Prior semantic also counted dispatched/in-transit rows, creating
		// a confusing gap between the two surfaces.
		let totalRevenue = 0;
		filteredJobData.forEach(r => {
			const amt = parseFloat(String((jtRateCol2 ? r[jtRateCol2] : "0")).replace(/[$,]/g, "")) || 0;
			if (!amt) return;
			const st = rptStatusCol ? (r[rptStatusCol] || "").trim() : "";
			if (rptCompletedStatuses.test(st)) totalRevenue += amt;
		});

		// Fleet purchase price — sum actual trucks.purchase_price column.
		// Was previously hardcoded to $58,000 via config.truck_purchase_price
		// fallback, which was wrong once real purchase prices were entered
		// in the trucks table. Per 2026-04-13 client feedback.
		const ownedTrucks2 = isSuperAdmin
			? db.prepare("SELECT * FROM trucks").all()
			: db.prepare("SELECT * FROM trucks WHERE owner_id = ?").all(user.id);
		const totalTrucks = ownedTrucks2.length || 1;
		const totalPurchasePrice = ownedTrucks2.reduce((sum, t) => sum + (t.purchase_price || 0), 0);
		// "Per truck" shows the single value for a one-truck fleet and the
		// average for multi-truck fleets (same pattern as /api/investor).
		const purchasePrice = ownedTrucks2.length === 1
			? (ownedTrucks2[0].purchase_price || 0)
			: (totalTrucks > 0 ? Math.round(totalPurchasePrice / totalTrucks) : 0);
		const totalStartupExpenses = 5000 * totalTrucks;
		const currentValue = Math.round(totalPurchasePrice * 0.80);

		// Helper: how many months does this truck appear in the report period?
		// - With a date range: clamp to the range, bounded by the in-service date
		// - All-time: from the truck's in-service date to now
		// - Missing both dates (legacy data): fall back to the fleet-wide
		//   earliest created_at, or to 1 month as a floor
		const reportNow = new Date();
		const fleetEarliestCreated = ownedTrucks2
			.map(t => (t.created_at ? new Date(t.created_at) : null))
			.filter(d => d && !isNaN(d))
			.reduce((min, d) => (min === null || d < min ? d : min), null);
		function truckMonthsInPeriod(t) {
			const createdAt = t.created_at ? new Date(t.created_at) : null;
			// Same precedence and same start MONTH as truckChargeFromMonth
			// (in_service_date first, else created_at) — but this site clamps
			// against a caller-supplied date range, so it needs day granularity
			// and builds a Date instead of consuming the helper's 'YYYY-MM'.
			// Parsed component-wise on purpose: new Date('2026-08-01') is UTC
			// midnight = 2026-07-31 19:00 in Houston, which would pull the truck
			// back into the previous month. See truckChargeFromMonth.
			const inService = String(t.in_service_date || "").trim();
			const inServiceDate = /^\d{4}-\d{2}-\d{2}$/.test(inService)
				? new Date(parseInt(inService.slice(0, 4), 10), parseInt(inService.slice(5, 7), 10) - 1, parseInt(inService.slice(8, 10), 10))
				: null;
			const truckStart = inServiceDate || ((createdAt && !isNaN(createdAt))
				? createdAt
				: fleetEarliestCreated); // legacy data fallback
			// The retirement end, built the same component-wise way and for the same
			// UTC-midnight reason. null = never retired = no upper bound (see
			// truckChargeUntilMonth: "" must never read as "retired long ago").
			// ⚠️ This site is the reason retired_at is a DATE rather than a bare
			// month: it clamps against a caller-supplied range with DAY granularity,
			// so a month-only column would force an invented day here — and an
			// unstated "last day of the month" convention is exactly the kind of
			// thing that drifts away from the month gates.
			const retired = String(t.retired_at || "").trim();
			const retiredDate = /^\d{4}-\d{2}-\d{2}$/.test(retired)
				? new Date(parseInt(retired.slice(0, 4), 10), parseInt(retired.slice(5, 7), 10) - 1, parseInt(retired.slice(8, 10), 10))
				: null;
			let start, end;
			if (filterStart || filterEnd) {
				start = filterStart || truckStart || reportNow;
				end = filterEnd || reportNow;
			} else {
				start = truckStart || reportNow;
				end = reportNow;
			}
			// If the truck entered service after the period ended, zero months.
			if (truckStart && filterEnd && truckStart > filterEnd) return 0;
			// Mirror image: if it was retired before the period began, zero months.
			if (retiredDate && filterStart && retiredDate < filterStart) return 0;
			// Clamp start to the truck's service start.
			if (truckStart && start < truckStart) start = truckStart;
			// ...and the end to its retirement. Inclusive of the retirement MONTH,
			// matching truckChargedInMonth — the month arithmetic below counts whole
			// months, so a truck retired mid-month still bills that month in full.
			if (retiredDate && end > retiredDate) end = retiredDate;
			if (end < start) return 0;
			const months = (end.getFullYear() - start.getFullYear()) * 12
				+ (end.getMonth() - start.getMonth()) + 1;
			return Math.max(1, months);
		}

		let totalExpenses = 0;
		let fuelExpenses = 0, maintenanceExpenses = 0, complianceExpenses = 0, truckPaymentExpenses = 0, insuranceExpenses = 0, otherExpenses = 0;
		// Parameterized date filters (avoid string interpolation in SQL)
		let dateWhere = '';
		const dateParams = [];
		if (filterStart) { dateWhere += ' AND date >= ?'; dateParams.push(filterStart.toISOString().slice(0, 10)); }
		if (filterEnd) { dateWhere += ' AND date <= ?'; dateParams.push(filterEnd.toISOString().slice(0, 10)); }

		// Itemized trip expenses by type — runs for both Super Admin and Investor.
		// Investor: scoped by the SHARED builder. Super Admin: no scope at all
		// (aggregate everything). Previously this block was gated on
		// investorDriverSet being populated, which silently zeroed all expense
		// lines on Super Admin reports.
		//
		// ⚠️ THIS WAS THE SEVENTH SITE, AND IT WAS STILL ON THE PRE-FIX SHAPE.
		// It hand-rolled ` AND LOWER(driver) IN (<the live driver set>)` — the exact
		// predicate investorExpenseScopeSql() exists to replace — so it carried the
		// whole 2026-08-13 bug on its own: getInvestorDriverSet() is present-tense,
		// has no clock and no owner_id leg, so the moment a driver was reassigned
		// onto an investor's truck his ENTIRE expense history (filed on someone
		// else's truck, stamped owner_id = 0 at insert) landed in this investor's
		// downloadable P&L. Measured on production for owner 5: $40,761.24 against a
		// correctly-scoped $19,553.93 — $21,207.31 of another owner's costs, in a
		// document the investor keeps. The six other callers were fixed; this one is
		// ~500 lines away from them and was missed, which is precisely the
		// DRIVER_RENAME_TARGETS lesson the shared builder was written for.
		//
		// It also failed OPEN in a second way: `investorDriverSet.size > 0` meant an
		// investor whose driver set came back EMPTY got no filter whatsoever and was
		// shown the entire fleet's expenses. Scoping on the owner id instead can only
		// ever narrow — the worst case is `owner_id = ?` alone.
		//
		// ⚠️ EXPENSE_PERIOD_EXPR goes to the BUILDER; `dateWhere` stays on plain
		// `date`. That is the settlement-vs-operational split: the driver windows
		// bound the month a row SETTLES in (posted_period wins), while the report's
		// own caller-supplied range is a question about the world — which purchases
		// fall between these two dates — and has always read the true purchase date.
		// Mixing the two bases would put a prior-period adjustment in one month for
		// the filter and another for the sum.
		{
			// reportOwnerId is null for a real Super Admin and the previewed
			// investor's users.id under ?as_user_id= — the handler's own single
			// notion of "whose report is this", reused rather than re-derived.
			// Tested `!== null`, never truthiness: this repo has already been bitten
			// by a falsy-0 read of a configured value (resolveInvestorSplitPct).
			let scopeSql = '1=1';
			const scopeParams = [];
			if (reportOwnerId !== null) {
				const scope = investorExpenseScopeSql(reportOwnerId, getInvestorDriverMonthWindows(reportOwnerId), EXPENSE_PERIOD_EXPR);
				scopeSql = scope.sql;
				scopeParams.push(...scope.params);
			}
			const expRows = db.prepare(
				`SELECT LOWER(type) AS t, COALESCE(SUM(amount),0) AS total FROM expenses WHERE ${scopeSql}${dateWhere} AND ${EXPENSE_PNL_FILTER} GROUP BY LOWER(type)`
			).all(...scopeParams, ...dateParams);
			// Categorization per 2026-04-13 client feedback:
			// - Fuel → Fuel Expenses
			// - Repair / Maintenance / Tire / Oil → Maintenance & Repairs
			// - Everything else (Wear & Tear, Toll, Food, Other) → Other Expenses
			expRows.forEach(r => {
				if (/fuel/i.test(r.t)) fuelExpenses += r.total;
				else if (/maint|repair|tire|oil/i.test(r.t)) maintenanceExpenses += r.total;
				else otherExpenses += r.total;
				totalExpenses += r.total;
			});
		}

		// Maintenance fund disbursements (truck-level service payments) —
		// joined to trucks so inactive-truck disbursements drop out.
		// Super-Admin path uses NOT IN so orphan rows (where `truck` doesn't
		// match any truck) still appear in the global total.
		{
			const maintTotal = (investorDriverSet
				? db.prepare(`SELECT COALESCE(SUM(mf.amount),0) AS t FROM maintenance_fund mf INNER JOIN trucks t ON LOWER(mf.truck)=LOWER(t.unit_number) WHERE t.owner_id=? AND t.status='Active' AND mf.type='service'`).get(user.id)
				: db.prepare(`SELECT COALESCE(SUM(amount),0) AS t FROM maintenance_fund WHERE type='service' AND LOWER(truck) NOT IN (SELECT LOWER(unit_number) FROM trucks WHERE status != 'Active')`).get()
			).t;
			maintenanceExpenses += maintTotal;
			totalExpenses += maintTotal;
		}

		// Compliance / Regulatory = truck fixed costs (ELD + HVUT/12 + IRP/12)
		// per month, multiplied by the number of months each truck was active
		// in the report period. PLUS any manually-logged compliance_fees rows.
		// Per 2026-04-13 client feedback: "Compliance/Regulatory is the ELD,
		// HVUT, IRP added up and divided by 12 months which is part of the
		// fixed expenses. On run report period it needs to show this month
		// per month."
		//
		// ⚠️ INSURANCE IS ITS OWN LINE, AND IT WAS MISSING FROM THIS REPORT
		// ENTIRELY UNTIL 2026-08-14 — not mis-bucketed, absent. A grep for
		// `insurance` across this whole handler returned zero hits, so the
		// statement's Total Expenses understated by the full insurance accrual:
		// $1,630 + $1,630 + $1,520 + $1,680 = $6,460/month fleet-wide, against
		// which /api/investor and the payouts ledger both bill it. An investor
		// comparing the downloadable P&L to their portal saw two different
		// numbers, and the report was the flattering one.
		//
		// It does NOT go in Compliance: the client defined that bucket as
		// exactly ELD + HVUT + IRP, and quietly widening a category they named
		// is how the next reconciliation argument starts. It gets the same
		// treatment truck_payment_monthly already got — its own P&L row.
		{
			// Skip inactive trucks for projected fixed-cost accrual.
			// Asset Security section above still shows them (the investor
			// owns them); they just don't contribute compliance expense.
			for (const t of ownedTrucks2) {
				if (t.status !== "Active") continue;
				const months = truckMonthsInPeriod(t);
				// Shared per-truck math, so this statement and the portal can no
				// longer disagree about what a truck costs per month. The five
				// parts are then bucketed into the client's named categories.
				const f = truckMonthlyFixed(t);
				const truckFixed = (f.eld + f.hvut + f.irp) * months;
				complianceExpenses += truckFixed;
				totalExpenses += truckFixed;
				// Truck loan/lease payment — a fixed monthly cost, shown as its own
				// P&L line (not lumped into Compliance). Split out of the ELD fee.
				const truckPay = f.truckPayment * months;
				truckPaymentExpenses += truckPay;
				totalExpenses += truckPay;
				const truckIns = f.insurance * months;
				insuranceExpenses += truckIns;
				totalExpenses += truckIns;
			}
			const compFees = (investorDriverSet
				? db.prepare(`SELECT COALESCE(SUM(cf.amount),0) AS t FROM compliance_fees cf INNER JOIN trucks t ON LOWER(cf.truck)=LOWER(t.unit_number) WHERE t.owner_id=? AND t.status='Active' AND cf.status='Paid'`).get(user.id)
				: db.prepare(`SELECT COALESCE(SUM(amount),0) AS t FROM compliance_fees WHERE status='Paid' AND LOWER(truck) NOT IN (SELECT LOWER(unit_number) FROM trucks WHERE status != 'Active')`).get()
			).t;
			complianceExpenses += compFees;
			totalExpenses += compFees;
		}

		// Round category totals AFTER all sources have been summed, then
		// derive totalExpenses from the ROUNDED categories so the P&L adds
		// up exactly — otherwise independent rounding can drift by $1-2.
		fuelExpenses = Math.round(fuelExpenses);
		maintenanceExpenses = Math.round(maintenanceExpenses);
		complianceExpenses = Math.round(complianceExpenses);
		truckPaymentExpenses = Math.round(truckPaymentExpenses);
		insuranceExpenses = Math.round(insuranceExpenses);
		otherExpenses = Math.round(otherExpenses);
		totalExpenses = fuelExpenses + maintenanceExpenses + complianceExpenses + truckPaymentExpenses + insuranceExpenses + otherExpenses;

		const netRevenueToDate = Math.round(totalRevenue - totalExpenses);
		const netCashFlow = totalRevenue - totalExpenses;
		// ⚠️ Was a hardcoded 0.5 with a hardcoded "(50%)" label, in two places, on
		// a statement whose whole job is to agree with the portal. `config` above
		// already merges the per-investor investor_config over the global row, and
		// /api/investor reads investor_split_pct from exactly that — so a
		// non-50 investor got a report that silently paid them at 50 and said so.
		// A no-op at today's config (every investor is 50), which is precisely why
		// it would have gone unnoticed until the first investor on a different split.
		// `|| 50` matches the portal's own fallback rather than inventing a second.
		const splitPctLabel = resolveInvestorSplitPct(config);
		const ownerEarnings = netCashFlow * (splitPctLabel / 100);

		// Monthly revenue from Job Tracking
		const monthlyRevenue2 = {};
		if (jtDateCol2 && jtRateCol2) {
			filteredJobData.forEach(r => {
				const amt = parseFloat(String((r[jtRateCol2] || "0")).replace(/[$,]/g, "")) || 0;
				if (!amt) return;
				const d = new Date(r[jtDateCol2]);
				if (!isNaN(d)) {
					const key = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`;
					monthlyRevenue2[key] = (monthlyRevenue2[key] || 0) + amt;
				}
			});
		}
		const monthlyData2 = Object.entries(monthlyRevenue2)
			.sort(([a],[b]) => a.localeCompare(b))
			.map(([month, amount]) => ({ month, amount: Math.round(amount) }));

		const completedStatuses = /^(delivered|completed|pod received)$/i;
		const statusCol2 = findCol(jobTracking.headers, /status/i);
		const completedJobs = statusCol2 ? filteredJobData.filter(r => completedStatuses.test((r[statusCol2]||"").trim())).length : 0;

		// Build PDF
		const PDFDocument = require("pdfkit");
		const doc = new PDFDocument({ margin: 50, size: "LETTER" });
		const chunks = [];
		doc.on("data", c => chunks.push(c));

		const fmt = n => "$" + Number(n||0).toLocaleString("en-US", { maximumFractionDigits: 0 });
		const dateStr = new Date().toLocaleDateString("en-US", { weekday:"long", year:"numeric", month:"long", day:"numeric" });
		const investorName = isSuperAdmin ? "Super Admin" : user.username;
		const periodStr = filterStart || filterEnd
			? `Period: ${filterStart ? filterStart.toLocaleDateString("en-US") : "All"} – ${filterEnd ? filterEnd.toLocaleDateString("en-US") : "Today"}`
			: "All-time";

		// ── Header
		doc.rect(0, 0, doc.page.width, 80).fill("#0f3460");
		doc.fillColor("#ffffff").fontSize(22).font("Helvetica-Bold")
			.text(`${investorName} — Asset Dashboard`, 50, 18);
		doc.fontSize(10).font("Helvetica").fillColor("rgba(255,255,255,0.7)")
			.text(`Performance Report  ·  ${dateStr}`, 50, 45);
		doc.fontSize(9).fillColor("rgba(255,255,255,0.5)")
			.text(periodStr, 50, 62);
		doc.moveDown(3).fillColor("#000000");

		// ── Helper: section header
		const sectionHeader = (title) => {
			doc.moveDown(0.5)
				.rect(50, doc.y, doc.page.width - 100, 22).fill("#e8f4fd")
				.fillColor("#0f3460").fontSize(11).font("Helvetica-Bold")
				.text(title, 58, doc.y - 17)
				.fillColor("#333333").font("Helvetica").fontSize(10)
				.moveDown(0.8);
		};

		// ── Helper: two-column KPI row
		const kpiRow = (label, value, label2, value2) => {
			const y = doc.y;
			doc.font("Helvetica-Bold").fontSize(9).fillColor("#666").text(label.toUpperCase(), 50, y, { width: 200 });
			doc.font("Helvetica-Bold").fontSize(13).fillColor("#0f3460").text(value, 50, y + 11, { width: 200 });
			if (label2) {
				doc.font("Helvetica-Bold").fontSize(9).fillColor("#666").text(label2.toUpperCase(), 280, y, { width: 200 });
				doc.font("Helvetica-Bold").fontSize(13).fillColor("#0f3460").text(value2 || "—", 280, y + 11, { width: 200 });
			}
			doc.moveDown(1.8);
		};

		// ── Production
		sectionHeader("Production Performance");
		const avgPerLoad = completedJobs > 0 ? totalRevenue / completedJobs : 0;
		kpiRow("Total Revenue", fmt(totalRevenue), "Avg Revenue / Load", fmt(avgPerLoad));
		kpiRow("Completed Loads", String(completedJobs), "Total Jobs", String(filteredJobData.length));

		// ── Asset
		sectionHeader("Asset Security");
		kpiRow("Purchase Price (per truck)", fmt(purchasePrice), "Current Market Value (80%)", fmt(currentValue));
		kpiRow("Fleet Size", String(totalTrucks), "Total Purchase Price", fmt(totalPurchasePrice));
		kpiRow("Title Status", config.truck_title_status || "Clean", "Depreciation", "100% Year 1 (Sec. 179)");

		// ── Cash Flow
		sectionHeader("Cash Flow & Projections");
		kpiRow("Net Cash Flow", fmt(netCashFlow), `Owner Earnings (${splitPctLabel}%)`, fmt(ownerEarnings));
		kpiRow("Total Expenses", fmt(totalExpenses), "Net Revenue To Date", fmt(netRevenueToDate));
		const totalInv = totalPurchasePrice + totalStartupExpenses;
		const recPct = totalInv > 0 ? Math.min(100, (netRevenueToDate / totalInv * 100)).toFixed(1) : "0";
		kpiRow("Total Investment", fmt(totalInv), "Payoff Progress", `${recPct}%`);
		const roiPct = totalRevenue > 0 ? (netRevenueToDate / totalRevenue * 100).toFixed(1) : "0";
		kpiRow("Business ROI", `${roiPct}%`, "Section 179 Deduction", fmt(purchasePrice));

		// ── P&L Statement (RFD-26)
		// Helper: add a page break if the next line wouldn't fit above the
		// footer. Fixes the "Total Expenses" orphan + gap bug where the loop
		// used to let pdfkit split a row across pages, leaving a huge blank
		// space on page 2. Per 2026-04-13 client feedback.
		const footerSafety = 60;
		const ensureSpace = (needed) => {
			if (doc.y + needed > doc.page.height - footerSafety) {
				doc.addPage();
			}
		};
		sectionHeader("Income Statement (Profit & Loss)");
		const plLines = [
			{ label: "Gross Revenue", value: fmt(totalRevenue), indent: false, bold: true },
			{ label: "  Fuel Expenses", value: `(${fmt(fuelExpenses)})`, indent: true, bold: false },
			{ label: "  Maintenance & Repairs", value: `(${fmt(maintenanceExpenses)})`, indent: true, bold: false },
			{ label: "  Insurance", value: `(${fmt(insuranceExpenses)})`, indent: true, bold: false },
			{ label: "  Compliance / Regulatory", value: `(${fmt(complianceExpenses)})`, indent: true, bold: false },
			{ label: "  Truck Payment", value: `(${fmt(truckPaymentExpenses)})`, indent: true, bold: false },
			{ label: "  Other Expenses", value: `(${fmt(otherExpenses)})`, indent: true, bold: false },
			{ label: "Total Expenses", value: `(${fmt(totalExpenses)})`, indent: false, bold: false },
			{ label: "Net Profit", value: fmt(netCashFlow), indent: false, bold: true },
			{ label: `Investor Payout (${splitPctLabel}%)`, value: fmt(ownerEarnings), indent: false, bold: true },
		];
		const plLineHeight = 18;
		const plX = 50, plW = doc.page.width - 100;
		plLines.forEach((line, i) => {
			if (i === plLines.length - 3) { // separator before net profit
				// Keep the separator AND the following three bold rows together
				// so they don't split across pages.
				ensureSpace(plLineHeight * 3 + 10);
				doc.moveTo(plX, doc.y).lineTo(plX + plW, doc.y).strokeColor("#cccccc").stroke();
				doc.moveDown(0.3);
			} else {
				ensureSpace(plLineHeight);
			}
			const y = doc.y;
			doc.font(line.bold ? "Helvetica-Bold" : "Helvetica").fontSize(10).fillColor(line.indent ? "#555555" : "#000000")
				.text(line.label, plX + (line.indent ? 15 : 0), y, { width: plW - 80 })
				.font(line.bold ? "Helvetica-Bold" : "Helvetica").fillColor(line.bold ? "#0f3460" : "#333333")
				.text(line.value, plX + plW - 80, y, { width: 80, align: "right" });
			// Force consistent line spacing regardless of pdfkit's per-text
			// auto-advance, so ensureSpace() math stays predictable.
			doc.y = y + plLineHeight;
		});
		doc.moveDown(0.5);

		// ── Monthly Revenue Table
		if (monthlyData2.length > 0) {
			// Keep the section header + header row + first data row together.
			// sectionHeader ~52pt + 18pt header row + 16pt data row = 86pt.
			ensureSpace(90);
			sectionHeader("Monthly Revenue");
			const colW = [120, 100];
			const tableX = 50;
			let ty = doc.y;
			doc.rect(tableX, ty, colW[0] + colW[1], 18).fill("#e8f4fd");
			doc.fillColor("#0f3460").font("Helvetica-Bold").fontSize(9)
				.text("Month", tableX + 5, ty + 5, { width: colW[0] })
				.text("Revenue", tableX + colW[0] + 5, ty + 5, { width: colW[1] });
			ty += 18;
			monthlyData2.forEach((m, i) => {
				if (ty > doc.page.height - footerSafety) { doc.addPage(); ty = 50; }
				doc.rect(tableX, ty, colW[0] + colW[1], 16).fill(i % 2 === 0 ? "#ffffff" : "#f8f9fa");
				doc.fillColor("#333333").font("Helvetica").fontSize(9)
					.text(m.month, tableX + 5, ty + 4, { width: colW[0] })
					.text(fmt(m.amount), tableX + colW[0] + 5, ty + 4, { width: colW[1] });
				ty += 16;
			});
			doc.y = ty + 10;
		}

		// ── Per-Truck
		if (ownedTrucks2.length > 0) {
			// Section header ~52pt + first kpiRow ~36pt = 88pt.
			ensureSpace(90);
			sectionHeader("Fleet Breakdown");
			ownedTrucks2.forEach(t => {
				ensureSpace(36);
				kpiRow(
					`Unit ${t.unit_number}`,
					`${t.make||""} ${t.model||""}`.trim() || "—",
					"Driver",
					t.assigned_driver || "Unassigned"
				);
			});
		}

		// ── Footer (last page only — pageAdded handler removed to prevent infinite loop)
		doc.rect(0, doc.page.height - 30, doc.page.width, 30).fill("#f0f0f0");
		doc.fillColor("#999").fontSize(8).font("Helvetica")
			.text(`Generated by LogisX  ·  ${dateStr}`, 50, doc.page.height - 20, { lineBreak: false });

		doc.end();
		await new Promise(resolve => doc.on("end", resolve));

		const pdfBuffer = Buffer.concat(chunks);
		const fileName = `${investorName.replace(/\s+/g,"_")}_Report_${new Date().toISOString().slice(0,10)}.pdf`;
		res.setHeader("Content-Type", "application/pdf");
		res.setHeader("Content-Disposition", `attachment; filename="${fileName}"`);
		res.send(pdfBuffer);
	} catch (err) {
		console.error("Report generation error:", err.message);
		res.status(500).json({ error: "Failed to generate report" });
	}
});

// POST /api/documents/upload — Upload document (images → PDF, or direct file)
app.post("/api/documents/upload", requireAuth, driverWriteLimiter, async (req, res) => {
	try {
		const { loadId, rowIndex, photoData, fileType, fileName: clientFileName } = req.body;
		const driverName = resolveDriverActor(req, res, req.body.driverName);
		if (driverName === null) return;
		const docType = req.body.docType || req.body.type || "POD";
		if (!loadId || !rowIndex || !photoData) {
			return res
				.status(400)
				.json({ error: "Please select a file before uploading." });
		}
		// SECURITY: drivers can only upload docs for loads assigned to them
		if (req.session.user.role === "Driver") {
			const owned = await loadBelongsToDriver(loadId, driverName);
			if (!owned) return res.status(403).json({ error: "This load is not assigned to you" });
		}

		const timestamp = Date.now();
		let fileBuffer;
		let fileName;
		let driveUrl = "";

		// SECURITY — path traversal. `loadId` and `docType` are both request-body
		// strings that get interpolated straight into a filename and then
		// path.join'ed against uploads/. Unsanitized, `docType = "/../../client/dist/a"`
		// escapes to a directory that is served UNAUTHENTICATED (bypassing the
		// nosniff/attachment headers on the /uploads mount entirely), and
		// `loadId = "../../../tmp/x"` leaves the app root altogether. pm2 runs as
		// root on a box shared with other tenants under /var/www, so this is an
		// arbitrary-path root-owned write — and it is reachable by a DRIVER, the
		// lowest-privilege role: loadBelongsToDriver() below validates loadId's
		// OWNERSHIP but never its SHAPE, and docType is unchecked at every role.
		// Same character class as the rate-con archive and the receipts ZIP export.
		const safeLoadId = String(loadId).replace(/[^A-Za-z0-9._-]/g, "_").slice(0, 100);
		const safeDocType = String(docType).replace(/[^A-Za-z0-9._-]/g, "_").slice(0, 40) || "DOC";

		if (fileType === 'document') {
			// Direct document upload (PDF, Word, etc.) — no image conversion
			if (clientFileName && !validateFileExt(clientFileName)) return res.status(400).json({ error: "File type not allowed" });
			const base64 = (typeof photoData === 'string' ? photoData : '').replace(/^data:[^;]+;base64,/, "");
			fileBuffer = Buffer.from(base64, "base64");
			const ext = (clientFileName ? path.extname(clientFileName) : '.pdf').replace(/[^A-Za-z0-9.]/g, "");
			// Magic-byte check, closing the asymmetry with the sibling receipt path
			// (which insists on "%PDF-"). Scoped to exactly the extensions the
			// /uploads mount still serves INLINE — those are the only ones a browser
			// will render, so they are the only ones where a lying extension can do
			// anything. The office/text types are attachment-served and several of
			// them (.csv/.txt) have no signature to check anyway.
			const docErr = verifyInlineServedBytes(fileBuffer, ext);
			if (docErr) return res.status(400).json({ error: docErr });
			fileName = `${safeLoadId}_${safeDocType}_${timestamp}${ext}`;
		} else {
			// Image upload — convert to multi-page PDF
			const photoArray = Array.isArray(photoData) ? photoData : [photoData];
			const imageBuffers = photoArray.map(p => {
				const base64 = (typeof p === "string" ? p : "").replace(/^data:image\/\w+;base64,/, "");
				return Buffer.from(base64, "base64");
			});
			// SECURITY: client-supplied data URI Content-Type is trivially forged
			// (a driver could send `data:image/jpeg;base64,<html-payload>`).
			// Reject anything whose decoded bytes don't carry a real image header
			// before we hand it to pdfkit (or, worse, write it to /uploads).
			for (const buf of imageBuffers) {
				if (!isValidImageMagic(buf)) {
					return res.status(400).json({ error: "Uploaded photo is not a recognized image format." });
				}
			}
			try {
				fileBuffer = await imageToPdf(imageBuffers);
			} catch (pdfErr) {
				console.error("Image-to-PDF error:", pdfErr.message);
				return res.status(400).json({ error: "The photo could not be processed. Please try taking a new photo." });
			}
			fileName = `${safeLoadId}_${safeDocType}_${timestamp}.pdf`;
		}

		// Save to local disk
		try {
			const uploadsDir = path.join(__dirname, "uploads");
			if (!fs.existsSync(uploadsDir)) fs.mkdirSync(uploadsDir, { recursive: true });
			// Belt-and-braces containment assert, mirroring the receipts ZIP export.
			// The sanitizer above already makes traversal unrepresentable; this
			// catches any future edit that widens the character class or builds the
			// name a different way, and it fails the request rather than the write.
			const destPath = path.join(uploadsDir, fileName);
			if (!destPath.startsWith(uploadsDir + path.sep)) {
				console.error("Document upload: refused out-of-tree path", { fileName });
				return res.status(400).json({ error: "Invalid document name" });
			}
			fs.writeFileSync(destPath, fileBuffer);
			driveUrl = `/uploads/${fileName}`;
		} catch (localErr) {
			console.error("Local file save error:", localErr.message);
			return res.status(500).json({ error: "Could not save the document. Please try again." });
		}

		// OCR for receipts (images only). Stays ON the critical path because it
		// populates ocrText in the response body below; it only runs for
		// docType === "Receipt", never for the POD path.
		let ocrText = "";
		if (docType === "Receipt" && fileType !== 'document') {
			const photoArray = Array.isArray(photoData) ? photoData : [photoData];
			const firstBuf = Buffer.from(photoArray[0].replace(/^data:image\/\w+;base64,/, ""), "base64");
			ocrText = await extractReceiptText(firstBuf);
		}

		// Store metadata in SQLite
		try {
			db.prepare(
				`INSERT INTO documents (load_id, driver, type, file_name, drive_file_id, drive_url, ocr_text)
				 VALUES (?, ?, ?, ?, ?, ?, ?)`,
			).run(
				loadId,
				driverName || "",
				docType,
				fileName,
				"",
				driveUrl,
				ocrText,
			);
		} catch (dbErr) {
			console.error("SQLite insert error:", dbErr.message);
			return res.status(500).json({ error: "Document was uploaded but could not be saved. Please try again." });
		}

		// Notify dispatch
		io.to("dispatch").emit("pod-uploaded", {
			loadId,
			driverName,
			driveUrl,
			docType,
		});
		insertDispatchNotification.run(
			'pod-uploaded',
			`${docType} uploaded by ${driverName || 'driver'}`,
			`Load ${loadId}`,
			JSON.stringify({ loadId, driverName, docType })
		);
		io.to("dispatch").emit("dispatch-notification", {
			type: 'pod-uploaded',
			title: `${docType} uploaded by ${driverName || 'driver'}`,
			body: `Load ${loadId}`,
		});

		res.json({ success: true, driveUrl, ocrText });
		console.log(`[upload] 200 sent; deferring POD sheet update row ${rowIndex}`);

		// Mark the POD column in the sheet AFTER the response is sent. This Sheets
		// get+update adds 2–3s+ and used to block the response long enough that
		// iPhone-on-cellular clients aborted mid-upload (nginx 499) even though
		// the file was already saved. setImmediate runs it once the response has
		// flushed; rowIndex/loadId/docType are captured from the handler closure.
		// The try/catch keeps a Sheets failure from surfacing as an unhandled
		// rejection — res IS in closure scope but MUST NOT be touched (already sent).
		if (docType === "POD") {
			setImmediate(async () => {
				try {
					const sheets = await getSheets();
					// Resolve the target row authoritatively by loadId rather than trusting the
					// client-supplied rowIndex, which can arrive bogus (e.g. 999999) and blow past
					// the sheet grid ("Range 'Job Tracking'!T999999 exceeds grid limits"), silently
					// dropping the POD flag. Falls back to the client rowIndex only when it is a real
					// in-bounds row and no loadId match is found.
					const jtResp = await sheets.spreadsheets.values.get({
						spreadsheetId: SPREADSHEET_ID,
						range: "Job Tracking",
					});
					const jtRows = jtResp.data.values || [];
					const headers = jtRows[0] || [];
					const podColIdx = headers.findIndex((h) =>
						/pod.*upload|^documents$/i.test(h),
					);
					if (podColIdx < 0) return;
					const loadIdColIdx = headers.findIndex((h) => /load.?id|job.?id/i.test(h));
					const targetLid = String(loadId).trim().toLowerCase().replace(/^#/, "");
					let targetRow = -1;
					if (loadIdColIdx >= 0) {
						// jtRows[] is 0-based and includes the header at [0], so sheet row = i + 1.
						for (let i = jtRows.length - 1; i >= 1; i--) {
							const lid = String(jtRows[i][loadIdColIdx] || "").trim().toLowerCase().replace(/^#/, "");
							if (lid === targetLid) { targetRow = i + 1; break; }
						}
					}
					const clientRow = parseInt(rowIndex, 10);
					if (targetRow < 0 && Number.isInteger(clientRow) && clientRow >= 2 && clientRow <= jtRows.length) {
						targetRow = clientRow;
					}
					if (targetRow < 0) {
						console.error(`Sheet POD column update skipped: no row for load ${loadId} (client rowIndex=${rowIndex})`);
						return;
					}
					const podColLetter = colLetter(podColIdx);
					await sheets.spreadsheets.values.update({
						spreadsheetId: SPREADSHEET_ID,
						range: `Job Tracking!${podColLetter}${targetRow}`,
						valueInputOption: "USER_ENTERED",
						requestBody: { values: [["Yes"]] },
					});
					console.log(`[upload] deferred POD sheet update done row ${targetRow} (load ${loadId})`);
				} catch (sheetErr) {
					console.error("Sheet POD column update error (non-critical):", sheetErr.message);
				}
			});
		}
	} catch (error) {
		console.error("Error uploading document:", error.message);
		res.status(500).json({ error: "Something went wrong. Please try again or contact dispatch." });
	}
});

// ============================================================
// GPS TRACKING & GEOFENCING
// ============================================================

// Geofence radius in metres, for BOTH the pickup and the delivery zone.
// 3218.69 m = 2 miles, set by the client on 2026-08-06. Their reasoning held up
// against the data: in the two times GPS auto-status had ever fired by then, one
// landed at 881 m against the old 1000 m zone — it barely qualified. Widening
// buys margin against imprecise rate-con geocodes and large yards.
//
// Env-tunable because this is a field-tuned number, not a constant: watching it
// in production is the only way to know if it is right, and a retune should cost
// a `pm2 restart`, not a deploy. Mirrors ROUTEMATE_POLL_LIVE_SEC.
// The `> 0` test is load-bearing — it catches 0, negatives and NaN alike. A
// radius of 0 would disable every geofence silently, which looks exactly like
// the bug this feature spent months having.
//
// ⚠️ Area scales with the SQUARE of this: 1000 m -> 3218.69 m is 3.2× the radius
// but 10.4× the area (3.1 -> 32.5 km²). Two consequences before you raise it
// further: (a) the arrival hysteresis weakens, since a highway drive-by spends
// more consecutive fixes inside the zone; (b) any load SHORTER than the radius
// can never exit the pickup zone — see the departure guard below.
const GEOFENCE_RADIUS = Number(process.env.GEOFENCE_RADIUS_M) > 0
	? Number(process.env.GEOFENCE_RADIUS_M)
	: 3218.69;
// Departure needs the truck to actually be moving, not just to have drifted a
// few metres while parked. Same threshold the driver-pay "active day" basis
// uses for "traveled" (~5 mph), so the two notions of moving agree.
const GEOFENCE_DEPART_SPEED_MPS = 2.235;

// ARRIVAL speed ceiling (~10 mph). A truck cannot arrive at highway speed.
//
// The dwell hysteresis below asks for two consecutive fixes inside the zone,
// which was a real filter at 1000 m — a 2 km chord is barely two fixes at 60 mph
// on a 60 s poll. At 3218.69 m the chord is 6.44 km, about FOUR fixes, so a
// truck merely passing a shipper on the freeway now satisfies it. Speed fixes
// that in a way a fix count cannot: it does not degrade when the radius grows,
// so this stays correct if the radius is retuned again.
//
// It also sharpens detention. Arrival now stamps when the truck actually slows
// down at the site, not when it first crosses a line two miles out — so the
// At Shipper -> In Transit window measures time AT the shipper rather than time
// within two miles of it.
//
// Deliberately looser than GEOFENCE_DEPART_SPEED_MPS: 5 mph means "moving at
// all", which would make a truck still rolling through the gate wait for another
// poll. 10 mph still excludes every highway pass while letting a normal yard
// entry qualify on the first fix inside.
//
// FAILS OPEN: every "no speed" shape compares false against the ceiling, so a
// ping carrying no speed behaves exactly as it did before this existed — a
// missing field can never cause a MISSED arrival. Two different coercions get
// you there, which is worth stating precisely rather than hand-waving:
// Number(undefined) and Number("abc") are NaN (and every comparison with NaN is
// false), while Number(null) and Number("") are 0 (and 0 > 4.5 is false).
const GEOFENCE_ARRIVE_MAX_SPEED_MPS = Number(process.env.GEOFENCE_ARRIVE_MAX_SPEED_MPS) > 0
	? Number(process.env.GEOFENCE_ARRIVE_MAX_SPEED_MPS)
	: 4.5;

// How far along its lifecycle a load is. Used to order a driver's active loads
// when they carry more than one (queueing is supported, so this is routine):
// the most-progressed load is the one they are actually working, so it gets
// evaluated first. Sheet row order — the previous tie-break — is rate-con
// arrival order, which reliably picks the STALEST load instead.
// Unknown statuses rank -1 so they are asked last rather than first.
const STATUS_PROGRESS = [
	"assigned", "dispatched", "heading to shipper", "at shipper",
	"loading", "in transit", "at receiver", "unloading",
];
function statusProgressRank(status) {
	return STATUS_PROGRESS.indexOf(String(status || "").trim().toLowerCase());
}

// Order a driver's active loads for geofence evaluation: most-progressed first,
// then NEAREST PICKUP as the tie-break.
//
// The rank sort alone leaves ties unresolved, and Array.sort is stable, so a tie
// fell through to the input order — which is Job Tracking row order, i.e. the
// order rate-cons happened to arrive. That is arbitrary with respect to where
// the truck actually is. Two loads both sitting in "Dispatched" share a valid
// predecessor for "At Shipper", so whichever came first in the sheet won, and
// the caller breaks on the first advance. At a 1000 m radius the two pickups had
// to be within ~1.2 mi for this to matter; at 3218.69 m it is ~4 mi — routine
// for two loads out of the same industrial park, port terminal or rail ramp.
//
// Nearest-pickup does not make a genuinely ambiguous case unambiguous (two docks
// in one yard remain a coin flip), but it is strictly better than rate-con
// arrival order, and it costs one indexed lookup per candidate.
//
// Loads with no coordinates sort LAST rather than first: geofencing is a no-op
// for them anyway, so they must never displace a load that could actually fire.
function orderGeofenceCandidates(candidates, latitude, longitude) {
	const distCache = new Map();
	const pickupDist = (loadId) => {
		if (distCache.has(loadId)) return distCache.get(loadId);
		let d = Infinity;
		try {
			const row = getLoadCoordsRow(loadId);
			if (row && Number.isFinite(row.origin_lat) && Number.isFinite(row.origin_lng)) {
				d = geolib.getDistance({ latitude, longitude }, { latitude: row.origin_lat, longitude: row.origin_lng });
			}
		} catch { /* unknown distance sorts last, same as no coordinates */ }
		distCache.set(loadId, d);
		return d;
	};
	return candidates.slice().sort((a, b) => {
		const byRank = statusProgressRank(b.status) - statusProgressRank(a.status);
		if (byRank !== 0) return byRank;
		return pickupDist(a.loadId) - pickupDist(b.loadId);
	});
}

// Pickup/drop-off coordinates for a load.
//
// WHY THIS EXISTS: geofencing was written in full — radius, hysteresis, guards,
// notifications — and then never fired once in production (zero rows of
// source='geofence' against 197 manual status changes). The cause was that
// coordinates were resolved ONLY from Job Tracking sheet columns, and that sheet
// has 26 columns of which none is a latitude or longitude. checkGeofence
// therefore returned [] on every ping, silently, forever.
//
// The coordinates do exist — in load_coordinates, written by
// POST /api/loads/from-ratecon at ingestion and by the on-demand geocode. The
// sheet stays PRIMARY so this keeps working if such columns are ever added;
// load_coordinates is the fallback that actually carries the data today.
const loadCoordsStmt = db.prepare(
	`SELECT origin_lat, origin_lng, dest_lat, dest_lng FROM load_coordinates WHERE load_id = ?`
);

// The previous clean fix for a vehicle. OFFSET 1 skips the ping currently being
// processed (already INSERTed by the sync's txn). Used twice: arrival hysteresis
// (previous fix must ALSO be inside the zone) and departure detection (previous
// fix must have been inside the zone we just left).
const prevCleanFixStmt = db.prepare(`
	SELECT latitude, longitude
	FROM routemate_telemetry
	WHERE routemate_vehicle_id = ?
	  AND dropped_reason = ''
	  AND latitude IS NOT NULL
	  AND longitude IS NOT NULL
	ORDER BY id DESC
	LIMIT 1 OFFSET 1
`);

// load_coordinates keys are not written consistently — from-ratecon stores the
// raw sheet value while /api/geocode/load stores it lowercased with a leading
// '#' stripped, and the sheet contains both "513987502" and "#513987502" forms.
// Look both up rather than silently missing a row that exists.
const normLoadKey = (id) => String(id || "").trim().toLowerCase().replace(/^#/, "");
function getLoadCoordsRow(loadId) {
	const raw = String(loadId || "").trim();
	if (!raw) return null;
	try {
		return loadCoordsStmt.get(raw) || loadCoordsStmt.get(normLoadKey(raw)) || null;
	} catch { return null; }
}

const upsertLoadCoordsStmt = db.prepare(
	`INSERT OR REPLACE INTO load_coordinates
	 (load_id, origin_lat, origin_lng, dest_lat, dest_lng, pickup_address, dropoff_address)
	 VALUES (?, ?, ?, ?, ?, ?, ?)`
);

// Geofencing is a silent no-op for any load with no coordinates, and
// load_coordinates is populated only opportunistically — at rate-con ingestion,
// or when someone opens the load's map. n8n-ingested loads (the majority) get
// no row until a human happens to look at them, so geofencing would stay dead
// for exactly the loads nobody is watching. Fill the gap on first ping instead.
//
// Cheap by construction: the row here comes from the already-cached sheet (no
// re-read), geocodeAddress() is backed by geocode_cache, and a successful write
// means this never runs again for that load. Best-effort — never throws.
async function ensureLoadCoordinates(loadId, loadObj, headers) {
	const lid = normLoadKey(loadId);
	if (!lid) return false;
	try {
		const existing = getLoadCoordsRow(loadId);
		if (existing && existing.origin_lat != null && existing.dest_lat != null) return true;

		const puCol = headers.find((h) => /pickup.*address|origin.*address|shipper.*address/i.test(h));
		const doCol = headers.find((h) => /drop.?off.*address|dest.*address|receiver.*address|delivery.*address/i.test(h));
		const pu = puCol ? String(loadObj[puCol] || "").trim() : "";
		const dz = doCol ? String(loadObj[doCol] || "").trim() : "";
		if (!pu && !dz) return false;

		const [o, d] = await Promise.all([
			pu ? geocodeAddress(pu) : Promise.resolve(null),
			dz ? geocodeAddress(dz) : Promise.resolve(null),
		]);
		if (!o && !d) return false;
		upsertLoadCoordsStmt.run(lid, o ? o.lat : null, o ? o.lng : null, d ? d.lat : null, d ? d.lng : null, pu, dz);
		console.log(`[geofence] geocoded load ${lid} on demand (origin=${!!o} dest=${!!d})`);
		return true;
	} catch (err) {
		console.error("ensureLoadCoordinates error:", err.message);
		return false;
	}
}

function resolveGeofencePoints(loadData, headers, loadId) {
	const num = (v) => { const n = parseFloat(v); return Number.isFinite(n) ? n : null; };
	const col = (re) => headers.find((h) => re.test(h));

	const oLatCol = col(/origin.*lat|pickup.*lat|shipper.*lat/i);
	const oLngCol = col(/origin.*l(on|ng)|pickup.*l(on|ng)|shipper.*l(on|ng)/i);
	const dLatCol = col(/dest.*lat|drop.*lat|receiver.*lat|delivery.*lat/i);
	const dLngCol = col(/dest.*l(on|ng)|drop.*l(on|ng)|receiver.*l(on|ng)|delivery.*l(on|ng)/i);

	let oLat = oLatCol ? num(loadData[oLatCol]) : null;
	let oLng = oLngCol ? num(loadData[oLngCol]) : null;
	let dLat = dLatCol ? num(loadData[dLatCol]) : null;
	let dLng = dLngCol ? num(loadData[dLngCol]) : null;

	if ((oLat === null || oLng === null || dLat === null || dLng === null) && loadId) {
		const row = getLoadCoordsRow(loadId);
		if (row) {
			if (oLat === null || oLng === null) { oLat = num(row.origin_lat); oLng = num(row.origin_lng); }
			if (dLat === null || dLng === null) { dLat = num(row.dest_lat); dLng = num(row.dest_lng); }
		}
	}

	return {
		origin: (oLat !== null && oLng !== null) ? { latitude: oLat, longitude: oLng } : null,
		dest: (dLat !== null && dLng !== null) ? { latitude: dLat, longitude: dLng } : null,
	};
}

function checkGeofence(lat, lng, loadData, headers, loadId) {
	const { origin, dest } = resolveGeofencePoints(loadData, headers, loadId);
	const here = { latitude: lat, longitude: lng };
	const triggers = [];
	if (origin && geolib.isPointWithinRadius(here, origin, GEOFENCE_RADIUS)) triggers.push("At Shipper");
	if (dest && geolib.isPointWithinRadius(here, dest, GEOFENCE_RADIUS)) triggers.push("At Receiver");
	return triggers;
}

// Auto-advance a load's status when the truck enters a pickup/drop-off geofence.
// Shared by any location source — currently only the Routemate telemetry sync.
// Guards: never advances delivered/canceled rows, never auto-writes a completion
// status, only transitions from a valid predecessor status, AND requires the
// previous (non-dropped) telemetry fix to also be inside the same geofence
// trigger so a single noisy ping can't flip status mid-highway-pass.
async function tryGeofenceAdvance({ latitude, longitude, driverName, loadId, routemateVehicleId, speedMps }) {
	if (!latitude || !longitude || !driverName || !loadId) return null;
	try {
		const jt = await getJobTrackingCached();
		const headers = jt.headers;
		const loadIdCol = headers.find((h) => /load.?id|job.?id/i.test(h));
		const statusCol = headers.find((h) => /status/i.test(h));
		if (!loadIdCol || !statusCol) return null;

		for (const loadObj of jt.data) {
			const rowStatus = (loadObj[statusCol] || "").trim().toLowerCase();
			if (/^(delivered|completed|pod received|canceled|cancelled)$/i.test(rowStatus)) continue;
			if (String(loadObj[loadIdCol] || "") !== String(loadId)) continue;

			// No coordinates => checkGeofence can only ever return []. Geocode
			// once from the addresses already on this row so the next ping works,
			// rather than staying silently dead for the life of the load.
			if (!resolveGeofencePoints(loadObj, headers, loadId).origin) {
				await ensureLoadCoordinates(loadId, loadObj, headers);
			}

			const triggers = checkGeofence(latitude, longitude, loadObj, headers, loadId);
			// With a 1000m radius a short-haul load whose pickup and drop sit
			// within ~2km can fall inside BOTH geofences at once (checkGeofence
			// then returns both). Pick the trigger whose predecessor matches the
			// current status instead of taking triggers[0], so the correct
			// transition still fires. checkGeofence only ever emits the two
			// arrival statuses, so a completion status can never be auto-written.
			let trigger = triggers.find((t) =>
				(t === "At Shipper" && /^(dispatched|assigned|heading to shipper)$/i.test(rowStatus)) ||
				(t === "At Receiver" && /^(in transit)$/i.test(rowStatus))
			);

			// DEPARTURE -> In Transit. Arrival alone gives a time-IN but no
			// time-OUT, which is why detention has been invisible. Leaving the
			// pickup zone under power is the departure signal: the truck was
			// inside the shipper geofence on the previous fix, is outside it
			// now, and is actually moving (not GPS drift while parked).
			//
			// Deliberately pickup-only. Leaving the RECEIVER is NOT automated —
			// that would mean "delivered", and the hard rule here is that a
			// completion status is never auto-written (POD depends on it).
			let departed = false;
			if (!trigger && /^(at shipper|loading)$/i.test(rowStatus)
				&& Number(speedMps) > GEOFENCE_DEPART_SPEED_MPS && routemateVehicleId) {
				// Normally departure means "no longer inside the pickup zone".
				//
				// SHORT-HAUL GUARD: that test alone strands any load whose total
				// length is under GEOFENCE_RADIUS — the truck never exits the
				// pickup circle, so In Transit never fires, and At Receiver
				// can't fire either because its predecessor IS "in transit".
				// The load sits at "At Shipper" forever. At 1000 m that hit
				// hauls under ~1.2 mi (1 load in production); at 3218.69 m it
				// would hit everything under 2 mi. So: also treat it as a
				// departure when the truck is closer to the DELIVERY than to
				// the PICKUP and moving.
				//
				// Safe for the normal case by construction: on the 220-mile
				// median haul a truck pulling out of the shipper is nowhere
				// near closer to the destination, so this second clause only
				// ever engages where the two zones genuinely overlap.
				let leftPickupZone = !triggers.includes("At Shipper");
				if (!leftPickupZone) {
					try {
						const pts = resolveGeofencePoints(loadObj, headers, loadId);
						if (pts.origin && pts.dest) {
							const here = { latitude, longitude };
							leftPickupZone = geolib.getDistance(here, pts.dest) < geolib.getDistance(here, pts.origin);
						}
					} catch { /* fall back to the plain zone-exit test */ }
				}
				const prevFix = leftPickupZone ? prevCleanFixStmt.get(routemateVehicleId) : null;
				if (prevFix && checkGeofence(prevFix.latitude, prevFix.longitude, loadObj, headers, loadId).includes("At Shipper")) {
					trigger = "In Transit";
					departed = true;
				}
			}
			if (!trigger) return null;

			// Dwell hysteresis (Tier 1, 2026-05-15). Require the *previous*
			// non-dropped fix on this vehicle to ALSO be inside the same
			// trigger zone. Single-ping noise on a highway pass-through can
			// drop a fix 150m sideways into the 1000m radius; demanding two
			// consecutive fixes (≈30s at 15s polling) rules that out without
			// adding meaningful latency to legitimate arrivals.
			// Arrivals only: a departure already proved the previous fix was
			// inside the zone (that IS its signal), so re-checking it here
			// would demand the truck be simultaneously in and out of the zone.
			// Speed ceiling, checked BEFORE the fix-count test because it is the
			// cheaper and stronger of the two: no DB read, and unlike a fix count
			// it does not weaken as the radius grows. See
			// GEOFENCE_ARRIVE_MAX_SPEED_MPS for why a count alone stopped being
			// enough at a 2-mile radius. Arrivals only — a departure is defined
			// by the truck moving, so applying a speed ceiling there would
			// contradict its own trigger.
			if (!departed && Number(speedMps) > GEOFENCE_ARRIVE_MAX_SPEED_MPS) return null;
			if (routemateVehicleId && !departed) {
				const prevFix = prevCleanFixStmt.get(routemateVehicleId);
				// OFFSET 1 because the CURRENT ping was already INSERTed by
				// the txn above us; OFFSET 0 would just hand back our own row.
				if (!prevFix) return null;
				const prevTriggers = checkGeofence(prevFix.latitude, prevFix.longitude, loadObj, headers, loadId);
				if (!prevTriggers.includes(trigger)) return null;
			}

			// How far the truck actually was from the MAPPED point when this
			// fired. A geocode lands on a front gate or a centroid, not on the
			// dock — at a large DC or a yard the truck can legitimately sit
			// several hundred metres from the coordinate we hold. Recording the
			// real distance is what tells you whether a given coordinate is
			// trustworthy and whether the 1000 m radius is right for that site,
			// instead of everyone guessing. Measured against the pickup point
			// for At Shipper and In Transit (departure), the drop for At Receiver.
			const zonePoints = resolveGeofencePoints(loadObj, headers, loadId);
			const zonePoint = trigger === "At Receiver" ? zonePoints.dest : zonePoints.origin;
			let distanceM = null;
			try {
				if (zonePoint) distanceM = geolib.getDistance({ latitude, longitude }, zonePoint);
			} catch { /* distance is informational — never block the transition */ }
			const distTxt = distanceM === null
				? ""
				: departed
					? ` (${distanceM} m from the mapped pickup point)`
					: ` (${distanceM} m from the mapped ${trigger === "At Receiver" ? "delivery" : "pickup"} point)`;

			const sheets = await getSheets();
			const statusColIdx = headers.indexOf(statusCol);
			const statusColLetter = colLetter(statusColIdx);
			const sheetRow = loadObj._rowIndex; // 1-based, includes header row
			await sheets.spreadsheets.values.update({
				spreadsheetId: SPREADSHEET_ID,
				range: `Job Tracking!${statusColLetter}${sheetRow}`,
				valueInputOption: "USER_ENTERED",
				requestBody: { values: [[trigger]] },
			});
			jtCacheInvalidate();
			recordStatusChange({
				loadId,
				oldStatus: loadObj[statusCol] || '',
				newStatus: trigger,
				source: 'geofence',
				actor: driverName,
				// Reuses the `reason` column added for cancellations — same
				// question ("why did this transition happen"), and it surfaces
				// in the phase timeline the admin modal and driver app render.
				reason: distanceM === null
					? "auto by GPS"
					: `auto by GPS — ${distanceM} m from the mapped ${trigger === "At Receiver" ? "delivery" : "pickup"} point (radius ${GEOFENCE_RADIUS} m)`,
			});

			const geoMsg = (trigger === "At Shipper"
				? "You have arrived at the pickup location"
				: trigger === "In Transit"
					? "Departed the pickup location — you're now in transit"
					: "You have arrived at the delivery location") + distTxt;
			const geoNotif = insertNotification.run(
				driverName.trim().toLowerCase(), "geofence",
				`${trigger} — Load ${loadId}`,
				geoMsg,
				JSON.stringify({ loadId, status: trigger, distanceM })
			);
			io.to(driverName.trim().toLowerCase()).emit("geofence-trigger", {
				loadId, status: trigger, distanceM,
				notificationId: geoNotif.lastInsertRowid,
			});
			io.to("dispatch").emit("geofence-trigger", {
				loadId, driver: driverName, status: trigger, distanceM,
			});
			const dispatchMsg = (trigger === "At Shipper"
				? `${driverName} has arrived at the pickup location (Load ${loadId})`
				: trigger === "In Transit"
					? `${driverName} has departed the pickup location (Load ${loadId})`
					: `${driverName} has arrived at the delivery location (Load ${loadId})`) + distTxt;
			insertDispatchNotification.run(
				"geofence",
				`${driverName}: ${trigger}`,
				dispatchMsg,
				JSON.stringify({ loadId, driverName, status: trigger, distanceM })
			);
			io.to("dispatch").emit("dispatch-notification", {
				type: "geofence",
				title: `${driverName}: ${trigger}`,
				body: dispatchMsg,
			});

			return trigger;
		}
		return null;
	} catch (err) {
		console.error("tryGeofenceAdvance error:", err.message);
		return null;
	}
}

// POST /api/location — Retired. Phone GPS was superseded by Routemate ELD
// (see lib/routemate-client.js + routemateSyncTelemetry). Route kept so cached
// driver clients on old phones receive a clear 410 instead of 404.
app.post("/api/location", requireAuth, locationLimiter, (req, res) => {
	res.status(410).json({
		error: "Phone GPS is discontinued. Location is now sourced from Routemate ELD.",
	});
});

// (Legacy phone-GPS POST /api/location body removed 2026-05-13. Geofence logic
//  now lives in tryGeofenceAdvance() above and runs from the Routemate sync.)

// Movement state for the tracking panel (Moving / Idling / Parked). Derived from
// live GPS — NOT FMCSA duty status. Per client: a moving truck means driving, a
// stopped one means stopped. A fresh ELD ping (< 15 min old) above the ~5 mph
// travel gate is "moving"; fresh but slower is "idling"; no recent ping is "parked".
const MOVEMENT_MOVING_MPS = 2.235;         // ~5 mph — same gate as the ELD travel-day basis
const MOVEMENT_ACTIVE_MS = 15 * 60 * 1000; // ELD ping within 15 min = truck active; older = parked
function classifyMovement(loc) {
	const age = loc ? loc.lastPingAge : null;
	if (age == null || age >= MOVEMENT_ACTIVE_MS) return "parked";
	return (loc.speed || 0) > MOVEMENT_MOVING_MPS ? "moving" : "idling";
}

// GET /api/locations/latest — Latest position per active driver with ETA
app.get("/api/locations/latest", requireRole("Super Admin", "Dispatcher"), async (req, res) => {
	try {
		// Phone GPS retired 2026-05-13 — locations come exclusively from Routemate
		// telemetry. Start with one placeholder per carrier driver and let the
		// overlay below fill in fresh ELD positions.
		let allDriverNames = [];
		try {
			const dirDrivers = db.prepare("SELECT driver_name FROM drivers_directory").all();
			for (const d of dirDrivers) {
				if (d.driver_name) allDriverNames.push(d.driver_name);
			}
		} catch { /* silent */ }

		const locations = [];
		const seen = new Set();
		for (const name of allDriverNames) {
			if (!seen.has(name.toLowerCase())) {
				locations.push({
					driver: name,
					latitude: null,
					longitude: null,
					speed: 0,
					heading: 0,
					timestamp: null,
					loadId: '',
					fuelPct: null,
					noGps: true,
				});
				seen.add(name.toLowerCase());
			}
		}

		// Overlay Routemate telemetry. When a driver's currently-assigned truck
		// is linked to a Routemate/Linxup device AND we have its LAST KNOWN fix
		// within the lookback window, fill in lat/lng/speed/timestamp from the ELD
		// and tag the source. Owner request 2026-07-27: an ELD pings whenever the
		// truck is powered, but a parked/idle truck pings intermittently (Rodney
		// last pinged 4 h ago), so a 5-minute freshness gate was throwing the
		// position away and hiding the truck ("I can't see where Rodney's truck
		// is"). We now surface the last known position for up to 14 days; ping
		// RECENCY (not visibility) is what the client turns into
		// Online / Dormant / Offline. Trucks with no fix in the window stay noGps.
		try {
			const STALE_SHOW_MS = 14 * 24 * 60 * 60 * 1000;
			const cutoff = Date.now() - STALE_SHOW_MS;
			const routemateRows = db.prepare(`
				SELECT
					LOWER(ta.driver_name) AS driver_lc,
					rt.latitude, rt.longitude, rt.speed, rt.bearing,
					rt.fuel_pct,
					rt.location_date_ms,
					-- Prior telemetry row's coords, used as a fallback heading source
					-- when rt.bearing is missing or non-numeric. Index idx_rm_tel_vid_date
					-- covers (routemate_vehicle_id, location_date_ms DESC) so this stays cheap.
					(SELECT rt2.latitude  FROM routemate_telemetry rt2
					   WHERE rt2.routemate_vehicle_id = t.routemate_vehicle_id
					     AND rt2.id < rt.id
					     AND rt2.dropped_reason = ''
					   ORDER BY rt2.id DESC LIMIT 1) AS prev_lat,
					(SELECT rt2.longitude FROM routemate_telemetry rt2
					   WHERE rt2.routemate_vehicle_id = t.routemate_vehicle_id
					     AND rt2.id < rt.id
					     AND rt2.dropped_reason = ''
					   ORDER BY rt2.id DESC LIMIT 1) AS prev_lng
				FROM truck_assignments ta
				JOIN trucks t ON t.id = ta.truck_id
				JOIN routemate_telemetry rt
				  ON rt.routemate_vehicle_id = t.routemate_vehicle_id
				WHERE ta.end_date = ''
				  AND COALESCE(t.routemate_vehicle_id, '') <> ''
				  AND rt.id = (
					SELECT MAX(rt2.id) FROM routemate_telemetry rt2
					WHERE rt2.routemate_vehicle_id = t.routemate_vehicle_id
					  AND rt2.dropped_reason = ''
				  )
				  AND rt.location_date_ms > ?
			`).all(cutoff);
			const routemateByDriver = {};
			for (const r of routemateRows) {
				routemateByDriver[r.driver_lc] = r;
			}
			const now = Date.now();
			for (const loc of locations) {
				const key = (loc.driver || "").toLowerCase();
				const rm = routemateByDriver[key];
				// Only overlay Routemate when telemetry has a valid fix.
				// A linked truck whose ELD lost GPS sends NULL/0 lat/lng — letting that
				// through would clobber phone GPS and pin the truck at the equator.
				const rmHasFix = rm
					&& Number.isFinite(rm.latitude)
					&& Number.isFinite(rm.longitude)
					&& (rm.latitude !== 0 || rm.longitude !== 0);
				if (rmHasFix) {
					loc.latitude = rm.latitude;
					loc.longitude = rm.longitude;
					loc.speed = rm.speed || 0;
					loc.timestamp = new Date(rm.location_date_ms).toISOString();
					loc.source = "routemate";
					loc.lastPingAge = now - rm.location_date_ms;
					// Latest ELD fuel level (0-100). Same convention as
					// /api/admin/fleet-health: fuelPct, null when the device
					// doesn't report fuel.
					loc.fuelPct = Number.isFinite(rm.fuel_pct) ? rm.fuel_pct : null;
					if (loc.noGps) loc.noGps = false;
					// Heading: parse Routemate's compass string (NW/SE/SSW/...) or numeric
					// bearing to degrees; fall back to the rhumb-line bearing between the
					// previous and current telemetry rows when Routemate sends no bearing.
					const headingDeg = parseRoutemateBearing(rm.bearing);
					if (headingDeg != null) {
						loc.heading = headingDeg;
					} else if (Number.isFinite(rm.prev_lat) && Number.isFinite(rm.prev_lng) &&
					           (rm.prev_lat !== rm.latitude || rm.prev_lng !== rm.longitude)) {
						loc.heading = geolib.getRhumbLineBearing(
							{ latitude: rm.prev_lat, longitude: rm.prev_lng },
							{ latitude: rm.latitude, longitude: rm.longitude }
						);
					}
				} else {
					loc.source = "none";
					loc.lastPingAge = null;
				}
			}
		} catch (rmErr) {
			console.error("Routemate source overlay error:", rmErr.message);
		}

		// Active truck-assignment overlay. Surfaces every actively-assigned
		// driver in the dispatcher panel even when their truck isn't
		// ELD-linked yet — without this, the panel filter
		// (loc.activeLoads.length > 0) hides every driver whose name doesn't
		// appear in the Job Tracking sheet, so /tracking looks empty when
		// only one truck has a Routemate device. Source of truth is
		// truck_assignments + trucks (not the sheet), so this stays accurate
		// when the sheet's free-text driver names drift.
		const assignmentByDriver = {};
		try {
			const assignRows = db.prepare(`
				SELECT LOWER(ta.driver_name) AS driver_lc,
				       t.id AS truck_id,
				       t.unit_number,
				       CASE WHEN COALESCE(t.routemate_vehicle_id, '') = ''
				            THEN 0 ELSE 1 END AS has_eld
				FROM truck_assignments ta
				JOIN trucks t ON t.id = ta.truck_id
				WHERE ta.end_date = ''
			`).all();
			for (const r of assignRows) {
				assignmentByDriver[r.driver_lc] = {
					truckId: r.truck_id,
					unit: r.unit_number || "",
					hasEld: !!r.has_eld,
				};
			}
		} catch (asErr) {
			console.error("Truck-assignment overlay error:", asErr.message);
		}

		// Enrich with ETA data from sheet
		try {
			const sheets = await getSheets();
			const headerResp = await sheets.spreadsheets.values.get({
				spreadsheetId: SPREADSHEET_ID,
				range: "Job Tracking!1:1",
			});
			const headers = (headerResp.data.values || [[]])[0];
			const dataResp = await sheets.spreadsheets.values.get({
				spreadsheetId: SPREADSHEET_ID,
				range: "Job Tracking",
			});
			const rows = dataResp.data.values || [];

			const loadIdCol = headers.find((h) => /load.?id|job.?id/i.test(h));
			const originLatCol = headers.find((h) => /origin.*lat|pickup.*lat|shipper.*lat/i.test(h));
			const originLngCol = headers.find((h) => /origin.*l(on|ng)|pickup.*l(on|ng)|shipper.*l(on|ng)/i.test(h));
			const destLatCol = headers.find((h) => /dest.*lat|drop.*lat|receiver.*lat|delivery.*lat/i.test(h));
			const destLngCol = headers.find((h) => /dest.*l(on|ng)|drop.*l(on|ng)|receiver.*l(on|ng)|delivery.*l(on|ng)/i.test(h));
			const deliveryTimeCol = headers.find((h) => /delivery.*time|drop.*time|delivery.*date|drop.*date/i.test(h));

			if (loadIdCol) {
				// Build load lookup
				const loadMap = {};
				for (let i = 1; i < rows.length; i++) {
					const obj = {};
					headers.forEach((h, idx) => { obj[h] = rows[i][idx] || ""; });
					const lid = obj[loadIdCol];
					if (lid) loadMap[lid] = obj;
				}

				// Build map of each driver's active loads from the sheet
				// Used to override stale load_ids and provide load details in the panel
				const statusCol = headers.find((h) => /status/i.test(h));
				const driverCol = headers.find((h) => /^driver$/i.test(h));
				const detailsCol = headers.find((h) => /^details$/i.test(h));
				const pickupAddrCol = headers.find((h) => /pickup.*addr|origin.*addr|shipper.*addr/i.test(h));
				const dropoffAddrCol = headers.find((h) => /drop.*addr|dest.*addr|receiver.*addr|delivery.*addr/i.test(h));
				const activeRe = /^(assigned|dispatched|heading to shipper|at shipper|loading|in transit|at receiver|unloading)$/i;
				// Matches /api/dashboard's activeStatuses so the Tracking panel and Dashboard KPI agree on what counts as active.
				const workingRe = /^(heading to shipper|in transit|dispatched|assigned|picked up|at shipper|at receiver|loading|unloading)$/i;
				const driverActiveLoadMap = {};   // driver → first active loadId (for override, includes dispatched)
				const driverActiveLoadsMap = {};  // driver → working loads for panel (matches /api/dashboard activeStatuses)
				if (statusCol && driverCol && loadIdCol) {
					for (let i = 1; i < rows.length; i++) {
						const obj = {};
						headers.forEach((h, idx) => { obj[h] = rows[i][idx] || ""; });
						const name = (obj[driverCol] || "").trim();
						const status = (obj[statusCol] || "").trim();
						const lid = (obj[loadIdCol] || "").trim().replace(/^#/, "");
						if (!name || !lid) continue;
						const key = name.toLowerCase();
						if (activeRe.test(status)) {
							driverActiveLoadMap[key] = lid;
						}
						if (workingRe.test(status)) {
							if (!driverActiveLoadsMap[key]) driverActiveLoadsMap[key] = [];
							const rawPickup  = pickupAddrCol  ? (obj[pickupAddrCol]  || "") : "";
							const rawDropoff = dropoffAddrCol ? (obj[dropoffAddrCol] || "") : "";
								// Two-line address parts for the tracking panel — split once per side.
								const puParts = resolveAddressParts(obj, "pickup", lid, rawPickup);
								const drParts = resolveAddressParts(obj, "drop", lid, rawDropoff);
							const entry = {
								loadId: lid,
								status,
								details: sanitizeDetails(detailsCol ? obj[detailsCol] : ""),
								pickupAddress:  puParts.cityStateZip, pickupStreet: puParts.street,
								dropoffAddress: drParts.cityStateZip, dropoffStreet: drParts.street,
							};
							if (originLatCol && originLngCol) {
								const oLat = parseFloat(obj[originLatCol]);
								const oLng = parseFloat(obj[originLngCol]);
								if (!isNaN(oLat) && !isNaN(oLng)) { entry.originLat = oLat; entry.originLng = oLng; }
							}
							if (destLatCol && destLngCol) {
								const dLat = parseFloat(obj[destLatCol]);
								const dLng = parseFloat(obj[destLngCol]);
								if (!isNaN(dLat) && !isNaN(dLng)) { entry.destLat = dLat; entry.destLng = dLng; }
							}
							// Fallback: load_coordinates table by Load ID
							if (!entry.originLat || !entry.destLat) {
								const lc = db.prepare("SELECT * FROM load_coordinates WHERE load_id = ?").get(lid.toLowerCase());
								if (lc) {
									if (!entry.originLat && lc.origin_lat) { entry.originLat = lc.origin_lat; entry.originLng = lc.origin_lng; }
									if (!entry.destLat && lc.dest_lat) { entry.destLat = lc.dest_lat; entry.destLng = lc.dest_lng; }
								}
							}
							driverActiveLoadsMap[key].push(entry);
						}
					}
				}

				const DEFAULT_SPEED_MPS = 24.587; // ~55 mph fallback when Routes API fails

				// First pass: attach loads + coords, collect ETA work
				const etaTasks = [];
				for (const loc of locations) {
					loc.etaStatus = "unknown";
					loc.etaMinutes = null;
					loc.distanceMiles = null;

					const driverKey = (loc.driver || "").toLowerCase();
					loc.activeLoads = driverActiveLoadsMap[driverKey] || [];
					loc.assignedTruck = assignmentByDriver[driverKey] || null;

					const sheetActiveLoad = driverActiveLoadMap[driverKey];
					if (sheetActiveLoad && loc.loadId !== sheetActiveLoad && loadMap[sheetActiveLoad]) {
						loc.loadId = sheetActiveLoad;
					}

					if (!loc.loadId || !loadMap[loc.loadId]) continue;
					const load = loadMap[loc.loadId];

					let oLat = NaN, oLng = NaN, dLat = NaN, dLng = NaN;
					if (originLatCol && originLngCol) {
						oLat = parseFloat(load[originLatCol]);
						oLng = parseFloat(load[originLngCol]);
					}
					if (destLatCol && destLngCol) {
						dLat = parseFloat(load[destLatCol]);
						dLng = parseFloat(load[destLngCol]);
					}
					// Fallback: many loads carry coordinates only in the load_coordinates
					// table (drag-drop / geocoded loads), not in the sheet's lat/lng
					// columns — the tracking panel's activeLoads already resolves them
					// this way. Do the same here so ETA + distance still compute.
					if (isNaN(oLat) || isNaN(oLng) || isNaN(dLat) || isNaN(dLng)) {
						try {
							const lc = db.prepare("SELECT origin_lat, origin_lng, dest_lat, dest_lng FROM load_coordinates WHERE load_id = ?")
								.get(String(loc.loadId).toLowerCase().replace(/^#/, ""));
							if (lc) {
								if ((isNaN(oLat) || isNaN(oLng)) && Number.isFinite(lc.origin_lat) && Number.isFinite(lc.origin_lng)) { oLat = lc.origin_lat; oLng = lc.origin_lng; }
								if ((isNaN(dLat) || isNaN(dLng)) && Number.isFinite(lc.dest_lat) && Number.isFinite(lc.dest_lng)) { dLat = lc.dest_lat; dLng = lc.dest_lng; }
							}
						} catch { /* coord fallback is best-effort */ }
					}

					if (!isNaN(oLat) && !isNaN(oLng)) {
						loc.originLat = oLat;
						loc.originLng = oLng;
					}
					if (!isNaN(dLat) && !isNaN(dLng)) {
						loc.destLat = dLat;
						loc.destLng = dLng;
						if (loc.latitude == null || loc.longitude == null) continue;
						etaTasks.push({ loc, dLat, dLng, load });
					}
				}

				// Second pass: parallel Routes API calls (cached internally for 15 min,
				// keyed by lat/lng rounded to 3 decimals — repeat polls hit the cache).
				// Falls back to haversine ÷ 55 mph when Routes returns null.
				await Promise.all(etaTasks.map(async ({ loc, dLat, dLng, load }) => {
					let etaSeconds;
					const route = await getRoute(
						{ latitude: loc.latitude, longitude: loc.longitude },
						{ latitude: dLat, longitude: dLng },
					);
					if (route) {
						loc.etaMinutes = route.durationMin;
						// Remaining road miles for the tracking quick-glance panel.
						loc.distanceMiles = Number.isFinite(route.distanceMiles) ? route.distanceMiles : null;
						etaSeconds = route.durationMin * 60;
					} else {
						const distMeters = geolib.getDistance(
							{ latitude: loc.latitude, longitude: loc.longitude },
							{ latitude: dLat, longitude: dLng },
						);
						// Haversine fallback (straight-line) when Routes API is unavailable.
						loc.distanceMiles = Math.round((distMeters / 1609.34) * 10) / 10;
						const speed = loc.speed > 1 ? loc.speed : DEFAULT_SPEED_MPS;
						etaSeconds = distMeters / speed;
						loc.etaMinutes = Math.round(etaSeconds / 60);
					}

					if (deliveryTimeCol && load[deliveryTimeCol]) {
						try {
							const scheduled = new Date(load[deliveryTimeCol]);
							if (!isNaN(scheduled)) {
								const arrival = new Date(Date.now() + etaSeconds * 1000);
								loc.etaStatus = arrival <= scheduled ? "on-time" : "delayed";
							}
						} catch { /* ignore parse error */ }
					}
				}));
			}
		} catch (etaErr) {
			console.error("ETA enrichment error:", etaErr.message);
			// Still return locations without ETA
		}

		// Movement state (Moving / Idling / Parked) for the tracking panel — derived
		// from live GPS, NOT FMCSA duty status (per client: a moving truck is driving,
		// a stopped one is stopped). Fresh ELD ping above the ~5 mph travel gate =
		// moving; fresh but slower = idling; no recent ping = parked.
		locations.forEach((loc) => { loc.movement = classifyMovement(loc); });

		res.json({ locations });
	} catch (error) {
		console.error("Error fetching locations:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// GET /api/tracking/hos — Current FMCSA hours-of-service clocks for all
// drivers, pulled on demand from Routemate's /api/v0/drivers/hos (no sync
// interval — dispatchers only need this while /tracking is open). Each row
// carries the remaining drive/shift/cycle/break countdowns in milliseconds
// (see lib/routemate-client.js listHosClocks for the unit rationale) plus
// dutyStatus, and is resolved to a LogisX driver name where possible so the
// tracking panel can match rows to its driver list:
//   1. Routemate driverName vs active truck_assignments.driver_name
//   2. Routemate vehicleId label → routemate_vehicles → trucks link → driver
//   3. Routemate vehicleId label vs trucks.unit_number directly
// A 60s in-memory cache absorbs dispatcher refreshes; on upstream failure the
// last good snapshot is served (tagged stale:true) so clocks don't blink out
// during a transient Routemate outage. Returns 503 when the integration is
// disabled — the UI hides the HOS block entirely on any non-200.
const HOS_CACHE_TTL_MS = 60 * 1000;
const HOS_FAIL_COOLDOWN_MS = 3 * 60 * 1000; // after a Routemate HOS failure, serve fast (skip the retry loop) for this long
let hosClockCache = { at: 0, payload: null, failedAt: 0 };

app.get("/api/tracking/hos", requireRole("Super Admin", "Dispatcher"), async (req, res) => {
	// HOS is a supplementary overlay on the tracking panel. When its provider is
	// off/unconfigured, return an empty set with 200 (not 503) so /tracking doesn't
	// log a console error on every poll — the UI just shows no HOS pills. (HOS is
	// currently Routemate-only, which is being phased out for Linxup GPS; real
	// provider status is surfaced to admins via GET /api/routemate/health.)
	if (!ROUTEMATE_ENABLED || !ROUTEMATE_API_KEY) {
		return res.json({ clocks: [], available: false, reason: !ROUTEMATE_ENABLED ? "hos_disabled" : "hos_no_key", fetchedAt: new Date().toISOString() });
	}
	try {
		const now = Date.now();
		if (hosClockCache.payload && now - hosClockCache.at < HOS_CACHE_TTL_MS) {
			return res.json(hosClockCache.payload);
		}
		// Circuit breaker: Routemate HOS is flaky (frequent 5xx) and each cache miss
		// costs a multi-second retry loop. After a failure, serve fast (stale/empty)
		// for a cooldown instead of hammering the dead upstream on every /tracking
		// poll; it retries once the cooldown passes and self-heals on the next success.
		if (hosClockCache.failedAt && now - hosClockCache.failedAt < HOS_FAIL_COOLDOWN_MS) {
			if (hosClockCache.payload) return res.json({ ...hosClockCache.payload, stale: true });
			return res.json({ clocks: [], available: false, reason: "hos_unavailable", fetchedAt: new Date().toISOString() });
		}

		// Page through the clocks (required pagination params handled by the
		// adapter). Small fleets fit in one page; the cap bounds a runaway loop.
		const HARD_PAGE_CAP = 10;
		const PAGE_SIZE = 200;
		let rows = [];
		for (let page = 0; page < HARD_PAGE_CAP; page++) {
			const batch = await routemate.listHosClocks(routemateCreds(), { page, elements: PAGE_SIZE });
			rows = rows.concat(batch.rows);
			if (batch.rows.length < PAGE_SIZE || rows.length >= batch.total) break;
		}

		// Build the three matchers from SQLite (active assignments + vehicle links).
		const byName = {};
		const byUnit = {};
		const driverByRvid = {};
		try {
			const assignRows = db.prepare(`
				SELECT ta.driver_name, t.unit_number,
				       COALESCE(t.routemate_vehicle_id, '') AS rvid
				FROM truck_assignments ta
				JOIN trucks t ON t.id = ta.truck_id
				WHERE ta.end_date = ''
			`).all();
			for (const a of assignRows) {
				const nm = (a.driver_name || "").trim();
				if (!nm) continue;
				byName[nm.toLowerCase()] = nm;
				if (a.unit_number) byUnit[String(a.unit_number).trim().toLowerCase()] = nm;
				if (a.rvid) driverByRvid[a.rvid] = nm;
			}
		} catch (mapErr) {
			console.error("HOS assignment-map error:", mapErr.message);
		}
		const rvidByLabel = {};
		try {
			const rvRows = db.prepare(
				"SELECT routemate_vehicle_id, vehicle_id FROM routemate_vehicles WHERE COALESCE(vehicle_id, '') <> ''"
			).all();
			for (const rv of rvRows) {
				rvidByLabel[String(rv.vehicle_id).trim().toLowerCase()] = rv.routemate_vehicle_id;
			}
		} catch (rvErr) {
			console.error("HOS vehicle-map error:", rvErr.message);
		}

		const clocks = rows.map((r) => {
			const nameKey = (r.driver_name || "").trim().toLowerCase();
			const labelKey = (r.vehicle_id || "").trim().toLowerCase();
			const viaLink = labelKey && rvidByLabel[labelKey] ? driverByRvid[rvidByLabel[labelKey]] : "";
			const logisxDriver = byName[nameKey] || viaLink || byUnit[labelKey] || "";
			return {
				driverName: r.driver_name,
				vehicleId: r.vehicle_id,
				dutyStatus: r.duty_status,
				driveMs: r.drive_ms,
				shiftMs: r.shift_ms,
				cycleMs: r.cycle_ms,
				breakMs: r.break_ms,
				cycleTomorrowMs: r.cycle_tomorrow_ms,
				logisxDriver,
			};
		});

		const payload = { clocks, fetchedAt: new Date().toISOString(), source: "routemate" };
		hosClockCache = { at: now, payload };
		res.json(payload);
	} catch (err) {
		console.error("tracking HOS error:", err.message);
		hosClockCache.failedAt = Date.now();
		if (hosClockCache.payload) {
			return res.json({ ...hosClockCache.payload, stale: true });
		}
		// Degrade to an empty 200 (not a 5xx) so a flapping/unreachable upstream
		// doesn't spam the browser console on every /tracking poll; the UI hides the
		// HOS pills on empty clocks either way. Admins see the real error via
		// /api/routemate/health.
		res.json({ clocks: [], available: false, reason: "hos_unavailable", fetchedAt: new Date().toISOString() });
	}
});

// GET /api/load/:loadId — Look up a specific load from Job Tracking sheet
app.get("/api/load/:loadId", requireRole("Super Admin", "Dispatcher"), async (req, res) => {
	try {
		const { loadId } = req.params;
		const sheets = await getSheets();
		const headerResp = await sheets.spreadsheets.values.get({
			spreadsheetId: SPREADSHEET_ID,
			range: "Job Tracking!1:1",
		});
		const headers = (headerResp.data.values || [[]])[0];
		const dataResp = await sheets.spreadsheets.values.get({
			spreadsheetId: SPREADSHEET_ID,
			range: "Job Tracking",
		});
		const rows = dataResp.data.values || [];
		const loadIdCol = headers.find((h) => /load.?id|job.?id/i.test(h));
		if (!loadIdCol) {
			return res.status(404).json({ error: "No load ID column found in sheet" });
		}

		for (let i = 1; i < rows.length; i++) {
			const obj = {};
			headers.forEach((h, idx) => { obj[h] = rows[i][idx] || ""; });
			if (obj[loadIdCol] === loadId) {
				obj._rowIndex = i + 1;
				return res.json({ load: obj });
			}
		}

		res.status(404).json({ error: `Load ${loadId} not found` });
	} catch (error) {
		console.error("Error fetching load:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// PUT /api/load/:loadId — Update specific fields of a load by load ID.
//
// The sibling of PUT /api/data/:rowIndex, addressed by LOAD ID rather than by row
// number, and it carried none of that route's guards: no period check, no audit
// line, no Owner ID validation — plus a door into the header row that route does
// not have (see UNKNOWN_COLUMN below).
//
// Because it resolves its own row, #222's caller-supplied-rowIndex class is
// structurally absent here. Everything it does after that is the same accounting
// event, so it runs the SAME sheetRowUpdateBlocker() over the same before ∪ after
// union and writes the same `update_sheet_row` audit action — one query finds
// every rewrite of a Job Tracking row whichever door it came through, with `via`
// naming the door.
app.put("/api/load/:loadId", requireRole("Super Admin", "Dispatcher"), async (req, res) => {
	try {
		const { loadId } = req.params;
		const updates = req.body; // { "Column Name": "value", ... }
		// Arrays and null are both typeof "object". An array body would turn every
		// key into a numeric index that matches no header, which is worth refusing
		// honestly rather than as a confusing UNKNOWN_COLUMN list.
		if (!updates || typeof updates !== "object" || Array.isArray(updates) || Object.keys(updates).length === 0) {
			return res.status(400).json({ error: "Request body with column updates required" });
		}
		const updateKeys = Object.keys(updates);
		// Same reasoning as PUT /api/data's ROW_TOO_WIDE: the body limit is 50mb, and
		// the diff and audit builder both walk this set. Sheets itself stops at
		// 18,278 columns, so nothing real is refused.
		if (updateKeys.length > SHEET_ROW_MAX_CELLS) {
			return res.status(400).json({
				error: `A row cannot have more than ${SHEET_ROW_MAX_CELLS} columns (received ${updateKeys.length}).`,
				code: "ROW_TOO_WIDE",
			});
		}

		const sheets = await getSheets();
		// This route addresses Job Tracking and nothing else — the tab is a hardcoded
		// literal in every range below and there is no ?sheet= parameter, so it has
		// none of the caller-controlled-tab surface resolveSheetTargetForWrite()
		// exists to close on PUT /api/data. The tab is period-guarded by definition.
		const sheetName = "Job Tracking";
		const guarded = PERIOD_GUARDED_SHEETS.includes(sheetName);
		const a1 = a1SheetPrefix(sheetName);

		// One read: headers and every row, which is what the load-id lookup needs
		// anyway. Replaces the two separate gets this route used to make.
		const dataResp = await sheets.spreadsheets.values.get({
			spreadsheetId: SPREADSHEET_ID,
			range: a1,
		});
		const rows = dataResp.data.values || [];
		const headers = rows[0] || [];
		// ⚠️ An empty-but-successful read must not unlock the write — the same
		// fail-open #209's review caught on the delete batch. Job Tracking always has
		// a header row, so no header means the read failed; and with no `before` the
		// guard can know neither which cells changed nor which month the row books
		// to, which is exactly what it needs.
		if (!headers.length) {
			return res.status(409).json({
				error: "Job Tracking could not be read, so this edit cannot be shown to leave closed months alone and cannot be recorded reversibly. Try again.",
				code: "ROW_READ_FAILED",
			});
		}
		const loadIdCol = headers.find((h) => /load.?id|job.?id/i.test(h));
		if (!loadIdCol) {
			return res.status(404).json({ error: "No load ID column found in sheet" });
		}
		const loadIdIdx = headers.indexOf(loadIdCol);

		// ⚠️ AN UNKNOWN BODY KEY USED TO CREATE A COLUMN BY REWRITING ROW 1.
		//
		// The old branch pushed any unrecognised key onto `headers` and wrote the
		// whole array back to `Job Tracking!A1`. That is the header row, and this app
		// resolves EVERY column by matching header text (findCol, the /driver/i and
		// /status/i findIndex calls, the money pattern), so one request re-pointed
		// the dashboard, the driver app, /api/financials, /api/investor and the
		// invoice batch at once — with no data row touched and no period guard fired,
		// because no data row WAS touched. It ran before the load was even located,
		// so a request for a load id that does not exist still rewrote row 1 and then
		// answered 404.
		//
		// This is not hypothetical: the route's one caller in this repo,
		// scripts/geocode-loads.js, sends ONLY unknown keys — "Origin Lat",
		// "Origin Lng", "Dest Lat", "Dest Lng" — none of which exist on Job Tracking
		// (26 columns, no coordinates; the real ones live in `load_coordinates`).
		// Running it would have taken the sheet to 30 columns, and the four new
		// headers match resolveGeofencePoints()'s /origin.*lat/i and /dest.*lat/i,
		// which PREFER sheet columns over `load_coordinates` — so it would also have
		// silently repointed geofencing at a second, unmaintained copy of the
		// coordinates. It is also what would have detonated the column-letter bug
		// fixed in this same change: at 30 columns, index 26 is where
		// String.fromCharCode(65 + i) starts emitting "[".
		//
		// Refusing is the right rule rather than "create the column safely": the
		// header row is this app's schema, a REST update route is not a migration
		// tool, and a new column is free to capture an existing regex (a "Driver
		// Phone" column would be matched by the loose /driver/i fallback). Adding a
		// column is a deliberate act — do it in the Sheets UI.
		const unknownCols = updateKeys.filter((k) => !headers.includes(k));
		if (unknownCols.length > 0) {
			return res.status(400).json({
				error: `Unknown column(s) ${unknownCols.map((c) => JSON.stringify(c)).join(", ")}. This route updates existing columns only — it used to create a missing one by rewriting the header row, which re-points every column this app resolves by header text. Add the column in the sheet first, or correct the name (header names are matched exactly, and some carry real leading/trailing spaces).`,
				code: "UNKNOWN_COLUMN",
				unknownColumns: unknownCols,
				knownColumns: headers,
			});
		}

		// Which rows this load id resolves to. Selection keeps the route's original
		// EXACT match, so no row that resolved before resolves differently now.
		// Ambiguity, though, is judged on the NORMALISED id, because that is the rule
		// deduplicateLoads() applies inside getJobTrackingCached(): every aggregate in
		// the app collapses "#123", "123 " and "123" to one load and keeps the LAST
		// row. An exact-only test would miss the "#123" vs "123" pair entirely.
		const normLid = (v) => String(v == null ? "" : v).trim().toLowerCase().replace(/^#/, "");
		const wantedLid = normLid(loadId);
		const exactRows = [];
		const normRows = [];
		for (let i = 1; i < rows.length; i++) {
			const cell = (rows[i] || [])[loadIdIdx];
			if (String(cell == null ? "" : cell) === loadId) exactRows.push(i);
			if (wantedLid && normLid(cell) === wantedLid) normRows.push(i);
		}
		if (!exactRows.length) {
			return res.status(404).json({ error: `Load ${loadId} not found` });
		}
		// ⚠️ AMBIGUITY REFUSES, IT DOES NOT GUESS — the same rule, code and reasoning
		// PUT /api/loads/:loadId/status-override adopted in #223, on the same sheet.
		// The request carries a load id and nothing else, so there is no basis for
		// choosing. First-match (what this route did) is the worst of the available
		// guesses: the aggregates keep the LAST row, so editing the payment of an
		// earlier duplicate is written to the sheet, answered {success:true}, and then
		// discarded by every total that reads it — while the period guard reasoned
		// about the months of a row that contributes nothing. #223 measured 87 load
		// ids sitting on 2+ rows inside locked months.
		const candidateRows = [...new Set([...exactRows, ...normRows])].sort((a, b) => a - b);
		if (candidateRows.length > 1) {
			const shown = candidateRows.map((i) => i + 1);
			return res.status(409).json({
				error: `Load '${loadId}' matches ${candidateRows.length} rows in Job Tracking (rows ${shown.join(", ")}). Every total in this app collapses duplicate load ids to the last row, so writing one of them cannot be shown to change what the app reads. Edit the row directly with PUT /api/data/<rowIndex>, or make the load ids unique.`,
				code: "AMBIGUOUS_LOAD",
				rowIndexes: shown,
			});
		}

		const matchIdx = candidateRows[0];
		const rowIndex = matchIdx + 1;
		const before = rows[matchIdx] || [];

		// The row as it will be written. Object.prototype.hasOwnProperty.call, not
		// updates.hasOwnProperty — a body carrying its own "hasOwnProperty" key
		// shadows the method and turns this into a TypeError 500.
		const updatedRow = headers.map((h, idx) => {
			if (Object.prototype.hasOwnProperty.call(updates, h)) return updates[h];
			return before[idx] || "";
		});
		const after = sheetRowAfterUpdate(before, updatedRow);
		const changes = changedGuardedCells(headers, before, after);

		// Reject investors.id typos before anything is written, exactly as
		// PUT /api/data does. A no-op on any layout without an "Owner ID" header.
		if (guarded) {
			const ownerErr = validateOwnerIdCell(sheetName, headers, updatedRow);
			if (ownerErr) return res.status(400).json({ error: ownerErr.error });
		}

		const auditDetails = (outcome, extra) => buildSheetUpdateAudit({
			outcome,
			sheet: sheetName,
			rowIndex,
			loadId,
			via: "PUT /api/load/:loadId",
			// Every changed cell, guarded or not — the audit's job is to make the
			// write reversible by hand, and a corrected address is as much a change as
			// a corrected payment.
			changed: (() => {
				const out = [];
				for (let i = 0; i < Math.max(headers.length, before.length, after.length); i++) {
					const from = before[i] == null ? "" : String(before[i]);
					const to = after[i] == null ? "" : String(after[i]);
					if (from === to) continue;
					out.push({ column: String(headers[i] == null ? "" : headers[i]).trim() || "(unnamed)", index: i, from, to, why: guardedColumnReason(headers[i]) || "" });
				}
				return out;
			})(),
			guardedChanged: changes,
			...extra,
		});

		// ⚠️ A LOAD ID CHANGE REACHES A ROW THIS GUARD NEVER LOOKED AT — the hole #218
		// closed on PUT /api/data/:rowIndex, and free here because the whole sheet is
		// already in memory. deduplicateLoads() keeps the LAST row for a colliding id,
		// so retyping this row's Load ID onto a completed load sitting in a finalized
		// month shadows that load out of every total: both sides of the EDITED row are
		// open, so the period guard sees nothing to refuse.
		if (guarded) {
			const lidChange = changes.find((c) => /load.?id|job.?id/i.test(c.column));
			if (lidChange) {
				const target = normLid(lidChange.to);
				let collision = null;
				if (target) {
					for (let i = 1; i < rows.length; i++) {
						if (i === matchIdx) continue;
						if (normLid((rows[i] || [])[loadIdIdx]) === target) { collision = i + 1; break; }
					}
				}
				if (collision) {
					logAudit(req, "update_sheet_row_blocked", "sheet_row", `${sheetName}!${rowIndex}`, sheetAuditWithCode(auditDetails("blocked", { code: "DUPLICATE_LOAD" }), "DUPLICATE_LOAD"));
					return res.status(409).json({
						error: `Load ID '${lidChange.to}' already exists on row ${collision}. Two rows sharing a load id are collapsed to one everywhere the app totals revenue, so this would silently drop that row's figures — including out of a finalized month. Use a unique load id.`,
						code: "DUPLICATE_LOAD",
						conflictRowIndex: collision,
					});
				}
			}
		}

		const blocker = sheetRowUpdateBlocker(guarded, headers, before, after, changes);
		if (blocker) {
			// Record the attempt. `super_admin` is a shared login, so a refusal that
			// left no trace would make a repeated attempt to rewrite a closed month
			// invisible in the one place anyone looks afterwards.
			// logAuditRefusal, not logAudit — see the create twin in POST /api/data. Every
			// code sheetRowUpdateBlocker() can answer here is a PERIOD_* one and all three
			// are in UNCOALESCED_REFUSAL_CODES, so this is byte-identical today: still one
			// row per attempt, still carrying its own sheet address and month list. What it
			// buys is that the action now declares its coalescing rule in one place, and
			// the sibling refusals on this same action (DUPLICATE_LOAD, SHEET_CHANGED) —
			// which ARE reachable on demand — are the ones a future reader will reach for.
			logAuditRefusal(req, "update_sheet_row_blocked", "sheet_row", `${sheetName}!${rowIndex}`, sheetAuditWithCode(auditDetails("blocked", { code: blocker.code, periods: blocker.periods }), blocker.code), blocker.code);
			return res.status(409).json({
				error: blocker.error,
				code: blocker.code,
				periods: blocker.periods,
				...(blocker.changed ? { changed: blocker.changed } : {}),
				...(blocker.unreadable ? { unreadable: blocker.unreadable } : {}),
			});
		}

		// ⚠️ RE-READ IMMEDIATELY BEFORE WRITING, for the same reason PUT /api/data and
		// POST /api/admin/remove-rows do. The whole sheet was read at the top of this
		// handler; a delete landing since then shifts every following row up, so the
		// index this load id resolved to now points at a different load, and the write
		// would overwrite a row the guard never evaluated while the audit records a
		// `before` describing another load. `values.update` leaves a plausible-looking
		// row where a delete at least leaves a hole.
		if (guarded) {
			let fresh = null;
			try {
				const re = await sheets.spreadsheets.values.get({
					spreadsheetId: SPREADSHEET_ID,
					range: `${a1}!${rowIndex}:${rowIndex}`,
				});
				fresh = ((re.data.values || [[]])[0]) || [];
			} catch (err) {
				logAudit(req, "update_sheet_row_blocked", "sheet_row", `${sheetName}!${rowIndex}`, sheetAuditWithCode(auditDetails("blocked", { code: "ROW_READ_FAILED", error: err.message }), "ROW_READ_FAILED"));
				return res.status(409).json({
					error: "The row could not be re-read immediately before writing, so it cannot be confirmed to be the row that was checked. Try again.",
					code: "ROW_READ_FAILED",
				});
			}
			const same = (a, b) => {
				const n = Math.max(a.length, b.length);
				for (let i = 0; i < n; i++) if (String(a[i] == null ? "" : a[i]) !== String(b[i] == null ? "" : b[i])) return false;
				return true;
			};
			if (!same(fresh, before)) {
				logAudit(req, "update_sheet_row_blocked", "sheet_row", `${sheetName}!${rowIndex}`, sheetAuditWithCode(auditDetails("blocked", { code: "SHEET_CHANGED" }), "SHEET_CHANGED"));
				return res.status(409).json({
					error: `Row ${rowIndex} changed while this edit was being checked — another write, or a deleted row shifting the sheet up, means load '${loadId}' no longer resolves to the row that was validated. Re-read the load and try again.`,
					code: "SHEET_CHANGED",
				});
			}
		}

		try {
			await sheets.spreadsheets.values.update({
				spreadsheetId: SPREADSHEET_ID,
				range: `${a1}!A${rowIndex}`,
				valueInputOption: "USER_ENTERED",
				requestBody: { values: [updatedRow] },
			});
		} catch (err) {
			// Audit the failed attempt too. A timed-out Sheets write leaves it
			// genuinely unknown whether the row changed, and that is precisely when the
			// before/after values are worth having.
			logAudit(req, "update_sheet_row_failed", "sheet_row", `${sheetName}!${rowIndex}`, auditDetails("failed", { error: err.message }));
			throw err;
		}

		logAudit(req, "update_sheet_row", "sheet_row", `${sheetName}!${rowIndex}`, auditDetails("updated"));
		// The 60s Job Tracking cache would otherwise keep serving the old figures.
		if (guarded) jtCacheInvalidate();

		// Return updated load — unchanged response shape.
		const result = {};
		headers.forEach((h, idx) => { result[h] = updatedRow[idx]; });
		result._rowIndex = rowIndex;
		res.json({ success: true, load: result });
	} catch (error) {
		console.error("Error updating load:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// Decode Google Maps encoded polyline to [{latitude, longitude}] array
function decodePolyline(encoded) {
	const points = [];
	let index = 0, lat = 0, lng = 0;
	while (index < encoded.length) {
		let b, shift = 0, result = 0;
		do { b = encoded.charCodeAt(index++) - 63; result |= (b & 0x1f) << shift; shift += 5; } while (b >= 0x20);
		lat += (result & 1) ? ~(result >> 1) : (result >> 1);
		shift = 0; result = 0;
		do { b = encoded.charCodeAt(index++) - 63; result |= (b & 0x1f) << shift; shift += 5; } while (b >= 0x20);
		lng += (result & 1) ? ~(result >> 1) : (result >> 1);
		points.push({ latitude: lat / 1e5, longitude: lng / 1e5 });
	}
	return points;
}

// Forward geocode address → lat/lng with SQLite cache
async function geocodeAddress(address) {
	if (!address || address.trim().length < 5) return null;
	const key = address.trim().toLowerCase();
	// Check cache
	const cached = db.prepare("SELECT lat, lng FROM geocode_cache WHERE address = ?").get(key);
	if (cached) return cached.lat ? { lat: cached.lat, lng: cached.lng } : null;
	// Call Google Geocoding API. 5s abort — this now runs inline in the expense
	// submit path, so a hung Google call must not hang the driver's POST.
	try {
		const controller = new AbortController();
		const timeout = setTimeout(() => controller.abort(), 5000);
		const resp = await fetch(`https://maps.googleapis.com/maps/api/geocode/json?address=${encodeURIComponent(address)}&key=${GOOGLE_MAPS_API_KEY}`, { signal: controller.signal });
		clearTimeout(timeout);
		const data = await resp.json();
		if (data.status === "OK" && data.results && data.results.length > 0) {
			const loc = data.results[0].geometry.location;
			db.prepare("INSERT OR REPLACE INTO geocode_cache (address, lat, lng) VALUES (?, ?, ?)").run(key, loc.lat, loc.lng);
			return { lat: loc.lat, lng: loc.lng };
		}
		// Only a definitive "no such place" is worth remembering. Caching null on
		// quota blips / transient errors would permanently poison real cities in
		// the shared geocode_cache (backfill + live inserts both read it).
		if (data.status === "ZERO_RESULTS") {
			db.prepare("INSERT OR REPLACE INTO geocode_cache (address, lat, lng) VALUES (?, NULL, NULL)").run(key);
		}
	} catch { /* transient — do not cache */ }
	return null;
}

// Reverse geocode coordinates to a formatted address using Google Geocoding API
async function geocodeReverse(lat, lng) {
	try {
		const controller = new AbortController();
		const timeout = setTimeout(() => controller.abort(), 5000);
		const resp = await fetch(`https://maps.googleapis.com/maps/api/geocode/json?latlng=${lat},${lng}&key=${GOOGLE_MAPS_API_KEY}`, { signal: controller.signal });
		clearTimeout(timeout);
		if (!resp.ok) return null;
		const data = await resp.json();
		if (data.status !== "OK" || !data.results || data.results.length === 0) return null;
		return data.results[0].formatted_address || null;
	} catch {
		return null;
	}
}

// Route cache: TTL-based in-memory cache for Google Routes API results
const routeCache = new Map();
const ROUTE_CACHE_TTL = 15 * 60 * 1000; // 15 minutes
const ROUTE_CACHE_MAX = 500;            // hard cap on entry COUNT
// Byte budget — the real OOM guard. A single `alternatives` entry can hold 3
// routes x ~10k-point decoded polylines (~2.5MB JSON / ~10MB in-heap), so a
// count-only cap of 500 let the cache grow to multiple GB and blow Node's
// ~2GB heap (crash always landed in JSON.stringify of a route response or the
// shutdown snapshot). We now also cap total cached bytes; in-heap is ~3-6x the
// figure below, so ~96MB of estimated payload ≈ ~300-500MB heap.
// ⚠️ BUDGET IMPLICATION OF ROUTE_NAV_POINTS_MAX (below). A rich `alternatives`
// entry now carries up to 3 routes x 4000 points instead of 3 x 1500, so a
// worst-case nav entry is ~2.7x fatter: estimateRouteBytes() puts it at ~480 KB
// against ~180 KB, i.e. ~1.9 MB in-heap against ~700 KB. The BUDGET IS UNCHANGED
// and still holds — it is a byte cap, not an entry cap, so it simply evicts
// sooner: ~200 concurrent nav lanes fit here instead of ~530, and the count cap
// (ROUTE_CACHE_MAX, 500) stops being the binding constraint for nav entries. The
// persisted snapshot (ROUTE_SNAPSHOT_MAX_BYTES, 8 MB) likewise holds FEWER
// entries across a restart — ~17 nav lanes instead of ~45 — which costs a cold
// Google call on the lanes that fall off, never correctness. Both are the right
// trade: lean single-route callers (the admin tracking map, the public customer
// tracker) are untouched at 1500 and are the overwhelming majority of entries.
const ROUTE_CACHE_MAX_BYTES = 96 * 1024 * 1024;
const ROUTE_POINTS_MAX = 1500;          // cap decoded polyline points per route
// ⚠️ NAV-GRADE GEOMETRY, AND 1500 IS NOT ENOUGH FOR IT. ROUTE_POINTS_MAX is a
// MAP budget: at ~540 m between points on a 500-mile route it is visually
// identical at any zoom a human looks at, which is all it was ever asked to be.
// It is not enough to decide whether a truck is ON the road, and that is what
// the `alternatives` payload is used for.
//
// Chord error on a downsampled polyline is ~L²/8R. A 500 m chord across a 300 m
// radius interchange curve puts the stored line ~104 m from the real road — and
// 104 m is LARGER than any off-route threshold worth having (a usable one is
// 50-80 m; below ~40 m ordinary GPS scatter trips it). So a truck driving the
// route perfectly reads as off-route at every curve, and deviation detection
// reroutes continuously. Raising the budget to 4000 puts the same curve at
// ~200 m spacing and ~17 m of chord error — comfortably inside the threshold,
// with the error now dominated by GPS accuracy rather than by our own geometry.
//
// APPLIED ONLY ON THE `alternatives` PATH. The lean single-route response feeds
// map rendering, where 1500 is already indistinguishable and 4000 would be 2.7x
// the bytes for nothing. Two budgets because there are genuinely two questions.
const ROUTE_NAV_POINTS_MAX = 4000;      // cap decoded polyline points per NAV route
const ROUTE_STEP_POINTS_MAX = 60;       // cap per-step sub-polyline points
const ROUTE_SNAPSHOT_MAX_BYTES = 8 * 1024 * 1024; // cap persisted snapshot size
let routeCacheBytes = 0;                // running estimate of cached result bytes

// Uniformly downsample a [{latitude,longitude},...] array to at most `max`
// points, always keeping the first and last. Visually identical at map zoom
// levels but collapses cross-country polylines from ~10k points to ~1.5k —
// the single biggest lever on per-entry memory.
function downsamplePoints(points, max) {
	if (!Array.isArray(points) || points.length <= max || max < 2) return points;
	const out = new Array(max);
	const stride = (points.length - 1) / (max - 1);
	for (let i = 0; i < max; i++) out[i] = points[Math.round(i * stride)];
	return out;
}

// Approximate the heap-relevant size of a cached route result. We count
// decoded points (the dominant cost) rather than JSON.stringify, which would
// itself allocate megabytes per call. ~40 bytes/point is a conservative
// in-heap estimate for a {latitude, longitude} object plus array slot.
function estimateRouteBytes(result) {
	if (!result) return 64;
	let pts = 0;
	if (Array.isArray(result.points)) pts += result.points.length;
	if (Array.isArray(result.routes)) {
		for (const r of result.routes) {
			if (Array.isArray(r.points)) pts += r.points.length;
			if (Array.isArray(r.steps)) {
				for (const s of r.steps) if (Array.isArray(s.polyline)) pts += s.polyline.length;
			}
		}
	}
	return 256 + pts * 40;
}

// Insert into the route cache with TTL-aware + byte-budget eviction. Replaces
// the old count-only FIFO so fat multi-MB entries can't accumulate to GB.
// Sweeps expired entries first, then evicts oldest (Map preserves insertion
// order) until BOTH the count and byte budgets are satisfied.
function routeCacheStore(key, entry) {
	const now = Date.now();
	const existing = routeCache.get(key);
	if (existing) {
		routeCacheBytes -= existing._bytes || 0;
		routeCache.delete(key);
	}
	for (const [k, v] of routeCache) {
		if (typeof v.time !== "number" || now - v.time >= ROUTE_CACHE_TTL) {
			routeCacheBytes -= v._bytes || 0;
			routeCache.delete(k);
		}
	}
	entry._bytes = estimateRouteBytes(entry.result);
	routeCache.set(key, entry);
	routeCacheBytes += entry._bytes;
	while (routeCache.size > ROUTE_CACHE_MAX || routeCacheBytes > ROUTE_CACHE_MAX_BYTES) {
		const oldestKey = routeCache.keys().next().value;
		if (oldestKey === undefined) break;
		const oldest = routeCache.get(oldestKey);
		routeCacheBytes -= (oldest && oldest._bytes) || 0;
		routeCache.delete(oldestKey);
	}
	if (routeCacheBytes < 0) routeCacheBytes = 0; // guard against drift
}

function routeCacheKey(from, to, alternatives = false) {
	// Round to 3 decimal places (~111m precision) to group nearby positions.
	// `|alt` suffix keeps the rich (alternatives + traffic + fuel + tolls)
	// payload separate from the lean single-route payload — same waypoints
	// produce different responses, so they must not collide in the cache.
	const base = `${from.latitude.toFixed(3)},${from.longitude.toFixed(3)}>${to.latitude.toFixed(3)},${to.longitude.toFixed(3)}`;
	return alternatives ? `${base}|alt` : base;
}

// Parse one Google Routes API v2 route into the LogisX rich-route shape.
// Handles missing optional fields (no traffic data, toll-free roads, etc.)
// by returning null for that field so the client can render gracefully.
function parseRichRoute(googleRoute) {
	if (!googleRoute || !googleRoute.legs || googleRoute.legs.length === 0) return null;
	const leg = googleRoute.legs[0];
	const durationSec = parseInt((leg.duration || "0s").replace("s", ""), 10);
	const pointsRaw = googleRoute.polyline?.encodedPolyline
		? decodePolyline(googleRoute.polyline.encodedPolyline)
		: [];
	if (pointsRaw.length < 2) return null;
	// ROUTE_NAV_POINTS_MAX, not ROUTE_POINTS_MAX: parseRichRoute is only ever
	// reached from the `alternatives` branch of getRoute(), which is the driver's
	// navigation payload. See the constant for why a map budget is not a
	// navigation budget.
	const points = downsamplePoints(pointsRaw, ROUTE_NAV_POINTS_MAX);
	// speedReadingIntervals index into the *full* polyline; rescale those indices
	// to the downsampled `points` array so the client's congestion overlay
	// (DriverRouteMap / DriveModeOverlay) still lines up after downsampling.
	// `steps[].startIdx` below is rescaled through the same factor, for the same
	// reason — both are positions in `points`, so both must survive downsampling.
	const ptScale = (points.length !== pointsRaw.length && pointsRaw.length > 1)
		? (points.length - 1) / (pointsRaw.length - 1)
		: 1;

	const adv = googleRoute.travelAdvisory || {};
	let fuelLiters = null;
	if (adv.fuelConsumptionMicroliters) {
		const microL = parseInt(adv.fuelConsumptionMicroliters, 10);
		if (Number.isFinite(microL)) fuelLiters = microL / 1e6;
	}
	let tollPriceUsd = null;
	if (adv.tollInfo?.estimatedPrice?.length) {
		// Sum USD entries; non-USD currencies fall through as null so the UI
		// doesn't pretend a Mexican-peso toll is dollars.
		const usd = adv.tollInfo.estimatedPrice.find(p => p.currencyCode === "USD");
		if (usd) {
			const units = parseInt(usd.units || "0", 10) || 0;
			const nanos = parseInt(usd.nanos || 0, 10) || 0;
			tollPriceUsd = units + nanos / 1e9;
		}
	}
	let trafficSegments = null;
	if (Array.isArray(adv.speedReadingIntervals) && adv.speedReadingIntervals.length) {
		trafficSegments = adv.speedReadingIntervals
			.filter(s => s.speed)
			.map(s => ({
				startIdx: Math.round((s.startPolylinePointIndex || 0) * ptScale),
				endIdx: Math.round((s.endPolylinePointIndex || 0) * ptScale),
				congestion: s.speed, // NORMAL | SLOW | TRAFFIC_JAM
			}));
	}
	let steps = null;
	if (Array.isArray(leg.steps) && leg.steps.length) {
		// `startIdx` — where in `points` this step BEGINS. Without it a client
		// holding "you are at polyline index 812" cannot say which instruction is
		// current, so turn-by-turn has to re-derive the answer by scanning every
		// step's sub-polyline for the nearest vertex on every GPS tick. That scan
		// is also wrong at any point where the route crosses or doubles back on
		// itself, because nearest-vertex has no notion of progress along the route.
		//
		// Google's Routes API does not hand us a point index (we do not request
		// startLocation, and it would be a coordinate rather than an index anyway),
		// but the step polylines CONCATENATE to the route polyline sharing one
		// vertex at each seam — so step i begins at sum over j<i of (len_j - 1).
		//
		// ⚠️ COUNTED ON THE RAW DECODED STEP POLYLINE, BEFORE DOWNSAMPLING. The
		// output polyline is capped at ROUTE_STEP_POINTS_MAX (60), so accumulating
		// the downsampled lengths would under-count every step longer than 60
		// points and drift the offset further wrong with each one — silently, and
		// worst on exactly the long highway steps where it matters least to notice.
		let cumRaw = 0;
		let offsetKnown = true;
		steps = leg.steps.map(s => {
			const raw = s.polyline?.encodedPolyline ? decodePolyline(s.polyline.encodedPolyline) : null;
			// ⚠️ A STEP WITH NO POLYLINE BREAKS THE CHAIN, AND THE HONEST ANSWER IS
			// null. The field mask requests every step polyline so this should not
			// happen, but if one is ever missing we cannot know how many points it
			// spanned — and carrying on would report every LATER step at an offset
			// short by that step's length, which is a confidently wrong instruction
			// rather than an absent one. Once broken it stays broken for the rest of
			// the leg; a client must treat null as "scan for it yourself".
			const startIdx = offsetKnown
				? Math.min(Math.round(cumRaw * ptScale), Math.max(points.length - 1, 0))
				: null;
			if (raw && raw.length > 0) cumRaw += raw.length - 1;
			else offsetKnown = false;
			return {
				instruction: s.navigationInstruction?.instructions || "",
				maneuver: s.navigationInstruction?.maneuver || "",
				distanceMeters: s.distanceMeters || 0,
				durationSec: parseInt((s.staticDuration || "0s").replace("s", ""), 10),
				startIdx,
				polyline: raw ? downsamplePoints(raw, ROUTE_STEP_POINTS_MAX) : null,
			};
		});
	}

	return {
		points,
		distanceMiles: Math.round(leg.distanceMeters / 160.934) / 10,
		durationMin: Math.round(durationSec / 60),
		fuelLiters,
		tollPriceUsd,
		trafficSegments,
		steps,
	};
}

// Pick the best route by weighted score of normalized time + fuel + tolls.
// Lower score wins. If fuel or tolls are missing on any route, drop that
// factor from the comparison (renormalize weights) — penalizing a route for
// missing data would just pick whichever route Google happened to compute
// the metric for, not the actually best one.
function scoreRoutes(routes) {
	if (!routes || routes.length === 0) return 0;
	if (routes.length === 1) return 0;
	const hasFuel = routes.every(r => typeof r.fuelLiters === "number" && isFinite(r.fuelLiters));
	const hasTolls = routes.every(r => typeof r.tollPriceUsd === "number" && isFinite(r.tollPriceUsd));
	const wTime = 0.5;
	const wFuel = hasFuel ? 0.35 : 0;
	const wTolls = hasTolls ? 0.15 : 0;
	const wSum = wTime + wFuel + wTolls;
	function norm(vals, v) {
		const lo = Math.min(...vals);
		const hi = Math.max(...vals);
		if (hi === lo) return 0;
		return (v - lo) / (hi - lo);
	}
	const times = routes.map(r => r.durationMin);
	const fuels = hasFuel ? routes.map(r => r.fuelLiters) : null;
	const tolls = hasTolls ? routes.map(r => r.tollPriceUsd) : null;
	let bestIdx = 0;
	let bestScore = Infinity;
	for (let i = 0; i < routes.length; i++) {
		const tn = norm(times, times[i]);
		const fn = hasFuel ? norm(fuels, fuels[i]) : 0;
		const ton = hasTolls ? norm(tolls, tolls[i]) : 0;
		const score = (wTime * tn + wFuel * fn + wTolls * ton) / wSum;
		if (score < bestScore) { bestScore = score; bestIdx = i; }
	}
	return bestIdx;
}

// Persist routeCache across pm2 restarts via a single SQLite row. Avoids the
// per-deploy burst of cold Google Routes calls when many customers are
// actively tracking the same in-flight loads. No per-request DB writes —
// snapshot is taken on graceful shutdown only.
db.exec(`
	CREATE TABLE IF NOT EXISTS server_state (
		key TEXT PRIMARY KEY,
		value TEXT NOT NULL,
		updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
	)
`);
function loadRouteCacheSnapshot() {
	try {
		const row = db.prepare("SELECT value FROM server_state WHERE key = ?").get("route_cache_snapshot");
		if (!row || !row.value) return;
		const data = JSON.parse(row.value);
		if (!Array.isArray(data)) return;
		const now = Date.now();
		let hydrated = 0;
		for (const [k, v] of data) {
			if (v && v.result && typeof v.time === "number" && now - v.time < ROUTE_CACHE_TTL) {
				// Route through routeCacheStore so the byte tally + budget eviction
				// apply to hydrated entries too (snapshot is already byte-capped, but
				// this keeps routeCacheBytes accurate from boot).
				routeCacheStore(k, { result: v.result, time: v.time });
				hydrated++;
			}
		}
		if (hydrated > 0) console.log(`[route-cache] hydrated ${hydrated} entries from snapshot`);
	} catch (err) {
		console.error("[route-cache] hydrate failed:", err.message);
	}
}
function saveRouteCacheSnapshot() {
	try {
		const entries = [];
		const now = Date.now();
		let bytes = 0;
		for (const [k, v] of routeCache.entries()) {
			// Only persist successful, unexpired results — nulls are transient API
			// errors that should be retried on next attempt, not served stale.
			if (!(v && v.result && typeof v.time === "number" && now - v.time < ROUTE_CACHE_TTL)) continue;
			// Byte-cap the persisted blob so a graceful restart can't OOM inside
			// JSON.stringify (the original crash signature). Stop once we'd exceed
			// the budget rather than serializing the whole cache.
			const est = v._bytes || estimateRouteBytes(v.result);
			if (bytes + est > ROUTE_SNAPSHOT_MAX_BYTES) break;
			bytes += est;
			// Strip the internal _bytes bookkeeping field from the persisted shape.
			entries.push([k, { result: v.result, time: v.time }]);
		}
		db.prepare(`INSERT OR REPLACE INTO server_state (key, value, updated_at) VALUES (?, ?, CURRENT_TIMESTAMP)`)
			.run("route_cache_snapshot", JSON.stringify(entries));
		console.log(`[route-cache] snapshot saved: ${entries.length} entries`);
	} catch (err) {
		console.error("[route-cache] snapshot failed:", err.message);
	}
}
loadRouteCacheSnapshot();

// Get driving route between two points using Google Routes API.
// opts.alternatives:
//   false (default) → single lean route, shape { points, distanceMiles, durationMin }
//   true            → up to 3 alternatives with traffic/fuel/tolls + steps,
//                     shape { routes: [...], recommendedIdx }
// The two response shapes are cached separately (see routeCacheKey) so a
// lean caller can't poison the rich cache and vice versa.
async function getRoute(from, to, opts = {}, retries = 2) {
	if (!from || !to) return null;
	// Skip impossible routes (e.g. cross-ocean) — max ~5000 km straight-line
	const distM = geolib.getDistance(from, to);
	if (distM > 5000000) return null;

	const alternatives = opts.alternatives === true;
	// Check cache before calling API
	const cacheKey = routeCacheKey(from, to, alternatives);
	const cached = routeCache.get(cacheKey);
	if (cached && Date.now() - cached.time < ROUTE_CACHE_TTL) {
		return cached.result;
	}

	const reqBody = {
		origin: { location: { latLng: { latitude: from.latitude, longitude: from.longitude } } },
		destination: { location: { latLng: { latitude: to.latitude, longitude: to.longitude } } },
		travelMode: "DRIVE",
	};
	let fieldMask = "routes.polyline,routes.legs.distanceMeters,routes.legs.duration";
	if (alternatives) {
		reqBody.computeAlternativeRoutes = true;
		reqBody.routingPreference = "TRAFFIC_AWARE_OPTIMAL";
		reqBody.extraComputations = ["FUEL_CONSUMPTION", "TOLLS", "TRAFFIC_ON_POLYLINE"];
		reqBody.routeModifiers = { vehicleInfo: { emissionType: "DIESEL" } };
		reqBody.polylineQuality = "HIGH_QUALITY";
		fieldMask = [
			"routes.polyline",
			"routes.legs.distanceMeters",
			"routes.legs.duration",
			"routes.travelAdvisory.fuelConsumptionMicroliters",
			"routes.travelAdvisory.tollInfo.estimatedPrice",
			"routes.travelAdvisory.speedReadingIntervals",
			"routes.legs.steps.navigationInstruction",
			"routes.legs.steps.distanceMeters",
			"routes.legs.steps.staticDuration",
			"routes.legs.steps.polyline.encodedPolyline",
		].join(",");
	}

	for (let attempt = 0; attempt <= retries; attempt++) {
		try {
			const controller = new AbortController();
			const timeout = setTimeout(() => controller.abort(), 10000);
			const resp = await fetch("https://routes.googleapis.com/directions/v2:computeRoutes", {
				method: "POST",
				headers: {
					"Content-Type": "application/json",
					"X-Goog-Api-Key": GOOGLE_MAPS_API_KEY,
					"X-Goog-FieldMask": fieldMask,
				},
				body: JSON.stringify(reqBody),
				signal: controller.signal,
			});
			clearTimeout(timeout);
			if (!resp.ok) {
				const errText = await resp.text();
				console.error(`Routes API HTTP error (attempt ${attempt + 1}): ${resp.status} — ${errText}`);
				if (attempt < retries) { await new Promise(r => setTimeout(r, 500 * (attempt + 1))); continue; }
				routeCacheStore(cacheKey, { result: null, time: Date.now() });
				return null;
			}
			const data = await resp.json();
			if (!data.routes || data.routes.length === 0) {
				routeCacheStore(cacheKey, { result: null, time: Date.now() });
				return null;
			}

			let result;
			if (alternatives) {
				const richRoutes = data.routes
					.map(r => parseRichRoute(r))
					.filter(r => r !== null);
				if (richRoutes.length === 0) {
					routeCacheStore(cacheKey, { result: null, time: Date.now() });
					return null;
				}
				result = { routes: richRoutes, recommendedIdx: scoreRoutes(richRoutes) };
			} else {
				const route = data.routes[0];
				const leg = route.legs[0];
				const durationSec = parseInt((leg.duration || "0s").replace("s", ""), 10);
				result = {
					points: downsamplePoints(decodePolyline(route.polyline.encodedPolyline), ROUTE_POINTS_MAX),
					distanceMiles: Math.round(leg.distanceMeters / 160.934) / 10,
					durationMin: Math.round(durationSec / 60),
				};
			}
			routeCacheStore(cacheKey, { result, time: Date.now() });
			return result;
		} catch (err) {
			console.error(`Routes API error (attempt ${attempt + 1}/${retries + 1}):`, err.message);
			if (attempt < retries) { await new Promise(r => setTimeout(r, 500 * (attempt + 1))); continue; }
			return null;
		}
	}
	return null;
}

// GET /api/locations/trail — ELD trail for a specific driver/load
app.get("/api/locations/trail", requireRole("Super Admin", "Dispatcher"), async (req, res) => {
	try {
		const { driver, loadId } = req.query;
		if (!driver) {
			return res.status(400).json({ error: "driver query param required" });
		}

		// Sourced from Routemate telemetry. Resolve the driver's currently-assigned
		// truck, then pull the last 24h of telemetry for that vehicle. When a
		// historical loadId is requested we still scope to the same truck — older
		// trips off this truck aren't recoverable from ELD alone.
		const assignment = db.prepare(
			`SELECT ta.truck_id, t.routemate_vehicle_id
			 FROM truck_assignments ta
			 JOIN trucks t ON t.id = ta.truck_id
			 WHERE LOWER(TRIM(ta.driver_name)) = LOWER(TRIM(?))
			   AND COALESCE(t.routemate_vehicle_id, '') <> ''
			 ORDER BY ta.end_date = '' DESC, ta.start_date DESC
			 LIMIT 1`
		).get(driver);

		let rawPoints = [];
		if (assignment && assignment.routemate_vehicle_id) {
			const cutoffMs = Date.now() - 24 * 60 * 60 * 1000;
			const rows = db.prepare(
				`SELECT latitude, longitude, speed, location_date_ms
				 FROM routemate_telemetry
				 WHERE routemate_vehicle_id = ?
				   AND location_date_ms > ?
				   AND dropped_reason = ''
				 ORDER BY location_date_ms ASC`
			).all(assignment.routemate_vehicle_id, cutoffMs);
			rawPoints = rows.map((r) => ({
				latitude: r.latitude,
				longitude: r.longitude,
				speed: r.speed || 0,
				timestamp: new Date(r.location_date_ms).toISOString(),
			}));
		}
		// loadId is accepted for backward compatibility but not used as a filter —
		// telemetry isn't tagged with loadId on the ELD side. Kept here to avoid
		// breaking callers that still pass it.
		void loadId;

		// Simplify: skip consecutive points < 10m apart, always keep first and last
		const simplified = [];
		for (let i = 0; i < rawPoints.length; i++) {
			if (i === 0 || i === rawPoints.length - 1) {
				simplified.push(rawPoints[i]);
				continue;
			}
			const prev = simplified[simplified.length - 1];
			const dist = geolib.getDistance(
				{ latitude: prev.latitude, longitude: prev.longitude },
				{ latitude: rawPoints[i].latitude, longitude: rawPoints[i].longitude }
			);
			if (dist >= 10) {
				simplified.push(rawPoints[i]);
			}
		}

		// Cap at 2000 points
		const trail = simplified.length > 2000 ? simplified.slice(-2000) : simplified;

		// Look up origin/destination from sheet
		let origin = null;
		let destination = null;
		if (loadId) {
			try {
				const sheets = await getSheets();
				const headerResp = await sheets.spreadsheets.values.get({
					spreadsheetId: SPREADSHEET_ID,
					range: "Job Tracking!1:1",
				});
				const headers = (headerResp.data.values || [[]])[0];
				const dataResp = await sheets.spreadsheets.values.get({
					spreadsheetId: SPREADSHEET_ID,
					range: "Job Tracking",
				});
				const rows = dataResp.data.values || [];

				const loadIdCol = headers.find((h) => /load.?id|job.?id/i.test(h));
				const originLatCol = headers.find((h) => /origin.*lat|pickup.*lat|shipper.*lat/i.test(h));
				const originLngCol = headers.find((h) => /origin.*l(on|ng)|pickup.*l(on|ng)|shipper.*l(on|ng)/i.test(h));
				const destLatCol = headers.find((h) => /dest.*lat|drop.*lat|receiver.*lat|delivery.*lat/i.test(h));
				const destLngCol = headers.find((h) => /dest.*l(on|ng)|drop.*l(on|ng)|receiver.*l(on|ng)|delivery.*l(on|ng)/i.test(h));

				// Find address/city columns for origin and destination
				const originAddrCol = pickAddressColumn(headers, /origin|pickup|shipper/i);
				const destAddrCol = pickAddressColumn(headers, /dest|drop|receiver|delivery/i);

				if (loadIdCol) {
					const statusCol = headers.find((h) => /status/i.test(h));
					const completedRe = /^(delivered|completed|pod received|canceled)$/i;
					// Collect all matching rows, prefer active over completed
					let bestMatch = null;
					for (let i = 1; i < rows.length; i++) {
						const obj = {};
						headers.forEach((h, idx) => { obj[h] = rows[i][idx] || ""; });
						const lid = (obj[loadIdCol] || "").trim().replace(/^#/, "");
						if (lid === loadId || obj[loadIdCol] === loadId) {
							const status = statusCol ? (obj[statusCol] || "").trim() : "";
							if (!completedRe.test(status)) {
								bestMatch = obj;
								break; // Active row found — use it
							}
							if (!bestMatch) bestMatch = obj; // Fallback to first match
						}
					}
					if (bestMatch) {
						if (originLatCol && originLngCol) {
							const oLat = parseFloat(bestMatch[originLatCol]);
							const oLng = parseFloat(bestMatch[originLngCol]);
							if (!isNaN(oLat) && !isNaN(oLng)) origin = { latitude: oLat, longitude: oLng };
						}
						if (destLatCol && destLngCol) {
							const dLat = parseFloat(bestMatch[destLatCol]);
							const dLng = parseFloat(bestMatch[destLngCol]);
							if (!isNaN(dLat) && !isNaN(dLng)) destination = { latitude: dLat, longitude: dLng };
						}
						if (origin && originAddrCol) origin.address = bestMatch[originAddrCol] || "";
						if (destination && destAddrCol) destination.address = bestMatch[destAddrCol] || "";
					}
				}
			} catch (sheetErr) {
				console.error("Trail sheet lookup error:", sheetErr.message);
			}
		}

		// Geocode addresses if missing from sheet data
		if (origin && !origin.address) origin.address = await geocodeReverse(origin.latitude, origin.longitude) || "";
		if (destination && !destination.address) destination.address = await geocodeReverse(destination.latitude, destination.longitude) || "";

		// Get planned route from driver's current position to destination
		let route = null;
		if (destination) {
			const currentPos = trail.length > 0
				? { latitude: trail[trail.length - 1].latitude, longitude: trail[trail.length - 1].longitude }
				: origin;
			if (currentPos) {
				route = await getRoute(currentPos, destination);
			}
			// Fallback: route from origin to destination if driver position route fails
			if (!route && origin) {
				route = await getRoute(origin, destination);
			}
		}

		res.json({
			trail,
			route: route ? route.points : null,
			distanceMiles: route ? route.distanceMiles : null,
			etaMinutes: route ? route.durationMin : null,
			origin,
			destination,
		});
	} catch (error) {
		console.error("Error fetching trail:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// This endpoint had NO limiter at all, which made it the cheapest billed Google
// call in the app to abuse: an authenticated caller supplies BOTH coordinate
// pairs, so routeCacheKey() — rounded to 3 decimals, ~111 m — is trivially
// missed by walking a coordinate, and every miss is a Routes call (the
// `alternatives` form on the TRAFFIC_AWARE_OPTIMAL + FUEL_CONSUMPTION + TOLLS +
// TRAFFIC_ON_POLYLINE tier, i.e. the expensive one). It is also the only Maps
// surface a Driver can drive with arbitrary coordinates.
//
// Modelled on fuelPlanLimiter, and per-USER for its reason rather than per-IP:
// IP keying is backwards here, since a dispatch office behind one NAT would
// share a single bucket while every driver on cellular gets a fresh one whenever
// the carrier rotates their address — throttling the cheap callers and not the
// expensive ones.
//
// 180 / 60 are set against real client behaviour, not guessed: TrackingMap
// refetches behind a 100 m + 60 s gate across two legs, so one continuously open
// map cannot exceed ~30 calls in a 15-minute window. Dispatch gets six such maps
// of headroom; a driver, running one load, gets two.
//
// ⚠️ MOUNTED AFTER requireRole, NOT BEFORE. Same ordering as fuelEventsLimiter
// and fuelGallonsLimiter: with the limiter first, an unauthenticated caller
// spends the whole bucket on 403s and locks out the legitimate user behind that
// key. It also lets the role-aware `max` read req.session.user, which only
// exists once requireRole has run.
const routeLimiter = rateLimit({
	windowMs: 15 * 60 * 1000,
	max: (req) => {
		const role = req.session?.user?.role;
		return role === "Super Admin" || role === "Dispatcher" ? 180 : 60;
	},
	keyGenerator: (req) => {
		const id = req.session?.user?.id;
		return id ? `u:${id}` : `ip:${ipKeyGenerator(req.ip)}`;
	},
	message: { error: "Too many route requests. Try again later." },
	standardHeaders: true,
});

// GET /api/route — Lightweight rerouting: get driving route between two points.
// ?alternatives=true requests up to 3 alternatives with traffic-aware ETAs,
// per-route fuel + toll estimates, traffic congestion segments, and turn-by-turn
// steps. Used by the driver's smart route guidance UI. Existing callers
// (admin tracking map, public customer tracker) omit the flag and receive the
// lean single-route payload unchanged.
app.get("/api/route", requireRole("Super Admin", "Dispatcher", "Driver"), routeLimiter, async (req, res) => {
	res.set('Cache-Control', 'private, max-age=300');
	try {
		const { fromLat, fromLng, toLat, toLng } = req.query;
		if (!fromLat || !fromLng || !toLat || !toLng) {
			return res.status(400).json({ error: "fromLat, fromLng, toLat, toLng required" });
		}
		const from = { latitude: parseFloat(fromLat), longitude: parseFloat(fromLng) };
		const to = { latitude: parseFloat(toLat), longitude: parseFloat(toLng) };
		const alternatives = req.query.alternatives === "true";
		const route = await getRoute(from, to, { alternatives });
		if (!route) {
			// Return empty route instead of 500 (e.g. cross-ocean routes OSRM can't compute)
			const distMiles = Math.round(geolib.getDistance(from, to) / 160.934) / 10;
			if (alternatives) {
				return res.json({ routes: [], recommendedIdx: 0, distanceMiles: distMiles, fallback: true });
			}
			return res.json({ route: null, distanceMiles: distMiles, etaMinutes: null, fallback: true });
		}
		if (alternatives) {
			// Translate internal shape (points / durationMin) → client shape
			// (route / etaMinutes) to match the rest of the API surface.
			return res.json({
				routes: route.routes.map(r => ({
					route: r.points,
					distanceMiles: r.distanceMiles,
					etaMinutes: r.durationMin,
					fuelLiters: r.fuelLiters,
					tollPriceUsd: r.tollPriceUsd,
					trafficSegments: r.trafficSegments,
					steps: r.steps,
				})),
				recommendedIdx: route.recommendedIdx,
			});
		}
		res.json({
			route: route.points,
			distanceMiles: route.distanceMiles,
			etaMinutes: route.durationMin,
		});
	} catch (error) {
		console.error("Error computing route:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// ── Fuel range + POI fuel stops (tracking quick-glance / fuel finder) ────────

// Express parses `?k[]=1` (and a repeated `?k=1&k=2`) into an ARRAY, so the
// usual `(req.query.k || "").trim()` throws a TypeError and surfaces as a
// generic 500 instead of the clean 400 the caller should get. Fail closed:
// anything that is not a plain string reads as absent, which falls into the
// endpoint's existing "required"/"not provided" validation. No data flows
// either direction on this path — it is purely a wrong-status-code fix.
function queryStr(v) {
	return typeof v === "string" ? v.trim() : "";
}

// Resolve the truck currently assigned to a driver, for the fuel endpoints.
//
// Two divergences this deliberately closes, both of which read to a user as
// "the app says I have no fuel data":
//
//  1. SOURCE. /api/fuel/range historically read only the active
//     truck_assignments row, while /api/driver/:driverName reads
//     trucks.assigned_driver. assignDriverToTruck() writes both, but the
//     truck-document guard already accepts assigned_driver as a fallback
//     "in case the history table lags" — mirror that here rather than show an
//     empty fuel panel to a driver who is demonstrably in a truck.
//  2. NAME MATCHING. This endpoint used SQL TRIM(LOWER(...)); every other
//     driver path uses normalizeDriverName(), which ALSO collapses internal
//     whitespace (real sheet/user rows carry typo'd double spaces — see the
//     invoice-generator regression the helper documents). SQLite has no regex
//     replace, so the whitespace collapse cannot be expressed in SQL: read the
//     active rows (fleet-sized, a few dozen) and compare in JS instead.
//     Strictly widening — every name that matched before still matches.
//
// Returns the truck row (id/unit/routemate_vehicle_id/fuel_tank_gallons/avg_mpg)
// or null. Never throws on an unknown name; callers degrade to "no fuel data".
function resolveTruckForDriverName(driverName) {
	const target = normalizeDriverName(driverName);
	if (!target) return null;
	// Primary: newest active assignment (same ordering the old query used).
	const active = db.prepare(
		`SELECT t.id, t.unit_number AS unit, t.routemate_vehicle_id, t.fuel_tank_gallons,
		        t.avg_mpg, ta.driver_name AS matched_name
		 FROM truck_assignments ta JOIN trucks t ON t.id = ta.truck_id
		 WHERE ta.end_date = '' ORDER BY ta.id DESC`
	).all();
	const fromHistory = active.find((r) => normalizeDriverName(r.matched_name) === target);
	if (fromHistory) return fromHistory;
	// Fallback: the denormalized pointer on trucks itself.
	const owned = db.prepare(
		`SELECT id, unit_number AS unit, routemate_vehicle_id, fuel_tank_gallons,
		        avg_mpg, assigned_driver AS matched_name
		 FROM trucks WHERE TRIM(COALESCE(assigned_driver, '')) != '' ORDER BY id DESC`
	).all();
	return owned.find((r) => normalizeDriverName(r.matched_name) === target) || null;
}

// GET /api/fuel/range?driver=NAME  (or ?vehicleId=ID) — miles-left-in-tank estimate
// from the assigned truck's latest ELD fuel% + tank size (config or 200-gal
// default) + MPG (ELD-derived, else the truck's configured/6.5 default). Powers
// the Fuel Finder panel; rangeMiles/gallonsRemaining come back null when the
// truck's device reports no fuel (frontend hides the panel via hasFuelData).
//
// BOTH assumptions are labeled, and both labels are load-bearing: `mpgSource`
// and `tankSource` ('eld'|'default' / 'truck'|'default') tell the caller whether
// the range rests on measured truck config or on a fleet-wide guess, so the UI
// can badge it instead of presenting an estimate with false precision. Added for
// tank after two trucks with an unset fuel_tank_gallons quietly took the 200-gal
// default and displayed ~2.5x their real range (see lib/fuel-model.js).
//
// SECURITY — Drivers are permitted but SCOPED to themselves. Both query params
// are IGNORED for the Driver role and the truck is resolved from the session
// name, exactly like GET /api/driver/me/truck-photo. This matters because
// ?vehicleId= bypasses the driver lookup entirely: honoring it for a driver
// would turn this into "read any truck's live fuel state by guessing an id".
// Ignoring rather than 403-ing on the params leaves no spoofable surface at all
// — there is nothing to probe, so nothing to enumerate. Super Admin/Dispatcher
// keep both params and the full fleet, unchanged.
app.get("/api/fuel/range", requireRole("Super Admin", "Dispatcher", "Driver"), (req, res) => {
	try {
		const isDriver = req.session.user.role === "Driver";
		// Session name for a Driver; query param for dispatch.
		const driver = isDriver
			? (req.session.user.driverName || req.session.user.driver_name || "").trim()
			: queryStr(req.query.driver);
		const vehicleIdParam = isDriver ? "" : queryStr(req.query.vehicleId);
		let truck = null;
		if (vehicleIdParam) {
			truck = db.prepare(`SELECT id, unit_number AS unit, routemate_vehicle_id, fuel_tank_gallons, avg_mpg
				FROM trucks WHERE routemate_vehicle_id = ? LIMIT 1`).get(vehicleIdParam);
		} else if (driver) {
			truck = resolveTruckForDriverName(driver);
		} else if (!isDriver) {
			return res.status(400).json({ ok: false, error: "driver or vehicleId required" });
		}
		// A Driver whose account has no linked driver name (or no truck) falls
		// through with truck = null and gets the normal hasFuelData:false shape
		// rather than a 400 — the panel simply hides, which is the same thing the
		// UI does for a truck with no fuel sensor. A hard error here would only
		// surface an admin-side linkage gap as a broken driver screen.
		const vehicleId = (truck && truck.routemate_vehicle_id) || "";
		// newest-first; fuel-model re-sorts. Pass raw truck config (0 = unset → the
		// module resolves its own default and echoes the resolved tankGallons back,
		// plus tankSource saying whether that number was configured or assumed —
		// keep passing the raw 0 rather than substituting a default here, or the
		// module loses the only signal it has to tell those two cases apart).
		const rows = vehicleId ? db.prepare(
			`SELECT odometer, fuel_pct, location_date_ms FROM routemate_telemetry
			 WHERE routemate_vehicle_id = ? AND dropped_reason = '' ORDER BY id DESC LIMIT 200`).all(vehicleId) : [];
		const latest = rows[0] || null;

		// MPG comes from the persisted ELD rollup (routemate_fuel_daily), not an
		// on-the-fly derivation: average the recent CLEAN daily rows
		// (derivation_notes = '' means no outlier/insufficient-sample flag). This is
		// the same smoothed, per-truck economy the fuel dashboard shows. When the
		// rollup has nothing for this vehicle we fall back to the truck's configured
		// avg_mpg, then the model default.
		let rollupMpg = 0;
		if (vehicleId) {
			const mpgRows = db.prepare(
				`SELECT mpg FROM routemate_fuel_daily
				 WHERE routemate_vehicle_id = ? AND derivation_notes = '' AND mpg > 0 AND miles >= 50
				 ORDER BY date DESC LIMIT 14`).all(vehicleId);
			if (mpgRows.length) {
				const sum = mpgRows.reduce((s, r) => s + r.mpg, 0);
				rollupMpg = Math.round((sum / mpgRows.length) * 100) / 100;
			}
		}

		const estimate = fuelModel.estimateRangeForVehicle({
			fuelPct: latest ? latest.fuel_pct : null,
			tankGallons: truck ? truck.fuel_tank_gallons : 0,
			avgMpg: truck ? truck.avg_mpg : 0,
			telemetryRows: rows,
		});

		// Authoritative MPG: ELD rollup → truck avg_mpg → model default. Overrides
		// the module's on-the-fly derivation so the range panel matches the persisted
		// fuel rollup. estimateRangeForVehicle still owns the fuel-sensor detection +
		// tank/gallons resolution; we only re-pick MPG and (when there is a live fuel
		// reading) recompute the range from it via the same computeRange() math.
		//
		// MPG is re-picked here ONLY because the server can see a source the pure
		// module cannot (the routemate_fuel_daily rollup), which forces mpgSource to
		// be re-labeled alongside it. Tank has no such second source — the column is
		// passed straight through and estimate.tankGallons is never reassigned below
		// — so tankSource is set once, in the module, next to the branch that picks
		// the value. Do NOT add a mirror-image tank override here: a second copy of
		// "was fuel_tank_gallons configured?" is exactly the kind of quiet drift the
		// field was added to prevent.
		const avgMpgCfg = truck && truck.avg_mpg > 0 ? Math.round(truck.avg_mpg * 100) / 100 : 0;
		// Receipt-derived MPG wins when we have it: ELD odometer for the miles and
		// the actual PUMP receipt for the gallons, so no fuel_pct and no tank-size
		// guess anywhere in the chain.
		//
		// This is not a refinement of the rollup, it replaces a broken number.
		// rollupOneDay() estimates gallons by summing the NEGATIVE deltas of a
		// bouncing fuel sender; measured on this fleet, the daily drops roughly
		// equal the daily rises (#2372 on 8/4: 188 points down, 198 up), so it
		// roughly doubles consumption and then some — it has booked 856 gallons
		// burned in one day, and 484 on a truck whose tank is configured at 300.
		// That is where the 1.05–2.45 mpg currently shown to drivers comes from.
		// Note deriveMpg() in lib/fuel-model.js is NOT the culprit: it rejects
		// implausible values correctly and is simply overwritten here.
		//
		// 'receipts' is a NEW mpgSource value rather than reusing 'eld'. Different
		// provenance deserves a different label, and this pair of *Source fields
		// exists precisely because an unlabelled default already shipped a wrong
		// number to drivers once. Clients that only know 'eld'/'default' must treat
		// an unknown source as "not verified" — FuelFinderPanel/DriverFuelPanel
		// already compare === 'eld', so they degrade to the plain badge.
		const receiptMpg = receiptMpgForVehicle(vehicleId);
		if (receiptMpg) {
			estimate.mpg = receiptMpg.mpg;
			estimate.mpgSource = "receipts";
		} else if (rollupMpg >= 3 && rollupMpg <= 11) {
			// Trust the ELD-derived MPG only in a plausible class-8 band (3–11 mpg);
			// anything outside is contaminated telemetry (heavy idle, sensor noise) →
			// fall back to the configured/default MPG rather than show a nonsense range.
			estimate.mpg = rollupMpg;
			estimate.mpgSource = "eld";
		} else if (avgMpgCfg > 0) {
			estimate.mpg = avgMpgCfg;
			estimate.mpgSource = "default";
		} else {
			estimate.mpg = fuelModel.DEFAULT_MPG;
			estimate.mpgSource = "default";
		}
		if (estimate.hasFuelData) {
			const r = fuelModel.computeRange({
				fuelPct: estimate.fuelPct,
				tankGallons: estimate.tankGallons,
				mpg: estimate.mpg,
			});
			estimate.gallonsRemaining = r.gallonsRemaining;
			estimate.rangeMiles = r.rangeMiles;
		}
		// --- honest interval -------------------------------------------------
		// rangeMiles above is a POINT estimate off tank x mpg, and backtesting it
		// against this fleet's own fill history found it overstated on 123 of 125
		// tank-to-tank legs (#33 56/56 at 1.95x, #2372 64/66, #302 3/3) — figures
		// measured BEFORE the 2026-08-07 tank correction, after which the aggregate
		// overstatement is #33 1.30x / #2372 0.99x / #302 0.83x. The interval is
		// what survives that: it never depended on the tank. Worse, the
		// error is not a constant to be divided out: at a fixed 23% #33's measured
		// legs span p10 100 mi to p90 340 mi, a 3.4x spread driven by load weight,
		// terrain and idle hours. So the point estimate is kept for compatibility
		// (existing clients read rangeMiles) and an INTERVAL is added beside it.
		//
		// `rangePlanningMiles` is the low end and is the number any single-figure
		// UI must render. Showing `typical` — never mind rangeMiles — is what put
		// "449 mi" in front of a driver with 210 miles of fuel.
		const burn = burnRateForVehicle(vehicleId);
		const interval = fuelModel.rangeInterval({
			fuelPct: estimate.fuelPct, burn, rangeMiles: estimate.rangeMiles,
		});
		const updatedAt = latest && latest.location_date_ms
			? new Date(latest.location_date_ms).toISOString() : new Date().toISOString();
		// SECURITY: the ELD vehicle id is dispatch-only and is OMITTED for the
		// Driver role. It is inert today — ?vehicleId= is ignored above — but
		// shipping it to every driver hands out precisely the enumeration key that
		// the ignore-the-param scoping exists to protect: if that blanking is ever
		// relaxed or refactored away, the fleet's ids are already in the wild.
		// Don't publish the key to the lock. `unit` deliberately stays: it is the
		// placard number on the truck the driver is sitting in, and
		// /api/driver/:driverName already returns it.
		res.json({ ok: true, driver: driver || null,
			...(isDriver ? {} : { vehicleId: vehicleId || null }),
			unit: (truck && truck.unit) || null, ...estimate,
			// Interval + basis. `rangeBasis` ranks 'measured' > 'estimated' >
			// 'unknown', the same vocabulary as mpgSource/tankSource, so a client
			// that already badges those needs no new concept.
			rangeLowMiles: interval.low,
			rangeTypicalMiles: interval.typical,
			rangeHighMiles: interval.high,
			rangePlanningMiles: interval.planning,
			rangeBasis: interval.basis,
			milesPerFuelPoint: interval.milesPerPoint,
			// Evidence behind a 'measured' basis, so the UI can say WHY it is
			// trusted ("from 56 of this truck's own fill-ups") instead of asserting
			// it. Null when there are no usable legs — which is itself the reason
			// the basis is 'estimated'. Safe for every role: it is this truck's own
			// aggregate history and carries no vehicle id or location.
			rangeEvidence: burn && burn.usable
				? { legs: burn.n, miles: burn.miles, milesPerPointP10: burn.p10, milesPerPointP90: burn.p90 }
				: null,
			updatedAt });
	} catch (err) {
		console.error("[fuel/range]", err.message);
		res.status(500).json({ ok: false, error: "fuel range failed" });
	}
});

// GET /api/fuel/verify[?vehicleId=ID] — Super Admin. Does the range panel tell
// the truth? Backtests the displayed formula against each truck's OWN fill
// history and reports the answer per truck.
//
// This is the client's ask verbatim — "we need to write a script that verifies
// that, to make sure it's accurate" — as an endpoint rather than a script,
// because a script answers once and an endpoint answers whenever someone doubts
// the number. The finding it was built to surface: on production data the panel
// overstated on 123 of 125 tank-to-tank legs across the three instrumented
// trucks (#33 56/56 at 1.95x, #2372 64/66 at 1.97x, #302 3/3 at 2.25x).
//
// ⚠️ THOSE ARE THE 2026-08-06 NUMBERS AND THEY HAVE MOVED. `fuel_tank_gallons`
// was corrected on all three trucks the next day (#33 300 -> 198, #2372 200 ->
// 100, #302 200 -> 80) and the aggregate overstatement is now #33 1.30x, #2372
// 0.99x, #302 0.83x. Run this endpoint rather than quoting the paragraph above —
// which is the whole reason it exists as an endpoint and not a one-off script.
//
// Auditing the arithmetic would have found nothing — the formula is correct and
// its inputs are wrong — so the only thing that can answer the question is the
// fill history, and that is what this reads.
//
// READ-ONLY by construction: it runs no sweep and issues no UPDATE, so the
// locked-period rule has nothing to bite on here (nothing this endpoint touches
// can write to a row in a finalized month). It reports what fuel_events already
// holds; if the sweep has never run the answer is honestly "no evidence yet"
// rather than a fabricated pass.
app.get("/api/fuel/verify", requireRole("Super Admin"), (req, res) => {
	try {
		const only = queryStr(req.query.vehicleId);
		const trucks = db.prepare(`
			SELECT id, unit_number AS unit, routemate_vehicle_id AS vid, assigned_driver,
			       fuel_tank_gallons, avg_mpg
			FROM trucks WHERE COALESCE(routemate_vehicle_id,'') <> ''
			${only ? "AND routemate_vehicle_id = ?" : ""}
			ORDER BY unit_number
		`).all(...(only ? [only] : []));

		const calibrationByVid = {};
		for (const c of fuelTankCalibrationWire()) calibrationByVid[c.vehicleId] = c;

		const results = trucks.map((t) => {
			const legs = burnLegsForVehicle(t.vid);
			const burn = fuelModel.measureBurnRate(legs);
			// The MPG the panel would actually use today, resolved the same way
			// /api/fuel/range resolves it — otherwise the backtest would grade a
			// formula nobody is looking at.
			const receipt = receiptMpgForVehicle(t.vid);
			const panelMpg = receipt ? receipt.mpg
				: (t.avg_mpg > 0 ? t.avg_mpg : fuelModel.DEFAULT_MPG);
			const panelTank = t.fuel_tank_gallons > 0 ? t.fuel_tank_gallons : fuelModel.DEFAULT_TANK_GALLONS;
			const backtest = fuelModel.backtestRangeFormula(legs, { tankGallons: panelTank, mpg: panelMpg });

			// Same numbers as they stand RIGHT NOW at the truck's live fuel level,
			// because "1.95x" is abstract and "the panel says 449, the history says
			// 210" is not.
			const latest = db.prepare(`
				SELECT fuel_pct, location_date_ms FROM routemate_telemetry
				WHERE routemate_vehicle_id = ? AND dropped_reason = '' AND fuel_pct IS NOT NULL
				ORDER BY id DESC LIMIT 1`).get(t.vid);
			const pct = latest ? latest.fuel_pct : null;
			const shown = fuelModel.computeRange({ fuelPct: pct, tankGallons: panelTank, mpg: panelMpg });
			const interval = fuelModel.rangeInterval({ fuelPct: pct, burn, rangeMiles: shown.rangeMiles });

			const cal = calibrationByVid[t.vid] || null;
			return {
				vehicleId: t.vid,
				unitNumber: t.unit,
				assignedDriver: t.assigned_driver || null,
				// What the panel is built from, and whether either half is a guess.
				panelInputs: {
					tankGallons: panelTank,
					tankSource: t.fuel_tank_gallons > 0 ? "truck" : "default",
					mpg: Math.round(panelMpg * 100) / 100,
					mpgSource: receipt ? "receipts" : (t.avg_mpg > 0 ? "default" : "default"),
				},
				// The verdict.
				backtest: {
					legs: backtest.legs,
					milesMeasured: backtest.milesTotal,
					pointsMeasured: backtest.pointsTotal,
					claimedMilesPerPoint: backtest.predictedMilesPerPoint,
					measuredMilesPerPoint: backtest.measuredMilesPerPoint,
					overstatementFactor: backtest.overstatementFactor,
					medianOverstatement: backtest.medianOverstatement,
					legsOverstated: backtest.overstatedLegs,
					// A caller that wants to check our work rather than trust it.
					legDetail: backtest.legDetail,
				},
				// Right now, on this truck.
				live: {
					fuelPct: pct,
					atMs: latest ? latest.location_date_ms : null,
					panelWouldShowMiles: shown.rangeMiles,
					measuredLowMiles: interval.low,
					measuredTypicalMiles: interval.typical,
					measuredHighMiles: interval.high,
					basis: interval.basis,
				},
				// Tank calibration, RE-LABELLED. impliedGallonsPer100Pct measures the
				// volume behind the SENDER, and on a twin-tank truck that is one tank,
				// not the truck's capacity — #33's lower mode reads ~117 while the
				// truck has twice taken a single 202.7-gallon fill. Reporting it under
				// a name that says "sensed" is the whole point: told "your 300 is
				// wrong, it's 117", an operator would set 117 and be shown HALF the
				// real range, which strands trucks just as surely. Never written back
				// to trucks.fuel_tank_gallons — a human decides, with this in hand.
				tankEvidence: cal ? {
					sampleCount: cal.sampleCount,
					sensedGallonsPer100Pct: cal.impliedGallonsPer100Pct,
					sensedLowerMode: cal.lowerMode,
					bimodal: cal.bimodal,
					// Bimodal at ~2x is the twin-saddle-tank signature: fills that top
					// up one tank vs both.
					bimodalNote: cal.bimodal
						? "Two populations ~2x apart — consistent with twin saddle tanks where the sender reads one. The LOWER mode is the SENSED tank, not the truck's capacity."
						: null,
					// Capacity inferred from the burn side instead, which is what the
					// truck actually draws on: gal/point = (mi/point) / mpg.
					burnImpliedGallonsPer100Pct: burn.usable && burn.milesPerPoint
						? Math.round((burn.milesPerPoint / panelMpg) * 100) : null,
					largestSingleFillGallons: db.prepare(`
						SELECT MAX(gallons) g FROM expenses
						WHERE LOWER(type)='fuel' AND gallons > 0 AND LOWER(TRIM(truck_unit)) = LOWER(TRIM(?))
					`).get(t.unit).g || null,
					configuredGallons: cal.configuredGallons,
				} : null,
			};
		});

		res.json({
			ok: true,
			// Absent-vs-empty, same contract as the fuel-analytics reconciliation
			// lists: no fuel_events at all means the sweep has never run, which is a
			// different statement from "checked, nothing to report".
			sweepHasRun: !!db.prepare("SELECT 1 FROM fuel_events LIMIT 1").get(),
			windowDays: FUEL_EVENTS_MATCH_DAYS,
			trucks: results,
		});
	} catch (err) {
		console.error("[fuel/verify]", err.message);
		res.status(500).json({ ok: false, error: "fuel verification failed" });
	}
});

// One Routes call per miss (cached 15 min by ROUTE_CACHE_TTL) and a handful of
// indexed SQLite reads — an order of magnitude cheaper than poiLimiter's 4-8
// billed Places calls, so the caps are correspondingly looser. Same per-user
// keying and the same reason: a dispatch office behind one NAT must not share a
// bucket while every driver on cellular gets a fresh one.
const fuelPlanLimiter = rateLimit({
	windowMs: 15 * 60 * 1000,
	max: (req) => {
		const role = req.session?.user?.role;
		return role === "Super Admin" || role === "Dispatcher" ? 120 : 30;
	},
	keyGenerator: (req) => {
		const id = req.session?.user?.id;
		return id ? `u:${id}` : `ip:${ipKeyGenerator(req.ip)}`;
	},
	message: { error: "Too many trip-plan requests. Try again later." },
	standardHeaders: true,
});

// GET /api/fuel/trip-plan?loadId=ID[&vehicleId=ID] — "will this load's route fit
// in the tank, and if not, where do I have to stop?"
//
// The question behind the client's message. It needs three things the range
// panel alone cannot give: the distance still AHEAD (not the whole lane — the
// truck is usually mid-route), the fuel that distance costs, and a verdict that
// is allowed to say NO.
//
// REMAINING route, from the truck's live position. Planning from the load's
// origin would answer a question nobody asked and would overstate the fuel
// needed once the truck is moving; the fallback to the load origin exists only
// for a truck with no recent fix.
//
// Fuel stops are NOT fetched here. GET /api/poi/fuel-stops fans out to 4-8
// billed Places calls per cache miss, and folding that into an endpoint the
// panel polls would multiply that cost by the poll rate. This returns
// `fuelStopsRecommended` + `refuelWithinMiles` and lets the client make that
// call ONCE, deliberately, through the endpoint that already owns the cache and
// the limiter.
//
// SECURITY: identical scoping to /api/poi/fuel-stops, and for the same reasons.
// A Driver must pass loadId, is ownership-checked against it, cannot pass
// vehicleId (it is ignored, not rejected — nothing to probe), and never receives
// the ELD vehicle id back.
app.get("/api/fuel/trip-plan", requireRole("Super Admin", "Dispatcher", "Driver"), fuelPlanLimiter, async (req, res) => {
	try {
		const isDriver = req.session.user.role === "Driver";
		const loadId = queryStr(req.query.loadId);
		if (!loadId) return res.status(400).json({ ok: false, error: "loadId required" });

		let truck = null;
		if (isDriver) {
			const owned = await loadBelongsToDriver(loadId, req.session.user.driverName);
			if (!owned) return res.status(403).json({ ok: false, error: "This load is not assigned to you" });
			truck = resolveTruckForDriverName(
				(req.session.user.driverName || req.session.user.driver_name || "").trim());
		} else {
			const vehicleIdParam = queryStr(req.query.vehicleId);
			if (vehicleIdParam) {
				truck = db.prepare(`SELECT id, unit_number AS unit, routemate_vehicle_id, fuel_tank_gallons, avg_mpg
					FROM trucks WHERE routemate_vehicle_id = ? LIMIT 1`).get(vehicleIdParam);
			} else {
				// Fall back to whoever is actually on the load, so dispatch can ask the
				// question without first looking up the truck.
				const jt = await getJobTrackingCached();
				const headers = jt.headers || [];
				const driverCol = findCol(headers, /driver/i);
				const loadIdCol = findCol(headers, /load.?id|job.?id/i);
				const target = String(loadId).trim().toLowerCase().replace(/^#/, "");
				const row = (jt.data || []).find((r) => loadIdCol
					&& String(r[loadIdCol] || "").trim().toLowerCase().replace(/^#/, "") === target);
				if (row && driverCol && row[driverCol]) truck = resolveTruckForDriverName(String(row[driverCol]));
			}
		}

		const vehicleId = (truck && truck.routemate_vehicle_id) || "";
		const lc = db.prepare("SELECT origin_lat, origin_lng, dest_lat, dest_lng FROM load_coordinates WHERE load_id = ?")
			.get(loadId.toLowerCase().replace(/^#/, ""));
		if (!lc || ![lc.dest_lat, lc.dest_lng].every(Number.isFinite)) {
			return res.status(400).json({ ok: false, error: "load has no geocoded destination" });
		}

		// Live fuel + position.
		const latest = vehicleId ? db.prepare(`
			SELECT latitude, longitude, fuel_pct, location_date_ms FROM routemate_telemetry
			WHERE routemate_vehicle_id = ? AND dropped_reason = '' ORDER BY id DESC LIMIT 1`).get(vehicleId) : null;
		const fixFresh = latest && latest.location_date_ms
			&& Date.now() - latest.location_date_ms < 6 * 60 * 60 * 1000
			&& Number.isFinite(latest.latitude) && Number.isFinite(latest.longitude);
		const from = fixFresh
			? { latitude: latest.latitude, longitude: latest.longitude }
			: (Number.isFinite(lc.origin_lat) && Number.isFinite(lc.origin_lng)
				? { latitude: lc.origin_lat, longitude: lc.origin_lng } : null);
		if (!from) return res.status(400).json({ ok: false, error: "no position to plan from" });

		let routeMiles = null;
		try {
			const route = await getRoute(from, { latitude: lc.dest_lat, longitude: lc.dest_lng });
			if (route && Number.isFinite(route.distanceMiles)) routeMiles = route.distanceMiles;
		} catch { /* fall through to the straight-line floor below */ }
		// Routes API down -> straight-line distance, which is always SHORTER than
		// the road. That understates the route, which would flatter the verdict, so
		// it is inflated by 1.15 (a standard road-vs-crow factor) and labelled. A
		// null here would drop the panel entirely at exactly the moment a driver is
		// trying to decide whether to stop.
		const routeSource = routeMiles != null ? "routes_api" : "straight_line_estimate";
		if (routeMiles == null) {
			routeMiles = Math.round(
				(geolib.getDistance(from, { latitude: lc.dest_lat, longitude: lc.dest_lng }) / 1609.34) * 1.15 * 10) / 10;
		}

		const burn = burnRateForVehicle(vehicleId);
		const receipt = receiptMpgForVehicle(vehicleId);
		const mpg = receipt ? receipt.mpg
			: (truck && truck.avg_mpg > 0 ? truck.avg_mpg : fuelModel.DEFAULT_MPG);
		const tank = truck && truck.fuel_tank_gallons > 0 ? truck.fuel_tank_gallons : fuelModel.DEFAULT_TANK_GALLONS;
		const pct = latest ? latest.fuel_pct : null;
		const shown = fuelModel.computeRange({ fuelPct: pct, tankGallons: tank, mpg });

		const plan = fuelModel.planTripFuel({
			routeMiles, fuelPct: pct, burn, rangeMiles: shown.rangeMiles, mpg,
		});

		res.json({
			ok: true,
			loadId,
			unit: (truck && truck.unit) || null,
			...(isDriver ? {} : { vehicleId: vehicleId || null }),
			routeSource,
			// True when the plan is measured from where the truck is right now
			// rather than from the load's pickup — a dispatcher reading a big number
			// needs to know which question was answered.
			fromLivePosition: !!fixFresh,
			fuelPct: pct,
			mpg: Math.round(mpg * 100) / 100,
			mpgSource: receipt ? "receipts" : "default",
			...plan,
			// The point estimate the old panel would have shown, kept beside the
			// verdict so the gap is visible rather than silently corrected.
			pointEstimateMiles: shown.rangeMiles,
			fuelStopsRecommended: plan.verdict === "tight" || plan.verdict === "insufficient",
			updatedAt: latest && latest.location_date_ms
				? new Date(latest.location_date_ms).toISOString() : null,
		});
	} catch (err) {
		console.error("[fuel/trip-plan]", err.message);
		res.status(500).json({ ok: false, error: "trip plan failed" });
	}
});

// Each payout statement runs a full month recompute AND a Puppeteer render, so a
// refresh-hammer could pin the box. Generous enough for real use (a handful of
// months downloaded in a sitting), tight enough to bound the cost.
const statementLimiter = rateLimit({
	windowMs: 15 * 60 * 1000,
	max: 20,
	message: { error: "Too many statement downloads. Try again in a few minutes." },
	standardHeaders: true,
});

// Each request fans out to 4–8 `places:searchNearby` calls (MIN/MAX_WAYPOINTS in
// lib/poi-fuel-stops.js) on the Places Enterprise + Atmosphere SKU — the most
// expensive tier, because the field mask asks for `places.fuelOptions` to get
// live pump prices — plus a Routes call. With drivers added this limiter is the
// only thing between the rollout and a large Google bill, so it is both
// per-user and role-aware.
const poiLimiter = rateLimit({
	windowMs: 15 * 60 * 1000,
	// Dispatch keeps the original 60: they shop fuel across the whole board and
	// re-run lookups while planning. A Driver gets 6 — they run ONE load at a
	// time, and with poiStopsCache below serving every repeat for that lane free
	// of charge, 6 distinct lane lookups per 15 min is far more than an honest
	// driver reaches. Lower is deliberate: at ~$0.16–0.32 of billed Places calls
	// per MISS, the cap is the ceiling on what a scripted client can spend, and
	// per-user keying means that ceiling is now per account rather than shared.
	// requireRole runs before this middleware, so req.session.user is populated.
	max: (req) => {
		const role = req.session?.user?.role;
		return role === "Super Admin" || role === "Dispatcher" ? 60 : 6;
	},
	// Key on the SESSION USER, not the IP (the default). IP keying is actively
	// backwards for this endpoint: a dispatch office behind one NAT shares a
	// single bucket, so one person planning fuel locks out everyone else, while
	// every driver on cellular gets a fresh bucket whenever the carrier rotates
	// their IP — i.e. the cheap callers are throttled and the expensive ones are
	// not. Same generator as expenseOcrLimiter; falls back to IP for the
	// unauthenticated edge.
	keyGenerator: (req) => {
		const id = req.session?.user?.id;
		return id ? `u:${id}` : `ip:${ipKeyGenerator(req.ip)}`;
	},
	message: { error: "Too many POI requests. Try again later." },
	standardHeaders: true,
});

// Per-lane TTL cache for the Places fan-out. Mirrors trackResponseCache (Map +
// TTL + FIFO cap), which exists on the public tracker for exactly this reason.
//
// WHY: this endpoint had a cost asymmetry — getRoute() is cached 15 min
// (ROUTE_CACHE_TTL), but the expensive half was not, so the cheap Routes call
// was memoized while 4-8 Places `searchNearby` calls on the Enterprise +
// Atmosphere SKU (~$40/1,000 → ~$0.16-0.32 a request) were re-billed on every
// single call, including repeat polls for a load whose route has not moved.
//
// KEYED ON THE RESOLVED COORDINATES, not the query string, and rounded to 3
// decimals (~111 m) exactly like routeCacheKey(). Consequences, all wanted:
//   • `?loadId=%23123` and `?loadId=123` normalize to the same load_coordinates
//     row → same coords → SAME entry.
//   • `limit` is NOT part of the key and never causes a refetch — we fetch the
//     full cap once and slice on read (see POI_FETCH_CAP).
//   • Two different loads running the same lane share one fan-out.
//   • Re-geocoding a load moves its coords → new key → no stale route, without
//     needing an invalidation hook.
// A load's route is static, so this collapses repeat cost to ~zero and makes
// the per-user rate cap a backstop rather than the only cost control.
const poiStopsCache = new Map();
// Aligned with ROUTE_CACHE_TTL so both halves of this endpoint expire together
// (no window where we re-bill Places only to pair it with a stale route path).
const POI_CACHE_TTL_MS = 15 * 60 * 1000;
const POI_CACHE_MAX = 200;
// Always fetch at the endpoint's max `limit` so one cached entry can serve any
// requested limit. This is BILLING-NEUTRAL: `limit` only feeds maxResultCount
// per call (lib/poi-fuel-stops.js), while the number of billed calls is the
// waypoint count — clamp(ceil(routeMiles/75), 4, 8) — which `limit` cannot
// influence. Same requests, more rows per request, one entry that fits all.
const POI_FETCH_CAP = 25;
function poiCacheKey(oLat, oLng, dLat, dLng) {
	return `${oLat.toFixed(3)},${oLng.toFixed(3)}>${dLat.toFixed(3)},${dLng.toFixed(3)}`;
}

// GET /api/poi/fuel-stops?loadId=ID  (or ?originLat=&originLng=&destLat=&destLng=)[&limit=]
// — diesel truck stops along a load's route, each stamped with its LIVE
// per-station pump price. Locations and prices both come from Google Places
// (`places.fuelOptions`); there is deliberately no EIA/regional-average
// fallback — see the ranking comment below for why a coarse estimate is worse
// than no price at all. (The old "prices via EIA regional avg" note here was
// stale: that source was removed when live pump prices landed.)
//
// SECURITY — Drivers are permitted but SCOPED to their own loads: loadId is
// REQUIRED and raw coordinate pairs are REJECTED. The same reasoning as
// GET /api/geocode/load/:loadId, which is the precedent for this shape — pickup
// and dropoff coordinates are competitive intel, and a free origin/dest pair is
// worse than reading one load: it is an arbitrary route-pricing oracle for any
// lane in the country, billed to us at 4–8 Places calls a shot. Dispatch keeps
// the raw-coordinate form (they price prospective lanes that have no load yet).
app.get("/api/poi/fuel-stops", requireRole("Super Admin", "Dispatcher", "Driver"), poiLimiter, async (req, res) => {
	try {
		let oLat = parseFloat(req.query.originLat), oLng = parseFloat(req.query.originLng),
		    dLat = parseFloat(req.query.destLat), dLng = parseFloat(req.query.destLng);
		const loadId = queryStr(req.query.loadId);
		if (req.session.user.role === "Driver") {
			if (!loadId) {
				return res.status(400).json({ ok: false, error: "loadId required", stops: [] });
			}
			// Reject only coordinates that actually parsed — an empty/absent param
			// is a harmless no-op, but any usable coordinate means the caller is
			// trying to route somewhere other than their load.
			if ([oLat, oLng, dLat, dLng].some(Number.isFinite)) {
				return res.status(403).json({ ok: false, error: "Drivers must request fuel stops by loadId", stops: [] });
			}
			const owned = await loadBelongsToDriver(loadId, req.session.user.driverName);
			if (!owned) return res.status(403).json({ ok: false, error: "This load is not assigned to you", stops: [] });
			// Defense in depth: force the load_coordinates lookup below to be the
			// only source of coordinates for this request, whatever was passed.
			oLat = oLng = dLat = dLng = NaN;
		}
		if (loadId && ![oLat, oLng, dLat, dLng].every(Number.isFinite)) {
			const lc = db.prepare("SELECT origin_lat, origin_lng, dest_lat, dest_lng FROM load_coordinates WHERE load_id = ?")
				.get(loadId.toLowerCase().replace(/^#/, ""));
			if (lc) { oLat = lc.origin_lat; oLng = lc.origin_lng; dLat = lc.dest_lat; dLng = lc.dest_lng; }
		}
		if (![oLat, oLng, dLat, dLng].every(Number.isFinite)) {
			return res.status(400).json({ ok: false, error: "need origin+dest coords or a geocoded loadId", stops: [] });
		}
		if (!GOOGLE_MAPS_API_KEY) return res.status(503).json({ ok: false, error: "maps_key_unset", stops: [] });
		const limit = Math.min(parseInt(req.query.limit) || 12, 25);

		// Cache lookup sits AFTER coordinate resolution and after the Driver
		// ownership check above, so a cache hit can never bypass authorization —
		// same placement rule trackResponseCache follows w.r.t. its rate limiter.
		const cacheKey = poiCacheKey(oLat, oLng, dLat, dLng);
		const hit = poiStopsCache.get(cacheKey);
		let priced = hit && Date.now() - hit.time < POI_CACHE_TTL_MS ? hit.stops : null;
		const fromCache = priced !== null;

		if (!fromCache) {
			// Sample the search waypoints along the ACTUAL driving polyline (not the
			// straight line) so stops land on the highway. Best-effort: getRoute()
			// returns null on any Routes API failure, and we degrade to straight-line
			// sampling (today's behavior) rather than failing the fuel-stop lookup.
			let routePath = null;
			try {
				const route = await getRoute(
					{ latitude: oLat, longitude: oLng },
					{ latitude: dLat, longitude: dLng },
				);
				if (route && Array.isArray(route.points) && route.points.length >= 2) {
					routePath = route.points; // [{ latitude, longitude }, …] — lib normalizes
				}
			} catch { /* degrade to straight-line sampling */ }
			const stops = await poiFuelStops.findFuelStopsAlongRoute({
				originLat: oLat, originLng: oLng, destLat: dLat, destLng: dLng,
				apiKey: GOOGLE_MAPS_API_KEY, limit: POI_FETCH_CAP, routePath,
			});
			// Attach the live per-station diesel pump price (Google `fuelOptions`) where
			// Google has coverage. Stations with no price data get effectivePrice: null
			// → the UI shows "price n/a". We deliberately do NOT substitute a regional
			// average: a coarse regional number would sort as if it were the cheapest
			// stop and mislead the driver. Real pump price or nothing.
			priced = (stops || []).map((s) => {
				const hasLive = Number.isFinite(s.dieselPrice);
				return {
					...s,
					priceSource: hasLive ? "station" : null,
					effectivePrice: hasLive ? s.dieselPrice : null,
					priceAsOf: hasLive ? (s.dieselPriceUpdated || null) : null,
				};
			});
			// True-cheapest first: live-priced stations by price ascending, then the
			// no-price stations nearest-to-route.
			priced.sort((a, b) => {
				const al = a.priceSource === "station", bl = b.priceSource === "station";
				if (al && bl) return a.effectivePrice - b.effectivePrice;
				if (al !== bl) return al ? -1 : 1;
				return (a.aboutMilesFromRoute || 0) - (b.aboutMilesFromRoute || 0);
			});
			// Only cache a NON-EMPTY result. findFuelStopsAlongRoute degrades a failed
			// waypoint to [] silently, so an empty array is ambiguous between "no
			// truck stops on this lane" and "Places was briefly down" — pinning the
			// latter for 15 minutes would turn a blip into an outage for that lane.
			// An empty result simply retries on the next call.
			if (priced.length) {
				poiStopsCache.set(cacheKey, { stops: priced, time: Date.now() });
				if (poiStopsCache.size > POI_CACHE_MAX) poiStopsCache.delete(poiStopsCache.keys().next().value);
			}
		}

		// Slice on read — the cached entry always holds the full POI_FETCH_CAP set,
		// so changing `limit` re-slices instead of re-billing. Cached stop objects
		// are treated as READ-ONLY; nothing below mutates one.
		const stopsOut = priced.slice(0, limit);
		// cheapest/livePriceCount describe the rows actually returned, so they stay
		// self-consistent with `stops` at any limit. `cheapest` is stable across
		// limits regardless: the sort puts the globally cheapest priced station at
		// index 0, so it survives every slice >= 1.
		const liveStops = stopsOut.filter((s) => s.priceSource === "station");
		res.json({
			ok: true,
			stops: stopsOut,
			cheapest: liveStops[0] || null,     // true-cheapest station with a live pump price
			livePriceCount: liveStops.length,
			cached: fromCache,                  // ops/QA signal: did this request bill Google?
		});
	} catch (err) {
		if (err && err.code === "POI_NO_KEY") return res.status(503).json({ ok: false, error: "maps_key_unset", stops: [] });
		if (err && err.code === "POI_BAD_COORDS") return res.status(400).json({ ok: false, error: "coords_required", stops: [] });
		console.error("[poi/fuel-stops]", err.message);
		res.status(500).json({ ok: false, error: err.message, stops: [] });
	}
});

// GET /api/config/maps-key — expose the BROWSER Google Maps key for client-side
// map rendering. Unauthenticated on purpose: /apply, /invest and the public
// /track/:loadId tracker all load a map before any session exists, so adding
// requireAuth here breaks three public surfaces and is not the fix it looks
// like. Anything served here is world-readable — see GOOGLE_MAPS_BROWSER_KEY.
//
// no-store so the key is never parked in a shared/proxy cache: a rotation must
// take effect on the next page load, not whenever an intermediary expires it.
app.get("/api/config/maps-key", (req, res) => {
	res.set("Cache-Control", "no-store");
	res.json({ key: GOOGLE_MAPS_BROWSER_KEY });
});

// --- Investor maintenance notice --------------------------------------------
// Client ask: while the app is mid-update, investors should see (a) a one-shot
// popup on login and (b) a persistent banner saying so — WITHOUT losing access
// to anything; nothing here gates a route or an action. The copy has to be
// tunable in production without a redeploy, so it lives in env vars and is
// served through an endpoint rather than baked into the client bundle — the
// same reason GOOGLE_MAPS_API_KEY above is served, not inlined. Like every
// other env-derived constant in this file, these are read once at module
// scope, so a copy change still needs a `pm2 restart` — a redeploy is avoided,
// a restart is not, and that's an accepted tradeoff, not an oversight.
//
// DEFAULT OFF, matching this repo's convention for anything that changes what a
// user sees the instant the flag flips (ROUTEMATE_ENABLED / SCANKIT_ENABLED /
// INVOICE_AUTOGEN_ENABLED / PERIOD_FINALIZE_ENABLED): merging this code must
// not, by itself, put a "SYSTEM UPDATE IN PROGRESS" banner in front of an
// investor — an operator opts in only once there is a real maintenance window
// to announce.
const MAINTENANCE_NOTICE_ENABLED = /^(true|1|yes|on)$/i.test(String(process.env.MAINTENANCE_NOTICE_ENABLED ?? "").trim());

// COPY CAPS. Tunable-without-a-redeploy is also an unguarded input path: this
// endpoint hands out whatever an operator typed into .env, and the banner is
// `position: sticky`, so its height is taken off every screen underneath it for
// as long as the flag is on. Roughly 1,300 characters of message fills a phone
// viewport, which pins the banner over the whole page and locks the investor
// out of the very content the client insisted we never take away ("don't knock
// him out of it"). The client caps the rendered banner height — that is the
// primary fix; this is the second layer, so the server never hands out copy
// long enough to cause it in the first place. Caps are ~2-4x the default copy
// below, and the two the banner stacks (title 80 + message 400) sit well under
// that 1,300 even at worst case.
//
// TRUNCATE, NEVER REJECT. This ships during an incident: a maintenance notice
// that fails closed because someone pasted an essay is worse than one that got
// shortened. Nothing in here can 400, throw, or blank the notice.
const MAINTENANCE_NOTICE_MAX = { title: 80, message: 400, disclaimer: 200, version: 32 };

// Clamp one copy field, cutting at a word boundary. Deliberately appends NO
// ellipsis: on a surface with no expand affordance a "…" reads as "tap for
// more" and, on copy whose entire job is to reassure an investor, as broken
// text — a shortened line that still reads like a finished line is the better
// failure mode. The operator is not left guessing either; a real truncation
// warns at boot (same module-scope pattern as the SESSION_SECRET warning).
function clampNoticeCopy(text, max, envName) {
	const s = String(text ?? "");
	if (s.length <= max) return s; // the normal path — copy passes through byte-for-byte
	let cut = s.slice(0, max);
	// Drop a half-word, but only when the cut actually splits one, and only if
	// enough survives — one giant token (a pasted URL/blob) would otherwise back
	// off to nothing.
	if (/\S$/.test(cut) && /^\S/.test(s.slice(max))) {
		const atBoundary = cut.replace(/\S+$/, "");
		if (atBoundary.trim().length >= max * 0.6) cut = atBoundary;
	}
	// A cut can strand an opener whose closer sat past `max`. Backing up to it is
	// cheap and beats copy that ends on a lone `(` or `"`.
	const paren = cut.lastIndexOf("(");
	if (paren > -1 && cut.indexOf(")", paren) === -1) cut = cut.slice(0, paren);
	const curly = cut.lastIndexOf("“");
	if (curly > -1 && cut.indexOf("”", curly) === -1) cut = cut.slice(0, curly);
	if ((cut.match(/"/g) || []).length % 2 === 1) cut = cut.slice(0, cut.lastIndexOf('"'));
	// Trailing joiners/openers read as a sentence someone chopped; a trailing
	// . ! ? is kept, since landing on one is the cleanest cut available.
	cut = cut.replace(/[\s,;:\-–—\/&+([{<«]+$/, "");
	// A quote after a space is an opener that lost its closer; a quote glued to a
	// word is a possessive or contraction, so leave that one alone.
	cut = cut.replace(/\s+['‘"“]$/, "").trim();
	const out = cut || s.slice(0, max).trim(); // never hand back an empty string
	console.warn(`[maintenance-notice] ${envName} is ${s.length} chars, capped at ${max} — serving ${out.length}. Shorten it in .env: long copy pins the sticky banner over the whole page on a phone.`);
	return out;
}

// The BANNER headline. Rendered uppercase, 800-weight, on the red bar — the
// client's "make it big and bold and red so they know this is under maintenance".
const MAINTENANCE_NOTICE_TITLE = clampNoticeCopy(
	String(process.env.MAINTENANCE_NOTICE_TITLE ?? "SYSTEM UPDATE IN PROGRESS").trim() || "SYSTEM UPDATE IN PROGRESS",
	MAINTENANCE_NOTICE_MAX.title, "MAINTENANCE_NOTICE_TITLE");
// The POPUP heading — SEPARATE from the banner on purpose. The client asked for
// two different things in one breath: a banner saying the system is updating,
// and a popup saying "Application is currently under maintenance". One shared
// title could only satisfy one of them, and the banner uppercases whatever it
// is given, so borrowing the popup's sentence would have shouted a full
// sentence across the top of the page. Defaults to the client's exact wording.
// Falls back to the banner title only if an operator deliberately blanks it.
const MAINTENANCE_NOTICE_MODAL_TITLE = clampNoticeCopy(
	String(process.env.MAINTENANCE_NOTICE_MODAL_TITLE ?? "Application is currently under maintenance").trim() || MAINTENANCE_NOTICE_TITLE,
	MAINTENANCE_NOTICE_MAX.title, "MAINTENANCE_NOTICE_MODAL_TITLE");
// Default copy: says the portal is mid-update, that figures may move, and that
// nothing is locked — the thing investors are most likely to worry about.
const MAINTENANCE_NOTICE_MESSAGE_DEFAULT =
	"The portal is being updated behind the scenes right now — some figures may shift while we finish. You're welcome to keep using everything as normal; nothing here is locked.";
// The clamp wraps the whole `env || DEFAULT` expression rather than just the env
// value, so (a) an all-whitespace env var still falls back to the default
// instead of collapsing to an empty banner, and (b) a default that someone
// later edits past its own cap is caught too.
const MAINTENANCE_NOTICE_MESSAGE = clampNoticeCopy(
	String(process.env.MAINTENANCE_NOTICE_MESSAGE ?? MAINTENANCE_NOTICE_MESSAGE_DEFAULT).trim() || MAINTENANCE_NOTICE_MESSAGE_DEFAULT,
	MAINTENANCE_NOTICE_MAX.message, "MAINTENANCE_NOTICE_MESSAGE");
// The client's own wording for the fine-print disclaimer. NOTE: an earlier draft
// of this copy read "final sentiments", a mis-transcription of the client's
// spoken "final settlements" — the word means the monthly investor payout, so
// the typo landed on investor-facing money copy. Keep it "settlements".
const MAINTENANCE_NOTICE_DISCLAIMER_DEFAULT = "The final settlements are still being calculated.";
const MAINTENANCE_NOTICE_DISCLAIMER = clampNoticeCopy(
	String(process.env.MAINTENANCE_NOTICE_DISCLAIMER ?? MAINTENANCE_NOTICE_DISCLAIMER_DEFAULT).trim() || MAINTENANCE_NOTICE_DISCLAIMER_DEFAULT,
	MAINTENANCE_NOTICE_MAX.disclaimer, "MAINTENANCE_NOTICE_DISCLAIMER");
// 'all' is the only other accepted value; anything unrecognized (typo, blank,
// unset) falls back to the narrower 'investor' rather than silently
// broadcasting to dispatch/admin staff who have no reason to see an
// investor-facing notice.
const MAINTENANCE_NOTICE_AUDIENCE = String(process.env.MAINTENANCE_NOTICE_AUDIENCE ?? "").trim().toLowerCase() === "all" ? "all" : "investor";
// A STRING, not a number: the client store compares it with
// `String(data?.version ?? DEFAULTS.version)` and keys the per-session
// dismissal flag off it (client/src/stores/maintenance.js), so bumping this is
// how an operator re-shows the popup to everyone who already dismissed it.
//
// Because it is concatenated straight into a sessionStorage key
// (`logisx.maintenanceNotice.dismissed.v${version}`), it gets the tightest
// handling of the four: strip to plain alphanumerics plus `. _ -`, THEN cap —
// stripping first so the cap counts only surviving characters. That keeps a
// pathological value (an essay, a quoted blob, a key-shaped string with its own
// dots and colons) from becoming an absurd or ambiguous storage key. Caveat
// worth knowing: a bump that differs from the previous value only in stripped
// characters sanitizes to the same string, so the popup will NOT resurface —
// use plain values like `2`, `2026-08-06`, `aug-window`.
const MAINTENANCE_NOTICE_VERSION = String(process.env.MAINTENANCE_NOTICE_VERSION ?? "1").trim().replace(/[^A-Za-z0-9._-]/g, "").slice(0, MAINTENANCE_NOTICE_MAX.version) || "1";
if (MAINTENANCE_NOTICE_VERSION !== (String(process.env.MAINTENANCE_NOTICE_VERSION ?? "1").trim() || "1")) {
	console.warn(`[maintenance-notice] MAINTENANCE_NOTICE_VERSION sanitized to "${MAINTENANCE_NOTICE_VERSION}" (alphanumerics plus . _ - only, max ${MAINTENANCE_NOTICE_MAX.version}). If that matches the previous version, dismissed popups will not re-show.`);
}

// GET /api/config/maintenance — investor maintenance-notice copy (login popup +
// top banner). No auth, same reasoning as /api/config/maps-key above: the SPA
// fetches this at boot, potentially before the session has resolved, and the
// payload is nothing but static copy already destined for the investor's own
// screen — requiring auth here would just race the session check for zero
// benefit. The client applies its own DEFAULTS and audience/role gating; this
// endpoint's only job is to hand back today's configured copy, length-capped
// per MAINTENANCE_NOTICE_MAX above but otherwise untouched.
//
// ⚠️ Unauthenticated means ANYONE who curls this can read the copy whenever the
// flag is on. That is acceptable — and strictly less sensitive than the Maps key
// next door — precisely because the copy is generic. Keep it that way: it must
// never name a client, a dollar amount, or a root cause. Same warning sits over
// the vars in .env.example, where an operator actually types the words.
app.get("/api/config/maintenance", (req, res) => {
	res.json({
		enabled: MAINTENANCE_NOTICE_ENABLED,
		title: MAINTENANCE_NOTICE_TITLE,
		modalTitle: MAINTENANCE_NOTICE_MODAL_TITLE,
		message: MAINTENANCE_NOTICE_MESSAGE,
		disclaimer: MAINTENANCE_NOTICE_DISCLAIMER,
		audience: MAINTENANCE_NOTICE_AUDIENCE,
		version: MAINTENANCE_NOTICE_VERSION,
	});
});

// GET /api/geocode — reverse geocode via Google Geocoding API
app.get("/api/geocode", async (req, res) => {
	const { lat, lng } = req.query;
	if (!lat || !lng) return res.status(400).json({ error: "lat and lng required" });
	try {
		const resp = await fetch(
			`https://maps.googleapis.com/maps/api/geocode/json?latlng=${lat},${lng}&key=${GOOGLE_MAPS_API_KEY}`
		);
		if (!resp.ok) return res.json({ status: "ERROR", results: [] });
		const data = await resp.json();
		if (data.status !== "OK" || !data.results || data.results.length === 0)
			return res.json({ status: "OK", results: [] });
		const r = data.results[0];
		const comp = r.address_components || [];
		res.json({
			status: "OK",
			results: [{
				formatted_address: r.formatted_address,
				address_components: [
					{ long_name: (comp.find(c => c.types.includes("locality")) || {}).long_name || "", types: ["locality"] },
					{ long_name: (comp.find(c => c.types.includes("sublocality")) || {}).long_name || "", types: ["sublocality"] },
					{ short_name: (comp.find(c => c.types.includes("administrative_area_level_1")) || {}).short_name || "", types: ["administrative_area_level_1"] },
					{ long_name: (comp.find(c => c.types.includes("postal_code")) || {}).long_name || "", types: ["postal_code"] },
				],
			}],
		});
	} catch {
		res.json({ status: "ERROR", results: [] });
	}
});

// GET /api/geocode/search — Forward geocode via Google Places API (New)
app.get("/api/geocode/search", async (req, res) => {
	const { q } = req.query;
	if (!q || q.trim().length < 3) return res.json({ results: [] });
	try {
		const resp = await fetch("https://places.googleapis.com/v1/places:searchText", {
			method: "POST",
			headers: {
				"Content-Type": "application/json",
				"X-Goog-Api-Key": GOOGLE_MAPS_API_KEY,
				"X-Goog-FieldMask": "places.displayName,places.formattedAddress,places.location",
			},
			body: JSON.stringify({ textQuery: q.trim() }),
		});
		if (!resp.ok) return res.json({ results: [] });
		const data = await resp.json();
		const results = (data.places || []).map(p => ({
			lat: p.location?.latitude,
			lng: p.location?.longitude,
			displayName: p.formattedAddress || p.displayName?.text || "",
		}));
		res.json({ results });
	} catch {
		res.json({ results: [] });
	}
});

// GET /api/geocode/load/:loadId — get coordinates for a load (SQLite lookup, geocodes on-demand if missing)
app.get("/api/geocode/load/:loadId", requireAuth, async (req, res) => {
	try {
		const loadId = decodeURIComponent(req.params.loadId).trim().toLowerCase().replace(/^#/, "");
		// SECURITY: allow-list, not a deny-list for one role.
		//
		// This used to read `if (role === "Driver")`, which guarded the role
		// someone had thought about and silently waved through every other
		// authenticated role — including INVESTOR. And the payload below is not
		// just coordinates: it returns `pickupAddress` and `dropoffAddress`, i.e.
		// the shipper and receiver for any load id. That is the carrier's
		// customer list, and load ids are visible and enumerable. An investor
		// funds trucks; they are an outside party who happens to hold a login,
		// and there is no reading of the product where they need it.
		//
		// Written as an explicit allow-list so a role added later is denied by
		// default rather than inheriting access nobody decided to grant. No
		// investor surface calls this endpoint — the only callers are the three
		// dispatcher load tabs and the driver app.
		const geoRole = req.session.user.role;
		if (geoRole === "Driver") {
			const owned = await loadBelongsToDriver(req.params.loadId, req.session.user.driverName);
			if (!owned) return res.status(403).json({ error: "This load is not assigned to you" });
		} else if (geoRole !== "Super Admin" && geoRole !== "Dispatcher") {
			return res.status(403).json({ error: "Forbidden" });
		}
		let row = db.prepare("SELECT * FROM load_coordinates WHERE load_id = ?").get(loadId);

		// On miss (or partial coverage): find addresses in the sheet, geocode, and cache
		const needsGeocode = !row || !row.origin_lat || !row.dest_lat;
		if (needsGeocode) {
			try {
				const sheets = await getSheets();
				const headerResp = await sheets.spreadsheets.values.get({
					spreadsheetId: SPREADSHEET_ID,
					range: "Job Tracking!1:1",
				});
				const headers = (headerResp.data.values || [[]])[0];
				const dataResp = await sheets.spreadsheets.values.get({
					spreadsheetId: SPREADSHEET_ID,
					range: "Job Tracking",
				});
				const rows = dataResp.data.values || [];
				const loadIdCol = headers.find((h) => /load.?id|job.?id/i.test(h));
				const pickupAddrCol = headers.find((h) => /pickup.*address|origin.*address|shipper.*address/i.test(h));
				const dropoffAddrCol = headers.find((h) => /drop.?off.*address|dest.*address|receiver.*address|delivery.*address/i.test(h));
				if (loadIdCol) {
					for (let i = 1; i < rows.length; i++) {
						const obj = {};
						headers.forEach((h, idx) => { obj[h] = rows[i][idx] || ""; });
						if ((obj[loadIdCol] || "").trim().toLowerCase() === loadId) {
							const pickupAddr = pickupAddrCol ? (obj[pickupAddrCol] || "").trim() : "";
							const dropoffAddr = dropoffAddrCol ? (obj[dropoffAddrCol] || "").trim() : "";
							const [origin, dest] = await Promise.all([
								pickupAddr ? geocodeAddress(pickupAddr) : Promise.resolve(null),
								dropoffAddr ? geocodeAddress(dropoffAddr) : Promise.resolve(null),
							]);
							db.prepare(`INSERT OR REPLACE INTO load_coordinates (load_id, origin_lat, origin_lng, dest_lat, dest_lng, pickup_address, dropoff_address) VALUES (?, ?, ?, ?, ?, ?, ?)`)
								.run(
									loadId,
									origin ? origin.lat : (row && row.origin_lat) || null,
									origin ? origin.lng : (row && row.origin_lng) || null,
									dest ? dest.lat : (row && row.dest_lat) || null,
									dest ? dest.lng : (row && row.dest_lng) || null,
									pickupAddr || (row && row.pickup_address) || "",
									dropoffAddr || (row && row.dropoff_address) || "",
								);
							row = db.prepare("SELECT * FROM load_coordinates WHERE load_id = ?").get(loadId);
							break;
						}
					}
				}
			} catch (err) {
				console.error("Lazy geocode failed for load", loadId, err.message);
			}
		}

		if (!row) return res.json({});
		const result = {};
		if (row.origin_lat) { result.originLat = row.origin_lat; result.originLng = row.origin_lng; }
		if (row.dest_lat) { result.destLat = row.dest_lat; result.destLng = row.dest_lng; }
		result.pickupAddress = row.pickup_address;
		result.dropoffAddress = row.dropoff_address;
		res.json(result);
	} catch (err) {
		res.status(500).json({ error: err.message });
	}
});

// GET /api/geocode/bulk — geocode all loads (Super Admin)
app.get("/api/geocode/bulk", requireRole("Super Admin"), async (req, res) => {
	try {
		const sheets = await getSheets();
		const resp = await sheets.spreadsheets.values.get({ spreadsheetId: SPREADSHEET_ID, range: "Job Tracking" });
		const rows = (resp.data.values || []);
		if (rows.length < 2) return res.json({ geocoded: 0, skipped: 0 });
		const headers = rows[0];
		const loadIdIdx = headers.findIndex(h => /load.?id|job.?id/i.test(h));
		const pickupIdx = headers.findIndex(h => /pickup.*address/i.test(h));
		const dropoffIdx = headers.findIndex(h => /drop.?off.*address|dest.*address/i.test(h));
		const addresses = new Set();
		for (let i = 1; i < rows.length; i++) {
			if (loadIdIdx !== -1 && !(rows[i][loadIdIdx] || "").trim()) continue;
			if (pickupIdx !== -1) { const a = (rows[i][pickupIdx] || "").trim(); if (a) addresses.add(a); }
			if (dropoffIdx !== -1) { const a = (rows[i][dropoffIdx] || "").trim(); if (a) addresses.add(a); }
		}
		let geocoded = 0, skipped = 0;
		for (const addr of addresses) {
			const cached = db.prepare("SELECT id FROM geocode_cache WHERE address = ?").get(addr.trim().toLowerCase());
			if (cached) { skipped++; continue; }
			await geocodeAddress(addr);
			geocoded++;
			await new Promise(r => setTimeout(r, 50)); // rate limit
		}
		res.json({ geocoded, skipped, total: addresses.size });
	} catch (err) {
		res.status(500).json({ error: err.message });
	}
});

// GET /api/weather — current weather at coordinates proxy
app.get("/api/weather", requireAuth, async (req, res) => {
	const { lat, lng } = req.query;
	if (!lat || !lng) return res.status(400).json({ error: "lat and lng required" });
	try {
		const resp = await fetch(
			`https://weather.googleapis.com/v1/forecast:lookup?location.latitude=${lat}&location.longitude=${lng}&unitsSystem=IMPERIAL&key=${GOOGLE_MAPS_API_KEY}`
		);
		if (!resp.ok) return res.json({ error: "unavailable" });
		const data = await resp.json();
		const current = data.currentConditions;
		if (!current) return res.json({ error: "no data" });
		res.json({
			condition: current.weatherCondition?.description?.text || current.weatherCondition?.type || "",
			tempF: current.temperature?.value ?? null,
			feelsLikeF: current.feelsLikeTemperature?.value ?? null,
			humidity: current.relativeHumidity ?? null,
			windMph: current.wind?.speed?.value ?? null,
			uvIndex: current.uvIndex ?? null,
		});
	} catch {
		res.json({ error: "unavailable" });
	}
});

// ============================================================
// INVESTOR — Financial & Investor View (Read-Only)
// ============================================================

// Job Tracking sheet cache — avoids hitting Google Sheets API on every investor request (2-5s).
// TTL 60s. Invalidated by mutation endpoints (dispatch, status update, load edit) via jtCacheInvalidate().
//
// The cache had no in-flight coalescing, so every concurrent cold miss fired
// its own full-tab fetch. One dashboard page load is several simultaneous
// 291 KB reads where one would do — and during the 2026-08-06 dead-socket
// outage each of those was an independent chance to draw a half-open socket,
// so the stampede was also a blast-radius multiplier. _jtInflight collapses
// them onto one request.
//
// ⚠️ A REJECTED promise must never be cached. Parking a failed fetch in
// _jtCache (or leaving it in _jtInflight) would serve the failure to every
// later caller and turn a single blip into a persistent outage — strictly
// worse than the stampede. Hence: _jtCache is written only after a successful
// parse, and _jtInflight is cleared in a `finally`, so the next caller after a
// failure starts a clean attempt.
let _jtCache = null;
let _jtInflight = null;
let _jtEpoch = 0;
const JT_CACHE_TTL = 60_000;
async function getJobTrackingCached() {
	if (_jtCache && (Date.now() - _jtCache.at) < JT_CACHE_TTL) return _jtCache.data;
	// Join the read already in flight rather than starting a second one.
	if (_jtInflight) return _jtInflight;

	// Snapshot the epoch: if a mutation invalidates the cache while this read is
	// in flight, the result is a PRE-mutation snapshot and must not be written
	// back — that would silently undo jtCacheInvalidate() and pin stale data for
	// another 60s. (Latent before coalescing too; it just bit one caller instead
	// of all of them.)
	const epoch = _jtEpoch;
	const attempt = (async () => {
		const sheets = await getSheets();
		const response = await sheets.spreadsheets.values.get({ spreadsheetId: SPREADSHEET_ID, range: "Job Tracking" });
		const parsed = parseSheet(response.data);
		parsed.data = deduplicateLoads(parsed.data, parsed.headers);
		if (_jtEpoch === epoch) _jtCache = { data: parsed, at: Date.now() };
		return parsed;
	})();
	_jtInflight = attempt;
	try {
		return await attempt;
	} finally {
		// Guard the identity check: a jtCacheInvalidate() during the read may
		// already have dropped this attempt and a newer one may own the slot.
		if (_jtInflight === attempt) _jtInflight = null;
	}
}
function jtCacheInvalidate() {
	_jtCache = null;
	_jtEpoch += 1;
	// Detach any read that started before this mutation so callers arriving
	// afterwards fetch fresh data instead of joining a stale request. Callers
	// already joined keep the older snapshot — exactly what they would have got
	// from their own pre-mutation request before coalescing existed.
	_jtInflight = null;
}

// ============================================================
// INVESTOR PAYOUTS — settlement helpers
// ============================================================

// 'YYYY-MM' (work month) → ISO date ('YYYY-MM-DD') of the last Friday of the
// month FOLLOWING the work month. Investors are settled the last Friday after
// the work month closes out.
//   '2026-05' → '2026-06-26'  (June 2026's last Friday)
//   '2026-06' → '2026-07-31'  (July 31 2026 is itself a Friday)
// Day 0 of (followingMonth + 1) is the last calendar day of the following
// month; Date normalizes the +2 month offset across year boundaries. We then
// walk back to the nearest Friday (getDay() === 5). All local-time, no UTC.
function lastFridayOfFollowingMonth(period) {
	const m = /^(\d{4})-(\d{2})$/.exec(String(period || "").trim());
	if (!m) throw new Error(`period must be 'YYYY-MM', got: ${period}`);
	const year = parseInt(m[1], 10);
	const monthIdx = parseInt(m[2], 10) - 1; // 0-based index of the work month
	const d = new Date(year, monthIdx + 2, 0); // last day of the FOLLOWING month
	const back = (d.getDay() - 5 + 7) % 7;     // days to step back to Friday
	d.setDate(d.getDate() - back);
	return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

// 'YYYY-MM' → "May 2026" for display.
function periodLabel(period) {
	const m = /^(\d{4})-(\d{2})$/.exec(String(period || "").trim());
	if (!m) return String(period || "");
	const d = new Date(parseInt(m[1], 10), parseInt(m[2], 10) - 1, 1);
	return d.toLocaleString("en-US", { month: "long", year: "numeric" });
}

// Single source of truth for the per-month investor take-home shown on the
// dashboard. This recomputes the SAME monthlyEarnings array the inline block in
// GET /api/investor builds (revenue − driverPay − fixedCosts − tripExpenses,
// then × investor_split_pct), using the same module-level primitives
// (getJobTrackingCached, getInvestorDriverSet, getDriverPayStructures,
// getDeductibleExpensesByDriverMonth, getEldTravelDaysByVehicle, ELD-intersected
// active days, admin day overrides, completed-status + Active-truck rules, the
// zero-activity fixed-cost deferral). The settlement layer
// (GET /api/investor/payouts) calls this so a payout's `amount` equals the
// dashboard's investorEarnings to the cent — no second formula.
//
// opts: { user, isSuperAdmin, investorDriverSet, investorOwnerId, config }
//   - investorDriverSet: Set of lowercased driver names, or null for Super Admin
//   - investorOwnerId:   user.id for an investor, or null for Super Admin
//   - config:            merged investor_config (must include investor_split_pct)
// One truck's monthly fixed cost, split into the parts the drill-down prints.
// BOTH the monthly total (getMonthlyFixedCosts) and the per-truck itemized rows
// go through this, so a headline can never round differently from the list that
// explains it — summing raw twelfths and rounding once gave $3,043 against an
// itemized $3,043.33, which read as two different answers to the same question.
// Annualized lines are divided by 12 and rounded to the cent, exactly as shown.
function truckMonthlyFixed(t) {
	const insurance = t.insurance_monthly || 0;
	const eld = t.eld_monthly || 0;
	const truckPayment = t.truck_payment_monthly || 0;
	const hvut = Math.round(((t.hvut_annual || 0) / 12) * 100) / 100;
	const irp = Math.round(((t.irp_annual || 0) / 12) * 100) / 100;
	return { insurance, eld, truckPayment, hvut, irp, total: Math.round((insurance + eld + truckPayment + hvut + irp) * 100) / 100 };
}

// The first 'YYYY-MM' a truck may be charged monthly fixed costs for, or "" when
// we have no date at all (callers then charge every month — today's behavior for
// a truck with neither date, so this is a no-op for existing rows).
//
// Companion to truckMonthlyFixed: that answers "how much per month", this answers
// "starting which month". Both exist so a headline, its drill-down, the P&L and
// the investor report cannot disagree — there were SEVEN independent copies of
// this month gate, and fixing one of them would have made the drill-down
// contradict the number it was explaining.
//
// in_service_date is the real answer. created_at is only when the row was typed
// into the Trucks UI, which for Logisx-#91 was ~2.5 months before the truck ever
// moved; charging from it billed May/June/July for a truck that entered service
// 2026-08-04.
//
// ⚠️ The in_service_date branch slices the STRING, and that is load-bearing, not
// style. in_service_date is a bare 'YYYY-MM-DD', which new Date() parses as UTC
// midnight — in America/Chicago that is 19:00 the PREVIOUS day, so a truck in
// service 2026-08-01 would read back as July and re-introduce the exact
// off-by-one-month overcharge this helper exists to kill. Never round-trip a
// bare date through Date here.
//
// ⚠️ The regex guard is equally load-bearing, because a slice cannot fail — it
// just returns something wrong-shaped that still compares. '2026-8-4' (what a
// hand-written UPDATE or a scripts/patch-*.js produces; the API validators
// reject it, direct SQL does not) slices to '2026-8-', and index 5 of any real
// 'YYYY-MM' is '0' or '1', both < '8' — so `monthKey < truckKey` is true for
// EVERY month and the truck silently books $0 fixed costs forever, ~$1,553/mo
// straight to the investor. 'not-a-date' behaves the same way. Anything not
// exactly YYYY-MM-DD therefore falls through to created_at, which is a stale
// answer but a sane one. This is the same regex truckMonthsInPeriod applies, so
// the two agree on malformed input instead of diverging.
//
// The created_at branch deliberately keeps new Date(): created_at is
// 'YYYY-MM-DD HH:MM:SS', which parses as LOCAL time and has no such shift. It is
// reproduced byte-for-byte from the gate it replaces so nothing can regress for
// the ~all rows that have no in_service_date yet.
function truckChargeFromMonth(t) {
	const inService = String(t.in_service_date || "").trim();
	if (/^\d{4}-\d{2}-\d{2}$/.test(inService)) return inService.slice(0, 7);
	if (t.created_at) {
		const td = new Date(t.created_at);
		return `${td.getFullYear()}-${String(td.getMonth() + 1).padStart(2, "0")}`;
	}
	return "";
}

// The LAST 'YYYY-MM' a truck may be charged monthly fixed costs for, or "" when
// it has not been retired (callers then charge forever — today's behavior for
// every existing row, so this is a no-op until someone sets the column).
//
// Exact mirror of truckChargeFromMonth, and every property of that helper is
// deliberately reproduced rather than re-invented:
//
// ⚠️ "" MEANS "CHARGE FOREVER", NOT "RETIRED AT THE EPOCH". This is the single
// most dangerous value in the pair. truckChargeFromMonth's callers read its ""
// as "charge in EVERY month" via the `truckKey &&` short-circuit; the mirror
// short-circuit `untilKey &&` must therefore read "" as "no upper bound". A gate
// or a guard that read "" as "retired long ago" would silently stop billing the
// ENTIRE fleet — every row has "" today — and a GUARD that read it that way
// would wave through precisely the truck with the most exposure. That exact
// inversion shipped once in the user-delete guard (PR #205) and once more in the
// truck-create guard (PR #216), from opposite directions, on the FROM half.
//
// ⚠️ The regex guard is load-bearing for the same reason it is on the FROM half,
// but the failure is MIRRORED and therefore worse. There, a malformed date
// ('2026-8-4', 'not-a-date') slices to something no month sorts above, so the
// truck silently books $0 forever. Here, a malformed value slices to something
// EVERY month sorts above, so a retired truck would keep billing — the failure
// is silent in both cases but points the opposite way. Anything not exactly
// YYYY-MM-DD therefore falls through to "" (never retired), which is the same
// "stale but sane" direction the FROM half takes to created_at, and is the
// conservative direction here: it keeps billing rather than stopping.
//
// ⚠️ Slices the STRING, never round-trips through new Date(). A bare date parses
// as UTC midnight, which in America/Chicago is 19:00 the PREVIOUS day — a truck
// retired 2026-08-01 would read back as July and drop a month of costs it is
// owed. Same trap, same fix, as the in_service_date branch above.
//
// There is deliberately NO created_at fallback. created_at is a lower bound by
// nature and means nothing as an end date; the only honest answer for a truck
// nobody has retired is "not retired".
function truckChargeUntilMonth(t) {
	const retired = String(t.retired_at || "").trim();
	const m = retired.match(/^(\d{4})-(\d{2})-(\d{2})$/);
	if (!m) return "";
	// ⚠️ DELIBERATE ASYMMETRY with truckChargeFromMonth: the month is range-checked
	// here and is not there. '2026-13-01' passes a bare shape test and slices to
	// '2026-13', which every real 2026 month sorts BELOW — so a truck "retired"
	// that way would bill all of 2026 and then silently stop in 2027. Neither
	// half of that is a retirement.
	//
	// The FROM half is not given the same check on purpose. It has a created_at
	// FALLBACK, so tightening it would change which months an existing malformed
	// row bills — a live behaviour change on rows that already have money against
	// them, for a case parseInServiceDate already refuses at the API boundary.
	// This half has no fallback and no existing rows at all, so validating costs
	// nothing and collapses an ambiguous state into the CONSERVATIVE one: "" =
	// keep billing. Direct SQL and scripts/patch-*.js are the paths the API
	// validators do not cover, and they are exactly how a '2026-13-01' arrives.
	const mo = parseInt(m[2], 10), dd = parseInt(m[3], 10);
	if (mo < 1 || mo > 12 || dd < 1 || dd > 31) return "";
	return retired.slice(0, 7);
}

// Is this truck charged fixed costs in `monthKey`? THE single predicate behind
// every fixed-cost month gate, so the interval can never be spelled two ways.
// Both bounds INCLUSIVE; an empty bound is no bound (see the two helpers above).
function truckChargedInMonth(t, monthKey) {
	const from = truckChargeFromMonth(t);
	if (from && monthKey < from) return false;
	const until = truckChargeUntilMonth(t);
	if (until && monthKey > until) return false;
	return true;
}

// How many months of fixed costs has this truck accrued as of `now`?
//
// The month-gate sites above ask "is this truck billed in month X" and walk a
// month cursor. The ALL-TIME total sites instead multiply one monthly figure by
// a COUNT of months — a second shape that needs its own end bound, because
// clamping the gate does nothing to a multiplication. There were four
// hand-rolled copies of this arithmetic (two in /api/investor, two in
// /api/financials); they are now one function for the same reason the gate is.
//
// Returns null when the start month is unparseable, so each caller keeps its own
// established fallback (`monthsOfOperation`) rather than having a new one
// imposed here — preserving today's behavior byte-for-byte for every row that
// has no retirement date.
//
// Floor 0, not 1: a forward-dated truck accrues nothing yet. Inclusive of BOTH
// endpoint months (+1), matching truckChargedInMonth — a truck in service and
// retired in the same month is billed exactly one month, not zero.
function truckBilledMonthCount(t, now) {
	const from = truckChargeFromMonth(t);
	const sy = parseInt(from.slice(0, 4), 10);
	const sm = parseInt(from.slice(5, 7), 10) - 1;
	if (!Number.isFinite(sy) || !Number.isFinite(sm)) return null;
	// End month = the current month, pulled back to the retirement month when the
	// truck has one. Never pushed FORWARD: a truck retired in the future is still
	// accruing today, so a later retired_at must not invent months it has not
	// lived through.
	let ey = now.getFullYear(), em = now.getMonth();
	const until = truckChargeUntilMonth(t);
	if (until) {
		const uy = parseInt(until.slice(0, 4), 10), um = parseInt(until.slice(5, 7), 10) - 1;
		if (Number.isFinite(uy) && Number.isFinite(um) && uy * 12 + um < ey * 12 + em) { ey = uy; em = um; }
	}
	return Math.max(0, (ey - sy) * 12 + (em - sm) + 1);
}

// returns: { monthlyEarnings: [...], currentMonthKey }
async function computeInvestorMonthlyEarnings({ user, isSuperAdmin, investorDriverSet, investorOwnerId, config, detailForMonth = null }) {
	const jobTracking = await getJobTrackingCached();
	const data = excludeDroppedLoads(jobTracking.data, jobTracking.headers);
	const headers = jobTracking.headers;
	const investorSplit = resolveInvestorSplitPct(config) / 100;

	// Local date helpers — identical to the ones inside GET /api/investor.
	//
	// ⚠️ THE LOCAL `parseSheetDate` IS DELETED, NOT MERELY UNUSED. Every date read
	// in this function now goes through the shared moneySheetDate(). A strict
	// ISO+US-only parser left sitting inline in a money handler is precisely how
	// this whole class of defect keeps coming back: the next date read reaches for
	// the nearest helper, gets a parser narrower than the sheet, and silently drops
	// or mis-dates the rows it cannot read (PR #215 assigned dates, PR #237 IFTA
	// rows and the drop-off end, this one the pickup end). Do not reintroduce it —
	// call moneySheetDate().
	const fmtDate = (d) => d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
	const expandDateRange = (start, end) => {
		const dates = [];
		const s = new Date(start); s.setHours(12, 0, 0, 0);
		const e = end ? new Date(end) : new Date(start);
		e.setHours(12, 0, 0, 0);
		if (e < s) return [fmtDate(s)];
		const MAX_SPAN = 31 * 24 * 3600 * 1000;
		if (e - s > MAX_SPAN) e.setTime(s.getTime() + MAX_SPAN);
		const cur = new Date(s);
		while (cur <= e) { dates.push(fmtDate(cur)); cur.setDate(cur.getDate() + 1); }
		return dates;
	};

	// Column resolution — same regexes as GET /api/investor.
	const jtRateCol = findCol(headers, /payment|rate|amount|revenue/i);
	const jtDateCol = findCol(headers, /status.*update.*date|completion.*date|assigned.*date/i) || findCol(headers, /date/i);
	const jtDriverCol = findCol(headers, /^driver$/i);
	const jtTruckCol = findCol(headers, /^truck$|truck[._\s-]?(unit|number|#)|unit[._\s-]?number/i);
	const statusCol = findCol(headers, /status/i);
	const pickupDateCol = findCol(headers, /pickup.*appo|pickup.*date/i);
	const dropoffDateCol = findCol(headers, /drop.?off.*appo|drop.?off.*date|delivery.*date/i);
	const ownerIdCol = findCol(headers, /^owner.?id$/i);
	const driverCol = findCol(headers, /^driver$/i);
	const completedStatuses = /^(delivered|completed|pod received)$/i;

	// Optional per-month line-item detail (drill-down). Collected ONLY for
	// `detailForMonth`, purely additive — it never affects any total computed below.
	// Match the rest of the codebase (NOT contract.?id): Job Tracking's column A is
	// "Contract ID" and is blank for email-ingested loads, so including it here binds
	// to the empty column and the drill-down "Load #" renders "—" on every row.
	const jtLoadIdCol = findCol(headers, /load.?id|job.?id/i);
	// Reuse the dashboard's address-column picker (skips lat/lng/date/appt columns)
	// so the drill-down route text never grabs a coordinate instead of a city.
	const jtPickupCol = pickAddressColumn(headers, /origin|pickup|shipper/i);
	const jtDropCol = pickAddressColumn(headers, /dest|drop|receiver|delivery/i);
	const detail = detailForMonth ? { revenueLoads: [], driverPayRows: [], fixedCostItems: [], tripExpenseItems: [] } : null;

	// Investor-scope the rows: Owner ID column (primary) or driver-set (fallback).
	const filteredJobData = investorDriverSet
		? data.filter(r => {
			if (ownerIdCol) {
				const raw = r[ownerIdCol];
				const hasOwnerIdValue = raw !== undefined && raw !== null && String(raw).trim() !== "";
				if (hasOwnerIdValue) return (parseInt(raw) || 0) === investorOwnerId;
			}
			const driver = driverCol ? (r[driverCol] || "").trim().toLowerCase() : "";
			return driver && investorDriverSet.has(driver);
		})
		: data;

	const now = new Date();
	// Houston month, not server-local: on the UTC VPS a plain getMonth() flips at
	// 19:00 (CDT) / 18:00 (CST) Houston on the last day of the month, so for the
	// final 5-6 hours of every month the portal showed the NEXT month accruing at
	// $0 and treated the just-ended one as complete. houstonDay() is the same
	// Central basis the stamps and the close lifecycle now use.
	const currentMonthKey = houstonDay(now).slice(0, 7);

	// ELD travel-day index per in-scope truck (same as GET /api/investor).
	const unitToVid = {};
	{
		const vidQuery = investorDriverSet
			? "SELECT LOWER(unit_number) AS u, routemate_vehicle_id AS vid FROM trucks WHERE owner_id = ? AND COALESCE(routemate_vehicle_id, '') != ''"
			: "SELECT LOWER(unit_number) AS u, routemate_vehicle_id AS vid FROM trucks WHERE COALESCE(routemate_vehicle_id, '') != ''";
		db.prepare(vidQuery).all(...(investorDriverSet ? [user.id] : [])).forEach(t => { unitToVid[t.u] = t.vid; });
	}
	const eldByVid = getEldTravelDaysByVehicleCached(Object.values(unitToVid), 0, Date.now() + 86400000);
	const driverDayOverrides = getAllExcludedDriverDays();

	// Pass: monthly revenue, per-driver active days (ELD-intersected), earliest date.
	const monthlyRevenue = {};
	const driverDaySets = {};
	const driverMonthlyDays = {};        // { driver: { mk: Set<day> } }
	const driverMonthlyRevenue = {};     // { driver: { mk: revenue } }
	let earliestDate = null;
	filteredJobData.forEach((r) => {
		const st = statusCol ? (r[statusCol] || "").trim() : "";
		const driver = jtDriverCol ? normalizeDriverName(r[jtDriverCol]) : "";
		const truckUnit = jtTruckCol ? (r[jtTruckCol] || "").trim().toLowerCase() : "";
		let assignedMonthKey = null;
		if (jtDateCol && r[jtDateCol]) {
			const d = moneySheetDate(r[jtDateCol]);
			if (d && !isNaN(d)) assignedMonthKey = fmtDate(d).slice(0, 7);
		}
		if (completedStatuses.test(st)) {
			const amt = parseFloat(String((jtRateCol ? r[jtRateCol] : "0")).replace(/[$,]/g, "")) || 0;
			if (amt && assignedMonthKey) {
				monthlyRevenue[assignedMonthKey] = (monthlyRevenue[assignedMonthKey] || 0) + amt;
				if (detail && assignedMonthKey === detailForMonth) {
					// ⚠️ CITY LEVEL ONLY — these two fields reach an INVESTOR, on the
					// payout statement PDF (lib/payout-statement.js routeText) and in the
					// on-screen revenue drill-down, and the street belongs to the BROKER'S
					// CUSTOMER, not to us. The raw sheet cell was being passed straight
					// through, so a statement printed e.g. "3311 EAST LINCOLN WAY AMES, IA
					// 50010 → 2930 114TH STREET GRAND PRAIRIE,TX 75050" — every shipper and
					// receiver's door, handed to an outside party. resolveCityState() is the
					// same reduction /api/investor's My Loads already uses; reduce at the
					// PUSH SITE so both consumers of revenueLoads inherit it and neither can
					// drift back to the raw string.
					const lid = jtLoadIdCol ? String(r[jtLoadIdCol] || "").trim() : "";
					detail.revenueLoads.push({
						loadId: lid,
						driver: driver || "",
						truck: jtTruckCol ? String(r[jtTruckCol] || "").trim() : "",
						date: jtDateCol ? String(r[jtDateCol] || "").trim() : "",
						pickup: resolveCityState(r, "pickup", lid, jtPickupCol ? r[jtPickupCol] : ""),
						dropoff: resolveCityState(r, "drop", lid, jtDropCol ? r[jtDropCol] : ""),
						amount: Math.round(amt * 100) / 100,
					});
				}
				if (driver) {
					if (!driverMonthlyRevenue[driver]) driverMonthlyRevenue[driver] = {};
					driverMonthlyRevenue[driver][assignedMonthKey] = (driverMonthlyRevenue[driver][assignedMonthKey] || 0) + amt;
				}
			}
		}
		if (completedStatuses.test(st) && driver) {
			// ⚠️ BOTH ENDS RESOLVE THROUGH moneySheetDate(), and the pickup end is the
			// half that was left behind by the drop-off fix. It used to call the strict
			// local parseSheetDate(), whose null is indistinguishable from a blank cell —
			// so the fallback on the line below fired on a cell that was present and
			// merely unreadable, silently starting the window at the ASSIGNED date (when
			// the rate-con email arrived) instead of at the pickup. That fallback's own
			// comment says "blank", which is what the code was documented to do and not
			// what it did.
			//
			// Unlike the drop-off this is a SHIFT, not a widening, so it was measured on
			// its own before shipping (see the union note at loadWindowDays for the guard
			// half). Production 2026-08-09, all 275 live rows: of 252 non-empty Pickup
			// Appointment cells exactly 2 are unreadable by the strict parser, and 1
			// resolves — load 529227269, "2025/09/23 23:59", whose window moves
			// [09-22, 09-23, 09-24] -> [09-23, 09-24], i.e. it LOSES 2025-09-22. The
			// per-period driver-pay delta is nevertheless $0.00 on EVERY period, on the
			// Super-Admin fleet scope and on all three investor scopes, because the
			// driver-month day set is a UNION and 2025-09-22 is independently supplied by
			// load 529231436 (pickup "9/22/25 16:00-18:00"). 2025-09 is locked and its
			// payout is unchanged. The other unreadable cell, "14:00" on 557861739, stays
			// null under both parsers — it is a time, not a date.
			//
			// It also ends a live disagreement inside the trio CLAUDE.md requires to
			// reconcile: POST /api/invoices/generate already reads that same cell as
			// 2025-09-23 (its parseInvoiceDate has a native-Date fallback), while this
			// function and GET /api/financials read 2025-09-22. Same load, same column,
			// two different pay windows.
			let pickup = moneySheetDate(pickupDateCol ? r[pickupDateCol] : null);
			// ⚠️ Drop-off resolves through moneySheetDate(), like the pickup fallback
			// on the next line. The local parseSheetDate() reads only ISO and US
			// M/D/Y, so a drop-off in any other shape returned null and collapsed
			// this load's window to the single pickup day — silently shortening the
			// driver's active-day window, which is driver pay, which is deducted
			// from the investor payout this function computes. Kept in lockstep with
			// the two twin sites in GET /api/investor and GET /api/financials.
			// Measured read-only on production 2026-08-09: of 251 non-empty drop-off
			// cells exactly 2 were unreadable; 1 resolves ("2025/09/24 23:59" on load
			// 529227269) and 1 correctly stays null ("9:00" is a time, not a date —
			// the new Date() tail branch rejects it rather than inventing a day). The
			// resolving row's own window goes 1 day -> 3, but the driver-month day set
			// is a UNION and those days already came from loads 529231436 / 528174081,
			// so the per-period driver-pay delta is $0.00 on every period and the
			// locked 2025-09 payout is untouched.
			const dropoff = moneySheetDate(dropoffDateCol ? r[dropoffDateCol] : null);
			if (!pickup && jtDateCol && r[jtDateCol]) pickup = moneySheetDate(r[jtDateCol]);
			if (pickup && !isNaN(pickup)) {
				const windowDays = expandDateRange(pickup, dropoff || pickup);
				const vid = truckUnit ? unitToVid[truckUnit] : null;
				const eld = vid ? eldByVid[vid] : null;
				const covered = eld && windowDays.some(d => eld.coverage.has(d));
				const eldCounted = covered ? windowDays.filter(d => eld.travel.has(d)) : windowDays;
				const ovr = driverDayOverrides[driver] || null;
				const skipSet = ovr ? ovr.remove : null;
				const counted = skipSet && skipSet.size ? eldCounted.filter(d => !skipSet.has(d)) : eldCounted;
				if (!driverDaySets[driver]) driverDaySets[driver] = new Set();
				counted.forEach(d => driverDaySets[driver].add(d));
				if (!driverMonthlyDays[driver]) driverMonthlyDays[driver] = {};
				counted.forEach(d => {
					const bucket = assignedMonthKey || d.slice(0, 7);
					if (!driverMonthlyDays[driver][bucket]) driverMonthlyDays[driver][bucket] = new Set();
					driverMonthlyDays[driver][bucket].add(d);
				});
			}
		}
		if (jtDateCol && r[jtDateCol]) {
			const d = moneySheetDate(r[jtDateCol]);
			if (d && !isNaN(d) && (!earliestDate || d < earliestDate)) earliestDate = d;
		}
	});

	// Admin-added days (ELD missed) — same bucketing as GET /api/investor.
	for (const [drv, ovr] of Object.entries(driverDayOverrides)) {
		if (!ovr.add || !ovr.add.size) continue;
		if (investorDriverSet && !investorDriverSet.has(drv)) continue;
		if (!driverDaySets[drv]) driverDaySets[drv] = new Set();
		if (!driverMonthlyDays[drv]) driverMonthlyDays[drv] = {};
		for (const d of ovr.add) {
			driverDaySets[drv].add(d);
			const bucket = d.slice(0, 7);
			if (!driverMonthlyDays[drv][bucket]) driverMonthlyDays[drv][bucket] = new Set();
			driverMonthlyDays[drv][bucket].add(d);
		}
	}

	// Per-month driver pay — fixed: activeDays × dailyRate; percentage:
	// max(0, monthRevenue − monthDeductible) × pct. Same as GET /api/investor.
	const payStructures = getDriverPayStructures();
	const expensesByDriverMonth = getDeductibleExpensesByDriverMonth();
	const trucksByDriver = {};
	{
		const truckQuery = investorDriverSet
			? "SELECT assigned_driver, driver_pay_daily FROM trucks WHERE owner_id = ?"
			: "SELECT assigned_driver, driver_pay_daily FROM trucks";
		db.prepare(truckQuery).all(...(investorDriverSet ? [user.id] : [])).forEach(t => {
			const d = normalizeDriverName(t.assigned_driver);
			if (d) trucksByDriver[d] = t.driver_pay_daily || 250;
		});
	}
	const monthlyDriverPay = {};
	for (const [driver, monthsMap] of Object.entries(driverMonthlyDays)) {
		const struct = payStructures[driver] || { payType: "fixed", payPercentage: 0 };
		const fixedRate = resolveDailyRate(struct.payDaily, trucksByDriver[driver]);
		for (const [mk, daySet] of Object.entries(monthsMap)) {
			const activeDays = daySet.size;
			const monthRev = (driverMonthlyRevenue[driver] || {})[mk] || 0;
			const monthExp = (expensesByDriverMonth[driver] || {})[mk] || 0;
			const net = Math.max(0, monthRev - monthExp);
			let pay;
			if (struct.payType === "percentage") {
				pay = Math.round((net * struct.payPercentage / 100) * 100) / 100;
			} else {
				pay = activeDays * fixedRate;
			}
			monthlyDriverPay[mk] = (monthlyDriverPay[mk] || 0) + pay;
			if (detail && mk === detailForMonth) {
				detail.driverPayRows.push({
					driver,
					activeDays,
					dailyRate: fixedRate,
					payType: struct.payType,
					payPercentage: struct.payPercentage,
					pay: Math.round(pay * 100) / 100,
				});
			}
		}
	}

	// Monthly trip expenses (P&L filter, owner_id OR month-bounded driver leg),
	// grouped by month. investorExpenseScopeSql is shared with GET /api/investor —
	// this function and that handler are documented as producing the identical
	// array, and the payouts ledger reads one while the portal reads the other, so
	// a second copy of this predicate is how they come to disagree.
	const monthlyTripExp = {};
	const investorExpenseWindows = investorOwnerId ? getInvestorDriverMonthWindows(investorOwnerId) : null;
	if (investorOwnerId) {
		const scope = investorExpenseScopeSql(investorOwnerId, investorExpenseWindows, EXPENSE_PERIOD_EXPR);
		db.prepare(
			`SELECT ${EXPENSE_PERIOD_EXPR} AS m, COALESCE(SUM(amount), 0) AS t FROM expenses WHERE ${scope.sql} AND ${EXPENSE_PNL_FILTER} GROUP BY m`
		).all(...scope.params).forEach(r => { if (r.m) monthlyTripExp[r.m] = r.t; });
	} else if (isSuperAdmin) {
		db.prepare(`SELECT ${EXPENSE_PERIOD_EXPR} AS m, COALESCE(SUM(amount), 0) AS t FROM expenses WHERE ${EXPENSE_PNL_FILTER} GROUP BY m`)
			.all().forEach(r => { if (r.m) monthlyTripExp[r.m] = r.t; });
	}

	// Per-expense line items for the drill-down month — SAME scope, P&L filter AND
	// period basis as the SUM above, so they reconcile to
	// monthlyTripExp[detailForMonth]. The displayed `date` stays the true purchase
	// date, so a receipt posted here from an earlier closed month shows its real
	// date while counting in this month — which is what makes the drill-down able
	// to explain itself ("Mar 14 fuel, posted to May").
	if (detail) {
		const expCols = "COALESCE(NULLIF(date,''), strftime('%Y-%m-%d', created_at)) AS date, type, description, amount, driver, truck_unit AS truck, location_city AS city, location_state AS state, posted_period AS postedPeriod";
		const monthExpr = EXPENSE_PERIOD_EXPR;
		if (investorOwnerId) {
			const scope = investorExpenseScopeSql(investorOwnerId, investorExpenseWindows, monthExpr);
			detail.tripExpenseItems = db.prepare(`SELECT ${expCols} FROM expenses WHERE ${scope.sql} AND ${EXPENSE_PNL_FILTER} AND ${monthExpr} = ? ORDER BY 1`).all(...scope.params, detailForMonth);
		} else if (isSuperAdmin) {
			detail.tripExpenseItems = db.prepare(`SELECT ${expCols} FROM expenses WHERE ${EXPENSE_PNL_FILTER} AND ${monthExpr} = ? ORDER BY 1`).all(detailForMonth);
		}
	}

	// Monthly maintenance-fund service disbursements + paid compliance fees,
	// grouped by month — same owner/super-admin scoping as the all-time
	// truck-level block in GET /api/investor. Puts per-month netProfit on the
	// SAME expense basis as the aggregate (and therefore the payout ledger).
	// Both tables are empty in prod today, so this is $0 — it unifies the basis.
	const monthlyMaintFund = {};
	const monthlyCompliance = {};
	if (investorOwnerId) {
		db.prepare(
			`SELECT strftime('%Y-%m', COALESCE(NULLIF(mf.date, ''), strftime('%Y-%m-%d', mf.created_at))) AS m, COALESCE(SUM(mf.amount), 0) AS t FROM maintenance_fund mf INNER JOIN trucks t ON LOWER(mf.truck) = LOWER(t.unit_number) WHERE t.owner_id = ? AND t.status = 'Active' AND mf.type = 'service' GROUP BY m`
		).all(investorOwnerId).forEach(r => { if (r.m) monthlyMaintFund[r.m] = r.t; });
		db.prepare(
			`SELECT strftime('%Y-%m', COALESCE(NULLIF(cf.paid_date, ''), NULLIF(cf.due_date, ''), strftime('%Y-%m-%d', cf.created_at))) AS m, COALESCE(SUM(cf.amount), 0) AS t FROM compliance_fees cf INNER JOIN trucks t ON LOWER(cf.truck) = LOWER(t.unit_number) WHERE t.owner_id = ? AND t.status = 'Active' AND cf.status = 'Paid' GROUP BY m`
		).all(investorOwnerId).forEach(r => { if (r.m) monthlyCompliance[r.m] = r.t; });
	} else if (isSuperAdmin) {
		db.prepare(
			`SELECT strftime('%Y-%m', COALESCE(NULLIF(date, ''), strftime('%Y-%m-%d', created_at))) AS m, COALESCE(SUM(amount), 0) AS t FROM maintenance_fund WHERE type = 'service' AND LOWER(truck) NOT IN (SELECT LOWER(unit_number) FROM trucks WHERE status != 'Active') GROUP BY m`
		).all().forEach(r => { if (r.m) monthlyMaintFund[r.m] = r.t; });
		db.prepare(
			`SELECT strftime('%Y-%m', COALESCE(NULLIF(paid_date, ''), NULLIF(due_date, ''), strftime('%Y-%m-%d', created_at))) AS m, COALESCE(SUM(amount), 0) AS t FROM compliance_fees WHERE status = 'Paid' AND LOWER(truck) NOT IN (SELECT LOWER(unit_number) FROM trucks WHERE status != 'Active') GROUP BY m`
		).all().forEach(r => { if (r.m) monthlyCompliance[r.m] = r.t; });
	}

	// Monthly fixed costs — Active trucks only, charged from the truck's
	// in-service month (truckChargeFromMonth: in_service_date, else created_at).
	const truckFixedQuery = investorDriverSet
		? "SELECT unit_number, insurance_monthly, eld_monthly, truck_payment_monthly, hvut_annual, irp_annual, created_at, in_service_date, retired_at FROM trucks WHERE owner_id = ? AND status = 'Active'"
		: "SELECT unit_number, insurance_monthly, eld_monthly, truck_payment_monthly, hvut_annual, irp_annual, created_at, in_service_date, retired_at FROM trucks WHERE status = 'Active'";
	const fixedTrucks = db.prepare(truckFixedQuery).all(...(investorDriverSet ? [user.id] : []));
	const getMonthlyFixedCosts = (monthKey) => {
		let total = 0;
		for (const t of fixedTrucks) {
			// In service by this month AND not yet retired. truckChargedInMonth is
			// the single predicate all four month gates share, so the settlement
			// figure, its drill-down, /api/investor, /api/financials and the
			// truckFixedCostLockedMonths GUARD cannot disagree about the interval.
			if (!truckChargedInMonth(t, monthKey)) continue;
			total += truckMonthlyFixed(t).total;
		}
		// Cents, not whole dollars — this figure is shown beside its own itemized
		// per-truck list, and the two have to agree.
		return Math.round(total * 100) / 100;
	};

	// Fixed-cost line items for the drill-down month (same in-service inclusion
	// guard as getMonthlyFixedCosts — if these two ever diverge the drill-down
	// contradicts the headline it is supposed to explain). Cleared below if the
	// month is zero-activity.
	if (detail) {
		for (const t of fixedTrucks) {
			if (!truckChargedInMonth(t, detailForMonth)) continue;
			detail.fixedCostItems.push({ truck: t.unit_number || "", ...truckMonthlyFixed(t) });
		}
	}

	// Build the per-month array from earliest month → current month inclusive.
	const monthlyEarnings = [];
	const startMonth = earliestDate
		? `${earliestDate.getFullYear()}-${String(earliestDate.getMonth() + 1).padStart(2, "0")}`
		: currentMonthKey;
	let cursor = new Date(parseInt(startMonth.slice(0, 4)), parseInt(startMonth.slice(5, 7)) - 1, 1);
	const endDate = new Date(now.getFullYear(), now.getMonth(), 1);
	while (cursor <= endDate) {
		const mk = `${cursor.getFullYear()}-${String(cursor.getMonth() + 1).padStart(2, "0")}`;
		const revenue = monthlyRevenue[mk] || 0;
		const driverPay = monthlyDriverPay[mk] || 0;
		const rawFixedCosts = getMonthlyFixedCosts(mk);
		const tripExpenses = monthlyTripExp[mk] || 0;
		const maintFundCost = monthlyMaintFund[mk] || 0;
		const complianceCost = monthlyCompliance[mk] || 0;
		// Zero-activity grace: defer fixed costs in months with no activity so
		// onboarding months don't read as losses (matches GET /api/investor,
		// including its driver-day-count guard for percentage drivers whose pay
		// nets to $0 but who were still active that month).
		const driverCount = Object.values(driverMonthlyDays).filter(m => m[mk] && m[mk].size).length;
		const isZeroActivity = revenue === 0 && driverPay === 0 && tripExpenses === 0 && maintFundCost === 0 && complianceCost === 0 && driverCount === 0;
		const fixedCosts = isZeroActivity ? 0 : rawFixedCosts;
		// Keep the fixed-cost drill-down consistent with the (possibly deferred) total.
		if (detail && mk === detailForMonth && fixedCosts === 0) detail.fixedCostItems = [];
		const netProfit = revenue - driverPay - fixedCosts - tripExpenses - maintFundCost - complianceCost;
		// Match GET /api/investor exactly: split is applied to the RAW netProfit
		// (the rounded netProfit is only what gets surfaced for display).
		const investorEarnings = Math.round(netProfit * investorSplit);
		monthlyEarnings.push({
			month: mk,
			revenue: Math.round(revenue),
			driverPay: Math.round(driverPay),
			fixedCosts,
			tripExpenses: Math.round(tripExpenses),
			maintFundCost: Math.round(maintFundCost),
			complianceCost: Math.round(complianceCost),
			netProfit: Math.round(netProfit),
			// Unrounded copies, to the cent. The payout waterfall and its statement
			// PDF show these so the summary reconciles EXACTLY with the itemized
			// drill-down (a $3,043.33 truck cost was displaying as $3,043 beside an
			// itemized list totalling $3,043.33). Purely additive: the rounded fields
			// above are untouched, so every other consumer — and the settlement math,
			// which splits the RAW netProfit above — is unchanged.
			exact: { revenue, driverPay, fixedCosts, tripExpenses, maintFundCost, complianceCost, netProfit },
			investorEarnings,
			isCurrentMonth: mk === currentMonthKey,
		});
		cursor.setMonth(cursor.getMonth() + 1);
	}
	return { monthlyEarnings, currentMonthKey, detail };
}

// ---- Loss carry-forward — ONE definition, every reader ---------------------
// A month where costs outran revenue (e.g. driver pay $12,250 on $10,310 of
// revenue) yields NEGATIVE investorEarnings. Storing that verbatim produced a
// "-$970 owed" payout row with a due date and a "mark paid" action — a debt
// the investor cannot settle and nonsense to show on a statement.
//
// Instead the loss carries forward as a deficit and is absorbed by later
// profitable months, which is where it belongs economically. Payable is never
// negative, and the lifetime total is unchanged: a month's shortfall reduces
// what later months pay out rather than inverting a single row.
//
// Walks oldest → newest (monthlyEarnings is ordered that way), so the result is
// deterministic and every caller that runs it is idempotent.
//
// ⚠️ This lived inline inside reconcileInvestorPayouts, which made the SETTLEMENT
// the only surface that knew about the carry — GET /api/investor published the
// full monthly share while the payouts ledger and the statement PDF published the
// post-carry figure, for the same month, and an investor comparing the two screens
// saw two different numbers. It is a module-scope helper so the second reader
// SHARES the walk instead of copying it; a second copy of this rule is how the
// next drift starts (same lesson as DRIVER_RENAME_TARGETS / investorExpenseScopeSql).
//
// Pure: no DB, no network, no mutation of the input. Returns
// { "YYYY-MM": { raw, payable, carriedIn, deferred } } for EVERY month passed in,
// so a caller may index it without a presence check.
function computeLossCarryForward(monthlyEarnings) {
	const carryByPeriod = {};
	let deficit = 0;
	for (const m of monthlyEarnings || []) {
		const raw = Math.round(m.investorEarnings);
		let payable, carriedIn = 0, deferred = 0;
		if (raw < 0) {
			deferred = -raw;      // this month's loss joins the running deficit
			deficit += deferred;
			payable = 0;
		} else {
			carriedIn = Math.min(deficit, raw); // earlier losses eat into this month
			payable = raw - carriedIn;
			deficit -= carriedIn;
		}
		carryByPeriod[m.month] = { raw, payable, carriedIn, deferred };
	}
	return carryByPeriod;
}

// Enumerate every investor that can be settled, as { ownerId, name }. An
// investor is settled by users.id, so we list `investors` rows whose user_id
// links to a real user with role 'Investor' (same join /api/investors-style
// listings use), then UNION in any `trucks.owner_id > 0` whose user is an
// Investor but is missing an `investors` profile row — that owner still has
// loads to reconcile. Name prefers investors.full_name, then the user's
// company_name / username. Sorted by name (case-insensitive) so the aggregate
// console and its monthlyTotals render deterministically.
function listSettlableInvestors() {
	const rows = db.prepare(`
		SELECT u.id AS ownerId,
		       COALESCE(NULLIF(TRIM(i.full_name), ''), NULLIF(TRIM(u.company_name), ''), u.username) AS name
		FROM users u
		LEFT JOIN investors i ON i.user_id = u.id
		WHERE u.role = 'Investor'
		UNION
		SELECT u.id AS ownerId,
		       COALESCE(NULLIF(TRIM(u.company_name), ''), u.username) AS name
		FROM (SELECT DISTINCT owner_id FROM trucks WHERE owner_id > 0) t
		JOIN users u ON u.id = t.owner_id
		WHERE u.role = 'Investor'
	`).all();
	// De-dup by ownerId (UNION already collapses identical rows, but the two
	// SELECTs can yield the same owner with a different name); keep the first
	// (investors.full_name-derived) name. Then sort by name.
	const byId = new Map();
	for (const r of rows) {
		if (!byId.has(r.ownerId)) byId.set(r.ownerId, { ownerId: r.ownerId, name: r.name || `Investor #${r.ownerId}` });
	}
	return [...byId.values()].sort((a, b) =>
		a.name.localeCompare(b.name, "en", { sensitivity: "base" })
	);
}

// Shared settlement reconcile for ONE investor — the single source of truth for
// both GET /api/investor/payouts (one owner) and GET /api/payouts (all owners).
// For every COMPLETED PAST work month (current/in-progress excluded) it
// idempotently UPSERTs one investor_payouts row: INSERT if missing (amount =
// that month's investorEarnings, due = lastFridayOfFollowingMonth, status
// 'owed'); refresh `amount` ONLY while still 'owed'; never touch
// processing/paid. amount === the dashboard's investorEarnings to the cent
// (via computeInvestorMonthlyEarnings — no second formula here).
//
// ctx carries request-scoped data fetched ONCE by the caller so a multi-investor
// loop never refetches per investor:
//   - ctx.sessionUser:  req.session.user (for the synthesized per-owner `user`)
//   - ctx.carrierDB:    getCarrierDBFromSQLite() result (shared)
//   - ctx.globalConfig: investor_config rows for owner_id = 0 as { key: value }
// The Job Tracking sheet is threaded implicitly: computeInvestorMonthlyEarnings
// reads getJobTrackingCached(), which the caller primes once up front so every
// investor reconciles against the same cached snapshot (no per-investor fetch).
// Returns { payouts, currentMonth, totals }.
async function reconcileInvestorPayouts(ownerId, ctx) {
	const carrierDB = ctx.carrierDB;
	const carrierDriverCol = findCol(carrierDB.headers, /driver/i) || carrierDB.headers[0];
	const carrierCarrierCol = findCol(carrierDB.headers, /carrier/i);
	const investorDriverSet = getInvestorDriverSet(ownerId, carrierDB.data, carrierDriverCol, carrierCarrierCol);

	// Per-investor config layered over the shared global defaults (owner_id = 0).
	const config = { ...ctx.globalConfig };
	db.prepare("SELECT key, value FROM investor_config WHERE owner_id = ?").all(ownerId).forEach((r) => (config[r.key] = r.value));

	// computeInvestorMonthlyEarnings only needs user.id for its owner-scoped
	// truck/expense queries; synthesize an investor-scoped user from the session.
	const user = { ...ctx.sessionUser, id: ownerId };
	const { monthlyEarnings, currentMonthKey } = await computeInvestorMonthlyEarnings({
		user, isSuperAdmin: false, investorDriverSet, investorOwnerId: ownerId, config,
	});

	// Per-period P&L lookup so the Payouts screen can show WHY each month paid
	// what it did (revenue − driverPay − fixedCosts − tripExpenses − maintFundCost
	// − complianceCost = netProfit, × split). Display-only — it does NOT feed
	// `amount`/carry-forward/totals below.
	const earningsByPeriod = {};
	monthlyEarnings.forEach((m) => { earningsByPeriod[m.month] = m; });
	const splitPct = Math.round(resolveInvestorSplitPct(config));

	// ---- Loss carry-forward -------------------------------------------------
	// computeLossCarryForward() (module scope, beside computeInvestorMonthlyEarnings)
	// is the single definition of this rule — GET /api/investor runs the SAME walk
	// over its own monthlyEarnings so the Earnings screen and this ledger cannot
	// publish different figures for one month. Pure and deterministic, so the
	// reconcile stays idempotent.
	const carryByPeriod = computeLossCarryForward(monthlyEarnings);

	// Reconcile completed PAST months into investor_payouts (idempotent).
	const findRow = db.prepare("SELECT * FROM investor_payouts WHERE owner_id = ? AND period = ?");
	const insertRow = db.prepare(
		"INSERT INTO investor_payouts (owner_id, period, amount, due_date, status) VALUES (?, ?, ?, ?, 'owed')"
	);
	const refreshAmount = db.prepare(
		"UPDATE investor_payouts SET amount = ? WHERE owner_id = ? AND period = ?"
	);
	// Stamps a row that was created AFTER its period had already been finalized —
	// an investor onboarded late, or a month that only became payable once older
	// data landed. There was no earlier value to prefer, and the period's inputs
	// are already frozen by the lock, so recording the current figure is correct.
	// Guarded on finalized_at = '' so it is idempotent (this runs on every GET,
	// and GET /api/payouts loops it per investor).
	const stampLateRow = db.prepare(
		"UPDATE investor_payouts SET finalized_at = ?, finalized_amount = ? WHERE owner_id = ? AND period = ? AND COALESCE(finalized_at,'') = ''"
	);
	// A month is "completed" only if BOTH clocks agree it is. currentMonthKey is
	// server-local (computeInvestorMonthlyEarnings), while the close lifecycle
	// runs on America/Chicago — so on a UTC server they disagree for the first
	// few hours of each month. Taking the stricter of the two keeps row existence
	// and `phase` from contradicting each other (a row that exists but reports
	// 'accruing', which is settleable while the UI calls it pending). Whichever
	// way the server's zone leans, the AND is always the conservative choice.
	const ctMonthKey = currentMonthKeyCT();
	const reconcile = db.transaction((months) => {
		for (const m of months) {
			if (m.isCurrentMonth || m.month >= currentMonthKey || m.month >= ctMonthKey) continue; // only completed past months
			const amount = carryByPeriod[m.month].payable;
			const existing = findRow.get(ownerId, m.month);
			if (!existing) {
				insertRow.run(ownerId, m.month, amount, lastFridayOfFollowingMonth(m.month));
				if (isLocked(m.month)) {
					stampLateRow.run(new Date().toISOString(), amount, ownerId, m.month);
					console.warn(`[period-close] ${m.month} was already finalized when owner ${ownerId}'s row was created — stamped at $${amount}`);
				}
			} else if (
				existing.status === "owed" &&
				!existing.finalized_at &&        // per-row: a month already settled on a published statement stays settled
				!periodWriteLocked(m.month) &&   // fleet-wide: the period itself is closed
				existing.amount !== amount
			) {
				// periodWriteLocked, not isLocked. This one guard is what the entire
				// month-close rests on — it is the line that freezes a settled figure
				// against all six drift sources — and isLocked() answers "not locked"
				// on ANY error, so an unreadable period_locks table silently re-opens
				// every finalized month to drift, on a page GET, with no log. Failing
				// closed instead leaves the stored amount exactly where it is, which
				// is the same thing a working lock does.
				//
				// The sibling stamp above deliberately still uses isLocked(): fail-
				// closed there would stamp finalized_at on rows in months that may be
				// open, freezing payouts that should still be moving. It does not need
				// the change either — with this refresh guard closed, an unstamped row
				// cannot drift anyway.
				// Refresh amount ONLY while the month is genuinely still open:
				// still 'owed' AND not finalized. This is what lets a straggler
				// receipt land in the prior month by itself during the grace window
				// — and what stops it doing so once the month has been closed and
				// its statement issued. Never overwrite a processing/paid
				// settlement. Also what heals rows written before carry-forward
				// existed.
				refreshAmount.run(amount, ownerId, m.month);
				// The whole reason investor_payout_history exists. This is the ONE
				// place a payout figure moves without anybody asking it to, and it
				// used to leave no trace — so a month that quietly changed between
				// two page loads was unexplainable after the fact.
				//
				// Deliberately inside this guard, not before it: the four conditions
				// above are what make the write change-only. The reconcile runs on
				// every GET and loops per investor on the admin console, so hooking
				// any earlier would log thousands of no-ops and bury the few real
				// movements. `m` carries the recomputed components, so the snapshot
				// costs nothing extra.
				recordPayoutChange({
					payoutId: existing.id,
					ownerId,
					period: m.month,
					kind: "recompute",
					oldAmount: existing.amount,
					newAmount: amount,
					detail: "recalculated from current loads and expenses",
					// splitPct (line ~18629) is already a whole-number percentage, and
					// m.exact holds the UNROUNDED components — the same values the
					// waterfall uses, so the history reconciles to it to the cent.
					breakdown: m.exact ? { ...m.exact, splitPct } : null,
					actor: "system",
				});
			}
		}
	});
	reconcile(monthlyEarnings);

	// Live-recomputed PAYABLE per period — what the month would settle at now
	// (e.g. after late receipts were logged), so the admin console can show the
	// gap vs the frozen `amount`. Post-carry-forward, so it compares like for like.
	const recomputedByPeriod = {};
	for (const m of monthlyEarnings) recomputedByPeriod[m.month] = carryByPeriod[m.month].payable;

	// Read back the settled rows (period DESC). effectiveAmount = amount +
	// adjustment is the corrected figure everything downstream (totals, display)
	// keys on; `amount` is preserved as the original auto-computed settlement.
	const rows = db.prepare(
		"SELECT id, owner_id, period, amount, due_date, status, paid_at, adjustment, adjustment_note, adjusted_by, adjusted_at, reopened_at, reopened_by, reopen_reason, finalized_at, finalized_amount, finalized_breakdown FROM investor_payouts WHERE owner_id = ? ORDER BY period DESC"
	).all(ownerId);
	const graceDays = settlementGraceDays();
	const payouts = rows.map((r) => {
		const adjustment = Number(r.adjustment || 0);
		const carry = carryByPeriod[r.period] || { raw: r.amount || 0, carriedIn: 0, deferred: 0 };
		const be = earningsByPeriod[r.period];
		return {
			id: r.id,
			ownerId: r.owner_id,
			period: r.period,
			periodLabel: periodLabel(r.period),
			amount: r.amount,
			// What the month itself earned before carry-forward (may be negative),
			// plus how the deficit moved, so a statement can explain why a
			// profitable month paid out less than it earned.
			monthEarnings: carry.raw,
			lossCarriedIn: carry.carriedIn,   // earlier losses absorbed by this month
			lossDeferred: carry.deferred,     // this month's own loss pushed forward
			adjustment,
			// A payout can be reduced to nothing but never inverted — a negative
			// adjusted total is a debt the investor can't settle. The adjust
			// endpoint rejects one outright; this clamp is the backstop for rows
			// written before that guard existed. adjustmentApplied is the delta
			// that ACTUALLY landed, so amount + adjustmentApplied === effectiveAmount
			// always holds on a statement row, and the totals stay exact.
			effectiveAmount: Math.max(0, Math.round((r.amount || 0) + adjustment)),
			adjustmentApplied: Math.max(0, Math.round((r.amount || 0) + adjustment)) - Math.round(r.amount || 0),
			adjustmentNote: r.adjustment_note || "",
			adjustedBy: r.adjusted_by || "",
			adjustedAt: r.adjusted_at || "",
			recomputedAmount: recomputedByPeriod[r.period] != null ? recomputedByPeriod[r.period] : null,
			dueDate: r.due_date,
			status: r.status,
			paidAt: r.paid_at || null,
			// Where this month sits in the close lifecycle. '' when the feature is
			// dormant, in which case the UI falls back to `status` alone and every
			// screen behaves exactly as it did before. See periodPhase().
			//   accruing  — in progress, not payable
			//   pending   — month over, books still open for straggler receipts;
			//               amount is still tracking live earnings
			//   finalized — closed and frozen; statement issued, settlement allowed
			phase: periodPhase(r.period),
			// Last day (inclusive, ET) the books stay open for this period. Shown on
			// pending rows as "closes {date}" — the whole point of the window is that
			// people can see how long they have left to get receipts in.
			graceEndsAt: graceEndsAt(r.period, graceDays),
			finalizedAt: r.finalized_at || "",
			// Set only when this row was walked BACKWARDS out of a settled state.
			// Surfaced so the console can mark a corrected row instead of it
			// silently looking like it was never advanced in the first place.
			reopenedAt: r.reopened_at || "",
			reopenedBy: r.reopened_by || "",
			reopenReason: r.reopen_reason || "",
			// Display-only P&L breakdown for this period (null if the month has
			// aged out of the live earnings window). monthShare is the gross split
			// of this month's netProfit, BEFORE loss carry-forward — see
			// monthEarnings / lossCarriedIn / lossDeferred above for how it nets
			// down to `amount`. Never feeds amount/effectiveAmount/totals.
			// Exact (unrounded) figures so the waterfall reconciles to the cent with
			// the line-item drill-down. monthShare is carry.raw — the SAME number the
			// settlement used (split applied to the raw netProfit, rounded once) —
			// rather than re-deriving it from the rounded netProfit, which could land
			// a dollar off the amount actually settled.
			breakdown: be ? {
				revenue: (be.exact || be).revenue,
				driverPay: (be.exact || be).driverPay,
				fixedCosts: (be.exact || be).fixedCosts,
				tripExpenses: (be.exact || be).tripExpenses,
				maintFundCost: (be.exact || be).maintFundCost || 0,
				complianceCost: (be.exact || be).complianceCost || 0,
				netProfit: (be.exact || be).netProfit,
				splitPct,
				monthShare: carry.raw,
			} : null,
		};
	});

	// Current, in-progress month — shown but NOT a payable row.
	const cur = monthlyEarnings.find((m) => m.month === currentMonthKey);
	// The open month's carry-forward slot. It is computed by the loop above for
	// every month, current one included, and until now was discarded for this
	// one — which is why the accrual card had no way to say anything except the
	// raw signed figure. Undefined when the month has no rows at all yet.
	const curCarry = carryByPeriod[currentMonthKey] || { raw: 0, payable: 0, carriedIn: 0, deferred: 0 };
	const currentMonth = {
		period: currentMonthKey,
		periodLabel: periodLabel(currentMonthKey),
		// ⚠️ SIGNED, and deliberately still signed: this is the month's ACCRUAL,
		// not a payable. A loss-making open month reads negative here (a live
		// investor sat at -2,450), which is honest but must NOT be rendered as
		// somebody's payout — use payableIfClosedNow for that, below.
		//
		// DO NOT clamp this at 0. It is the only place the open month's economics
		// appear in this response, and it is a term in the ledger reconciliation
		// (test-suite.js 53):
		//   paid+processing+owed+ACCRUING === earned+adjustments+carriedLoss−drift
		// `earned` (investorNetToDate) sums every month INCLUDING this one's loss,
		// and carriedLossOutstanding covers only periods < this one, so clamping
		// here moves the left side alone and the identity breaks by exactly the
		// loss. Folding the open month into carriedLossOutstanding would rebalance
		// it arithmetically but assert a settlement fact that has not happened —
		// the month is open, and a load delivering on the 28th can still erase the
		// deficit, at which point nothing was ever carried.
		amountInProgress: cur ? Math.round(cur.investorEarnings) : 0,
		// ---- What the month would settle at IF it closed right now ------------
		// A PROJECTION, not a settlement — the month is still open and every
		// figure below moves until it closes. Published because the client
		// otherwise cannot render an honest accrual card without re-deriving the
		// carry-forward rules itself, and settlement math faked client-side is a
		// hole this codebase has already had to close once (see the adjust guard).
		//
		// Same three quantities every settled payout row already publishes
		// (amount / lossCarriedIn / lossDeferred), so the open month finally has
		// the shape of the rows it will become. Never negative, for the same
		// reason a payout row never is: a loss defers, it does not invert.
		// Nothing here feeds amount/effectiveAmount/totals or the identity above.
		payableIfClosedNow: Math.max(0, curCarry.payable),
		// Earlier months' losses this month has soaked up so far. Why a
		// PROFITABLE open month can still project a payout of $0.
		lossCarriedIn: curCarry.carriedIn,
		// This month's own shortfall so far, i.e. what would carry forward if it
		// closed today. This is the number to disclose beside a $0 accrual —
		// it is the same deficit amountInProgress is showing as a negative.
		lossDeferred: curCarry.deferred,
		// ⚠️ COMPUTED, NOT HARDCODED — /api/payouts and /api/periods were answering
		// differently about the SAME month. This was the literal string "accruing"
		// while GET /api/periods reports periodPhase(), which returns "" whenever
		// PERIOD_FINALIZE_ENABLED is off (and whenever period_locks cannot be read).
		// So with the flag off the payouts screen asserted a close lifecycle that
		// the close calendar simultaneously denied, and "" is not a cosmetic
		// difference: it is this codebase's documented signal for "no month will
		// ever close here, fall back to `status` alone", which is exactly what a
		// dormant deployment must render.
		//
		// periodPhase() is the one that knows about the flag, so it wins. In
		// production (flag ON, lock table readable) it returns "accruing" for the
		// current month by its own final line — `p >= currentMonthKeyCT()` — so the
		// live payload is UNCHANGED and only the flag-off/unreadable cases move,
		// which are the cases that were disagreeing.
		phase: periodPhase(currentMonthKey),
		// When this month will close, so the accrual card can say "closes Sep 7"
		// rather than the vaguer "not yet payable until the period closes".
		graceEndsAt: graceEndsAt(currentMonthKey, graceDays),
		// EXACT components and `curCarry.raw`, exactly like the settled rows above.
		// This block was the one place left re-deriving the split from an already
		// ROUNDED netProfit, and it was a dollar off in production.
		//
		// The open month of a live investor (Johnny Rocks Spirits, 2026-08): revenue
		// 1800 − driverPay 150 − fixedCosts 6149.16 − tripExpenses 400 = −4899.16,
		// halved = −2449.58, rounded ONCE = −2450. That −2450 is what
		// `amountInProgress` publishes and what `lossDeferred` (2450) agrees with.
		// The old `monthShare` first rounded netProfit to −4899, then halved it to
		// −2449.5 — and Math.round rounds a negative half TOWARD ZERO (−2449.5 →
		// −2449, not −2450). So the card's own expandable breakdown contradicted the
		// shortfall sentence printed directly above it by $1. The breakdown was the
		// odd one out of three published figures, which is why the fix belongs here
		// and NOT in the settlement: rounding once at the end is strictly more
		// accurate than halving a pre-rounded part, and `amountInProgress` is already
		// the number this month will settle at when it closes.
		//
		// ⚠️ Not a rare coincidence for this investor. fixedCosts 6149.16 is two real
		// trucks (#33 3043.33 + #91 3105.83), so against whole-dollar revenue the raw
		// net always ends in cents that put the halved figure exactly on a .5
		// boundary — every page load was wrong, not one in a hundred.
		//
		// ⚠️ Nothing about the money moves. `amountInProgress`, `payableIfClosedNow`,
		// `lossCarriedIn` and `lossDeferred` are untouched; `totals` never reads this
		// object; and `breakdown` is display-only (its sole consumer is the accrual
		// card's waterfall in PayoutsSection.vue). The settled rows' `breakdown` — not
		// this one — is what finalizePeriods() snapshots into `finalized_breakdown`,
		// so no stored or frozen figure can see this change and the ledger identity
		// in test-suite.js 53 cannot either.
		//
		// The components were also MIXED — revenue/driverPay/tripExpenses arrive
		// pre-rounded from monthlyEarnings while fixedCosts does not — so the
		// drill-down did not even sum to its own netProfit line (−4899.16 of parts
		// under a −4899 total) while the waterfall renders every row to the cent.
		// `(cur.exact || cur)` is the same expression the settled rows use; the
		// `|| cur` fallback keeps an older monthlyEarnings shape (no `exact` block)
		// rendering rather than emitting undefined.
		//
		// A sub-dollar gap between `netProfit × splitPct` and `monthShare` REMAINS by
		// design (−4899.16 × 50% = −2449.58 vs −2450): that is the single settlement
		// rounding, and the settled rows have carried exactly the same property since
		// they were fixed. Publishing the exact netProfit beside it is what discloses
		// that gap instead of hiding it behind a second rounding.
		breakdown: cur ? {
			revenue: (cur.exact || cur).revenue,
			driverPay: (cur.exact || cur).driverPay,
			fixedCosts: (cur.exact || cur).fixedCosts,
			tripExpenses: (cur.exact || cur).tripExpenses,
			maintFundCost: (cur.exact || cur).maintFundCost || 0,
			complianceCost: (cur.exact || cur).complianceCost || 0,
			netProfit: (cur.exact || cur).netProfit,
			splitPct,
			// curCarry.raw is Math.round(cur.investorEarnings) — the SAME quantity
			// amountInProgress publishes, so the two can no longer disagree. Safe
			// against the `{raw: 0}` fallback on the line above: carryByPeriod is
			// built from every monthlyEarnings entry, so whenever `cur` is truthy
			// (the only case this object is emitted at all) the real slot exists.
			monthShare: curCarry.raw,
		} : null,
	};

	const totals = payouts.reduce((acc, p) => {
		if (p.status === "owed") acc.totalOwed += p.effectiveAmount;
		else if (p.status === "processing") acc.totalProcessing += p.effectiveAmount;
		else if (p.status === "paid") acc.totalPaid += p.effectiveAmount;
		// Sum what LANDED, not what was requested — a clamped deduction only
		// moved the row as far as $0, so the banner identity stays exact.
		acc.totalAdjustments += Number(p.adjustmentApplied || 0);
		return acc;
	}, { totalOwed: 0, totalProcessing: 0, totalPaid: 0, totalAdjustments: 0 });
	totals.totalOwed = Math.round(totals.totalOwed);
	totals.totalProcessing = Math.round(totals.totalProcessing);
	totals.totalPaid = Math.round(totals.totalPaid);
	// Manual settlement adjustments are NOT part of investorNetToDate (that stays
	// the untouched operational earnings figure, so it keeps reconciling with the
	// Earnings section and the P&L). They land in the three status totals via
	// effectiveAmount, which would silently break the "everything adds up to
	// Earned" property the banner relies on. Reporting the sum lets the banner
	// name the difference instead of leaving an unexplained gap.
	totals.totalAdjustments = Math.round(totals.totalAdjustments);
	// Loss deficit still unabsorbed after the last COMPLETED month — a carried
	// loss with no later profit to eat it yet. Like adjustments it sits between
	// earnings and payable, so the banner has to account for it to balance.
	totals.carriedLossOutstanding = Object.entries(carryByPeriod)
		.filter(([period]) => period < currentMonthKey)
		.reduce((d, [, c]) => d + c.deferred - c.carriedIn, 0);

	return { payouts, currentMonth, totals };
}

// GET /api/investor — Aggregated financial data for investor view
app.get("/api/investor", requireRole("Super Admin", "Investor"), async (req, res) => {
	try {
		const jobTracking = await getJobTrackingCached();
		// Drop soft-deleted + cancelled loads before any aggregation so investor
		// dashboards match the admin KPIs exactly.
		jobTracking.data = excludeDroppedLoads(jobTracking.data, jobTracking.headers);
		const carrierDB = getCarrierDBFromSQLite();

		// Super Admin can pass ?as_user_id=N to preview a specific investor's
		// portal (read-only admin "view as" flow). When in preview mode the
		// endpoint takes the investor-scoped branch using the target's user_id;
		// `user` and `isSuperAdmin` shadow the session values so the rest of
		// the endpoint scopes data as if the admin were logged in as that
		// investor. Outside preview mode the values match the session user.
		const preview = resolvePreviewUser(req);
		const user = {
			...preview.sessionUser,
			id: preview.effectiveUserId,
			username: preview.effectiveUsername,
		};
		const isSuperAdmin = preview.sessionUser.role === "Super Admin" && !preview.isPreview;
		if (preview.isPreview) {
			logAudit(req, "investor_preview_view", "investor", preview.effectiveUserId, "");
		}

		// Resolve carrier DB columns (history sync moved to POST/PUT /api/drivers-directory)
		const carrierDriverCol = findCol(carrierDB.headers, /driver/i) || carrierDB.headers[0];
		const carrierCarrierCol = findCol(carrierDB.headers, /carrier/i);

		// Get investor's driver names (current + historical) for data filtering
		let investorDriverSet = null; // null = no filter (Super Admin)
		const investorOwnerId = !isSuperAdmin ? user.id : null;
		// ...and the MONTHS each of those drivers was actually this investor's, which
		// is what the expense queries below scope on. The set alone is "right now"
		// and restates closed months every time a driver moves trucks — see the
		// ⚠️ on getInvestorDriverMonthWindows().
		let investorExpenseWindows = null;
		if (!isSuperAdmin) {
			investorDriverSet = getInvestorDriverSet(user.id, carrierDB.data, carrierDriverCol, carrierCarrierCol);
			investorExpenseWindows = getInvestorDriverMonthWindows(user.id);
		}

		// Load per-investor config with fallback to global defaults (owner_id=0)
		const globalConfig = db.prepare("SELECT key, value FROM investor_config WHERE owner_id = 0").all();
		const config = {};
		globalConfig.forEach((r) => (config[r.key] = r.value));
		if (!isSuperAdmin) {
			const investorConfig = db.prepare("SELECT key, value FROM investor_config WHERE owner_id = ?").all(user.id);
			investorConfig.forEach((r) => (config[r.key] = r.value)); // override globals
		}

		// Filter sheet data by Owner ID column (primary) or driver name (fallback for old data).
		// An EMPTY Owner ID cell falls back to driver-name match (legacy rows from before
		// the Owner ID column existed). An EXPLICIT value — including "0" — is trusted as-is
		// and stops the fallback, so a company-truck load (Owner ID = 0) run by an investor's
		// driver doesn't leak into that investor's view.
		const driverCol = findCol(jobTracking.headers, /^driver$/i);
		const ownerIdCol = findCol(jobTracking.headers, /^owner.?id$/i);
		const filteredJobData = investorDriverSet
			? jobTracking.data.filter(r => {
				if (ownerIdCol) {
					const raw = r[ownerIdCol];
					const hasOwnerIdValue = raw !== undefined && raw !== null && String(raw).trim() !== "";
					if (hasOwnerIdValue) {
						return (parseInt(raw) || 0) === investorOwnerId;
					}
				}
				const driver = driverCol ? (r[driverCol] || "").trim().toLowerCase() : "";
				return driver && investorDriverSet.has(driver);
			})
			: jobTracking.data;

		const filteredCarrierData = investorDriverSet
			? carrierDB.data.filter(r => {
				const driver = (r[carrierDriverCol] || "").trim().toLowerCase();
				return driver && investorDriverSet.has(driver);
			})
			: carrierDB.data;

		// ---- Production Performance (from Job Tracking) ----
		const jtRateCol = findCol(jobTracking.headers, /payment|rate|amount|revenue/i);
		const jtDateCol = findCol(jobTracking.headers, /status.*update.*date|completion.*date|assigned.*date/i)
			|| findCol(jobTracking.headers, /date/i);
		const jtDriverCol = findCol(jobTracking.headers, /^driver$/i);
		const jtTruckCol = findCol(jobTracking.headers, /^truck$|truck[._\s-]?(unit|number|#)|unit[._\s-]?number/i);
		const statusCol = findCol(jobTracking.headers, /status/i);
		const pickupDateCol = findCol(jobTracking.headers, /pickup.*appo|pickup.*date/i);
		const dropoffDateCol = findCol(jobTracking.headers, /drop.?off.*appo|drop.?off.*date|delivery.*date/i);

		// ⚠️ The local `parseSheetDate` is DELETED, not merely unused — every date
		// read in this handler now goes through the shared moneySheetDate(). See the
		// note at the top of computeInvestorMonthlyEarnings() for why leaving a
		// narrower parser inline in a money handler is the defect, not a convenience.
		// Helper: format a Date as "YYYY-MM-DD" using LOCAL time (avoids UTC shift)
		function fmtDate(d) {
			return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
		}
		// Helper: expand two dates into an array of "YYYY-MM-DD" strings (inclusive)
		function expandDateRange(start, end) {
			const dates = [];
			const s = new Date(start); s.setHours(12, 0, 0, 0);
			const e = end ? new Date(end) : new Date(start);
			e.setHours(12, 0, 0, 0);
			if (e < s) return [fmtDate(s)];
			// Cap at 31 days to prevent runaway loops on bad data (no trucking load spans >31 days)
			const MAX_SPAN = 31 * 24 * 3600 * 1000;
			if (e - s > MAX_SPAN) e.setTime(s.getTime() + MAX_SPAN);
			const cur = new Date(s);
			while (cur <= e) {
				dates.push(fmtDate(cur));
				cur.setDate(cur.getDate() + 1);
			}
			return dates;
		}
		const loadIdCol = findCol(jobTracking.headers, /load.?id|job.?id/i);
		const completedStatuses = /^(delivered|completed|pod received)$/i;

		// ---- Miles source: load_coordinates table ----
		// Prefer cached road distance (Google Routes API, distance_miles
		// column). Fall back to haversine straight-line when the backfill
		// hasn't run yet. Same pattern as /api/financials.
		const milesByLoadId = {};
		{
			const coordRows = db.prepare(
				"SELECT load_id, origin_lat, origin_lng, dest_lat, dest_lng, distance_miles FROM load_coordinates WHERE origin_lat IS NOT NULL AND dest_lat IS NOT NULL"
			).all();
			for (const c of coordRows) {
				if (c.distance_miles != null && c.distance_miles > 0) {
					milesByLoadId[(c.load_id || "").toLowerCase()] = c.distance_miles;
				} else {
					const meters = geolib.getDistance(
						{ latitude: c.origin_lat, longitude: c.origin_lng },
						{ latitude: c.dest_lat, longitude: c.dest_lng }
					);
					milesByLoadId[(c.load_id || "").toLowerCase()] = meters / 1609.344;
				}
			}
		}

		// ---- Single-pass: revenue + driver pay + operating period + per-driver gross ----
		// (Driver active days now key off completedStatuses ∩ ELD travel — see the
		// active-day block below — so the old broad activeWorkStatuses set is gone.)
		let totalRevenue = 0;
		let last30DaysRevenue = 0;
		let earliestDate = null;
		let latestDate = null;
		const monthlyRevenue = {};
		const completedLoadIds = new Set();
		const grossByDriver = {};       // per-driver completed revenue (replaces Pass 3 inner loop)
		const milesByDriver = {};       // per-driver haversine miles (replaces odoByDriver)
		const milesByTruck = {};        // per-truck haversine miles
		const loadsByDriver = {};       // per-driver completed load count (fallback when no truck column)
		const loadsByTruck = {};        // per-truck completed load count (preferred when truck column exists)
		// Per-truck per-month REVENUE (completed loads only), bucketed by the load's
		// ASSIGNED month exactly like monthlyRevenue / driverMonthlyRevenue below.
		// Needed because perTruckData.unitMonthlyGross is DRIVER-keyed: two trucks
		// sharing a driver each read back that driver's full gross, so it cannot say
		// which truck earned what. The per-truck projection at the bottom of this
		// handler needs revenue on the same monthly clock as monthlyEarnings, and
		// this is the only place both keys (truckUnit + assignedMonthKey) are already
		// in hand — so it costs no extra query and no extra sheet read.
		const revenueByTruckMonth = {}; // { truckUnit: { "YYYY-MM": revenue } }
		const driverDaySets = {};        // per-driver active day Sets (all-time, used for totals)
		// Driver active days bucketed by LOAD'S ASSIGNED MONTH (not by physical day).
		// This matches how revenue is bucketed — both should answer the question:
		// "for loads assigned in month X, how much did we earn and how much did we
		// pay the driver?" Previously loads assigned in April with old pickup dates
		// in 2021 would show their revenue in April but their driver pay in 2021.
		const driverMonthlyDays = {};    // { driver: { "YYYY-MM": Set<"YYYY-MM-DD"> } }
		// Per-driver per-month per-day → contributing load IDs. Surfaces in the
		// "Driver Pay Explained" modal so an investor can see e.g. May 18 was
		// covered by loads 553198052 AND 552854956 (one calendar day, two loads).
		const driverMonthlyDayLoads = {}; // { driver: { "YYYY-MM": { "YYYY-MM-DD": Set<loadId> } } }
		// Preserve original sheet casing for display ("Howard Reddie" vs the
		// lowercased "howard reddie" key used internally).
		const driverDisplayName = {};    // { normalizedDriver: "Original Casing" }
		// Per-driver per-month REVENUE (completed loads only). Used by the
		// percentage-pay branch so owner-op pay = (monthRevenue − monthDeductible) × pct.
		const driverMonthlyRevenue = {}; // { driver: { "YYYY-MM": revenue } }
		// Admin overrides — Super Admin moves a (driver, date) into or out of
		// the active-day count. `remove` drops a day the ELD over-counted;
		// `add` credits a day the ELD missed (truck offline, etc.). Applied
		// the same way across /api/investor, /api/financials, and the weekly
		// invoice so the three numbers stay reconciled.
		const driverDayOverrides = getAllExcludedDriverDays();
		const now = new Date();
		const thirtyDaysAgo = new Date(now);
		thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

		// ---- ELD travel-day index (per linked vehicle) ----
		// Map each in-scope truck's unit number → its Routemate vehicle id, then
		// fetch the calendar days each vehicle actually traveled. The active-day
		// loop below intersects a COMPLETED load's pickup→delivery window with
		// these days, so we never count scheduled days the truck sat still nor
		// ELD travel on a day with no load. Trucks with no ELD link fall back to
		// the full window (so un-instrumented investors are unaffected).
		const unitToVid = {};
		{
			const vidQuery = investorDriverSet
				? "SELECT LOWER(unit_number) AS u, routemate_vehicle_id AS vid FROM trucks WHERE owner_id = ? AND COALESCE(routemate_vehicle_id, '') != ''"
				: "SELECT LOWER(unit_number) AS u, routemate_vehicle_id AS vid FROM trucks WHERE COALESCE(routemate_vehicle_id, '') != ''";
			db.prepare(vidQuery).all(...(investorDriverSet ? [user.id] : [])).forEach(t => { unitToVid[t.u] = t.vid; });
		}
		const eldByVid = getEldTravelDaysByVehicleCached(Object.values(unitToVid), 0, Date.now() + 86400000);
		// Per-driver-per-month ELD-source flags for the UI badge: { driver: { "YYYY-MM": {eld,est} } }
		const driverDaySource = {};
		const daySrcLabel = (o) => o ? (o.eld && o.est ? "mixed" : o.eld ? "eld" : "estimated") : "estimated";
		const driverSrcAllTime = (drv) => {
			const m = driverDaySource[drv]; if (!m) return "estimated";
			let eld = false, est = false;
			for (const k in m) { if (m[k].eld) eld = true; if (m[k].est) est = true; }
			return daySrcLabel({ eld, est });
		};

		filteredJobData.forEach((r) => {
			const st = statusCol ? (r[statusCol] || "").trim() : "";
			const driver = jtDriverCol ? normalizeDriverName(r[jtDriverCol]) : "";
			const truckUnit = jtTruckCol ? (r[jtTruckCol] || "").trim().toLowerCase() : "";

			// Resolve the load's assigned-month key once (used by both revenue and driver pay)
			let assignedMonthKey = null;
			if (jtDateCol && r[jtDateCol]) {
				const d = moneySheetDate(r[jtDateCol]);
				if (d && !isNaN(d)) assignedMonthKey = fmtDate(d).slice(0, 7);
			}

			// Revenue (completed loads only)
			if (completedStatuses.test(st)) {
				if (driver) loadsByDriver[driver] = (loadsByDriver[driver] || 0) + 1;
				if (truckUnit) loadsByTruck[truckUnit] = (loadsByTruck[truckUnit] || 0) + 1;
				const amt = parseFloat(String((jtRateCol ? r[jtRateCol] : "0")).replace(/[$,]/g, "")) || 0;
				if (amt) {
					const lid = loadIdCol ? (r[loadIdCol] || "").trim() : "";
					if (lid) completedLoadIds.add(lid);
					totalRevenue += amt;
					if (driver) grossByDriver[driver] = (grossByDriver[driver] || 0) + amt;
					// Haversine miles per load (straight-line, load_coordinates)
					const loadMiles = milesByLoadId[lid.toLowerCase()] || 0;
					if (loadMiles > 0) {
						if (driver) milesByDriver[driver] = (milesByDriver[driver] || 0) + loadMiles;
						if (truckUnit) milesByTruck[truckUnit] = (milesByTruck[truckUnit] || 0) + loadMiles;
					}
					if (assignedMonthKey) {
						const d = moneySheetDate(r[jtDateCol]);
						if (d >= thirtyDaysAgo) last30DaysRevenue += amt;
						monthlyRevenue[assignedMonthKey] = (monthlyRevenue[assignedMonthKey] || 0) + amt;
						if (driver) {
							if (!driverMonthlyRevenue[driver]) driverMonthlyRevenue[driver] = {};
							driverMonthlyRevenue[driver][assignedMonthKey] =
								(driverMonthlyRevenue[driver][assignedMonthKey] || 0) + amt;
						}
						// Same accumulation, keyed on the sheet's truck column. Paired with
						// driverMonthlyRevenue above the way loadsByTruck pairs with
						// loadsByDriver: truck attribution is preferred, driver attribution
						// is the fallback for sheets/rows with no usable truck column.
						if (truckUnit) {
							if (!revenueByTruckMonth[truckUnit]) revenueByTruckMonth[truckUnit] = {};
							revenueByTruckMonth[truckUnit][assignedMonthKey] =
								(revenueByTruckMonth[truckUnit][assignedMonthKey] || 0) + amt;
						}
					}
				}
			}

			// Driver active days — COMPLETED loads only (so driver pay is counted
			// the same way as revenue), intersected with the days the truck
			// actually traveled per ELD. A scheduled window day with no movement
			// is not an active day; ELD travel on a day with no load is not one
			// either. Falls back to the full pickup→delivery window only when the
			// truck has no ELD link/data.
			if (completedStatuses.test(st) && driver) {
				// BOTH ends resolve through the shared moneySheetDate(), matching the
				// fallback below and the twin sites in computeInvestorMonthlyEarnings()
				// and GET /api/financials — see the full rationale and production
				// measurement at the first of those. These three MUST stay in lockstep
				// or the investor portal, the P&L and the weekly invoice stop
				// reconciling; the pickup end is the half that was still diverging from
				// POST /api/invoices/generate.
				let pickup = moneySheetDate(pickupDateCol ? r[pickupDateCol] : null);
				const dropoff = moneySheetDate(dropoffDateCol ? r[dropoffDateCol] : null);
				// Completed load with an unreadable or blank pickup → fall back to its
				// assigned date. Now genuinely the last resort: before the line above
				// read the cell through the shared resolver, a present-but-unreadable
				// pickup landed here too, contradicting this comment.
				if (!pickup && jtDateCol && r[jtDateCol]) pickup = moneySheetDate(r[jtDateCol]);
				if (pickup && !isNaN(pickup)) {
					const windowDays = expandDateRange(pickup, dropoff || pickup);
					const vid = truckUnit ? unitToVid[truckUnit] : null;
					const eld = vid ? eldByVid[vid] : null;
					// Intersect with real travel days ONLY when the ELD covered this
					// load's window (≥1 ping). Uncovered windows (load predates the
					// feed, or no link) fall back to the full window so historical pay
					// isn't zeroed; a covered-but-parked window stays 0.
					const covered = eld && windowDays.some(d => eld.coverage.has(d));
					const eldCounted = covered ? windowDays.filter(d => eld.travel.has(d)) : windowDays;
					// Drop admin-removed days last. The ELD/estimated source flag
					// still reflects the underlying day source — an override is a
					// manual adjustment, not a change to how the day was originally
					// classified. Admin-added days are applied after this loop so
					// they don't depend on a load existing for that date.
					const ovr = driverDayOverrides[driver] || null;
					const skipSet = ovr ? ovr.remove : null;
					const counted = skipSet && skipSet.size ? eldCounted.filter(d => !skipSet.has(d)) : eldCounted;
					const srcKey = covered ? "eld" : "est";
					const lid = loadIdCol ? (r[loadIdCol] || "").trim() : "";
					const displayDriver = jtDriverCol ? (r[jtDriverCol] || "").trim() : "";
					if (displayDriver && !driverDisplayName[driver]) driverDisplayName[driver] = displayDriver;
					// All-time set (for totals)
					if (!driverDaySets[driver]) driverDaySets[driver] = new Set();
					counted.forEach(d => driverDaySets[driver].add(d));
					// Per-assigned-month set (for monthly P&L). Falls back to the
					// physical day's month if the load has no assigned date (rare).
					if (!driverMonthlyDays[driver]) driverMonthlyDays[driver] = {};
					if (!driverMonthlyDayLoads[driver]) driverMonthlyDayLoads[driver] = {};
					if (!driverDaySource[driver]) driverDaySource[driver] = {};
					counted.forEach(d => {
						const bucket = assignedMonthKey || d.slice(0, 7);
						if (!driverMonthlyDays[driver][bucket]) driverMonthlyDays[driver][bucket] = new Set();
						driverMonthlyDays[driver][bucket].add(d);
						if (!driverDaySource[driver][bucket]) driverDaySource[driver][bucket] = { eld: false, est: false };
						driverDaySource[driver][bucket][srcKey] = true;
						if (!driverMonthlyDayLoads[driver][bucket]) driverMonthlyDayLoads[driver][bucket] = {};
						if (!driverMonthlyDayLoads[driver][bucket][d]) driverMonthlyDayLoads[driver][bucket][d] = new Set();
						if (lid) driverMonthlyDayLoads[driver][bucket][d].add(lid);
					});
				}
			}

			// Operating period (track earliest/latest dates)
			if (jtDateCol && r[jtDateCol]) {
				const d = moneySheetDate(r[jtDateCol]);
				if (d && !isNaN(d)) {
					if (!earliestDate || d < earliestDate) earliestDate = d;
					if (!latestDate || d > latestDate) latestDate = d;
				}
			}
		});

		// Apply admin-added days — Super Admin credits a day the ELD missed
		// (truck offline, vehicle not linked, gap in feed). Bucketed by the
		// date's own calendar month since added days aren't tied to any load's
		// assigned-month key. Sourced as 'est' since by definition this isn't
		// ELD-verified. Only applies to drivers visible in this scope (the
		// outer filteredJobData is investor-scoped via investorDriverSet upstream).
		for (const [drv, ovr] of Object.entries(driverDayOverrides)) {
			if (!ovr.add || !ovr.add.size) continue;
			if (investorDriverSet && !investorDriverSet.has(drv)) continue;
			if (!driverDaySets[drv]) driverDaySets[drv] = new Set();
			if (!driverMonthlyDays[drv]) driverMonthlyDays[drv] = {};
			if (!driverDaySource[drv]) driverDaySource[drv] = {};
			for (const d of ovr.add) {
				driverDaySets[drv].add(d);
				const bucket = d.slice(0, 7);
				if (!driverMonthlyDays[drv][bucket]) driverMonthlyDays[drv][bucket] = new Set();
				driverMonthlyDays[drv][bucket].add(d);
				if (!driverDaySource[drv][bucket]) driverDaySource[drv][bucket] = { eld: false, est: false };
				driverDaySource[drv][bucket].est = true;
			}
		}

		// Avg daily revenue = 30-day average (S2).
		// Gross = raw top-line from completed loads in the trailing 30 days.
		// Investor daily = the 50% split after driver pay + fixed + trip expenses
		// is applied — computed below after netProfit is known for the window.
		const avgDailyRevenue = last30DaysRevenue / 30;

		// Months of operation and avg monthly owner earnings (S3)
		let monthsOfOperation = 1;
		if (earliestDate && latestDate) {
			monthsOfOperation = Math.max(1,
				(latestDate.getFullYear() - earliestDate.getFullYear()) * 12
				+ (latestDate.getMonth() - earliestDate.getMonth()) + 1
			);
		}
		const avgMonthlyOwnerEarnings = Math.round(totalRevenue / monthsOfOperation);

		// ---- Expense Data — load-specific + truck-level ----
		let totalExpenses = 0;
		// Trip expenses on the SAME owner/driver basis as the monthly tripExpenses
		// rollup below — NOT gated to completed-load IDs. A receipt with a blank or
		// non-completed load_id is still a real cost; the old `load_id IN (...)`
		// filter silently dropped those (Johnny had 11 ≈ $2,028), making
		// netRevenueToDate under-count expenses vs the payout ledger. Now they match.
		if (investorOwnerId) {
			// The all-time sum takes the same month-bounded scope as the monthly
			// rollup — the window filter applies per row via EXPENSE_PERIOD_EXPR, so
			// "all time" means "every month that was mine", not "every month".
			// Leaving this one unbounded would make the headline totals disagree with
			// the sum of the months that explain them.
			const scope = investorExpenseScopeSql(investorOwnerId, investorExpenseWindows, EXPENSE_PERIOD_EXPR);
			const expSum = db.prepare(`SELECT COALESCE(SUM(amount), 0) AS total FROM expenses WHERE ${scope.sql} AND ${EXPENSE_PNL_FILTER}`).get(...scope.params);
			totalExpenses += expSum.total;
		} else if (isSuperAdmin) {
			const expSum = db.prepare(`SELECT COALESCE(SUM(amount), 0) AS total FROM expenses WHERE ${EXPENSE_PNL_FILTER}`).get();
			totalExpenses += expSum.total;
		}
		// Truck-level costs (maintenance fund DISBURSEMENTS, compliance fees)
		// NOTE: maintenance_fund table = actual service payments. SEPARATE from trucks.maintenance_fund_monthly (budget).
		// Inactive trucks are excluded — once a truck is flipped off Active,
		// its associated costs drop out of the investor bottom-line. Orphan
		// rows whose `truck` field doesn't match any truck still flow through
		// the Super-Admin branch via the NOT IN subquery.
		if (investorOwnerId) {
			const maintSum = db.prepare(`SELECT COALESCE(SUM(mf.amount), 0) AS total FROM maintenance_fund mf INNER JOIN trucks t ON LOWER(mf.truck) = LOWER(t.unit_number) WHERE t.owner_id = ? AND t.status = 'Active' AND mf.type = 'service'`).get(user.id);
			totalExpenses += maintSum.total;
			const compSum = db.prepare(`SELECT COALESCE(SUM(cf.amount), 0) AS total FROM compliance_fees cf INNER JOIN trucks t ON LOWER(cf.truck) = LOWER(t.unit_number) WHERE t.owner_id = ? AND t.status = 'Active' AND cf.status = 'Paid'`).get(user.id);
			totalExpenses += compSum.total;
		} else if (isSuperAdmin) {
			totalExpenses += db.prepare(`SELECT COALESCE(SUM(amount), 0) AS total FROM maintenance_fund WHERE type = 'service' AND LOWER(truck) NOT IN (SELECT LOWER(unit_number) FROM trucks WHERE status != 'Active')`).get().total;
			totalExpenses += db.prepare(`SELECT COALESCE(SUM(amount), 0) AS total FROM compliance_fees WHERE status = 'Paid' AND LOWER(truck) NOT IN (SELECT LOWER(unit_number) FROM trucks WHERE status != 'Active')`).get().total;
		}

		// ---- Driver Pay (branches on each driver's pay_type) ----
		// Fixed drivers: activeDays × per-truck dailyRate (legacy logic).
		// Percentage drivers (e.g. Rodney): max(0, weekly load revenue − Fuel & Maintenance) × pct.
		// Same formula their invoice uses, so the P&L matches reality.
		const payStructures = getDriverPayStructures();
		const expensesByDriverMonth = getDeductibleExpensesByDriverMonth();
		const driverPayDetails = {};
		let totalDriverPay = 0;
		{
			const trucksByDriver = {};
			const truckQuery = investorDriverSet
				? "SELECT assigned_driver, driver_pay_daily FROM trucks WHERE owner_id = ?"
				: "SELECT assigned_driver, driver_pay_daily FROM trucks";
			db.prepare(truckQuery).all(...(investorDriverSet ? [user.id] : [])).forEach(t => {
				const d = normalizeDriverName(t.assigned_driver);
				if (d) trucksByDriver[d] = t.driver_pay_daily || 250;
			});
			for (const [driver, daySet] of Object.entries(driverDaySets)) {
				const struct = payStructures[driver] || { payType: "fixed", payPercentage: 0 };
				const activeDays = daySet.size;
				let pay, dailyRate;
				if (struct.payType === "percentage") {
					const totalRev = Object.values(driverMonthlyRevenue[driver] || {}).reduce((s, v) => s + v, 0);
					const totalExp = (expensesByDriverMonth[driver] || {})._total || 0;
					const net = Math.max(0, totalRev - totalExp);
					pay = Math.round((net * struct.payPercentage / 100) * 100) / 100;
					dailyRate = 0;
				} else {
					dailyRate = resolveDailyRate(struct.payDaily, trucksByDriver[driver]);
					pay = activeDays * dailyRate;
				}
				totalDriverPay += pay;
				driverPayDetails[driver] = {
					activeDays, dailyRate, totalPay: pay,
					dates: [...daySet].sort(),
					payType: struct.payType,
					payPercentage: struct.payType === "percentage" ? struct.payPercentage : 0,
					source: driverSrcAllTime(driver),
				};
			}
			totalExpenses += totalDriverPay;
		}

		// ---- Add truck fixed costs (excluding driver pay — now computed above) ----
		// `maintenance_fund_monthly` is intentionally OMITTED. It's a budget
		// reserve allocation, not an actual cost — actuals already flow
		// through `maintenanceExpenses` from maintenance_fund service rows
		// elsewhere in this handler. Including the reserve here would
		// double-count maintenance. Same fix as /api/financials.
		{
			// Inactive trucks don't contribute projected fixed costs — once a
			// truck is flipped off Active in the Trucks UI, its IRP/HVUT/ELD/
			// insurance stops accruing on the investor bottom-line.
			const truckQuery = investorDriverSet
				? "SELECT insurance_monthly, eld_monthly, truck_payment_monthly, hvut_annual, irp_annual, created_at, in_service_date, retired_at FROM trucks WHERE owner_id = ? AND status = 'Active'"
				: "SELECT insurance_monthly, eld_monthly, truck_payment_monthly, hvut_annual, irp_annual, created_at, in_service_date, retired_at FROM trucks WHERE status = 'Active'";
			const truckArgs = investorDriverSet ? [user.id] : [];
			const fleetTrucks = db.prepare(truckQuery).all(...truckArgs);
			for (const t of fleetTrucks) {
				const fixedPerMonth = (t.insurance_monthly || 0) + (t.eld_monthly || 0) + (t.truck_payment_monthly || 0)
					+ ((t.hvut_annual || 0) / 12) + ((t.irp_annual || 0) / 12);
				// Accrue from the in-service month, not the row's created_at — same
				// start month the monthlyEarnings gate uses, so this all-time total
				// stays the sum of the months shown below it.
				// Bounded at BOTH ends by truckBilledMonthCount: from the in-service
				// month, to the retirement month when the truck has one. null means
				// the start month is unparseable — fall through to full fleet months,
				// exactly as the old !isNaN(truckDate) guard did.
				let truckMonths = monthsOfOperation;
				const billed = truckBilledMonthCount(t, now);
				if (billed !== null) truckMonths = Math.min(billed, monthsOfOperation);
				totalExpenses += fixedPerMonth * truckMonths;
			}
		}

		// Monthly revenue sorted
		const monthlyData = Object.entries(monthlyRevenue)
			.sort(([a], [b]) => a.localeCompare(b))
			.map(([month, amount]) => ({ month, amount: Math.round(amount) }));

		// ---- Monthly Earnings Breakdown (exact calendar month) ----
		const monthlyEarnings = [];
		{
			// Houston month, not server-local: on the UTC VPS a plain getMonth() flips at
			// 19:00 (CDT) / 18:00 (CST) Houston on the last day of the month, so for the
			// final 5-6 hours of every month the portal showed the NEXT month accruing at
			// $0 and treated the just-ended one as complete. houstonDay() is the same
			// Central basis the stamps and the close lifecycle now use.
			const currentMonthKey = houstonDay(now).slice(0, 7);
			// Investor take-home = configurable split of net profit (default 50%).
			// Read from investor_config.investor_split_pct (per-investor override
			// already merged into `config` above). This is the SAME split the
			// settlement layer (/api/investor/payouts) applies, so a payout's
			// amount equals the investorEarnings shown here.
			const monthlySplit = resolveInvestorSplitPct(config) / 100;

			// 1. Monthly driver pay — bucketed by each load's ASSIGNED month,
			// not by the physical day the driver was active. This keeps revenue
			// and driver pay aligned so a load assigned in April always shows
			// both its revenue AND its driver pay in April.
			// Branches on pay_type: percentage drivers use (monthRevenue − monthDeductible) × pct.
			const monthlyDriverPay = {};
			const monthlyDriverDetails = {}; // { "YYYY-MM": { driver: { activeDays, dailyRate, totalPay, payType, payPercentage, monthRevenue, monthDeductible, netForPercentage, source, dayBreakdown, excludedDays, addedDays, displayDriverName } } }
			// Full override rows (with id + reason + action) for the modal's
			// restore action. Split into excluded vs added below.
			const overrideRows = (() => {
				try {
					return db.prepare(
						"SELECT id, driver_name, excluded_date, reason, excluded_by, strftime('%Y-%m-%dT%H:%M:%SZ', excluded_at) AS excluded_at, COALESCE(action, 'remove') AS action FROM excluded_driver_days"
					).all();
				} catch { return []; }
			})();
			for (const [driver, monthsMap] of Object.entries(driverMonthlyDays)) {
				const struct = payStructures[driver] || { payType: "fixed", payPercentage: 0 };
				const fixedRate = (driverPayDetails[driver] && driverPayDetails[driver].dailyRate) || 250;
				for (const [mk, daySet] of Object.entries(monthsMap)) {
					const activeDays = daySet.size;
					const monthRev = (driverMonthlyRevenue[driver] || {})[mk] || 0;
					const monthExp = (expensesByDriverMonth[driver] || {})[mk] || 0;
					const net = Math.max(0, monthRev - monthExp);
					let pay, dailyRate;
					if (struct.payType === "percentage") {
						pay = Math.round((net * struct.payPercentage / 100) * 100) / 100;
						dailyRate = 0;
					} else {
						dailyRate = fixedRate;
						pay = activeDays * dailyRate;
					}
					monthlyDriverPay[mk] = (monthlyDriverPay[mk] || 0) + pay;
					// Day-by-day breakdown: { date, loadIds[] } sorted by date.
					// Only days that survived the ELD + admin-exclusion filters
					// show up — same as what activeDays counted.
					const perDayLoads = (driverMonthlyDayLoads[driver] || {})[mk] || {};
					const dayBreakdown = Object.entries(perDayLoads)
						.sort(([a], [b]) => a.localeCompare(b))
						.map(([date, lidSet]) => ({ date, loadIds: [...lidSet].sort() }));
					// Override rows for this driver in this assigned-month bucket.
					// `excludedDays` (action='remove') = days the admin dropped from
					// the count. `addedDays` (action='add') = days credited because
					// the ELD missed them. Both surface in the modal so the audit
					// trail is visible.
					const driverMonthOverrides = overrideRows
						.filter((er) => er.driver_name === driver && (er.excluded_date || "").slice(0, 7) === mk);
					const excludedDays = driverMonthOverrides
						.filter((er) => er.action !== "add")
						.map((er) => ({
							id: er.id,
							date: er.excluded_date,
							reason: er.reason || "",
							excludedBy: er.excluded_by || "",
							excludedAt: er.excluded_at || "",
						}))
						.sort((a, b) => a.date.localeCompare(b.date));
					const addedDays = driverMonthOverrides
						.filter((er) => er.action === "add")
						.map((er) => ({
							id: er.id,
							date: er.excluded_date,
							reason: er.reason || "",
							excludedBy: er.excluded_by || "",
							excludedAt: er.excluded_at || "",
						}))
						.sort((a, b) => a.date.localeCompare(b.date));
					if (!monthlyDriverDetails[mk]) monthlyDriverDetails[mk] = {};
					monthlyDriverDetails[mk][driver] = {
						activeDays, dailyRate, totalPay: pay,
						payType: struct.payType,
						payPercentage: struct.payType === "percentage" ? struct.payPercentage : 0,
						monthRevenue: Math.round(monthRev),
						monthDeductible: Math.round(monthExp),
						netForPercentage: Math.round(net),
						source: daySrcLabel(driverDaySource[driver] && driverDaySource[driver][mk]),
						dayBreakdown,
						excludedDays,
						addedDays,
						displayDriverName: driverDisplayName[driver] || driver,
					};
				}
			}

			// 2. Monthly trip expenses — from DB grouped by month
			const monthlyTripExp = {};
			const tripExpByCategory = {};  // { "YYYY-MM": { fuel: X, maintenance: X, ... } }
			if (investorOwnerId) {
				// ONE scope object for both queries — the category breakdown is what
				// the Trip Expenses drill-down renders, so it must select exactly the
				// rows the headline summed or the modal explains a different number
				// than the row it opened from.
				const scope = investorExpenseScopeSql(investorOwnerId, investorExpenseWindows, EXPENSE_PERIOD_EXPR);
				const rows = db.prepare(
					`SELECT ${EXPENSE_PERIOD_EXPR} AS m, COALESCE(SUM(amount), 0) AS t FROM expenses WHERE ${scope.sql} AND ${EXPENSE_PNL_FILTER} GROUP BY m`
				).all(...scope.params);
				rows.forEach(r => { if (r.m) monthlyTripExp[r.m] = r.t; });
				const catRows = db.prepare(
					`SELECT ${EXPENSE_PERIOD_EXPR} AS m, LOWER(type) AS cat, COALESCE(SUM(amount), 0) AS t FROM expenses WHERE ${scope.sql} AND ${EXPENSE_PNL_FILTER} GROUP BY m, LOWER(type)`
				).all(...scope.params);
				catRows.forEach(r => { if (r.m) { if (!tripExpByCategory[r.m]) tripExpByCategory[r.m] = {}; tripExpByCategory[r.m][r.cat] = r.t; } });
			} else if (isSuperAdmin) {
				const rows = db.prepare(`SELECT ${EXPENSE_PERIOD_EXPR} AS m, COALESCE(SUM(amount), 0) AS t FROM expenses WHERE ${EXPENSE_PNL_FILTER} GROUP BY m`).all();
				rows.forEach(r => { if (r.m) monthlyTripExp[r.m] = r.t; });
				const catRows = db.prepare(`SELECT ${EXPENSE_PERIOD_EXPR} AS m, LOWER(type) AS cat, COALESCE(SUM(amount), 0) AS t FROM expenses WHERE ${EXPENSE_PNL_FILTER} GROUP BY m, LOWER(type)`).all();
				catRows.forEach(r => { if (r.m) { if (!tripExpByCategory[r.m]) tripExpByCategory[r.m] = {}; tripExpByCategory[r.m][r.cat] = r.t; } });
			}

			// 2b. Monthly maintenance-fund service + paid compliance fees, grouped
			// by month — same owner/super-admin scoping as the all-time truck-level
			// block above. Puts per-month netProfit on the SAME expense basis as the
			// aggregate totalExpenses (and the payout ledger). Empty in prod = $0.
			const monthlyMaintFund = {};
			const monthlyCompliance = {};
			if (investorOwnerId) {
				db.prepare(
					`SELECT strftime('%Y-%m', COALESCE(NULLIF(mf.date, ''), strftime('%Y-%m-%d', mf.created_at))) AS m, COALESCE(SUM(mf.amount), 0) AS t FROM maintenance_fund mf INNER JOIN trucks t ON LOWER(mf.truck) = LOWER(t.unit_number) WHERE t.owner_id = ? AND t.status = 'Active' AND mf.type = 'service' GROUP BY m`
				).all(user.id).forEach(r => { if (r.m) monthlyMaintFund[r.m] = r.t; });
				db.prepare(
					`SELECT strftime('%Y-%m', COALESCE(NULLIF(cf.paid_date, ''), NULLIF(cf.due_date, ''), strftime('%Y-%m-%d', cf.created_at))) AS m, COALESCE(SUM(cf.amount), 0) AS t FROM compliance_fees cf INNER JOIN trucks t ON LOWER(cf.truck) = LOWER(t.unit_number) WHERE t.owner_id = ? AND t.status = 'Active' AND cf.status = 'Paid' GROUP BY m`
				).all(user.id).forEach(r => { if (r.m) monthlyCompliance[r.m] = r.t; });
			} else if (isSuperAdmin) {
				db.prepare(
					`SELECT strftime('%Y-%m', COALESCE(NULLIF(date, ''), strftime('%Y-%m-%d', created_at))) AS m, COALESCE(SUM(amount), 0) AS t FROM maintenance_fund WHERE type = 'service' AND LOWER(truck) NOT IN (SELECT LOWER(unit_number) FROM trucks WHERE status != 'Active') GROUP BY m`
				).all().forEach(r => { if (r.m) monthlyMaintFund[r.m] = r.t; });
				db.prepare(
					`SELECT strftime('%Y-%m', COALESCE(NULLIF(paid_date, ''), NULLIF(due_date, ''), strftime('%Y-%m-%d', created_at))) AS m, COALESCE(SUM(amount), 0) AS t FROM compliance_fees WHERE status = 'Paid' AND LOWER(truck) NOT IN (SELECT LOWER(unit_number) FROM trucks WHERE status != 'Active') GROUP BY m`
				).all().forEach(r => { if (r.m) monthlyCompliance[r.m] = r.t; });
			}

			// 3. Monthly fixed costs — constant per month per truck (only months truck existed).
			// maintenance_fund_monthly omitted on purpose — see fleet-totals
			// fix above. Reserve budget ≠ actual cost; actual maintenance
			// flows through monthlyTripExp / maintByTruck.
			const truckFixedQuery = investorDriverSet
				? "SELECT insurance_monthly, eld_monthly, truck_payment_monthly, hvut_annual, irp_annual, created_at, in_service_date, retired_at FROM trucks WHERE owner_id = ? AND status = 'Active'"
				: "SELECT insurance_monthly, eld_monthly, truck_payment_monthly, hvut_annual, irp_annual, created_at, in_service_date, retired_at FROM trucks WHERE status = 'Active'";
			const truckFixedArgs = investorDriverSet ? [user.id] : [];
			const fixedTrucks = db.prepare(truckFixedQuery).all(...truckFixedArgs);
			// Same shared per-truck math AND the same start-month gate as
			// computeInvestorMonthlyEarnings, so the dashboard and the payouts card
			// never disagree on fixed costs.
			function getMonthlyFixedCosts(monthKey) {
				let total = 0;
				for (const t of fixedTrucks) {
					// In service by this month and not yet retired — shared predicate.
					if (!truckChargedInMonth(t, monthKey)) continue;
					total += truckMonthlyFixed(t).total;
				}
				return Math.round(total * 100) / 100;
			}
			// The same loop, split into the parts the drill-down prints.
			//
			// ⚠️ THE MODAL USED TO RENDER production.fixedCostBreakdown AGAINST THIS
			// MONTH'S TOTAL, AND THE TWO ARE NOT THE SAME QUESTION. That object is a
			// present-tense FLEET RATE built from every owned truck with no
			// in_service_date gate, so July 2026 printed
			// "$3,310 + $100 + $2,410 + $233 + $97 = $3,043/mo" — a left side of
			// $6,150 against a right side of $3,043, on an investor's money screen.
			// The $3,107 excess was one truck that did not enter service until August.
			// Deriving the parts from the SAME gated loop as the total makes them sum
			// by construction rather than by coincidence, at every month in history.
			function getMonthlyFixedCostParts(monthKey) {
				const parts = { insurance: 0, eld: 0, truckPayment: 0, irp: 0, hvut: 0, truckCount: 0 };
				for (const t of fixedTrucks) {
					if (!truckChargedInMonth(t, monthKey)) continue;
					const f = truckMonthlyFixed(t);
					parts.insurance += f.insurance;
					parts.eld += f.eld;
					parts.truckPayment += f.truckPayment;
					parts.irp += f.irp;
					parts.hvut += f.hvut;
					parts.truckCount++;
				}
				// Cents, matching getMonthlyFixedCosts — NOT whole dollars. Rounding
				// the parts to dollars is exactly how an itemization stops adding up
				// to its own headline (the $3,043 vs $3,043.33 case truckMonthlyFixed
				// was introduced to close).
				for (const k of ["insurance", "eld", "truckPayment", "irp", "hvut"]) {
					parts[k] = Math.round(parts[k] * 100) / 100;
				}
				return parts;
			}

			// 4. Build the array for every month from earliest to current
			const startMonth = earliestDate
				? `${earliestDate.getFullYear()}-${String(earliestDate.getMonth() + 1).padStart(2, "0")}`
				: currentMonthKey;
			let cursor = new Date(parseInt(startMonth.slice(0, 4)), parseInt(startMonth.slice(5, 7)) - 1, 1);
			const endDate = new Date(now.getFullYear(), now.getMonth(), 1);
			let deferredAccrual = 0;
			while (cursor <= endDate) {
				const mk = `${cursor.getFullYear()}-${String(cursor.getMonth() + 1).padStart(2, "0")}`;
				const revenue = monthlyRevenue[mk] || 0;
				const driverPay = monthlyDriverPay[mk] || 0;
				const rawFixedCosts = getMonthlyFixedCosts(mk);
				const tripExpenses = monthlyTripExp[mk] || 0;
				const maintFundCost = monthlyMaintFund[mk] || 0;
				const complianceCost = monthlyCompliance[mk] || 0;
				// Investor-facing grace: if the truck did nothing this month
				// (no revenue, no driver-day records, no trip expenses), defer
				// the fixed costs so onboarding months don't appear as losses.
				// /admin/financials still accrues these normally.
				const driverCount = Object.keys(monthlyDriverDetails[mk] || {}).length;
				const isZeroActivity = revenue === 0 && driverPay === 0 && tripExpenses === 0 && maintFundCost === 0 && complianceCost === 0 && driverCount === 0;
				const fixedCosts = isZeroActivity ? 0 : rawFixedCosts;
				if (isZeroActivity && rawFixedCosts > 0) deferredAccrual += rawFixedCosts;
				const netProfit = revenue - driverPay - fixedCosts - tripExpenses - maintFundCost - complianceCost;
				monthlyEarnings.push({
					month: mk,
					revenue: Math.round(revenue),
					driverPay: Math.round(driverPay),
					driverDetails: monthlyDriverDetails[mk] || {},
					fixedCosts,
					// The MONEY is zeroed alongside `fixedCosts` in a deferred month —
					// the drill-down must never itemize costs the row above it says
					// were not charged — but `truckCount` stays truthful, because it
					// is a count of trucks and not a cost, and the deferred copy reads
					// "your N trucks were inactive" off it.
					fixedCostComposition: isZeroActivity
						? { ...getMonthlyFixedCostParts(mk), insurance: 0, eld: 0, truckPayment: 0, irp: 0, hvut: 0 }
						: getMonthlyFixedCostParts(mk),
					fixedCostsDeferred: isZeroActivity && rawFixedCosts > 0,
					tripExpenses: Math.round(tripExpenses),
					tripExpCategories: tripExpByCategory[mk] || {},
					maintFundCost: Math.round(maintFundCost),
					complianceCost: Math.round(complianceCost),
					netProfit: Math.round(netProfit),
					investorEarnings: Math.round(netProfit * monthlySplit),
					companyEarnings: Math.round(netProfit - Math.round(netProfit * monthlySplit)),
					isCurrentMonth: mk === currentMonthKey,
				});
				cursor.setMonth(cursor.getMonth() + 1);
			}

			// ---- Loss carry-forward, published per month ----------------------
			// The SAME walk the settlement ledger runs (computeLossCarryForward —
			// one definition, two readers), not a second copy of the rule.
			//
			// ⚠️ Without this the two screens disagreed about one month. This array
			// published `investorEarnings` — the FULL share of net profit — while
			// GET /api/investor/payouts and the statement PDF published the
			// post-carry figure, so a profitable month that had absorbed an earlier
			// loss read one number in the Earnings waterfall and a smaller one on
			// the payout row beside it, with nothing on screen to explain the gap.
			// Live case: owner 5's 2026-08 runs at −$995, which September will
			// legitimately absorb.
			//
			// `payable` is what the month settles at (raw − carriedIn, and 0 for a
			// losing month) — the same quantity `amount` freezes to at close and
			// `payableIfClosedNow` projects for the open month.
			//
			// Purely ADDITIVE: every existing key is untouched, so no current
			// consumer changes shape.
			const carryByPeriod = computeLossCarryForward(monthlyEarnings);
			for (const m of monthlyEarnings) {
				const c = carryByPeriod[m.month];
				m.lossCarriedIn = c.carriedIn;   // earlier losses absorbed by this month
				m.lossDeferred = c.deferred;     // this month's own loss pushed forward
				m.payable = c.payable;           // what this month actually settles at
			}

			// Reconcile aggregate totalExpenses with the per-month deferral
			// applied above. The truck-fixed-costs accrual earlier in this
			// handler charges every month from truck.created_at; subtract the
			// months we deferred so netRevenueToDate matches the monthly view.
			totalExpenses = Math.max(0, totalExpenses - deferredAccrual);
		}

		// ---- Asset Security (S4, S5) — now per-truck ----
		// Single truck query with all columns needed by asset section + per-truck loop
		const allOwnedTrucks = investorDriverSet
			? db.prepare("SELECT * FROM trucks WHERE owner_id = ?").all(user.id)
			: db.prepare("SELECT * FROM trucks").all();
		const totalTrucks = allOwnedTrucks.length;
		const totalPurchasePrice = allOwnedTrucks.reduce((sum, t) => sum + (t.purchase_price || 0), 0);
		const depreciationYears = Math.max(1, parseFloat(config.depreciation_years) || 5);
		const depreciationRate = Math.min(1, monthsOfOperation / (depreciationYears * 12));
		const totalCurrentValue = Math.round(totalPurchasePrice * (1 - depreciationRate));
		// Use first truck's values as representative for single-truck display; fleet view uses totals
		const purchasePrice = allOwnedTrucks.length === 1 ? (allOwnedTrucks[0].purchase_price || 0) : totalPurchasePrice;
		const currentValue = allOwnedTrucks.length === 1 ? Math.round((allOwnedTrucks[0].purchase_price || 0) * (1 - depreciationRate)) : totalCurrentValue;
		const titleStatus = allOwnedTrucks.length === 1 ? (allOwnedTrucks[0].title_status || "Clean") : "Mixed";

		// Fleet totals (S9)
		const totalStartupExpenses = 5000 * totalTrucks;
		const netRevenueToDate = Math.round(totalRevenue - totalExpenses);

		// Fixed cost breakdown (per-category sums across fleet, monthly).
		//
		// This is a PRESENT-TENSE RATE — "what the fleet costs per month right now",
		// rendered as the fixed-cost tiles in EarningsSection.vue. A retired truck is
		// no longer costing anything, so it must drop out of the rate the month after
		// it retires. Bounded on the RETIREMENT half only, deliberately:
		//   • the in-service half is left alone so a forward-dated truck keeps
		//     appearing exactly as it does today (byte-identical for every existing
		//     row, which all have retired_at = "");
		//   • `until >= thisMonth` keeps a truck retired THIS month in the tile,
		//     matching truckChargedInMonth's inclusive upper bound — it really is
		//     still being paid for this month.
		// ⚠️ Pre-existing and deliberately NOT changed here: this set has no status
		// filter, so INACTIVE trucks are already counted in these tiles. That is a
		// separate inconsistency with the status-filtered monthly math; fixing it
		// would move a displayed number for reasons unrelated to retirement.
		const rateMonthKey = houstonDay(now).slice(0, 7);
		const fixedRateTrucks = allOwnedTrucks.filter((t) => {
			const until = truckChargeUntilMonth(t);
			return !until || until >= rateMonthKey;
		});
		const fixedCostBreakdown = {
			insurance: Math.round(fixedRateTrucks.reduce((s, t) => s + (t.insurance_monthly || 0), 0)),
			eld: Math.round(fixedRateTrucks.reduce((s, t) => s + (t.eld_monthly || 0), 0)),
			truckPayment: Math.round(fixedRateTrucks.reduce((s, t) => s + (t.truck_payment_monthly || 0), 0)),
			irp: Math.round(fixedRateTrucks.reduce((s, t) => s + ((t.irp_annual || 0) / 12), 0)),
			hvut: Math.round(fixedRateTrucks.reduce((s, t) => s + ((t.hvut_annual || 0) / 12), 0)),
			maintReserve: Math.round(fixedRateTrucks.reduce((s, t) => s + (t.maintenance_fund_monthly || 0), 0)),
			truckCount: totalTrucks,
		};

		// ---- Tax Shield (S6, S7, S10) ----
		const section179 = totalPurchasePrice; // S6: 100% deductibility per truck
		const atRiskCapital = Math.max(0, (totalPurchasePrice + totalStartupExpenses) - netRevenueToDate); // S7

		// ---- Per-Truck Revenue Data (S8) — batched queries, no inner loops ----
		const perTruckData = {};
		if (investorDriverSet) {
			// Batch queries BEFORE the loop (4 queries total instead of 5N)
			const expByDriver = Object.fromEntries(
				db.prepare(`SELECT LOWER(driver) AS d, COALESCE(SUM(amount),0) AS t FROM expenses WHERE owner_id = ? AND ${EXPENSE_PNL_FILTER} GROUP BY LOWER(driver)`).all(user.id).map(r => [r.d, r.t])
			);
			const maintByTruck = Object.fromEntries(
				db.prepare(`SELECT LOWER(mf.truck) AS u, COALESCE(SUM(mf.amount),0) AS t FROM maintenance_fund mf INNER JOIN trucks t ON LOWER(mf.truck)=LOWER(t.unit_number) WHERE t.owner_id = ? AND mf.type='service' GROUP BY LOWER(mf.truck)`).all(user.id).map(r => [r.u, r.t])
			);
			const compByTruck = Object.fromEntries(
				db.prepare(`SELECT LOWER(cf.truck) AS u, COALESCE(SUM(cf.amount),0) AS t FROM compliance_fees cf INNER JOIN trucks t ON LOWER(cf.truck)=LOWER(t.unit_number) WHERE t.owner_id = ? AND cf.status='Paid' GROUP BY LOWER(cf.truck)`).all(user.id).map(r => [r.u, r.t])
			);
			// Use allOwnedTrucks (already fetched for asset section) — no extra query
			allOwnedTrucks.forEach((truck) => {
				const driverName = normalizeDriverName(truck.assigned_driver);
				const unitLower = truck.unit_number.toLowerCase();
				// Revenue from grossByDriver map (computed in single pass above)
				const unitTotalGross = grossByDriver[driverName] || 0;
				// Expenses from batch maps (zero queries in this loop)
				const varExp = expByDriver[driverName] || 0;
				const maintExp = maintByTruck[unitLower] || 0;
				const compExp = compByTruck[unitLower] || 0;
				// Fixed costs per truck per month — exclude
				// maintenance_fund_monthly (reserve budget, not actual
				// cost; actuals are in maintExp). Same fix applied to the
				// fleet totalExpenses loop and /api/financials.
				const fixedPerMonth = (truck.insurance_monthly || 0) + (truck.eld_monthly || 0) + (truck.truck_payment_monthly || 0)
					+ ((truck.hvut_annual || 0) / 12) + ((truck.irp_annual || 0) / 12);
				// Accrue from the in-service month — same gate as the fleet
				// totalExpenses loop above, so this per-truck table stays a
				// breakdown OF that total rather than a second opinion.
				// Floor 0: a forward-dated truck accrues nothing yet (see the
				// fleet loop above for why the old floor of 1 was safe until
				// in_service_date made future start months reachable).
				let truckMonths = monthsOfOperation;
				const billedMonths = truckBilledMonthCount(truck, now);
				if (billedMonths !== null) truckMonths = Math.min(billedMonths, monthsOfOperation);
				const driverPay = driverPayDetails[driverName]?.totalPay || 0;
				const unitTotalExpenses = varExp + maintExp + compExp + (fixedPerMonth * truckMonths) + driverPay;
				// ⚠️ truckMonths is a DIVISOR here and its floor is 0, so this is a
				// live division by zero — Math.round(x/0) is Infinity, which
				// JSON.stringify emits as null and the UI renders as a blank cell.
				// Reachable before retirement (a truck forward-dated past the current
				// month counts 0) but retirement makes it ordinary: a truck retired
				// before its own in-service month counts 0 as well. Averaging over a
				// span the truck never operated in is meaningless either way, so the
				// honest answer for a zero-month truck is 0, not Infinity.
				const avgMonthlyGross = truckMonths > 0 ? Math.round(unitTotalGross / truckMonths) : 0;
				const avgMonthlyExpenses = truckMonths > 0 ? Math.round(unitTotalExpenses / truckMonths) : 0;
				// Miles from the haversine accumulators computed in the single-pass
				// loop above. Prefer truck-column attribution over driver-based
				// (same fallback pattern as loadCount below).
				const truckMilesRaw = milesByTruck[unitLower];
				const totalMiles = Math.round(
					truckMilesRaw !== undefined ? truckMilesRaw : (milesByDriver[driverName] || 0)
				);

				// Prefer direct truck-column attribution (loads tagged with this unit
				// number) over driver-based attribution, which is stale if a driver
				// switched trucks. Fall back to driver-based when the sheet has no
				// truck column for a given row.
				const truckLoadCount = loadsByTruck[unitLower];
				const loadCount = (truckLoadCount !== undefined)
					? truckLoadCount
					: (loadsByDriver[driverName] || 0);
				// Inactive/OOS/Maintenance trucks must not project expected
				// revenue — only Active units run. Zero their monthly gross +
				// estimated annual revenue (an inactive truck "is not supposed
				// to show any data"). The truck still counts as an owned asset
				// (purchase price etc.) in the asset section above.
				const truckActive = String(truck.status || "").toLowerCase() === "active";
				perTruckData[truck.unit_number] = {
					unitMonthlyGross: truckActive ? avgMonthlyGross : 0,
					unitMonthlyExpenses: truckActive ? avgMonthlyExpenses : 0,
					estAnnualRevenue: truckActive ? Math.round((avgMonthlyGross - avgMonthlyExpenses) * 12) : 0,
					totalMiles,
					loadCount,
					status: truck.status || "",
				};
			});
		}

		// ---- Recession-Proof Metrics (kept in API for backward compat) ----
		const brokerCol = findCol(jobTracking.headers, /broker|shipper|customer|client/i);
		const totalJobs = filteredJobData.length;
		const completedJobCount = statusCol
			? filteredJobData.filter((r) => completedStatuses.test((r[statusCol] || "").trim())).length
			: 0;

		// Fleet-level mileage aggregation
		const fleetTotalMiles = Object.values(perTruckData).reduce((s, t) => s + (t.totalMiles || 0), 0);
		const revenuePerMile = fleetTotalMiles > 0 ? Math.round((totalRevenue / fleetTotalMiles) * 100) / 100 : 0;
		const costPerMile = fleetTotalMiles > 0 ? Math.round((totalExpenses / fleetTotalMiles) * 100) / 100 : 0;

		// Resolve the investor's own record so the dashboard can display (and upload) their profile picture.
		// In preview mode we also surface full_name + username so the admin's banner / chat
		// can label the target investor accurately.
		let investorProfile = null;
		if (!isSuperAdmin) {
			investorProfile = db.prepare(
				"SELECT id, profile_picture_url, full_name, carrier_name FROM investors WHERE user_id = ?"
			).get(user.id);
		}

		// ---- Investor-centric aggregates (P0-4/5/6 from 2026-04-12 meeting) ----
		// Every metric on the investor dashboard must be based on what the
		// owner actually takes home, not the gross. The backend returns both:
		// frontend can show "Truck Gross" and "Your Take-Home" side-by-side.
		const investorNetToDate = Math.round(
			(monthlyEarnings || []).reduce((s, m) => s + (m.investorEarnings || 0), 0)
		);
		// NOTE: this endpoint deliberately does NOT publish a "still owed" figure.
		// It used to return investorPaidToDate + investorStillOwed = netToDate −
		// paid, which counted the STILL-OPEN current month as already owed. The
		// payout ledger is stricter on purpose — reconcileInvestorPayouts() only
		// settles COMPLETED past months and reports the open month separately as
		// currentMonth.amountInProgress — so the Load Reports banner claimed
		// "$6,389 still owed" while the Payouts section on the same page read
		// "Total Owed $0 · July in progress". One ledger, one answer: the banner
		// now sources GET /api/investor/payouts like the Payouts section does.
		// Trailing 3-month average investor take-home. Uses the most recent
		// 3 entries from monthlyEarnings (which is ordered oldest → newest).
		// Falls back to all-time avg if fewer than 3 months exist.
		const recentMonths = (monthlyEarnings || []).slice(-3);
		const trailing3MonthInvestor = recentMonths.length
			? recentMonths.reduce((s, m) => s + (m.investorEarnings || 0), 0) / recentMonths.length
			: 0;
		const avgMonthlyInvestorEarnings = Math.round(
			monthsOfOperation > 0 && monthlyEarnings?.length
				? investorNetToDate / monthlyEarnings.length
				: 0
		);
		// Daily investor take-home: derived from monthly take-home across the
		// trailing window, divided by days in that window. This is more
		// accurate than `avgDailyRevenue / 2` because it already accounts for
		// the actual driver pay / fixed cost / trip expense mix per month.
		const trailingDays = recentMonths.length * 30;
		const avgDailyInvestorEarnings = trailingDays > 0
			? Math.round((recentMonths.reduce((s, m) => s + (m.investorEarnings || 0), 0) / trailingDays) * 100) / 100
			: 0;

		// Annotate every perTruckData entry with the investor-centric numbers the
		// frontend needs for ROI and break-even. Each ACTIVE truck now takes the
		// share of the investor's trailing take-home that its OWN revenue earned
		// over the SAME trailing months.
		//
		// This replaces an equal split by active-truck count that never consulted a
		// load: Logisx-#91 (0 loads, 0 miles, in service 2026-08) projected exactly
		// the same annual take-home as LogisX-#33 (41 loads, 22,148 mi), and the
		// client reasonably asked how a truck that has never moved projects what a
		// working truck does.
		{
			// ACTIVE trucks only — inactive/OOS/maintenance units don't run, so they
			// must not dilute the active trucks' share, and they keep showing $0
			// expected take-home / ROI (an inactive truck "is not supposed to show
			// any data"). That $0 contract is unchanged by this rewrite.
			const activeUnits = new Set(
				allOwnedTrucks
					.filter(t => String(t.status || "").toLowerCase() === "active")
					.map(t => t.unit_number)
			);
			// The revenue window MUST be the exact months recentMonths covers, so the
			// numerator (a truck's revenue) and the denominator (trailing3MonthInvestor,
			// averaged over those same months) describe the same period. Derived from
			// recentMonths rather than re-deriving "the last 3 months" from `now`, which
			// would silently disagree for an investor with fewer than 3 months of history.
			const trailingWindow = recentMonths.map(m => m.month);
			const windowStart = trailingWindow.length ? trailingWindow[0] : null;
			const sumWindow = (byMonth) => byMonth
				? trailingWindow.reduce((s, mk) => s + (byMonth[mk] || 0), 0)
				: 0;
			// Attribution mode mirrors /api/financials' perTruck block byte-for-byte in
			// shape (see grossByTruck / fleetHasTruckRevenue there): a truck carrying its
			// own truck-column revenue is "truck"; a truck with none is "no-data" when the
			// fleet uses the truck column at all, else "driver-fallback" (the sheet has no
			// usable truck column, so the assigned driver is the best signal available).
			// Same three names, same precedence — one convention across both endpoints.
			const fleetHasTruckRevenue = Object.keys(revenueByTruckMonth).length > 0;

			// Deliberately NOT weighted by loadCount or totalMiles. Both are ALL-TIME
			// (the single-pass loop applies no date gate to them), so weighting a
			// 3-month earnings figure by them would let a truck parked since last year
			// keep a large slice of today's projection. Revenue inside the window is the
			// only per-truck figure on the same clock as trailing3MonthInvestor.
			const windowRevenue = {};   // unit -> revenue earned inside trailingWindow
			const modeByUnit = {};      // unit -> "truck" | "driver-fallback" | "no-data"
			const insufficient = {};    // unit -> not in service for the whole window
			for (const unit of Object.keys(perTruckData)) {
				const truck = allOwnedTrucks.find(t => t.unit_number === unit);
				const unitLower = unit.toLowerCase();
				const byTruck = revenueByTruckMonth[unitLower];
				if (byTruck !== undefined) {
					modeByUnit[unit] = "truck";
					windowRevenue[unit] = sumWindow(byTruck);
				} else if (fleetHasTruckRevenue) {
					modeByUnit[unit] = "no-data";
					windowRevenue[unit] = 0;
				} else {
					modeByUnit[unit] = "driver-fallback";
					windowRevenue[unit] = sumWindow(driverMonthlyRevenue[normalizeDriverName(truck?.assigned_driver)]);
				}
				// A truck that entered service partway through the window was never given
				// the chance to earn across it, so a share computed from a partial window
				// is not a projection, it's an artifact. truckChargeFromMonth() is the same
				// in-service resolver the fixed-cost accrual uses — reuse it so "when did
				// this truck start" has exactly one answer in this handler. It returns ""
				// for a truck with neither in_service_date nor created_at, and "" is never
				// > windowStart, so an undated truck is treated as long-standing (the safe
				// direction: it keeps projecting rather than blanking out).
				const chargeFrom = truck ? truckChargeFromMonth(truck) : "";
				// Mirror of the same argument at the other end of the interval: a truck
				// RETIRED partway through the window stopped being given the chance to
				// earn across it, so its share is just as much an artifact as a truck
				// that arrived partway through. Compared against the LAST month of the
				// window, not the first — a truck retired before the window even began
				// is caught by this too, and correctly so.
				// "" is never < any month key, so an un-retired truck keeps projecting
				// exactly as it does today (the same safe direction the chargeFrom half
				// relies on).
				const chargeUntil = truck ? truckChargeUntilMonth(truck) : "";
				const windowEnd = trailingWindow.length ? trailingWindow[trailingWindow.length - 1] : null;
				insufficient[unit] = !!(
					(windowStart && chargeFrom && chargeFrom > windowStart)
					|| (windowEnd && chargeUntil && chargeUntil < windowEnd)
				);
			}

			// Allocate the fleet annual ONCE, then split it — never round each truck's
			// own monthly and multiply by 12. FleetBreakdownSection sums this column into
			// a Fleet Total while TrendSection and CashFlowSection independently render
			// trailing3MonthInvestor × 12 ON THE SAME PAGE, so any rounding residue is a
			// visible self-contradiction (the old per-truck rounding drifted $12 on a
			// two-truck fleet). Largest-remainder hands each leftover dollar to the
			// truck with the biggest fractional claim, so the parts sum to the whole
			// EXACTLY rather than approximately.
			//
			// ⚠️ round(x) × 12, NOT round(x × 12) — and the difference is visible money.
			// The response publishes the ROUNDED scalar (`trailing3MonthInvestor:
			// Math.round(trailing3MonthInvestor)` further below), and both sibling
			// components multiply THAT by 12: TrendSection.vue:321 and
			// CashFlowSection.vue:197/280. Targeting round(x × 12) here would make this
			// column sum to a different number than the "Projected Annual Take-Home"
			// card rendered beside it — up to $6 apart, e.g. a Trend card reading
			// $59,988 next to a Fleet Total of $59,992. Match what the page actually
			// displays, not the mathematically tidier value.
			const fleetAnnualInvestor = Math.round(trailing3MonthInvestor) * 12;
			let eligible = Object.keys(perTruckData).filter(u => activeUnits.has(u) && !insufficient[u]);
			// Guard: if every active truck is too new (e.g. the only earning truck was
			// just flipped Inactive), allocating to nobody would leave the Fleet Total at
			// $0 against a non-zero Trend figure. Falling back to all active units keeps
			// the page self-consistent — those rows then carry a real number, so they are
			// NOT flagged insufficientData (that flag means exactly "this row is null").
			// With no active trucks at all nothing can hold the invariant, and that was
			// equally true before this change.
			if (!eligible.length) eligible = Object.keys(perTruckData).filter(u => activeUnits.has(u));
			const basis = {};
			let totalBasis = 0;
			for (const u of eligible) {
				// Negative revenue is not expected (rates parse positive) but a floor of 0
				// keeps a bad sheet cell from handing a truck a negative share.
				basis[u] = Math.max(0, windowRevenue[u] || 0);
				totalBasis += basis[u];
			}
			// No revenue anywhere in the window (a brand-new or fully idle fleet) leaves
			// no basis to rank on, so fall back to the equal split — which is what this
			// block did unconditionally before, and is the only defensible answer when
			// every truck's claim is identical.
			const shareOf = (u) => totalBasis > 0 ? basis[u] / totalBasis : (eligible.length ? 1 / eligible.length : 0);
			const alloc = {};
			{
				let floorSum = 0;
				const parts = eligible.map((u) => {
					const raw = fleetAnnualInvestor * shareOf(u);
					const whole = Math.floor(raw);
					alloc[u] = whole;
					floorSum += whole;
					return { unit: u, frac: raw - whole };
				});
				// Σraw is exactly fleetAnnualInvestor, so Σfloor is short by an integer in
				// [0, eligible.length). Hand those dollars out largest-fraction-first.
				// Math.round() absorbs float error in floorSum; the residue sweep below
				// then makes the sum exact no matter what the arithmetic did.
				let remainder = Math.round(fleetAnnualInvestor - floorSum);
				remainder = Math.max(0, Math.min(parts.length, remainder));
				parts.sort((a, b) => b.frac - a.frac);
				for (let i = 0; i < remainder; i++) alloc[parts[i].unit] += 1;
				if (parts.length) {
					const residue = fleetAnnualInvestor - eligible.reduce((s, u) => s + alloc[u], 0);
					if (residue !== 0) alloc[parts[0].unit] += residue;
				}
			}

			for (const unit of Object.keys(perTruckData)) {
				const price = (allOwnedTrucks.find(t => t.unit_number === unit)?.purchase_price) || 0;
				const unitActive = activeUnits.has(unit);
				const tooNew = unitActive && insufficient[unit] && !(unit in alloc);
				// null ≠ 0 here, and the difference is the whole point: null means "in
				// service too briefly to project" (the UI renders "—"), while 0 means
				// "in service the whole window and genuinely earned nothing". A truck
				// that ran the full window with no revenue must still read 0.
				const annual = tooNew ? null : (unitActive ? (alloc[unit] || 0) : 0);
				const monthly = annual === null ? null : Math.round(annual / 12);
				perTruckData[unit].monthlyInvestorEarnings = monthly;
				perTruckData[unit].estAnnualInvestorRevenue = annual;
				// investorROI follows the annual rather than being pinned to 0 — a 0% ROI
				// is the same false claim as $0 revenue. It stays published (the client
				// recomputes ROI from estAnnualInvestorRevenue and ignores this field, but
				// dropping fields is a separate cleanup, not something to couple to a
				// money-visible change).
				perTruckData[unit].investorROI = annual === null
					? null
					: ((unitActive && price > 0) ? Math.round((annual / price) * 1000) / 10 : 0);
				perTruckData[unit].breakEvenMonths = (monthly !== null && monthly > 0)
					? Math.ceil(price / monthly)
					: null;
				// Why this truck got the share it got — so a surprising row is explainable
				// without re-deriving the math (same spirit as /api/financials' per-truck
				// data-quality flags). insufficientData is true exactly when the three
				// projection fields are null, so the UI can key on either one.
				perTruckData[unit].insufficientData = tooNew;
				perTruckData[unit].attributionMode = modeByUnit[unit] || "no-data";
				perTruckData[unit].windowRevenue = Math.round(windowRevenue[unit] || 0);
				perTruckData[unit].windowRevenueShare = (unit in alloc)
					? Math.round(shareOf(unit) * 1000) / 1000
					: 0;
			}
		}

		// ---- My Loads (pending + active) — scoped to this investor's drivers/trucks ----
		// filteredJobData is already investor-scoped (owner_id + driver-set fallback) and has
		// canceled / soft-deleted rows stripped by excludeDroppedLoads() upstream.
		const myPendingRe = /^(dispatched|assigned|heading to shipper)$/i;
		const myActiveRe = /^(in transit|picked up|at shipper|at receiver|loading|unloading)$/i;
		const investorSplit = resolveInvestorSplitPct(config) / 100;
		const myLoadsOriginCol = pickAddressColumn(jobTracking.headers, /origin|pickup|shipper/i);
		const myLoadsDestCol = pickAddressColumn(jobTracking.headers, /dest|drop|receiver|delivery/i);
		function shapeMyLoad(r) {
			const lid = loadIdCol ? (r[loadIdCol] || "").trim() : "";
			const gross = parseFloat(String(jtRateCol ? r[jtRateCol] : "0").replace(/[$,]/g, "")) || 0;
			return {
				loadId: lid,
				status: statusCol ? (r[statusCol] || "").trim() : "",
				pickup: resolveCityState(r, "pickup", lid, myLoadsOriginCol ? r[myLoadsOriginCol] : ""),
				dropoff: resolveCityState(r, "drop", lid, myLoadsDestCol ? r[myLoadsDestCol] : ""),
				truck: jtTruckCol ? (r[jtTruckCol] || "").trim() : "",
				driver: jtDriverCol ? (r[jtDriverCol] || "").trim() : "",
				pickupDate: pickupDateCol ? (r[pickupDateCol] || "") : "",
				dropDate: dropoffDateCol ? (r[dropoffDateCol] || "") : "",
				yourShare: Math.round(gross * investorSplit),
			};
		}
		const myLoads = {
			pending: filteredJobData
				.filter(r => statusCol && myPendingRe.test((r[statusCol] || "").trim()))
				.map(shapeMyLoad),
			active: filteredJobData
				.filter(r => statusCol && myActiveRe.test((r[statusCol] || "").trim()))
				.map(shapeMyLoad),
		};

		res.json({
			production: {
				totalRevenue: Math.round(totalRevenue),
				avgDailyRevenue: Math.round(avgDailyRevenue),
				avgDailyInvestorEarnings,
				last30DaysRevenue: Math.round(last30DaysRevenue),
				monthlyData,
				avgMonthlyOwnerEarnings,
				avgMonthlyInvestorEarnings,
				trailing3MonthInvestor: Math.round(trailing3MonthInvestor),
				monthsOfOperation,
				investorSplitPct: resolveInvestorSplitPct(config),
				totalJobs,
				completedJobs: completedJobCount,
				totalExpenses: Math.round(totalExpenses),
				// NOTE: `investorEarnings` used to sit here as
				// round((totalRevenue - totalExpenses) * investorSplit) — a SECOND
				// answer to "what has this investor earned", off by $165 from
				// investorNetToDate on live data. The two used different expense
				// bases: the aggregate totalExpenses ($31,199) vs the sum of each
				// month's driverPay + fixedCosts + tripExpenses ($31,531).
				// investorNetToDate is the authoritative one — it is the basis the
				// payout ledger, EarningsSection and driver pay all settle on — so
				// the rival is gone rather than reconciled. Nothing rendered it.
				investorNetToDate,
				totalDriverPay: Math.round(totalDriverPay),
				driverPayDetails: Object.fromEntries(Object.entries(driverPayDetails).map(([k, v]) => [k, { activeDays: v.activeDays, dailyRate: v.dailyRate, totalPay: v.totalPay }])),
				netRevenueToDate,
				totalPurchasePrice,
				totalStartupExpenses,
				perTruckData,
				monthlyEarnings,
				fixedCostBreakdown,
			},
			asset: {
				purchasePrice,
				currentValue,
				titleStatus,
				depreciationYears,
				annualDepreciation: Math.round(totalPurchasePrice / depreciationYears),
				totalTrucks,
				totalMiles: fleetTotalMiles,
				revenuePerMile,
				costPerMile,
			},
			taxShield: {
				section179,
				atRiskCapital,
				writeOffPct: 100,
			},
			recessionProof: {
				totalJobs,
				completedJobs: completedJobCount,
			},
			myLoads,
			config,
			investor: investorProfile ? {
				id: investorProfile.id,
				profilePictureUrl: investorProfile.profile_picture_url || "",
				fullName: investorProfile.full_name || "",
				carrierName: investorProfile.carrier_name || "",
				username: user.username || "",
			} : null,
		});
	} catch (error) {
		console.error("Error building investor data:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// GET /api/investor/expenses — Line-item expenses scoped to the calling
// investor's trucks. Investors only see expenses where owner_id matches
// their user.id OR the expense's driver is in their carrier's driver set
// (legacy fallback for rows logged before owner_id was stamped) — and that
// fallback is bounded to the months the driver was actually theirs, so
// reassigning a driver can no longer republish his whole history here.
// Super Admin path returns all rows for impersonation / QA, mirroring
// the pattern in /api/investor itself.
app.get("/api/investor/expenses", requireRole("Super Admin", "Investor"), async (req, res) => {
	try {
		const preview = resolvePreviewUser(req);
		const user = { ...preview.sessionUser, id: preview.effectiveUserId, username: preview.effectiveUsername };
		const isSuperAdmin = preview.sessionUser.role === "Super Admin" && !preview.isPreview;
		const { truck, type, status, from, to } = req.query;

		// Date range sanity check (matches receipts-download convention)
		if (from && !/^\d{4}-\d{2}-\d{2}$/.test(from)) {
			return res.status(400).json({ error: "'from' must be YYYY-MM-DD" });
		}
		if (to && !/^\d{4}-\d{2}-\d{2}$/.test(to)) {
			return res.status(400).json({ error: "'to' must be YYYY-MM-DD" });
		}

		const conditions = [];
		const params = [];

		if (!isSuperAdmin) {
			// Same scope the dashboard aggregator uses, so this line-item list and the
			// Trip Expenses headline reconcile. Shared builder, not a fourth hand-copy.
			const scope = investorExpenseScopeSql(user.id, getInvestorDriverMonthWindows(user.id), EXPENSE_PERIOD_EXPR);
			conditions.push(scope.sql);
			params.push(...scope.params);
		}

		if (truck) { conditions.push("LOWER(truck_unit) = ?"); params.push(String(truck).toLowerCase()); }
		if (type) { conditions.push("LOWER(type) = ?"); params.push(String(type).toLowerCase()); }
		if (status) {
			conditions.push("LOWER(status) = ?");
			params.push(String(status).toLowerCase());
		} else if (!isSuperAdmin) {
			// Investors don't see Rejected by default — rejected rows never
			// contribute to any total and only add noise to the audit view.
			// They can still opt in via ?status=Rejected explicitly.
			conditions.push("LOWER(status) != 'rejected'");
		}
		if (from) { conditions.push("date >= ?"); params.push(from); }
		if (to) { conditions.push("date <= ?"); params.push(to); }

		// created_at is UTC CURRENT_TIMESTAMP with no zone marker — emit ISO-8601 Z
		// so the client doesn't parse it as local time.
		let sql = "SELECT id, timestamp, driver, load_id, type, amount, description, date, photo_data, status, gallons, odometer, truck_unit, owner_id, location_city, location_state, strftime('%Y-%m-%dT%H:%M:%SZ', created_at) AS created_at FROM expenses";
		if (conditions.length) sql += " WHERE " + conditions.join(" AND ");
		sql += " ORDER BY date DESC, id DESC LIMIT 1000";

		const expenses = db.prepare(sql).all(...params);
		res.json({ expenses });
	} catch (err) {
		console.error("GET /api/investor/expenses error:", err.message);
		res.status(500).json({ error: "Failed to load investor expenses" });
	}
});

// GET /api/investor/payouts — settlement view for one investor.
// Auth mirrors /api/investor: an Investor sees their own payouts; a Super Admin
// previews a specific investor via ?as_user_id=N (payouts are per-owner, so a
// target is required for the admin path — there is no whole-fleet payout).
//
// For every COMPLETED PAST work month (current, in-progress month excluded) we
// idempotently UPSERT one investor_payouts row:
//   - missing  → INSERT (amount = that month's investorEarnings,
//                due_date = lastFridayOfFollowingMonth(period), status 'owed')
//   - existing → refresh `amount` ONLY (earnings can still move while 'owed');
//                status / processed_* / paid_* are NEVER touched here.
// The amount is the SAME number the dashboard shows (computeInvestorMonthlyEarnings).
app.get("/api/investor/payouts", requireRole("Super Admin", "Investor"), async (req, res) => {
	try {
		const preview = resolvePreviewUser(req);
		const user = { ...preview.sessionUser, id: preview.effectiveUserId, username: preview.effectiveUsername };
		const isSuperAdmin = preview.sessionUser.role === "Super Admin" && !preview.isPreview;

		// A Super Admin not previewing anyone has no single owner to settle.
		if (isSuperAdmin) {
			return res.status(400).json({ error: "Pass ?as_user_id=<investorUserId> to view an investor's payouts." });
		}
		if (preview.isPreview) {
			logAudit(req, "investor_payouts_view", "investor", user.id, "");
		}

		const ownerId = user.id;

		// Prime the Job Tracking cache once, then delegate to the shared
		// reconcile (the SAME implementation GET /api/payouts runs per investor).
		// carrierDB + global config are fetched once and threaded via ctx.
		await getJobTrackingCached();
		const globalConfig = {};
		db.prepare("SELECT key, value FROM investor_config WHERE owner_id = 0").all().forEach((r) => (globalConfig[r.key] = r.value));
		const ctx = { sessionUser: preview.sessionUser, carrierDB: getCarrierDBFromSQLite(), globalConfig };

		const { payouts, currentMonth, totals } = await reconcileInvestorPayouts(ownerId, ctx);

		// Lock health. Without it this endpoint answers 200 with a full, plausible
		// ledger while period_locks is unreadable, and the ONLY tell is that every
		// `phase` silently goes blank — which is also what the flag being off looks
		// like, so the two states are indistinguishable from the outside.
		// period_locks is the guard the whole month-close feature rests on; it
		// should not be the quietest thing here.
		//
		// ⚠️ PREVIEW ONLY — deliberately NOT sent to an Investor on their own GET.
		// The expense routes look like a precedent for sending it to anyone, but
		// the distinction that matters is CONDITIONAL vs UNCONDITIONAL, not role:
		// Only two routes emit it today, and both answer a question the caller
		// just asked:
		//   POST /api/expenses        requireAuth — reachable by a Driver — but the
		//                             flag is spread ONLY when postedPeriod is set,
		//                             i.e. the caller just submitted a back-dated
		//                             receipt and is being told where it landed.
		//   PUT /api/expenses/bulk-status   Super Admin / Dispatcher, and only in
		//                             the response to a batch they just submitted.
		// (PUT /api/expenses/:id/status is Super Admin / Dispatcher too but does
		// not emit the flag at all — not a precedent either way.)
		// This route would emit on every passive page load, to an Investor, for
		// as long as the fault lasts.
		//
		// The objection is commercial, not security (it is one boolean — no ids,
		// no schema, no enumeration value). It is an automated admission, to the
		// exact counterparty whose settlement figure is in question, that the
		// accounting freeze was inoperative on a given date — the same fault that
		// can move a settled payout. That belongs to a human, not a JSON key.
		// A Super Admin previewing the portal is who needs the signal, and
		// GET /api/payouts (Super Admin only) carries it for the console.
		const lockReadable = periodLocksReadable();
		const reportLockHealth = preview.isPreview && !lockReadable;
		res.json({ payouts, currentMonth, totals, ...(reportLockHealth ? { periodLockUnreadable: true } : {}) });
	} catch (err) {
		console.error("GET /api/investor/payouts error:", err.message);
		res.status(500).json({ error: "Failed to load investor payouts" });
	}
});

// Shared per-month loader for the two payout drill-down surfaces: the on-screen
// detail modal and the PDF statement. Extracted so the printed document can
// never disagree with the screen — one computation, two presentations.
// Returns { m, detail } where `m` is the monthly earnings row (null when the
// period aged out of the live window) and `detail` is always populated.
async function loadPayoutMonthDetail(ownerId, sessionUser, period) {
	await getJobTrackingCached();
	const config = {};
	db.prepare("SELECT key, value FROM investor_config WHERE owner_id = 0").all().forEach((r) => (config[r.key] = r.value));
	db.prepare("SELECT key, value FROM investor_config WHERE owner_id = ?").all(ownerId).forEach((r) => (config[r.key] = r.value));
	const carrierDB = getCarrierDBFromSQLite();
	const cDriverCol = findCol(carrierDB.headers, /driver/i) || carrierDB.headers[0];
	const cCarrierCol = findCol(carrierDB.headers, /carrier/i);
	const investorDriverSet = getInvestorDriverSet(ownerId, carrierDB.data, cDriverCol, cCarrierCol);

	const { monthlyEarnings, detail } = await computeInvestorMonthlyEarnings({
		user: { ...sessionUser, id: ownerId }, isSuperAdmin: false,
		investorDriverSet, investorOwnerId: ownerId, config, detailForMonth: period,
	});
	const m = monthlyEarnings.find((x) => x.month === period) || null;
	const d = detail || { revenueLoads: [], driverPayRows: [], fixedCostItems: [], tripExpenseItems: [] };

	// Reconciliation guard — each drill-down list MUST sum to its headline.
	// Compared against the EXACT headline (both sides to the cent) so the guard
	// measures real drift rather than the display rounding. Log only; never block.
	if (m) {
		const x0 = m.exact || m;
		const sum = (arr, f) => Math.round(arr.reduce((a, x) => a + (Number(f(x)) || 0), 0) * 100) / 100;
		[["revenue", sum(d.revenueLoads, (x) => x.amount), x0.revenue],
		 ["driverPay", sum(d.driverPayRows, (x) => x.pay), x0.driverPay],
		 ["fixedCosts", sum(d.fixedCostItems, (x) => x.total), x0.fixedCosts],
		 ["tripExpenses", sum(d.tripExpenseItems, (x) => x.amount), x0.tripExpenses]]
			.forEach(([k, got, want]) => { if (Math.abs(got - want) > 1) console.warn(`Payout detail ${period} ${k} drift: items=${got} headline=${want} (owner ${ownerId})`); });
	}
	return { m, detail: d };
}

// GET /api/investor/payouts/:period/detail — lazy per-month line-item drill-down
// for the Payouts waterfall (Revenue / Driver Pay / Fixed Costs / Trip Expenses).
// Computed by the SAME computeInvestorMonthlyEarnings() that produces the totals,
// so each list reconciles to its headline. Honors ?as_user_id= preview scoping.
// GET /api/investor/payouts/:period/history — the movement log for one month.
//
// Answers "when did this amount move, and why". Rows accrue from 2026-08-04 only;
// earlier movements were overwritten in place and cannot be reconstructed, so an
// empty log for an older month means "not recorded", NOT "never moved". The client
// says so rather than showing a bare empty state.
//
// changed_at is re-exposed via strftime because SQLite's CURRENT_TIMESTAMP is UTC
// but serialises with no zone marker, which the browser would read as local.
app.get("/api/investor/payouts/:period/history", requireRole("Super Admin", "Investor"), (req, res) => {
	try {
		const period = String(req.params.period || "");
		if (!/^\d{4}-\d{2}$/.test(period)) return res.status(400).json({ error: "period must be YYYY-MM" });

		// Same scoping rule as the detail route: a Super Admin must name whose
		// payouts they are reading, so an investor's history can never be served
		// off an ambiguous session.
		const preview = resolvePreviewUser(req);
		const isSuperAdmin = preview.sessionUser.role === "Super Admin" && !preview.isPreview;
		if (isSuperAdmin) return res.status(400).json({ error: "Pass ?as_user_id=<investorUserId> to view an investor's payout history." });

		const rows = db.prepare(
			`SELECT id, payout_id, period, kind, old_amount, new_amount, delta, detail, breakdown, actor,
			        strftime('%Y-%m-%dT%H:%M:%SZ', changed_at) AS changed_at
			   FROM investor_payout_history
			  WHERE owner_id = ? AND period = ?
			  ORDER BY changed_at DESC, id DESC`
		).all(preview.effectiveUserId, period);

		res.json({
			period,
			// Explicit, so the UI can distinguish "nothing moved" from "we were not
			// recording yet" without hardcoding the date in the client.
			recordingSince: "2026-08-04",
			entries: rows.map((r) => ({
				id: r.id,
				kind: r.kind,
				oldAmount: r.old_amount,
				newAmount: r.new_amount,
				delta: r.delta,
				detail: r.detail || "",
				actor: r.actor || "",
				changedAt: r.changed_at,
				breakdown: (() => { try { return r.breakdown ? JSON.parse(r.breakdown) : null; } catch { return null; } })(),
			})),
		});
	} catch (error) {
		console.error("GET /api/investor/payouts/:period/history error:", error.message);
		res.status(500).json({ error: "Failed to load payout history" });
	}
});

app.get("/api/investor/payouts/:period/detail", requireRole("Super Admin", "Investor"), async (req, res) => {
	try {
		const period = String(req.params.period || "");
		if (!/^\d{4}-\d{2}$/.test(period)) return res.status(400).json({ error: "period must be YYYY-MM" });

		const preview = resolvePreviewUser(req);
		const isSuperAdmin = preview.sessionUser.role === "Super Admin" && !preview.isPreview;
		if (isSuperAdmin) return res.status(400).json({ error: "Pass ?as_user_id=<investorUserId> to view an investor's payout detail." });
		if (preview.isPreview) logAudit(req, "investor_payout_detail_view", "investor", preview.effectiveUserId, period);

		const ownerId = preview.effectiveUserId;
		const { m, detail: d } = await loadPayoutMonthDetail(ownerId, preview.sessionUser, period);

		// Headlines are the EXACT (unrounded) figures so the modal's totals match
		// its own itemized rows to the cent.
		const mx = m ? (m.exact || m) : null;
		res.json({
			period,
			revenue: mx ? mx.revenue : 0, revenueLoads: d.revenueLoads,
			driverPay: mx ? mx.driverPay : 0, driverPayRows: d.driverPayRows,
			fixedCosts: mx ? mx.fixedCosts : 0, fixedCostItems: d.fixedCostItems,
			tripExpenses: mx ? mx.tripExpenses : 0, tripExpenseItems: d.tripExpenseItems,
			maintFundCost: mx ? mx.maintFundCost : 0, complianceCost: mx ? mx.complianceCost : 0,
			netProfit: mx ? mx.netProfit : 0, investorEarnings: m ? m.investorEarnings : 0,
		});
	} catch (err) {
		console.error("GET /api/investor/payouts/:period/detail error:", err.message);
		res.status(500).json({ error: "Failed to load payout detail" });
	}
});

// GET /api/investor/payouts/:period/statement — PDF payout statement for a PAID
// month. Page 1 is the waterfall ending in the FROZEN figure that was actually
// paid (effectiveAmount), page 2+ itemizes every component.
//
// The payout object comes from reconcileInvestorPayouts — the SAME reconcile the
// ledger screen runs — so `breakdown`, the loss carry-forward chain and the
// adjustment printed here are the ledger's own numbers, never re-derived here.
// The line items come from the shared loadPayoutMonthDetail(), i.e. the same
// computation behind the on-screen drill-down. Two computations, but this route
// is a rate-limited, user-initiated download and a money document that disagrees
// with the screen would be far more expensive than a second of latency.
app.get("/api/investor/payouts/:period/statement", requireRole("Super Admin", "Investor"), statementLimiter, async (req, res) => {
	try {
		const period = String(req.params.period || "");
		if (!/^\d{4}-\d{2}$/.test(period)) return res.status(400).json({ error: "period must be YYYY-MM" });

		const preview = resolvePreviewUser(req);
		const isSuperAdmin = preview.sessionUser.role === "Super Admin" && !preview.isPreview;
		if (isSuperAdmin) return res.status(400).json({ error: "Pass ?as_user_id=<investorUserId> to download an investor's payout statement." });
		const ownerId = preview.effectiveUserId;

		// Direct row read: the reconcile projection omits paid_by, and this is the
		// authority on whether money actually moved.
		const row = db.prepare("SELECT * FROM investor_payouts WHERE owner_id = ? AND period = ?").get(ownerId, period);
		if (!row) return res.status(404).json({ error: `No payout on record for ${period}.` });

		// A statement is issued once the period is FINALIZED — not once the money
		// has moved. Client's words: "let's not wait till after it's paid to
		// publish a statement, let's wait till after the settlement. Then a
		// statement is published of what the final number's going to be."
		//
		// `|| paid` keeps this monotone — strictly more permissive than the old
		// paid-only rule — so every historical paid month stays printable even
		// though it predates period_locks entirely. Note the document itself must
		// then distinguish FINAL from PAID; see the header mode in
		// lib/payout-statement.js, or an investor gets a PDF telling them they were
		// paid before anything was sent.
		if (!isLocked(period) && row.status !== "paid") {
			const pending = isPending(period);
			return res.status(409).json({
				error: pending
					? `${periodLabel(period)} is still in final settlement until ${graceEndsAt(period, settlementGraceDays())}. The statement is published once the period closes.`
					: `A statement is issued once the period is finalized — ${period} is currently ${row.status}.`,
				code: "PERIOD_NOT_FINALIZED",
				period,
				...(pending ? { graceEndsAt: graceEndsAt(period, settlementGraceDays()) } : {}),
			});
		}

		await getJobTrackingCached();
		const globalConfig = {};
		db.prepare("SELECT key, value FROM investor_config WHERE owner_id = 0").all().forEach((r) => (globalConfig[r.key] = r.value));
		const ctx = { sessionUser: preview.sessionUser, carrierDB: getCarrierDBFromSQLite(), globalConfig };
		const { payouts } = await reconcileInvestorPayouts(ownerId, ctx);
		const p = payouts.find((x) => x.period === period);
		if (!p) return res.status(404).json({ error: `No payout on record for ${period}.` });

		// A settled row can still be corrected (PUT …/adjust accepts a paid row and
		// can clamp it to zero), which would otherwise print a document stamped PAID
		// with an "Amount Paid" of $0.00. Mirrors the settleable guard on the
		// status route.
		if (Math.round(p.effectiveAmount) <= 0) {
			return res.status(409).json({
				error: `The ${period} payout nets to $0 after corrections, so there is no statement to issue.`,
				code: "PAYOUT_NOT_SETTLEABLE",
			});
		}

		const { detail } = await loadPayoutMonthDetail(ownerId, preview.sessionUser, period);

		// Investor identity — same COALESCE precedence as listSettlableInvestors().
		const who = db.prepare(
			`SELECT COALESCE(NULLIF(TRIM(i.full_name),''), NULLIF(TRIM(u.company_name),''), u.username) AS name,
			        COALESCE(NULLIF(TRIM(u.company_name),''), NULLIF(TRIM(i.carrier_name),''), '') AS company
			   FROM users u LEFT JOIN investors i ON i.user_id = u.id WHERE u.id = ?`,
		).get(ownerId) || { name: "Investor", company: "" };

		// A correction recorded AFTER the money went out means effectiveAmount is
		// the corrected net, not the sum that was wired — the document has to say
		// so rather than labelling the net "Amount Paid".
		const adjustedAfterPaid = !!(
			p.adjustmentApplied && row.adjusted_at && row.paid_at && String(row.adjusted_at) > String(row.paid_at)
		);

		// Log the attempt BEFORE the render so a failed download is still on record.
		logAudit(req, "investor_payout_statement", "investor_payout", row.id,
			`Downloaded ${period} payout statement (${who.name}${row.paid_at ? "" : " — FINAL, not yet paid"})`);

		// Prefer the composition SNAPSHOT taken when the period was finalized over a
		// live recompute. This is what actually retires the drift disclosure: a
		// historical month's recompute keeps moving underneath it (getMonthlyFixedCosts
		// reads trucks.status='Active', splitPct reads the CURRENT config), so a
		// statement re-downloaded months later used to show a composition that no
		// longer added up to the figure printed beside it. The snapshot is what the
		// investor was shown at close. Legacy/baseline rows have no snapshot and fall
		// through to `p.breakdown` — the existing live path, drift note and all.
		let frozenBreakdown = null;
		if (row.finalized_breakdown) {
			try { frozenBreakdown = JSON.parse(row.finalized_breakdown); } catch { frozenBreakdown = null; }
		}

		const html = buildPayoutStatementHtml({
			investorName: who.name,
			// Don't print the same string twice when full_name and company_name match.
			investorCompany: String(who.company || "").trim() === String(who.name || "").trim() ? "" : who.company,
			period,
			periodLabel: p.periodLabel,
			status: p.status,
			paidAt: p.paidAt,
			paidBy: row.paid_by || "",
			// Drives FINAL-vs-PAID mode in the document: a period can now be
			// finalized (and its statement published) before any money moves.
			finalizedAt: row.finalized_at || "",
			dueDate: p.dueDate,
			adjustedAt: row.adjusted_at || "",
			adjustedAfterPaid,
			breakdown: frozenBreakdown || p.breakdown,
			// ⚠️ THESE MUST TRACK `breakdown` ABOVE, OR THE PAGE DOES NOT FOOT.
			// They used to be unconditionally LIVE, so a finalized month printed a
			// frozen top half with a re-derived subtraction beneath it — the June
			// statement whose "− Earlier loss applied −$1,563.00" matched nothing
			// else on the page. finalizePeriods now snapshots both terms INSIDE
			// finalized_breakdown, so a row closed since that change prints one
			// self-consistent set of numbers.
			//
			// ⚠️ `??`, NEVER `||`. Zero is the COMMON value here — most months carry
			// nothing in — and `||` would send every one of them back to the live
			// recompute, i.e. re-create the exact bug for the majority of statements.
			// Only a genuinely absent key (every row finalized before this shipped)
			// falls through to live, which is byte-identical to the old behaviour and
			// is what keeps 2026-01…2026-07 printable.
			lossCarriedIn: frozenBreakdown?.lossCarriedIn ?? p.lossCarriedIn,
			lossDeferred: frozenBreakdown?.lossDeferred ?? p.lossDeferred,
			// adjustmentApplied is the delta that ACTUALLY landed, so
			// amount + it === effectiveAmount always holds on the printed page.
			adjustment: p.adjustmentApplied,
			adjustmentNote: p.adjustmentNote,
			amount: p.amount,
			effectiveAmount: p.effectiveAmount,
			detail,
			statementNo: `${period.replace("-", "")}-${row.id}`,
			generatedAt: new Date(),
		});

		const pdf = await renderHtmlToPdf(html);
		const safeName = String(who.name || "Investor").replace(/[^a-zA-Z0-9._-]/g, "_");
		// Distinguish the two documents on disk. An investor who downloads the final
		// statement in July and the paid one in August should not end up with two
		// identically-named files where the second silently replaces the first.
		const kind = row.paid_at ? "Payout_Statement" : "Final_Statement";
		res.setHeader("Content-Type", "application/pdf");
		res.setHeader("Content-Disposition", `attachment; filename="LogisX_${kind}_${safeName}_${period}.pdf"`);
		res.send(pdf);
	} catch (err) {
		console.error("GET /api/investor/payouts/:period/statement error:", err.message);
		res.status(500).json({ error: "Failed to generate the payout statement" });
	}
});

// GET /api/payouts — ADMIN settlement console: aggregates payouts ACROSS every
// investor. Runs the SAME per-investor reconcile (reconcileInvestorPayouts) the
// single-investor route uses — one formula, no duplication. The Job Tracking
// sheet is fetched ONCE up front (cache primed) and the carrier DB + global
// config are fetched once and threaded into each investor's reconcile, so a
// fleet-wide loop never refetches per investor.
//
// Returns:
//   investors[]    — per investor: { ownerId, name, payouts[], currentMonth,
//                    totalOwed, totalProcessing, totalPaid }, sorted by name
//   monthlyTotals[]— per period summed across investors (owed/processing/paid/
//                    total) = "how much is paid out each month", period DESC
//   grandTotals    — { totalOwed, totalProcessing, totalPaid } across everyone
app.get("/api/payouts", requireRole("Super Admin"), async (req, res) => {
	try {
		// Fetch the Job Tracking sheet ONCE up front (primes the 60s cache so every
		// per-investor computeInvestorMonthlyEarnings reconciles against the same
		// snapshot — no per-investor sheet fetch). carrierDB + global config are
		// likewise read once and threaded through ctx.
		await getJobTrackingCached();
		const globalConfig = {};
		db.prepare("SELECT key, value FROM investor_config WHERE owner_id = 0").all().forEach((r) => (globalConfig[r.key] = r.value));
		const ctx = { sessionUser: req.session.user, carrierDB: getCarrierDBFromSQLite(), globalConfig };

		const investorList = listSettlableInvestors();

		const investors = [];
		const monthly = new Map();   // period -> { period, periodLabel, owed, processing, paid, total }
		const grandTotals = { totalOwed: 0, totalProcessing: 0, totalPaid: 0 };

		for (const inv of investorList) {
			// SAME reconcile as GET /api/investor/payouts (shared implementation).
			const { payouts, currentMonth, totals } = await reconcileInvestorPayouts(inv.ownerId, ctx);

			// How many recorded movements each period has, so the console can show
			// the affordance only on rows that actually have something behind it.
			// ONE grouped query per investor rather than one per row: this endpoint
			// already loops every settlable investor, and a per-row query would turn
			// a page load into investors x months round-trips.
			const histCounts = {};
			try {
				for (const r of db.prepare(
					"SELECT period, COUNT(*) AS n FROM investor_payout_history WHERE owner_id = ? GROUP BY period"
				).all(inv.ownerId)) histCounts[r.period] = r.n;
			} catch { /* history is additive; its absence must not break the console */ }

			investors.push({
				ownerId: inv.ownerId,
				name: inv.name,
				payouts: payouts.map((p) => ({
					id: p.id,
					period: p.period,
					historyCount: histCounts[p.period] || 0,
					periodLabel: p.periodLabel,
					amount: p.amount,
					adjustment: p.adjustment,
					effectiveAmount: p.effectiveAmount,
					adjustmentNote: p.adjustmentNote,
					adjustedBy: p.adjustedBy,
					adjustedAt: p.adjustedAt,
					recomputedAmount: p.recomputedAmount,
					dueDate: p.dueDate,
					status: p.status,
					paidAt: p.paidAt,
					reopenedAt: p.reopenedAt,
					reopenedBy: p.reopenedBy,
					reopenReason: p.reopenReason,
					// Close lifecycle — the console gates Mark Processing/Paid and
					// Adjust on these, matching the server guards exactly.
					phase: p.phase,
					graceEndsAt: p.graceEndsAt,
					finalizedAt: p.finalizedAt,
				})),
				currentMonth,
				totalOwed: totals.totalOwed,
				totalProcessing: totals.totalProcessing,
				totalPaid: totals.totalPaid,
			});

			grandTotals.totalOwed += totals.totalOwed;
			grandTotals.totalProcessing += totals.totalProcessing;
			grandTotals.totalPaid += totals.totalPaid;

			// Sum each settled month ACROSS investors → "paid out each month".
			for (const p of payouts) {
				let bucket = monthly.get(p.period);
				if (!bucket) {
					bucket = { period: p.period, periodLabel: p.periodLabel, owed: 0, processing: 0, paid: 0, total: 0 };
					monthly.set(p.period, bucket);
				}
				if (p.status === "owed") bucket.owed += p.effectiveAmount;
				else if (p.status === "processing") bucket.processing += p.effectiveAmount;
				else if (p.status === "paid") bucket.paid += p.effectiveAmount;
				bucket.total += p.effectiveAmount;
			}
		}

		const monthlyTotals = [...monthly.values()]
			.sort((a, b) => (a.period < b.period ? 1 : a.period > b.period ? -1 : 0)); // period DESC

		// See GET /api/investor/payouts for the reasoning — same key, same shape,
		// probed ONCE for the whole response rather than per investor (the answer
		// cannot change mid-request, and on a broken table each probe re-compiles a
		// failing statement). Absent on a healthy database.
		const lockReadable = periodLocksReadable();
		res.json({ investors, monthlyTotals, grandTotals, ...(lockReadable ? {} : { periodLockUnreadable: true }) });
	} catch (err) {
		console.error("GET /api/payouts error:", err.message);
		res.status(500).json({ error: "Failed to load payouts" });
	}
});

// POST /api/investor/payouts/:id/status — Super Admin moves a payout along its
// lifecycle in EITHER direction:
//   forward  owed → processing → paid (owed → paid also allowed)
//   backward paid → processing → owed (paid → owed also allowed)
//
// Forward stamps processed_at/by and paid_at/by from the session admin.
// Backward ("reopen") is the correction path for a settlement advanced by
// mistake — the real case that motivated it: "Mark Paid" clicked on a payout
// that was never actually sent, leaving $8,703 booked as paid with no way to
// walk it back. A reopen REQUIRES a reason, un-stamps the milestones it undoes
// (so paid_at never survives a row that is no longer paid), and records who did
// it on the row + in audit_trail. Amount/period stay immutable here — use
// PUT /api/investor/payouts/:id/adjust to change the money.
//
// One consequence worth knowing: reconcileInvestorPayouts refreshes `amount`
// ONLY while a row is 'owed'. Reopening to 'processing' keeps the settled
// figure frozen; reopening all the way to 'owed' re-links the row to live
// earnings, so its amount will track recomputes again on the next read.
const PAYOUT_STATUS_RANK = { owed: 0, processing: 1, paid: 2 };
app.post("/api/investor/payouts/:id/status", requireRole("Super Admin"), refuseCrossOrigin, (req, res) => {
	try {
		const id = parseInt(req.params.id, 10);
		if (!Number.isFinite(id) || id <= 0) {
			return res.status(400).json({ error: "Invalid payout id" });
		}
		const status = typeof req.body?.status === "string" ? req.body.status.trim() : "";
		if (!Object.prototype.hasOwnProperty.call(PAYOUT_STATUS_RANK, status)) {
			return res.status(400).json({ error: "status must be 'owed', 'processing' or 'paid'" });
		}

		const payout = db.prepare("SELECT * FROM investor_payouts WHERE id = ?").get(id);
		if (!payout) return res.status(404).json({ error: "Payout not found" });

		const fromRank = PAYOUT_STATUS_RANK[payout.status];
		const toRank = PAYOUT_STATUS_RANK[status];
		if (fromRank === undefined) {
			return res.status(409).json({ error: `Payout is in an unrecognized state ('${payout.status}').` });
		}
		if (fromRank === toRank) {
			return res.status(409).json({ error: `This payout is already '${status}'.` });
		}
		const isReopen = toRank < fromRank;

		// A backward move rewrites settled financial history, so it never happens
		// silently — the reason is mandatory and lands on the row + audit trail.
		let reason = "";
		if (isReopen) {
			reason = (req.body?.reason || "").toString().trim().slice(0, 500);
			if (!reason) {
				return res.status(400).json({ error: "A reason is required to reopen a settled payout." });
			}
		}

		// Nothing to settle: a month with no activity, or one whose earnings were
		// fully absorbed by an earlier loss (see the carry-forward in
		// reconcileInvestorPayouts). Losses no longer produce negative rows, but
		// an adjustment can still zero one out — either way there is no payment to
		// make, so don't let it be stamped paid. Reopening is exempt: a $0 row
		// advanced by mistake still has to be walkable back.
		const settleable = Math.round((payout.amount || 0) + Number(payout.adjustment || 0));
		if (!isReopen && settleable <= 0) {
			return res.status(409).json({ error: "Nothing to settle for this period — the payable amount is $0." });
		}

		// The month is over but still inside its grace window, so its figure is
		// still moving as straggler receipts land. Settling now is precisely how
		// the correction treadmill started: mark paid on the 1st, a receipt arrives
		// on the 4th, hand-write an adjustment. Blocking the forward move until the
		// period is finalized is the actual fix — the window is only useful if
		// nothing can be settled out from under it.
		//
		// Reopening stays exempt, same as the $0 rule above: a payout advanced by
		// mistake yesterday must still be walkable back today, window or no window.
		//
		// ⚠️ THIS GUARD FAILS CLOSED, AND ONLY VIA A DOUBLE NEGATIVE. Spelled out,
		// because the expression does not say it and the next person will be tempted
		// to tidy it:
		//   isPending(p)  ==  flag on && p is a past month && !isLocked(p)
		//   isLocked(p)   ==  false on ANY error, including an unreadable table
		// so when period_locks cannot be read, isLocked is false, isPending is TRUE,
		// and this blocks. Blocking is the right answer — refusing to settle costs a
		// retry, settling a month that may already be finalized costs a restated
		// payout — but it is right by accident, not by construction.
		//
		// DO NOT rewrite this as `periodPhase(p) === 'pending'`. periodPhase()
		// deliberately returns '' when the table is unreadable (it refuses to label
		// a month it cannot look up), so that rewrite reads as "not pending", the
		// guard stops firing, and the failure direction INVERTS silently — settling
		// straight into a possibly-closed month. Same trap for any refactor that
		// routes through isLocked() directly. If this ever does need restating, the
		// fail-closed predicate to build on is periodWriteLocked(), not isLocked().
		if (!isReopen && isPending(payout.period)) {
			// Probed only once the guard has already fired, so the healthy path does
			// no extra work. Two very different situations were reading identically:
			// "the window is still open, wait for the 7th" is a normal, self-resolving
			// state, while "we cannot tell" is a broken database that resolves only
			// when someone fixes it. Telling an admin to wait for a date is actively
			// misleading in the second case — the date will pass and nothing will
			// change.
			const lockUnreadable = !periodLocksReadable();
			// ⚠️ THE REFUSAL IS AUDITED. This is the settle route — "Mark Paid" is the
			// only verb in the app that asserts money actually moved — and until now
			// the ONLY logAudit on it was on the success path, so a blocked settlement
			// left no trace whatsoever. audit_trail could therefore not distinguish
			// "nobody tried to settle June early" from "someone tried repeatedly and
			// the close window refused them", which is precisely the signal a refusal
			// row exists to keep. Same gap, same fix as PUT /api/expenses/bulk-status
			// and its single-row twin.
			//
			// THE CAUSE CODE IS NOT THE WIRE CODE, DELIBERATELY. The response says
			// PERIOD_NOT_FINALIZED in both branches (an existing client shape; not
			// changed here), but the two causes are different things with different
			// remedies — one is a normal window that clears on a date, the other is a
			// database fault that never will. Auditing both as one code would hide
			// PERIOD_LOCK_UNREADABLE from the cross-route search for it, which is how
			// a broken period_locks gets noticed at all; every other guard in this file
			// records that condition under that name. The wire code is not lost — the
			// period and the transition below identify the request.
			//
			// logAuditRefusal, not logAudit: BOTH codes are in
			// UNCOALESCED_REFUSAL_CODES (asserted at boot — PERIOD_NOT_FINALIZED was
			// added there with this change and was NOT previously a member). Without
			// that membership two operators refused inside the same 60s window would
			// collapse to one row naming one of them: the coalesce key is the ACCOUNT,
			// and `super_admin` is a shared login, so "a different person" is the same
			// key. On a settlement route that is the exact bug being closed.
			//
			// ⚠️ NOT added to PURGEABLE_REFUSAL_ACTIONS. It satisfies that list's
			// invariant — the 409 returns before any write, so this is a wholesale
			// refusal — but it must not be purged, and the purge's own comment makes
			// the argument better than this one could: settlement disputes surface on a
			// quarterly or annual cadence, i.e. reliably after 90 days. "Who kept
			// trying to mark this month paid, and when" is a question asked long after
			// the fact or not at all. Adding it would also be a no-op today (every row
			// carries a `[PERIOD_` code, which the purge's detail filter exempts) that
			// reads as a decision these rows are disposable. They are the opposite.
			//
			// The amount is recorded because on this route the money IS the change.
			// `super_admin` is a shared login: this identifies the account and session,
			// never an individual.
			const refusalCode = lockUnreadable ? "PERIOD_LOCK_UNREADABLE" : "PERIOD_NOT_FINALIZED";
			// The route reads `reason` only on the reopen path, and a reopen is exempt
			// from this guard — so the local `reason` is "" here by construction and a
			// note sent with a forward move would be discarded. It is captured anyway:
			// stated intent is MORE useful on a refusal than on a success, and on a
			// blocked "Mark Paid" it is the record of what someone believed they were
			// settling. Same 500-char cap as the reopen path, plus the newline collapse
			// expenseStatusReason() applies — an audit detail is a single line.
			const blockedNote = (req.body?.reason || "").toString().replace(/[\r\n\t]+/g, " ").trim().slice(0, 500);
			logAuditRefusal(
				req, "investor_payout_status_blocked", "investor_payout", id,
				`${payout.status} -> ${status} WITHHELD (owner ${payout.owner_id} ${payout.period},` +
				` $${(Number(payout.amount || 0) + Number(payout.adjustment || 0)).toFixed(2)})` +
				` [${refusalCode}] period=${payout.period || "unknown"} — nothing was written` +
				(blockedNote ? ` — reason: ${blockedNote}` : ""),
				refusalCode
			);
			return res.status(409).json({
				error: lockUnreadable
					? `${periodLabel(payout.period)} cannot be confirmed closed — the period lock table could not be read, so this settlement is blocked until it can be. This is a database fault, not the close window; waiting will not clear it.`
					: `${periodLabel(payout.period)} is still in final settlement — receipts can be added until ${graceEndsAt(payout.period, settlementGraceDays())}. It settles automatically after that, or close it early from the Payouts console.`,
				code: "PERIOD_NOT_FINALIZED",
				period: payout.period,
				graceEndsAt: graceEndsAt(payout.period, settlementGraceDays()),
				...(lockUnreadable ? { periodLockUnreadable: true } : {}),
			});
		}

		const nowIso = new Date().toISOString();
		const actor = req.session.user.username;

		if (isReopen) {
			// Clear the milestones being undone so no stale stamp outlives the
			// status it belonged to: dropping out of 'paid' clears paid_at/by,
			// and going all the way back to 'owed' clears the processing pair too.
			if (status === "owed") {
				db.prepare(
					`UPDATE investor_payouts SET status = 'owed',
						processed_at = NULL, processed_by = NULL, paid_at = NULL, paid_by = NULL,
						reopened_at = ?, reopened_by = ?, reopen_reason = ? WHERE id = ?`
				).run(nowIso, actor, reason, id);
			} else {
				db.prepare(
					`UPDATE investor_payouts SET status = 'processing',
						paid_at = NULL, paid_by = NULL,
						processed_at = COALESCE(processed_at, ?), processed_by = COALESCE(processed_by, ?),
						reopened_at = ?, reopened_by = ?, reopen_reason = ? WHERE id = ?`
				).run(nowIso, actor, nowIso, actor, reason, id);
			}
		} else if (status === "processing") {
			db.prepare(
				"UPDATE investor_payouts SET status = 'processing', processed_at = ?, processed_by = ? WHERE id = ?"
			).run(nowIso, actor, id);
		} else {
			// Moving to paid. If it skipped 'processing' (owed→paid), stamp the
			// processing fields too so the audit trail is complete.
			if (payout.status === "owed") {
				db.prepare(
					"UPDATE investor_payouts SET status = 'paid', processed_at = COALESCE(processed_at, ?), processed_by = COALESCE(processed_by, ?), paid_at = ?, paid_by = ? WHERE id = ?"
				).run(nowIso, actor, nowIso, actor, id);
			} else {
				db.prepare(
					"UPDATE investor_payouts SET status = 'paid', paid_at = ?, paid_by = ? WHERE id = ?"
				).run(nowIso, actor, id);
			}
		}

		// Every status branch above converges here, so one hook covers forward
		// settlement AND reopens. A status change does not move `amount` — it moves
		// the settlement STATE — so old and new are equal by design; the value is in
		// the transition itself. Without this the timeline would show a month's
		// figure changing and then go silent about it being paid, which is the half
		// of the story Deshorn is most likely to be asking about.
		recordPayoutChange({
			payoutId: id,
			ownerId: payout.owner_id,
			period: payout.period,
			kind: "status",
			oldAmount: Number(payout.amount || 0) + Number(payout.adjustment || 0),
			newAmount: Number(payout.amount || 0) + Number(payout.adjustment || 0),
			detail: isReopen
				? `reopened ${payout.status} -> ${status}: ${reason}`
				: `${payout.status} -> ${status}`,
			actor,
		});

		// Tag reversals distinctly — scanning the trail for money that was
		// un-booked should not mean eyeballing every status line.
		logAudit(
			req,
			"investor_payout_status",
			"investor_payout",
			id,
			isReopen
				? `REOPENED ${payout.status} -> ${status} (owner ${payout.owner_id} ${payout.period}): ${reason}`
				: `${payout.status} -> ${status}`
		);
		const updated = db.prepare(
			"SELECT *, strftime('%Y-%m-%dT%H:%M:%SZ', created_at) AS created_at FROM investor_payouts WHERE id = ?"
		).get(id);
		res.json({ success: true, reopened: isReopen, payout: updated });
	} catch (err) {
		console.error("POST /api/investor/payouts/:id/status error:", err.message);
		res.status(500).json({ error: "Failed to update payout status" });
	}
});

// PUT /api/investor/payouts/:id/adjust — Super Admin records a signed correction
// on ANY payout period, including one already processing/paid. The canonical use
// case: receipts uploaded AFTER the month settled that should have reduced the
// investor's share (a negative adjustment claws it back on the record); a
// positive adjustment credits the investor. Effective payout = amount +
// adjustment. The reconcile only ever writes `amount`, so this manual delta
// persists across live recomputes. Mirrors PUT /api/invoices/:id/adjust.
app.put("/api/investor/payouts/:id/adjust", requireRole("Super Admin"), refuseCrossOrigin, (req, res) => {
	try {
		const id = parseInt(req.params.id, 10);
		if (!Number.isFinite(id) || id <= 0) {
			return res.status(400).json({ error: "Invalid payout id" });
		}
		const payout = db.prepare("SELECT * FROM investor_payouts WHERE id = ?").get(id);
		if (!payout) return res.status(404).json({ error: "Payout not found" });

		// An adjustment is only meaningful once the underlying figure has stopped
		// moving. On a period that is still open, `amount` is refreshed from live
		// earnings on every read — so a manual delta layered on top gets counted
		// twice and drifts again on the next reconcile.
		//
		// Until now this rule lived only in the UI (PayoutsView hid the button for
		// 'owed' rows); the server accepted the write. Anchoring it to the PERIOD
		// rather than the row's status both closes that hole and loosens the case
		// that matters: a finalized-but-not-yet-paid row IS adjustable, which is
		// exactly the finalize -> correct -> pay flow the close window is for.
		//
		// ⚠️ FAILS CLOSED VIA THE SAME DOUBLE NEGATIVE as the settle guard in
		// POST /api/investor/payouts/:id/status — see the long note there before
		// touching either. Short version: isPending() is true when period_locks
		// cannot be read (because isLocked() swallows the error and answers false),
		// so an unreadable table blocks the adjustment. That is the safe direction,
		// and rewriting this in terms of periodPhase() would reverse it.
		if (isPending(payout.period)) {
			// See the settle guard for why the unreadable case gets its own sentence:
			// the old copy named a date the admin could wait for, which is a false
			// statement about a month whose lock state is simply unknown.
			const lockUnreadable = !periodLocksReadable();
			// ⚠️ THE REFUSAL IS AUDITED, AND IT WAS THE LAST OUTCOME OF THIS ROUTE
			// THAT WAS NOT. This is the one verb in the app that restates a SETTLED
			// month directly — a signed correction of up to ±$10,000 applied to a
			// payout that may already be marked paid — and the only logAudit on it was
			// on the success path. A blocked correction therefore left no trace at
			// all, so audit_trail could not tell "nobody tried to claw back May" from
			// "someone tried repeatedly and the close window refused them", which is
			// the entire signal a refusal row exists to keep. Same gap and same fix as
			// its two siblings: POST /api/investor/payouts/:id/status (the settle
			// route, which shares this exact guard) and PUT /api/expenses/:id/status.
			//
			// THE CAUSE CODE IS NOT THE WIRE CODE, DELIBERATELY — the same call the
			// settle route makes. The response says PERIOD_NOT_FINALIZED in both
			// branches (an existing client shape, not changed here), but the two
			// causes are different things with different remedies: one is a normal
			// window that clears on a date, the other is a database fault that never
			// will. Auditing both under one code would hide PERIOD_LOCK_UNREADABLE
			// from the cross-route search for it, which is how a broken period_locks
			// gets noticed at all — every other guard in this file records that
			// condition under that name. The wire code is not lost; the period and the
			// transition below identify the request.
			//
			// logAuditRefusal, not logAudit: both codes are already in
			// UNCOALESCED_REFUSAL_CODES (asserted at boot by
			// assertUncoalescedRefusalContract, which also keeps the `PERIOD_…`
			// naming that exempts these rows from purgeOldAuditRefusals' detail
			// filter), so this is byte-identical to logAudit today while stating the
			// intent — and a future non-period refusal audited on this action inherits
			// the coalescing window without anyone having to remember. If either code
			// were dropped from that set, a second operator refused inside the same
			// 60s window would write NOTHING and this bug would be back: the coalesce
			// key is the ACCOUNT, and `super_admin` is a SHARED login, so "a different
			// person" does not produce a different key.
			//
			// ⚠️ NOT added to PURGEABLE_REFUSAL_ACTIONS, and of the three siblings
			// this is the one with the least excuse for being there. It satisfies that
			// list's stated invariant — the 409 returns before the UPDATE, so this is
			// a wholesale refusal — but the purge's own comment makes the argument
			// better than this one could: settlement disputes surface on a quarterly
			// or annual cadence, i.e. reliably AFTER 90 days, so purging by action
			// would delete the evidence exactly when it is first wanted while the
			// corresponding successful corrections are kept forever. It also cannot
			// flood — Super Admin only, behind refuseCrossOrigin, and it needs a
			// past-but-unlocked month to fire at all. Adding it would purge nothing
			// today anyway (every row here carries a `[PERIOD_` code, which the detail
			// filter exempts) while reading as a decision that these rows are
			// disposable. They are the opposite.
			//
			// ⚠️ THE AMOUNT RECORDED IS THE ATTEMPT, NOT A FIGURE THAT WOULD HAVE BEEN
			// WRITTEN. This guard runs BEFORE the finite check, the ±$10,000 cap and
			// the never-invert rule, so the request may have been invalid on its own
			// terms and this row must not be read as "this correction would otherwise
			// have landed". It is parsed with the SAME Number() expression the
			// validator below uses, so the audit can never disagree with the route
			// about what the caller sent — note that null/""/[] are 0 to both, and an
			// absent or unparseable value is recorded as such rather than silently
			// becoming $0.00.
			//
			// entity/entity_id are the payout id, matching the success line below.
			// `super_admin` is a shared login, so this identifies the account and
			// session, never an individual.
			const refusalCode = lockUnreadable ? "PERIOD_LOCK_UNREADABLE" : "PERIOD_NOT_FINALIZED";
			// Explicit sign on both sides: a claw-back and a credit are opposite
			// events and `-` alone is easy to lose in a line of prose.
			const signedUsd = (n) => `${n < 0 ? "-" : "+"}$${Math.abs(n).toFixed(2)}`;
			const rawAdjustment = req.body?.adjustment;
			const attempted = Number(rawAdjustment);
			// The echo is bounded by TYPE, not by slicing the result of String():
			// a string is worth quoting back because the typo is the useful part,
			// while an array from a 50 MB body would build a huge string only to
			// throw all but 24 characters of it away.
			const attemptedText = Number.isFinite(attempted)
				? signedUsd(attempted)
				: `unparseable (${rawAdjustment === undefined ? "absent"
					: typeof rawAdjustment === "string" ? JSON.stringify(rawAdjustment.slice(0, 24))
					: typeof rawAdjustment})`;
			// The route's own note field — `adjustmentNote` is the only one its client
			// sends, and it is what the success line records. Captured because stated
			// intent is MORE useful on a refusal than on a success: it is the record
			// of what someone believed they were correcting on a month the server
			// would not let them touch. Same 500-char cap as the success path, plus
			// the newline collapse every audit detail gets — this table is read one
			// line per row and exported.
			const blockedNote = (req.body?.adjustmentNote || "").toString().replace(/[\r\n\t]+/g, " ").trim().slice(0, 500);
			const currentAdjustment = Number(payout.adjustment || 0);
			logAuditRefusal(
				req, "investor_payout_adjust_blocked", "investor_payout", id,
				`adjustment ${signedUsd(currentAdjustment)} -> ${attemptedText} WITHHELD (owner ${payout.owner_id} ${payout.period},` +
				` payout ${payout.status || "unknown"} $${(Number(payout.amount || 0) + currentAdjustment).toFixed(2)})` +
				` [${refusalCode}] period=${payout.period || "unknown"} — nothing was written` +
				(blockedNote ? ` — reason: ${blockedNote}` : ""),
				refusalCode
			);
			return res.status(409).json({
				error: lockUnreadable
					? `${periodLabel(payout.period)} cannot be confirmed finalized — the period lock table could not be read, so adjustments are blocked until it can be. Log the receipt as normal; this is a database fault, not the close window.`
					: `${periodLabel(payout.period)} is still open until ${graceEndsAt(payout.period, settlementGraceDays())} — log the receipt and it will be counted automatically. Adjustments apply once the period is finalized.`,
				code: "PERIOD_NOT_FINALIZED",
				period: payout.period,
				graceEndsAt: graceEndsAt(payout.period, settlementGraceDays()),
				...(lockUnreadable ? { periodLockUnreadable: true } : {}),
			});
		}

		const adjustment = Number(req.body?.adjustment);
		if (!Number.isFinite(adjustment)) {
			return res.status(400).json({ error: "adjustment must be a finite number" });
		}
		// Conservative cap — matches the invoices adjust endpoint. Late-receipt
		// corrections are small; raise if a real case needs more headroom.
		if (Math.abs(adjustment) > 10000) {
			return res.status(400).json({ error: "adjustment magnitude capped at $10,000 — contact engineering if you need more" });
		}
		const note = (req.body?.adjustmentNote || "").toString().trim().slice(0, 500);
		// Whole dollars — payout amounts are whole-dollar throughout (investorEarnings
		// is Math.round'd), so keeping the adjustment whole makes amount+adjustment
		// exact and avoids a cents mismatch between the stored delta and effectiveAmount.
		const rounded = Math.round(adjustment);
		// A payout can be reduced to nothing but never inverted: a negative adjusted
		// total is a debt the investor cannot settle, the same nonsense the loss
		// carry-forward removed. Reject rather than silently clamp, so the admin
		// sees the ceiling and can decide, instead of having their number altered.
		const base = Math.round(payout.amount || 0);
		if (base + rounded < 0) {
			return res.status(400).json({
				error: `Deduction exceeds the payout. This period is ${base < 0 ? "$0" : "$" + base.toLocaleString()}, so the largest deduction is ${base <= 0 ? "$0" : "−$" + base.toLocaleString()}.`,
			});
		}
		const nowIso = new Date().toISOString();
		const actor = req.session.user.username || "";
		const oldAdjustment = Number(payout.adjustment || 0);

		db.prepare(
			"UPDATE investor_payouts SET adjustment = ?, adjustment_note = ?, adjusted_by = ?, adjusted_at = ? WHERE id = ?"
		).run(rounded, note, actor, nowIso, id);

		// An adjustment does not change `amount` — it sits beside it — so the
		// effective payout moves without `amount` moving. Record the EFFECTIVE
		// figures, or the timeline would show a settled month as unchanged while
		// the number the investor is paid demonstrably changed.
		recordPayoutChange({
			payoutId: id,
			ownerId: payout.owner_id,
			period: payout.period,
			kind: "adjustment",
			oldAmount: Number(payout.amount || 0) + Number(payout.adjustment || 0),
			newAmount: Number(payout.amount || 0) + rounded,
			detail: note ? `adjustment: ${note}` : "adjustment",
			actor,
		});

		// Flag corrections to an already-settled row explicitly in the audit trail.
		const settledTag = (payout.status === "paid" || payout.status === "processing")
			? `POST-SETTLEMENT EDIT (status ${payout.status}): ` : "";
		logAudit(
			req,
			"investor_payout_adjust",
			"investor_payout",
			id,
			`${settledTag}owner ${payout.owner_id} ${payout.period}: adjustment ${oldAdjustment.toFixed(2)} -> ${rounded.toFixed(2)} (${note || "no reason given"})`
		);

		const updated = db.prepare(
			"SELECT *, strftime('%Y-%m-%dT%H:%M:%SZ', created_at) AS created_at FROM investor_payouts WHERE id = ?"
		).get(id);
		res.json({
			success: true,
			payout: {
				...updated,
				effectiveAmount: Math.max(0, Math.round((updated.amount || 0) + Number(updated.adjustment || 0))),
			},
		});
	} catch (err) {
		console.error("PUT /api/investor/payouts/:id/adjust error:", err.message);
		res.status(500).json({ error: "Failed to adjust payout" });
	}
});

// ============================================================
// Period close — manual finalize / reopen
// ============================================================
// The close normally happens on its own (see the finalize sweep), so these are
// the two human overrides:
//   POST /api/periods/:period/finalize — "everything's in, close it now"
//   POST /api/periods/:period/reopen   — "we got that wrong, open it back up"
//
// Both are FLEET-WIDE: one carrier, one month-end. Payout status stays per
// investor, but a month is open or closed for everybody, because the
// super-admin branch of the monthly math sums all expenses with no owner scope
// and there is no coherent answer to "which month does this receipt post to" if
// March is closed for one investor and open for another.

// GET /api/periods — the close calendar: every locked period plus the ones
// currently accruing/pending, so the console can render the lifecycle without
// inferring it from payout rows.
app.get("/api/periods", requireRole("Super Admin"), (req, res) => {
	try {
		const graceDays = settlementGraceDays();
		const locks = db.prepare("SELECT * FROM period_locks ORDER BY period DESC").all();
		const cur = currentMonthKeyCT();

		// Periods that have payout rows but no lock yet — i.e. accruing or pending.
		//
		// `period_locks.status` is QUALIFIED, and that is the whole point of this
		// line. Written bare as `WHERE status = 'locked'` it silently produced the
		// wrong answer on exactly the database this screen exists to diagnose: if
		// period_locks is rebuilt without its `status` column (the break
		// periodLocksReadable() was written for), SQL scoping does not error — it
		// resolves the unqualified name outward to investor_payouts.status, turning
		// the subquery into a correlated reference that is never 'locked'. It then
		// returns EMPTY, `NOT IN ()` matches everything, and all 14 locked months
		// land in the `open` bucket — so every finalized month rendered as never
		// finalized, on the one page an admin opens mid-outage.
		// Qualified, the same break throws and the route 500s: still bad, but bad in
		// a way that says so instead of fabricating a close calendar. On a healthy
		// database this is byte-identical.
		//
		// (This comment used to add "and they win the de-dupe because `open` is
		// spread first". That is no longer the mechanism — the merge below is
		// order-independent, so a lock row's provenance survives however the two
		// lists are ordered. The qualification above is still the real fix here;
		// the merge only stops a SECOND way of losing the same data.)
		const open = db.prepare(
			"SELECT DISTINCT period FROM investor_payouts WHERE period NOT IN (SELECT period FROM period_locks WHERE period_locks.status = 'locked') ORDER BY period DESC"
		).all().map((r) => r.period);

		// ⚠️ A REOPENED PERIOD APPEARS IN BOTH LISTS, AND THE NAIVE DE-DUPE THREW
		// AWAY THE HALF THAT CARRIES THE PROVENANCE. `reopen` sets
		// period_locks.status = 'reopened' (deliberately — keeping the row is what
		// stops the per-minute sweep re-locking what an admin just opened), so the
		// row is NOT 'locked' and therefore is NOT excluded from `open`; it is also
		// in `locks`, which has no status filter. The old code spread `open` first
		// and kept the FIRST occurrence, so the winner was always the `open` entry —
		// which hardcodes finalizedAt/finalizedBy to "" and has no reopen fields at
		// all. Net effect: the reason that POST /api/periods/:period/reopen REQUIRES
		// was invisible on the only endpoint that reports the close calendar, for
		// every period that has a payout row, which is every period ever locked.
		// (reopen does not clear finalized_at either, so "closed on X, reopened on Y
		// by Z because R" is a complete history the screen simply never received.)
		//
		// MERGED, NOT PICKED, and deliberately ORDER-INDEPENDENT. Swapping the two
		// spreads would also fix today's symptom, but it leaves the same trap armed:
		// the correctness of the payload would still rest on which array happens to
		// be listed first, and the `open` branch would still be carrying blanks that
		// overwrite real values. So the `open` branch now contributes ONLY the
		// computed fields it actually knows (period/label/phase/graceEndsAt — both
		// branches compute those identically from the period key), the `locks` branch
		// contributes the stored provenance, and the defaults are applied once at the
		// end. Neither list can blank the other's data whatever order they arrive in.
		const byPeriod = new Map();
		const mergePeriod = (entry) => {
			const prev = byPeriod.get(entry.period);
			byPeriod.set(entry.period, prev ? { ...prev, ...entry } : entry);
		};
		const computedFields = (p) => ({
			period: p, periodLabel: periodLabel(p), phase: periodPhase(p),
			graceEndsAt: graceEndsAt(p, graceDays),
		});

		for (const p of open) mergePeriod(computedFields(p));
		for (const l of locks) {
			mergePeriod({
				...computedFields(l.period),
				finalizedAt: l.finalized_at, finalizedBy: l.finalized_by,
				reopenedAt: l.reopened_at, reopenedBy: l.reopened_by, reopenReason: l.reopen_reason,
			});
		}

		// ⚠️ A PAST MONTH WITH NEITHER A PAYOUT ROW NOR A LOCK WAS SIMPLY MISSING —
		// A HOLE IN THE MIDDLE OF THE CALENDAR, not merely a truncated end. Both
		// sources above are evidence-driven: `open` reads investor_payouts, which
		// reconcileInvestorPayouts() only writes for a completed past month IN WHICH
		// AN INVESTOR HAD EARNINGS, and `locks` holds only months that have already
		// closed — which, with PERIOD_FINALIZE_ENABLED off, is never any of them. So
		// a month in which the fleet earned nothing, or any month at all on a server
		// that has never enabled the close, rendered as though it did not exist. The
		// current-month backstop below fixed the same class of bug at the near end;
		// this fixes it in the middle, and the two are the same argument: this
		// endpoint is the CLOSE CALENDAR, and a calendar with a month missing is read
		// as "that month needs nothing" rather than "that month is unknown to me".
		//
		// ⚠️ THE RANGE IS ANCHORED ON THE EARLIEST MONTH ANYTHING ELSE ALREADY KNOWS
		// ABOUT, never on a date walked back from today. There is no defensible
		// horizon for the latter — any constant is either short enough to hide a real
		// month or long enough to invent hundreds of months that predate the carrier
		// — whereas the earliest payout-or-lock row is the first month the ledger
		// itself claims to describe. A month BEFORE that anchor stays absent,
		// deliberately: nothing in this database asserts it was ever a settlement
		// period.
		//
		// ⚠️ COMPOSES WITH BOTH FIXES BELOW/ABOVE RATHER THAN LEANING ON EITHER.
		// Guarded on `!byPeriod.has(p)` exactly like the current-month seed, so it can
		// never contribute a field to an entry `locks` already produced and cannot
		// blank a reopen provenance whatever order the sources arrive in; and it stops
		// STRICTLY BELOW `cur`, so the current-month backstop keeps sole ownership of
		// the open month and neither line becomes the other's dead code.
		//
		// String month arithmetic, never a Date round-trip — same rule
		// truckChargeFromMonth() states, for the same reason (a bare or UTC-midnight
		// value reads back one month early in Houston). The iteration cap is a
		// termination guarantee, not a policy: the anchor is validated below, so the
		// loop is already finite, and 600 is 50 years of months.
		//
		// ⚠️ THE ANCHOR IS RANGE-CHECKED, not merely shape-checked, and that is what
		// bounds the RESPONSE rather than just the loop. `/^\d{4}-\d{2}$/` accepts
		// "0001-01", which would anchor the walk two millennia back and emit the full
		// 600 entries — bounded, but nonsense on the one screen an admin opens to see
		// the close calendar. isPlausibleLockPeriod() is the same predicate
		// POST /api/periods/:period/finalize validates against, so the calendar cannot
		// contain a month the close routes would refuse to act on. Not reachable
		// today (both sources are server-computed) — closed by construction rather
		// than by luck.
		const MONTH_KEY = /^\d{4}-\d{2}$/;
		const known = [...byPeriod.keys()].filter(isPlausibleLockPeriod).sort();
		if (known.length && MONTH_KEY.test(cur || "")) {
			let p = known[0];
			for (let guard = 0; p < cur && guard < 600; guard++) {
				if (!byPeriod.has(p)) mergePeriod(computedFields(p));
				let y = parseInt(p.slice(0, 4), 10);
				let m = parseInt(p.slice(5, 7), 10) + 1;
				if (m > 12) { m = 1; y += 1; }
				p = `${y}-${String(m).padStart(2, "0")}`;
			}
		}

		// ⚠️ THE MONTH IN PROGRESS IS A BACKSTOP, because NEITHER source above is
		// guaranteed to contain it and in the ordinary case neither does. `open` reads
		// investor_payouts, and reconcileInvestorPayouts() only mints a row for a
		// COMPLETED PAST month; `locks` holds only months that have already closed,
		// which the current one by definition has not. A month with neither row was
		// therefore dropped from the array entirely — measured on production, 2026-08
		// was simply absent. `currentPeriod` was still reported top-level, but with no
		// matching entry there was no phase and no graceEndsAt, i.e. no answer to the
		// one question this endpoint exists to answer: WHEN DOES THE OPEN MONTH CLOSE?
		// The calendar panel's headline is "nothing to do — months close themselves"
		// plus that date, so it was making an unbacked claim about the only month
		// anybody is actually looking at.
		//
		// ⚠️ GUARDED ON ABSENCE, AND PLACED LAST, so it CANNOT CONTRIBUTE A FIELD TO AN
		// ENTRY EITHER SOURCE ALREADY PRODUCED. That is what makes it compose with the
		// merge above rather than lean on it. Merging unconditionally would be
		// harmless under today's de-dupe — computedFields() carries no provenance and
		// both branches derive those four fields identically from the period key — but
		// it would be harmless only BECAUSE the de-dupe merges. Under the keep-first
		// de-dupe this route actually shipped with, an unconditional seed placed first
		// would win outright and blank exactly the finalizedAt/reopenedAt/reopenReason
		// that the merge fix was written to stop losing, re-creating that bug through a
		// new door. `!byPeriod.has(cur)` means the seed only ever runs when there is
		// nothing to lose, so it stays correct under any de-dupe scheme. Verified on a
		// period that is simultaneously current, reopened and payout-bearing: the row
		// keeps its full "closed on X, reopened on Y by Z because R" history.
		//
		// ⚠️ phase comes from periodPhase(), NEVER a hardcoded 'accruing'. That
		// function returns "" when PERIOD_FINALIZE_ENABLED is off — nothing will ever
		// close, so naming a phase promises a settlement that is not coming — and the
		// calendar renders "" as "automatic month-close is switched off on this server"
		// and withholds the Close now button the server would answer with 503. It also
		// still reports 'finalized' for a current month closed early, which is why this
		// cannot be a literal.
		//
		// The deliberate 500 on a malformed period_locks is untouched: both queries
		// above run first and throw there, and every throw in this handler lands in the
		// catch. This adds no new success path — it only fills a hole in one.
		if (cur && !byPeriod.has(cur)) mergePeriod(computedFields(cur));

		res.json({
			enabled: PERIOD_FINALIZE_ENABLED,
			graceDays,
			currentPeriod: cur,
			// Every key is present on every row, so the client never has to tell
			// "absent" from "empty" — an un-finalized period reports "" exactly as it
			// always did, and a NULL column normalizes to the same "".
			periods: [...byPeriod.values()]
				.map((e) => ({
					...e,
					finalizedAt: e.finalizedAt || "", finalizedBy: e.finalizedBy || "",
					reopenedAt: e.reopenedAt || "", reopenedBy: e.reopenedBy || "", reopenReason: e.reopenReason || "",
				}))
				.sort((a, b) => (a.period < b.period ? 1 : -1)),
			// Work the period lock REFUSED, surfaced where an admin is already
			// deciding whether to reopen a month. The boot backfill will not write
			// truck_unit/owner_id into a finalized period, so a non-zero count here
			// means N legacy receipts are unattributed to any investor until someone
			// reopens the listed periods. Zero on every current deployment; present
			// so the condition can never accumulate silently.
			legacyExpenseBackfill: {
				ranAt: legacyExpenseBackfillHealth.ranAt,
				applied: legacyExpenseBackfillHealth.pass1 + legacyExpenseBackfillHealth.pass2,
				skippedLockedPeriod: legacyExpenseBackfillHealth.skippedLockedPeriod,
				skippedPeriods: [...legacyExpenseBackfillHealth.skippedPeriods].sort(),
				error: legacyExpenseBackfillHealth.error,
			},
		});
	} catch (err) {
		console.error("GET /api/periods error:", err.message);
		res.status(500).json({ error: "Failed to load periods" });
	}
});

// POST /api/periods/:period/finalize — close a month early. The sweep will close
// it on its own once the grace window elapses; this is for "every receipt is in,
// don't make me wait until the 8th".
app.post("/api/periods/:period/finalize", requireRole("Super Admin"), refuseCrossOrigin, async (req, res) => {
	try {
		const period = String(req.params.period || "");
		// Validate at the SOURCE. This route is the only door through which a human
		// creates a lock row, and period_locks has no CHECK on `period`, so anything
		// admitted here becomes a permanent fact that every period guard consults.
		// Two rungs, because they are different failures and deserve different words:
		// a malformed key is a client bug, an out-of-range month is a typo.
		if (!LOCKABLE_MONTH_KEY.test(period)) {
			return res.status(400).json({ error: "period must be YYYY-MM", code: "PERIOD_KEY_INVALID" });
		}
		if (!isPlausibleLockPeriod(period)) {
			return res.status(400).json({
				error: `"${period}" is not a settlement month — months run 01-12 and years ${LOCK_PERIOD_MIN_YEAR}-${LOCK_PERIOD_MAX_YEAR}.`,
				code: "PERIOD_OUT_OF_RANGE",
			});
		}
		if (!PERIOD_FINALIZE_ENABLED) {
			return res.status(503).json({ error: "Period close is not enabled on this server.", code: "FEATURE_DISABLED" });
		}
		// A month still in progress has no final number to freeze.
		if (period >= currentMonthKeyCT()) {
			return res.status(409).json({
				error: `${periodLabel(period)} is still in progress — it can't be finalized until the month ends.`,
				code: "PERIOD_ACCRUING",
			});
		}
		const existing = periodLockStmt().get(period);
		if (existing && existing.status === "locked") {
			return res.status(409).json({ error: `${periodLabel(period)} is already finalized.`, code: "ALREADY_FINALIZED" });
		}

		const result = await finalizePeriod(period, req.session.user.username || "admin");
		logAudit(req, "period_finalize", "period", period,
			`Finalized ${period} early (${result.stamped} payout row(s) frozen)`);
		res.json({ success: true, period, ...result });
	} catch (err) {
		console.error("POST /api/periods/:period/finalize error:", err.message);
		res.status(500).json({ error: "Failed to finalize period" });
	}
});

// POST /api/periods/:period/reopen — walk a finalized month back open. Requires a
// reason, exactly like reopening a settled payout: this un-freezes figures that
// may already be on a delivered statement.
app.post("/api/periods/:period/reopen", requireRole("Super Admin"), refuseCrossOrigin, (req, res) => {
	try {
		const period = String(req.params.period || "");
		if (!LOCKABLE_MONTH_KEY.test(period)) {
			return res.status(400).json({ error: "period must be YYYY-MM", code: "PERIOD_KEY_INVALID" });
		}

		const lock = db.prepare("SELECT * FROM period_locks WHERE period = ?").get(period);
		// ⚠️ THE RANGE BOUND IS NOT APPLIED WHEN A LOCK ROW EXISTS, DELIBERATELY.
		// Reopen is the REMEDY, and the finalize route was unbounded until this
		// commit — so a database may already hold a `1900-05` row. Refusing to
		// reopen it would strand the junk lock permanently: there is no other API
		// that clears one, and the VPS has no sqlite3 binary, so the only way back
		// would be hand-editing app.db. Validating a key we are about to DELETE the
		// authority of is backwards; the bound belongs on creation, which is where
		// it now is. Ordering matters — the lookup happens first, and the bound is
		// only consulted when there is nothing to remedy. (Parameterized query, so
		// an unvalidated string is safe to look up.)
		if (!lock && !isPlausibleLockPeriod(period)) {
			return res.status(400).json({
				error: `"${period}" is not a settlement month — months run 01-12 and years ${LOCK_PERIOD_MIN_YEAR}-${LOCK_PERIOD_MAX_YEAR}.`,
				code: "PERIOD_OUT_OF_RANGE",
			});
		}
		if (!lock || lock.status !== "locked") {
			return res.status(404).json({ error: `${periodLabel(period)} is not finalized.`, code: "NOT_FINALIZED" });
		}
		const reason = (req.body?.reason || "").toString().trim().slice(0, 500);
		if (!reason) {
			return res.status(400).json({ error: "A reason is required to reopen a finalized period." });
		}

		const nowIso = new Date().toISOString();
		const actor = req.session.user.username || "";

		// Count what reopening will NOT undo, before we change anything.
		// Receipts that were redirected out of this period while it was closed have
		// already been reported in a later month; pulling them back would move TWO
		// months, one of which may itself be settled. So they stay put — but the
		// admin is told, rather than discovering it later.
		const diverted = db.prepare(
			"SELECT COUNT(*) AS c, COALESCE(SUM(amount),0) AS t FROM expenses WHERE COALESCE(posted_period,'') != '' AND substr(COALESCE(NULLIF(date,''), created_at), 1, 7) = ?"
		).get(period);

		const reopenTx = db.transaction(() => {
			// KEEP the row, flip its status. It is the sweep's idempotency marker in
			// BOTH states — deleting it would let the per-minute tick re-lock this
			// period within 60 seconds of the admin reopening it.
			db.prepare(
				"UPDATE period_locks SET status = 'reopened', reopened_at = ?, reopened_by = ?, reopen_reason = ? WHERE period = ?"
			).run(nowIso, actor, reason, period);

			// Re-link ONLY still-owed rows to live earnings. A processing/paid row
			// keeps its snapshot: its money moved against a document that was already
			// issued, and unfinalizing must not retroactively rewrite that statement.
			return db.prepare(
				"UPDATE investor_payouts SET finalized_at = '', finalized_amount = NULL, finalized_breakdown = '' WHERE period = ? AND status = 'owed'"
			).run(period).changes;
		});
		const relinked = reopenTx();

		logAudit(req, "period_reopen", "period", period,
			`REOPENED ${period} (${relinked} owed row(s) re-linked to live earnings; ${diverted.c} redirected receipt(s) left in place): ${reason}`);

		res.json({
			success: true,
			period,
			relinkedOwedRows: relinked,
			// Surfaced so "why is March still short?" has an answer on screen.
			divertedReceipts: diverted.c,
			divertedAmount: diverted.t,
			note: diverted.c
				? `${diverted.c} receipt(s) dated in ${periodLabel(period)} ($${Number(diverted.t).toFixed(2)}) were booked to a later month while it was closed. They stay there — reversing them would move two months.`
				: "",
		});
	} catch (err) {
		console.error("POST /api/periods/:period/reopen error:", err.message);
		res.status(500).json({ error: "Failed to reopen period" });
	}
});

// ============================================================
// GET /api/admin/period-lock-issues — the month-end close queue
// ============================================================
// The sixth detector behind /admin/data-issues. Client ask, verbatim:
// "everything that is concerning the lock month or date it should go to that page
// where we show all the concerns."
//
// TWO HALVES, and each answers a question the other cannot.
//
//   HISTORY — writes that were REFUSED because a month was closed. Until the
//   refusal-audit work this batch carries, most of those guards returned a 409
//   and wrote nothing at all, so there was no record that anyone had tried. Now
//   every one lands in audit_trail carrying a `[PERIOD_…]` code, and that marker
//   — not a list of action names — is what this reads. See
//   parsePeriodRefusalDetail() for why.
//
//   CURRENT STATE — what is FROZEN right now. A refusal only exists if somebody
//   happened to try; an invoice sitting in a finalized month is stuck whether or
//   not anyone has bumped into it yet. Six of the twenty-nine live invoices on
//   this data can never be marked Paid without reopening a month, and nothing in
//   the app was saying so.
//
// ⚠️ EXPENSES REDIRECTED VIA `posted_period` ARE DELIBERATELY NOT LISTED. Owner's
// call: that redirect is the system working as designed, both admin surfaces
// already say so at the moment it happens, and with every month through 2026-07
// locked it fires on essentially every backdated receipt. Listing them would bury
// the rows above under routine traffic — the failure mode that taught everyone to
// ignore the rate-con reconciler's daily mail.
//
// Structurally read-only: SELECTs only, no UPDATE, no render, no audit row of its
// own. No cross-site guard, for the same reason GET /api/admin/onboarding-doc-failures
// has none — cost, not the verb, is what decides, and there is no billed API call
// and no side effect here for a forged navigation to spend.
//
// ⚠️ BUT IT IS NOT "A FEW DOZEN INDEXED LOOKUPS", WHICH IS WHAT THIS COMMENT USED
// TO CLAIM AND WAS THE WHOLE JUSTIFICATION FOR CARRYING NO LIMITER. Only the
// invoice half is indexed (a 29-row table, then one primary-key probe of
// period_locks per month of span). The HISTORY half is three FULL passes over
// audit_trail on every call, measured with EXPLAIN QUERY PLAN on a copy of
// production:
//   SELECT COUNT(*) FROM audit_trail                  -> SCAN … COVERING INDEX
//   the MARKED aggregate (MIN/MAX + COUNT)            -> SCAN audit_trail
//   the MARKED list (ORDER BY timestamp DESC LIMIT n) -> SCAN … USING INDEX
// A leading-wildcard LIKE is non-sargable, so no index on `details` would help
// even if one existed, and the COUNT(*) is unfiltered by construction (it is the
// "is the table empty?" signal that makes "no refusals" readable). All three
// together measured ~1.0 ms at 1,444 rows — but the cost is LINEAR in a table
// that grows without bound, because every `[PERIOD_` row is exempt from
// purgeOldAuditRefusals() forever and audit_trail has no other prune. And
// better-sqlite3 is synchronous: this is event-loop time, charged to the driver
// app, the dashboard and the Linxup webhook, not just to the caller.
//
// So the no-limiter conclusion does not follow from the corrected premise.
// periodIssueLimiter below is the backstop — sized for a page, not for a script.
//
// Cap on EACH list. Both counts beside them are computed over the full set, so a
// truncated list never lets a reader count rendered rows and disbelieve the
// headline.
const PERIOD_ISSUE_MAX_ROWS = 200;

// Sibling of fuelEventsLimiter, and it earns its mount for that limiter's stated
// reason — "each call re-scans <table> synchronously" — rather than for a billed
// third-party call. Looser than fuelEventsLimiter (20) because the unit of work is
// three ~1 ms table scans rather than a telemetry sweep, and because a Super Admin
// bouncing between /admin/data-issues and a fix legitimately reloads this several
// times a minute: 60 in 15 minutes is one page-load every 15 seconds, sustained.
//
// ⚠️ PER-USER, NOT PER-IP, the reasoning poiLimiter states: the whole office
// behind one NAT would otherwise share one bucket, throttling the ordinary
// callers. Falls back to the IP for a request with no session, which requireRole
// has already refused by then.
//
// ⚠️ MOUNTED AFTER requireRole, same ordering as fuelEventsLimiter and
// fuelGallonsLimiter: with the limiter first an unauthenticated caller spends the
// whole bucket on 403s and locks out the legitimate user behind that key.
const periodIssueLimiter = rateLimit({
	windowMs: 15 * 60 * 1000,
	max: 60,
	keyGenerator: (req) => {
		const id = req.session?.user?.id;
		return id ? `u:${id}` : `ip:${ipKeyGenerator(req.ip)}`;
	},
	message: { error: "Too many month-end lock checks. Try again in a few minutes." },
	standardHeaders: true,
});

app.get("/api/admin/period-lock-issues", requireRole("Super Admin"), periodIssueLimiter, (req, res) => {
	try {
		// ------------------------------------------------------------------
		// Context — what this queue is and is NOT entitled to call "all clear"
		// ------------------------------------------------------------------
		// ⚠️ AN EMPTY RESULT HERE IS AMBIGUOUS IN EXACTLY THE WAY GET /api/fuel/verify's
		// zero is, so the client needs the context to tell the two apart. With
		// period_locks unreadable nothing can be judged at all; with no month ever
		// locked nothing CAN be frozen, so "no concerns" is trivially true and says
		// nothing about whether month-end close is working. Both are reported as
		// facts and lib/dataIssues.js decides what may be claimed from them.
		let locksReadable = periodLocksReadable();
		let lockedPeriods = [];
		if (locksReadable) {
			try {
				lockedPeriods = db.prepare("SELECT period FROM period_locks WHERE status = 'locked' ORDER BY period")
					.all().map((r) => String(r.period));
			} catch (err) {
				// The probe passed and the real read did not. Report the stricter of the
				// two answers: a guard is failing closed somewhere and this cannot say where.
				locksReadable = false;
				console.error("period-lock-issues: period_locks unreadable:", err.message);
			}
		}

		// ------------------------------------------------------------------
		// HISTORY — refusals, keyed on the marker
		// ------------------------------------------------------------------
		let auditReadable = true;
		let auditRows = 0;
		let refusalCount = 0, refusalOldest = null, refusalNewest = null;
		let refusalRows = [];
		try {
			auditRows = db.prepare("SELECT COUNT(*) AS n FROM audit_trail").get().n || 0;
			// ⚠️ THE IDENTICAL PREDICATE purgeOldAuditRefusals() USES, character for
			// character including the ESCAPE clause. That is what makes the queue and
			// the retention job agree by construction: every row the purge spares is a
			// row this can show, and a row it would delete is one this never claims to
			// have. (SQLite's LIKE is case-insensitive for ASCII, so `[period_` matches
			// here as well — which is precisely why scrubPurgeMarker() folds case when
			// it neutralises caller-supplied text.)
			const MARKED = "details LIKE '%[PERIOD\\_%' ESCAPE '\\'";
			const agg = db.prepare(
				`SELECT COUNT(*) AS n, MIN(timestamp) AS oldest, MAX(timestamp) AS newest FROM audit_trail WHERE ${MARKED}`
			).get();
			refusalCount = agg.n || 0;
			refusalOldest = agg.oldest || null;
			refusalNewest = agg.newest || null;
			refusalRows = db.prepare(
				`SELECT id, timestamp, username, role, action, entity, entity_id, details
				   FROM audit_trail WHERE ${MARKED}
				  ORDER BY timestamp DESC, id DESC LIMIT ?`
			).all(PERIOD_ISSUE_MAX_ROWS).map((r) => {
				const p = parsePeriodRefusalDetail(r.details);
				return {
					id: r.id,
					at: r.timestamp,
					// ⚠️ "account", NEVER "who". `super_admin` is a SHARED login used by
					// several people, so this column identifies a login and a session and
					// can never identify a person. The field is named for what it holds.
					account: r.username || "",
					role: r.role || "",
					action: r.action || "",
					entity: r.entity || "",
					entityId: String(r.entity_id || ""),
					code: p.code,
					periods: p.periods,
					periodLabels: p.periods.map(periodLabel),
					unnamedPeriods: p.unnamedPeriods,
					attempted: p.attempted,
					note: p.note,
					suppressed: p.suppressed,
					// The stored row, unedited. Everything above is a convenience read off
					// it; this is the record itself, and it is what a dispute is answered
					// from.
					details: String(r.details || ""),
				};
			});
		} catch (err) {
			auditReadable = false;
			console.error("period-lock-issues: audit_trail unreadable:", err.message);
		}

		// ------------------------------------------------------------------
		// CURRENT STATE — invoices frozen right now
		// ------------------------------------------------------------------
		// ⚠️ `COALESCE(deleted_at,'') = ''`, WHICH IS NOT THE LIST ENDPOINT'S FILTER.
		// GET /api/invoices uses a bare `deleted_at = ''`, which drops a NULL. The
		// question here is "which invoices would the adjust / pay routes refuse", and
		// those routes fetch the row and test `if (invoice.deleted_at)` — truthy, so a
		// NULL is LIVE to them. Copying the list endpoint would under-report exactly
		// the rows whose guard still fires.
		const invoiceRows = db.prepare(
			`SELECT id, invoice_number, driver, week_start, week_end, status,
			        COALESCE(total_earnings, 0) AS total_earnings, COALESCE(adjustment, 0) AS adjustment,
			        COALESCE(paid_at, '') AS paid_at, COALESCE(is_manual, 0) AS is_manual
			   FROM invoices WHERE COALESCE(deleted_at, '') = ''`
		).all();

		const frozen = [];
		let neverPayable = 0, unresolvedDates = 0;
		let frozenAmount = 0, neverPayableAmount = 0;

		// ⚠️ WITH period_locks UNREADABLE, EVERY LIVE INVOICE IS FROZEN AND NONE OF
		// THEM IS LISTED. invoiceMonthLockBlockers() fails closed on that table, so
		// enumerating would print all twenty-nine rows as though each had its own
		// month-end problem, when there is one root cause and it is not a month at
		// all. `locksReadable:false` plus `liveInvoices` is the honest shape; the page
		// renders that as a fault to fix rather than a queue to work through, and
		// queueEstablished() refuses to call any of it clear.
		if (locksReadable) {
			for (const inv of invoiceRows) {
				// The GUARD ITSELF, never a re-derived predicate. This queue exists to say
				// what those two routes will refuse, so asking anything else would let the
				// page and the server disagree — and the span walk, the range check and
				// the unresolved-date rung are the parts most easily got wrong twice.
				const lock = invoiceMonthLockBlockers(inv);
				if (lock.unreadable || !lock.blockers.length) continue;

				const periods = [...new Set(lock.blockers.flatMap((b) => b.periods))].filter(Boolean).sort();
				const unresolved = lock.blockers.some((b) => b.periods.some((p) => !p));
				// Same ranking periodBlockedResponse() applies: a named month outranks an
				// unresolved date, because "this would restate June" is the answer an
				// operator can act on.
				const cause = periods.length ? "PERIOD_FINALIZED" : (unresolved ? "PERIOD_UNRESOLVED" : "PERIOD_FINALIZED");

				// ⚠️ CAN THIS INVOICE EVER REACH PAID? approve / submit / processing carry
				// NO month-end guard — only the `paid` transition does — so a Draft in a
				// finalized month walks all the way to Approved and then stops for good.
				// Paid and Rejected are terminal and are waiting on nothing. This is the
				// number an admin most needs, because unlike an un-adjustable invoice it
				// has no in-app remedy at all short of reopening the month.
				const stuckBeforePaid = ["Draft", "Submitted", "Approved", "Processing"].includes(String(inv.status || ""));
				// ⚠️ AN EXPLICIT TERMINAL LIST, NOT `!stuckBeforePaid`, so an
				// UNRECOGNISED status is neither. The two lists answer different
				// questions and an unknown value has to fall on the cautious side of
				// each: it is not "waiting to be paid" (so it is not neverPayable), and
				// it is not "finished, nothing waiting on it" either — so it stays in
				// noRemedy below rather than being quietly dropped from the headline by
				// a negation. Today the column only ever holds these six values.
				const settled = /^(paid|rejected)$/i.test(String(inv.status || ""));
				const amount = Number(inv.total_earnings || 0) + Number(inv.adjustment || 0);

				frozenAmount += amount;
				if (cause === "PERIOD_UNRESOLVED") unresolvedDates++;
				if (stuckBeforePaid) { neverPayable++; neverPayableAmount += amount; }

				frozen.push({
					id: inv.id,
					invoiceNumber: inv.invoice_number || "",
					driver: inv.driver || "",
					weekStart: inv.week_start || "",
					weekEnd: inv.week_end || "",
					status: inv.status || "",
					isManual: !!inv.is_manual,
					amount: Math.round(amount * 100) / 100,
					paidAt: inv.paid_at || "",
					cause,
					periods,
					periodLabels: periods.map(periodLabel),
					// Both write guards are already refused, so these are constants rather
					// than predictions — `adjust` has no rung this row could pass.
					adjustable: false,
					neverPayable: stuckBeforePaid,
					// Server-told, so the client's sentence and the headline count below
					// cannot drift into contradicting each other on one screen.
					settled,
					detail: lock.blockers.map((b) => b.detail).join("; "),
					// The unresolved-date branch carries its own remedy, because the
					// month-end one names no period and points at a route that cannot edit a
					// week date. Same fallback the three invoice routes use.
					remedy: lock.remedy || INVOICE_LOCK_REMEDY,
				});
			}
		}

		// Worst first: a row with no in-app remedy leads, then the newest weeks.
		frozen.sort((a, b) =>
			(b.neverPayable ? 1 : 0) - (a.neverPayable ? 1 : 0)
			|| String(b.weekStart).localeCompare(String(a.weekStart))
			|| b.id - a.id);

		res.json({
			// --- context -------------------------------------------------
			closeEnabled: PERIOD_FINALIZE_ENABLED,
			locksReadable,
			lockedPeriods,
			lockedCount: lockedPeriods.length,
			currentPeriod: currentMonthKeyCT(),
			auditReadable,
			// Total rows in audit_trail, so "no refusals" can be told apart from "the
			// table is empty" without a second call.
			auditRows,

			// --- history -------------------------------------------------
			refusals: refusalRows,
			// ⚠️ COUNTED OVER THE FULL MATCH, NOT OVER THE RENDERED LIST, so a reader
			// can never count rows and disbelieve the headline. Same rule the duplicate
			// summary follows with FUEL_DUPLICATE_MAX_GROUPS / `truncated` / `shown`.
			refusalCount,
			refusalShown: refusalRows.length,
			refusalTruncated: refusalCount > refusalRows.length,
			// Both computed over the FULL match too — the oldest row is what says how
			// far back this history actually reaches, which a truncated list cannot.
			refusalOldest,
			refusalNewest,

			// --- current state -------------------------------------------
			invoices: frozen.slice(0, PERIOD_ISSUE_MAX_ROWS),
			invoiceCount: frozen.length,
			invoiceShown: Math.min(frozen.length, PERIOD_ISSUE_MAX_ROWS),
			invoiceTruncated: frozen.length > PERIOD_ISSUE_MAX_ROWS,
			liveInvoices: invoiceRows.length,
			invoiceSummary: {
				live: invoiceRows.length,
				frozen: frozen.length,
				neverPayable,
				unresolvedDates,
				// ⚠️ COMPUTED HERE, NOT AS `neverPayable + unresolvedDates` ON THE CLIENT.
				// The two overlap — a Draft carrying an unparseable week date is both —
				// and adding them would count that row twice in the headline the whole
				// queue leads with. Counted over the FULL set for the same reason the
				// other totals are.
				//
				// ⚠️ THE UNRESOLVED ARM CONSULTS STATUS, because `noRemedy` feeds the
				// bar's `actionable` — "how much work is there" — and a Paid invoice
				// with an unparseable week date is not work: nobody is waiting on it,
				// exactly like the un-adjustable-but-settled rows this queue already
				// files under `closed`. Bare `|| cause === PERIOD_UNRESOLVED` counted it,
				// while frozenInvoiceImpact() told the reader it "has to be regenerated"
				// — one screen, two answers. `!settled`, NOT `neverPayable`: an
				// unrecognised status keeps its place in the count AND keeps the dead-end
				// sentence, so the two agree in that case too. Zero such rows exist today
				// (measured on a copy: 25 frozen, 0 unresolved) — this is the shape for
				// the day one appears, like the COALESCE decision on the SELECT above.
				noRemedy: frozen.filter((f) => f.neverPayable || (f.cause === "PERIOD_UNRESOLVED" && !f.settled)).length,
				frozenAmount: Math.round(frozenAmount * 100) / 100,
				neverPayableAmount: Math.round(neverPayableAmount * 100) / 100,
			},
		});
	} catch (err) {
		console.error("GET /api/admin/period-lock-issues error:", err.message);
		res.status(500).json({ error: "Failed to load month-end lock issues" });
	}
});

// Close ONE period: take the lock, then freeze each investor's figure for it.
//
// Split deliberately into two steps that fail differently:
//
//   1. LOCK   — pure clock arithmetic + one INSERT. No Sheets, no network,
//               effectively cannot fail. This is the step that matters: once the
//               lock exists, the reconcile stops refreshing amounts and new
//               receipts dated into this month get redirected. The period stops
//               moving.
//   2. STAMP  — needs the Job Tracking sheet to recompute earnings. If Sheets is
//               down this throws AFTER the lock is already in place, so the month
//               is still frozen at its last known figure; only the statement
//               snapshot is missing, and the statement falls back to the live
//               recompute path (which carries its own drift disclosure). The
//               sweep retries the stamp on the next tick.
//
// Fails in the safe direction: never "half open", at worst "closed but not yet
// documented". Idempotent — re-running only touches rows with no stamp yet.
async function finalizePeriods(periods, actor) {
	const nowIso = new Date().toISOString();
	// EVERY lock write that is not the baseline seed funnels through here — the
	// finalize route AND the per-minute sweep — so this is the one place that can
	// state "nothing implausible reaches period_locks" without depending on which
	// caller it was. The route validates too and returns a proper 400; this is the
	// backstop for the callers that have no response to fail, and for the next one.
	//
	// The sweep's own candidates are already filtered (periodsDueForClose), so in
	// practice this fires only for a period reached some other way — which is
	// abnormal enough to say out loud rather than drop silently.
	const proposed = [...new Set(periods)].filter(Boolean);
	const list = proposed.filter(isPlausibleLockPeriod);
	const refused = proposed.filter((p) => !isPlausibleLockPeriod(p));
	if (refused.length) {
		console.warn(`[period-close] REFUSED to lock ${refused.length} implausible period key(s): ${refused.join(", ")} — not a settlement month, nothing written to period_locks`);
	}
	if (!list.length) return { stamped: 0, investors: 0, periods: [] };

	const takeLock = db.prepare(
		`INSERT INTO period_locks (period, status, finalized_at, finalized_by) VALUES (?, 'locked', ?, ?)
		 ON CONFLICT(period) DO UPDATE SET status = 'locked', finalized_at = excluded.finalized_at, finalized_by = excluded.finalized_by`
	);
	db.transaction(() => { for (const p of list) takeLock.run(p, nowIso, actor || "system"); })();

	// Owners with at least one unstamped row in any of these periods. Guarded on
	// finalized_at so a retry after a partial run never re-times what succeeded.
	const ph = list.map(() => "?").join(",");
	const owners = db.prepare(
		`SELECT DISTINCT owner_id FROM investor_payouts WHERE period IN (${ph}) AND COALESCE(finalized_at,'') = ''`
	).all(...list).map((r) => r.owner_id);
	if (!owners.length) return { stamped: 0, investors: 0, periods: list };

	await getJobTrackingCached();
	const globalConfig = {};
	db.prepare("SELECT key, value FROM investor_config WHERE owner_id = 0").all().forEach((r) => (globalConfig[r.key] = r.value));
	const ctx = {
		sessionUser: { role: "Super Admin", username: actor || "period-close" },
		carrierDB: getCarrierDBFromSQLite(),
		globalConfig,
	};

	// Freeze a still-owed row at the LIVE recompute, not at whatever `amount`
	// happens to hold.
	//
	// This is the subtle one. `amount` is only refreshed when someone loads the
	// payouts screen, so if nobody looked between day 3 and day 7 it is stale —
	// and because the lock is already taken above, the reconcile inside can no
	// longer refresh it. Stamping `amount` would therefore freeze a figure that
	// predates the very receipts the grace window existed to collect.
	// `recomputedAmount` is computed from live earnings on every reconcile
	// regardless of lock state, so it is the true closing figure.
	//
	// A row already processing/paid keeps its own `amount` untouched — that money
	// moved against a settled figure, and the long-standing invariant is that the
	// reconcile never rewrites a settled amount.
	const stampOwed = db.prepare(
		`UPDATE investor_payouts SET amount = ?, finalized_at = ?, finalized_amount = ?, finalized_breakdown = ?
		  WHERE owner_id = ? AND period = ? AND status = 'owed' AND COALESCE(finalized_at,'') = ''`
	);
	const stampSettled = db.prepare(
		`UPDATE investor_payouts SET finalized_at = ?, finalized_amount = amount, finalized_breakdown = ?
		  WHERE owner_id = ? AND period = ? AND status != 'owed' AND COALESCE(finalized_at,'') = ''`
	);

	let stamped = 0;
	for (const ownerId of owners) {
		// ONE reconcile per owner covers every period at once — it already returns
		// the owner's whole ledger. Reconciling per (owner, period) would re-run the
		// full monthly earnings computation N times for no extra information, which
		// matters on first enable when the baseline leaves a backlog to stamp.
		const { payouts } = await reconcileInvestorPayouts(ownerId, ctx);
		for (const period of list) {
			const p = payouts.find((x) => x.period === period);
			if (!p) continue;
			// ⚠️ THE CARRY-FORWARD TERMS ARE PART OF THE SNAPSHOT, and leaving them
			// out is what made a finalized statement print arithmetic that did not
			// foot. The PDF composed a FROZEN top half (`finalized_breakdown`) with a
			// LIVE `lossCarriedIn` recomputed months later — and the carry chain moves
			// whenever any earlier month's recompute moves, so a June statement showed
			// clean frozen figures (Net Profit $17,580.88 → share $8,790.00) with a
			// live "− Earlier loss applied −$1,563.00" line under it that no longer
			// corresponded to anything on the page. Freeze both halves together or the
			// document is internally inconsistent by construction.
			//
			// Only ever attached to a real breakdown object: when the month has aged
			// out of the live earnings window `p.breakdown` is null, and the statement
			// deliberately prints "composition no longer available to re-derive"
			// rather than a waterfall of blanks. A bare {lossCarriedIn, lossDeferred}
			// would defeat that null check and render an all-zero waterfall.
			const breakdown = JSON.stringify(
				p.breakdown
					? { ...p.breakdown, lossCarriedIn: p.lossCarriedIn, lossDeferred: p.lossDeferred }
					: null
			);
			const live = p.recomputedAmount != null ? p.recomputedAmount : p.amount;
			const n = stampOwed.run(live, nowIso, live, breakdown, ownerId, period).changes
				+ stampSettled.run(nowIso, breakdown, ownerId, period).changes;
			stamped += n;
			// Closing a month is the last moment its figure can move, and stampOwed
			// writes `live` — which is the RECOMPUTED amount, not necessarily the one
			// stored. So the close itself can shift the number, and this is the only
			// record that it did. Guarded on n so a period that stamped nothing (the
			// idempotent re-run case) logs nothing.
			if (n > 0) {
				recordPayoutChange({
					payoutId: p.id,
					ownerId,
					period,
					kind: "finalize",
					oldAmount: p.amount,
					newAmount: live,
					detail: `period closed and frozen${actor ? ` by ${actor}` : ""}`,
					breakdown: p.breakdown || null,
					actor: actor || "period-close",
				});
			}
		}
	}
	return { stamped, investors: owners.length, periods: list };
}

// Single-period convenience for the manual "close it now" route. A function
// declaration, not a const arrow: the route above calls it, and hoisting keeps
// that safe regardless of where either ends up in this file.
function finalizePeriod(period, actor) {
	return finalizePeriods([period], actor);
}

// ============================================================
// Automatic month-end close
// ============================================================
// Ported from the weekly invoice batch (maybeRunWeeklyInvoiceBatch) — same
// shape, same failure discipline: a per-minute tick, a marker keyed on the
// period identifier, a boot catch-up, and a baseline seed so enabling the
// feature never retroactively closes history.
//
// The marker here is the period_locks row itself, and it counts in BOTH states:
// a period an admin deliberately REOPENED must not be re-locked by the next tick
// 60 seconds later. Reopen is a human decision; the sweep does not overrule it.
//
// Why a scheduled sweep rather than closing lazily on the next page load: a lazy
// close freezes whatever value happens to be there when someone first opens the
// screen — so a receipt logged on day 9 lands inside a "final" number, and two
// investors' months finalize at different values depending on who logged in
// first. Non-deterministic money. This codebase already rejected read-path
// period close for payroll; that is why invoice_autogen_runs exists.
const PERIOD_CLOSE_MAX_ATTEMPTS = 5;
const PERIOD_CLOSE_RETRY_MS = 15 * 60 * 1000;
let periodCloseRunning = false;
let periodCloseLastAttempt = 0;
let periodCloseFailStreak = 0;

// Every completed month that is past its grace window and has no lock row yet.
// Bounded to periods we actually have payout rows for, so this can't wander back
// through years of empty calendar.
function periodsDueForClose() {
	const graceDays = settlementGraceDays();
	const cur = currentMonthKeyCT();
	return db.prepare(
		"SELECT DISTINCT period FROM investor_payouts WHERE period NOT IN (SELECT period FROM period_locks) ORDER BY period ASC"
	).all()
		.map((r) => r.period)
		// isPlausibleLockPeriod is the same predicate the finalize route enforces.
		// Applied HERE as well as inside finalizePeriods so this leg of the sweep
		// never proposes a junk key — otherwise a single unlockable row in
		// investor_payouts stays "due" forever and warns once a minute, for good.
		// ⚠️ This covers the `due` leg ONLY. The sweep's other input — the
		// `unstamped` retry, which reads period_locks directly — carries its own
		// copy of this filter for the same reason; see maybeCloseFinishedPeriods().
		// investor_payouts.period is NOT independently validated: it is built from a
		// Date cursor whose start comes from moneySheetDate() over the sheet, so one
		// mistyped year in `Assigned Date` seeds real-shaped but absurd months.
		.filter((p) => p < cur && isPastGrace(p, graceDays) && isPlausibleLockPeriod(p));
}

async function maybeCloseFinishedPeriods() {
	if (!PERIOD_FINALIZE_ENABLED || periodCloseRunning) return;

	// Throttle after a failure so a persistent Sheets outage doesn't retry every
	// minute; a clean pass leaves nothing due, so the normal path costs one cheap
	// SELECT per tick.
	if (periodCloseFailStreak > 0 && Date.now() - periodCloseLastAttempt < PERIOD_CLOSE_RETRY_MS) return;

	// EVERYTHING that can throw lives inside the try, including the two SELECTs
	// that decide what to work on. They used to sit above it, and both read
	// `period_locks` — periodsDueForClose() through a NOT IN subquery, the
	// unstamped retry through a JOIN — so the single failure this whole apparatus
	// exists to survive (an unreadable lock table) escaped as a rejected promise
	// before the streak counter, the log line, or the ACTION-NEEDED notification
	// could fire. Verified by QA: a broken server ran past two ticks in total
	// silence. A scheduled job that cannot report its own failure is worse than no
	// job, because the absence of an alert reads as success.
	//
	// `stage` is carried so the failure copy can tell the truth about what state
	// the books are in. The two are genuinely different situations and the old
	// wording only described one of them.
	periodCloseRunning = true;
	periodCloseLastAttempt = Date.now();
	let stage = "scan";
	let due = [];
	try {
		due = periodsDueForClose();
		// Also retry the stamp for periods locked earlier whose snapshot never landed
		// (step 2 failed on a previous pass — see finalizePeriod).
		//
		// ⚠️ FILTERED TOO, and this leg is the one that actually needs it. Unlike
		// `due` (which reads investor_payouts), this reads period_locks itself — so
		// it surfaces a junk row that a PRE-VALIDATION build already wrote, which is
		// exactly the database state the reopen carve-out exists for. Unfiltered, such
		// a row makes `work` permanently non-empty, finalizePeriods refuses it and
		// stamps nothing, nothing changes, and the same row comes back on the next
		// tick — a per-minute WARN loop, forever, burying every real close failure.
		// The operator's remedy is POST /api/periods/:period/reopen, which flips the
		// status and drops the row out of both this JOIN and periodsDueForClose's
		// NOT IN.
		const unstamped = db.prepare(
			`SELECT DISTINCT p.period FROM investor_payouts p
			   JOIN period_locks l ON l.period = p.period AND l.status = 'locked'
			  WHERE COALESCE(p.finalized_at,'') = '' ORDER BY p.period ASC`
		).all().map((r) => r.period).filter(isPlausibleLockPeriod);

		const work = [...new Set([...due, ...unstamped])];
		if (!work.length) { periodCloseFailStreak = 0; return; }

		stage = "finalize";
		// One batched pass: locks are taken for every due period up front, then
		// each investor is reconciled ONCE and stamped across all of them.
		const result = await finalizePeriods(work, "system");
		// ⚠️ Report what was CLOSED (result.periods), not what was PROPOSED (work).
		// finalizePeriods refuses implausible keys, so logging `work` would announce a
		// close that never happened — the log line is the only place anyone looks when
		// asking "did the month close?", and it must not be able to lie.
		console.log(`[period-close] finalized ${result.periods.join(", ") || "(nothing)"} — ${result.stamped} payout row(s) frozen across ${result.investors} investor(s)`);

		// Notify only for periods that actually crossed their window on this pass;
		// `unstamped` retries of an already-announced month must not re-announce it.
		for (const period of due) {
			try {
				insertDispatchNotification.run(
					"period-close",
					`${periodLabel(period)} is closed`,
					`Final settlement complete. Investor payouts for ${periodLabel(period)} are frozen at their final figure — statements are now available and payouts can be marked paid. Receipts dated in ${periodLabel(period)} that arrive from now on will be booked to the current open month.`,
					JSON.stringify({ period, stamped: result.stamped, investors: result.investors }),
				);
			} catch {}
		}
		periodCloseFailStreak = 0;
	} catch (e) {
		// Two failure shapes, and they leave the books in different places:
		//   stage 'finalize' — locks are already in place for anything we got to, so
		//     the figures are frozen and only the snapshot is outstanding;
		//   stage 'scan' — we never got as far as taking a lock, so NOTHING closed
		//     this pass and a month past its window is still accruing.
		// The second is the more urgent of the two and used to be reported as the
		// first, which would send someone looking for a snapshot rather than for the
		// reason no month is closing at all.
		periodCloseFailStreak++;
		console.error(`[period-close] close failed at ${stage} (streak ${periodCloseFailStreak}):`, e.message);
		if (periodCloseFailStreak === PERIOD_CLOSE_MAX_ATTEMPTS) {
			try {
				insertDispatchNotification.run(
					"period-close",
					"ACTION NEEDED — month close incomplete",
					stage === "scan"
						? `The month-close sweep has failed ${PERIOD_CLOSE_MAX_ATTEMPTS} times before it could take a single lock (${e.message}). NO period has been closed on those passes, so any month past its ${settlementGraceDays()}-day window is still open and its figure can still move. This usually means period_locks is unreadable — check the database, not the Sheets connection.`
						: `Finalizing a period has failed ${PERIOD_CLOSE_MAX_ATTEMPTS} times (${e.message}). Affected months ARE locked, so their figures are frozen and no new receipt can move them — but the statement snapshot is missing, so statements fall back to a live recompute with a drift note. Check the Sheets connection.`,
					JSON.stringify({ attempts: PERIOD_CLOSE_MAX_ATTEMPTS, stage, error: e.message }),
				);
			} catch {}
		}
	} finally {
		periodCloseRunning = false;
	}
}

if (PERIOD_FINALIZE_ENABLED) {
	// First-ever enable: lock every period whose window has ALREADY passed, in one
	// pass, without recomputing anything. Rationale:
	//   - months already processing/paid are de facto final; formalising it is
	//     what finally stops a backdated receipt polluting them, and the freeze
	//     guard only affects 'owed' rows so nothing settled is touched;
	//   - months long past their window get locked at their current figure;
	//   - a month still legitimately inside its window is EXCLUDED and closes
	//     naturally when the sweep next runs.
	// finalized_at is left empty on the payout rows, so statements for these fall
	// through to the existing live-recompute path with its drift disclosure — no
	// snapshot is invented for a month nobody watched close.
	try {
		const seeded = db.prepare("SELECT COUNT(*) AS c FROM period_locks").get().c;
		if (seeded === 0) {
			const graceDays = settlementGraceDays();
			const cur = currentMonthKeyCT();
			const historical = db.prepare("SELECT DISTINCT period FROM investor_payouts ORDER BY period ASC").all()
				.map((r) => r.period)
				// The seed is the SECOND writer of period_locks (it INSERTs directly
				// rather than going through finalizePeriods), so it needs the predicate
				// in its own right. It is also the riskiest one: it takes whatever
				// distinct periods investor_payouts happens to hold and locks the lot in
				// a single pass, so one absurd month key there becomes a permanent lock
				// row on the day the feature is first enabled.
				.filter((p) => p < cur && isPastGrace(p, graceDays) && isPlausibleLockPeriod(p));
			const ins = db.prepare("INSERT OR IGNORE INTO period_locks (period, status, finalized_at, finalized_by) VALUES (?, 'locked', ?, 'baseline')");
			const nowIso = new Date().toISOString();
			db.transaction(() => { for (const p of historical) ins.run(p, nowIso); })();
			console.log(`[period-close] baseline seeded — ${historical.length} historical period(s) locked; nothing reopened`);
		}
	} catch (e) { console.error("[period-close] baseline seed failed:", e.message); }

	// The tick's rejection handler LOGS. It used to be `.catch(() => {})`, which is
	// how the unguarded SELECTs above stayed invisible through two QA ticks: the
	// sweep threw, the promise rejected, and the empty handler discarded it without
	// so much as a line on stdout.
	//
	// maybeCloseFinishedPeriods() now owns its own try/catch/finally and should
	// never reject, so anything arriving here is a defect in that guard itself
	// (or in the catch block) rather than an ordinary close failure — which is
	// exactly why it must be noisy instead of silent. Deliberately NOT wired into
	// periodCloseFailStreak: the inner catch already counts real failures, and
	// double-counting would trip the ACTION-NEEDED threshold early.
	const periodCloseTick = () => {
		maybeCloseFinishedPeriods().catch((e) => {
			console.error("[period-close] sweep threw outside its own guard:", (e && e.message) || e);
		});
	};
	setInterval(periodCloseTick, 60 * 1000);
	setTimeout(periodCloseTick, 95 * 1000);
	console.log(`[period-close] enabled — months finalize ${settlementGraceDays()} day(s) after they end (America/Chicago)`);
}

// GET /api/financials — Super Admin financials dashboard (P1-1 from 2026-04-12 meeting)
// Deshorn asked for a financial overview tab showing expense categories, highest/lowest
// loads, per-truck macro view, rate-per-mile, and a driver earnings leaderboard. Reuses
// the job-tracking cache + the same aggregation primitives as /api/investor but without
// the investor-owner filter (Super Admin sees the whole fleet).
app.get("/api/financials", requireRole("Super Admin"), async (req, res) => {
	try {
		// Optional month drill-down (?month=YYYY-MM). Validated up front so a
		// bad param fails fast before any Sheets/DB work. When absent the
		// response is unchanged apart from `monthDetail: null`, so existing
		// consumers are unaffected.
		const monthParam = typeof req.query.month === "string" ? req.query.month.trim() : "";
		if (monthParam && !/^\d{4}-(0[1-9]|1[0-2])$/.test(monthParam)) {
			return res.status(400).json({ error: "month must be in YYYY-MM format" });
		}

		const jobTracking = await getJobTrackingCached();
		// Drop soft-deleted + cancelled loads before any aggregation so the P&L
		// numbers match the dashboard KPIs exactly.
		jobTracking.data = excludeDroppedLoads(jobTracking.data, jobTracking.headers);

		// Column resolution (same regex as investor endpoint)
		const jtRateCol = findCol(jobTracking.headers, /payment|rate|amount|revenue/i);
		const jtDateCol = findCol(jobTracking.headers, /status.*update.*date|completion.*date|assigned.*date/i)
			|| findCol(jobTracking.headers, /date/i);
		const jtDriverCol = findCol(jobTracking.headers, /^driver$/i);
		const jtTruckCol = findCol(jobTracking.headers, /^truck$|truck[._\s-]?(unit|number|#)|unit[._\s-]?number/i);
		// Intentionally stricter than /api/investor's /status/i so we never
		// accidentally match "Status Update Date". Production sheet uses
		// "Job Status" as the actual header, which is handled here. Same
		// fix pattern as the P0-8 invoice endpoint regex.
		const statusCol = findCol(jobTracking.headers, /^(job[\s._-]?)?status$/i);
		const pickupDateCol = findCol(jobTracking.headers, /pickup.*appo|pickup.*date/i);
		const dropoffDateCol = findCol(jobTracking.headers, /drop.?off.*appo|drop.?off.*date|delivery.*date/i);
		const loadIdCol = findCol(jobTracking.headers, /load.?id|job.?id/i);
		const completedStatuses = /^(delivered|completed|pod received)$/i;

		// ⚠️ The local `parseSheetDate` is DELETED, not merely unused — every date
		// read in this handler now goes through the shared moneySheetDate(). See the
		// note at the top of computeInvestorMonthlyEarnings() for why leaving a
		// narrower parser inline in a money handler is the defect, not a convenience.
		function fmtDate(d) {
			return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
		}
		function expandDateRange(start, end) {
			const dates = [];
			const s = new Date(start); s.setHours(12, 0, 0, 0);
			const e = end ? new Date(end) : new Date(start);
			e.setHours(12, 0, 0, 0);
			if (e < s) return [fmtDate(s)];
			const MAX_SPAN = 31 * 24 * 3600 * 1000;
			if (e - s > MAX_SPAN) e.setTime(s.getTime() + MAX_SPAN);
			const cur = new Date(s);
			while (cur <= e) {
				dates.push(fmtDate(cur));
				cur.setDate(cur.getDate() + 1);
			}
			return dates;
		}

		// ---- Miles source: load_coordinates table ----
		// Prefer real road distance from Google Routes API (cached in
		// distance_miles column, populated via /api/admin/backfill-road-
		// distances). Fall back to haversine straight-line for any row
		// where the backfill hasn't run yet. Old odometer-based miles
		// were always $0 because drivers rarely filled the odometer field.
		const milesByLoadId = {};
		let roadMilesCount = 0;
		let haversineMilesCount = 0;
		{
			const coordRows = db.prepare(
				"SELECT load_id, origin_lat, origin_lng, dest_lat, dest_lng, distance_miles FROM load_coordinates WHERE origin_lat IS NOT NULL AND dest_lat IS NOT NULL"
			).all();
			for (const c of coordRows) {
				if (c.distance_miles != null && c.distance_miles > 0) {
					milesByLoadId[(c.load_id || "").toLowerCase()] = c.distance_miles;
					roadMilesCount++;
				} else {
					const meters = geolib.getDistance(
						{ latitude: c.origin_lat, longitude: c.origin_lng },
						{ latitude: c.dest_lat, longitude: c.dest_lng }
					);
					milesByLoadId[(c.load_id || "").toLowerCase()] = meters / 1609.344;
					haversineMilesCount++;
				}
			}
		}

		// ---- Single-pass aggregation across all loads ----
		let totalRevenue = 0;
		let earliestDate = null;
		let latestDate = null;
		let completedRowCount = 0;       // row-level count — matches /api/investor.completedJobs
		// Unassigned revenue: completed loads where the Driver column is blank.
		// Tracked separately so the leaderboard sum reconciles with totalRevenue
		// AND so Deshorn can see a data-quality signal (loads that never got
		// attributed to a real driver).
		let unassignedGross = 0;
		let unassignedLoadCount = 0;
		let unassignedMiles = 0;
		const completedLoadIds = new Set();  // unique load IDs — used for expense matching
		const grossByDriver = {};
		const grossByTruck = {};         // sum revenue per truck (truck-column attribution)
		const milesByDriver = {};        // sum of haversine miles per driver
		const milesByTruck = {};         // sum of haversine miles per truck
		let fleetTotalMiles = 0;
		let loadsWithCoords = 0;         // data-quality signal
		const loadsByDriver = {};
		const loadsByTruck = {};
		const driverDaySets = {};
		const truckDaySets = {};         // active days per truck (per-truck driver pay)
		const truckLoadDates = {};       // {first, last} per truck — accurate operating window
		const completedLoads = []; // for highest/lowest — store minimal fields
		// Per-driver per-month REVENUE (completed loads only). Used by the
		// percentage-pay branch so owner-op pay = (monthRevenue − monthDeductible) × pct.
		const driverMonthlyRevenue = {}; // { driver_lc: { "YYYY-MM": revenue } }
		// Fleet-wide completed revenue per assigned month (incl. unassigned
		// loads) — drives the monthly performance breakdown. Keyed "YYYY-MM".
		const monthlyRevenue = {};
		// Mirror the admin overrides from /api/investor so the company P&L
		// and investor view honor the same adjustments (CLAUDE.md consistency
		// rule). `remove` filters days out; `add` credits ELD-missed days.
		const driverDayOverrides = getAllExcludedDriverDays();
		const now = new Date();

		// ---- ELD travel-day index (per linked vehicle), fleet-wide ----
		// Same rationale as /api/investor: a COMPLETED load's pickup→delivery
		// window is intersected with the days that truck actually traveled per
		// ELD, so driver/truck active days reflect real working days. Trucks with
		// no ELD link fall back to the full window. Keeps this P&L reconciled with
		// the investor view (the CLAUDE.md consistency invariant).
		const unitToVid = {};
		db.prepare("SELECT LOWER(unit_number) AS u, routemate_vehicle_id AS vid FROM trucks WHERE COALESCE(routemate_vehicle_id, '') != ''").all()
			.forEach(t => { unitToVid[t.u] = t.vid; });
		const eldByVid = getEldTravelDaysByVehicleCached(Object.values(unitToVid), 0, Date.now() + 86400000);

		jobTracking.data.forEach((r) => {
			const st = statusCol ? (r[statusCol] || "").trim() : "";
			const driver = jtDriverCol ? (r[jtDriverCol] || "").trim() : "";
			const driverLc = normalizeDriverName(driver);
			const truckUnit = jtTruckCol ? (r[jtTruckCol] || "").trim().toLowerCase() : "";

			// Operating period
			if (jtDateCol && r[jtDateCol]) {
				const d = moneySheetDate(r[jtDateCol]);
				if (d && !isNaN(d)) {
					if (!earliestDate || d < earliestDate) earliestDate = d;
					if (!latestDate || d > latestDate) latestDate = d;
				}
			}

			// Revenue + completed-load list
			if (completedStatuses.test(st)) {
				completedRowCount++;
				if (driverLc) loadsByDriver[driverLc] = (loadsByDriver[driverLc] || 0) + 1;
				if (truckUnit) loadsByTruck[truckUnit] = (loadsByTruck[truckUnit] || 0) + 1;
				const amt = parseFloat(String((jtRateCol ? r[jtRateCol] : "0")).replace(/[$,]/g, "")) || 0;
				if (amt) {
					const lid = loadIdCol ? (r[loadIdCol] || "").trim() : "";
					if (lid) completedLoadIds.add(lid);
					totalRevenue += amt;
					if (driverLc) {
						grossByDriver[driverLc] = (grossByDriver[driverLc] || 0) + amt;
					} else {
						unassignedGross += amt;
						unassignedLoadCount += 1;
					}
					if (truckUnit) {
						grossByTruck[truckUnit] = (grossByTruck[truckUnit] || 0) + amt;
						// First/last load date per truck — used to bound the
						// fixed-cost accrual window so a truck idle for half
						// the year doesn't get charged 12 months of insurance.
						if (jtDateCol && r[jtDateCol]) {
							const d = moneySheetDate(r[jtDateCol]);
							if (d && !isNaN(d)) {
								if (!truckLoadDates[truckUnit]) truckLoadDates[truckUnit] = { first: d, last: d };
								else {
									if (d < truckLoadDates[truckUnit].first) truckLoadDates[truckUnit].first = d;
									if (d > truckLoadDates[truckUnit].last) truckLoadDates[truckUnit].last = d;
								}
							}
						}
					}
					// Miles for this load (straight-line from load_coordinates).
					// Loads without coordinates contribute 0 — counted separately
					// as loadsWithCoords so the frontend can show coverage %.
					const loadMiles = milesByLoadId[lid.toLowerCase()] || 0;
					if (loadMiles > 0) {
						loadsWithCoords++;
						fleetTotalMiles += loadMiles;
						if (driverLc) {
							milesByDriver[driverLc] = (milesByDriver[driverLc] || 0) + loadMiles;
						} else {
							unassignedMiles += loadMiles;
						}
						if (truckUnit) milesByTruck[truckUnit] = (milesByTruck[truckUnit] || 0) + loadMiles;
					}
					// Capture for highest/lowest. Use display name for driver (not lowercase).
					// monthKey (assigned-month bucket) is filled in below when the date
					// parses; the month drill-down filters completedLoads on it so the
					// month's load list reconciles with monthlyRevenue by construction.
					const dateStr = jtDateCol && r[jtDateCol] ? String(r[jtDateCol]) : "";
					const loadEntry = {
						loadId: lid || `#${completedLoads.length + 1}`,
						driver: driver || "(unknown)",
						amount: amt,
						date: dateStr,
						monthKey: "",
					};
					completedLoads.push(loadEntry);
					// Per-month revenue: fleet-wide (incl. unassigned) for the
					// monthly performance view, plus per-driver for the
					// percentage-pay branch. Bucketed by the load's assigned month.
					if (jtDateCol && r[jtDateCol]) {
						const d = moneySheetDate(r[jtDateCol]);
						if (d && !isNaN(d)) {
							const mk = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
							loadEntry.monthKey = mk;
							monthlyRevenue[mk] = (monthlyRevenue[mk] || 0) + amt;
							if (driverLc) {
								if (!driverMonthlyRevenue[driverLc]) driverMonthlyRevenue[driverLc] = {};
								driverMonthlyRevenue[driverLc][mk] = (driverMonthlyRevenue[driverLc][mk] || 0) + amt;
							}
						}
					}
				}
			}

			// Active-day sets for driver pay (per-driver and per-truck).
			// COMPLETED loads only, intersected with the days the truck actually
			// traveled per ELD. Per-truck days × that truck's `driver_pay_daily`
			// is the authoritative per-row driver pay; per-driver days remain the
			// fallback when the sheet has no truck-column attribution. Trucks with
			// no ELD link fall back to the full pickup→delivery window.
			if (completedStatuses.test(st)) {
				// BOTH ends resolve through the shared moneySheetDate(), matching the
				// fallback below and the twin sites in computeInvestorMonthlyEarnings()
				// and GET /api/investor — see the full rationale and production
				// measurement at the first of those. These three MUST stay in lockstep
				// or the P&L, the investor portal and the weekly invoice stop
				// reconciling; the pickup end is the half that was still diverging from
				// POST /api/invoices/generate.
				let pickup = moneySheetDate(pickupDateCol ? r[pickupDateCol] : null);
				const dropoff = moneySheetDate(dropoffDateCol ? r[dropoffDateCol] : null);
				// Unreadable or blank pickup → fall back to the assigned date. Now
				// genuinely the last resort; see the note at the first site.
				if (!pickup && jtDateCol && r[jtDateCol]) pickup = moneySheetDate(r[jtDateCol]);
				if (pickup && !isNaN(pickup)) {
					const windowDays = expandDateRange(pickup, dropoff || pickup);
					const vid = truckUnit ? unitToVid[truckUnit] : null;
					const eld = vid ? eldByVid[vid] : null;
					// Intersect with real travel days only when the ELD covered this
					// window (≥1 ping); otherwise fall back to the full window (see
					// /api/investor for rationale).
					const covered = eld && windowDays.some(d => eld.coverage.has(d));
					const eldCounted = covered ? windowDays.filter(d => eld.travel.has(d)) : windowDays;
					// Strip admin-removed days here; admin-added days are applied
					// after the loop so they don't require a load row to exist.
					const ovr = driverLc ? (driverDayOverrides[driverLc] || null) : null;
					const skipSet = ovr ? ovr.remove : null;
					const counted = skipSet && skipSet.size ? eldCounted.filter(d => !skipSet.has(d)) : eldCounted;
					if (driverLc) {
						if (!driverDaySets[driverLc]) driverDaySets[driverLc] = new Set();
						counted.forEach(d => driverDaySets[driverLc].add(d));
					}
					// truckDaySets intentionally left unfiltered — truck-level days
					// aren't user-visible, and the driver-keyed exclusion gets
					// ambiguous when a truck has multiple drivers in a window.
					if (truckUnit) {
						if (!truckDaySets[truckUnit]) truckDaySets[truckUnit] = new Set();
						eldCounted.forEach(d => truckDaySets[truckUnit].add(d));
					}
				}
			}
		});

		// Apply admin-added days fleet-wide. Same as /api/investor: credits a
		// day the ELD missed (truck offline, vehicle not linked, feed gap) to
		// the driver's all-time active-day set. Per-truck day sets are not
		// touched — added days are driver-keyed, and the per-truck breakdown
		// uses unfiltered ELD travel anyway.
		for (const [drv, ovr] of Object.entries(driverDayOverrides)) {
			if (!ovr.add || !ovr.add.size) continue;
			if (!driverDaySets[drv]) driverDaySets[drv] = new Set();
			for (const d of ovr.add) driverDaySets[drv].add(d);
		}

		// Partition each driver's final active-day set by calendar month for the
		// monthly performance breakdown. An exact partition of driverDaySets, so
		// per-month fixed-driver pay sums back to the annual total computed below.
		const driverMonthlyDays = {}; // { driver_lc: { "YYYY-MM": Set<"YYYY-MM-DD"> } }
		for (const [drv, daySet] of Object.entries(driverDaySets)) {
			const buckets = (driverMonthlyDays[drv] = {});
			for (const d of daySet) {
				const mk = d.slice(0, 7);
				(buckets[mk] || (buckets[mk] = new Set())).add(d);
			}
		}

		let monthsOfOperation = 1;
		if (earliestDate && latestDate) {
			monthsOfOperation = Math.max(1,
				(latestDate.getFullYear() - earliestDate.getFullYear()) * 12
				+ (latestDate.getMonth() - earliestDate.getMonth()) + 1
			);
		}

		// ---- Expense totals (entire fleet, no filter) ----
		const expByCategory = Object.fromEntries(
			db.prepare(`SELECT LOWER(type) AS cat, COALESCE(SUM(amount),0) AS t FROM expenses WHERE ${EXPENSE_PNL_FILTER} GROUP BY LOWER(type)`).all().map(r => [r.cat || "other", r.t])
		);
		const totalTripExpenses = Object.values(expByCategory).reduce((s, v) => s + v, 0);

		// Monthly expenses by category
		const monthlyCategoryRows = db.prepare(
			`SELECT strftime('%Y-%m', date) AS m, LOWER(type) AS cat, COALESCE(SUM(amount),0) AS t
			 FROM expenses WHERE date IS NOT NULL AND date != '' AND ${EXPENSE_PNL_FILTER} GROUP BY m, LOWER(type) ORDER BY m ASC`
		).all();
		const expensesByMonthMap = {};
		monthlyCategoryRows.forEach(r => {
			if (!r.m) return;
			if (!expensesByMonthMap[r.m]) expensesByMonthMap[r.m] = { month: r.m, fuel: 0, maintenance: 0, repair: 0, toll: 0, food: 0, other: 0 };
			const key = (r.cat in expensesByMonthMap[r.m]) ? r.cat : "other";
			expensesByMonthMap[r.m][key] += r.t;
		});
		const expensesByMonth = Object.values(expensesByMonthMap);

		// Maintenance fund + compliance fees (truck-level) roll into totalExpenses.
		// Exclude rows tied to non-Active trucks (Inactive / Maintenance / OOS)
		// via NOT IN, which preserves orphan rows whose `truck` cell doesn't
		// match any truck (existing behavior) while dropping inactive ones.
		const maintSum = db.prepare(`SELECT COALESCE(SUM(amount),0) AS t FROM maintenance_fund WHERE type='service' AND LOWER(truck) NOT IN (SELECT LOWER(unit_number) FROM trucks WHERE status != 'Active')`).get().t;
		const compSum = db.prepare(`SELECT COALESCE(SUM(amount),0) AS t FROM compliance_fees WHERE status='Paid' AND LOWER(truck) NOT IN (SELECT LOWER(unit_number) FROM trucks WHERE status != 'Active')`).get().t;

		// ---- Driver pay (branches on each driver's pay_type) ----
		// Fixed drivers: activeDays × per-truck dailyRate (legacy logic).
		// Percentage drivers: max(0, completed-load revenue − Fuel & Maintenance) × pct.
		// Same formula their invoice uses, so /admin/financials matches reality.
		const payStructures = getDriverPayStructures();
		const expensesByDriverMonth = getDeductibleExpensesByDriverMonth();
		const trucksByDriver = {};
		db.prepare("SELECT assigned_driver, driver_pay_daily FROM trucks").all().forEach(t => {
			const d = normalizeDriverName(t.assigned_driver);
			if (d) trucksByDriver[d] = t.driver_pay_daily || 250;
		});
		const driverPayDetails = {};
		let totalDriverPay = 0;
		for (const [driver, daySet] of Object.entries(driverDaySets)) {
			const struct = payStructures[driver] || { payType: "fixed", payPercentage: 0 };
			const activeDays = daySet.size;
			let pay, dailyRate;
			if (struct.payType === "percentage") {
				const totalRev = Object.values(driverMonthlyRevenue[driver] || {}).reduce((s, v) => s + v, 0);
				const totalExp = (expensesByDriverMonth[driver] || {})._total || 0;
				const net = Math.max(0, totalRev - totalExp);
				pay = Math.round((net * struct.payPercentage / 100) * 100) / 100;
				dailyRate = 0;
			} else {
				dailyRate = resolveDailyRate(struct.payDaily, trucksByDriver[driver]);
				pay = activeDays * dailyRate;
			}
			totalDriverPay += pay;
			driverPayDetails[driver] = {
				activeDays, dailyRate, totalPay: pay,
				payType: struct.payType,
				payPercentage: struct.payType === "percentage" ? struct.payPercentage : 0,
				source: "estimate",
			};
		}

		// ---- Truck fixed costs ----
		// `maintenance_fund_monthly` is intentionally OMITTED. It's a budget
		// reserve allocation (see comment at line ~11134), not a real cost.
		// Real maintenance spend already flows through `maintSum` (actual
		// service payments from the maintenance_fund table). Including the
		// reserve here would double-count maintenance for the whole fleet.
		// Operating-window rule mirrors the per-truck loop below: prefer the
		// truck's first→last load date range, fall back to created_at-capped
		// fleet months only when the truck has no recorded loads. Keeps the
		// fleet KPI reconciled with sum(perTruck.fixedTotal).
		// Inactive trucks drop out of the fleet P&L — they don't accrue
		// projected fixed costs and they don't appear in the per-truck
		// performance table further down (both consume `allTrucks`).
		const allTrucks = db.prepare("SELECT * FROM trucks WHERE status = 'Active'").all();
		let totalFixedCosts = 0;
		for (const t of allTrucks) {
			const perMonth = (t.insurance_monthly || 0) + (t.eld_monthly || 0) + (t.truck_payment_monthly || 0)
				+ ((t.hvut_annual || 0) / 12) + ((t.irp_annual || 0) / 12);
			const unitLower = (t.unit_number || "").toLowerCase();
			let truckMonths = monthsOfOperation;
			if (truckLoadDates[unitLower]) {
				const { first, last } = truckLoadDates[unitLower];
				truckMonths = Math.max(1,
					(last.getFullYear() - first.getFullYear()) * 12
					+ (last.getMonth() - first.getMonth()) + 1
				);
			} else {
				// No loads: accrue from the in-service month (in_service_date, else
				// created_at) to the retirement month, rather than from the day the
				// row was entered in the UI to today. Floor 0 so a forward-dated truck
				// accrues nothing yet, matching the $0 its monthly rows show.
				//
				// ⚠️ The truckLoadDates branch above is deliberately NOT retirement-
				// clamped. It spans first load → last load, so it is already bounded by
				// the truck's real activity and a retired truck's last load is in the
				// past by construction. Clamping it too would double-count the bound
				// and could shorten a span the truck genuinely worked.
				const billed = truckBilledMonthCount(t, now);
				if (billed !== null) truckMonths = Math.min(billed, monthsOfOperation);
			}
			totalFixedCosts += perMonth * truckMonths;
		}

		const totalExpenses = totalTripExpenses + maintSum + compSum + totalDriverPay + totalFixedCosts;
		const netProfit = totalRevenue - totalExpenses;

		// ---- Biggest expense category (compared across fuel/maint/repair/tolls/other) ----
		const catLabels = { fuel: "Fuel", maintenance: "Maintenance", repair: "Repair", toll: "Tolls", food: "Food", other: "Other" };
		let biggest = { name: "—", amount: 0 };
		for (const [cat, amt] of Object.entries(expByCategory)) {
			if (amt > biggest.amount) biggest = { name: catLabels[cat] || cat, amount: Math.round(amt) };
		}

		// ---- Per-Truck Performance ----
		// Attribution rule: every per-truck term must use the truck's
		// unit_number as the key. Driver-keyed maps are only used as a
		// fallback when the entire fleet has no truck-column attribution
		// (legacy single-driver fleet). Partial fallback would let one
		// truck inherit another truck's revenue/expenses when a single
		// load is missing its truck column — that was the source of the
		// negative-Net rows reported by Deshorn on /admin/financials.
		const expByDriverRows = db.prepare(`SELECT LOWER(driver) AS d, COALESCE(SUM(amount),0) AS t FROM expenses WHERE ${EXPENSE_PNL_FILTER} GROUP BY LOWER(driver)`).all();
		const expByDriver = Object.fromEntries(expByDriverRows.map(r => [r.d, r.t]));
		const expByTruck = Object.fromEntries(
			db.prepare(`SELECT LOWER(truck_unit) AS u, COALESCE(SUM(amount),0) AS t FROM expenses WHERE truck_unit IS NOT NULL AND truck_unit != '' AND ${EXPENSE_PNL_FILTER} GROUP BY LOWER(truck_unit)`).all().map(r => [r.u, r.t])
		);
		const maintByTruck = Object.fromEntries(
			db.prepare(`SELECT LOWER(truck) AS u, COALESCE(SUM(amount),0) AS t FROM maintenance_fund WHERE type='service' GROUP BY LOWER(truck)`).all().map(r => [r.u, r.t])
		);
		const compByTruck = Object.fromEntries(
			db.prepare(`SELECT LOWER(truck) AS u, COALESCE(SUM(amount),0) AS t FROM compliance_fees WHERE status='Paid' GROUP BY LOWER(truck)`).all().map(r => [r.u, r.t])
		);

		// Fleet-wide attribution flags: decide whether to fall back to
		// driver-keyed maps for trucks that have zero truck-attributed data.
		const fleetHasTruckRevenue = Object.keys(grossByTruck).length > 0;
		const fleetHasTruckExpenses = Object.keys(expByTruck).length > 0;
		const fleetHasTruckDays = Object.keys(truckDaySets).length > 0;

		const perTruck = allTrucks.map((truck) => {
			const driverName = normalizeDriverName(truck.assigned_driver);
			const unitLower = (truck.unit_number || "").toLowerCase();

			// Revenue: truck-first, with safe fallback only when no truck
			// in the fleet has any truck-attributed gross. Avoids the
			// "blank/mismatched assigned_driver → $0 gross + thousands in
			// expenses → big negative Net" failure mode.
			const gross = grossByTruck[unitLower] !== undefined
				? grossByTruck[unitLower]
				: (fleetHasTruckRevenue ? 0 : (grossByDriver[driverName] || 0));

			// Variable expenses: truck-first via expenses.truck_unit.
			const varExp = expByTruck[unitLower] !== undefined
				? expByTruck[unitLower]
				: (fleetHasTruckExpenses ? 0 : (expByDriver[driverName] || 0));

			const maintExp = maintByTruck[unitLower] || 0;
			const compExp = compByTruck[unitLower] || 0;

			// Fixed costs: drop maintenance_fund_monthly (reserve budget,
			// already counted via maintExp service rows). Same rationale
			// as the fleet totalFixedCosts loop above — keeps fleet and
			// per-truck consistent.
			const fixedPerMonth = (truck.insurance_monthly || 0) + (truck.eld_monthly || 0) + (truck.truck_payment_monthly || 0)
				+ ((truck.hvut_annual || 0) / 12) + ((truck.irp_annual || 0) / 12);

			// Operating window: prefer the actual range of load dates for
			// THIS truck. Falls back to in-service-capped fleet months only
			// when the truck has no recorded loads (then it's all overhead
			// and Net should be negative — that's accurate, not a bug).
			// MUST stay identical to the fleet totalFixedCosts loop above:
			// that KPI is documented as reconciling to sum(perTruck.fixedTotal),
			// so moving one start month without the other silently breaks it.
			let truckMonths = monthsOfOperation;
			if (truckLoadDates[unitLower]) {
				const { first, last } = truckLoadDates[unitLower];
				truckMonths = Math.max(1,
					(last.getFullYear() - first.getFullYear()) * 12
					+ (last.getMonth() - first.getMonth()) + 1
				);
			} else {
				// Floor 0 and retirement-bounded, same as the fleet loop — these two
				// must not diverge, because the fleet KPI is documented as reconciling
				// to sum(perTruck.fixedTotal).
				const billed = truckBilledMonthCount(truck, now);
				if (billed !== null) truckMonths = Math.min(billed, monthsOfOperation);
			}

			// Driver pay: per-truck active days × this truck's daily rate.
			// dailyRate=0 silently defaults to $250/day (preserved for
			// backwards compat); flagged via driverPayUsedDefault so the
			// UI can warn.
			// Percentage drivers (e.g. Rodney) bypass the daily-rate path and
			// use the per-driver totalPay computed above, pro-rated by this
			// truck's share of the driver's total active days so multi-truck
			// drivers don't double-count.
			const truckDays = truckDaySets[unitLower]?.size || 0;
			const driverStruct = (driverName && payStructures[driverName]) || { payType: "fixed", payPercentage: 0 };
			const dailyRateRaw = truck.driver_pay_daily || 0;
			const dailyRate = resolveDailyRate(driverStruct.payDaily, dailyRateRaw);
			let driverPay;
			let driverPayUsedDefault;
			if (driverStruct.payType === "percentage") {
				const driverTotalPay = driverPayDetails[driverName]?.totalPay || 0;
				if (truckDays > 0) {
					const driverDays = driverDaySets[driverName]?.size || 0;
					const share = driverDays > 0 ? Math.min(1, truckDays / driverDays) : 1;
					driverPay = driverTotalPay * share;
				} else if (fleetHasTruckDays) {
					driverPay = 0;
				} else {
					driverPay = driverTotalPay;
				}
				driverPayUsedDefault = false;
			} else {
				driverPayUsedDefault = dailyRateRaw === 0;
				driverPay = truckDays > 0
					? truckDays * dailyRate
					: (fleetHasTruckDays ? 0 : (driverPayDetails[driverName]?.totalPay || 0));
			}

			const fixedTotal = fixedPerMonth * truckMonths;
			const expenses = varExp + maintExp + compExp + fixedTotal + driverPay;
			const net = gross - expenses;

			// Miles: same truck-first rule (already in place pre-patch).
			// Compute $/mile from the unrounded mile count so small-fleet
			// rates don't drift (e.g. 1.4 mi rounds to 1, halving the rate).
			const truckMiles = milesByTruck[unitLower];
			const rawMiles = truckMiles !== undefined ? truckMiles : (milesByDriver[driverName] || 0);
			const totalMiles = Math.round(rawMiles);
			const ratePerMile = rawMiles > 0 ? Math.round((gross / rawMiles) * 100) / 100 : 0;
			const truckLoadCount = loadsByTruck[unitLower];
			const loadCount = (truckLoadCount !== undefined) ? truckLoadCount : (loadsByDriver[driverName] || 0);

			return {
				unitNumber: truck.unit_number,
				assignedDriver: truck.assigned_driver || "—",
				loadCount,
				gross: Math.round(gross),
				expenses: Math.round(expenses),
				net: Math.round(net),
				totalMiles,
				ratePerMile,
				monthlyCost: Math.round(fixedPerMonth),
				// Data-quality flags so the UI can explain surprising rows.
				operatingMonths: truckMonths,
				driverPayUsedDefault,
				driverPayType: driverStruct.payType,
				driverPayPercentage: driverStruct.payType === "percentage" ? driverStruct.payPercentage : 0,
				attributionMode: grossByTruck[unitLower] !== undefined
					? "truck"
					: (fleetHasTruckRevenue ? "no-data" : "driver-fallback"),
				// Idle asset: a truck that's been onboarded (and is accruing fixed
				// costs) but has never carried a completed load. Its negative Net is
				// pure overhead, not an operating loss — flag it so the UI can label
				// the row instead of showing a confusing red number.
				idle: loadCount === 0 && gross === 0,
				idleSince: (loadCount === 0 && gross === 0) ? (truck.created_at || null) : null,
			};
		});

		// ---- Idle assets: onboarded trucks with zero completed loads ----
		// Their fixed costs drag fleet net, but it's idle overhead (insurance +
		// ELD on a parked truck), not a freight loss. Summarized so /admin/
		// financials can warn up front rather than leaving Deshorn to puzzle
		// over a negative-net row (e.g. Rodney Brown / INV-38-A).
		const idleTrucksList = perTruck.filter(t => t.idle);
		const idleTruckCount = idleTrucksList.length;
		const idleOverhead = idleTrucksList.reduce((s, t) => s + (t.expenses || 0), 0);

		// ---- Highest + lowest paying loads ----
		// Guard against fewer than 10 completed loads: sliceStart below ensures
		// the "lowest" window never overlaps the "highest" window so a single
		// load never appears in both lists when the fleet is young.
		const sortedLoads = [...completedLoads].sort((a, b) => b.amount - a.amount);
		const highest = sortedLoads.slice(0, 5).map(l => ({ loadId: l.loadId, driver: l.driver, amount: Math.round(l.amount), date: l.date }));
		const lowestStart = Math.max(5, sortedLoads.length - 5);
		const lowest = sortedLoads.slice(lowestStart).reverse().map(l => ({ loadId: l.loadId, driver: l.driver, amount: Math.round(l.amount), date: l.date }));

		// ---- Driver earnings leaderboard ----
		// Use the driver's display name from the first row they appear in rather than lowercase
		const driverDisplayNames = {};
		jobTracking.data.forEach(r => {
			const d = jtDriverCol ? (r[jtDriverCol] || "").trim() : "";
			const k = normalizeDriverName(d);
			if (d && k && !driverDisplayNames[k]) driverDisplayNames[k] = d;
		});
		const drivers = Object.entries(grossByDriver).map(([lcName, gross]) => {
			const rawMiles = milesByDriver[lcName] || 0;
			const totalMiles = Math.round(rawMiles);
			const pay = driverPayDetails[lcName]?.totalPay || 0;
			return {
				name: driverDisplayNames[lcName] || lcName,
				totalEarnings: Math.round(pay), // what the driver earned (their take)
				grossRevenue: Math.round(gross), // revenue the driver generated
				loadCount: loadsByDriver[lcName] || 0,
				totalMiles,
				avgRatePerMile: rawMiles > 0 ? Math.round((gross / rawMiles) * 100) / 100 : 0,
			};
		}).sort((a, b) => b.grossRevenue - a.grossRevenue);
		// Reconcile the leaderboard with totalRevenue: any completed revenue
		// from rows with a blank Driver column is surfaced as a single
		// "(Unassigned)" row at the bottom. Without this, sum(drivers) is
		// quietly less than totalRevenue whenever the sheet has data-quality
		// gaps — and the investor reading the dashboard has no way to tell.
		if (unassignedGross > 0) {
			const uMiles = Math.round(unassignedMiles);
			drivers.push({
				name: "(Unassigned)",
				totalEarnings: 0,
				grossRevenue: Math.round(unassignedGross),
				loadCount: unassignedLoadCount,
				totalMiles: uMiles,
				avgRatePerMile: unassignedMiles > 0 ? Math.round((unassignedGross / unassignedMiles) * 100) / 100 : 0,
				isUnassigned: true, // flag for frontend styling
			});
		}

		// Fleet-wide avg rate/mile — divides by the unrounded mile count to
		// avoid drift on tiny mile totals; the rounded value is only used
		// for the totalMiles summary display.
		const fleetTotalMilesRounded = Math.round(fleetTotalMiles);
		const avgRatePerMile = fleetTotalMiles > 0
			? Math.round((totalRevenue / fleetTotalMiles) * 100) / 100
			: 0;

		// Reconciled expense breakdown for the Expense Categories chart: trip
		// categories + driver pay + truck fixed costs + maintenance-fund service
		// + compliance, so the bars sum to totalExpenses (the KPI). The "Biggest
		// Trip Expense" KPI (`biggest`, above) intentionally stays trip-only.
		// Maintenance-fund service folds into the single "maintenance" bar.
		const reconciledExpenses = Object.fromEntries(
			Object.entries(expByCategory).map(([k, v]) => [k, Math.round(v)])
		);
		reconciledExpenses.maintenance = Math.round((expByCategory.maintenance || 0) + maintSum);
		reconciledExpenses.driver_pay = Math.round(totalDriverPay);
		reconciledExpenses.fixed_costs = Math.round(totalFixedCosts);
		reconciledExpenses.compliance = Math.round((expByCategory.compliance || 0) + compSum);

		// ---- Monthly performance breakdown (revenue / expenses / net per
		// calendar month, oldest → current incl. month-to-date) ----
		// Mirrors /api/investor's monthlyEarnings so the two views reconcile:
		// revenue by assigned month; fixed pay = month active-days × daily rate;
		// percentage pay = max(0, monthRevenue − monthDeductible) × pct; plus
		// per-month trip expenses (expenses table) and truck fixed costs.
		// Monthly expenses exclude the maintenance-fund and compliance buckets
		// (not date-bucketed here), so the annual KPIs remain authoritative.
		// Also exposes the per-month intermediates (driver pay / trip expenses /
		// fixed costs) so the optional ?month= drill-down below reuses the exact
		// same numbers as the table rows instead of forking the math.
		const { monthlyPerformance, monthlyDriverPay, monthlyTripExp, monthlyFixedCosts } = (() => {
			const pad = (n) => String(n).padStart(2, "0");
			// Houston month, not server-local: on the UTC VPS a plain getMonth() flips at
			// 19:00 (CDT) / 18:00 (CST) Houston on the last day of the month, so for the
			// final 5-6 hours of every month the portal showed the NEXT month accruing at
			// $0 and treated the just-ended one as complete. houstonDay() is the same
			// Central basis the stamps and the close lifecycle now use.
			const currentMonthKey = houstonDay(now).slice(0, 7);

			// Driver pay per month.
			const monthlyDriverPay = {};
			const payDrivers = new Set([
				...Object.keys(driverMonthlyDays),
				...Object.keys(driverMonthlyRevenue),
			]);
			for (const driver of payDrivers) {
				const struct = payStructures[driver] || { payType: "fixed", payPercentage: 0 };
				if (struct.payType === "percentage") {
					const revByMonth = driverMonthlyRevenue[driver] || {};
					const expByMonth = expensesByDriverMonth[driver] || {};
					for (const [mk, monthRev] of Object.entries(revByMonth)) {
						const net = Math.max(0, monthRev - (expByMonth[mk] || 0));
						monthlyDriverPay[mk] = (monthlyDriverPay[mk] || 0)
							+ Math.round((net * struct.payPercentage / 100) * 100) / 100;
					}
				} else {
					const rate = resolveDailyRate(struct.payDaily, trucksByDriver[driver]);
					for (const [mk, daySet] of Object.entries(driverMonthlyDays[driver] || {})) {
						monthlyDriverPay[mk] = (monthlyDriverPay[mk] || 0) + daySet.size * rate;
					}
				}
			}

			// Trip expenses per month (expenses table — same source as the
			// Expense Categories chart's trip rows).
			const monthlyTripExp = {};
			for (const m of expensesByMonth) {
				monthlyTripExp[m.month] = (m.fuel || 0) + (m.maintenance || 0) + (m.repair || 0)
					+ (m.toll || 0) + (m.food || 0) + (m.other || 0);
			}

			// Fixed costs per month — constant per Active truck for every month
			// from its in-service month onward (maintenance-fund reserve omitted,
			// same as the fleet totals). Whole dollars here, unlike the investor
			// drill-down's cents — that rounding is this chart's own convention and
			// is left alone.
			const fixedTrucks = db.prepare(
				"SELECT insurance_monthly, eld_monthly, truck_payment_monthly, hvut_annual, irp_annual, created_at, in_service_date, retired_at FROM trucks WHERE status = 'Active'"
			).all();
			const monthlyFixedCosts = (mk) => {
				let total = 0;
				for (const t of fixedTrucks) {
					// Not in service yet, or already retired — shared predicate.
					if (!truckChargedInMonth(t, mk)) continue;
					total += (t.insurance_monthly || 0) + (t.eld_monthly || 0) + (t.truck_payment_monthly || 0)
						+ ((t.hvut_annual || 0) / 12) + ((t.irp_annual || 0) / 12);
				}
				return Math.round(total);
			};

			// Walk every month from the earliest load month to the current month.
			const startKey = earliestDate
				? `${earliestDate.getFullYear()}-${pad(earliestDate.getMonth() + 1)}`
				: currentMonthKey;
			const out = [];
			let cursor = new Date(parseInt(startKey.slice(0, 4), 10), parseInt(startKey.slice(5, 7), 10) - 1, 1);
			const endDate = new Date(now.getFullYear(), now.getMonth(), 1);
			let guard = 0;
			while (cursor <= endDate && guard++ < 600) {
				const mk = `${cursor.getFullYear()}-${pad(cursor.getMonth() + 1)}`;
				const revenue = monthlyRevenue[mk] || 0;
				const driverPay = monthlyDriverPay[mk] || 0;
				const tripExpenses = monthlyTripExp[mk] || 0;
				const fixedCosts = monthlyFixedCosts(mk);
				const totalExp = driverPay + tripExpenses + fixedCosts;
				out.push({
					month: mk,
					revenue: Math.round(revenue),
					driverPay: Math.round(driverPay),
					tripExpenses: Math.round(tripExpenses),
					fixedCosts,
					totalExpenses: Math.round(totalExp),
					netProfit: Math.round(revenue - totalExp),
					isCurrentMonth: mk === currentMonthKey,
				});
				cursor.setMonth(cursor.getMonth() + 1);
			}
			return { monthlyPerformance: out, monthlyDriverPay, monthlyTripExp, monthlyFixedCosts };
		})();

		// ---- Month drill-down (?month=YYYY-MM) ----
		// Built from the SAME aggregates that feed monthlyPerformance (revenue
		// by assigned month, driverMonthlyDays for active-day pay, strftime
		// month-bucketed trip expenses with EXPENSE_PNL_FILTER), so the modal
		// reconciles with the row the admin clicked by construction. Like the
		// monthly table, it excludes the maintenance-fund and compliance
		// buckets (not month-bucketed in this P&L) — the annual KPIs remain
		// authoritative for those.
		let monthDetail = null;
		if (monthParam) {
			const pad2 = (n) => String(n).padStart(2, "0");
			// Houston month, not server-local: on the UTC VPS a plain getMonth() flips at
			// 19:00 (CDT) / 18:00 (CST) Houston on the last day of the month, so for the
			// final 5-6 hours of every month the portal showed the NEXT month accruing at
			// $0 and treated the just-ended one as complete. houstonDay() is the same
			// Central basis the stamps and the close lifecycle now use.
			const currentMonthKey = houstonDay(now).slice(0, 7);
			const yearN = parseInt(monthParam.slice(0, 4), 10);
			const monthN = parseInt(monthParam.slice(5, 7), 10);
			const prevDate = new Date(yearN, monthN - 2, 1);
			const prevMk = `${prevDate.getFullYear()}-${pad2(prevDate.getMonth() + 1)}`;
			const daysInMonth = new Date(yearN, monthN, 0).getDate();
			const isCurrentMonth = monthParam === currentMonthKey;
			// For the in-progress month, per-day/per-week averages use elapsed
			// days so they aren't diluted by days that haven't happened yet.
			const elapsedDays = isCurrentMonth ? Math.max(1, now.getDate()) : daysInMonth;
			const weeksElapsed = elapsedDays / 7;

			// Same formula as the monthlyPerformance rows — keep in lockstep.
			const summarizeMonth = (mk) => {
				const revenue = monthlyRevenue[mk] || 0;
				const driverPay = monthlyDriverPay[mk] || 0;
				const tripExpenses = monthlyTripExp[mk] || 0;
				const fixedCosts = monthlyFixedCosts(mk);
				const totalExpenses = driverPay + tripExpenses + fixedCosts;
				return {
					month: mk,
					revenue: Math.round(revenue),
					driverPay: Math.round(driverPay),
					tripExpenses: Math.round(tripExpenses),
					fixedCosts,
					totalExpenses: Math.round(totalExpenses),
					netProfit: Math.round(revenue - totalExpenses),
				};
			};
			const cur = summarizeMonth(monthParam);
			const prev = summarizeMonth(prevMk);
			const prevHasData = prev.revenue !== 0 || prev.totalExpenses !== 0;

			// Expense split for the month: trip categories (same strftime
			// bucketing as expensesByMonth) plus the two P&L-level buckets.
			const catRow = expensesByMonthMap[monthParam]
				|| { fuel: 0, maintenance: 0, repair: 0, toll: 0, food: 0, other: 0 };
			const expenseCategories = {
				fuel: Math.round(catRow.fuel || 0),
				maintenance: Math.round(catRow.maintenance || 0),
				repair: Math.round(catRow.repair || 0),
				toll: Math.round(catRow.toll || 0),
				food: Math.round(catRow.food || 0),
				other: Math.round(catRow.other || 0),
				driver_pay: cur.driverPay,
				fixed_costs: cur.fixedCosts,
			};

			// Fuel analytics for the month — same source/filters as
			// /api/expenses/fuel-analytics (LOWER(type)='fuel', Rejected
			// excluded) with the same strftime month bucket as the category
			// rows, so fuel.spend === expenseCategories.fuel.
			const fuelTotals = db.prepare(
				`SELECT COALESCE(SUM(amount),0) AS spend, COALESCE(SUM(gallons),0) AS gallons, COUNT(*) AS fills
				 FROM expenses WHERE LOWER(type)='fuel' AND strftime('%Y-%m', date)=? AND ${EXPENSE_PNL_FILTER}`
			).get(monthParam);
			const prevFuelSpend = db.prepare(
				`SELECT COALESCE(SUM(amount),0) AS spend
				 FROM expenses WHERE LOWER(type)='fuel' AND strftime('%Y-%m', date)=? AND ${EXPENSE_PNL_FILTER}`
			).get(prevMk).spend;
			const fuelByTruckRows = db.prepare(
				`SELECT TRIM(COALESCE(truck_unit, '')) AS unit,
				        COALESCE(SUM(amount),0) AS spend, COALESCE(SUM(gallons),0) AS gallons, COUNT(*) AS fills
				 FROM expenses WHERE LOWER(type)='fuel' AND strftime('%Y-%m', date)=? AND ${EXPENSE_PNL_FILTER}
				 GROUP BY LOWER(TRIM(COALESCE(truck_unit, '')))
				 ORDER BY spend DESC`
			).all(monthParam);
			const fuel = {
				spend: Math.round(fuelTotals.spend),
				gallons: Math.round(fuelTotals.gallons * 10) / 10,
				fills: fuelTotals.fills,
				avgPricePerGallon: fuelTotals.gallons > 0
					? Math.round((fuelTotals.spend / fuelTotals.gallons) * 100) / 100 : 0,
				avgWeeklySpend: Math.round(fuelTotals.spend / weeksElapsed),
				prevMonthSpend: Math.round(prevFuelSpend),
				byTruck: fuelByTruckRows.map((r) => ({
					unit: r.unit || "(no truck)",
					spend: Math.round(r.spend),
					gallons: Math.round(r.gallons * 10) / 10,
					fills: r.fills,
					avgPricePerGallon: r.gallons > 0
						? Math.round((r.spend / r.gallons) * 100) / 100 : 0,
					avgWeeklySpend: Math.round(r.spend / weeksElapsed),
				})),
			};

			// Loads assigned to this month (revenue-bearing completed loads —
			// the same rows monthlyRevenue counted).
			const monthLoads = completedLoads.filter((l) => l.monthKey === monthParam);
			const monthLoadsSorted = [...monthLoads].sort((a, b) => b.amount - a.amount);
			const monthLoadRevenue = monthLoads.reduce((s, l) => s + l.amount, 0);
			const briefLoad = (l) => l
				? { loadId: l.loadId, driver: l.driver, amount: Math.round(l.amount), date: l.date }
				: null;
			const loads = {
				count: monthLoads.length,
				avgRevenuePerLoad: monthLoads.length
					? Math.round(monthLoadRevenue / monthLoads.length) : 0,
				avgLoadsPerDay: Math.round((monthLoads.length / elapsedDays) * 100) / 100,
				avgRevenuePerDay: Math.round(monthLoadRevenue / elapsedDays),
				highest: briefLoad(monthLoadsSorted[0] || null),
				lowest: briefLoad(monthLoadsSorted.length
					? monthLoadsSorted[monthLoadsSorted.length - 1] : null),
			};

			// Invoices whose Sat–Fri billing week OVERLAPS this month. Weekly
			// invoices straddle month boundaries, so this is the closest faithful
			// mapping to "this month's invoices" — the UI footnotes it. Rejected
			// invoices never count. `adjustment` carries admin deductions (−) /
			// bonuses (+), so invoiced = total_earnings + adjustment.
			//
			// ⚠️ `deleted_at = ''` IS NOT OPTIONAL, and its absence was a live money
			// bug. DELETE /api/invoices/:id is a SOFT delete — the row keeps its
			// `total_earnings` and `adjustment` and simply disappears from every list
			// — so without this predicate a deleted invoice still contributed to this
			// drill-down's `invoiced` and `adjustments` totals, and to the per-driver
			// rows built from them. Every other reader of this table filters it
			// (`GET /api/invoices`, buildPaymentReport(), the rename cascade's counts,
			// the restore clash probe, the weekly duplicate guard); this one did not,
			// so the Financials month detail was the single surface where a deleted
			// invoice still showed as billed.
			const monthStartStr = `${monthParam}-01`;
			const monthEndStr = `${monthParam}-${pad2(daysInMonth)}`;
			const invByDriver = {};
			db.prepare(
				`SELECT driver, COALESCE(total_earnings,0) AS earned, COALESCE(adjustment,0) AS adj
				 FROM invoices WHERE status != 'Rejected' AND deleted_at = '' AND week_start <= ? AND week_end >= ?`
			).all(monthEndStr, monthStartStr).forEach((r) => {
				const k = normalizeDriverName(r.driver);
				if (!k) return;
				if (!invByDriver[k]) invByDriver[k] = { count: 0, invoiced: 0, adjustments: 0 };
				invByDriver[k].count += 1;
				invByDriver[k].invoiced += r.earned + r.adj;
				invByDriver[k].adjustments += r.adj;
			});

			// Per-driver pay detail for the month. Same branch math as the
			// monthlyDriverPay loop above (fixed: month active days × per-truck
			// daily rate; percentage: max(0, month revenue − deductible) × pct),
			// so the rows sum back to summary.driverPay.
			const monthDriverRows = [];
			const monthDriverKeys = new Set([
				...Object.keys(driverMonthlyDays),
				...Object.keys(driverMonthlyRevenue),
				...Object.keys(invByDriver),
			]);
			for (const drv of monthDriverKeys) {
				const struct = payStructures[drv] || { payType: "fixed", payPercentage: 0 };
				const activeDays = driverMonthlyDays[drv]?.[monthParam]?.size || 0;
				const revenue = (driverMonthlyRevenue[drv] || {})[monthParam] || 0;
				let pay, dailyRate;
				if (struct.payType === "percentage") {
					const deductible = (expensesByDriverMonth[drv] || {})[monthParam] || 0;
					pay = Math.round((Math.max(0, revenue - deductible) * struct.payPercentage / 100) * 100) / 100;
					dailyRate = 0;
				} else {
					dailyRate = resolveDailyRate(struct.payDaily, trucksByDriver[drv]);
					pay = activeDays * dailyRate;
				}
				const inv = invByDriver[drv] || null;
				if (!activeDays && !revenue && !pay && !inv) continue;
				monthDriverRows.push({
					name: driverDisplayNames[drv] || drv,
					payType: struct.payType,
					payPercentage: struct.payType === "percentage" ? struct.payPercentage : 0,
					activeDays,
					dailyRate,
					pay: Math.round(pay),
					revenue: Math.round(revenue),
					// Revenue the driver generated minus their pay — the driver's
					// contribution margin for the month.
					margin: Math.round(revenue - pay),
					invoiceCount: inv ? inv.count : 0,
					invoicedTotal: inv ? Math.round(inv.invoiced) : 0,
					adjustments: inv ? Math.round(inv.adjustments) : 0,
					// Invoiced (incl. adjustments) − computed pay. Positive = the
					// driver has invoiced MORE than the active-day estimate for the
					// month (overage); negative = under. null when no invoice's
					// billing week overlaps this month.
					variance: inv ? Math.round(inv.invoiced - pay) : null,
				});
			}
			monthDriverRows.sort((a, b) => b.pay - a.pay);

			// Per-truck daily rates + activity for the month. truckDaySets is the
			// same completed-loads ∩ ELD-travel basis the annual per-truck pay
			// uses, partitioned to this calendar month.
			const perTruckMonth = [];
			for (const t of allTrucks) {
				const unitLower = (t.unit_number || "").toLowerCase();
				const daySet = truckDaySets[unitLower];
				let activeDays = 0;
				if (daySet) for (const d of daySet) { if (d.startsWith(monthParam)) activeDays++; }
				if (!activeDays) continue; // only trucks that worked this month
				const driverKey = normalizeDriverName(t.assigned_driver);
				const struct = (driverKey && payStructures[driverKey]) || { payType: "fixed", payPercentage: 0 };
				const driverDaily = Number(struct.payDaily) || 0;
				const dailyRateRaw = t.driver_pay_daily || 0;
				const dailyRate = resolveDailyRate(driverDaily, dailyRateRaw);
				perTruckMonth.push({
					unitNumber: t.unit_number,
					assignedDriver: t.assigned_driver || "—",
					activeDays,
					dailyRate,
					dailyRateIsDefault: driverDaily === 0 && dailyRateRaw === 0,
					driverPayType: struct.payType,
					estDriverPay: struct.payType === "percentage" ? null : activeDays * dailyRate,
				});
			}
			perTruckMonth.sort((a, b) => b.activeDays - a.activeDays);
			const ratedTrucks = perTruckMonth.filter((t) => t.driverPayType !== "percentage");
			const avgDailyRatePerTruck = ratedTrucks.length
				? Math.round(ratedTrucks.reduce((s, t) => s + t.dailyRate, 0) / ratedTrucks.length)
				: 0;

			const pctDelta = (curV, prevV) =>
				prevV > 0 ? Math.round(((curV - prevV) / prevV) * 1000) / 10 : null;
			monthDetail = {
				month: monthParam,
				isCurrentMonth,
				daysInMonth,
				elapsedDays,
				summary: cur,
				prevMonth: { ...prev, hasData: prevHasData },
				// Month-over-month deltas — the "winning / scaling / losing /
				// stagnant" signal. Pct deltas are null when the previous value
				// isn't a positive base (the UI falls back to absolute deltas).
				deltas: {
					revenue: cur.revenue - prev.revenue,
					revenuePct: pctDelta(cur.revenue, prev.revenue),
					totalExpenses: cur.totalExpenses - prev.totalExpenses,
					totalExpensesPct: pctDelta(cur.totalExpenses, prev.totalExpenses),
					driverPay: cur.driverPay - prev.driverPay,
					netProfit: cur.netProfit - prev.netProfit,
					fuelSpend: fuel.spend - fuel.prevMonthSpend,
				},
				expenseCategories,
				fuel,
				loads,
				drivers: monthDriverRows,
				trucks: perTruckMonth,
				avgDailyRatePerTruck,
			};
		}

		res.json({
			summary: {
				totalRevenue: Math.round(totalRevenue),
				totalExpenses: Math.round(totalExpenses),
				netProfit: Math.round(netProfit),
				biggestExpenseCategory: biggest,
				avgRatePerMile,
				totalMiles: fleetTotalMilesRounded,
				monthsOfOperation,
				// Row count (not unique load IDs) — consistent with totalRevenue
				// which also sums per-row, and matches /api/investor.completedJobs.
				completedLoadCount: completedRowCount,
				// Miles source breakdown: "road" if every coord row has a
				// cached Google Routes distance, "haversine" if none do,
				// "mixed" if some do. loadsWithCoords / completedRowCount =
				// coverage — non-100% means some completed loads have no
				// geocoded pickup/dropoff yet.
				milesSource: roadMilesCount > 0 && haversineMilesCount === 0
					? "road"
					: roadMilesCount === 0 ? "haversine" : "mixed",
				roadMilesLoadCount: roadMilesCount,
				haversineLoadCount: haversineMilesCount,
				loadsWithCoords,
				// Data-quality signal: completed revenue from rows with no
				// assigned driver. Non-zero means the sheet has attribution
				// gaps the investor should know about.
				unassignedRevenue: Math.round(unassignedGross),
				unassignedLoadCount,
				// Idle assets: onboarded trucks with zero completed loads. Their
				// fixed costs reduce netProfit, but it's parked-truck overhead, not
				// a freight loss — surfaced so the UI can explain the drag.
				idleTruckCount,
				idleOverhead: Math.round(idleOverhead),
			},
			expensesByCategory: reconciledExpenses,
			expensesByMonth,
			monthlyPerformance,
			perTruck,
			loads: { highest, lowest },
			drivers,
			monthDetail,
		});
	} catch (error) {
		console.error("GET /api/financials error:", error.message);
		res.status(500).json({ error: "Failed to load financials" });
	}
});

// GET /api/investor/config — merged investor config (global owner_id=0 rows
// overlaid by this investor's own overrides). Super Admin may target a specific
// investor via ?ownerId=N; an Investor is always scoped to their own id. Mirrors
// the PUT handler's auth + ownerId resolution and the /api/investor read pattern
// (per-investor rows override globals), so e.g. investor_split_pct returns the
// per-investor value when set, else the seeded global "50".
app.get("/api/investor/config", requireRole("Super Admin", "Investor"), (req, res) => {
	try {
		const user = req.session.user;
		const targetOwnerId = user.role === "Super Admin"
			? parseInt(req.query.ownerId) || 0
			: user.id;
		const config = {};
		db.prepare("SELECT key, value FROM investor_config WHERE owner_id = 0")
			.all().forEach((r) => (config[r.key] = r.value));
		if (targetOwnerId !== 0) {
			db.prepare("SELECT key, value FROM investor_config WHERE owner_id = ?")
				.all(targetOwnerId).forEach((r) => (config[r.key] = r.value)); // override globals
		}
		res.json(config);
	} catch (error) {
		console.error("Error reading investor config:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// PUT /api/investor/config — Admin: update investor config
app.put("/api/investor/config", requireRole("Super Admin", "Investor"), (req, res) => {
	try {
		const user = req.session.user;
		const targetOwnerId = user.role === "Super Admin"
			? parseInt(req.query.ownerId) || 0
			: user.id;
		const updates = req.body; // { key: value, ... }
		const stmt = db.prepare(
			"INSERT OR REPLACE INTO investor_config (owner_id, key, value) VALUES (?, ?, ?)",
		);
		const updateMany = db.transaction((entries) => {
			for (const [k, v] of entries) stmt.run(targetOwnerId, k, String(v));
		});
		updateMany(Object.entries(updates));
		res.json({ success: true });
	} catch (error) {
		console.error("Error updating investor config:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// ============================================================
// EXPENSE & MAINTENANCE TRACKING
// ============================================================

// GET /api/expenses/all — All expenses (all types) for dispatcher/admin.
// Optional filters (all additive): driver, type, status, truck (legacy) plus
// from/to (YYYY-MM-DD), state (2-letter), region (Census division name →
// resolveRegionToStates), and q (free-text across vendor/description/city).
app.get("/api/expenses/all", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		const { driver, type, status, truck, from, to, state, region, q } = req.query;
		// posted_period is exposed so a receipt that was redirected out of a closed
		// month is visible as such in the admin list — otherwise a March-dated row
		// silently counting in August looks like a bug rather than the rule.
		let sql = "SELECT id, timestamp, driver, load_id, type, amount, description, date, photo_data, status, gallons, odometer, truck_unit, owner_id, location_city, location_state, vendor, vendor_normalized, location_lat, location_lng, location_source, receipt_details, posted_period, strftime('%Y-%m-%dT%H:%M:%SZ', created_at) AS created_at FROM expenses";
		const conditions = [];
		const params = [];
		if (driver) { conditions.push("LOWER(driver) = ?"); params.push(driver.toLowerCase()); }
		if (type) { conditions.push("LOWER(type) = ?"); params.push(type.toLowerCase()); }
		if (status) { conditions.push("LOWER(status) = ?"); params.push(status.toLowerCase()); }
		if (truck) { conditions.push("LOWER(truck_unit) = ?"); params.push(String(truck).toLowerCase()); }
		if (from) {
			if (!/^\d{4}-\d{2}-\d{2}$/.test(from)) return res.status(400).json({ error: "Invalid date" });
			conditions.push("date >= ?"); params.push(from);
		}
		if (to) {
			if (!/^\d{4}-\d{2}-\d{2}$/.test(to)) return res.status(400).json({ error: "Invalid date" });
			conditions.push("date <= ?"); params.push(to);
		}
		const stateUc = state ? String(state).trim().toUpperCase() : "";
		if (region) {
			const regionStates = resolveRegionToStates(String(region));
			if (!regionStates) return res.status(400).json({ error: "Unknown region" });
			// If BOTH state and region are given, the state is unioned into the list.
			const list = [...new Set(regionStates.map((s) => String(s).toUpperCase()).concat(stateUc ? [stateUc] : []))];
			if (list.length) {
				conditions.push(`UPPER(location_state) IN (${list.map(() => "?").join(",")})`);
				params.push(...list);
			}
		} else if (stateUc) {
			conditions.push("UPPER(location_state) = ?");
			params.push(stateUc);
		}
		if (q) {
			const qSafe = q.toString().trim().slice(0, 80);
			if (qSafe) {
				// Escape LIKE wildcards so a literal % or _ in the search term
				// can't blow the match wide open.
				const term = "%" + qSafe.replace(/[\\%_]/g, (m) => "\\" + m) + "%";
				conditions.push("(vendor LIKE ? ESCAPE '\\' OR vendor_normalized LIKE ? ESCAPE '\\' OR description LIKE ? ESCAPE '\\' OR location_city LIKE ? ESCAPE '\\')");
				params.push(term, term, term, term);
			}
		}
		if (conditions.length) sql += " WHERE " + conditions.join(" AND ");
		sql += " ORDER BY id DESC";
		const expenses = db.prepare(sql).all(...params).map((e) => ({ ...e, receipt_details: parseReceiptDetails(e.receipt_details) }));
		res.json({ expenses });
	} catch (err) {
		console.error("Error fetching all expenses:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// GET /api/expenses/receipts-download — Super Admin downloads all receipts
// for a specific truck within a date range as a ZIP bundle. Returns both the
// receipt files (named by date + expense ID + load ID) and a manifest.csv
// with all metadata. Used for monthly accounting / tax review.
app.get("/api/expenses/receipts-download", requireRole("Super Admin"), (req, res) => {
	try {
		const { truck, from, to } = req.query;
		if (!truck || !from || !to) {
			return res.status(400).json({ error: "truck, from, and to query params are required (YYYY-MM-DD)" });
		}
		// Basic date format sanity check (YYYY-MM-DD). Anything else gets rejected.
		if (!/^\d{4}-\d{2}-\d{2}$/.test(from) || !/^\d{4}-\d{2}-\d{2}$/.test(to)) {
			return res.status(400).json({ error: "Dates must be YYYY-MM-DD" });
		}
		if (to < from) {
			return res.status(400).json({ error: "'to' must be on or after 'from'" });
		}
		const expenses = db.prepare(
			`SELECT id, date, driver, load_id, type, amount, description, photo_data, gallons, odometer
			 FROM expenses
			 WHERE LOWER(truck_unit) = LOWER(?) AND date >= ? AND date <= ?
			 ORDER BY date ASC, id ASC`
		).all(truck, from, to);

		if (expenses.length === 0) {
			return res.status(404).json({ error: "No expenses found for that truck and date range" });
		}

		// Stream a zip directly to the response. Files referenced in
		// photo_data live under /uploads/expense-receipts/ — any row that
		// somehow points outside that directory is skipped for safety.
		const archiver = require("archiver");
		const safeTruck = truck.replace(/[^a-zA-Z0-9._-]/g, "_");
		const filename = `${safeTruck}-receipts-${from}-to-${to}.zip`;
		res.setHeader("Content-Type", "application/zip");
		res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);

		const archive = archiver("zip", { zlib: { level: 9 } });
		// Error handler has to be installed BEFORE pipe() so early failures
		// surface as a JSON response. Once pipe() has flushed any bytes to
		// the client the headers are already sent, so a mid-stream failure
		// can only produce a truncated zip — we log it, but the client has
		// no clean way to know. Acceptable for a Super-Admin-only export.
		archive.on("error", (err) => {
			console.error("Receipt zip error:", err.message);
			if (!res.headersSent) res.status(500).json({ error: "Failed to build receipt archive" });
		});
		archive.pipe(res);

		// Manifest CSV — reviewer can open in Excel to reconcile the bundle.
		// Escaping (quoting + the formula-injection guard) lives in lib/csv.js so
		// this export and the completed-loads export can never drift apart.
		const manifestRows = [["date", "expense_id", "driver", "load_id", "type", "amount", "description", "file_name"]];
		const receiptsDir = path.join(__dirname, "uploads", "expense-receipts");
		let attachedCount = 0;
		for (const exp of expenses) {
			const p = exp.photo_data || "";
			let fileName = "";
			// Only accept photo_data rows that point at our expense-receipts
			// directory. This prevents path traversal (../../etc/passwd) or
			// any stray absolute path that might have been stored before the
			// disk-migration landed.
			if (p && p.startsWith("/uploads/expense-receipts/")) {
				const srcPath = path.join(__dirname, p.replace(/^\//, ""));
				if (srcPath.startsWith(receiptsDir) && fs.existsSync(srcPath)) {
					const ext = path.extname(srcPath).toLowerCase() || ".bin";
					fileName = `${exp.date}_exp-${exp.id}${exp.load_id ? "_load-" + exp.load_id : ""}${ext}`.replace(/[^a-zA-Z0-9._-]/g, "_");
					archive.file(srcPath, { name: `receipts/${fileName}` });
					attachedCount++;
				}
			}
			// CSV row: always include, so rows without a receipt file are still accounted for.
			manifestRows.push([
				exp.date, exp.id, exp.driver, exp.load_id, exp.type,
				Number(exp.amount || 0).toFixed(2),
				exp.description, fileName || "(no file)"
			]);
		}
		archive.append(csvRows(manifestRows), { name: "manifest.csv" });
		archive.finalize();
		console.log(`Receipt zip: ${truck} ${from}..${to} — ${expenses.length} rows, ${attachedCount} files`);
	} catch (err) {
		console.error("GET /api/expenses/receipts-download error:", err.message);
		if (!res.headersSent) res.status(500).json({ error: "Failed to download receipts" });
	}
});

// Optional free-text note on an approve/reject, recorded on the audit row.
//
// WHY IT IS OPTIONAL AND WHY IT LIVES IN ONE PLACE. Rejecting an expense removes
// money from the P&L and therefore from an investor's payout for that month, and
// the Data Issues page voids DUPLICATE receipts through the bulk route — so
// "which copy did we keep, and why" is the question asked afterwards, and until
// now nothing recorded even that a flip happened. It is OPTIONAL because the
// existing clients do not send it and a required field would break them; a
// missing reason simply produces the same audit line as before, never a fake one.
//
// ⚠️ THE CLIENT'S VOID CONFIRM CURRENTLY TELLS THE USER THERE IS NO NOTE
// ("recorded only as the receipt's own status changing to Rejected … there is no
// separate note"). That copy was CORRECT when written and is now understating
// what the server can do — but it must not be changed to promise a reason until
// the client actually collects one, because a page whose whole purpose is that a
// check never claims more than it did cannot afford to claim a stored note it
// never sent. Server-side capability first; client copy follows.
//
// Collapsed to one line and bounded: audit details are read by humans and
// exported, and this is free text from a form.
//
// ⚠️ scrubPurgeMarker() FOR THE SAME REASON auditText() RUNS IT, and this was the
// one caller-text capper in the file that did not. Harmless as it stands — the
// bulk route appends this AFTER its real `[CODE]`, so a forged marker inside it
// can neither remove that row's purge exemption nor win parsePeriodRefusalDetail's
// first-match — but "harmless because of where the caller happens to splice it"
// is a property of the two call sites, not of this function, and the next caller
// inherits the gap rather than the guarantee. One call makes the invariant
// uniform: no caller text anywhere reaches audit_trail.details carrying `[PERIOD`.
// Byte-identical on every real reason; only a string containing that literal moves.
const EXPENSE_STATUS_REASON_MAX = 300;
function expenseStatusReason(body) {
	const raw = body && typeof body.reason === "string" ? body.reason : "";
	return scrubPurgeMarker(raw).replace(/[\r\n\t]+/g, " ").trim().slice(0, EXPENSE_STATUS_REASON_MAX);
}

// PUT /api/expenses/:id/status — Approve or reject an expense
app.put("/api/expenses/:id/status", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		const id = parseInt(req.params.id);
		const { status } = req.body;
		if (!["Approved", "Rejected", "Pending"].includes(status)) {
			return res.status(400).json({ error: "Status must be Approved, Rejected, or Pending" });
		}
		// `status` is selected for the audit line below (the from-value); the other
		// three feed expensePostedPeriod(), which fails closed without them.
		const expense = db.prepare("SELECT id, date, status, created_at, posted_period FROM expenses WHERE id = ?").get(id);
		if (!expense) return res.status(404).json({ error: "Expense not found" });

		// Status is not cosmetic: EXPENSE_PNL_FILTER drops 'Rejected' from every
		// P&L, so flipping one moves the month it is posted to. On a finalized
		// month that would silently contradict a statement already issued — and
		// clearing a receipt backlog in one sitting could move several closed
		// months at once. Unlike a receipt arriving late, an approve/reject is
		// discretionary and has no deadline, so refusing is safe: do it before the
		// period closes, or book the correction as a payout adjustment.
		//
		// periodWriteLocked, not isLocked: an unreadable lock table makes every
		// month answer "open", which turns this guard off without a trace. The
		// paragraph above is also the justification for failing closed — a status
		// flip has no deadline, so refusing one until the lock table can be read
		// costs a retry, while permitting it can restate a month whose statement
		// has already been issued.
		const expPeriod = expensePostedPeriod(expense);
		if (periodWriteLocked(expPeriod)) {
			const unreadable = !periodLocksReadable();
			// ⚠️ THE REFUSAL IS AUDITED, AND UNTIL NOW IT WAS THE ONLY OUTCOME OF THIS
			// ROUTE THAT WAS NOT. The success path below records the flip; this branch
			// returned a 409 and wrote nothing, so audit_trail could not tell "nobody
			// tried to void that receipt" from "someone tried and the server refused".
			// That distinction is the whole reason a refusal row exists, and it is the
			// one asked for afterwards: this is the route the docs point people at for
			// voiding a single receipt, and a Rejected receipt leaves the P&L
			// (EXPENSE_PNL_FILTER) and therefore an investor's payout for that month.
			// Same gap and same fix as PUT /api/expenses/bulk-status, its batch twin.
			//
			// logAuditRefusal, not logAudit: both codes are in
			// UNCOALESCED_REFUSAL_CODES (asserted at boot), so this is byte-identical
			// to logAudit today while stating the intent — and a future non-period
			// refusal audited on this route inherits the coalescing window without
			// anyone having to remember. If either code were ever dropped from that
			// set, a second operator refused within 60s would write nothing and this
			// bug would be back: the coalesce key is the ACCOUNT, and `super_admin` is
			// a shared login, so "a different person" does not produce a different key.
			//
			// ⚠️ NOT added to PURGEABLE_REFUSAL_ACTIONS. It would qualify on that
			// list's stated invariant — this returns before any database write — but
			// adding it would purge exactly nothing (every row it writes carries a
			// `[PERIOD_` code, which the purge's own detail filter exempts) while
			// implying these rows are disposable. It also cannot flood: it needs a
			// finalized month or a broken lock table on a Super Admin / Dispatcher
			// route. Revisit only if a cheap, on-demand refusal is ever audited under
			// this same action.
			//
			// entity_id is the expense id, matching the success line below. The reason
			// is carried because stated intent is MORE useful on a refusal than on a
			// success — it is the record of what someone was trying to do to a settled
			// month. `super_admin` is a shared login, so this identifies the account
			// and session, never an individual.
			const refusalCode = unreadable ? "PERIOD_LOCK_UNREADABLE" : "PERIOD_FINALIZED";
			const blockedReason = expenseStatusReason(req.body);
			logAuditRefusal(req, "update_expense_status_blocked", "expense", id,
				`status ${expense.status || "Pending"} -> ${status} WITHHELD (${expense.date || "no date"})` +
				` [${refusalCode}] period=${expPeriod || "unknown"} — nothing was written` +
				(blockedReason ? ` — reason: ${blockedReason}` : ""),
				refusalCode);
			return res.status(409).json({
				// Two causes, two sentences, two remedies — "reopen the period" is
				// useless advice when the period_locks table itself is the problem.
				error: unreadable
					? "The period lock table could not be read, so this expense's month cannot be confirmed open. Status changes are held until that is fixed."
					: `This expense is booked to ${periodLabel(expPeriod)}, which is finalized. Reopen the period, or record the correction as a payout adjustment.`,
				code: unreadable ? "PERIOD_LOCK_UNREADABLE" : "PERIOD_FINALIZED",
				period: expPeriod,
			});
		}

		const prevStatus = expense.status || "Pending";
		db.prepare("UPDATE expenses SET status = ? WHERE id = ?").run(status, id);
		// ⚠️ THIS IS A MONEY WRITE AND IT USED TO LEAVE NO TRACE. Rejecting an
		// expense removes it from every P&L (EXPENSE_PNL_FILTER) and therefore from
		// the investor payout deduction for that month — the same class of change as
		// PATCH /api/expenses/:id/vendor, which has always audited. It is also the
		// remedy this feature tells people to use on a duplicate ping, so "who voided
		// which copy, and when" is exactly the question that gets asked afterwards.
		// `super_admin` is a shared login, so the row identifies a session, not a
		// person — still strictly more than the nothing that was recorded before.
		const reason = expenseStatusReason(req.body);
		logAudit(req, "update_expense_status", "expense", id,
			`status ${prevStatus} -> ${status} (${expense.date || "no date"}, period ${expPeriod || "unknown"})` +
			(reason ? ` — reason: ${reason}` : ""));
		notifyChange("expenses");
		res.json({ success: true });
	} catch (err) {
		console.error("Error updating expense status:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// PATCH /api/expenses/:id/location — set/correct the merchant City/State on an
// expense (back-office correction; drivers capture it at submit time via the
// OCR prefill on POST /api/expenses). Same validation as the POST route: city
// is trimmed to <=60 chars, state must be a 2-letter US code or it's cleared.
app.patch("/api/expenses/:id/location", requireRole("Super Admin", "Dispatcher"), async (req, res) => {
	try {
		const id = parseInt(req.params.id);
		if (!id || id <= 0) return res.status(400).json({ error: "Invalid expense id" });
		const { city, state } = req.body || {};
		const safeCity = (city || "").toString().trim().slice(0, 60);
		const rawState = (state || "").toString().trim().toUpperCase();
		const safeState = /^[A-Z]{2}$/.test(rawState) ? rawState : "";
		const expense = db.prepare("SELECT id FROM expenses WHERE id = ?").get(id);
		if (!expense) return res.status(404).json({ error: "Expense not found" });
		db.prepare("UPDATE expenses SET location_city = ?, location_state = ? WHERE id = ?").run(safeCity, safeState, id);
		// Best-effort: refresh the coordinates for the corrected City/State so
		// map pins + region rollups track the fix. Never fails the update itself.
		// A cleared/partial location (or a geocode miss) must also clear the old
		// coordinates — a stale pin contradicting the corrected state is worse
		// than no pin.
		try {
			let coords = null;
			if (safeCity && safeState && GEOCODE_CITY_RE.test(safeCity) && spendGeocodeBudget()) {
				coords = await geocodeAddress(`${safeCity}, ${safeState}`);
			}
			if (coords) {
				db.prepare("UPDATE expenses SET location_lat = ?, location_lng = ?, location_source = 'geocode' WHERE id = ?").run(coords.lat, coords.lng, id);
			} else {
				db.prepare("UPDATE expenses SET location_lat = NULL, location_lng = NULL, location_source = '' WHERE id = ?").run(id);
			}
		} catch (e) {
			console.warn("expense location geocode skipped:", e.message);
		}
		notifyChange("expenses");
		res.json({ success: true, city: safeCity, state: safeState });
	} catch (err) {
		console.error("Error updating expense location:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// PATCH /api/expenses/:id/vendor — set/correct the merchant on an expense
// (back-office correction; drivers capture it at submit time via the OCR
// prefill on POST /api/expenses). Empty vendor is allowed and clears the
// field; vendor_normalized is always recomputed via lib/expense-analytics so
// vendor rollups stay canonical.
app.patch("/api/expenses/:id/vendor", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		const id = parseInt(req.params.id);
		if (!id || id <= 0) return res.status(400).json({ error: "Invalid expense id" });
		const { vendor } = req.body || {};
		const safeVendor = (vendor || "").toString().trim().slice(0, 80);
		const vendorNormalized = normalizeVendor(safeVendor);
		const result = db.prepare("UPDATE expenses SET vendor = ?, vendor_normalized = ? WHERE id = ?").run(safeVendor, vendorNormalized, id);
		if (result.changes === 0) return res.status(404).json({ error: "Expense not found" });
		logAudit(req, "update_expense_vendor", "expense", id, `vendor -> ${safeVendor || "(cleared)"}`);
		notifyChange("expenses");
		res.json({ success: true, vendor: safeVendor, vendorNormalized });
	} catch (err) {
		console.error("Error updating expense vendor:", err.message);
		res.status(500).json({ error: err.message });
	}
});

// PUT /api/expenses/bulk-status — Approve/Reject/Pending many expenses in one
// call (2026-06-11 owner meeting: "multi-select and approve instead of one by
// one"). Same role gate + status whitelist as the single-row endpoint above.
// ids are validated to positive integers and both queries are parameterized
// IN (...) statements; one notifyChange covers the whole batch.
const BULK_STATUS_MAX_IDS = 200;
app.put("/api/expenses/bulk-status", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		const { ids, status } = req.body || {};
		if (!["Approved", "Rejected", "Pending"].includes(status)) {
			return res.status(400).json({ error: "Status must be Approved, Rejected, or Pending" });
		}
		if (!Array.isArray(ids) || ids.length === 0) {
			return res.status(400).json({ error: "ids must be a non-empty array of expense ids" });
		}
		if (ids.length > BULK_STATUS_MAX_IDS) {
			return res.status(400).json({ error: `Too many ids — max ${BULK_STATUS_MAX_IDS} per request` });
		}
		const numericIds = [
			...new Set(ids.map((v) => (typeof v === "number" || typeof v === "string" ? Number(v) : NaN))),
		];
		if (!numericIds.every((n) => Number.isInteger(n) && n > 0)) {
			return res.status(400).json({ error: "Every id must be a positive integer" });
		}
		const ph = numericIds.map(() => "?").join(",");
		const existing = db
			.prepare(`SELECT id, date, created_at, posted_period FROM expenses WHERE id IN (${ph})`)
			.all(...numericIds);
		if (existing.length === 0) {
			return res.status(404).json({ error: "No matching expenses found" });
		}

		// Same rule as the single-row route, but a batch of 50 shouldn't fail
		// wholesale because two rows sit in a closed month. Update what's open,
		// report what wasn't, and name the periods — a silent skip on a bulk
		// approve reads as "all done" when it wasn't.
		//
		// ⚠️ ONE PREDICATE, NOT TWO SPELLINGS OF ONE. This loop used to hand-inline
		// `!lockReadable || isLocked(p)`, which is the definition of
		// periodWriteLocked() written out longhand — the same behaviour as the
		// single-row route above, expressed differently, so the two could silently
		// drift the next time either rule moved. They now call the same function,
		// which is also the one carrying the argument for why a write guard reads
		// "cannot tell" as "assume closed" while isLocked() must not.
		//
		// `lockReadable` is still probed ONCE for the batch, but only to DESCRIBE
		// the outcome (the response must not call a month "finalized" when the table
		// could not be read). It no longer participates in the decision, so there is
		// no second copy of the rule to keep in step. Probing once also matters on a
		// broken table, where a per-row probe re-compiles a failing statement per id.
		const lockReadable = periodLocksReadable();
		const lockedRows = [];
		const existingIds = [];
		for (const e of existing) {
			const p = expensePostedPeriod(e);
			if (periodWriteLocked(p)) lockedRows.push({ id: e.id, period: p });
			else existingIds.push(e.id);
		}

		// Both hoisted above the branch below, because both are now needed on the
		// refusal path as well as the success one. `expenseStatusReason` is pure, so
		// the success audit line is unchanged by the move.
		const reason = expenseStatusReason(req.body);
		const lockedPeriods = [...new Set(lockedRows.map((r) => r.period))].sort();

		let changed = 0;
		if (existingIds.length) {
			const updatePh = existingIds.map(() => "?").join(",");
			changed = db
				.prepare(`UPDATE expenses SET status = ? WHERE id IN (${updatePh})`)
				.run(status, ...existingIds).changes;
			// ⚠️ THIS IS THE ROUTE THAT MATTERS MOST, not the single-row one. The Data
			// Issues page voids DUPLICATE receipts through THIS endpoint — so the
			// operation "an admin rejects a duplicate, removing money from the P&L and
			// changing an investor's payout" was, until this line, writing no audit
			// trail whatsoever. Same reasoning as PATCH /api/expenses/:id/vendor,
			// which has always audited a strictly smaller change.
			//
			// ONE row for the batch rather than N — BULK_STATUS_MAX_IDS is 200, and
			// 200 audit rows per click would bury the signal audit_trail exists to
			// preserve (the whole table is ~1,300 rows over four months). The id list
			// is included in full, so "who voided expense #X" is still greppable by
			// id; entity_id carries the count because no single id owns the row.
			//
			// `changed` and `existingIds` are BOTH reported because they can differ:
			// a row already carrying the target status is updated to the same value
			// and SQLite still counts it, but a row that vanished between the SELECT
			// and the UPDATE does not — so the id list is what was attempted and
			// `changed` is what the database confirmed.
			logAudit(req, "bulk_update_expense_status", "expense", String(changed),
				`status -> ${status} on ${changed} of ${existingIds.length} expense(s): ${existingIds.join(",")}` +
				(reason ? ` — reason: ${reason}` : ""));
			notifyChange("expenses");
		}

		// ⚠️ THE WITHHELD ROWS GET THEIR OWN AUDIT LINE, AND THE WHOLESALE CASE IS WHY.
		// The success audit above sits inside `if (existingIds.length)`, so a request
		// in which the server withheld EVERY row recorded nothing at all — not the
		// attempt, not the refusal, not the reason. That is not an exotic state: the
		// Data Issues void path sends ids whose `locked` flag is a snapshot from the
		// last fuel-analytics read, so a month closing between that read and the click
		// is an ordinary race. It also left audit_trail unable to distinguish "nobody
		// tried" from "someone tried and was refused wholesale", which is the one
		// distinction a refusal row exists to preserve.
		//
		// A PARTIAL withhold gets one too, deliberately. Today a request that updates
		// 3 of 5 audits only the 3, so the batch reads afterwards as a clean success
		// and the two refused ids — the ones that tried to restate a settled month,
		// i.e. the highest-value rows in this table per UNCOALESCED_REFUSAL_CODES —
		// leave no trace at all. The two outcomes are recorded as two rows rather than
		// folded into one because this file's naming split is load-bearing: a refusal
		// is always a DISTINCT action from its success (`cancel_blocked` vs
		// `cancel_load`), and both the purge and the coalescer key on the action. It
		// also keeps entity_id honest — the success row's count is what was written,
		// this row's is what was withheld; one merged row could only lie about one of
		// them. Cost is one extra row per REQUEST, not per id, and only when something
		// was actually withheld.
		//
		// logAuditRefusal, not logAudit: both codes below are in
		// UNCOALESCED_REFUSAL_CODES, so this is byte-identical to logAudit today, but
		// it states the intent and a future non-period refusal on this route inherits
		// the coalescing window without anyone having to remember.
		//
		// ⚠️ NOT added to PURGEABLE_REFUSAL_ACTIONS, and it must not be. That list's
		// stated invariant is that its entries are "written only on a path that
		// returns before any sheet or database write" — on a partial withhold this row
		// is written on a path that DID write, so it fails the invariant by
		// construction. Adding it would also buy nothing: every row this action writes
		// carries a `[PERIOD_` code, which the purge's own detail filter already
		// exempts. And it cannot flood — it needs a locked month (or a broken lock
		// table) on a Super Admin / Dispatcher route.
		//
		// entity_id carries the COUNT and details the id list, matching the success
		// line above — no single id owns the row. `super_admin` is a shared login, so
		// this identifies the account and session, never an individual.
		if (lockedRows.length) {
			// PERIOD_LOCK_UNREADABLE normally implies a wholesale refusal (an
			// unreadable table makes periodWriteLocked() true for every row), but the
			// probe is separate from the per-row check, so the count is reported as
			// measured rather than assumed.
			const refusalCode = lockReadable ? "PERIOD_FINALIZED" : "PERIOD_LOCK_UNREADABLE";
			const blockedIds = lockedRows.map((r) => r.id);
			// The periods are recorded on BOTH codes, unlike the response, which empties
			// `finalizedPeriods` when the table is unreadable. Those are different jobs:
			// the response must not CLAIM a month-end that was never confirmed, while
			// the audit's job is to reconstruct what was attempted, and "which months
			// the withheld rows fell in" is part of that. The code sits beside them, so
			// `periods=` is never read as an assertion that they are closed.
			logAuditRefusal(req, "bulk_update_expense_status_blocked", "expense", String(blockedIds.length),
				`status -> ${status} WITHHELD on ${blockedIds.length} of ${existing.length} expense(s): ${blockedIds.join(",")}` +
				` [${refusalCode}]${lockedPeriods.length ? ` periods=${lockedPeriods.join(",")}` : ""}` +
				(existingIds.length
					? ` — partial: ${changed} other row(s) updated`
					: " — nothing was written") +
				(reason ? ` — reason: ${reason}` : ""),
				refusalCode);
		}

		res.json({
			success: true,
			updated: changed,
			skipped: numericIds.length - existing.length,
			...(lockedRows.length ? {
				skippedFinalized: lockedRows.length,
				// Named `finalizedPeriods` for the existing client, but only populated
				// when they really are finalized: with the lock table unreadable these
				// are just the months the withheld rows happen to fall in, and their
				// lock state is unknown. Calling them finalized would report a
				// month-end that never happened.
				finalizedPeriods: lockReadable ? lockedPeriods : [],
				...(lockReadable ? {} : { periodLockUnreadable: true }),
				message: lockReadable
					? `${changed} updated. ${lockedRows.length} skipped — ${lockedPeriods.map(periodLabel).join(", ")} ${lockedPeriods.length === 1 ? "is" : "are"} finalized.`
					: `${changed} updated. ${lockedRows.length} skipped — the period lock table could not be read, so no month could be confirmed open.`,
			} : {}),
		});
	} catch (err) {
		console.error("Error bulk-updating expense status:", err.message);
		res.status(500).json({ error: "Failed to update expense statuses" });
	}
});

// GET /api/expenses/fuel-analytics — Fuel cost analytics + compliance
app.get("/api/expenses/fuel-analytics", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		const config = {};
		db.prepare("SELECT key, value FROM investor_config").all()
			.forEach((r) => (config[r.key] = r.value));
		const savingsTarget = parseFloat(config.fuel_savings_target_pct) || 15;

		// All fuel expenses
		const fuelExpenses = db.prepare(
			`SELECT * FROM expenses WHERE LOWER(type) = 'fuel' AND ${EXPENSE_PNL_FILTER} ORDER BY date DESC`
		).all();

		const totalFuelSpend = fuelExpenses.reduce((s, e) => s + (e.amount || 0), 0);
		const totalGallons = fuelExpenses.reduce((s, e) => s + (e.gallons || 0), 0);
		const avgCostPerGallon = totalGallons > 0 ? totalFuelSpend / totalGallons : 0;

		// Odometer provenance, read from the stored expenses.odometer_source column
		// the backfill stamps — NOT inferred by comparing the receipt's odometer to
		// its linked episode's. The inference is wrong in a case that really
		// happens: the re-match pass clears and rebuilds links every sweep while the
		// odometer backfill is write-once and never cleared, so an episode that
		// later loses its match would leave a system-written number with no link,
		// and the comparison would report it as hand-typed. The UI prints a
		// "receipt" vs "ELD" chip off this value and shows NO chip when it is null,
		// so getting it wrong puts a derived number on the paper.
		//
		// A row with an odometer but no stamp predates the backfill, which means a
		// person entered it.
		const odometerSourceFor = (e) => {
			if (!(e.odometer > 0)) return null;                        // nothing to attribute
			return e.odometer_source === "telemetry" ? "telemetry" : "receipt";
		};

		// Gallons provenance, same contract as the odometer one above and read from
		// the same kind of stored stamp: 'ocr' = this server read the volume off the
		// receipt image and cross-checked it against the row's own total; 'entered' =
		// a person typed it (every row logged before the recovery route existed, and
		// every manual entry after it — POST /api/expenses does not stamp the column).
		//
		// Surfaced rather than kept internal ON PURPOSE. A recovered gallon count
		// flows straight into cost-per-gallon, cost-per-mile and the tank-to-tank MPG
		// a driver plans a fuel stop against; if it is indistinguishable from a
		// hand-keyed one, nobody auditing a number that looks wrong can tell which
		// kind of wrong they are looking at, and the whole point of stamping it is
		// lost at the last step.
		//
		// ⚠️ THIS IS PROVENANCE, NOT A TRUST RATING — label it that way in any UI.
		// 'ocr' means "read off the receipt image", NOT "verified". The amount gate
		// proves the reading is of THAT receipt; it cannot prove the receipt is
		// genuine, because on a driver-logged expense the same person supplies both
		// the image and the amount it is checked against. A doctored pair passes by
		// construction. That is not a privilege gain (a driver can already type any
		// gallons figure at insert time, and this route only touches rows where
		// gallons <= 0) and it cannot move settlement dollars, which key on `amount`
		// — but a chip reading "verified" would launder a hand-made number into a
		// machine-checked one. "Read from receipt" is the honest wording.
		const gallonsSourceFor = (e) => {
			if (!(e.gallons > 0)) return null;                         // nothing to attribute
			return e.gallons_source === "ocr" ? "ocr" : "entered";
		};

		// Odometer-based cost per mile.
		//
		// ⚠️ CHANGED 2026-08-07, and the number on screen will move. This used to
		// take (max odometer − min odometer) across ALL fuel receipts, fleet-wide.
		// That was survivable only because exactly 2 of 126 receipts carried an
		// odometer, so it was really (96538 − 1) — one junk reading minus another —
		// divided into two receipts' spend, i.e. $0.00/mi. Now that matched
		// receipts get a real odometer backfilled from the ELD, the same formula
		// would subtract one truck's mileage from another's (#302 reads ~82k, #33
		// ~865k, #2372 ~993k) and print a confident, meaningless number.
		//
		// Two guards, and BOTH are needed:
		//   1. Group by truck, so a span is always one truck's own mileage.
		//   2. Use only odometers we can vouch for. A bare sanity floor is not
		//      enough: the junk 96538 on a truck that actually reads 992938 clears
		//      any floor and, being the minimum, inflates that truck's span by
		//      ~896,000 miles on its own.
		//
		// ⚠️ HOW GUARD 2 IS DECIDED CHANGED 2026-08-07, and the reason matters more
		// than the rule. It used to reject a hand-typed reading when a fuel_events
		// row LINKED to that receipt — i.e. "an episode contradicts it". That test
		// depended on sweep history, not on the data:
		//   · the link for receipt #31 is ~88 days old, so the rolling 45-day match
		//     window never re-creates it, and the matcher CLEARS links inside its
		//     window on every run;
		//   · so the exclusion rested entirely on a one-time 95-day first-run
		//     backfill, and evaporated whenever the seed had not run (deploy day),
		//     `firstEver` was false because fuel_event_alerts was non-empty, someone
		//     called POST /api/admin/fuel-events/run (45 days by default), or
		//     fuel_events was emptied — which is exactly what a DB restore does.
		// Two agents measured the SAME database as $0.32/mi and $0.00/mi purely on
		// which sweep had run: 19,425 mi vs 897,010 mi of basis. A figure on a
		// finance page cannot depend on that.
		//
		// The rule now is a PHYSICAL PLAUSIBILITY BOUND, which needs no history at
		// all: a truck's odometer cannot move faster than a truck can be driven, so
		// two readings are mutually consistent only if their difference fits in the
		// days between them. Chosen over "contradict against a nearby episode"
		// precisely because it still holds with fuel_events EMPTY. Consequence, and
		// it is the point: cost/mile is now a pure function of the `expenses` rows
		// (odometer, odometer_source, date, truck_unit) — the same data yields the
		// same figure no matter what has swept before, and fuel_events is not read
		// here at all.
		//
		// The bound is deliberately loose — an order of magnitude above real duty
		// cycles — because it exists to catch a junk reading (96,538 against
		// 992,265: 10× out), not to audit hard miles. 1200 mi/day is a team-driven
		// ceiling; solo runs ~700 under HOS. The +1 day is the same-day allowance:
		// two fills on one calendar date can legitimately be a full day's driving
		// apart, so a same-day pair gets a whole day's slack rather than zero.
		const ODOMETER_SANITY_FLOOR = 1000;
		const ODO_MAX_MILES_PER_DAY = 1200;
		const odoDay = (s) => {
			const t = Date.parse(String(s || "").slice(0, 10) + "T12:00:00Z");
			return Number.isFinite(t) ? t / 86400000 : null;
		};
		const odoPlausibleGap = (dayA, dayB) =>
			ODO_MAX_MILES_PER_DAY * (Math.abs(dayA - dayB) + 1);
		// Symmetric on purpose: which of two readings is "wrong" is not knowable
		// from the pair, only that they cannot both belong to one odometer.
		const odoConsistent = (a, b) =>
			Math.abs(a.odo - b.odo) <= odoPlausibleGap(a.day, b.day);

		const readingsByTruck = {};
		for (const e of fuelExpenses) {
			const unit = String(e.truck_unit || "").trim().toLowerCase();
			const day = odoDay(e.date);
			// A reading with no usable date cannot be placed on the truck's timeline,
			// so it cannot be checked and does not contribute a span.
			if (!unit || day === null || !(e.odometer > ODOMETER_SANITY_FLOOR)) continue;
			(readingsByTruck[unit] = readingsByTruck[unit] || []).push({
				odo: Number(e.odometer), day, spend: e.amount || 0,
				telemetry: odometerSourceFor(e) === "telemetry",
			});
		}

		let cpmMiles = 0, cpmSpend = 0, cpmTrucks = 0;
		let odoReadingsRejected = 0, cpmTrucksExcluded = 0;
		for (const unit of Object.keys(readingsByTruck)) {
			const rows = readingsByTruck[unit];
			// ELD-stamped readings anchor the timeline: they come off the vehicle bus,
			// and odometer_source is a STORED column the backfill writes once and
			// never clears, so the anchor survives a fuel_events wipe that the old
			// link-based test did not.
			const anchors = rows.filter((r) => r.telemetry);
			let kept;
			if (anchors.length) {
				kept = rows.filter((r) => r.telemetry || anchors.every((a) => odoConsistent(r, a)));
			} else {
				// No ELD reading to anchor on, so fall back to consensus among the
				// typed ones: keep the readings that agree with the most others. Two
				// readings that disagree both score 0, both survive, and the span
				// backstop below then throws the truck out — which is the honest
				// answer, because nothing in the data says which one is wrong.
				const scored = rows.map((r) => ({ r, agree: rows.filter((o) => o !== r && odoConsistent(r, o)).length }));
				const best = Math.max(...scored.map((s) => s.agree));
				kept = scored.filter((s) => s.agree === best).map((s) => s.r);
			}
			odoReadingsRejected += rows.length - kept.length;
			if (kept.length < 2) continue;

			let lo = Infinity, hi = -Infinity, loDay = 0, hiDay = 0, spend = 0;
			for (const r of kept) {
				if (r.odo < lo) { lo = r.odo; loDay = r.day; }
				if (r.odo > hi) { hi = r.odo; hiDay = r.day; }
				spend += r.spend;
			}
			if (!(hi > lo)) continue;
			// BACKSTOP. Whatever survived above still has to describe a span a truck
			// could actually have driven — including an all-telemetry set, because an
			// ELD odometer can glitch too and "trusted source" is not the same as
			// "checked". A truck that fails here contributes NOTHING rather than a
			// plausible-looking wrong number; the exclusion is visible in
			// costPerMileBasis instead of being buried in the average.
			if (hi - lo > odoPlausibleGap(hiDay, loDay)) { cpmTrucksExcluded++; continue; }
			cpmMiles += hi - lo;
			cpmSpend += spend;
			cpmTrucks++;
		}
		const costPerMile = cpmMiles > 0 ? cpmSpend / cpmMiles : 0;

		// Monthly breakdown
		const monthly = {};
		fuelExpenses.forEach((e) => {
			const month = (e.date || "").substring(0, 7);
			if (!month) return;
			if (!monthly[month]) monthly[month] = { spend: 0, gallons: 0, count: 0 };
			monthly[month].spend += e.amount || 0;
			monthly[month].gallons += e.gallons || 0;
			monthly[month].count++;
		});
		const monthlyData = Object.entries(monthly)
			.sort(([a], [b]) => a.localeCompare(b))
			.map(([month, d]) => ({
				month,
				spend: Math.round(d.spend),
				gallons: Math.round(d.gallons * 10) / 10,
				avgPerGallon: d.gallons > 0 ? Math.round((d.spend / d.gallons) * 100) / 100 : 0,
			}));

		// Per-driver breakdown
		const byDriver = {};
		fuelExpenses.forEach((e) => {
			if (!byDriver[e.driver]) byDriver[e.driver] = { spend: 0, gallons: 0 };
			byDriver[e.driver].spend += e.amount || 0;
			byDriver[e.driver].gallons += e.gallons || 0;
		});

		// National avg diesel ~$3.80/gal as baseline
		const nationalAvg = 3.80;
		const actualAvg = avgCostPerGallon || nationalAvg;
		const savingsVsNational = nationalAvg > 0
			? Math.round(((nationalAvg - actualAvg) / nationalAvg) * 10000) / 100
			: 0;

		const reconciliation = fuelReconciliationSnapshot();

		res.json({
			totalFuelSpend: Math.round(totalFuelSpend),
			totalGallons: Math.round(totalGallons * 10) / 10,
			avgCostPerGallon: Math.round(avgCostPerGallon * 100) / 100,
			costPerMile: Math.round(costPerMile * 100) / 100,
			// What the cost/mile is actually built from, so a reader can tell a real
			// figure from one resting on two receipts. The two rejection counts are
			// on the wire for the same reason the withheld-odometer count is: a guard
			// that silently shrinks the basis is indistinguishable from thin data.
			costPerMileBasis: {
				trucks: cpmTrucks, miles: Math.round(cpmMiles), spend: Math.round(cpmSpend),
				readingsRejected: odoReadingsRejected, trucksExcluded: cpmTrucksExcluded,
			},
			savingsTarget,
			savingsVsNational,
			onTarget: savingsVsNational >= savingsTarget,
			monthlyData,
			byDriver,
			recentFills: fuelExpenses.slice(0, 20).map((e) => ({
				id: e.id, driver: e.driver, amount: e.amount,
				gallons: e.gallons,
				odometer: e.odometer > 0 ? e.odometer : null,
				// Always present, explicitly null when unknown — see above.
				odometerSource: odometerSourceFor(e),
				gallonsSource: gallonsSourceFor(e),
				truckUnit: e.truck_unit || "",
				date: e.date, loadId: e.load_id,
			})),
			// Reconciliation lists are OMITTED entirely (not []) when the fuel-event
			// sweep has never populated its table: the client reads an absent key as
			// "this server doesn't do that yet" and [] as "checked, all clear", and
			// those must not be confused. Once the sweep has run they are always
			// arrays, empty or not.
			...(reconciliation ? {
				unmatchedFills: reconciliation.unmatchedFills,
				unmatchedReceipts: reconciliation.unmatchedReceipts,
				// Same absent-vs-[] contract as the two queues above: omitted with the
				// rest when the sweep has never run, an array (empty or not) once it has.
				odometerConflicts: reconciliation.odometerConflicts,
				// Third queue: receipts with a price and no gallons. Distinct from
				// unmatchedReceipts by construction — the matcher's `eligible` filter
				// requires gallons >= FUEL_MATCH_MIN_GALLONS, so a row can never appear
				// in both. Two defects, two fixes, two lists.
				volumelessReceipts: reconciliation.volumelessReceipts,
				// Summary is computed over the FULL set while the list above is capped,
				// so trust `count` here rather than volumelessReceipts.length.
				volumelessSummary: reconciliation.volumelessSummary,
				tankCalibration: fuelTankCalibrationWire(),
			} : {}),
			// FOURTH queue — the same purchase booked twice. Deliberately OUTSIDE the
			// `reconciliation ?` spread above: that block is omitted wholesale until
			// the fuel-event sweep has populated its table, and this queue never reads
			// fuel_events. Riding inside it would hide $1,115.35 of already
			// double-booked money on every deployment where the sweep is off — which
			// is the state of the snapshot this was measured against.
			...(() => {
				const d = duplicateReceiptGroups();
				return { duplicateReceipts: d.groups, duplicateSummary: d.summary };
			})(),
		});
	} catch (error) {
		console.error("Error fetching fuel analytics:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// GET /api/expenses/analytics — Expense Intelligence aggregates (all types,
// not just fuel). The heavy lifting (grouping, totals, trends) lives in
// lib/expense-analytics; this route validates/normalizes every filter so the
// lib can trust its inputs. Filters: from/to (YYYY-MM-DD), types (CSV,
// intersected with the canonical EXPENSE_TYPES), states (CSV of 2-letter
// codes), region (Census division → unioned into states), driver, truck,
// q, vendor (free text, <=80).
app.get("/api/expenses/analytics", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		const { from, to, types, states, region, driver, truck, q, vendor } = req.query;
		const dateRe = /^\d{4}-\d{2}-\d{2}$/;
		if ((from && !dateRe.test(String(from))) || (to && !dateRe.test(String(to)))) {
			return res.status(400).json({ error: "Invalid date format (YYYY-MM-DD)" });
		}
		if (from && to && String(to) < String(from)) {
			return res.status(400).json({ error: "'to' must be on or after 'from'" });
		}
		// types: CSV intersected with the canonical list (case-insensitive,
		// unknown values silently dropped, canonical casing kept for the lib).
		let typeList = [];
		if (types) {
			const wanted = String(types).split(",").map((t) => t.trim().toLowerCase()).filter(Boolean);
			typeList = EXPENSE_TYPES.filter((t) => wanted.includes(t.toLowerCase()));
		}
		// states: CSV of 2-letter codes; invalid entries silently dropped.
		let stateList = [];
		if (states) {
			stateList = String(states).split(",").map((s) => s.trim().toUpperCase()).filter((s) => /^[A-Z]{2}$/.test(s));
		}
		if (region) {
			const regionStates = resolveRegionToStates(String(region));
			if (!regionStates) return res.status(400).json({ error: "Unknown region" });
			stateList = [...new Set([...stateList, ...regionStates.map((s) => String(s).toUpperCase())])];
		}
		const clip = (v) => (v == null ? "" : String(v).trim().slice(0, 80));
		const filters = {
			from: from ? String(from) : undefined,
			to: to ? String(to) : undefined,
			types: typeList.length ? typeList : undefined,
			states: stateList.length ? stateList : undefined,
			driver: clip(driver) || undefined,
			truck: clip(truck) || undefined,
			q: clip(q) || undefined,
			vendor: clip(vendor) || undefined,
		};
		res.json(aggregateExpenses(db, filters));
	} catch (err) {
		console.error("Error computing expense analytics:", err.message);
		res.status(500).json({ error: "Failed to compute analytics" });
	}
});

// Shared limiter for BOTH Expense-AI routes below — caps Gemini spend the same
// way expenseOcrLimiter caps vision OCR.
const expenseAiLimiter = rateLimit({
	windowMs: 15 * 60 * 1000,
	max: 20,
	message: { error: "Too many AI requests. Try again in a few minutes." },
	standardHeaders: true,
});

// POST /api/expenses/ai/query — natural-language question over the company's
// expense data. lib/expense-ai turns the question into a bounded query spec
// (never raw SQL from the model); lib/expense-analytics executes the spec with
// parameterized queries; the model then narrates the result table. If the
// narration call fails we still return the table with a deterministic answer.
app.post("/api/expenses/ai/query", requireRole("Super Admin", "Dispatcher"), expenseAiLimiter, async (req, res) => {
	try {
		const question = ((req.body || {}).question ?? "").toString().trim();
		if (question.length < 3 || question.length > 300) {
			return res.status(400).json({ error: "Question must be 3-300 characters" });
		}
		logAudit(req, "expense_ai_query", "expense", 0, question.slice(0, 200));
		let spec;
		try {
			spec = await expenseAi.querySpecFromQuestion(question);
		} catch (err) {
			if (err && err.code === "AI_NO_KEY") return res.status(503).json({ error: "AI is not configured" });
			if (err && err.code === "AI_BAD_INPUT") return res.status(400).json({ error: "Invalid question" });
			// A rejected key or an exhausted quota is a SERVICE problem, not a bad
			// request — it is the same state as having no key at all, which already
			// answers 503 and makes the panel hide itself. 502 left the card stuck on
			// a generic failure with a retry that could never succeed. Same branch and
			// the same reasoning as POST /api/expenses/ocr. `kind` is set by
			// lib/gemini-errors.js; a request WE malformed stays a loud 502 below.
			if (err && err.kind === "unavailable") {
				console.error(`Expense AI query unavailable (Gemini ${err.status}${err.reason ? " " + err.reason : ""}):`, err.message);
				return res.status(503).json({ error: "AI is temporarily unavailable" });
			}
			console.error("Expense AI query-spec failed:", err && err.message);
			return res.status(502).json({ error: "AI request failed" });
		}
		if (!spec || !spec.supported) {
			return res.json({
				answer: "I can only answer questions about this company's expense data (vendors, fuel, repairs, states, drivers, trucks, dates).",
				unsupported: true,
				spec: null,
				columns: [],
				rows: [],
				chartHint: "none",
			});
		}
		const table = runQuerySpec(db, spec);
		let answer;
		try {
			answer = await expenseAi.answerFromResults(question, spec, table);
		} catch {
			// Deterministic fallback — the result table is still useful without
			// AI prose. Label = first column, metric = first numeric column.
			const cols = table.columns || [];
			const rows = table.rows || [];
			if (rows.length) {
				const cell = (row, i) => (Array.isArray(row) ? row[i] : row ? row[(cols[i] || {}).key] : undefined);
				// Narrate the REQUESTED metric's column when present (a gallons
				// question should not fall back to narrating Count).
				const metricKeys = {
					spend: ["spend", "totalSpend"], count: ["visits", "count"],
					gallons: ["gallons", "totalGallons"], avg_per_gallon: ["avgPerGallon"], avg_amount: ["avgAmount"],
				}[spec.metric] || [];
				let metricIdx = cols.findIndex((c) => c && metricKeys.includes(c.key));
				if (metricIdx < 0) {
					metricIdx = cols.length > 1 ? 1 : 0;
					for (let i = 1; i < cols.length; i++) {
						if (typeof cell(rows[0], i) === "number") { metricIdx = i; break; }
					}
				}
				answer = `Top result: ${cell(rows[0], 0)} — ${(cols[metricIdx] || {}).label || "value"}: ${cell(rows[0], metricIdx)}.`;
			} else {
				answer = "No matching expense data was found for that question.";
			}
		}
		res.json({ answer, unsupported: false, spec, columns: table.columns, rows: table.rows, chartHint: table.chartHint });
	} catch (err) {
		console.error("Expense AI query error:", err.message);
		res.status(500).json({ error: "Failed to answer question" });
	}
});

// GET /api/expenses/ai/insights — AI-generated spending insights, cached for
// up to 6h. The cache key folds in MAX(id) + COUNT(*) + the current business
// day (America/Chicago — same zone the invoice weeks use), so any expense
// insert/delete or a day rollover regenerates without needing a timer.
let expenseInsightsCache = { key: "", at: 0, data: null };
// Key folds in MAX(id) + COUNT + Pending/Rejected counts + the business day
// (America/Chicago), so any insert/delete, approve/reject, or day rollover
// regenerates without a timer.
function computeInsightsCacheKey() {
	const stat = db.prepare(
		"SELECT COALESCE(MAX(id),0) AS m, COUNT(*) AS c, COALESCE(SUM(status = 'Pending'), 0) AS p, COALESCE(SUM(status = 'Rejected'), 0) AS r FROM expenses"
	).get();
	return `${stat.m}:${stat.c}:${stat.p}:${stat.r}:${localDayInTz(Date.now(), "America/Chicago")}`;
}
// Serve a fresh cache hit BEFORE the rate limiter, so a tab-open that hits the
// 6h cache costs neither a Gemini call nor an expenseAiLimiter token (cached
// hits would otherwise burn the budget shared with real AI questions).
function insightsCacheGate(req, res, next) {
	try {
		const key = computeInsightsCacheKey();
		req._insightsKey = key;
		if (expenseInsightsCache.key === key && expenseInsightsCache.data && Date.now() - expenseInsightsCache.at < 6 * 3600e3) {
			return res.json({ ...expenseInsightsCache.data, cached: true });
		}
	} catch { /* fall through — the handler recomputes the key defensively */ }
	next();
}
app.get("/api/expenses/ai/insights", requireRole("Super Admin", "Dispatcher"), insightsCacheGate, expenseAiLimiter, async (req, res) => {
	try {
		const key = req._insightsKey || computeInsightsCacheKey();
		const aggregates = buildInsightsAggregates(db);
		let insights;
		try {
			insights = await expenseAi.generateInsights(aggregates);
		} catch (err) {
			if (err && err.code === "AI_NO_KEY") return res.status(503).json({ error: "AI is not configured" });
			// A rejected key or an exhausted quota is a SERVICE problem, not a bad
			// request — it is the same state as having no key at all, which already
			// answers 503 and makes the panel hide itself. 502 left the card stuck on
			// a generic failure with a retry that could never succeed. Same branch and
			// the same reasoning as POST /api/expenses/ocr. `kind` is set by
			// lib/gemini-errors.js; a request WE malformed stays a loud 502 below.
			if (err && err.kind === "unavailable") {
				console.error(`Expense AI insights unavailable (Gemini ${err.status}${err.reason ? " " + err.reason : ""}):`, err.message);
				return res.status(503).json({ error: "AI is temporarily unavailable" });
			}
			console.error("Expense AI insights failed:", err && err.message);
			return res.status(502).json({ error: "AI request failed" });
		}
		const data = { insights, generatedAt: new Date().toISOString(), cached: false };
		expenseInsightsCache = { key, at: Date.now(), data };
		logAudit(req, "expense_ai_insights", "expense", 0, `generated ${insights.length} insights`);
		res.json(data);
	} catch (err) {
		console.error("Expense AI insights error:", err.message);
		res.status(500).json({ error: "Failed to generate insights" });
	}
});

// GET /api/maintenance-fund — Fund balance, contributions, and service history
app.get("/api/maintenance-fund", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		const config = {};
		db.prepare("SELECT key, value FROM investor_config").all()
			.forEach((r) => (config[r.key] = r.value));
		const monthlyTarget = parseFloat(config.maintenance_fund_monthly) || 800;

		const entries = db.prepare(
			`SELECT * FROM maintenance_fund ORDER BY date DESC`
		).all();

		const contributions = entries.filter((e) => e.type === "contribution");
		const services = entries.filter((e) => e.type === "service");

		const totalContributed = contributions.reduce((s, e) => s + e.amount, 0);
		const totalSpent = services.reduce((s, e) => s + e.amount, 0);
		const balance = totalContributed - totalSpent;

		// Monthly contribution tracking
		const monthlyContribs = {};
		contributions.forEach((e) => {
			const month = (e.date || "").substring(0, 7);
			if (!month) return;
			monthlyContribs[month] = (monthlyContribs[month] || 0) + e.amount;
		});

		// How many months have met target
		const monthsMet = Object.values(monthlyContribs).filter((v) => v >= monthlyTarget).length;
		const totalMonths = Object.keys(monthlyContribs).length || 1;

		res.json({
			monthlyTarget,
			balance: Math.round(balance),
			totalContributed: Math.round(totalContributed),
			totalSpent: Math.round(totalSpent),
			complianceRate: Math.round((monthsMet / totalMonths) * 100),
			entries: entries.map((e) => ({
				id: e.id, type: e.type, amount: e.amount,
				description: e.description, truck: e.truck,
				date: e.date,
			})),
		});
	} catch (error) {
		console.error("Error fetching maintenance fund:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// POST /api/maintenance-fund — Add contribution or service entry
app.post("/api/maintenance-fund", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		const { type, amount, description, truck, date } = req.body;
		if (!type || !amount || !date) {
			return res.status(400).json({ error: "type, amount, and date required" });
		}
		if (!["contribution", "service"].includes(type)) {
			return res.status(400).json({ error: "type must be 'contribution' or 'service'" });
		}
		// The CREATE verb needed the same lock as the edit verbs, and this one is
		// reachable from the live UI rather than from curl: ExpensesTab's maintenance
		// form is a free `type` select beside a free `<input type="date">`, so a
		// Dispatcher picking "service" and back-dating the date books money straight
		// into a closed month. Only `service` rows reach the P&L (every query filters
		// `type = 'service'`), so a contribution — a reserve movement — is left alone.
		if (!/^\d{4}-\d{2}-\d{2}$/.test(String(date).trim())) {
			return res.status(400).json({ error: "date must be YYYY-MM-DD" });
		}
		if (type === "service") {
			// ⚠️ A CREATE VERB, so there is no row id to name and no prior value to
			// compare against — the attempted row IS the record, and without it the
			// refusal cannot be reconstructed at all. entity is `maintenance_fund`,
			// the table the write targets, and entity_id carries the truck because a
			// service payment is only ever read per-truck. (Its success twin,
			// `create_maintenance_fund_entry`, is written below and CAN name the id.)
			const maintAudit = {
				action: "maintenance_fund_blocked", entity: "maintenance_fund",
				entityId: String(truck || "").trim() || "(no truck)",
				subject: `log $${parseFloat(amount)} service payment dated ${String(date).trim()}` +
					` on ${String(truck || "").trim() || "no truck"}`,
				note: auditText(description, 500),
			};
			if (!periodLocksReadable()) return periodLockUnreadableResponse(req, res, "Logging a maintenance service payment", maintAudit);
			const period = String(date).trim().slice(0, 7);
			if (isLocked(period)) {
				return periodBlockedResponse(req, res, "Cannot log this maintenance service payment",
					[{
						table: "maintenance_fund", rows: 1, periods: [period],
						detail: `a $${parseFloat(amount)} service payment dated ${String(date).trim()} would be deducted from ${periodLabel(period)}, which is finalized`,
					}],
					"Date it inside the current open month, or reopen the affected period first — POST /api/periods/:period/reopen records a reason.",
					maintAudit);
			}
		}

		const result = db.prepare(
			`INSERT INTO maintenance_fund (type, amount, description, truck, date) VALUES (?, ?, ?, ?, ?)`
		).run(type, parseFloat(amount), description || "", truck || "", date);

		// ⚠️ BOTH TYPES ARE AUDITED, not just the guarded one. Only `service` reaches
		// the P&L (every query filters `type = 'service'`), which is why only
		// `service` is period-guarded — but a `contribution` still moves money into
		// the maintenance reserve, and a row that no query sums is exactly the row
		// nobody would notice was wrong. `date` is recorded because it, not the
		// insert time, is the month a service payment is deducted from. Dispatchers
		// can reach this route, so `super_admin` is not the only account here.
		// (`create_maintenance_fund_entry`, paired with the refusal action
		// `maintenance_fund_blocked` that was named before this line existed.)
		logAudit(req, "create_maintenance_fund_entry", "maintenance_fund", String(result.lastInsertRowid),
			`${type === "service" ? "Service payment" : "Contribution"} $${parseFloat(amount)} dated ${String(date).trim()}` +
			` on ${String(truck || "").trim() || "no truck"}` +
			`${type === "service" ? " (deducted from that month's P&L)" : " (reserve movement, not a P&L deduction)"}` +
			`${description ? ` — ${auditText(description, 300)}` : ""}`);

		res.json({ success: true, id: result.lastInsertRowid });
	} catch (error) {
		console.error("Error adding maintenance fund entry:", error.message);
		res.status(500).json({ error: error.message });
	}
});

