// POST /api/compliance/fees — Add a compliance fee
app.post("/api/compliance/fees", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		const { type, amount, description, truck, dueDate, paidDate, status } = req.body;
		if (!type || !amount || !dueDate) {
			return res.status(400).json({ error: "type, amount, and dueDate required" });
		}
		// Guarding the PUT and leaving the POST open would have been decorative:
		// `status` and `paidDate` came straight off the body with no validation and
		// no lock check, so a single POST with {"status":"Paid","paidDate":"<a day in
		// a closed month>"} books the whole deduction into a finalized month — the
		// exact write the PUT now refuses, by the create door. Same validation the
		// PUT gained, too: an unparseable date makes strftime() return NULL and the
		// fee then counts in no month at all.
		const feeStatus = status === "Paid" ? "Paid" : "Pending";
		const due = String(dueDate).trim();
		const paid = String(paidDate || "").trim();
		if (!/^\d{4}-\d{2}-\d{2}$/.test(due)) {
			return res.status(400).json({ error: "dueDate must be YYYY-MM-DD" });
		}
		if (paid && !/^\d{4}-\d{2}-\d{2}$/.test(paid)) {
			return res.status(400).json({ error: "paidDate must be YYYY-MM-DD or empty" });
		}
		// Only a Paid row is summed, so a Pending fee books nothing wherever it is
		// dated and is left alone — the same asymmetry the PUT relies on.
		if (feeStatus === "Paid") {
			// Another create verb with no id yet: the attempted row is the whole
			// record. Both dates are carried because compliancePostedPeriod() heads
			// its COALESCE with paid_date and falls back to due_date, so which month
			// this would have hit is only reconstructible from the pair. (Its success
			// twin, `create_compliance_fee`, is written below.)
			const feeAudit = {
				action: "create_compliance_fee_blocked", entity: "compliance_fee",
				entityId: String(truck || "").trim() || "(no truck)",
				subject: `record $${parseFloat(amount)} ${String(type || "fee").trim()} as Paid` +
					` on ${String(truck || "").trim() || "no truck"} (paid ${paid || "unset"}, due ${due})`,
				note: auditText(description, 500),
			};
			if (!periodLocksReadable()) return periodLockUnreadableResponse(req, res, "Recording a paid compliance fee", feeAudit);
			const period = compliancePostedPeriod({ paid_date: paid, due_date: due, created_at: "" });
			if (!period || isLocked(period)) {
				return periodBlockedResponse(req, res, "Cannot record this compliance fee as paid",
					[{
						table: "compliance_fees", rows: 1, periods: [period || ""],
						detail: period
							? `$${parseFloat(amount)} would be deducted from ${periodLabel(period)}, which is finalized`
							: "the dates on this fee do not resolve to a month, so the month it would be deducted from cannot be confirmed open",
					}],
					"Use a paid date inside the current open month, record it as Pending for now, or reopen the affected period first — POST /api/periods/:period/reopen records a reason.",
					feeAudit);
			}
		}

		const result = db.prepare(
			`INSERT INTO compliance_fees (type, amount, description, truck, due_date, paid_date, status)
			 VALUES (?, ?, ?, ?, ?, ?, ?)`
		).run(type, parseFloat(amount), description || "", truck || "",
			due, paid, feeStatus);

		// The create verb's success line, and the twin of `update_compliance_fee` on
		// the PUT — which has recorded which month a fee lands in since that route
		// was guarded, while a fee created ALREADY PAID (one POST, `status:"Paid"`
		// plus a paid date) made the identical deduction with no trace at all. Both
		// dates and the status are recorded for the reason the refusal states: paid_date
		// heads compliancePostedPeriod()'s COALESCE and falls back to due_date, so the
		// month deducted is only reconstructible from the pair.
		logAudit(req, "create_compliance_fee", "compliance_fee", String(result.lastInsertRowid),
			`${String(type || "Fee").trim()}${String(truck || "").trim() ? ` on ${String(truck).trim()}` : ""} ` +
			`$${parseFloat(amount)} created ${feeStatus}` +
			` (due ${due}, paid ${paid || "unset"})` +
			`${feeStatus === "Paid" ? ` — deducted from ${periodLabel(compliancePostedPeriod({ paid_date: paid, due_date: due, created_at: "" }))}` : " — not yet deducted"}` +
			`${description ? ` — ${auditText(description, 300)}` : ""}`);

		res.json({ success: true, id: result.lastInsertRowid });
	} catch (error) {
		console.error("Error adding compliance fee:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// JS mirror of the month bucket every compliance query uses:
//   strftime('%Y-%m', COALESCE(NULLIF(paid_date,''), NULLIF(due_date,''), strftime('%Y-%m-%d', created_at)))
// Kept adjacent to that SQL on purpose — if one changes, the other has to, and a
// guard that resolved the month its own way would answer for a different month
// than the SUM it protects. Returns "" when the row's date will not resolve,
// which SQLite reports as a NULL month (the row then counts in NO month at all).
function compliancePostedPeriod(fee) {
	const pick = String(fee.paid_date || "").trim() || String(fee.due_date || "").trim() || String(fee.created_at || "");
	const p = pick.slice(0, 7);
	return /^\d{4}-\d{2}$/.test(p) ? p : "";
}

// PUT /api/compliance/fees/:id — Mark fee as paid
//
// This route writes BOTH halves of a compliance deduction: `status = 'Paid'` is
// what makes the fee count at all (every query filters on it), and `paid_date`
// is the head of the COALESCE that decides WHICH MONTH it counts in. So marking
// a fee paid with a date inside a finalized month silently deducts its amount
// from that month's investor earnings, and re-paying an already-Paid fee moves
// the amount from one closed month to another.
//
// The everyday case is deliberately still allowed: a fee whose due_date sits in
// a closed month, paid today, books to the CURRENT month (paid_date wins the
// COALESCE) and touches nothing finalized. "You paid it this month, it books
// this month" is both the correct accounting and the common one, and refusing it
// would make the guard useless overhead. Only a paid_date that lands in — or
// moves out of — a closed month is refused.
app.put("/api/compliance/fees/:id", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		const id = parseInt(req.params.id);
		const fee = db.prepare("SELECT * FROM compliance_fees WHERE id = ?").get(id);
		// Previously this returned {success:true} for any id, having changed
		// nothing — an admin marking the wrong row paid got the same answer as one
		// who marked the right one.
		if (!fee) return res.status(404).json({ error: "Compliance fee not found" });

		// Houston day: paid_date is the month bucket for the investor compliance
		// deduction. Validate it, because an unparseable value is not merely
		// untidy — strftime() answers NULL on it, so the fee drops out of EVERY
		// month's total and silently stops being deducted at all.
		const paidDate = String(req.body.paidDate || "").trim() || houstonDay();
		if (!/^\d{4}-\d{2}-\d{2}$/.test(paidDate)) {
			return res.status(400).json({ error: "paidDate must be YYYY-MM-DD" });
		}

		// Fail CLOSED on an unreadable period_locks, matching every other write
		// guard: isLocked() answers "not locked" on any error, so a broken table
		// would turn this off silently.
		// Mirrors the `update_compliance_fee` success line's entity/entity_id. The
		// attempted paid date is the payload: paid_date heads compliancePostedPeriod's
		// COALESCE, so it alone decides which month the deduction lands in — which is
		// the entire subject of this guard.
		const feePayAudit = {
			action: "pay_compliance_fee_blocked", entity: "compliance_fee", entityId: String(id),
			subject: `mark ${fee.type || "fee"}${fee.truck ? ` on ${fee.truck}` : ""} paid` +
				` ($${fee.amount}, paid_date ${fee.paid_date || "unset"} -> ${paidDate}, status ${fee.status || "unknown"} -> Paid)`,
		};
		if (!periodLocksReadable()) return periodLockUnreadableResponse(req, res, "Marking a compliance fee paid", feePayAudit);

		// Does this fee reach a month's total at all? The investor branch INNER
		// JOINs `t.status = 'Active'`; the fleet branch is `LOWER(truck) NOT IN
		// (inactive unit numbers)`, which INCLUDES orphan rows whose `truck` string
		// matches no truck. So the only rows that count in neither are those keyed
		// to a truck that exists and is not Active — for those, no month moves.
		const parked = String(fee.truck || "").trim()
			? db.prepare("SELECT 1 FROM trucks WHERE LOWER(unit_number) = LOWER(?) AND status != 'Active'").get(String(fee.truck).trim())
			: null;
		if (!parked) {
			// Where it books today (only if it is already counted, i.e. Paid) and
			// where it would book after this write. paid_date heads the COALESCE, so
			// the destination month is always the month of `paidDate`.
			const before = fee.status === "Paid" ? compliancePostedPeriod(fee) : null;
			const after = compliancePostedPeriod({ ...fee, paid_date: paidDate });
			const blocked = [];
			// "" = the stored date will not resolve to a month. Refuse rather than
			// guess, for the same reason expenseRowPeriodLocked() fails closed on a
			// malformed date: one unreadable row is cheap to fix, and a guard that
			// waves through what it cannot read is not a guard.
			if (before === "") blocked.push({ when: "current", period: "" });
			else if (before && isLocked(before)) blocked.push({ when: "current", period: before });
			if (after && isLocked(after) && after !== before) blocked.push({ when: "new", period: after });
			if (blocked.length) {
				return periodBlockedResponse(req, res,
					`Cannot mark ${fee.type || "this fee"}${fee.truck ? ` on ${fee.truck}` : ""} paid`,
					[{
						table: "compliance_fees", rows: 1, feeId: id, amount: fee.amount,
						periods: blocked.map((b) => b.period),
						detail: blocked.map((b) => b.when === "current"
							? (b.period ? `$${fee.amount} is currently deducted from ${periodLabel(b.period)}, which is finalized` : `this fee carries a date the server cannot resolve to a month, so it is currently deducted from none`)
							: `paying it on ${paidDate} would deduct $${fee.amount} from ${periodLabel(b.period)}, which is finalized`).join("; "),
					}],
					`Use a paid date inside the current open month, or reopen the affected period first — POST /api/periods/:period/reopen records a reason.`,
					feePayAudit);
			}
		}

		db.prepare(
			`UPDATE compliance_fees SET status = 'Paid', paid_date = ? WHERE id = ?`
		).run(paidDate, id);
		// A compliance fee is a deduction from an investor's month. Which month it
		// lands in was previously decided, and changed, with no trail.
		logAudit(req, "update_compliance_fee", "compliance_fee", String(id),
			`${fee.type || "Fee"}${fee.truck ? ` on ${fee.truck}` : ""} $${fee.amount}: ${fee.status} → Paid, paid date ${String(fee.paid_date || "").trim() || "(unset)"} → ${paidDate}`);

		res.json({ success: true });
	} catch (error) {
		console.error("Error updating compliance fee:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// GET /api/compliance/ifta — Per-truck miles-by-state from Routemate ELD telemetry.
// Each truck gets its own state breakdown; drivers attributed via truck_assignments
// active at each point's timestamp.
app.get("/api/compliance/ifta", requireRole("Super Admin", "Dispatcher"), (req, res) => {
	try {
		const { start, end } = req.query;
		const startDate = start || new Date(new Date().getFullYear(), new Date().getMonth() - 2, 1).toISOString();
		const endDate = end || new Date().toISOString();
		const startMs = new Date(startDate).getTime();
		const endMs = new Date(endDate).getTime();

		const GAP_MS = 30 * 60 * 1000;
		const MAX_HOP_MILES = 50;
		const M_TO_MI = 0.000621371;

		const eldRows = db.prepare(
			`SELECT rt.latitude, rt.longitude, rt.location_date_ms,
			        t.id AS truck_id, t.unit_number
			 FROM routemate_telemetry rt
			 JOIN trucks t ON t.routemate_vehicle_id = rt.routemate_vehicle_id
			 WHERE rt.location_date_ms >= ? AND rt.location_date_ms <= ?
			   AND t.routemate_vehicle_id != ''
			   AND rt.dropped_reason = ''
			 ORDER BY t.id, rt.location_date_ms ASC`
		).all(startMs, endMs);

		let driverAt = () => null;
		if (eldRows.length > 0) {
			const truckIds = [...new Set(eldRows.map((r) => r.truck_id))];
			const placeholders = truckIds.map(() => "?").join(",");
			const assignmentRows = db.prepare(
				`SELECT truck_id, driver_name, start_date, end_date
				 FROM truck_assignments
				 WHERE truck_id IN (${placeholders})
				 ORDER BY truck_id, start_date ASC`
			).all(...truckIds);
			const assignmentsByTruck = {};
			for (const a of assignmentRows) {
				if (!assignmentsByTruck[a.truck_id]) assignmentsByTruck[a.truck_id] = [];
				assignmentsByTruck[a.truck_id].push(a);
			}
			driverAt = (truckId, isoTs) => {
				const list = assignmentsByTruck[truckId] || [];
				for (const a of list) {
					const startOk = a.start_date && a.start_date <= isoTs;
					const endOk = !a.end_date || a.end_date === "" || a.end_date >= isoTs;
					if (startOk && endOk) return a.driver_name;
				}
				return null;
			};
		}

		// Group telemetry points per truck (rows already time-ordered by SQL ORDER BY)
		const byTruck = {};
		for (const r of eldRows) {
			if (!byTruck[r.truck_id]) {
				byTruck[r.truck_id] = { unitNumber: r.unit_number || "", points: [], drivers: new Set() };
			}
			byTruck[r.truck_id].points.push(r);
		}

		const trucks = [];
		let totalMiles = 0;
		const allDrivers = new Set();

		for (const [truckIdStr, entry] of Object.entries(byTruck)) {
			const truckId = parseInt(truckIdStr, 10);
			const pts = entry.points;

			// Attribute every point to a driver (for the truck's drivers list)
			for (const r of pts) {
				const d = driverAt(truckId, new Date(r.location_date_ms).toISOString());
				if (d) {
					entry.drivers.add(d);
					allDrivers.add(d);
				}
			}

			const stateMileage = {};
			let truckTotal = 0;
			for (let i = 1; i < pts.length; i++) {
				const prev = pts[i - 1];
				const curr = pts[i];
				if (curr.location_date_ms - prev.location_date_ms > GAP_MS) continue;
				const distMeters = geolib.getDistance(
					{ latitude: prev.latitude, longitude: prev.longitude },
					{ latitude: curr.latitude, longitude: curr.longitude }
				);
				const miles = distMeters * M_TO_MI;
				if (miles > MAX_HOP_MILES) continue;
				const midLat = (prev.latitude + curr.latitude) / 2;
				const midLng = (prev.longitude + curr.longitude) / 2;
				const state = getStateFromCoords(midLat, midLng);
				stateMileage[state] = (stateMileage[state] || 0) + miles;
				truckTotal += miles;
			}

			const states = Object.entries(stateMileage)
				.map(([state, miles]) => ({
					state,
					miles: Math.round(miles),
					pct: truckTotal > 0 ? Math.round((miles / truckTotal) * 100) : 0,
				}))
				.sort((a, b) => b.miles - a.miles || a.state.localeCompare(b.state));

			trucks.push({
				truckId,
				unitNumber: entry.unitNumber,
				totalMiles: Math.round(truckTotal),
				drivers: [...entry.drivers],
				states,
			});
			totalMiles += truckTotal;
		}

		trucks.sort((a, b) => b.totalMiles - a.totalMiles);

		res.json({
			totalMiles: Math.round(totalMiles),
			truckCount: trucks.length,
			driverCount: allDrivers.size,
			startDate,
			endDate,
			trucks,
		});
	} catch (error) {
		console.error("Error calculating IFTA mileage:", error.message);
		res.status(500).json({ error: error.message });
	}
});

// GET /api/compliance/ifta/state-detail — daily mileage breakdown for one truck × one state.
// Mirrors the parent IFTA handler's algorithm so per-day rows reconcile with the parent state total.
// Each day is also matched against the Job Tracking sheet to attribute load IDs.
app.get("/api/compliance/ifta/state-detail", requireRole("Super Admin", "Dispatcher"), async (req, res) => {
	try {
		const truckId = parseInt(req.query.truck_id, 10);
		const state = String(req.query.state || "").trim();
		if (!truckId || !state) {
			return res.status(400).json({ error: "truck_id and state are required" });
		}

		const truck = db.prepare(
			"SELECT id, unit_number, routemate_vehicle_id FROM trucks WHERE id = ?"
		).get(truckId);
		if (!truck || !truck.routemate_vehicle_id) {
			return res.status(404).json({ error: "Truck not found or not linked to Routemate" });
		}

		const startDate = req.query.start || new Date(new Date().getFullYear(), new Date().getMonth() - 2, 1).toISOString();
		const endDate = req.query.end || new Date().toISOString();
		const startMs = new Date(startDate).getTime();
		const endMs = new Date(endDate).getTime();

		const GAP_MS = 30 * 60 * 1000;
		const MAX_HOP_MILES = 50;
		const M_TO_MI = 0.000621371;

		const rows = db.prepare(
			`SELECT latitude, longitude, location_date_ms
			 FROM routemate_telemetry
			 WHERE routemate_vehicle_id = ?
			   AND location_date_ms >= ? AND location_date_ms <= ?
			   AND dropped_reason = ''
			 ORDER BY location_date_ms ASC`
		).all(truck.routemate_vehicle_id, startMs, endMs);

		const days = {};
		let totalMiles = 0;
		for (let i = 1; i < rows.length; i++) {
			const prev = rows[i - 1];
			const curr = rows[i];
			if (curr.location_date_ms - prev.location_date_ms > GAP_MS) continue;
			const distMeters = geolib.getDistance(
				{ latitude: prev.latitude, longitude: prev.longitude },
				{ latitude: curr.latitude, longitude: curr.longitude }
			);
			const miles = distMeters * M_TO_MI;
			if (miles > MAX_HOP_MILES) continue;
			const midLat = (prev.latitude + curr.latitude) / 2;
			const midLng = (prev.longitude + curr.longitude) / 2;
			if (getStateFromCoords(midLat, midLng) !== state) continue;

			const day = new Date(curr.location_date_ms).toISOString().slice(0, 10);
			if (!days[day]) {
				days[day] = { miles: 0, firstPing: curr.location_date_ms, lastPing: curr.location_date_ms };
			}
			days[day].miles += miles;
			if (curr.location_date_ms < days[day].firstPing) days[day].firstPing = curr.location_date_ms;
			if (curr.location_date_ms > days[day].lastPing) days[day].lastPing = curr.location_date_ms;
			totalMiles += miles;
		}

		const daysList = Object.entries(days)
			.map(([date, d]) => ({
				date,
				miles: Math.round(d.miles),
				firstPing: new Date(d.firstPing).toISOString(),
				lastPing: new Date(d.lastPing).toISOString(),
				loadIds: [],
			}))
			.sort((a, b) => a.date.localeCompare(b.date));

		// Match each day to load IDs from the Job Tracking sheet — driver-aware via truck_assignments.
		if (daysList.length > 0) {
			try {
				const truckAssigns = db.prepare(
					"SELECT driver_name, start_date, end_date FROM truck_assignments WHERE truck_id = ?"
				).all(truckId);
				const nowIso = new Date().toISOString();
				const driversOnTruck = new Set();
				for (const a of truckAssigns) {
					const aStart = a.start_date || "";
					const aEnd = (a.end_date && a.end_date !== "") ? a.end_date : nowIso;
					if (aStart && aStart <= endDate && aEnd >= startDate) {
						driversOnTruck.add(String(a.driver_name || "").toLowerCase().trim());
					}
				}

				if (driversOnTruck.size > 0) {
					const jt = await getJobTrackingCached();
					const jtData = excludeDroppedLoads(jt.data, jt.headers);
					const jtDriverCol = findCol(jt.headers, /^driver$/i) || findCol(jt.headers, /driver/i);
					const jtLoadIdCol = findCol(jt.headers, /load.?id|job.?id/i);
					const jtAssignedCol = findCol(jt.headers, /assigned.*date|date.*assigned/i);
					const jtDeliveredCol = findCol(jt.headers, /delivered.*date|date.*delivered|delivery.*date|completion.*date/i);

					// "YYYY-MM-DD" for the string comparisons below. NOT a parser — it
					// formats whatever the SHARED resolver returns, so this route reads
					// the sheet the same way the money math does.
					//
					// It replaces a local US-M/D/Y-only parser that had no ISO branch at
					// all and returned null for everything else. Reading "Assigned Date",
					// that silently dropped every RFC 2822 and every ISO row under a bare
					// `if (!sIso) continue`. Measured read-only on production 2026-08-09:
					// of 267 eligible rows it resolved 96 and DROPPED 171 (64.0%) — 105
					// RFC 2822 (n8n copies the rate-con email's own `Date:` header into
					// this column) and 66 ISO, all perfectly dateable. IFTA per-day load
					// attribution was missing two thirds of its loads.
					//
					// Safe to widen without restating anything: this route WRITES nothing
					// (it res.json()s a mileage breakdown) and feeds no payout — IFTA is
					// deliberately on the operational basis, not the settlement one (see
					// EXPENSE_PERIOD_EXPR's exclusion list). The delivered-date column is
					// unchanged in practice: all 104 non-empty cells are US-slash and
					// resolve identically under both, so the `|| todayIso` fallback keeps
					// firing exactly where it did.
					const sheetToIso = (val) => {
						const d = moneySheetDate(val);
						return d && !isNaN(d) ? jtFmtDate(d) : null;
					};

					if (jtDriverCol && jtLoadIdCol && jtAssignedCol) {
						// Houston day, not the UTC day — after 7 PM Houston the UTC
						// day is already tomorrow, so this compared candidate loads
						// against a date that hadn't happened yet.
						const todayIso = houstonDay();
						const candidates = [];
						for (const row of jtData) {
							const drv = String(row[jtDriverCol] || "").toLowerCase().trim();
							if (!driversOnTruck.has(drv)) continue;
							const lid = String(row[jtLoadIdCol] || "").trim().replace(/^#/, "");
							if (!lid) continue;
							const sIso = sheetToIso(row[jtAssignedCol]);
							if (!sIso) continue;
							const eIso = jtDeliveredCol ? (sheetToIso(row[jtDeliveredCol]) || todayIso) : todayIso;
							candidates.push({ loadId: lid, startIso: sIso, endIso: eIso });
						}
						for (const day of daysList) {
							const ids = new Set();
							for (const c of candidates) {
								if (c.startIso <= day.date && c.endIso >= day.date) ids.add(c.loadId);
							}
							day.loadIds = [...ids];
						}
					}
				}
			} catch (matchErr) {
				console.error("IFTA state-detail: load matching failed:", matchErr.message);
				// Leave loadIds as the initialized empty arrays — don't fail the whole request.
			}
		}

		res.json({
			truckId,
			unitNumber: truck.unit_number || "",
			state,
			totalMiles: Math.round(totalMiles),
			startDate,
			endDate,
			days: daysList,
		});
	} catch (error) {
		console.error("Error calculating IFTA state detail:", error.message);
		res.status(500).json({ error: error.message });
	}
});

